import csv
import math
import os
import subprocess

def search_permits(root: str, species: str, page: int=1, page_size: int=10) -> list[dict]:
    if not species or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError('invalid arguments')
    if not os.path.isdir(root):
        raise FileNotFoundError(root)
    files = sorted((os.path.join(root, name) for name in os.listdir(root) if name.endswith('.permit') and os.path.isfile(os.path.join(root, name))))
    if not files:
        return []
    completed = subprocess.run(['grep', '-h', '-F', '--', species, *files], capture_output=True, text=True, check=False)
    if completed.returncode not in (0, 1):
        raise RuntimeError('search failed')
    results = []
    for line in completed.stdout.splitlines():
        if not line.strip() or line == 'permit_id,species,site,area_hectares,status':
            continue
        fields = next(csv.reader([line]), [])
        if len(fields) != 5:
            continue
        permit_id, row_species, site, area_text, status = fields
        if row_species != species or status != 'approved':
            continue
        try:
            area = float(area_text)
        except ValueError:
            continue
        if not math.isfinite(area):
            continue
        results.append({'permit_id': permit_id, 'species': row_species, 'site': site, 'area_hectares': round(area, 2), 'status': status})
    results.sort(key=lambda row: (-row['area_hectares'], row['permit_id']))
    start = (page - 1) * page_size
    return results[start:start + page_size]

