import json
import os
from pathlib import Path

def _record(value):
    if not isinstance(value, dict) or set(value) != {'product', 'rating', 'comment', 'submitted_at', 'tags'}:
        raise ValueError('invalid record')
    if not isinstance(value['product'], str) or not value['product']:
        raise ValueError('invalid record')
    if isinstance(value['rating'], bool) or not isinstance(value['rating'], int) or (not 1 <= value['rating'] <= 5):
        raise ValueError('invalid record')
    if not isinstance(value['comment'], str):
        raise ValueError('invalid record')
    if isinstance(value['submitted_at'], bool) or not isinstance(value['submitted_at'], int) or value['submitted_at'] < 0:
        raise ValueError('invalid record')
    if not isinstance(value['tags'], list) or not all((isinstance(x, str) for x in value['tags'])):
        raise ValueError('invalid record')
    return value

def _path(base, name):
    root = Path(base).resolve()
    target = (root / name).resolve()
    try:
        target.relative_to(root)
    except ValueError:
        raise ValueError('invalid path')
    return target

def write_feedback_file(base_dir: str, relative_name: str, feedback: list[dict]) -> str:
    if not feedback:
        raise ValueError('empty feedback')
    data = [_record(x) for x in feedback]
    target = _path(base_dir, relative_name)
    target.parent.mkdir(parents=True, exist_ok=True)
    data.sort(key=lambda x: (x['product'], x['submitted_at'], x['comment']))
    with target.open('w', encoding='utf-8') as f:
        for item in data:
            f.write(json.dumps(item, ensure_ascii=False, separators=(',', ':')) + '\n')
    return str(target)

def read_feedback_file(base_dir: str, relative_name: str) -> list[dict]:
    target = _path(base_dir, relative_name)
    result = []
    with target.open(encoding='utf-8') as f:
        for line in f:
            if line.strip():
                try:
                    value = json.loads(line)
                except (TypeError, json.JSONDecodeError):
                    raise ValueError('invalid JSON')
                result.append(_record(value))
    return result

def summarize_feedback(feedback: list[dict], since: int | None=None, until: int | None=None) -> dict[str, dict]:
    for bound in (since, until):
        if bound is not None and (isinstance(bound, bool) or not isinstance(bound, int) or bound < 0):
            raise ValueError('invalid bound')
    if since is not None and until is not None and (since > until):
        raise ValueError('invalid bounds')
    groups = {}
    for item in feedback:
        item = _record(item)
        if since is not None and item['submitted_at'] < since:
            continue
        if until is not None and item['submitted_at'] > until:
            continue
        groups.setdefault(item['product'], []).append(item)
    output = {}
    for product in sorted(groups):
        items = groups[product]
        counts = {str(i): 0 for i in range(1, 6)}
        for item in items:
            counts[str(item['rating'])] += 1
        latest = items[0]
        for item in items[1:]:
            if item['submitted_at'] >= latest['submitted_at']:
                latest = item
        output[product] = {'count': len(items), 'average_rating': round(sum((x['rating'] for x in items)) / len(items), 2), 'rating_counts': counts, 'latest_comment': latest['comment']}
    return output

