from solution import verify_campaign_webhook, apply_campaign_events
import hashlib
import hmac
import json

def make_body(events, campaign='spring'):
    return json.dumps({'campaign': campaign, 'events': events}, separators=(',', ':'))

def sign(body, secret):
    return hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()

def test_valid_webhook_returns_original_events():
    events = [{'id': 'b', 'customer': 'alice', 'points': 4, 'timestamp': 20}, {'id': 'a', 'customer': 'bob', 'points': 2, 'timestamp': 10}]
    body = make_body(events)
    assert verify_campaign_webhook(body, sign(body, 'key'), 'key') == events

def test_bad_signature_returns_none_for_wrong_and_malformed_values():
    body = make_body([])
    assert verify_campaign_webhook(body, '0' * 64, 'key') is None
    assert verify_campaign_webhook(body, 'g' * 64, 'key') is None
    assert verify_campaign_webhook(body, '0' * 63, 'key') is None

def test_invalid_signed_structure_and_duplicate_ids_raise():
    body = json.dumps({'campaign': 'x', 'events': [{'id': 'x'}]}, separators=(',', ':'))
    try:
        verify_campaign_webhook(body, sign(body, 'key'), 'key')
        assert False
    except ValueError:
        pass
    events = [{'id': 'x', 'customer': 'a', 'points': 1, 'timestamp': 1}, {'id': 'x', 'customer': 'b', 'points': 2, 'timestamp': 2}]
    body = make_body(events)
    try:
        verify_campaign_webhook(body, sign(body, 'key'), 'key')
        assert False
    except ValueError:
        pass

def test_processing_sorts_ties_and_applies_window():
    events = [{'id': 'z', 'customer': 'a', 'points': 3, 'timestamp': 100}, {'id': 'a', 'customer': 'a', 'points': 5, 'timestamp': 100}, {'id': 'old', 'customer': 'a', 'points': 99, 'timestamp': 100 - 30 * 86400 - 1}, {'id': 'b', 'customer': 'b', 'points': -2, 'timestamp': 99}]
    balances, done = apply_campaign_events(events, {'a': 1, 'c': 7}, {'keep'})
    assert balances == {'a': 9, 'b': -2, 'c': 7}
    assert done == {'keep', 'z', 'a', 'b'}

def test_processing_skips_existing_ids_and_does_not_mutate_inputs():
    events = [{'id': 'x', 'customer': 'a', 'points': 8, 'timestamp': 10}, {'id': 'y', 'customer': 'a', 'points': 2, 'timestamp': 20}]
    balances = {'a': 3}
    processed = {'x'}
    result = apply_campaign_events(events, balances, processed)
    assert result == ({'a': 5}, {'x', 'y'})
    assert balances == {'a': 3}
    assert processed == {'x'}

def test_empty_processing_returns_independent_copies():
    balances = {'a': 4}
    processed = {'x'}
    new_balances, new_processed = apply_campaign_events([], balances, processed)
    assert (new_balances, new_processed) == (balances, processed)
    assert new_balances is not balances
    assert new_processed is not processed

