import hashlib
import hmac
import json

def verify_campaign_webhook(body: str, signature: str, secret: str) -> list[dict] | None:
    if len(signature) != 64:
        return None
    try:
        int(signature, 16)
    except ValueError:
        return None
    expected = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return None
    try:
        document = json.loads(body)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(document, dict) or not isinstance(document.get('campaign'), str) or (not document['campaign']) or (not isinstance(document.get('events'), list)):
        raise ValueError('invalid document')
    seen = set()
    for event in document['events']:
        if not isinstance(event, dict) or set(event) != {'id', 'customer', 'points', 'timestamp'}:
            raise ValueError('invalid event')
        if not isinstance(event['id'], str) or not event['id'] or event['id'] in seen:
            raise ValueError('invalid event id')
        if not isinstance(event['customer'], str) or not event['customer']:
            raise ValueError('invalid customer')
        if isinstance(event['points'], bool) or not isinstance(event['points'], int):
            raise ValueError('invalid points')
        if isinstance(event['timestamp'], bool) or not isinstance(event['timestamp'], int):
            raise ValueError('invalid timestamp')
        seen.add(event['id'])
    return document['events']

def apply_campaign_events(events: list[dict], balances: dict[str, int], processed_ids: set[str]) -> tuple[dict[str, int], set[str]]:
    result = dict(balances)
    done = set(processed_ids)
    if not events:
        return (result, done)
    latest = max((event['timestamp'] for event in events))
    cutoff = latest - 30 * 86400
    for event in sorted(events, key=lambda item: (item['timestamp'], item['id'])):
        if event['timestamp'] < cutoff or event['id'] in done:
            continue
        result[event['customer']] = result.get(event['customer'], 0) + event['points']
        done.add(event['id'])
    return (result, done)

