import re
import pytest


def test_invite_normalizes_project_and_locale():
    result = make_translation_invite("  Atlas Project  ", " EN-us ")
    assert result["project"] == "Atlas Project"
    assert result["locale"] == "en-us"
    assert set(result) == {"project", "locale", "code"}


def test_invite_code_format():
