    assert len(result["code"]) == 12
    assert re.fullmatch(r"[A-Z0-9]{12}", result["code"])


def test_invalid_locale_raises_value_error():
    with pytest.raises(ValueError):
        make_translation_invite("Handbook", "english")


def test_blank_project_raises_value_error():
    with pytest.raises(ValueError):
        make_translation_invite("   ", "de")


def test_codes_are_distinct_across_invites():
    codes = {
        make_translation_invite("Glossary", "ja")["code"]
        for _ in range(40)
    }
    assert len(codes) == 40

