import re
import secrets
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def make_translation_invite(project_name: str, target_locale: str) -> dict:
    project = project_name.strip()
    locale = target_locale.strip().lower()
    if not project:
        raise ValueError('project name cannot be blank')
    if re.fullmatch('[a-z]{2}(?:-[a-z]{2})?', locale) is None:
        raise ValueError('invalid locale')
    code = ''.join((secrets.choice(_ALPHABET) for _ in range(12)))
    return {'project': project, 'locale': locale, 'code': code}

