from solution import fetch_genealogy_records
from unittest.mock import Mock, patch
import pytest

def response(payload, status=200):
    r = Mock()
    r.status_code = status
    r.json.return_value = payload
    return r

def test_sorts_normalizes_and_groups_records():
    payload = {'records': [{'id': 7, 'name': 'Zed', 'birth_year': 1900}, {'id': 2, 'name': 'Ann', 'birth_year': 1899}, {'id': 3, 'name': 'Bee', 'birth_year': 1900}]}
    with patch('solution.requests.get', return_value=response(payload)) as get:
        result = fetch_genealogy_records('Smith')
    assert result == {'records': [{'id': 2, 'name': 'Ann', 'birth_year': 1899}, {'id': 3, 'name': 'Bee', 'birth_year': 1900}, {'id': 7, 'name': 'Zed', 'birth_year': 1900}], 'page': 1, 'page_size': 10, 'total': 3, 'decades': {'1890s': 1, '1900s': 2}}
    assert get.call_args.args[0] == 'https://api.example.org/genealogy/records'
    assert get.call_args.kwargs['params'] == {'surname': 'Smith'}
    assert get.call_args.kwargs['headers'] == {'Accept': 'application/json'}
    assert get.call_args.kwargs['timeout'] == 10

def test_negative_year_decades_are_floor_grouped():
    payload = {'records': [{'id': 1, 'name': 'A', 'birth_year': -1}, {'id': 2, 'name': 'B', 'birth_year': -10}, {'id': 3, 'name': 'C', 'birth_year': 0}]}
    with patch('solution.requests.get', return_value=response(payload)):
        result = fetch_genealogy_records('Lee')
    assert result['decades'] == {'-10s': 2, '0s': 1}

def test_argument_validation():
    with patch('solution.requests.get') as get:
        for args in [('', 1, 10), ('  ', 1, 10), ('A', 0, 10), ('A', -1, 10), ('A', 1, 0), ('A', 1, 101)]:
            with pytest.raises(ValueError):
                fetch_genealogy_records(*args)
        get.assert_not_called()

def test_rejects_bad_status():
    with patch('solution.requests.get', return_value=response({}, 503)):
        with pytest.raises(RuntimeError):
            fetch_genealogy_records('Taylor')

def test_rejects_invalid_payload_and_fields():
    bad_payloads = [{}, {'records': {}}, {'records': [{'id': 1, 'name': 'A'}]}, {'records': [{'id': '1', 'name': 'A', 'birth_year': 1900}]}, {'records': [{'id': 1, 'name': 3, 'birth_year': 1900}]}]
    for payload in bad_payloads:
        with patch('solution.requests.get', return_value=response(payload)):
            with pytest.raises(ValueError):
                fetch_genealogy_records('Brown')

def test_single_page_boundary_and_query_whitespace_is_preserved():
    payload = {'records': [{'id': 4, 'name': 'N', 'birth_year': 2001}]}
    with patch('solution.requests.get', return_value=response(payload)) as get:
        result = fetch_genealogy_records('  Brown  ', page=1, page_size=1)
    assert result['records'] == [{'id': 4, 'name': 'N', 'birth_year': 2001}]
    assert result['total'] == 1
    assert get.call_args.kwargs['params'] == {'surname': '  Brown  '}

