import hmac
import os

def register_for_webinar(email: str, password: str, webinar_id: int) -> dict:
    if not isinstance(email, str) or not isinstance(password, str) or isinstance(webinar_id, bool) or (not isinstance(webinar_id, int)):
        raise TypeError()
    normalized = email.strip().lower()
    if '@' not in normalized or not normalized.split('@', 1)[0] or (not normalized.split('@', 1)[1]):
        raise ValueError()
    if len(password) < 6 or webinar_id <= 0:
        raise ValueError()
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return {'email': normalized, 'webinar_id': webinar_id, 'password_hash': f'{iterations}${salt.hex()}${digest.hex()}'}

def verify_registration(registration: dict, email: str, password: str) -> bool:
    try:
        if not isinstance(registration, dict) or not isinstance(email, str) or (not isinstance(password, str)):
            return False
        if registration['email'] != email.strip().lower():
            return False
        iterations, salt_hex, digest_hex = registration['password_hash'].split('$', 2)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt_hex), int(iterations)).hex()
        return hmac.compare_digest(actual, digest_hex)
    except (KeyError, TypeError, ValueError, AttributeError):
        return False

