import json

def encode_work_orders(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def summarize_work_orders(blob: bytes | str, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(blob, bytes):
        try:
            text = blob.decode('utf-8')
        except UnicodeDecodeError:
            raise ValueError('invalid payload')
    elif isinstance(blob, str):
        text = blob
    else:
        raise ValueError('invalid payload')
    try:
        records = json.loads(text)
    except (json.JSONDecodeError, TypeError):
        raise ValueError('invalid payload')
    if not isinstance(records, list):
        raise ValueError('invalid records')
    for record in records:
        if not isinstance(record, dict) or set(record) != {'id', 'facility', 'priority', 'hours', 'status'}:
            raise ValueError('invalid record')
        if not isinstance(record['id'], str) or not isinstance(record['facility'], str) or (not isinstance(record['priority'], int)) or isinstance(record['priority'], bool) or (not isinstance(record['hours'], (int, float))) or isinstance(record['hours'], bool) or (not isinstance(record['status'], str)):
            raise ValueError('invalid record')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    selected = [r for r in records if status is None or r['status'] == status]
    selected.sort(key=lambda r: (-r['priority'], -r['hours'], r['id']))
    totals = {}
    for record in selected:
        totals[record['facility']] = totals.get(record['facility'], 0) + record['hours']
    start = (page - 1) * page_size
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'items': selected[start:start + page_size], 'by_facility': {k: round(totals[k], 2) for k in sorted(totals)}}

