import os

def save_membership_card(base_dir: str, member_filename: str, card_text: str) -> str:
    if not member_filename:
        raise ValueError('member_filename must not be empty')
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, member_filename))
    try:
        inside = os.path.commonpath((base, target)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('member_filename is outside base_dir')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        handle.write(card_text)
    return os.path.abspath(target)

