from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import datetime
KIND_ORDER = {'training': 0, 'class': 1, 'assessment': 2}
PRICE = {'training': Decimal('12.50'), 'class': Decimal('8.00'), 'assessment': Decimal('25.00')}
Q = Decimal('0.01')

def _money(v):
    try:
        x = Decimal(str(v))
    except (InvalidOperation, ValueError):
        raise ValueError('money')
    if not x.is_finite() or x < 0:
        raise ValueError('money')
    return x.quantize(Q, rounding=ROUND_HALF_UP)

def _auth(requester, resource):
    if requester['tenant_id'] != resource['tenant_id'] or (requester['id'] != resource.get('owner_id') and 'billing_admin' not in requester.get('roles', [])):
        raise PermissionError('forbidden')

def _check_date(s):
    try:
        datetime.strptime(s, '%Y-%m-%d')
    except (TypeError, ValueError):
        raise ValueError('date')
    if len(s) != 10:
        raise ValueError('date')

def build_invoice(requester: dict, account: dict, entries: list[dict]) -> dict:
    _auth(requester, account)
    period = 'none'
    groups = {}
    for e in entries:
        if e['account_id'] != account['id'] or e['kind'] not in PRICE or (not isinstance(e['units'], int)) or isinstance(e['units'], bool) or (e['units'] <= 0):
            raise ValueError('entry')
        _check_date(e['date'])
        period = e['date'][:7] if period == 'none' else min(period, e['date'][:7])
        key = (e['date'], e['kind'])
        groups[key] = groups.get(key, 0) + e['units']
    lines = []
    if account['status'] == 'active':
        fee = _money(account['monthly_fee'])
        lines.append({'description': 'Monthly membership', 'date': period, 'kind': 'membership', 'units': 1, 'unit_price': f'{fee:.2f}', 'amount': f'{fee:.2f}'})
    for (date, kind), units in sorted(groups.items(), key=lambda z: (z[0][0], KIND_ORDER[z[0][1]])):
        amount = (PRICE[kind] * units).quantize(Q)
        lines.append({'description': kind.title(), 'date': date, 'kind': kind, 'units': units, 'unit_price': f'{PRICE[kind]:.2f}', 'amount': f'{amount:.2f}'})
    subtotal = sum((_money(x['amount']) for x in lines), Decimal('0'))
    discount = (subtotal * Decimal('.10')).quantize(Q) if account['plan'] == 'annual' and subtotal >= 100 else Decimal('0')
    total = subtotal - discount
    return {'id': f"{account['id']}:{period}", 'account_id': account['id'], 'tenant_id': account['tenant_id'], 'period': period, 'lines': lines, 'subtotal': f'{subtotal:.2f}', 'discount': f'{discount:.2f}', 'total': f'{total:.2f}', 'paid': '0.00'}

def apply_payment(requester: dict, invoice: dict, amount: str) -> dict:
    if requester['tenant_id'] != invoice['tenant_id']:
        raise PermissionError('forbidden')
    try:
        x = Decimal(amount)
    except (InvalidOperation, ValueError):
        raise ValueError('amount')
    if not x.is_finite() or x <= 0 or x.as_tuple().exponent < -2:
        raise ValueError('amount')
    paid = _money(invoice['paid']) + x
    if paid > _money(invoice['total']):
        raise ValueError('excess')
    out = invoice.copy()
    out['paid'] = f'{paid:.2f}'
    return out

def billing_summary(requester: dict, accounts: list[dict], invoices: list[dict]) -> dict:
    selected = [a for a in accounts if a['tenant_id'] == requester['tenant_id']]
    if len({a['id'] for a in accounts}) != len(accounts):
        raise ValueError('duplicate')
    by = {a['id']: {'account_id': a['id'], 'owner_id': a['owner_id'], 'invoice_count': 0, 'billed': Decimal('0'), 'paid': Decimal('0')} for a in selected}
    seen = set()
    for i in invoices:
        if i['id'] in seen:
            raise ValueError('duplicate')
        seen.add(i['id'])
        if i['account_id'] in by and i['tenant_id'] == requester['tenant_id']:
            t, p = (_money(i['total']), _money(i['paid']))
            if p > t:
                raise ValueError('balance')
            z = by[i['account_id']]
            z['invoice_count'] += 1
            z['billed'] += t
            z['paid'] += p
    result = []
    for k in sorted(by):
        z = by[k]
        o = z['billed'] - z['paid']
        result.append({'account_id': k, 'owner_id': z['owner_id'], 'invoice_count': z['invoice_count'], 'billed': f"{z['billed']:.2f}", 'paid': f"{z['paid']:.2f}", 'outstanding': f'{o:.2f}'})
    total = sum((_money(x['outstanding']) for x in result), Decimal('0'))
    return {'tenant_id': requester['tenant_id'], 'account_count': len(selected), 'invoice_count': sum((x['invoice_count'] for x in result)), 'outstanding': f'{total:.2f}', 'by_account': result}

