    except (ValueError, TypeError):
        raise ValueError('invalid timestamp')

def fetch_outages(region: str, start: str, end: str, token: str) -> list[dict]:
    response = requests.get('https://api.utility.example/v1/outages', params={'region': region, 'start': start, 'end': end}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed with status ' + str(response.status_code))
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('outages'), list):
        raise ValueError('invalid response')
    keys = ('id', 'region', 'status', 'started_at', 'customers', 'eta')
    result = []
    for item in data['outages']:
        if not isinstance(item, dict) or any((k not in item for k in keys)):
            raise ValueError('invalid outage')
        result.append({k: item[k] for k in keys})
    return sorted(result, key=lambda x: (_time(x['started_at']), x['id']))

