            continue
        groups.setdefault(event['region'], []).append((event, started, eta))
    result = []
    for region, items in groups.items():
        total = sum((x[0]['customers'] for x in items))
        earliest = min(items, key=lambda x: x[1])
        etas = [x for x in items if x[2] is not None]
        latest = max(etas, key=lambda x: x[2])[0]['eta'] if etas else None
        result.append({'region': region, 'outage_count': len(items), 'customers_affected': total, 'earliest_started_at': earliest[0]['started_at'], 'latest_eta': latest, 'severity': 'critical' if total >= 1000 or len(items) >= 3 else 'warning'})
    return sorted(result, key=lambda x: (0 if x['severity'] == 'critical' else 1, -x['customers_affected'], x['region']))

