import csv
from decimal import Decimal, InvalidOperation
HEADER = ['order_id', 'customer', 'isbn', 'quantity', 'unit_price']

def _row(values, seen):
    if len(values) != 5:
        raise ValueError('invalid row')
    values = [x.strip() for x in values]
    oid, customer, isbn, quantity, price = values
    if not oid or not customer or (not isbn) or (oid in seen):
        raise ValueError('invalid field')
    try:
        q = int(quantity, 10)
    except ValueError:
        raise ValueError('invalid quantity')
    if q <= 0 or str(q) != quantity:
        raise ValueError('invalid quantity')
    try:
        p = Decimal(price)
    except InvalidOperation:
        raise ValueError('invalid price')
    if not p.is_finite() or p < 0 or abs(p.as_tuple().exponent) > 2:
        raise ValueError('invalid price')
    seen.add(oid)
    return {'order_id': oid, 'customer': customer, 'isbn': isbn, 'quantity': q, 'unit_price': p}

def parse_orders(path: str) -> list[dict]:
    seen = set()
    with open(path, newline='', encoding='utf-8') as stream:
        reader = csv.reader(stream)
        try:
            if next(reader) != HEADER:
                raise ValueError('invalid header')
        except StopIteration:
            raise ValueError('invalid header')
        return [_row(row, seen) for row in reader]

def rank_customers(path: str, top_n: int | None=None) -> list[dict]:
    rows = parse_orders(path)
    if top_n is not None and top_n <= 0:
        return []
    totals = {}
    for row in rows:
        item = totals.setdefault(row['customer'], {'customer': row['customer'], 'orders': 0, 'units': 0, 'value': Decimal('0')})
        item['orders'] += 1
        item['units'] += row['quantity']
        item['value'] += row['quantity'] * row['unit_price']
    answer = [{'customer': x['customer'], 'orders': x['orders'], 'units': x['units'], 'revenue': f"{x['value']:.2f}"} for x in totals.values()]
    answer.sort(key=lambda x: (-Decimal(x['revenue']), -x['units'], x['customer']))
    return answer if top_n is None else answer[:top_n]

def format_report(path: str, top_n: int | None=None) -> str:
    rows = rank_customers(path, top_n)
    return '\n'.join(['customer\torders\tunits\trevenue'] + [f"{x['customer']}\t{x['orders']}\t{x['units']}\t{x['revenue']}" for x in rows]) + '\n'

