import re
import xml.etree.ElementTree as ET
_FIELDS = ('house', 'street', 'city', 'region', 'postal', 'households')

def _text(node):
    return re.sub('\\s+', ' ', ''.join(node.itertext())).strip()

def _load(xml_text):
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'census':
        raise ValueError('invalid root')
    records = []
    ids = set()
    for node in list(root):
        if node.tag != 'address' or set(node.attrib) != {'id'}:
            raise ValueError('invalid address list')
        ident = node.attrib['id'].strip()
        if not ident or ident in ids:
            raise ValueError('invalid id')
        ids.add(ident)
        children = {}
        for child in list(node):
            if child.tag in _FIELDS:
                if child.tag in children:
                    raise ValueError('repeated field')
                children[child.tag] = _text(child)
        if set(children) != set(_FIELDS):
            raise ValueError('missing field')
        if not children['house'].isdigit() or not children['households'].isdigit():
            raise ValueError('invalid number')
        house = int(children['house'])
        households = int(children['households'])
        if house < 1 or any((not children[x] for x in ('street', 'city', 'region', 'postal'))):
            raise ValueError('invalid field')
        records.append({'id': ident, 'house': house, 'street': re.sub('\\s+', ' ', children['street']).strip().upper(), 'city': re.sub('\\s+', ' ', children['city']).strip().upper(), 'region': re.sub('\\s+', ' ', children['region']).strip().upper(), 'postal': re.sub('\\s+', ' ', children['postal']).strip().upper(), 'households': households})
    return records

def parse_addresses(xml_text: str) -> list[dict]:
    return _load(xml_text)

def summarize_addresses(xml_text: str, region: str | None=None) -> dict:
    records = _load(xml_text)
    wanted = None if region is None else re.sub('\\s+', ' ', region).strip().upper()
    records = [r for r in records if wanted is None or r['region'] == wanted]
    regions = {}
    prefixes = {}
    for record in records:
        regions[record['region']] = regions.get(record['region'], 0) + 1
        prefix = record['postal'][:3]
        prefixes[prefix] = prefixes.get(prefix, 0) + 1
    return {'addresses': len(records), 'households': sum((r['households'] for r in records)), 'by_region': dict(sorted(regions.items())), 'by_postal_prefix': dict(sorted(prefixes.items()))}

def duplicate_address_groups(xml_text: str) -> list[list[str]]:
    records = _load(xml_text)
    groups = {}
    order = []
    for record in records:
        key = tuple((record[x] for x in ('house', 'street', 'city', 'region', 'postal')))
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(record['id'])
    return [groups[key] for key in order if len(groups[key]) > 1]

