        revenue = record['revenue']
        completed = record['completed']
        if not isinstance(route_id, str) or not route_id or (not isinstance(driver, str)) or (not driver):
            raise ValueError('invalid delivery record')
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or distance < 0:
            raise ValueError('invalid delivery record')
        if isinstance(revenue, bool) or not isinstance(revenue, (int, float)) or revenue < 0:
            raise ValueError('invalid delivery record')
        if isinstance(stops, bool) or not isinstance(stops, int) or stops < 0 or (not isinstance(completed, bool)):
            raise ValueError('invalid delivery record')
