def summarize_access_reviews(requester: dict, reviews: list[dict], page: int, page_size: int) -> dict:
    if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not requester['id']) or (not isinstance(requester.get('tenant'), str)) or (not requester['tenant']) or (not isinstance(requester.get('roles'), list)) or (not all((isinstance(x, str) for x in requester['roles']))):
        raise ValueError('invalid requester')
    if isinstance(page, bool) or not isinstance(page, int) or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    if not isinstance(reviews, list):
        raise ValueError('invalid reviews')
    parsed = []
    for item in reviews:
        if not isinstance(item, dict):
            raise ValueError('invalid review')
        required = ('review_id', 'tenant', 'owner_id', 'subject_id', 'decision', 'risk', 'updated_at')
        if any((not isinstance(item.get(k), str) or not item[k] for k in required[:4])):
            raise ValueError('invalid review')
        if item['decision'] not in ('pending', 'approved', 'revoked'):
            raise ValueError('invalid review')
        if isinstance(item['risk'], bool) or not isinstance(item['risk'], int) or (not 0 <= item['risk'] <= 100):
            raise ValueError('invalid review')
        try:
            stamp = datetime.fromisoformat(item['updated_at'])
        except (TypeError, ValueError):
            raise ValueError('invalid review')
        parsed.append((item, stamp))
    if not (requester['roles'] and 'access_reviewer' in requester['roles']):
        if any((item['owner_id'] != requester['id'] or item['tenant'] != requester['tenant'] for item, _ in parsed)):
            raise PermissionError('review access denied')
    parsed.sort(key=lambda pair: (-pair[0]['risk'], -pair[1].timestamp(), pair[0]['review_id']))
    counts = {'pending': 0, 'approved': 0, 'revoked': 0}
    for item, _ in parsed:
        counts[item['decision']] += 1
    start = (page - 1) * page_size
    items = [item for item, _ in parsed[start:start + page_size]]
    average = round(sum((item['risk'] for item, _ in parsed)) / len(parsed), 2) if parsed else 0.0
    return {'total': len(parsed), 'page': page, 'page_size': page_size, 'items': items, 'by_decision': counts, 'average_risk': average}

