import math
import sqlite3
from typing import Any

def get_station_report(conn: sqlite3.Connection, station: str | None=None, min_average_cycle: float | None=None, sort_by: str='station', descending: bool=False, limit: int | None=None) -> list[dict[str, Any]]:
    allowed = {'station', 'average_cycle_seconds', 'total_units', 'runs'}
    if sort_by not in allowed:
        raise ValueError('invalid sort field')
    if min_average_cycle is not None and (not math.isfinite(min_average_cycle) or min_average_cycle < 0):
        raise ValueError('invalid minimum')
    if limit is not None and (isinstance(limit, bool) or not isinstance(limit, int) or limit < 0):
        raise ValueError('invalid limit')
    sql = 'SELECT station, AVG(cycle_seconds), SUM(units), COUNT(*) FROM cycles'
    params: list[Any] = []
    if station is not None:
        sql += ' WHERE station = ?'
        params.append(station)
    sql += ' GROUP BY station'
    rows = []
    for name, average, total, runs in conn.execute(sql, params):
        if min_average_cycle is not None and average < min_average_cycle:
            continue
        rows.append({'station': name, 'average_cycle_seconds': round(average, 2), 'total_units': total, 'runs': runs})
    rows.sort(key=lambda row: row['station'])
    rows.sort(key=lambda row: row[sort_by], reverse=descending)
    if limit is not None:
        rows = rows[:limit]
    return rows

