import math
import secrets

def generate_route_invite_code(route_id: str, length: int=12) -> str:
    if not isinstance(route_id, str) or not isinstance(length, int):
        raise TypeError()
    if not route_id or any((not (c.isalnum() or c == '-') for c in route_id)):
        raise ValueError()
    if length < 8 or length > 32:
        raise ValueError()
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def summarize_routes(records: list[dict], capacity: int, page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(records, list) or not isinstance(capacity, int) or (not isinstance(page, int)) or (not isinstance(page_size, int)):
        raise TypeError()
    if capacity <= 0 or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError()
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError()
        required = {'route_id', 'stop_id', 'students', 'distance_km', 'active'}
        if set(record) != required:
            raise ValueError()
        route_id = record['route_id']
        stop_id = record['stop_id']
        students = record['students']
        distance = record['distance_km']
        active = record['active']
        if not isinstance(route_id, str) or not route_id or (not isinstance(stop_id, str)) or (not stop_id):
            raise ValueError()
        if isinstance(students, bool) or not isinstance(students, int) or students < 0:
            raise ValueError()
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or distance < 0:
            raise ValueError()
        if not isinstance(active, bool):
            raise ValueError()
        if active:
            item = grouped.setdefault(route_id, [0, 0, 0.0])
            item[0] += 1
            item[1] += students
            item[2] += distance
    result = [{'route_id': key, 'stops': value[0], 'students': value[1], 'distance_km': round(value[2], 1), 'buses_needed': math.ceil(value[1] / capacity)} for key, value in grouped.items()]
    result.sort(key=lambda item: (-item['students'], item['route_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

