import xml.etree.ElementTree as ET

def parse_membership_invoice(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
        if root.tag != 'invoice':
            raise ValueError
        values = {}
        for name in ('member_id', 'plan', 'amount', 'billing_period'):
            element = root.find(name)
            if element is None or element.text is None or (not element.text.strip()):
                raise ValueError
            values[name] = element.text.strip()
        amount = float(values['amount'])
        if amount <= 0:
            raise ValueError
        return {'member_id': values['member_id'], 'plan': values['plan'], 'amount': amount, 'billing_period': values['billing_period']}
    except (ET.ParseError, ValueError, TypeError, OverflowError):
        raise ValueError('invalid invoice')

