def camera_violation_report(path: str, min_speed: int, offset: int=0, limit: int=10) -> list[dict]:
    if min_speed < 0 or offset < 0 or limit <= 0:
        raise ValueError('invalid numeric argument')
    result = subprocess.run(['cat', path], capture_output=True, text=True, check=True)
    groups = {}
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
