        item = groups.setdefault(camera, {'count': 0, 'total': 0, 'max_speed': speed})
        item['count'] += 1
        item['total'] += speed
        item['max_speed'] = max(item['max_speed'], speed)
    output = []
    for camera, item in groups.items():
