import csv
import math
import os
import tempfile

def export_permits(permits: list[dict], destination: str, district: str | None=None, min_fee: float=0.0) -> dict:
    if not isinstance(permits, list):
        raise ValueError('permits must be a list')
    if isinstance(min_fee, bool) or not isinstance(min_fee, (int, float)) or (not math.isfinite(min_fee)) or (min_fee < 0):
        raise ValueError('invalid minimum fee')
    fields = ('id', 'district', 'status', 'fee', 'attendees')
    checked = []
    for permit in permits:
        if not isinstance(permit, dict) or any((field not in permit for field in fields)):
            raise ValueError('invalid permit')
        if not isinstance(permit['id'], str) or not permit['id']:
            raise ValueError('invalid permit')
        if not isinstance(permit['district'], str) or not permit['district']:
            raise ValueError('invalid permit')
        if not isinstance(permit['status'], str):
            raise ValueError('invalid permit')
        if isinstance(permit['fee'], bool) or not isinstance(permit['fee'], (int, float)) or (not math.isfinite(permit['fee'])) or (permit['fee'] < 0):
            raise ValueError('invalid permit')
        if isinstance(permit['attendees'], bool) or not isinstance(permit['attendees'], int) or permit['attendees'] < 0:
            raise ValueError('invalid permit')
        checked.append(permit)
    selected = [p for p in checked if p['status'] == 'approved' and (district is None or p['district'] == district) and (p['fee'] >= min_fee)]
    selected.sort(key=lambda p: (-p['fee'], p['id']))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.permit-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('permit_id', 'district', 'fee', 'attendees'))
            for permit in selected:
                writer.writerow((permit['id'], permit['district'], f"{permit['fee']:.2f}", permit['attendees']))
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'count': len(selected), 'total_fee': round(sum((p['fee'] for p in selected)), 2), 'total_attendees': sum((p['attendees'] for p in selected))}

