def build_bom_summary(records: list[dict[str, Any]], page: int=1, page_size: int=10) -> dict[str, Any]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    grouped: dict[str, list[Decimal | int]] = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        component = record.get('component')
        quantity = record.get('quantity')
        unit_cost = record.get('unit_cost')
        if not isinstance(component, str) or not component:
            raise ValueError('invalid component')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        if isinstance(unit_cost, bool) or not isinstance(unit_cost, (int, float)) or (not math.isfinite(unit_cost)) or (unit_cost < 0):
            raise ValueError('invalid unit cost')
        if component not in grouped:
            grouped[component] = [0, Decimal('0')]
        grouped[component][0] += quantity
        grouped[component][1] += Decimal(str(quantity)) * Decimal(str(unit_cost))
    rows = []
    for component, (quantity, cost) in grouped.items():
        rounded = cost.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append({'component': component, 'quantity': quantity, 'total_cost': float(rounded)})
    rows.sort(key=lambda row: (-row['total_cost'], row['component']))
    total = sum((Decimal(str(row['total_cost'])) for row in rows), Decimal('0'))
    start = (page - 1) * page_size
    return {'total_components': len(rows), 'total_quantity': sum((row['quantity'] for row in rows)), 'total_cost': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'page': page, 'page_size': page_size, 'page_count': (len(rows) + page_size - 1) // page_size, 'items': rows[start:start + page_size]}

