import csv
import datetime
import math
import os
import tempfile

def parse_readings(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty document')
    rows = list(csv.reader(text.splitlines()))
    if not rows or rows[0] != ['timestamp', 'meter', 'reading']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not row or all((not part.strip() for part in row)):
            continue
        if len(row) != 3:
            raise ValueError('invalid row')
        try:
            value = float(row[2].strip())
            stamp = row[0].strip()
            if stamp.endswith('Z'):
                stamp = stamp[:-1] + '+00:00'
            timestamp = datetime.datetime.fromisoformat(stamp)
        except Exception as exc:
            raise ValueError('invalid value') from exc
        meter = row[1].strip()
        if not meter or not math.isfinite(value):
            raise ValueError('invalid value')
        result.append({'timestamp': timestamp, 'meter': meter, 'reading': value})
    return result

def daily_totals(readings: list[dict]) -> list[dict]:
    groups = {}
    for position, record in enumerate(readings):
        try:
            timestamp = record['timestamp']
            meter = record['meter']
            value = float(record['reading'])
        except Exception as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(timestamp, datetime.datetime) or not isinstance(meter, str) or (not meter) or (not math.isfinite(value)):
            raise ValueError('invalid record')
        key = (timestamp.date().isoformat(), meter)
        groups.setdefault(key, []).append((timestamp, position, value))
    output = []
    for (date, meter), items in sorted(groups.items()):
        items.sort(key=lambda item: (item[0], item[1]))
        values = [item[2] for item in items]
        rounded = lambda x: round(x, 6)
        output.append({'date': date, 'meter': meter, 'count': len(values), 'first': rounded(values[0]), 'last': rounded(values[-1]), 'minimum': rounded(min(values)), 'maximum': rounded(max(values)), 'average': rounded(sum(values) / len(values)), 'consumption': rounded(values[-1] - values[0])})
    return output

def write_report(readings: list[dict], destination: str) -> int:
    rows = daily_totals(readings)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['date', 'meter', 'count', 'first', 'last', 'minimum', 'maximum', 'average', 'consumption'])
            for row in rows:
                writer.writerow([row['date'], row['meter'], row['count'], row['first'], row['last'], row['minimum'], row['maximum'], row['average'], row['consumption']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

