import os
import tempfile

def parse_scenes(payload: str) -> list[dict]:
    try:
        raw = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(raw, list):
        raise ValueError('top level must be a list')
    result = []
    seen = set()
    for item in raw:
        if not isinstance(item, dict):
            raise ValueError('scene must be an object')
        try:
            sid = item['scene_id']
            acquired = item['acquired']
            cloud = item['cloud_cover']
            bbox = item['bbox']
            bands = item['bands']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not isinstance(sid, str) or not (sid := sid.strip()) or sid in seen:
            raise ValueError('invalid or duplicate scene id')
        if not isinstance(acquired, str) or len(acquired) != 10:
            raise ValueError('invalid date')
        try:
            datetime.date.fromisoformat(acquired)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if isinstance(cloud, bool) or not isinstance(cloud, (int, float)) or (not math.isfinite(cloud)) or (not 0 <= cloud <= 100):
            raise ValueError('invalid cloud cover')
        if not isinstance(bbox, list) or len(bbox) != 4 or any((isinstance(x, bool) or not isinstance(x, (int, float)) or (not math.isfinite(x)) for x in bbox)):
            raise ValueError('invalid bounds')
        if bbox[0] >= bbox[2] or bbox[1] >= bbox[3]:
            raise ValueError('invalid bounds')
        if not isinstance(bands, list) or not bands or any((not isinstance(x, str) or not x.strip() for x in bands)):
            raise ValueError('invalid bands')
        clean_bands = sorted(set((x.strip() for x in bands)))
        seen.add(sid)
        result.append({'scene_id': sid, 'acquired': acquired, 'cloud_cover': float(cloud), 'bbox': [float(x) for x in bbox], 'bands': clean_bands})
    return result

def _number(x):
    return str(int(x)) if x.is_integer() else str(x)

def export_catalog(payload: str, destination: str) -> dict:
    scenes = parse_scenes(payload)
    scenes.sort(key=lambda x: (x['acquired'], x['cloud_cover'], x['scene_id']))
    years = {}
    for scene in scenes:
        year = scene['acquired'][:4]
        years[year] = years.get(year, 0) + 1
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.writer(stream)
            writer.writerow(['scene_id', 'acquired', 'cloud_cover', 'west', 'south', 'east', 'north', 'bands'])
            for s in scenes:
                writer.writerow([s['scene_id'], s['acquired'], _number(s['cloud_cover']), *[_number(x) for x in s['bbox']], '|'.join(s['bands'])])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'count': len(scenes), 'by_year': years}

