import datetime

def _check_record(record):
    if not isinstance(record, dict) or set(record) != {'machine', 'date', 'hours', 'task', 'parts'}:
        raise ValueError('invalid record')
    if not isinstance(record['machine'], str) or not record['machine']:
        raise ValueError('invalid machine')
    if not isinstance(record['task'], str) or not record['task']:
        raise ValueError('invalid task')
    if isinstance(record['hours'], bool) or not isinstance(record['hours'], int) or record['hours'] < 0:
        raise ValueError('invalid hours')
    if not isinstance(record['parts'], list) or any((not isinstance(x, str) for x in record['parts'])):
        raise ValueError('invalid parts')
    try:
        datetime.date.fromisoformat(record['date'])
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def encode_maintenance_log(records: list[dict]) -> bytes:
    if not isinstance(records, list):
        raise ValueError('invalid log')
    for record in records:
        _check_record(record)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def decode_maintenance_log(blob: bytes) -> list[dict]:
    if not isinstance(blob, (bytes, bytearray, memoryview)):
        raise ValueError('invalid blob')
    try:
        value = json.loads(bytes(blob).decode('utf-8'))
        if not isinstance(value, list):
            raise ValueError('invalid log')
        for record in value:
            _check_record(record)
        return value
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid blob')

