    if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days <= 0:
        raise ValueError('invalid window')
    if not isinstance(records, list):
        raise ValueError('invalid records')
    for record in records:
        _check_record(record)
    if not records:
        return []
    dates = [datetime.date.fromisoformat(x['date']) for x in records]
    cutoff = max(dates) - datetime.timedelta(days=window_days - 1)
    groups = {}
    for record, date in zip(records, dates):
        if date < cutoff:
            continue
        group = groups.setdefault(record['machine'], {'hours': 0, 'latest': date, 'tasks': {}, 'parts': {}})
        group['hours'] += record['hours']
        group['latest'] = max(group['latest'], date)
        group['tasks'][record['task']] = group['tasks'].get(record['task'], 0) + 1
        for part in record['parts']:
            group['parts'][part] = group['parts'].get(part, 0) + 1
    result = []
    for machine in sorted(groups):
