import csv
import hashlib
import hmac
import os

def create_operator(username: str, password: str) -> dict:
    if not isinstance(username, str) or not username.strip() or (not isinstance(password, str)) or (not password):
        raise ValueError('invalid operator')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username.strip(), 'salt': salt.hex(), 'password': digest.hex()}

def authenticate_operator(operator: dict, password: str) -> bool:
    try:
        if not isinstance(operator, dict) or not isinstance(password, str):
            return False
        salt = bytes.fromhex(operator['salt'])
        expected = bytes.fromhex(operator['password'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def parse_inventory(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('invalid inventory')
    rows = list(csv.reader(text.splitlines()))
    if not rows or rows[0] != ['site', 'equipment_id', 'kind', 'status', 'capacity']:
