def render_moderation_page(reviews: list[dict], page: int=1, per_page: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page <= 0:
        raise ValueError('invalid per_page')
    checked = []
    for review in reviews:
        if not isinstance(review, dict):
            raise ValueError('invalid review')
        try:
            review_id = review['id']
            reviewer = review['reviewer']
            destination = review['destination']
            rating = review['rating']
            comment = review['comment']
        except (KeyError, TypeError):
            raise ValueError('invalid review')
        if isinstance(review_id, bool) or not isinstance(review_id, int):
            raise ValueError('invalid id')
        if isinstance(rating, bool) or not isinstance(rating, int) or (not 1 <= rating <= 5):
