import csv
import os
import tempfile

def export_ticket_summary(tickets: list[dict], destination: str) -> int:
    groups = {}
    priorities = {'high': 0, 'medium': 1, 'low': 2}
    required = {'id', 'customer', 'category', 'priority', 'status', 'minutes'}
    for ticket in tickets:
        if not isinstance(ticket, dict) or set(ticket) != required:
            raise ValueError('invalid ticket')
        if not all((isinstance(ticket[key], str) for key in ('id', 'customer', 'category'))):
            raise ValueError('invalid ticket')
        if ticket['priority'] not in priorities or ticket['status'] not in {'open', 'pending', 'closed'}:
            raise ValueError('invalid ticket')
        if isinstance(ticket['minutes'], bool) or not isinstance(ticket['minutes'], int) or ticket['minutes'] < 0:
            raise ValueError('invalid ticket')
        if ticket['status'] != 'closed':
            key = (ticket['category'], ticket['priority'])
            groups.setdefault(key, []).append(ticket['minutes'])
    rows = sorted(groups.items(), key=lambda item: (item[0][0], priorities[item[0][1]]))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='ticket-summary-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['category', 'priority', 'count', 'average_minutes'])
            for (category, priority), values in rows:
                writer.writerow([category, priority, len(values), f'{sum(values) / len(values):.2f}'])
        os.replace(temporary, destination)
        return len(rows)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

