import hashlib
import hmac
import json
import re

def verify_export(text: str, secret: bytes) -> list[dict]:
    if not isinstance(text, str) or not isinstance(secret, bytes):
        raise TypeError()
    if '\n' not in text:
        raise ValueError()
    header, body = text.split('\n', 1)
    if not re.fullmatch('EDR1 [0-9a-f]{64}', header) or not body:
        raise ValueError()
    expected = hmac.new(secret, body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(header[5:], expected):
        raise ValueError()
    lines = body.split('\n')
    if lines[-1] != '':
        raise ValueError()
    lines.pop()
    if not lines:
        raise ValueError()
    result = []
    seen = set()
    fields = {'doc_id', 'reviewer', 'label', 'minutes', 'tags'}
    for line in lines:
        try:
            item = json.loads(line)
        except (ValueError, TypeError):
            raise ValueError()
        if not isinstance(item, dict) or set(item) != fields:
            raise ValueError()
        if not isinstance(item['doc_id'], str) or not item['doc_id'] or item['doc_id'] in seen or (not isinstance(item['reviewer'], str)) or (not item['reviewer']) or (item['label'] not in {'responsive', 'nonresponsive', 'privileged'}) or (not isinstance(item['minutes'], int)) or isinstance(item['minutes'], bool) or (item['minutes'] < 0) or (not isinstance(item['tags'], list)):
            raise ValueError()
        if any((not isinstance(t, str) or not t for t in item['tags'])):
            raise ValueError()
        if len(set(item['tags'])) != len(item['tags']):
            raise ValueError()
        seen.add(item['doc_id'])
        result.append(item)
    return result

def summarize_reviews(records: list[dict]) -> dict:
    groups = {}
    tags = {}
    for r in records:
        name = r['reviewer']
        if name not in groups:
            groups[name] = {'name': name, 'documents': 0, 'minutes': 0, 'labels': {'nonresponsive': 0, 'privileged': 0, 'responsive': 0}}
        g = groups[name]
        g['documents'] += 1
        g['minutes'] += r['minutes']
        g['labels'][r['label']] += 1
        for tag in r['tags']:
            tags[tag] = tags.get(tag, 0) + 1
    return {'documents': len(records), 'reviewers': [groups[k] for k in sorted(groups)], 'tag_counts': {k: tags[k] for k in sorted(tags)}}

