def assign_room(requester: dict, booking_id: str, room_id: str, bookings: dict, rooms: dict) -> dict:
    booking = bookings[booking_id]
    room = rooms[room_id]
    if requester.get('hostel_id') != booking.get('hostel_id'):
        raise PermissionError('requester is not allowed')
    if requester.get('user_id') != booking.get('guest_id') and requester.get('role') not in {'receptionist', 'manager'}:
        raise PermissionError('requester is not allowed')
    if booking.get('status') != 'confirmed':
        raise ValueError('booking is not confirmed')
    if room.get('hostel_id') != booking.get('hostel_id'):
        raise ValueError('room belongs to another hostel')
