import json
from datetime import date, timedelta

def serialize_tracker(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise TypeError('state must be a dictionary')
    return json.dumps(state, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')

def deserialize_tracker(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, AttributeError, TypeError, ValueError) as exc:
        raise ValueError('invalid tracker data') from exc
    if not isinstance(value, dict):
        raise ValueError('tracker data must be a dictionary')
    return value

def _day(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def injury_summary(events: list[dict], window_days: int=30) -> list[dict]:
    if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days <= 0:
        raise ValueError('invalid window')
    groups = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        athlete = event.get('athlete')
        injury = event.get('injury')
        severity = event.get('severity')
        if not isinstance(athlete, str) or not athlete or (not isinstance(injury, str)) or (not injury):
            raise ValueError('invalid event')
        if isinstance(severity, bool) or not isinstance(severity, int) or (not 1 <= severity <= 5):
            raise ValueError('invalid event')
        if 'start' not in event:
            raise ValueError('invalid event')
        start = _day(event['start'])
        end = _day(event.get('end', event['start']))
        if end < start:
            raise ValueError('invalid event')
        groups.setdefault(athlete, []).append((injury, start, end, severity))
    output = []
    for athlete, rows in groups.items():
        latest = max((row[2] for row in rows))
        cutoff = latest - timedelta(days=window_days - 1)
        days = burden = 0
        names = set()
        for injury, start, end, severity in rows:
            left, right = (max(start, cutoff), min(end, latest))
            if left <= right:
                count = (right - left).days + 1
                days += count
                burden += count * severity
                names.add(injury)
        output.append({'athlete': athlete, 'days': days, 'burden': burden, 'injuries': len(names)})
    output.sort(key=lambda item: (-item['burden'], -item['days'], item['athlete']))
    return output

