import datetime
import os
import tempfile

def _prepare(tickets):
    if not isinstance(tickets, list):
        raise ValueError('tickets must be a list')
    seen = set()
    rows = []
    for t in tickets:
        if not isinstance(t, dict) or not all((k in t for k in ('id', 'category', 'severity', 'created_at', 'tags'))):
            raise ValueError('invalid ticket')
        ident = t['id']
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError('invalid id')
        if t['severity'] not in ('critical', 'high', 'medium', 'low'):
            raise ValueError('invalid severity')
        if not isinstance(t['tags'], list) or not all((isinstance(x, str) for x in t['tags'])):
            raise ValueError('invalid tags')
        try:
            stamp = datetime.datetime.fromisoformat(t['created_at'].replace('Z', '+00:00'))
        except (AttributeError, TypeError, ValueError):
            raise ValueError('invalid timestamp')
        if stamp.tzinfo is None:
            stamp = stamp.replace(tzinfo=datetime.timezone.utc)
        seen.add(ident)
        sev = t['severity']
        priority = {'critical': 4, 'high': 3, 'medium': 2, 'low': 1}[sev]
        sla = {'critical': 1, 'high': 4, 'medium': 24, 'low': 72}[sev]
        executive = 'executive' in t['tags']
        if executive:
            queue = 'executive-desk'
            sla = max(1, sla // 2)
        elif sev == 'critical':
            queue = 'incident-command'
        else:
            queue = {'security': 'sec-ops', 'outage': 'platform', 'access': 'helpdesk'}.get(t['category'], 'triage')
        rows.append((stamp, ident, {'id': ident, 'queue': queue, 'priority': priority, 'sla_hours': sla}))
    rows.sort(key=lambda x: (-x[2]['priority'], x[0], x[1]))
    return [x[2] for x in rows]

def route_tickets(tickets: list[dict]) -> list[dict]:
    return _prepare(tickets)

def export_routing_report(tickets: list[dict], output_path: str) -> dict:
    rows = _prepare(tickets)
    counts = {}
    priorities = {4: 0, 3: 0, 2: 0, 1: 0}
    for row in rows:
        counts[row['queue']] = counts.get(row['queue'], 0) + 1
        priorities[row['priority']] += 1
    parent = os.path.dirname(os.path.abspath(output_path))
    os.makedirs(parent, exist_ok=True)
    fd, temp = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f, lineterminator='\n')
            writer.writerow(['id', 'queue', 'priority', 'sla_hours'])
            for row in rows:
                writer.writerow([row['id'], row['queue'], row['priority'], row['sla_hours']])
        os.replace(temp, output_path)
    except Exception:
        try:
            os.unlink(temp)
        except FileNotFoundError:
            pass
        raise
    return {'total': len(rows), 'queues': counts, 'priorities': priorities}

