import csv
from pathlib import Path

def write_segment_export(base_dir: str, relative_name: str, rows: list[dict[str, str]]) -> str:
    if not relative_name:
        raise ValueError('relative_name must not be empty')
    base = Path(base_dir).resolve()
    destination = (base / relative_name).resolve()
    if destination != base and base not in destination.parents:
        raise ValueError('output path is outside base directory')
    destination.parent.mkdir(parents=True, exist_ok=True)
    with destination.open('w', encoding='utf-8', newline='') as handle:
        writer = csv.DictWriter(handle, fieldnames=['email', 'first_name', 'segment'], lineterminator='\n')
        writer.writeheader()
        for row in rows:
            writer.writerow({'email': row['email'], 'first_name': row['first_name'], 'segment': row['segment']})
    return str(destination)

