import subprocess

def triage_report(path: str, page: int=1, per_page: int=10, acuity: int | None=None) -> dict:
    if type(page) is not int or page <= 0:
        raise ValueError('invalid page')
    if type(per_page) is not int or per_page <= 0:
        raise ValueError('invalid per_page')
    if acuity is not None and (type(acuity) is not int or acuity < 1 or acuity > 5):
        raise ValueError('invalid acuity')
    try:
        completed = subprocess.run(['sort', '-t,', '-k1,1n', '-k2,2', path], capture_output=True, text=True, check=True)
    except (OSError, subprocess.CalledProcessError) as exc:
        raise ValueError('unable to read file') from exc
    records = []
    for raw in completed.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 4:
            raise ValueError('malformed record')
        try:
            arrival = int(fields[0])
            record_acuity = int(fields[2])
            wait = int(fields[3])
        except ValueError as exc:
            raise ValueError('malformed record') from exc
        patient = fields[1]
        if not patient or arrival < 0 or record_acuity < 1 or (record_acuity > 5) or (wait < 0):
            raise ValueError('malformed record')
        if acuity is None or record_acuity == acuity:
            records.append({'arrival': arrival, 'patient': patient, 'acuity': record_acuity, 'wait': wait})
    counts = {str(number): 0 for number in range(1, 6)}
    for record in records:
        counts[str(record['acuity'])] += 1
    total = len(records)
    average = round(sum((record['wait'] for record in records)) / total, 2) if total else 0.0
    start = (page - 1) * per_page
    return {'total': total, 'by_acuity': counts, 'average_wait': average, 'page': page, 'per_page': per_page, 'records': records[start:start + per_page]}

