    with tempfile.TemporaryDirectory() as directory:
        write_json(directory, "page.json", [
            {"movie": "A", "seats": 1, "price": 50, "status": "confirmed"},
            {"movie": "B", "seats": 1, "price": 40, "status": "confirmed"},
            {"movie": "C", "seats": 1, "price": 30, "status": "confirmed"},
