            {"movie": "A", "tickets": 1, "revenue": 50.0},
            {"movie": "B", "tickets": 1, "revenue": 40.0},
        ]
        assert summarize_reservations(directory, "page.json", 3, 2) == [
            {"movie": "E", "tickets": 1, "revenue": 10.0}
        ]
        assert summarize_reservations(directory, "page.json", 4, 2) == []


def test_empty_input_returns_empty_list():
