        with open(path, 'r', encoding='utf-8') as handle:
            data = json.load(handle)
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError('invalid reservation file') from exc
    if not isinstance(data, list):
        raise ValueError('invalid reservation data')
    groups = {}
    for item in data:
        if not isinstance(item, dict):
            raise ValueError('invalid reservation')
        movie = item.get('movie')
        seats = item.get('seats')
        price = item.get('price')
        status = item.get('status')
        if not isinstance(movie, str) or not movie or (not isinstance(seats, int)) or isinstance(seats, bool) or (seats <= 0) or (not isinstance(price, (int, float))) or isinstance(price, bool) or (price < 0) or (status not in ('confirmed', 'cancelled')):
            raise ValueError('invalid reservation')
        if status == 'confirmed':
            total = groups.setdefault(movie, [0, 0.0])
            total[0] += seats
            total[1] += seats * price
    result = [{'movie': movie, 'tickets': values[0], 'revenue': round(values[1], 2)} for movie, values in groups.items()]
    result.sort(key=lambda item: (-item['revenue'], item['movie']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

