import hashlib
import hmac
import json
import re

def verify_signature(payload: str, signature: str, secret: bytes) -> bool:
    if not isinstance(signature, str) or re.fullmatch('[0-9a-f]{64}', signature) is None:
        return False
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def process_batch(payload: str, signature: str, secret: bytes) -> dict:
    if not verify_signature(payload, signature, secret):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(document, dict) or set(document) != {'events'} or (not isinstance(document['events'], list)):
        raise ValueError('invalid payload')
    totals = {}
    for event in document['events']:
        if not isinstance(event, dict) or set(event) != {'project', 'vintage', 'action', 'amount'}:
            raise ValueError('invalid event')
        project = event['project']
        vintage = event['vintage']
        action = event['action']
        amount = event['amount']
        if not isinstance(project, str) or not project or (not isinstance(vintage, int)) or isinstance(vintage, bool) or (vintage < 1900) or (vintage > 2100) or (action not in ('issue', 'retire')) or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount <= 0):
            raise ValueError('invalid event')
        key = (project, vintage)
        row = totals.setdefault(key, [0, 0, 0])
        if action == 'issue':
            row[0] += amount
            row[2] += amount
        else:
            if row[2] < amount:
                raise ValueError('insufficient credits')
            row[1] += amount
            row[2] -= amount
    projects = []
    for (project, vintage), values in sorted(totals.items()):
        projects.append({'project': project, 'vintage': vintage, 'issued': values[0], 'retired': values[1], 'available': values[2]})
    return {'projects': projects, 'total_available': sum((row['available'] for row in projects))}

