import html
import math

def render_inspection_report(records: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(per_page, int)) or isinstance(per_page, bool):
        raise TypeError('page and per_page must be integers')
    if page < 1 or per_page < 1 or per_page > 100:
        raise ValueError('invalid pagination')
    required = {'id', 'inspector', 'area', 'status', 'score'}
    checked = []
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('invalid record')
        if not all((isinstance(record[key], str) for key in ('id', 'inspector', 'area', 'status'))):
            raise ValueError('invalid record')
        score = record['score']
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)) or (not 0 <= score <= 100):
            raise ValueError('invalid score')
        if record['status'] not in {'pass', 'fail', 'hold'}:
            raise ValueError('invalid status')
        checked.append(record)
    ordered = sorted(checked, key=lambda r: (-r['score'], r['id']))
    total = len(ordered)
    average = sum((r['score'] for r in ordered)) / total if total else 0
    pages = (total + per_page - 1) // per_page if total else 0
    start = (page - 1) * per_page
    visible = ordered[start:start + per_page]
    esc = lambda value: html.escape(str(value), quote=True)
    rows = ''.join((f"<tr><td>{esc(r['id'])}</td><td>{esc(r['inspector'])}</td><td>{esc(r['area'])}</td><td>{esc(r['status'])}</td><td>{esc(r['score'])}</td></tr>" for r in visible))
    return f'<div class="report"><h1>Inspection Results</h1><p class="summary">Total: {total} | Average: {average:.2f}</p><table><thead><tr><th>ID</th><th>Inspector</th><th>Area</th><th>Status</th><th>Score</th></tr></thead><tbody>{rows}</tbody></table><p class="page">Page {page} of {pages}</p></div>'

