import hashlib
import secrets

def register_rig(password: str, asset_ids: list[str]) -> dict:
    if not isinstance(password, str) or not password:
        raise ValueError('password must not be empty')
    if not isinstance(asset_ids, list):
        raise ValueError('assets must be a list')
    if any((not isinstance(asset, str) or not asset for asset in asset_ids)):
        raise ValueError('invalid asset')
    if len(set(asset_ids)) != len(asset_ids):
        raise ValueError('duplicate asset')
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'password_hash': salt.hex() + '$' + digest.hex(), 'assets': list(asset_ids)}

def authorize_asset(account: dict, password: str, asset_id: str) -> bool:
    try:
        stored = account['password_hash']
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return secrets.compare_digest(actual, expected) and asset_id in account['assets']
    except (KeyError, TypeError, ValueError, AttributeError):
        return False

