import sqlite3

def calculate_reserves(conn: sqlite3.Connection, statuses: list[str] | None=None, policyholder_search: str | None=None, sort_by: str='claim_id', descending: bool=False) -> dict:
    allowed = {'claim_id', 'policyholder', 'status', 'incurred', 'paid', 'expenses', 'reserve'}
    if sort_by not in allowed:
        raise ValueError('invalid sort field')
    where = []
    params = []
    if statuses is not None:
        if not statuses:
            return {'claims': [], 'total_reserve': 0}
        marks = ','.join(('?' for _ in statuses))
        where.append(f'status IN ({marks})')
        params.extend(statuses)
    if policyholder_search is not None:
        where.append('LOWER(policyholder) LIKE LOWER(?)')
        params.append('%' + policyholder_search + '%')
    query = 'SELECT claim_id, policyholder, status, incurred, paid, expenses FROM claims'
    if where:
        query += ' WHERE ' + ' AND '.join(where)
    if sort_by == 'reserve':
        key = 'CASE WHEN incurred - paid > 0 THEN incurred - paid ELSE 0 END + expenses'
    else:
        key = sort_by
    direction = 'DESC' if descending else 'ASC'
    query += f' ORDER BY {key} {direction}, claim_id ASC'
    rows = conn.execute(query, params).fetchall()
    claims = []
    total = 0
    for claim_id, policyholder, status, incurred, paid, expenses in rows:
        reserve = max(incurred - paid, 0) + expenses
        claims.append({'claim_id': claim_id, 'policyholder': policyholder, 'status': status, 'incurred': incurred, 'paid': paid, 'expenses': expenses, 'reserve': reserve})
        total += reserve
    return {'claims': claims, 'total_reserve': total}

