from io import StringIO

def parse_inventory(text: str) -> dict:
    try:
        rows = list(csv.DictReader(StringIO(text), skipinitialspace=True))
    except csv.Error as e:
        raise ValueError(str(e))
    fields = ['sku', 'on_hand', 'reorder_point', 'target', 'unit_cost']
    if not rows or rows[0].keys() != set(fields):
        raise ValueError('invalid columns')
    out = {}
    for row in rows:
        sku = row['sku'].strip()
        if not sku or sku in out:
            raise ValueError('invalid sku')
        try:
            vals = [int(row[x].strip()) for x in fields[1:4]]
            cost = Decimal(row['unit_cost'].strip())
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if any((x < 0 for x in vals)) or vals[2] < vals[1] or cost <= 0:
            raise ValueError('invalid value')
        out[sku] = dict(zip(['on_hand', 'reorder_point', 'target'], vals))
        out[sku]['unit_cost'] = cost
    return out

def plan_replenishment(inventory: dict, usage: dict, horizon: int=7) -> dict:
    if not isinstance(horizon, int) or not 1 <= horizon <= 30:
        raise ValueError('horizon')
    keys = {k for k in inventory if isinstance(inventory[k], dict)}
    if set(usage) != keys:
        raise ValueError('skus')
    lines = []
    for sku in keys:
        vals = usage[sku]
        if len(vals) < horizon or any((not isinstance(x, int) or x < 0 for x in vals)):
            raise ValueError('usage')
        item = inventory[sku]
        qty = max(0, item['target'] - (item['on_hand'] - sum(vals[:horizon])))
        if qty:
            cost = item['unit_cost']
            lines.append({'sku': sku, 'quantity': qty, 'unit_cost': cost, 'extended_cost': cost * qty})
    lines.sort(key=lambda x: (-x['extended_cost'], x['sku']))
    result = {'lines': lines, 'total': sum((x['extended_cost'] for x in lines), Decimal('0')), 'status': 'pending'}
    result['owner_id'] = inventory.get('owner_id')
    result['tenant_id'] = inventory.get('tenant_id')
    return result

