import sqlite3

def summarize_leases(conn: sqlite3.Connection, statuses: list[str], min_rent: float | None, sort_by: str, descending: bool, page: int, page_size: int) -> list[dict]:
    allowed = {'property_id': 'property_id', 'property_name': 'property_name', 'lease_count': 'lease_count', 'total_monthly_rent': 'total_monthly_rent', 'average_monthly_rent': 'average_monthly_rent'}
    if sort_by not in allowed:
        raise ValueError('invalid sort_by')
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page_size')
    if min_rent is not None and min_rent < 0:
        raise ValueError('invalid min_rent')
    clauses = []
    if statuses:
        quoted = ','.join(("'" + status + "'" for status in statuses))
        clauses.append('status IN (' + quoted + ')')
    if min_rent is not None:
        clauses.append('monthly_rent >= ' + str(min_rent))
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    offset = (page - 1) * page_size
    query = 'SELECT property_id, property_name, COUNT(*) AS lease_count, ROUND(SUM(monthly_rent), 2) AS total_monthly_rent, ROUND(AVG(monthly_rent), 2) AS average_monthly_rent FROM leases' + where + ' GROUP BY property_id, property_name ORDER BY ' + allowed[sort_by] + ' ' + direction + ', property_id ASC LIMIT ' + str(page_size) + ' OFFSET ' + str(offset)
    rows = conn.execute(query).fetchall()
    keys = ['property_id', 'property_name', 'lease_count', 'total_monthly_rent', 'average_monthly_rent']
    return [dict(zip(keys, row)) for row in rows]

