def create_application(passport_number: str, pin: str, submitted_day: int, fee_cents: int) -> dict:
    if not isinstance(passport_number, str) or not passport_number.strip():
        raise ValueError('invalid passport number')
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isdecimal()) or (not pin.isascii()):
        raise ValueError('invalid pin')
    if not isinstance(submitted_day, int) or isinstance(submitted_day, bool) or (not 1 <= submitted_day <= 365):
        raise ValueError('invalid day')
    if not isinstance(fee_cents, int) or isinstance(fee_cents, bool) or fee_cents < 0:
        raise ValueError('invalid fee')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    proof = '100000$' + salt.hex() + '$' + digest.hex()
    return {'passport_number': passport_number.strip(), 'submitted_day': submitted_day, 'fee_cents': fee_cents, 'status': 'pending', 'pin_proof': proof}

def verify_pin(application: dict, pin: str) -> bool:
    try:
        if not isinstance(pin, str) or len(pin) != 4 or (not pin.isdecimal()) or (not pin.isascii()):
            return False
        iterations, salt_hex, digest_hex = application['pin_proof'].split('$')
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, int(iterations))
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

