def render_expense_report(records: list[dict], page: int=1, page_size: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        for key in ('employee', 'category', 'amount', 'status'):
            if key not in record:
                raise ValueError('missing field')
        employee = record['employee']
        category = record['category']
        amount = record['amount']
        status = record['status']
        if not isinstance(employee, str) or not employee:
            raise ValueError('invalid employee')
        if not isinstance(category, str) or not category:
            raise ValueError('invalid category')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise ValueError('invalid amount')
        if isinstance(amount, float) and (not isfinite(amount)):
            raise ValueError('invalid amount')
        if amount < 0:
            raise ValueError('invalid amount')
        if status not in ('approved', 'pending'):
            raise ValueError('invalid status')
        if status != 'approved':
            continue
        try:
            cents = int((Decimal(str(amount)) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid amount')
        groups.setdefault(employee, {})[category] = groups.setdefault(employee, {}).get(category, 0) + cents
    ordered = []
    for employee, categories in groups.items():
        total = sum(categories.values())
        ordered.append((employee, total, categories))
    ordered.sort(key=lambda item: (-item[1], item[0]))
    pages = max(1, (len(ordered) + page_size - 1) // page_size)
    if page > pages:
        raise ValueError('page out of range')
    selected = ordered[(page - 1) * page_size:page * page_size]
    rows = []
    for employee, _, categories in selected:
        items = sorted(categories.items(), key=lambda item: (-item[1], item[0]))
        for category, cents in items:
            rows.append(f'<tr><td>{escape(employee, quote=True)}</td><td>{escape(category, quote=True)}</td><td>${cents // 100:,}.{cents % 100:02d}</td></tr>')
    return f"""<div class="report"><h1>Expense report</h1><p>Page {page} of {pages}</p><table><thead><tr><th>Employee</th><th>Category</th><th>Amount</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div>"""

