import hashlib
import hmac
import os
import math

def _password_hash(password):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def _password_ok(password, stored):
    salt_text, digest_text = stored.split(':', 1)
    salt = bytes.fromhex(salt_text)
    expected = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
    return hmac.compare_digest(expected, digest_text)

def create_catalog(products: list[dict], password: str) -> dict:
    if not isinstance(products, list) or not isinstance(password, str) or (not password):
        raise ValueError()
    prepared = []
    for product in products:
        if not isinstance(product, dict) or set(product) != {'id', 'name', 'category', 'price', 'stock'}:
            raise ValueError()
        if any((not isinstance(product[k], str) or not product[k] for k in ('id', 'name', 'category'))):
            raise ValueError()
        price = product['price']
        stock = product['stock']
        if isinstance(price, bool) or not isinstance(price, (int, float)) or (not math.isfinite(price)) or (price < 0):
            raise ValueError()
        if isinstance(stock, bool) or not isinstance(stock, int) or stock < 0:
            raise ValueError()
        if stock:
            p = round(float(price), 2)
            prepared.append({'id': product['id'], 'name': product['name'], 'category': product['category'], 'price': p, 'stock': stock, 'inventory_value': round(p * stock, 2)})
    return {'products': prepared, 'password': _password_hash(password)}

def catalog_page(catalog: dict, password: str, category: str | None, page: int, page_size: int) -> dict:
    if not isinstance(category, (str, type(None))) or category == '':
        raise ValueError()
    if isinstance(page, bool) or not isinstance(page, int) or page < 1 or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError()
    if not _password_ok(password, catalog['password']):
        raise PermissionError()
    rows = [x for x in catalog['products'] if category is None or x['category'] == category]
    rows.sort(key=lambda x: (-x['inventory_value'], x['category'], x['id']))
    total = len(rows)
    start = (page - 1) * page_size
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': (total + page_size - 1) // page_size if total else 0, 'items': rows[start:start + page_size]}

