import io
import json
import math
import os

def parse_measurements(text: str) -> list[dict]:
    reader = csv.DictReader(io.StringIO(text))
    required = {'timestamp', 'well', 'temperature_c', 'pressure_kpa'}
    if reader.fieldnames is None or set(reader.fieldnames) != required:
        raise ValueError('invalid header')
    rows = list(reader)
    out = []
    for i, row in enumerate(rows):
        if all((v == '' for v in row.values() if v is not None)):
            if i != len(rows) - 1:
                raise ValueError('blank row')
            continue
        if None in row.values() or any((v is None for v in row.values())):
            raise ValueError('invalid row')
        try:
            ts = datetime.datetime.fromisoformat(row['timestamp'].replace('Z', '+00:00'))
            if ts.tzinfo is None:
                raise ValueError
            ts = ts.astimezone(datetime.timezone.utc)
            temp = float(row['temperature_c'])
            pressure = float(row['pressure_kpa'])
        except Exception as e:
            raise ValueError('invalid value') from e
        if not row['well'] or not math.isfinite(temp) or (not math.isfinite(pressure)):
            raise ValueError('invalid value')
        out.append({'timestamp': ts, 'well': row['well'], 'temperature_c': temp, 'pressure_kpa': pressure})
    return sorted(out, key=lambda r: (r['timestamp'], r['well']))

def aggregate_measurements(records: list[dict], window_minutes: int) -> list[dict]:
    if window_minutes <= 0:
        raise ValueError('invalid window')
    groups = {}
    for r in records:
        ts = r.get('timestamp')
        if not isinstance(ts, datetime.datetime) or ts.tzinfo is None:
            raise ValueError('invalid timestamp')
        try:
            ts = ts.astimezone(datetime.timezone.utc)
            base = ts.replace(hour=0, minute=0, second=0, microsecond=0)
            elapsed = int((ts - base).total_seconds())
            start = base + datetime.timedelta(seconds=elapsed // (window_minutes * 60) * window_minutes * 60)
            key = (start, r['well'])
            groups.setdefault(key, []).append(r)
        except (KeyError, TypeError) as e:
            raise ValueError('invalid record') from e
    result = []
    for (start, well), values in sorted(groups.items(), key=lambda x: (x[0][0], x[0][1])):
        result.append({'window_start': start.isoformat().replace('+00:00', 'Z'), 'well': well, 'count': len(values), 'average_temperature_c': sum((v['temperature_c'] for v in values)) / len(values), 'maximum_pressure_kpa': max((v['pressure_kpa'] for v in values))})
    return result

def sign_report(report: list[dict]) -> str:
    key = os.environ.get('GEOTHERMAL_SIGNING_KEY')
    if not key:
        raise RuntimeError('GEOTHERMAL_SIGNING_KEY is required')
    payload = json.dumps(report, sort_keys=True, separators=(',', ':')).encode('utf-8')
    return hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()

