import math

def summarize_manifest(requester: dict, voyage: dict, passengers: list[dict], page: int, page_size: int) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not isinstance(requester, dict) or not isinstance(voyage, dict):
        raise ValueError('invalid data')
    if requester.get('tenant_id') != voyage.get('tenant_id'):
        raise PermissionError('not permitted')
    if requester.get('id') != voyage.get('owner_id') and 'manifest_admin' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    if not isinstance(passengers, list) or not all((isinstance(x, dict) for x in passengers)):
        raise ValueError('invalid passengers')
    required = {'passenger_id', 'name', 'cabin', 'status', 'fare', 'voyage_id', 'tenant_id'}
    valid_statuses = ('booked', 'checked_in', 'cancelled')
    matching = []
    seen = set()
    for item in passengers:
        if not required.issubset(item):
            raise ValueError('invalid passenger')
        try:
            fare = float(item['fare'])
        except (TypeError, ValueError):
            raise ValueError('invalid fare')
        if not math.isfinite(fare) or fare < 0 or item['status'] not in valid_statuses:
            raise ValueError('invalid passenger')
        if item['voyage_id'] == voyage.get('id') and item['tenant_id'] == voyage.get('tenant_id'):
            if item['passenger_id'] in seen:
                raise ValueError('duplicate passenger')
            seen.add(item['passenger_id'])
            matching.append(item)
    matching.sort(key=lambda x: (x['cabin'], x['name'].casefold(), x['passenger_id']))
    counts = {status: 0 for status in valid_statuses}
    total = Decimal('0')
    for item in matching:
        counts[item['status']] += 1
        if item['status'] != 'cancelled':
            total += Decimal(str(item['fare']))
    total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    start = (page - 1) * page_size
    selected = matching[start:start + page_size]
    return {'voyage_id': voyage['id'], 'total_passengers': len(matching), 'status_counts': counts, 'total_fare': float(total), 'passengers': [{'passenger_id': x['passenger_id'], 'name': x['name'], 'cabin': x['cabin'], 'status': x['status']} for x in selected]}

