        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid rule') from exc
    matches = []
    for invoice in invoices:
        balance = invoice['amount'] - invoice['paid']
        names = {'id': invoice['id'], 'amount': invoice['amount'], 'paid': invoice['paid'], 'balance': balance, 'overdue': invoice['overdue']}
        try:
            selected = _value(tree, names)
        except Exception as exc:
            raise ValueError('invalid rule') from exc
