    matches.sort(key=lambda x: (-x[0], x[1]))
    start = (page - 1) * page_size
    return {'count': len(matches), 'total_balance': round(sum((x[0] for x in matches)), 2), 'items': [{'id': i, 'balance': round(b, 2)} for b, i in matches[start:start + page_size]]}

