        provided = bytes.fromhex(signature_text)
    except ValueError:
        raise ValueError('invalid ticket')
    if not 0 <= rating <= 3000:
        raise ValueError('invalid ticket')
    payload = f'{player}|{region}|{rating}'.encode('utf-8')
