            ident = node.attrib['id']
            item_status = node.attrib['status']
            priority = int(node.attrib['priority'])
            hours = float(node.attrib['hours'])
            rate = float(node.attrib['rate'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid work order') from exc
        if hours < 0 or rate < 0:
            raise ValueError('negative value')
        cost = round(hours * rate, 2)
        records.append({'id': ident, 'status': item_status, 'priority': priority, 'hours': hours, 'rate': rate, 'cost': cost})
