from datetime import datetime, timezone
from urllib.parse import quote
import requests

def fetch_reload_history(card_id: str, base_url: str, access_token: str, limit: int=100) -> dict:
    if not card_id or not 1 <= limit <= 500:
        raise ValueError('invalid card or limit')
    url = f"{base_url.rstrip('/')}/cards/{quote(card_id, safe='')}/reloads"
    response = requests.get(url, params={'limit': limit}, headers={'Accept': 'application/json', 'Authorization': f'Bearer {access_token}'}, timeout=10)
    if response.status_code != 200:
        raise ValueError(f'request failed with status {response.status_code}')
    return response.json()

def normalize_reloads(payload: dict) -> list[dict]:
    if not isinstance(payload, dict) or not isinstance(payload.get('reloads'), list):
        raise ValueError('reloads must be a list')
    required = ('id', 'amount_cents', 'currency', 'status', 'created_at', 'method')
    result = []
    for item in payload['reloads']:
        if not isinstance(item, dict) or any((k not in item for k in required)):
            raise ValueError('invalid reload')
        try:
            amount = int(item['amount_cents'])
            if amount < 0:
                raise ValueError('negative amount')
            stamp = item['created_at']
            if stamp.endswith('Z'):
                stamp = stamp[:-1] + '+00:00'
            moment = datetime.fromisoformat(stamp).astimezone(timezone.utc)
        except (TypeError, ValueError, AttributeError):
            raise ValueError('invalid reload')
        result.append({'id': item['id'], 'amount_cents': amount, 'currency': str(item['currency']).upper(), 'status': str(item['status']).upper(), 'created_at': moment, 'method': item['method']})
    return sorted(result, key=lambda x: (-x['created_at'].timestamp(), x['id']))

def monthly_reload_report(payload: dict, year: int, month: int) -> dict:
    if not 1 <= month <= 12:
        raise ValueError('invalid month')
    rows = [x for x in normalize_reloads(payload) if x['status'] == 'COMPLETED' and x['created_at'].year == year and (x['created_at'].month == month)]
    totals = {}
    for row in rows:
        totals[row['method']] = totals.get(row['method'], 0) + row['amount_cents']
    ordered = dict(sorted(totals.items()))
    return {'count': len(rows), 'total_cents': sum(totals.values()), 'by_method': ordered, 'latest_id': rows[0]['id'] if rows else None}

