import html
import re

def parse_sample_id(value: str) -> dict[str, object]:
    if not isinstance(value, str):
        raise ValueError('invalid sample id')
    match = re.fullmatch('([A-Z]{2,4})-([0-9]{4})-([0-9]{3,6})', value)
    if match is None:
        raise ValueError('invalid sample id')
    return {'site': match.group(1), 'year': int(match.group(2)), 'number': int(match.group(3))}

def summarize_readings(readings: list[dict[str, object]], sample_ids: set[str]) -> dict[str, dict[str, object]]:
    groups = {sample: [] for sample in sample_ids}
    for reading in readings:
        try:
            sample = reading['sample']
            day = reading['day']
            value = reading['value']
        except (KeyError, TypeError):
            raise ValueError('invalid reading')
        if not isinstance(sample, str) or sample not in sample_ids or (not isinstance(day, int)) or isinstance(day, bool) or (not isinstance(value, (int, float))) or isinstance(value, bool):
            raise ValueError('invalid reading')
        groups[sample].append((day, value))
    result = {}
    for sample in sorted(sample_ids):
        values = groups[sample]
        if not values:
            result[sample] = {'count': 0, 'average': None, 'first': None, 'last': None, 'trend': 'stable'}
            continue
        latest = max((day for day, value in values))
        nums = [value for day, value in values if day >= latest - 2]
        first, last = (nums[0], nums[-1])
        trend = 'increasing' if last > first else 'decreasing' if last < first else 'stable'
        result[sample] = {'count': len(nums), 'average': round(sum(nums) / len(nums), 2), 'first': first, 'last': last, 'trend': trend}
    return result

def render_sample_report(samples: list[dict[str, str]], readings: list[dict[str, object]]) -> str:
    parsed = []
    ids = set()
    for sample in samples:
        try:
            sid = sample['id']
            researcher = sample['researcher']
            species = sample['species']
        except (KeyError, TypeError):
            raise ValueError('invalid sample')
        info = parse_sample_id(sid)
        if sid in ids:
            raise ValueError('duplicate sample')
        ids.add(sid)
        parsed.append((info['site'], info['year'], info['number'], sid, researcher, species))
    summary = summarize_readings(readings, ids)
    rows = []
    for site, year, number, sid, researcher, species in sorted(parsed, key=lambda x: x[:3]):
        item = summary[sid]
        average = '-' if item['average'] is None else f"{item['average']:.2f}"
        rows.append('<tr>' + ''.join((f'<td>{html.escape(str(x), quote=True)}</td>' for x in [sid, researcher, species, item['count'], average, item['trend']])) + '</tr>')
    return '<table><thead><tr><th>Sample</th><th>Researcher</th><th>Species</th><th>Readings</th><th>Average</th><th>Trend</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table>'

