        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        if not isinstance(record['badge_id'], str) or not record['badge_id']:
            raise ValueError('invalid badge id')
        if not isinstance(record['holder'], str):
            raise ValueError('invalid holder')
        if not isinstance(record['clearance'], str) or not record['clearance']:
