import xml.etree.ElementTree as ET
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_deliveries(xml_text: str, customer: str | None=None, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'shipments':
        raise ValueError('invalid root')
    groups: dict[tuple[str, str], tuple[Decimal, int]] = {}
    for shipment in root.findall('shipment'):
        if shipment.get('status') != 'delivered':
            continue
        name = shipment.get('customer')
        chemical_node = shipment.find('chemical')
        quantity_node = shipment.find('quantity')
        if name is None or not name.strip() or chemical_node is None or (chemical_node.text is None) or (not chemical_node.text.strip()):
            raise ValueError('missing shipment field')
        if customer is not None and name != customer:
            continue
        if quantity_node is None or quantity_node.get('unit') != 'kg' or quantity_node.text is None:
            raise ValueError('invalid quantity')
        try:
            amount = Decimal(quantity_node.text.strip())
        except InvalidOperation as exc:
            raise ValueError('invalid quantity') from exc
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid quantity')
        key = (name, chemical_node.text.strip())
        old_amount, count = groups.get(key, (Decimal('0'), 0))
        groups[key] = (old_amount + amount, count + 1)
    ordered = sorted(groups.items(), key=lambda item: (-item[1][0], item[0][0], item[0][1]))
    start = (page - 1) * page_size
    result = []
    for (name, chemical), (amount, count) in ordered[start:start + page_size]:
        rounded = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'customer': name, 'chemical': chemical, 'quantity': float(rounded), 'shipments': count})
    return result

