import csv
import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_orders(path: str, page: int=1, page_size: int=10) -> list[dict]:
    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    result = subprocess.run(['sort', '-t,', '-k1,1', path], check=True, capture_output=True, text=True)
    groups = []
    current_id = None
    current_customer = None
    quantity = 0
    total = Decimal('0')
    for row in csv.reader(result.stdout.splitlines()):
        if not row:
            continue
        if len(row) != 5 or not row[0] or (not row[1]) or (not row[2]):
            raise ValueError('invalid row')
        try:
            qty = int(row[3])
            price = Decimal(row[4])
        except (ValueError, InvalidOperation):
            raise ValueError('invalid number')
        if qty <= 0 or price < 0:
            raise ValueError('invalid number')
        if current_id != row[0]:
            if current_id is not None:
                groups.append({'order_id': current_id, 'customer': current_customer, 'items': quantity, 'total': str(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))})
            current_id = row[0]
            current_customer = row[1]
            quantity = 0
            total = Decimal('0')
        elif current_customer != row[1]:
            raise ValueError('inconsistent customer')
        quantity += qty
        total += price * qty
    if current_id is not None:
        groups.append({'order_id': current_id, 'customer': current_customer, 'items': quantity, 'total': str(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))})
    start = (page - 1) * page_size
    return groups[start:start + page_size]

