import math
import secrets
import string

def create_pickup_passes(orders: list[dict], capacity: int, code_length: int=8) -> list[dict]:
    if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity <= 0:
        raise ValueError('invalid capacity')
    if isinstance(code_length, bool) or not isinstance(code_length, int) or (not 4 <= code_length <= 32):
        raise ValueError('invalid code length')
    if not isinstance(orders, list):
        raise ValueError('invalid orders')
    seen = set()
    grouped = {}
    for order in orders:
        if not isinstance(order, dict):
            raise ValueError('invalid order')
        if not all((key in order for key in ('order_id', 'slot', 'total'))):
            raise ValueError('invalid order')
        order_id, slot, total = (order['order_id'], order['slot'], order['total'])
        if not isinstance(order_id, str) or not order_id or order_id in seen:
            raise ValueError('invalid order id')
        if not isinstance(slot, str) or not slot:
            raise ValueError('invalid slot')
        if isinstance(total, bool) or not isinstance(total, (int, float)) or (not math.isfinite(total)) or (total < 0):
            raise ValueError('invalid total')
        seen.add(order_id)
        if total > 0:
            grouped.setdefault(slot, []).append((order_id, float(total)))
    alphabet = string.ascii_uppercase + string.digits
    result = []
    for slot in sorted(grouped):
        entries = sorted(grouped[slot], key=lambda item: (-item[1], item[0]))[:capacity]
        for order_id, total in entries:
            code = ''.join((secrets.choice(alphabet) for _ in range(code_length)))
            result.append({'order_id': order_id, 'slot': slot, 'total': total, 'code': code})
    return result

