from pathlib import Path

def save_camera_snapshot(base_dir: str, relative_name: str, content: bytes) -> str:
    if relative_name == '':
        raise ValueError('relative_name must not be empty')
    root = Path(base_dir).resolve()
    target = (root / relative_name).resolve()
    try:
        target.relative_to(root)
    except ValueError:
        raise ValueError('relative_name must refer to a location beneath base_dir')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('wb') as handle:
        handle.write(content)
    return str(target)

import hashlib
import hmac
import json

def verify_inventory_webhook(payload: bytes, signature: str, secret: bytes) -> dict | None:
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return None
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(value, dict):
        raise ValueError('payload must be an object')
    for field in ('event_id', 'venue', 'ticket_type'):
        if not isinstance(value.get(field), str):
            raise ValueError('invalid required field')
    quantity = value.get('quantity')
    if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
        raise ValueError('invalid quantity')
    return value

