def create_reviewer_record(username: str, password: str, clearance: str) -> dict:
    if not isinstance(username, str) or not username:
        raise ValueError('invalid username')
    if not isinstance(password, str) or len(password) < 8:
        raise ValueError('invalid password')
    if clearance not in {'public', 'internal', 'secret'}:
        raise ValueError('invalid clearance')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username, 'clearance': clearance, 'salt': base64.b64encode(salt).decode(), 'password_hash': base64.b64encode(digest).decode()}

def authenticate_reviewer(record: dict, password: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(password, str):
            return False
        salt = base64.b64decode(record['salt'], validate=True)
        expected = base64.b64decode(record['password_hash'], validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def parse_translation_segments(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    result = []
    for line in text.splitlines():
        if not line:
            continue
        fields, current, escaped = ([], [], False)
        for char in line:
            if escaped:
                if char not in '\\|':
                    raise ValueError('invalid escape')
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('dangling escape')
        fields.append(''.join(current))
        if len(fields) != 5 or not fields[0]:
            raise ValueError('malformed segment')
        try:
            page = int(fields[1])
            segment = int(fields[2])
        except ValueError:
            raise ValueError('invalid number')
        if page < 1 or segment < 0 or fields[3] not in {'draft', 'reviewed', 'approved'}:
            raise ValueError('invalid segment')
        result.append({'document': fields[0], 'page': page, 'segment': segment, 'status': fields[3], 'text': fields[4]})
    return result

def order_translation_segments(segments: list[dict]) -> list[dict]:
    if not isinstance(segments, list):
        raise TypeError('segments must be a list')
    ranks = {'draft': 0, 'reviewed': 1, 'approved': 2}
    checked = []
    for item in segments:
        try:
            status = item['status']
            document = item['document']
            page = item['page']
            segment = item['segment']
        except (KeyError, TypeError):
            raise ValueError('invalid entry')
        if status not in ranks:
            raise ValueError('invalid status')
        checked.append((item, (-ranks[status], document, page, segment)))
    return [item for item, _ in sorted(checked, key=lambda pair: pair[1])]

