    if not isinstance(base_url, str) or not base_url or (not isinstance(building_id, str)) or (not building_id):
        raise ValueError('invalid identifiers')
    if any((isinstance(x, bool) or not isinstance(x, int) for x in (start_time, end_time, min_duration_seconds))):
        raise ValueError('invalid time')
    if start_time >= end_time or min_duration_seconds < 0:
        raise ValueError('invalid range')
    url = base_url.rstrip('/') + '/v1/buildings/' + building_id + '/access-events'
    page = 1
    totals = {}
    while True:
        r = requests.get(url, params={'start_time': start_time, 'end_time': end_time, 'page': page, 'page_size': 100}, headers={'Accept': 'application/json'}, timeout=10)
        if r.status_code != 200:
            raise RuntimeError('request failed')
