        if not isinstance(data, dict) or not isinstance(data.get('events'), list):
            raise ValueError('invalid response')
        for event in data['events']:
            if not isinstance(event, dict) or not all((k in event for k in ('employee_id', 'door_id', 'entry_time', 'exit_time'))):
                raise ValueError('invalid event')
            if any((not isinstance(event[k], str) for k in ('employee_id', 'door_id'))) or any((isinstance(event[k], bool) or not isinstance(event[k], int) for k in ('entry_time', 'exit_time'))):
                raise ValueError('invalid event')
            duration = event['exit_time'] - event['entry_time']
            if start_time <= event['entry_time'] and event['exit_time'] <= end_time and (duration > 0) and (duration >= min_duration_seconds):
                item = totals.setdefault(event['employee_id'], {'total_seconds': 0, 'event_count': 0, 'doors': set()})
                item['total_seconds'] += duration
                item['event_count'] += 1
                item['doors'].add(event['door_id'])
        nxt = data.get('next_page')
        if nxt is None:
            break
        if isinstance(nxt, bool) or not isinstance(nxt, int) or nxt <= page:
            raise ValueError('invalid page')
        page = nxt
    result = [{'employee_id': k, 'total_seconds': v['total_seconds'], 'event_count': v['event_count'], 'doors': sorted(v['doors'])} for k, v in totals.items()]
    return sorted(result, key=lambda x: (-x['total_seconds'], x['employee_id']))

