        h[0] += 1
        a[0] += 1
        h[4] += hs
        h[5] += aws
        a[4] += aws
        a[5] += hs
        if hs > aws:
            h[1] += 1
            a[3] += 1
        elif hs < aws:
            a[1] += 1
            h[3] += 1
        else:
            h[2] += 1
            a[2] += 1
    fixtures.sort(key=lambda x: (x['date'], x['home'], x['away']))
    table = []
    for team, values in teams.items():
