        unit_cost = item.get('unit_cost')
        if not isinstance(part, str) or not part:
            raise ValueError('invalid item')
        if isinstance(qty, bool) or not isinstance(qty, (int, float)) or (not math.isfinite(qty)) or (qty <= 0):
            raise ValueError('invalid item')
        if isinstance(unit_cost, bool) or not isinstance(unit_cost, (int, float)) or (not math.isfinite(unit_cost)) or (unit_cost < 0):
            raise ValueError('invalid item')
        try:
            q = Decimal(str(qty))
            c = Decimal(str(unit_cost))
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid item') from exc
        if part not in grouped:
            grouped[part] = [Decimal(0), Decimal(0)]
        grouped[part][0] += q
        grouped[part][1] += q * c
    rows = []
    total = Decimal(0)
    for part, (quantity, raw_cost) in grouped.items():
        cost = raw_cost.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        total += raw_cost
