import ast
import operator

class _Evaluator(ast.NodeVisitor):
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    unary = {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}
    compare = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}

    def __init__(self, variables):
        self.variables = variables

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_Constant(self, node):
        if isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        raise ValueError('unsupported expression')

    def visit_Name(self, node):
        if node.id not in self.variables:
            raise NameError(node.id)
        return self.variables[node.id]

    def visit_BinOp(self, node):
        if type(node.op) not in self.binary:
            raise ValueError('unsupported expression')
        return self.binary[type(node.op)](self.visit(node.left), self.visit(node.right))

    def visit_UnaryOp(self, node):
        if type(node.op) not in self.unary:
            raise ValueError('unsupported expression')
        return self.unary[type(node.op)](self.visit(node.operand))

    def visit_BoolOp(self, node):
        if isinstance(node.op, ast.And):
            value = self.visit(node.values[0])
            for child in node.values[1:]:
                if not value:
                    return value
                value = self.visit(child)
            return value
        value = self.visit(node.values[0])
        for child in node.values[1:]:
            if value:
                return value
            value = self.visit(child)
        return value

    def visit_Compare(self, node):
        left = self.visit(node.left)
        for op, part in zip(node.ops, node.comparators):
            if type(op) not in self.compare:
                raise ValueError('unsupported expression')
            right = self.visit(part)
            if not self.compare[type(op)](left, right):
                return False
            left = right
        return True

    def visit_Call(self, node):
        if not isinstance(node.func, ast.Name) or node.func.id not in {'min', 'max', 'round'} or node.keywords:
            raise ValueError('unsupported expression')
        args = [self.visit(x) for x in node.args]
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)

    def generic_visit(self, node):
        raise ValueError('unsupported expression')

def evaluate_expression(expression: str, variables: dict[str, int | float]):
    return _Evaluator(variables).visit(ast.parse(expression, mode='eval'))

def training_report(records: list[dict], formula: str, threshold: int | float) -> list[dict]:
    grouped = {}
    for item in records:
        name = item['employee']
        if name not in grouped:
            grouped[name] = {'employee': name, 'department': item['department'], 'scores': [], 'hours': 0, 'completed': 0, 'records': 0}
        group = grouped[name]
        group['scores'].append(item['score'])
        group['hours'] += item['hours']
        group['completed'] += int(item['completed'])
        group['records'] += 1
    result = []
    for group in grouped.values():
        average = sum(group['scores']) / group['records']
        score = evaluate_expression(formula, {'average': average, 'hours': group['hours'], 'completed': group['completed'], 'records': group['records']})
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError('formula result must be numeric')
        if score >= threshold:
            result.append({'employee': group['employee'], 'department': group['department'], 'average': average, 'hours': group['hours'], 'completed': group['completed'], 'records': group['records'], 'score': score})
    return sorted(result, key=lambda x: (-x['score'], -x['completed'], x['employee']))

