import ast
import math
import re

def split_domain(domain: str) -> tuple[str, str]:
    if not isinstance(domain, str):
        raise TypeError('domain must be a string')
    if not domain or domain.endswith('.') or '.' not in domain:
        raise ValueError('invalid domain')
    parts = domain.split('.')
    if any((not p or not re.fullmatch('[a-z0-9-]+', p) or p[0] == '-' or (p[-1] == '-') for p in parts)):
        raise ValueError('invalid domain')
    if len(parts[-1]) < 2 or not re.fullmatch('[a-z]+', parts[-1]):
        raise ValueError('invalid suffix')
    return ('.'.join(parts[:-1]), '.' + parts[-1])

def _value(node, env):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in env:
            raise ValueError('unknown variable')
        return env[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        x = _value(node.operand, env)
        return +x if isinstance(node.op, ast.UAdd) else -x if isinstance(node.op, ast.USub) else not x
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        a, b = (_value(node.left, env), _value(node.right, env))
        try:
            return {ast.Add: a + b, ast.Sub: a - b, ast.Mult: a * b, ast.Div: a / b}[type(node.op)]
        except Exception as e:
            raise ValueError('bad arithmetic') from e
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _value(node.values[0], env)
        for n in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                return result
            result = _value(n, env)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, env)
        for op, n in zip(node.ops, node.comparators):
            right = _value(n, env)
            if isinstance(op, ast.Lt):
                ok = left < right
            elif isinstance(op, ast.LtE):
                ok = left <= right
            elif isinstance(op, ast.Gt):
                ok = left > right
            elif isinstance(op, ast.GtE):
                ok = left >= right
            elif isinstance(op, ast.Eq):
                ok = left == right
            elif isinstance(op, ast.NotEq):
                ok = left != right
            else:
                raise ValueError('bad comparison')
            if not ok:
                return False
            left = right
        return True
    if isinstance(node, ast.IfExp):
        return _value(node.body if _value(node.test, env) else node.orelse, env)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        try:
            return {'min': min, 'max': max, 'round': round}[node.func.id](*[_value(x, env) for x in node.args])
        except Exception as e:
            raise ValueError('bad function call') from e
    raise ValueError('unsupported expression')

def _evaluate(text, env):
    try:
        result = _value(ast.parse(text, mode='eval').body, env)
    except Exception as e:
        if isinstance(e, ValueError):
            raise
        raise ValueError('invalid expression') from e
    if isinstance(result, bool) or not isinstance(result, (int, float)) or (not math.isfinite(result)):
        raise ValueError('expression is not numeric')
    return result

def calculate_registrations(domains: list[str], rules: dict[str, str], context: dict[str, int | float]) -> list[dict[str, object]]:
    if any((not isinstance(k, str) or (k != '*' and (not k.startswith('.'))) for k in rules)) or any((not isinstance(v, str) for v in rules.values())):
        raise ValueError('invalid rules')
    if any((not isinstance(k, str) or not k.isidentifier() or isinstance(v, bool) or (not isinstance(v, (int, float))) for k, v in context.items())):
        raise ValueError('invalid context')
    out = []
    for domain in domains:
        name, suffix = split_domain(domain)
        matches = [k for k in rules if k != '*' and domain.endswith(k) and (domain == k[1:] or domain.endswith('.' + k[1:]))]
        key = max(matches, key=len) if matches else '*'
        if key not in rules:
            raise ValueError('no matching rule')
        env = dict(context, name_length=len(name), label_count=domain.count('.') + 1)
        out.append({'domain': domain, 'suffix': suffix, 'price': round(_evaluate(rules[key], env), 2), 'rule': key})
    return sorted(out, key=lambda x: (x['price'], x['domain']))

