import csv
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from io import StringIO

def _allowed(requester, project):
    return requester.get('tenant_id') == project.get('tenant_id') and (requester.get('id') == project.get('owner_id') or bool(set(requester.get('roles', [])) & {'admin', 'producer'}))

def _money(value):
    return float(Decimal(value).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

def build_project_report(requester: dict, project: dict, timesheet_csv: str, week_start: str) -> dict:
    if not _allowed(requester, project):
        raise PermissionError('not permitted')
    try:
        start = date.fromisoformat(week_start)
    except ValueError as exc:
        raise ValueError('invalid week') from exc
    if start.weekday() != 0:
        raise ValueError('week must start Monday')
    days = [start + timedelta(days=i) for i in range(7)]
    totals = {d.isoformat(): Decimal('0') for d in days}
    categories = {}
    billable = Decimal('0')
    reader = csv.DictReader(StringIO(timesheet_csv))
    if reader.fieldnames != ['date', 'employee', 'hours', 'category', 'billable']:
        raise ValueError('invalid header')
    for row in reader:
        if None in row or any((v is None for v in row.values())):
            raise ValueError('invalid row')
        try:
            d = date.fromisoformat(row['date'])
            hours = Decimal(row['hours'])
        except (ValueError, InvalidOperation) as exc:
            raise ValueError('invalid row') from exc
        if not row['employee'] or not row['category'] or hours < 0 or (hours > 24) or (row['billable'].lower() not in {'yes', 'no'}):
            raise ValueError('invalid row')
        if start <= d < start + timedelta(days=7):
            value = row['category']
            totals[d.isoformat()] += hours
            categories[value] = categories.get(value, Decimal('0')) + hours
            if row['billable'].lower() == 'yes':
                billable += hours
    return {'project_id': project['id'], 'week_start': week_start, 'total_hours': _money(sum(totals.values())), 'billable_hours': _money(billable), 'by_category': {k: _money(categories[k]) for k in sorted(categories)}, 'by_day': {k: _money(v) for k, v in totals.items()}}

def approve_deliverable(requester: dict, project: dict, deliverable_id: str) -> dict:
    if not _allowed(requester, project):
        raise PermissionError('not permitted')
    for item in project['deliverables']:
        if item.get('id') == deliverable_id:
            if item.get('status') != 'pending':
                raise ValueError('deliverable is not pending')
            item['status'] = 'approved'
            item['approved_by'] = requester['id']
            return item
    raise KeyError(deliverable_id)

