import hashlib
import hmac
import json

def build_index_report(payload: str, signature: str, secret: str, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        value = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(value, dict) or not isinstance(value.get('documents'), list):
        raise ValueError('invalid documents')
    totals = {}
    for item in value['documents']:
        if not isinstance(item, dict):
            raise ValueError('invalid document')
        required = ('id', 'tenant', 'title', 'size_bytes', 'status', 'indexed_at')
        if any((key not in item for key in required)):
            raise ValueError('invalid document')
        if not isinstance(item['id'], str) or not item['id']:
            raise ValueError('invalid document')
        if not isinstance(item['tenant'], str) or not item['tenant']:
            raise ValueError('invalid document')
        if not isinstance(item['title'], str) or not isinstance(item['status'], str) or (not isinstance(item['indexed_at'], str)):
            raise ValueError('invalid document')
        if isinstance(item['size_bytes'], bool) or not isinstance(item['size_bytes'], int) or item['size_bytes'] < 0:
            raise ValueError('invalid document')
        if item['status'] == 'ready':
            tenant = item['tenant']
            count, total = totals.get(tenant, (0, 0))
            totals[tenant] = (count + 1, total + item['size_bytes'])
    groups = []
    for tenant, (count, total) in totals.items():
        groups.append({'tenant': tenant, 'documents': count, 'total_bytes': total, 'average_bytes': round(total / count, 2)})
    groups.sort(key=lambda group: (-group['total_bytes'], group['tenant']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_groups': len(groups), 'groups': groups[start:start + page_size]}

