import xml.etree.ElementTree as ET

def parse_tile_index(xml_text: str, min_zoom: int=0) -> list[tuple[int, int, int, str]]:
    if min_zoom < 0:
        raise ValueError('min_zoom must be non-negative')
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    tiles = []
    for element in root.iter('tile'):
        try:
            z = int(element.attrib['z'])
            x = int(element.attrib['x'])
            y = int(element.attrib['y'])
            href = element.attrib['href']
        except (KeyError, ValueError) as exc:
            raise ValueError('invalid tile attributes') from exc
        if z >= min_zoom:
            tiles.append((z, x, y, href))
    return sorted(tiles, key=lambda tile: tile[:3])

