import xml.sax
import xml.sax.handler

class _TileHandler(xml.sax.handler.ContentHandler):

    def __init__(self, min_zoom: int) -> None:
        self.min_zoom = min_zoom
        self.tiles = []

    def startElement(self, name: str, attrs: xml.sax.xmlreader.AttributesImpl) -> None:
        if name != 'tile':
            return
        try:
            z = int(attrs['z'])
            x = int(attrs['x'])
            y = int(attrs['y'])
            href = attrs['href']
        except (KeyError, ValueError) as exc:
            raise ValueError('invalid tile attributes') from exc
        if z >= self.min_zoom:
            self.tiles.append((z, x, y, href))

def parse_tile_index(xml_text: str, min_zoom: int=0) -> list[tuple[int, int, int, str]]:
    if min_zoom < 0:
        raise ValueError('min_zoom must be non-negative')
    handler = _TileHandler(min_zoom)
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except (xml.sax.SAXException, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    return sorted(handler.tiles, key=lambda tile: tile[:3])

