import base64
import hashlib
import hmac
import os
import math
from datetime import datetime, timezone

def make_password_record(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password:
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def check_password(record: str, password: str) -> bool:
    if not isinstance(record, str) or not isinstance(password, str) or (not password):
        return False
    try:
        kind, salt_text, digest_text = record.split('$')
        if kind != 'pbkdf2':
            return False
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def refresh_dashboard(record: str, password: str, rows: list[dict], window_seconds: int=60) -> dict:
    if not check_password(record, password):
        raise PermissionError('invalid password')
    if not isinstance(rows, list):
        raise TypeError('rows must be a list')
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int):
        raise TypeError('window_seconds must be an integer')
    if window_seconds <= 0:
        raise ValueError('window_seconds must be positive')
    groups = {}
    totals = {}
    for row in rows:
        if not isinstance(row, dict) or set(row) != {'ts', 'metric', 'value', 'region'}:
            raise ValueError('invalid row')
        if not isinstance(row['ts'], str) or not isinstance(row['metric'], str) or (not isinstance(row['region'], str)):
            raise ValueError('invalid row')
        if not row['metric'] or not row['region'] or (not isinstance(row['value'], (int, float))) or isinstance(row['value'], bool) or (not math.isfinite(row['value'])):
            raise ValueError('invalid row')
        try:
            text = row['ts']
            if not text.endswith('Z'):
                raise ValueError
            stamp = datetime.fromisoformat(text[:-1] + '+00:00').timestamp()
        except (ValueError, OverflowError):
            raise ValueError('invalid row')
        start = math.floor(stamp / window_seconds) * window_seconds
        key = (start, row['metric'], row['region'])
        item = groups.setdefault(key, [0, 0])
        item[0] += 1
        item[1] += row['value']
        total = totals.setdefault(row['metric'], [0, 0])
        total[0] += 1
        total[1] += row['value']
    buckets = []
    for (start, metric, region), (count, total) in sorted(groups.items()):
        stamp = datetime.fromtimestamp(start, timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        buckets.append({'start': stamp, 'metric': metric, 'region': region, 'count': count, 'sum': total, 'average': total / count})
    result_totals = [{'metric': metric, 'count': count, 'sum': total, 'average': total / count} for metric, (count, total) in sorted(totals.items())]
    return {'buckets': buckets, 'totals': result_totals}

