import requests

def fetch_activity_summary(api_url: str, athlete_id: str, token: str, start_date: str | None=None, end_date: str | None=None) -> list[dict]:
    if not athlete_id or not token:
        raise ValueError('athlete_id and token are required')
    for value in (start_date, end_date):
        if value is not None:
            try:
                date.fromisoformat(value)
            except (TypeError, ValueError):
                raise ValueError('invalid date')
    if start_date and end_date and (start_date > end_date):
        raise ValueError('invalid date range')
    url = api_url.rstrip('/') + '/athletes/' + athlete_id + '/workouts'
    headers = {'Authorization': 'Bearer ' + token}
    page = 1
    groups = {}
    while True:
