        if start_date is not None:
            params['start_date'] = start_date
        if end_date is not None:
            params['end_date'] = end_date
        response = requests.get(url, params=params, headers=headers, timeout=10, verify=True)
        if response.status_code != 200:
            raise RuntimeError('request failed')
        try:
            payload = response.json()
        except Exception as exc:
            raise ValueError('invalid response') from exc
        if not isinstance(payload, dict) or not isinstance(payload.get('workouts'), list):
            raise ValueError('invalid response')
        for workout in payload['workouts']:
            workout_date = workout['date']
            if start_date is not None and workout_date < start_date:
                continue
            if end_date is not None and workout_date > end_date:
                continue
            activity = workout['activity']
            entry = groups.setdefault(activity, {'count': 0, 'total_duration': 0, 'total_calories': 0})
            entry['count'] += 1
            entry['total_duration'] += workout['duration_minutes']
            entry['total_calories'] += workout['calories']
        next_page = payload.get('next_page')
        if next_page is None:
            break
        page = next_page
    result = []
    for activity, values in groups.items():
        result.append({'activity': activity, **values, 'average_duration': round(values['total_duration'] / values['count'], 2)})
    result.sort(key=lambda item: (-item['total_duration'], item['activity']))
    return result

