def process_rebate_feed(xml_text: str, minimum_savings: float=0.0, offset: int=0, limit: int=50) -> list[dict[str, object]]:
    if minimum_savings < 0 or offset < 0 or limit <= 0:
        raise ValueError('invalid pagination or threshold')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
        if root.tag != 'applications':
            raise ValueError('invalid root')
        records = []
        for app in root.findall('application'):
            required = ['id', 'household', 'status', 'annual_kwh', 'projected_kwh', 'cost']
            if any((app.get(name) is None for name in required)):
                raise ValueError('missing attribute')
            annual = float(app.get('annual_kwh'))
            projected = float(app.get('projected_kwh'))
            cost = float(app.get('cost'))
            savings = annual - projected
            measures = []
            for measure in app.findall('measure'):
                if measure.get('type') is None or measure.get('kwh_saved') is None:
                    raise ValueError('invalid measure')
                measures.append({'type': measure.get('type'), 'kwh_saved': float(measure.get('kwh_saved'))})
            if app.get('status') == 'approved' and savings >= minimum_savings:
                rebate = round(min(cost * 0.3, savings * 0.12), 2)
                records.append({'id': app.get('id'), 'household': app.get('household'), 'savings_kwh': savings, 'rebate': rebate, 'measures': measures})
        records.sort(key=lambda item: (-item['rebate'], item['id']))
        return records[offset:offset + limit]
    except (etree.XMLSyntaxError, TypeError, ValueError):
        raise ValueError('invalid feed')

