import os

def read_schedule(base_dir: str, filename: str) -> list[tuple[str, str, str]]:
    root = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(root, filename))
    try:
        common = os.path.commonpath((root, path))
    except ValueError:
        raise ValueError('filename is outside base directory')
    if common != root:
        raise ValueError('filename is outside base directory')
    records = []
    with open(path, 'r', encoding='utf-8') as stream:
        for line in stream:
            line = line.strip()
            if not line:
                continue
            fields = [field.strip() for field in line.split(',')]
            if len(fields) != 3:
                raise ValueError('schedule line must have three fields')
            records.append(tuple(fields))
    records.sort(key=lambda record: (record[2], record[0]))
    return records

