import sqlite3

def incident_report(conn: sqlite3.Connection, station: str | None=None, status: str | None=None, min_severity: int | None=None, sort_by: str='reported_at', descending: bool=False, limit: int=50, offset: int=0) -> dict:
    if sort_by not in {'id', 'reported_at', 'severity', 'response_minutes'}:
        raise ValueError('invalid sort column')
    if not isinstance(descending, bool):
        raise TypeError('descending must be bool')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    if min_severity is not None and (not isinstance(min_severity, int) or isinstance(min_severity, bool) or (not 1 <= min_severity <= 5)):
        raise ValueError('invalid severity')
    clauses = []
    params = []
    if station is not None:
        clauses.append('station = ?')
        params.append(station)
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    if min_severity is not None:
        clauses.append('severity >= ?')
        params.append(min_severity)
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    order = ' DESC' if descending else ' ASC'
    base = 'SELECT id, station, reported_at, severity, status, response_minutes FROM incidents' + where
    rows = conn.execute(base + ' ORDER BY ' + sort_by + order + ', id ASC LIMIT ? OFFSET ?', params + [limit, offset]).fetchall()
    aggregate = conn.execute('SELECT COUNT(*), AVG(response_minutes) FROM incidents' + where, params).fetchone()
    grouped = conn.execute('SELECT status, COUNT(*) FROM incidents' + where + ' GROUP BY status ORDER BY status', params).fetchall()
    incidents = [dict(row) for row in rows]
    return {'incidents': incidents, 'count': aggregate[0], 'average_response_minutes': round(aggregate[1], 2) if aggregate[1] is not None else None, 'by_status': {row[0]: row[1] for row in grouped}}

