def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def route_requests(records: list[dict], as_of: str) -> list[dict]:
    today = _day(as_of)
    required = {'id', 'requester', 'department', 'category', 'amount', 'submitted', 'status'}
    result = []
    for item in records:
        if not isinstance(item, dict) or not required.issubset(item):
            raise ValueError('invalid record')
        if not all((isinstance(item[k], str) for k in ('id', 'requester', 'department', 'category', 'submitted', 'status'))):
            raise ValueError('invalid record')
        amount = item['amount']
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not isfinite(amount)) or (amount < 0):
            raise ValueError('invalid amount')
        submitted = _day(item['submitted'])
        if item['status'] not in {'pending', 'approved', 'rejected'}:
            raise ValueError('invalid status')
        days = max(0, (today - submitted).days)
        approver = 'manager' if amount <= 1000 else 'director' if amount <= 10000 else 'committee'
        priority = 'high' if amount > 10000 or days >= 14 else 'normal'
        result.append({'id': item['id'], 'requester': item['requester'], 'department': item['department'], 'category': item['category'], 'amount': amount, 'submitted': item['submitted'], 'status': item['status'], 'approver': approver, 'days_open': days, 'priority': priority})
    result.sort(key=lambda x: (0 if x['priority'] == 'high' else 1, -x['amount'], x['submitted'], x['id']))
    return result

def render_report(routed: list[dict]) -> str:
    out = ['<section class="approval-report">', '<h1>Procurement approvals</h1>', '<table>', '<thead><tr><th>ID</th><th>Requester</th><th>Department</th><th>Category</th><th>Amount</th><th>Submitted</th><th>Status</th><th>Approver</th><th>Days open</th><th>Priority</th></tr></thead>', '<tbody>']
