import datetime
import hashlib
import hmac
import json
import math

def summarize_memberships(payload: str, signature: str, secret: str, as_of: str, offset: int=0, limit: int=20) -> list[dict]:
    try:
        expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    except Exception:
        raise ValueError('invalid signature')
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        cutoff = datetime.date.fromisoformat(as_of)
    except Exception:
        raise ValueError('invalid date')
    if offset < 0 or limit <= 0:
        raise ValueError('invalid pagination')
    try:
        records = json.loads(payload)
        if not isinstance(records, list):
            raise ValueError
        groups = {}
        for record in records:
            if not isinstance(record, dict):
                raise ValueError
            member = record['member']
            club = record['club']
            joined_text = record['joined']
            active = record['active']
            dues = record['dues']
            if not isinstance(member, str) or not member or (not isinstance(club, str)) or (not club) or (not isinstance(joined_text, str)) or (not isinstance(active, bool)) or isinstance(dues, bool) or (not isinstance(dues, (int, float))) or (not math.isfinite(dues)) or (dues < 0):
                raise ValueError
            joined = datetime.date.fromisoformat(joined_text)
            if active and joined <= cutoff:
                groups.setdefault(club, {'total': 0.0, 'members': []})
                groups[club]['total'] += dues
                groups[club]['members'].append(member)
    except Exception:
        raise ValueError('invalid payload')
    result = []
    for club, data in groups.items():
        result.append({'club': club, 'count': len(data['members']), 'total_dues': round(data['total'], 2), 'members': sorted(data['members'])})
    result.sort(key=lambda item: (-item['count'], item['club']))
    return result[offset:offset + limit]

