import hashlib
import os
from datetime import datetime

def issue_session_record(pilot_id: str, password: str, simulator: str, started_at: str, duration_minutes: int, score: float) -> dict:
    if not isinstance(pilot_id, str) or not pilot_id or (not isinstance(password, str)) or (not password) or (not isinstance(simulator, str)) or (not simulator):
        raise ValueError('invalid text')
    try:
        datetime.fromisoformat(started_at)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if isinstance(duration_minutes, bool) or not isinstance(duration_minutes, int) or duration_minutes < 0:
        raise ValueError('invalid duration')
    if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100):
        raise ValueError('invalid score')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'pilot_id': pilot_id, 'simulator': simulator, 'started_at': started_at, 'duration_minutes': duration_minutes, 'score': score, 'password_hash': salt.hex() + '$' + digest.hex()}

def verify_session_record(record: dict, password: str) -> bool:
    if not isinstance(password, str):
        return False
    try:
        salt_text, digest_text = record['password_hash'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return len(expected) == len(actual) and __import__('hmac').compare_digest(actual, expected)
    except (KeyError, AttributeError, ValueError, TypeError):
        return False

def summarize_sessions(records: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    groups = {}
    for record in records:
        pilot = record['pilot_id']
        item = groups.setdefault(pilot, [0, 0, 0])
        item[0] += 1
        item[1] += record['duration_minutes']
        item[2] += record['score']
    result = [{'pilot_id': pilot, 'flight_count': v[0], 'total_minutes': v[1], 'average_score': round(v[2] / v[0], 2)} for pilot, v in groups.items()]
    result.sort(key=lambda x: (-x['total_minutes'], x['pilot_id']))
    start = (page - 1) * page_size
