from urllib.parse import quote
import requests

def summarize_transactions(payload: dict) -> list[dict]:
    if not isinstance(payload, dict):
        raise ValueError('payload must be an object')
    transactions = payload.get('transactions')
    if transactions is None:
        return []
    if not isinstance(transactions, list):
        raise ValueError('transactions must be a list')
    totals = {}
    seen = {}
    for tx in transactions:
        if not isinstance(tx, dict) or 'id' not in tx or 'cashier' not in tx or ('lines' not in tx):
            raise ValueError('invalid transaction')
        if tx.get('status') == 'void':
            continue
        if not isinstance(tx['lines'], list):
            raise ValueError('invalid lines')
        touched = set()
        for line in tx['lines']:
            if not isinstance(line, dict) or not all((k in line for k in ('sku', 'quantity', 'unit_price'))):
                raise ValueError('invalid line')
            quantity = line['quantity']
            if isinstance(quantity, bool) or not isinstance(quantity, int):
                raise ValueError('invalid quantity')
            try:
                price = Decimal(str(line['unit_price']))
                discount = Decimal(str(line.get('discount_percent', 0)))
            except (InvalidOperation, ValueError):
                raise ValueError('invalid decimal')
            if not price.is_finite() or not discount.is_finite() or discount < 0 or (discount > 100):
                raise ValueError('invalid decimal')
            key = (tx['cashier'], line['sku'])
            amount = Decimal(quantity) * price * (Decimal(100) - discount) / Decimal(100)
            if key not in totals:
                totals[key] = [0, Decimal(0)]
                seen[key] = set()
            totals[key][0] += quantity
            totals[key][1] += amount
            touched.add(key)
        for key in touched:
            seen[key].add(tx['id'])
    rows = []
    for key, value in totals.items():
        rows.append({'cashier': key[0], 'sku': key[1], 'quantity': value[0], 'sales_cents': int((value[1] * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP)), 'transaction_count': len(seen[key])})
    return sorted(rows, key=lambda r: (r['cashier'], -r['sales_cents'], r['sku']))

def fetch_sales_summary(store_id: str, business_date: str, api_key: str) -> list[dict]:
    response = requests.get('https://pos.example.test/v1/stores/' + quote(store_id, safe='') + '/sales', params={'date': business_date}, headers={'Authorization': 'Bearer ' + api_key}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed with status ' + str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    return summarize_transactions(payload)

