def _number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError('invalid measurement')
    if value < 0:
        raise ValueError('invalid measurement')
    return float(value)

def summarize_shipments(records, period):
    if not isinstance(period, str) or re.fullmatch('\\d{4}-\\d{2}', period) is None:
        raise ValueError('invalid period')
    groups = {}
    for record in records:
        try:
            date = record['date']
            route = record['route']
            mode = record['mode']
            distance = _number(record['distance_km'])
            fuel = _number(record['fuel_l'])
            co2 = _number(record['co2_kg'])
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(date, str) or not isinstance(route, str) or (not isinstance(mode, str)):
            raise ValueError('invalid record')
        try:
            parsed = datetime.date.fromisoformat(date)
        except ValueError:
            raise ValueError('invalid date')
        if parsed.strftime('%Y-%m') != period:
            continue
        key = (route, mode)
        item = groups.setdefault(key, [route, mode, 0.0, 0.0, 0.0, 0])
        item[2] += distance
        item[3] += fuel
        item[4] += co2
        item[5] += 1
    result = [{'route': x[0], 'mode': x[1], 'distance_km': round(x[2], 2), 'fuel_l': round(x[3], 2), 'co2_kg': round(x[4], 2), 'shipments': x[5]} for x in groups.values()]
    return sorted(result, key=lambda x: (-x['co2_kg'], x['route'], x['mode']))

