import tempfile

def export_inventory(items: list[dict], destination: str) -> int:
    if not isinstance(items, list):
        raise TypeError('items must be a list')
    fields = ('item_id', 'name', 'quantity', 'rarity')
    for item in items:
        if not isinstance(item, dict) or any((field not in item for field in fields)):
            raise ValueError('invalid item')
        if not all((isinstance(item[field], str) for field in ('item_id', 'name', 'rarity'))):
            raise ValueError('invalid item')
        if isinstance(item['quantity'], bool) or not isinstance(item['quantity'], int) or item['quantity'] < 0:
            raise ValueError('invalid item')
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.inventory-', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(fields)
            for item in items:
                writer.writerow([item[field] for field in fields])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(items)

