def _records(paths):
    result = subprocess.run(['cat', '--', *paths], check=True, capture_output=True, text=True)
    records = []
    for line in result.stdout.splitlines():
        fields = line.split('|')
        if len(fields) != 4:
            raise ValueError('malformed ballot')
        voter, timestamp, candidate, weight = fields
        if not voter or not candidate:
            raise ValueError('malformed ballot')
        try:
            timestamp = int(timestamp)
            weight = int(weight)
        except ValueError as exc:
            raise ValueError('malformed ballot') from exc
        if weight <= 0:
            raise ValueError('malformed ballot')
        records.append((voter, timestamp, candidate, weight))
    return records

def tally_ballots(paths: list[str], quorum: int) -> list[tuple[str, int]]:
    if quorum <= 0:
        raise ValueError('quorum must be positive')
    latest = {}
    for voter, timestamp, candidate, weight in _records(paths):
        old = latest.get(voter)
        if old is None or timestamp > old[0]:
            latest[voter] = (timestamp, candidate, weight)
    totals = {}
    for _, candidate, weight in latest.values():
        totals[candidate] = totals.get(candidate, 0) + weight
    answer = [(candidate, total) for candidate, total in totals.items() if total >= quorum]
    answer.sort(key=lambda item: (-item[1], item[0]))
    return answer

def winning_candidate(paths: list[str], quorum: int) -> str | None:
    result = tally_ballots(paths, quorum)
    return result[0][0] if result else None

