import math
import secrets

def generate_technician_code(length: int=8) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or (not 6 <= length <= 32):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def get_elevator_report(readings: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(readings, list):
        raise ValueError('readings must be a list')
    if any((isinstance(x, bool) or not isinstance(x, int) or x <= 0 for x in (page, page_size))):
        raise ValueError('invalid pagination')
    groups = {}
    for reading in readings:
        if not isinstance(reading, dict) or not all((k in reading for k in ('elevator', 'floor', 'load', 'status'))):
            raise ValueError('invalid reading')
        elevator = reading['elevator']
        floor = reading['floor']
        load = reading['load']
        status = reading['status']
        if not isinstance(elevator, str) or not elevator.strip():
            raise ValueError('invalid elevator')
        if isinstance(floor, bool) or not isinstance(floor, int):
            raise ValueError('invalid floor')
        if isinstance(load, bool) or not isinstance(load, (int, float)) or (not math.isfinite(load)) or (not 0 <= load <= 100):
            raise ValueError('invalid load')
        if status not in {'ok', 'maintenance', 'offline'}:
            raise ValueError('invalid status')
        if elevator not in groups:
            groups[elevator] = {'elevator': elevator, 'loads': [], 'floors': [], 'status': status}
        groups[elevator]['loads'].append(load)
        groups[elevator]['floors'].append(floor)
        groups[elevator]['status'] = status
    items = []
    for group in groups.values():
        items.append({'elevator': group['elevator'], 'count': len(group['loads']), 'average_load': round(sum(group['loads']) / len(group['loads']), 2), 'max_floor': max(group['floors']), 'status': group['status']})
    items.sort(key=lambda x: (-x['average_load'], x['elevator']))
    start = (page - 1) * page_size
    return {'total': len(items), 'page': page, 'page_size': page_size, 'items': items[start:start + page_size]}

