import ast

def rank_engine_health(records: list[dict], expression: str, minimum: float=0.0, limit: int | None=None) -> list[dict]:
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
        raise ValueError('invalid limit')
    try:
        tree = ast.parse(expression, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid expression') from exc

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in values:
                return values[node.id]
            raise ValueError('unknown name')
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, values)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left = evaluate(node.left, values)
            right = evaluate(node.right, values)
            if isinstance(node.op, ast.Add):
                return left + right
            if isinstance(node.op, ast.Sub):
                return left - right
            if isinstance(node.op, ast.Mult):
                return left * right
            return left / right
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = evaluate(node.values[0], values)
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = evaluate(part, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for op, item in zip(node.ops, node.comparators):
                right = evaluate(item, values)
                if isinstance(op, ast.Lt):
                    ok = left < right
                elif isinstance(op, ast.LtE):
                    ok = left <= right
                elif isinstance(op, ast.Gt):
                    ok = left > right
                elif isinstance(op, ast.GtE):
                    ok = left >= right
                elif isinstance(op, ast.Eq):
                    ok = left == right
                elif isinstance(op, ast.NotEq):
                    ok = left != right
                else:
                    raise ValueError('invalid comparison')
                if not ok:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            args = [evaluate(arg, values) for arg in node.args]
            if node.func.id == 'round' and len(args) in (1, 2):
                return round(*args)
            if node.func.id == 'min' and len(args) >= 2:
                return min(args)
            if node.func.id == 'max' and len(args) >= 2:
                return max(args)
        raise ValueError('invalid expression')
    result = []
    for record in records:
        try:
            values = {key: record[key] for key in ('cycles', 'vibration', 'exhaust_temp', 'oil_pressure')}
            score = evaluate(tree, values)
            if not isinstance(score, (int, float)) or isinstance(score, complex):
                raise ValueError('non-numeric score')
            if score >= minimum:
                result.append({'engine_id': record['engine_id'], 'score': score})
        except Exception as exc:
            raise ValueError('invalid record or expression') from exc
    result.sort(key=lambda item: (-item['score'], item['engine_id']))
    return result if limit is None else result[:limit]

