def parse_play_log(text: str) -> list[dict]:
    out = []
    for raw in text.splitlines():
        if not raw:
            continue
        fields, current, escaped = ([], [], False)
        for ch in raw:
            if escaped:
                current.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        if escaped:
            raise ValueError('unterminated escape')
        fields.append(''.join(current))
        if len(fields) != 5 or not fields[0] or (not fields[1]):
            raise ValueError('invalid play')
        try:
            streams = int(fields[4])
        except ValueError:
            raise ValueError('invalid streams')
        if streams < 0:
            raise ValueError('invalid streams')
        out.append(dict(zip(('play_id', 'track_id', 'country', 'started_at'), fields[:4]), streams=streams))
    return out

def calculate_statement(requester: dict, account_id: str, accounts: dict[str, dict], plays: list[dict], rates: dict[str, int], adjustments: list[dict], period_start: str, period_end: str) -> dict:
    if account_id not in accounts:
        raise KeyError(account_id)
    if period_start >= period_end:
        raise ValueError('invalid period')
    account = accounts[account_id]
    roles = requester.get('roles', [])
    if requester.get('id') != account.get('owner_id') and ('royalty_admin' not in roles or requester.get('tenant_id') != account.get('tenant_id')):
        raise PermissionError('not authorized')
    seen = set()
    totals = {}
    for play in plays:
        try:
            pid, track, country, started, streams = (play[k] for k in ('play_id', 'track_id', 'country', 'started_at', 'streams'))
            if not isinstance(streams, int) or streams < 0 or (not track) or (not pid):
                raise ValueError
        except (KeyError, TypeError):
            raise ValueError('invalid play')
        if pid in seen:
            raise ValueError('duplicate play')
        seen.add(pid)
        if period_start <= started < period_end and streams:
            if country not in rates:
                raise KeyError(country)
            item = totals.setdefault(track, [0, 0])
            item[0] += streams
            item[1] += streams * rates[country]
    result_adjustments = []
    references = set()
    for item in adjustments:
        try:
            if item['account_id'] != account_id or item['reference'] in references or (not isinstance(item['cents'], int)):
                raise ValueError
            references.add(item['reference'])
            result_adjustments.append({'reference': item['reference'], 'cents': item['cents']})
        except (KeyError, TypeError):
            raise ValueError('invalid adjustment')
    tracks = [{'track_id': k, 'streams': v[0], 'cents': v[1]} for k, v in totals.items()]
    tracks.sort(key=lambda x: (-x['cents'], x['track_id']))
    total = sum((x['cents'] for x in tracks)) + sum((x['cents'] for x in result_adjustments))
    return {'account_id': account_id, 'period': {'start': period_start, 'end': period_end}, 'tracks': tracks, 'adjustments': result_adjustments, 'total_cents': total}

