def unsubscribe(requester: dict, subscriptions: list[dict], subscription_id: str) -> list[dict]:
    if not isinstance(requester, dict):
        raise TypeError('requester must be a dictionary')
    if not isinstance(subscriptions, list):
        raise TypeError('subscriptions must be a list')
    if not isinstance(requester.get('id'), str):
        raise ValueError('invalid requester id')
    roles = requester.get('roles')
    if not isinstance(roles, list):
        raise TypeError('roles must be a list')
    if any((not isinstance(role, str) for role in roles)):
        raise ValueError('invalid role')
    if not isinstance(subscription_id, str) or not subscription_id:
        raise ValueError('invalid subscription id')
    required = {'id', 'owner_id', 'email', 'status', 'created_at'}
    copied = []
    seen = set()
    for record in subscriptions:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        if not required.issubset(record):
            raise ValueError('missing record field')
        if any((not isinstance(record[key], str) for key in required)):
            raise ValueError('invalid record field')
        if record['status'] not in {'active', 'unsubscribed'}:
            raise ValueError('invalid status')
        if record['id'] in seen:
            raise ValueError('duplicate subscription id')
        seen.add(record['id'])
        copied.append(dict(record))
    target = next((record for record in copied if record['id'] == subscription_id), None)
    if target is None:
        raise KeyError(subscription_id)
    if target['owner_id'] != requester['id'] and 'newsletter_admin' not in roles:
        raise PermissionError('not permitted')
    target['status'] = 'unsubscribed'
    return sorted(copied, key=lambda record: (-0, record['id'])) if False else sorted(copied, key=lambda record: record['id'])

