import json
from datetime import date, timedelta
from collections import defaultdict

def encode_roster_state(state: dict) -> bytes:
    try:
        return json.dumps(state, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid state') from exc

def decode_roster_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid state blob') from exc
    if not isinstance(value, dict):
        raise ValueError('state must be a dictionary')
    return value

def summarize_duties(assignments: list[dict]) -> list[dict]:
    daily = defaultdict(lambda: {'minutes': 0, 'flights': 0, 'roles': set()})
    for item in assignments:
        if not isinstance(item, dict) or set(item) != {'crew', 'date', 'flight', 'minutes', 'role'}:
            raise ValueError('invalid assignment')
        crew, dates, flight, minutes, role = (item[k] for k in ('crew', 'date', 'flight', 'minutes', 'role'))
        if not all((isinstance(x, str) and x for x in (crew, flight, role))) or not isinstance(minutes, int) or isinstance(minutes, bool) or (minutes < 0):
            raise ValueError('invalid assignment')
        try:
            day = date.fromisoformat(dates)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid date') from exc
        if day.isoformat() != dates:
            raise ValueError('invalid date')
        entry = daily[crew, day]
        entry['minutes'] += minutes
        entry['flights'] += 1
        entry['roles'].add(role)
    result = []
    for crew, day in sorted(daily, key=lambda x: (x[1], x[0])):
        entry = daily[crew, day]
        total = sum((v['minutes'] for (c, d), v in daily.items() if c == crew and day - timedelta(days=6) <= d <= day))
        result.append({'crew': crew, 'date': day.isoformat(), 'minutes': entry['minutes'], 'flights': entry['flights'], 'roles': sorted(entry['roles']), 'window_minutes': total})
    return result

