from decimal import Decimal, ROUND_HALF_UP

def plan_replenishment(requester: dict, warehouse: dict, inventory: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid pagination')
    if not isinstance(requester, dict) or not isinstance(warehouse, dict) or (not all((k in requester for k in ('id', 'tenant_id', 'roles')))) or (not all((k in warehouse for k in ('id', 'tenant_id', 'owner_id')))) or (not isinstance(requester['roles'], list)):
        raise ValueError('invalid parties')
    if not (requester['id'] == warehouse['owner_id'] or (requester['tenant_id'] == warehouse['tenant_id'] and 'inventory_manager' in requester['roles'])):
        raise PermissionError('not permitted')
    if not isinstance(inventory, list):
        raise ValueError('invalid inventory')
    rows = []
    for r in inventory:
        if not isinstance(r, dict) or not all((k in r for k in ('sku', 'on_hand', 'reorder_point', 'target_level', 'unit_cost'))) or (not isinstance(r['sku'], str)):
            raise ValueError('invalid record')
        vals = [r[k] for k in ('on_hand', 'reorder_point', 'target_level', 'unit_cost')]
        if any((isinstance(v, bool) or not isinstance(v, (int, float)) or v < 0 for v in vals)) or r['target_level'] < r['reorder_point'] or r['target_level'] < r['on_hand']:
            raise ValueError('invalid values')
        if r['on_hand'] < r['reorder_point']:
            q = r['target_level'] - r['on_hand']
            line = float((Decimal(str(q)) * Decimal(str(r['unit_cost']))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
            rows.append({'sku': r['sku'], 'quantity': q, 'unit_cost': r['unit_cost'], 'line_total': line, 'shortage': r['reorder_point'] - r['on_hand']})
    rows.sort(key=lambda x: (-x['shortage'], x['sku']))
    total = len(rows)
    if page > max(1, (total + page_size - 1) // page_size):
        raise ValueError('page out of range')
    cost = float(sum((Decimal(str(x['line_total'])) for x in rows), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    start = (page - 1) * page_size
    return {'warehouse_id': warehouse['id'], 'items': rows[start:start + page_size], 'total_items': total, 'total_cost': cost}

