def encode_workflow(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def decode_workflow(blob: bytes, desk: str | None=None, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    try:
        articles = json.loads(blob.decode('utf-8'))
        if not isinstance(articles, list):
            raise ValueError('articles must be a list')
        fields = {'id', 'title', 'desk', 'status', 'word_count', 'updated_at'}
        if any((not isinstance(article, dict) or not fields.issubset(article) for article in articles)):
            raise ValueError('invalid article')
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid payload') from exc
    selected = [article for article in articles if (desk is None or article['desk'] == desk) and (status is None or article['status'] == status)]
    selected.sort(key=lambda article: (-1, article['id']))
    selected.sort(key=lambda article: article['updated_at'], reverse=True)
    total = len(selected)
    start = (page - 1) * page_size
    pages = (total + page_size - 1) // page_size if total else 0
    return {'total': total, 'pages': pages, 'page': page, 'items': selected[start:start + page_size], 'word_count': sum((article['word_count'] for article in selected))}

