import base64
import hashlib
import hmac
import os

def _validate_pin(access_pin: str) -> None:
    if not access_pin.isdigit() or not 4 <= len(access_pin) <= 12:
        raise ValueError('access_pin must contain 4 to 12 digits')

def log_voyage(vessel: str, ports: list[str], access_pin: str) -> dict[str, object]:
    _validate_pin(access_pin)
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_pin.encode(), salt, 100000)
    stored_pin = base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()
    return {'vessel': vessel, 'ports': sorted(set(ports)), 'pin': stored_pin}

def verify_voyage_pin(access_pin: str, voyage: dict[str, object]) -> bool:
    stored = voyage.get('pin')
    if not isinstance(stored, str) or stored.count('$') != 1:
        return False
    try:
        salt_text, digest_text = stored.split('$')
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', access_pin.encode(), salt, 100000)
    except (ValueError, TypeError):
        return False
    return hmac.compare_digest(actual, expected)

