import ast

def rank_shifts(shifts: list[dict], formula: str, variables: dict[str, int | float]) -> list[tuple[str, int | float]]:
    tree = ast.parse(formula, mode='eval').body

    def ev(n, env):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.Name):
            if n.id not in env:
                raise NameError(n.id)
            return env[n.id]
        if isinstance(n, ast.BinOp):
            a, b = (ev(n.left, env), ev(n.right, env))
            if isinstance(n.op, ast.Add):
                return a + b
            if isinstance(n.op, ast.Sub):
                return a - b
            if isinstance(n.op, ast.Mult):
                return a * b
            if isinstance(n.op, ast.Div):
                return a / b
        if isinstance(n, ast.UnaryOp):
            x = ev(n.operand, env)
            if isinstance(n.op, ast.UAdd):
                return +x
            if isinstance(n.op, ast.USub):
                return -x
            if isinstance(n.op, ast.Not):
                return not x
        if isinstance(n, ast.BoolOp):
            values = [ev(x, env) for x in n.values]
            if isinstance(n.op, ast.And):
                return all(values)
            return next((x for x in values if x), values[-1])
        if isinstance(n, ast.Compare):
            left = ev(n.left, env)
            for op, right_node in zip(n.ops, n.comparators):
                right = ev(right_node, env)
                ok = left == right if isinstance(op, ast.Eq) else left != right if isinstance(op, ast.NotEq) else left < right if isinstance(op, ast.Lt) else left <= right if isinstance(op, ast.LtE) else left > right if isinstance(op, ast.Gt) else left >= right
                if not ok:
                    return False
                left = right
            return True
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
            return {'min': min, 'max': max, 'round': round}[n.func.id](*[ev(x, env) for x in n.args])
        raise ValueError('unsupported expression')
    result = []
    for index, shift in enumerate(shifts):
        env = dict(variables)
        env.update(shift)
        score = ev(tree, env)
        if score > 0:
            result.append((shift['id'], score, index))
    result.sort(key=lambda x: (-x[1], x[2]))
    return [(item[0], item[1]) for item in result]

