import csv
import io
import os
import zipfile
from datetime import datetime

def _read_csv(data, totals):
    rows = csv.reader(io.StringIO(data.decode('utf-8')))
    header = next(rows, None)
    expected = ['sku', 'pharmacy', 'quantity', 'recorded_at']
    if header != expected:
        raise ValueError('invalid header')
    for row in rows:
        if not row:
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        sku, pharmacy, quantity, recorded = (part.strip() for part in row)
        if not sku or not pharmacy:
            raise ValueError('empty field')
        try:
            amount = int(quantity, 10)
            if amount < 0:
                raise ValueError
            datetime.fromisoformat(recorded)
        except (TypeError, ValueError):
            raise ValueError('invalid value')
        key = (sku, pharmacy)
        if key not in totals:
            totals[key] = [amount, recorded]
        else:
            totals[key][0] += amount
            if recorded > totals[key][1]:
                totals[key][1] = recorded

def summarize_inventory_archive(archive_path: str, base_dir: str) -> list[dict[str, object]]:
    root = os.path.realpath(base_dir)
    totals = {}
    try:
        with zipfile.ZipFile(archive_path) as archive:
            for member in archive.infolist():
                target = os.path.realpath(os.path.join(root, member.filename))
                if os.path.commonpath((root, target)) != root:
                    raise ValueError('invalid archive member')
                if member.is_dir():
                    os.makedirs(target, exist_ok=True)
                    continue
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with open(target, 'wb') as output:
                    output.write(archive.read(member))
                if member.filename.lower().endswith('.csv'):
                    with open(target, 'rb') as source:
                        _read_csv(source.read(), totals)
    except (zipfile.BadZipFile, OSError, UnicodeDecodeError, KeyError) as exc:
        raise ValueError('invalid archive') from exc
    return [{'sku': sku, 'pharmacy': pharmacy, 'quantity': value[0], 'latest_recorded_at': value[1]} for (sku, pharmacy), value in sorted(totals.items())]

