def build_access_report(base_dir: str, relative_name: str, events: list[dict], page: int=1, page_size: int=10) -> str:
    if isinstance(page, bool) or isinstance(page_size, bool) or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    groups = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        badge = event.get('badge')
        door = event.get('door')
        granted = event.get('granted')
        timestamp = event.get('timestamp')
        if not isinstance(badge, str) or not badge or (not isinstance(door, str)) or (not door):
            raise ValueError('invalid event')
        if not isinstance(granted, bool) or not isinstance(timestamp, str):
            raise ValueError('invalid event')
        try:
            parsed = datetime.fromisoformat(timestamp)
        except ValueError:
            raise ValueError('invalid event')
        if badge not in groups:
            groups[badge] = {'badge': badge, 'total': 0, 'granted': 0, 'denied': 0, 'last_event': timestamp, 'latest': parsed}
        item = groups[badge]
        item['total'] += 1
        item['granted' if granted else 'denied'] += 1
        if parsed > item['latest']:
            item['latest'] = parsed
            item['last_event'] = timestamp
    for item in groups.values():
        item.pop('latest')
    ordered = sorted(groups.values(), key=lambda x: (-x['denied'], x['badge']))
    start = (page - 1) * page_size
    result = {'page': page, 'page_size': page_size, 'total_badges': len(ordered), 'results': ordered[start:start + page_size]}
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, target]) != base:
        raise ValueError('invalid output name')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        json.dump(result, handle, indent=2)
        handle.write('\n')
    return target

