import csv
import os
import tempfile
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP

def create_staffing_export(assignments: list[dict], week_start: str, destination: str) -> dict:
    try:
        start = date.fromisoformat(week_start)
    except (TypeError, ValueError):
        raise ValueError('invalid week_start')
    if start.weekday() != 0:
        raise ValueError('week_start must be Monday')
    end = start + timedelta(days=6)
    grouped = {}
    for item in assignments:
        try:
            worker = item['worker']
            day = date.fromisoformat(item['date'])
            hours = Decimal(str(item['hours']))
            rate = Decimal(str(item['rate']))
            status = item['status']
        except (KeyError, TypeError, ValueError, ArithmeticError):
            raise ValueError('invalid assignment')
        if not isinstance(worker, str) or not worker or status not in ('confirmed', 'cancelled'):
            raise ValueError('invalid assignment')
        if not hours.is_finite() or not rate.is_finite() or hours < 0 or (rate < 0):
            raise ValueError('invalid assignment')
        if status == 'confirmed' and start <= day <= end:
            entry = grouped.setdefault(worker, {'days': 0, 'hours': Decimal('0'), 'gross': Decimal('0')})
            entry['days'] += 1
            entry['hours'] += hours
            entry['gross'] += hours * rate
    rows = []
    for worker, values in grouped.items():
        hours = values['hours'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        gross = values['gross'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append((worker, values['days'], hours, gross))
    rows.sort(key=lambda row: (-row[3], row[0]))
    folder = os.path.dirname(os.path.abspath(destination)) or '.'
    fd, temporary = tempfile.mkstemp(dir=folder, prefix='staffing-', suffix='.csv')
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.writer(stream)
            writer.writerow(['worker', 'days', 'hours', 'gross_pay'])
            for worker, days, hours, gross in rows:
                writer.writerow([worker, days, f'{hours:.2f}', f'{gross:.2f}'])
        os.replace(temporary, destination)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    total_hours = sum((row[2] for row in rows), Decimal('0'))
    total_gross = sum((row[3] for row in rows), Decimal('0'))
    return {'workers': len(rows), 'hours': float(total_hours), 'gross_pay': float(total_gross)}

