            "variants": {
                "control": 1,
                "new_button": 2,
                "compact_flow": 1,
            }
        }
    }


def expected(users, key, experiment, variants):
    total = sum(variants.values())
    result = []
    for user in sorted(users):
        message = (experiment + ":" + user).encode()
        digest = hmac.new(key.encode(), message, hashlib.sha256).digest()
        point = int.from_bytes(digest[:8], "big") % total
        running = 0
        for name, weight in variants.items():
            running += weight
            if point < running:
                result.append((user, name))
                break
    return result


def test_assignments_are_stable_and_sorted():
