    config = make_config()
    with patch.dict(os.environ, {"EXPERIMENT_ASSIGNMENT_KEY": "test-key"}):
        actual = assign_variants(users, "checkout", config)
    assert actual == expected(users, "test-key", "checkout", config["checkout"]["variants"])
