def assign_variants(user_ids: list[str], experiment: str, config: dict, offset: int=0, limit: int | None=None) -> list[tuple[str, str]]:
    if not isinstance(user_ids, list) or any((not isinstance(x, str) or not x for x in user_ids)):
        raise ValueError('user_ids must be a list of non-empty strings')
    if len(set(user_ids)) != len(user_ids):
        raise ValueError('user_ids must be unique')
    if not isinstance(experiment, str) or not experiment:
        raise ValueError('experiment must be a non-empty string')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
