        raise ValueError('limit must be non-negative or None')
    try:
        variants = config[experiment]['variants']
    except (KeyError, TypeError):
        raise ValueError('invalid experiment configuration')
    if not isinstance(variants, dict) or not variants:
        raise ValueError('invalid variants')
    for name, weight in variants.items():
        if not isinstance(name, str) or not name or isinstance(weight, bool) or (not isinstance(weight, int)) or (weight <= 0):
            raise ValueError('invalid variant weight')
    key = os.environ.get('EXPERIMENT_ASSIGNMENT_KEY')
    if key is None:
        raise RuntimeError('EXPERIMENT_ASSIGNMENT_KEY is not set')
    total = sum(variants.values())
    ordered = []
    for user in sorted(user_ids):
        message = (experiment + ':' + user).encode()
        digest = hmac.new(key.encode(), message, hashlib.sha256).digest()
        point = int.from_bytes(digest[:8], 'big') % total
        running = 0
        for name, weight in variants.items():
            running += weight
            if point < running:
                ordered.append((user, name))
                break
    end = None if limit is None else offset + limit
    return ordered[offset:end]

