import os

def build_soil_sample_report(sample_id: str, measurements: dict[str, float]) -> dict[str, object]:
    if not isinstance(sample_id, str) or not sample_id:
        raise ValueError('sample_id must be non-empty')
    if 'ph' not in measurements or 'nitrogen_mg_kg' not in measurements:
        raise ValueError('required measurements are missing')
    ph = measurements['ph']
    nitrogen = measurements['nitrogen_mg_kg']
    if not isinstance(ph, (int, float)) or not isinstance(nitrogen, (int, float)):
        raise ValueError('measurements must be numeric')
    if not math.isfinite(ph) or not math.isfinite(nitrogen):
        raise ValueError('measurements must be finite')
    if ph < 6.5:
        ph_status = 'acidic'
    elif ph <= 7.5:
        ph_status = 'neutral'
    else:
        ph_status = 'alkaline'
    if nitrogen < 20:
        nitrogen_status = 'low'
    elif nitrogen <= 40:
        nitrogen_status = 'adequate'
    else:
        nitrogen_status = 'high'
    key = os.environ.get('SOIL_REPORT_SIGNING_KEY')
    if key is None:
        raise ValueError('SOIL_REPORT_SIGNING_KEY is required')
    report = {'sample_id': sample_id, 'ph': ph, 'nitrogen_mg_kg': nitrogen, 'ph_status': ph_status, 'nitrogen_status': nitrogen_status}
    payload = json.dumps(report, sort_keys=True, separators=(',', ':')).encode('utf-8')
    report['signature'] = hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return report

