import ast
import math

def rank_meters(records: list[dict], expression: str, limit: int) -> list[str]:
    if limit < 0:
        raise ValueError('invalid limit')
    try:
        tree = ast.parse(expression, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid expression') from exc
    allowed = {'kwh', 'peak_kw', 'days'}
    funcs = {'min': min, 'max': max, 'round': round}

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float):
            return node.value
        if isinstance(node, ast.Name) and node.id in allowed:
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a, b = (evaluate(node.left, values), evaluate(node.right, values))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            vals = [evaluate(x, values) for x in node.values]
            return all(vals) if isinstance(node.op, ast.And) else any(vals)
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for op, comp in zip(node.ops, node.comparators):
                right = evaluate(comp, values)
                if not {ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right, ast.Eq: left == right, ast.NotEq: left != right}[type(op)]:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in funcs) and (not node.keywords):
            return funcs[node.func.id](*(evaluate(x, values) for x in node.args))
        raise ValueError('unsupported expression')
    scored = []
    for record in records:
        values = {name: record[name] for name in allowed}
        try:
            score = evaluate(tree, values)
            if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)):
                raise ValueError('invalid score')
        except Exception as exc:
            if isinstance(exc, KeyError):
                raise
            raise ValueError('invalid expression') from exc
        scored.append((score, record['meter_id']))
    scored.sort(key=lambda item: (-item[0], item[1]))
    return [meter_id for _, meter_id in scored[:limit]]

