        start = datetime.strptime(item['window_start'], '%Y-%m-%dT%H:%M:%SZ')
        end = datetime.strptime(item['window_end'], '%Y-%m-%dT%H:%M:%SZ')
        duration = int((end - start).total_seconds() // 60)
