    if event['event_id'] in events:
        raise ValueError('duplicate event')
    pid, kind, data = (event['participant_id'], event['kind'], event['data'])
    old = participants.get(pid)
    if kind == 'enroll':
        if old is not None or set(data) != {'site', 'consent'} or (not isinstance(data['site'], str)) or (not data['site']) or (not isinstance(data['consent'], bool)):
            raise ValueError('invalid enrollment')
        record = {'site': data['site'], 'consent': data['consent'], 'status': 'active', 'visits': []}
    elif kind == 'visit':
        if old is None or old['status'] != 'active' or set(data) != {'visit_number', 'outcome'} or (type(data['visit_number']) is not int) or (not 1 <= data['visit_number'] <= 20) or (data['outcome'] not in ('pending', 'completed', 'missed')) or (old['visits'] and data['visit_number'] <= old['visits'][-1]['number']):
            raise ValueError('invalid visit')
