        if old is None or old['status'] != 'active' or data != {}:
            raise ValueError('invalid withdrawal')
        record = dict(old)
        record['status'] = 'withdrawn'
    else:
        raise ValueError('invalid event')
    participants[pid] = record
    events.add(event['event_id'])

def trial_report(state: dict) -> list[dict]:
    if not isinstance(state, dict) or not isinstance(state.get('participants'), dict):
        raise ValueError('invalid state')
    out = []
    for pid, r in state['participants'].items():
        if not isinstance(pid, str) or not isinstance(r, dict) or set(r) != {'site', 'consent', 'status', 'visits'} or (not isinstance(r['site'], str)) or (r['status'] not in ('active', 'withdrawn')) or (not isinstance(r['visits'], list)):
