        visits = r['visits']
        if any((not isinstance(v, dict) or set(v) != {'date', 'number', 'outcome'} for v in visits)):
            raise ValueError('invalid state')
        out.append({'participant_id': pid, 'site': r['site'], 'status': r['status'], 'visit_count': len(visits), 'completed_visits': sum((v['outcome'] == 'completed' for v in visits)), 'last_visit': visits[-1]['date'] if visits else None})
    return sorted(out, key=lambda x: (x['site'], x['participant_id']))

