        donations = []
        for node in root.findall('donation'):
            donations.append({'donor': node.attrib['donor'], 'amount': float(node.attrib['amount'])})
        donations.sort(key=lambda item: item['amount'], reverse=True)
        return {'name': root.attrib['name'], 'goal': float(goal_node.text), 'donations': donations}
