import xml.sax.handler

class _CampaignHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.name = None
        self.goal_text = ''
        self.current_goal = False
        self.donations = []

    def startElement(self, name, attrs):
        if name == 'campaign':
            self.name = attrs['name']
        elif name == 'goal':
            self.current_goal = True
        elif name == 'donation':
            self.donations.append({'donor': attrs['donor'], 'amount': float(attrs['amount'])})

    def characters(self, content):
        if self.current_goal:
            self.goal_text += content

    def endElement(self, name):
        if name == 'goal':
            self.current_goal = False

def parse_campaign(xml_text: str) -> dict:
    handler = _CampaignHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
        if handler.name is None or not handler.goal_text.strip():
            raise ValueError
        donations = sorted(handler.donations, key=lambda item: item['amount'], reverse=True)
        return {'name': handler.name, 'goal': float(handler.goal_text), 'donations': donations}
    except (xml.sax.SAXException, KeyError, TypeError, ValueError) as exc:
        raise ValueError('invalid campaign XML') from exc

