from lxml import etree
from datetime import date

def _number(value):
    try:
        result = float(value)
    except (TypeError, ValueError):
        raise ValueError('invalid number')
    if result < 0:
        raise ValueError('negative number')
    return result

def _day(value):
    try:
        date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if len(value) != 10:
        raise ValueError('invalid date')
    return value

def parse_progress_report(xml: str) -> dict:
    try:
        root = etree.fromstring(xml.encode(), etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'report' or (root.text and root.text.strip()):
        raise ValueError('invalid report')
    project = root.get('project')
    as_of = root.get('as_of')
    if project is None or as_of is None:
        raise ValueError('missing report attribute')
    _day(as_of)
    groups = [x for x in root if x.tag == 'activities']
    if len(groups) != 1 or len(root) != 1 or (groups[0].tail and groups[0].tail.strip()):
        raise ValueError('invalid activities')
    result, seen = ([], set())
    for node in groups[0]:
        if node.tag != 'activity' or (node.tail and node.tail.strip()):
            raise ValueError('invalid activity')
        keys = ('id', 'name', 'status', 'planned', 'actual')
        if any((node.get(k) is None for k in keys)) or node.get('id') in seen:
            raise ValueError('invalid activity attributes')
        if node.get('status') not in ('planned', 'in_progress', 'complete'):
            raise ValueError('invalid status')
        if node.text and node.text.strip():
            raise ValueError('unexpected text')
        seen.add(node.get('id'))
        hours = []
        for h in node:
            if h.tag != 'hours' or (h.text and h.text.strip()) or (h.tail and h.tail.strip()):
                raise ValueError('invalid hours')
            if h.get('date') is None or h.get('value') is None:
                raise ValueError('missing hours attribute')
            hours.append({'date': _day(h.get('date')), 'value': _number(h.get('value'))})
        result.append({'id': node.get('id'), 'name': node.get('name'), 'status': node.get('status'), 'planned': _number(node.get('planned')), 'actual': _number(node.get('actual')), 'hours': hours})
    return {'project': project, 'as_of': as_of, 'activities': result}

def summarize_progress(xml: str) -> dict:
    report = parse_progress_report(xml)
    planned = round(sum((a['planned'] for a in report['activities'])), 2)
    actual = round(sum((a['actual'] for a in report['activities'])), 2)
    daily = {}
    counts = {s: 0 for s in ('planned', 'in_progress', 'complete')}
    for activity in report['activities']:
        counts[activity['status']] += 1
        for hour in activity['hours']:
            daily[hour['date']] = daily.get(hour['date'], 0.0) + hour['value']
    daily = {k: round(daily[k], 2) for k in sorted(daily)}
    percent = round(actual / planned * 100, 2) if planned else 0.0
