            score = review['score']
            review_date = review['review_date']
        except KeyError as exc:
            raise ValueError('missing review field') from exc
        if not isinstance(employee, str) or not employee:
            raise ValueError('invalid employee')
        if not isinstance(department, str) or not department:
            raise ValueError('invalid department')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)) or (not 0 <= score <= 100):
            raise ValueError('invalid score')
        if not isinstance(review_date, str):
            raise ValueError('invalid date')
        try:
            parsed_date = datetime.date.fromisoformat(review_date)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if score >= min_score:
            item = grouped.setdefault(department, {'employees': set(), 'scores': [], 'latest': parsed_date})
            item['employees'].add(employee)
            item['scores'].append(score)
            if parsed_date > item['latest']:
                item['latest'] = parsed_date
    rows = []
    for department, item in grouped.items():
        average = round(sum(item['scores']) / len(item['scores']), 2)
        rows.append((department, len(item['employees']), average, item['latest'].isoformat()))
