        with os.fdopen(descriptor, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['department', 'employee_count', 'average_score', 'latest_review'])
            for department, count, average, latest in rows:
                writer.writerow([department, count, f'{average:.2f}', latest])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.close(descriptor)
        except OSError:
            pass
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(rows)

