import csv
import io
import re
from datetime import datetime

def parse_attendees(text: str) -> dict[str, dict[str, str]]:
    if not text:
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as exc:
        raise ValueError('malformed csv') from exc
    if not rows or rows[0] != ['attendee_id', 'name', 'ticket_type']:
        raise ValueError('invalid header')
    result = {}
    for row in rows[1:]:
        if len(row) != 3 or any((not value for value in row)):
            raise ValueError('invalid row')
        ident, name, ticket = row
        if ident in result:
            raise ValueError('duplicate attendee')
        result[ident] = {'name': name, 'ticket_type': ticket, 'checked_in_at': None}
    return result

def _timestamp(value: str) -> str:
    if not re.fullmatch('\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(?:\\.\\d{1,6})?Z', value):
        raise ValueError('invalid timestamp')
    raw = value[:-1]
    parsed = datetime.fromisoformat(raw)
    if parsed.microsecond:
        return parsed.strftime('%Y-%m-%dT%H:%M:%S.%f').rstrip('0') + 'Z'
    return parsed.strftime('%Y-%m-%dT%H:%M:%SZ')

def check_in(event: dict, attendee_id: str, requester: dict, checked_in_at: str) -> dict:
    if requester.get('tenant_id') != event.get('tenant_id'):
        raise PermissionError('not permitted')
    if requester.get('id') != event.get('organizer_id') and 'checkin_manager' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    attendees = event.get('attendees')
    if not isinstance(attendees, dict) or attendee_id not in attendees:
        raise ValueError('unknown attendee')
    person = attendees[attendee_id]
    stamp = _timestamp(checked_in_at)
    if person.get('checked_in_at') is not None:
        raise ValueError('already checked in')
    person['checked_in_at'] = stamp
    return {'event_id': event['id'], 'attendee_id': attendee_id, 'name': person['name'], 'ticket_type': person['ticket_type'], 'checked_in_at': stamp}

def attendance_summary(event: dict) -> dict:
    attendees = event.get('attendees')
    if not isinstance(attendees, dict):
        raise ValueError('invalid attendees')
    counts = {}
    checked = []
    for ident, person in attendees.items():
        if not all((key in person for key in ('name', 'ticket_type', 'checked_in_at'))):
            raise ValueError('invalid attendee')
        counts[person['ticket_type']] = counts.get(person['ticket_type'], 0) + 1
        if person['checked_in_at'] is not None:
            checked.append((person['checked_in_at'], ident))
    checked.sort(key=lambda item: (-datetime.fromisoformat(item[0][:-1]).timestamp(), item[1]))
    return {'total': len(attendees), 'checked_in': len(checked), 'by_ticket_type': dict(sorted(counts.items())), 'latest': [ident for _, ident in checked]}

