import hashlib
import hmac
import os

def create_subscription(email: str, password: str, plan: str) -> dict:
    if plan not in {'monthly', 'annual'}:
        raise ValueError('unsupported plan')
    if not password:
        raise ValueError('password must not be empty')
    normalized_email = email.strip().lower()
    monthly_cents = 1200 if plan == 'monthly' else 12000
    salt = os.urandom(16)
    derived = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    password_hash = salt.hex() + '$' + derived.hex()
    return {'email': normalized_email, 'plan': plan, 'monthly_cents': monthly_cents, 'password_hash': password_hash}

def authenticate_subscription(subscription: dict, password: str) -> bool:
    try:
        salt_text, digest_text = subscription['password_hash'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (KeyError, ValueError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

