import hmac
import json
import math

def summarize_signed(payload: str, signature: str, key: bytes, year_start: int=2000, year_end: int=2100) -> dict:
    if not isinstance(signature, str) or len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError('invalid signature')
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    if type(year_start) is not int or type(year_end) is not int or (not (2000 <= year_start <= 2100 and 2000 <= year_end <= 2100 and (year_start <= year_end))):
        raise ValueError('invalid bounds')
    try:
        records = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid payload')
    groups = {}
    count = 0
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        project = record.get('project')
        category = record.get('category')
        year = record.get('year')
        amount = record.get('kg_co2e')
        if not isinstance(project, str) or not project or (not isinstance(category, str)) or (not category) or (type(year) is not int) or (not 2000 <= year <= 2100) or isinstance(amount, bool) or (not isinstance(amount, (int, float))) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid record')
        if year_start <= year <= year_end:
            count += 1
            groups[category] = groups.get(category, 0) + amount
    items = [{'category': category, 'kg_co2e': round(amount, 3)} for category, amount in groups.items()]
    items.sort(key=lambda item: (-item['kg_co2e'], item['category']))
    return {'count': count, 'total_kg_co2e': round(sum(groups.values()), 3), 'by_category': items}

