import json

def encode_downloads(records: list[dict]) -> bytes:
    try:
        return json.dumps(records, separators=(',', ':')).encode('utf-8')
    except Exception as exc:
        raise ValueError('invalid records') from exc

def build_download_report(blob: bytes, package: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(package, str) or not package:
        raise ValueError('invalid package')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        records = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('package'), str) or not isinstance(record.get('version'), str):
            raise ValueError('invalid record')
        count = record.get('downloads')
        if isinstance(count, bool) or not isinstance(count, int) or count < 0:
            raise ValueError('invalid record')
        if record['package'] == package:
            totals[record['version']] = totals.get(record['version'], 0) + count
    ordered = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    total = sum(totals.values())
    pages = (len(ordered) + page_size - 1) // page_size
    start = (page - 1) * page_size
    versions = [{'version': version, 'downloads': count, 'share': round(count * 100 / total, 2) if total else 0.0} for version, count in ordered[start:start + page_size]]
    return {'package': package, 'total_downloads': total, 'versions': versions, 'page': page, 'page_size': page_size, 'pages': pages}

