import json
import datetime
import math

def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = datetime.date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def _check(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for item in records:
        if not isinstance(item, dict):
            raise ValueError('record must be an object')
        for key in ('chemical', 'lot', 'quantity', 'unit', 'expires', 'hazard'):
            if key not in item:
                raise ValueError('missing field')
        if not isinstance(item['chemical'], str) or not item['chemical']:
            raise ValueError('invalid chemical')
        if not isinstance(item['lot'], str) or not item['lot']:
            raise ValueError('invalid lot')
        q = item['quantity']
        if isinstance(q, bool) or not isinstance(q, (int, float)) or (not math.isfinite(q)) or (q < 0):
            raise ValueError('invalid quantity')
        if item['unit'] not in ('kg', 'l') or not isinstance(item['hazard'], bool):
            raise ValueError('invalid record')
        _date(item['expires'])
    return records

def pack_inventory(records: list[dict]) -> bytes:
    _check(records)
    try:
        return json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('records cannot be encoded') from exc

def unpack_inventory(blob: bytes | str) -> list[dict]:
    if not isinstance(blob, (bytes, str)):
        raise ValueError('invalid payload')
    try:
        value = json.loads(blob.decode('utf-8') if isinstance(blob, bytes) else blob)
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    return _check(value)

def compliance_report(blob: bytes | str, as_of: str) -> dict:
    day = _date(as_of)
    groups = {}
    for item in unpack_inventory(blob):
        name = item['chemical']
        group = groups.setdefault(name, {'lots': 0, 'quantities': {}, 'expired': 0, 'expiring_within_30': 0, 'hazardous_lots': 0})
        group['lots'] += 1
        unit = item['unit']
        group['quantities'][unit] = group['quantities'].get(unit, 0) + item['quantity']
        expiry = _date(item['expires'])
        if expiry < day:
            group['expired'] += 1
        elif expiry <= day + datetime.timedelta(days=30):
            group['expiring_within_30'] += 1
        if item['hazard']:
            group['hazardous_lots'] += 1
    output = []
    for name in sorted(groups, key=lambda x: (x.casefold(), x)):
        entry = groups[name]
        quantities = {u: entry['quantities'][u] for u in ('kg', 'l') if u in entry['quantities']}
        output.append({'chemical': name, 'lots': entry['lots'], 'quantities': quantities, 'expired': entry['expired'], 'expiring_within_30': entry['expiring_within_30'], 'hazardous_lots': entry['hazardous_lots']})
    return {'as_of': as_of, 'chemicals': output}

