    try:
        _validate_common(recipient)
        rb, rr = (recipient['blood_type'], recipient['rh'])
        ra = recipient['age']
    except (KeyError, TypeError):
        raise ValueError('invalid recipient')
    allowed = {'O': {'O'}, 'A': {'O', 'A'}, 'B': {'O', 'B'}, 'AB': {'O', 'A', 'B', 'AB'}}
    out = []
    for d in donors:
        try:
            if not _check_type(d['blood_type']) or d['rh'] not in {'+', '-'}:
                raise ValueError('invalid blood value')
            if not isinstance(d['location'], (list, tuple)) or len(d['location']) != 2 or (not all((isinstance(x, (int, float)) and (not isinstance(x, bool)) for x in d['location']))):
                raise ValueError('invalid location')
            if not isinstance(d['hla'], dict) or any((k not in d['hla'] or not isinstance(d['hla'][k], int) for k in ('A', 'B', 'DR'))):
                raise ValueError('invalid hla')
            if not isinstance(d['ischemic_hours'], (int, float)) or d['ischemic_hours'] <= 0:
                raise ValueError('invalid hours')
            if d['blood_type'] not in allowed[rb] or (rr == '-' and d['rh'] == '+') or (not d['available']) or (not 18 <= d['age'] <= 65):
                continue
            mismatches = sum((d['hla'][k] != recipient['hla'][k] for k in ('A', 'B', 'DR')))
            if any((abs(d['hla'][k] - recipient['hla'][k]) > 1 for k in ('A', 'B', 'DR'))):
                continue
            distance = math.hypot(d['location'][0] - recipient['location'][0], d['location'][1] - recipient['location'][1])
            if distance > recipient['max_distance'] or d['ischemic_hours'] > recipient['max_ischemic_hours']:
                continue
            out.append({'id': d['id'], 'distance': float(distance), 'hla_mismatches': mismatches, 'age_difference': abs(d['age'] - ra), 'ischemic_hours': d['ischemic_hours']})
        except (KeyError, TypeError):
            raise ValueError('invalid donor')
    out.sort(key=lambda x: (x['hla_mismatches'], x['distance'], x['age_difference'], x['id']))
    return out

def export_matches(recipient: dict, donors: list[dict], output_path: str) -> int:
    matches = match_donors(recipient, donors)
    parent = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(prefix='.matches-', dir=parent, text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['id', 'distance', 'hla_mismatches', 'age_difference', 'ischemic_hours'])
            for row in matches:
                writer.writerow([row[k] for k in ('id', 'distance', 'hla_mismatches', 'age_difference', 'ischemic_hours')])
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(matches)

