import os
import json
import hmac
import hashlib
from datetime import date, timedelta

def aggregate_sessions(sessions: list[dict], window_days: int=7) -> list[dict]:
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days <= 0:
        raise ValueError('window_days must be positive')
    if not sessions:
        return []
    checked = []
    for row in sessions:
        try:
            d = date.fromisoformat(row['date'])
            exercise = row['exercise']
            reps = row['repetitions']
            pain = row['pain']
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid session')
        if not isinstance(exercise, str) or not exercise:
            raise ValueError('invalid session')
        if not isinstance(reps, int) or isinstance(reps, bool) or reps < 0:
            raise ValueError('invalid session')
        if isinstance(pain, bool) or not isinstance(pain, (int, float)) or (not 0 <= pain <= 10):
            raise ValueError('invalid session')
        checked.append((d, exercise, reps, pain))
    anchor = min((x[0] for x in checked)) - timedelta(days=min((x[0] for x in checked)).weekday())
    groups = {}
    for d, exercise, reps, pain in checked:
        offset = (d - anchor).days // window_days
        start = anchor + timedelta(days=offset * window_days)
        key = (start, exercise)
        item = groups.setdefault(key, [0, 0, [], 0])
        item[0] += 1
        item[1] += reps
        item[2].append(pain)
        item[3] = max(item[3], pain)
    result = []
    for (start, exercise), (count, total, pains, maximum) in sorted(groups.items()):
        result.append({'window_start': start.isoformat(), 'exercise': exercise, 'sessions': count, 'total_repetitions': total, 'average_pain': round(sum(pains) / count, 2), 'max_pain': maximum})
    return result

def _key(config):
    value = config.get('report_key') if config is not None and 'report_key' in config else os.environ.get('PHYSIO_REPORT_KEY')
    if not isinstance(value, str) or not value:
        raise ValueError('missing report key')
    return value.encode()

def create_report(sessions: list[dict], config: dict | None=None) -> str:
    data = aggregate_sessions(sessions)
    raw = json.dumps(data, sort_keys=True, separators=(',', ':'))
    sig = hmac.new(_key(config), raw.encode(), hashlib.sha256).hexdigest()
    return json.dumps({'data': data, 'signature': sig}, separators=(',', ':'))

def verify_report(report: str, config: dict | None=None) -> bool:
    try:
        obj = json.loads(report)
        if not isinstance(obj, dict) or not isinstance(obj.get('data'), list) or (not isinstance(obj.get('signature'), str)):
            return False
        raw = json.dumps(obj['data'], sort_keys=True, separators=(',', ':'))
        expected = hmac.new(_key(config), raw.encode(), hashlib.sha256).hexdigest()
        return hmac.compare_digest(obj['signature'], expected)
    except (ValueError, TypeError, json.JSONDecodeError):
        return False

