def generate_usage_report(requester: dict, workspace: dict, events: list[dict]) -> dict:
    required_workspace = {'id', 'name', 'owner_id', 'tenant_id'}
    if not required_workspace.issubset(workspace):
        raise ValueError('invalid workspace')
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    same_tenant = requester.get('tenant_id') == workspace['tenant_id']
    permitted = requester.get('id') == workspace['owner_id'] or 'analytics_admin' in requester.get('roles', [])
    if not (same_tenant and permitted):
        raise PermissionError('not permitted')
    totals = {}
    count = 0
    total = 0
    for event in events:
        required_event = {'workspace_id', 'user_id', 'feature', 'duration_seconds'}
        if not required_event.issubset(event):
            raise ValueError('invalid event')
        if event['duration_seconds'] < 0:
            raise ValueError('invalid duration')
        if event['workspace_id'] != workspace['id']:
            continue
        name = event['feature']
        item = totals.setdefault(name, [0, 0])
        item[0] += 1
        item[1] += event['duration_seconds']
        count += 1
        total += event['duration_seconds']
    features = [{'name': name, 'event_count': totals[name][0], 'total_duration_seconds': totals[name][1]} for name in sorted(totals)]
    return {'workspace_id': workspace['id'], 'workspace_name': workspace['name'], 'event_count': count, 'total_duration_seconds': total, 'features': features}

