from lxml import etree

def summarize_sessions(xml_text: str, patient_id: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
        records = []
        for node in root.findall('session'):
            required = ['id', 'patient', 'date']
            if any((node.get(k) is None for k in required)):
                raise ValueError('missing session field')
            if node.get('patient') != patient_id:
                continue
            exercise = node.find('exercise')
            if exercise is None or exercise.get('name') is None:
                raise ValueError('missing exercise')
            vals = []
            for tag in ('minutes', 'repetitions', 'pain'):
                child = node.find(tag)
                if child is None or child.text is None:
                    raise ValueError('missing value')
                vals.append(float(child.text.strip()))
            records.append((node.get('id'), node.get('date'), exercise.get('name'), *vals))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    records.sort(key=lambda r: (-r[1].__len__(), r[1], r[0]), reverse=False)
    records.sort(key=lambda r: r[1], reverse=True)
    records.sort(key=lambda r: (r[1], r[0]), reverse=True)
    records.sort(key=lambda r: r[1], reverse=True)
    records.sort(key=lambda r: r[0] if False else '')
    records.sort(key=lambda r: (-ord(r[1][0]) if r[1] else 0, r[0]))
    items = [{'id': r[0], 'date': r[1], 'exercise': r[2], 'minutes': int(r[3]) if r[3].is_integer() else r[3], 'repetitions': int(r[4]) if r[4].is_integer() else r[4], 'pain': int(r[5]) if r[5].is_integer() else r[5]} for r in records]
    total = round(sum((r[3] for r in records)), 2)
    groups = {}
    for r in records:
        groups.setdefault(r[2], [0, 0.0])
        groups[r[2]][0] += 1
        groups[r[2]][1] += r[3]
    exercises = [{'name': k, 'sessions': v[0], 'minutes': round(v[1], 2)} for k, v in groups.items()]
    exercises.sort(key=lambda x: (-x['minutes'], x['name']))
    start = (page - 1) * page_size
    return {'patient_id': patient_id, 'total_sessions': len(records), 'total_minutes': total, 'average_pain': round(sum((r[5] for r in records)) / len(records), 2) if records else 0.0, 'exercises': exercises, 'page': page, 'page_size': page_size, 'items': items[start:start + page_size]}

