    items = [{'id': r['id'], 'site_id': r['site_id'], 'status': r['status'], 'priority': r['priority'], 'due_day': r['due_day'], 'estimated_hours': r['estimated_hours'], 'completed_hours': r['completed_hours']} for r in selected[start:start + page_size]]
