import requests
from datetime import date, timedelta

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def normalize_license_records(payload):
    if not isinstance(payload, dict) or not isinstance(payload.get('licenses'), list):
        raise ValueError('invalid payload')
    result = []
    required = ('id', 'course', 'starts', 'expires', 'status', 'seats', 'features')
    for item in payload['licenses']:
        if not isinstance(item, dict) or any((k not in item for k in required)):
            raise ValueError('invalid license')
        if not all((isinstance(item[k], str) for k in ('id', 'course', 'starts', 'expires', 'status'))):
            raise ValueError('invalid license')
        _day(item['starts'])
        _day(item['expires'])
        if isinstance(item['seats'], bool) or not isinstance(item['seats'], int) or item['seats'] < 0:
            raise ValueError('invalid seats')
        if not isinstance(item['features'], list) or not all((isinstance(x, str) for x in item['features'])):
            raise ValueError('invalid features')
        result.append({'id': item['id'], 'course': item['course'], 'starts': item['starts'], 'expires': item['expires'], 'status': item['status'].lower(), 'seats': item['seats'], 'features': sorted(set(item['features']))})
    return sorted(result, key=lambda x: (x['course'], x['starts'], x['id']))

def fetch_license_records(api_base, learner_id, token):
    response = requests.get(api_base.rstrip('/') + '/v1/learners/' + learner_id + '/licenses', params={'learner': learner_id}, headers={'Authorization': 'Bearer ' + token})
    if response.status_code != 200:
        raise RuntimeError(str(response.status_code))
    return normalize_license_records(response.json())

def summarize_licenses(records, as_of):
    today = _day(as_of)
    groups = {}
    for record in records:
        try:
            start = _day(record['starts'])
            expiry = _day(record['expires'])
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        groups.setdefault(record['course'], []).append((record, start, expiry))
    output = []
    for course in sorted(groups):
        active = [(r, e) for r, s, e in groups[course] if r.get('status') == 'active' and s <= today <= e]
        features = sorted({f for r, _ in active for f in r['features']})
        expiry = max((e for _, e in active), default=None)
        output.append({'course': course, 'license_count': len(active), 'seats': sum((r['seats'] for r, _ in active)), 'features': features, 'expires': expiry.isoformat() if expiry else None, 'renewal_due': any((e <= today + timedelta(days=30) for _, e in active))})
    return output

