def normalize_invoice_number(value: str) -> str:
    if not isinstance(value, str):
        raise TypeError('value must be a string')
    return ''.join((c for c in value.strip().lower() if 'a' <= c <= 'z' or '0' <= c <= '9'))

def evaluate_formula(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval').body

        def ev(n):
            if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)) and (not isinstance(n.value, complex)):
                return n.value
            if isinstance(n, ast.Name) and n.id in variables:
                return variables[n.id]
            if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(n.op)](ev(n.operand))
            if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(n.op)](ev(n.left), ev(n.right))
            if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
