def summarize_enrollment(records: list[tuple[str, str, str, int, str]], term: str) -> dict:
    if not term:
        raise ValueError('term must not be empty')
    selected = []
    for record in records:
        if len(record) != 5:
            raise ValueError('invalid record')
        record_term, student, course, credits, status = record
        if status not in {'enrolled', 'waitlisted', 'dropped'}:
            raise ValueError('invalid status')
        if not isinstance(credits, int) or isinstance(credits, bool) or credits <= 0:
            raise ValueError('invalid credits')
        if record_term == term and status == 'enrolled':
            selected.append((student, course, credits))
