        courses = []
        credits = 0
        while index < len(selected) and selected[index][0] == student:
            _, course, value = selected[index]
            if course in courses:
                raise ValueError('duplicate course')
            courses.append(course)
            credits += value
            index += 1
        students.append({'student_id': student, 'courses': courses, 'credits': credits})
