            groups[key] = [0, Decimal('0')]
        groups[key][0] += 1
        groups[key][1] += fee
    rows = []
    for (current_region, species), (count, total) in sorted(groups.items()):
        average = total / count
        rows.append([current_region, species, str(count), format(total, '.2f'), format(average, '.2f')])
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
