def generate_invite_code(order_id: str, used_codes=(), length: int=10) -> str:
    if not isinstance(order_id, str):
        raise TypeError('order_id must be a string')
    if not order_id.strip():
        raise ValueError('order_id must not be empty')
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError('length must be an integer')
    if length < 6 or length > 32:
        raise ValueError('invalid length')
    existing = set(used_codes)
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ23456789'
    for _ in range(1000):
        code = ''.join((secrets.choice(alphabet) for _ in range(length)))
        if code not in existing:
            return code
    raise RuntimeError('unable to generate a unique code')

def order_report(lines: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(lines, list):
        raise ValueError('lines must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    totals = {}
    for line in lines:
        if not isinstance(line, dict):
            raise ValueError('invalid line')
        if set(line) != {'order_id', 'item', 'quantity', 'unit_price'}:
            raise ValueError('invalid fields')
        order_id = line['order_id']
        item = line['item']
        quantity = line['quantity']
        price = line['unit_price']
        if not isinstance(order_id, str) or not order_id.strip():
            raise ValueError('invalid order_id')
        if not isinstance(item, str) or not item.strip():
            raise ValueError('invalid item')
        if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity <= 0:
            raise ValueError('invalid quantity')
        if not isinstance(price, (int, float)) or isinstance(price, bool) or price < 0:
            raise ValueError('invalid price')
        if order_id not in totals:
            totals[order_id] = [0, 0.0]
        totals[order_id][0] += quantity
        totals[order_id][1] += quantity * price
    result = [{'order_id': k, 'item_count': v[0], 'total': round(v[1], 2)} for k, v in totals.items()]
    result.sort(key=lambda x: (-x['total'], x['order_id']))
    start = (page - 1) * page_size
    return {'orders': result[start:start + page_size], 'total_orders': len(result), 'page': page, 'page_size': page_size}

