def select_households(records: list[dict], formula: str, minimum: float, offset: int, limit: int) -> list[dict]:
    if isinstance(offset, bool) or isinstance(limit, bool) or (not isinstance(offset, int)) or (not isinstance(limit, int)) or (offset < 0) or (limit < 0):
        raise ValueError('offset and limit must be nonnegative integers')
    tree = ast.parse(formula, mode='eval')
    names = {'min': min, 'max': max, 'round': round}
    allowed = {'income', 'members', 'children', 'id'}

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in values:
                return values[node.id]
            if node.id in names:
                return names[node.id]
            raise NameError("name '%s' is not defined" % node.id)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
