import json

def _validate_records(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('title'), str) or not record['title']:
            raise ValueError('invalid title')
        if not isinstance(record.get('borrower'), str) or not record['borrower']:
            raise ValueError('invalid borrower')
        days = record.get('days_overdue')
        if isinstance(days, bool) or not isinstance(days, int) or days < 0:
            raise ValueError('invalid overdue days')

def dump_snapshot(records: list[dict[str, object]]) -> bytes:
    _validate_records(records)
    try:
        return json.dumps(records, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('unable to encode snapshot') from exc

def load_and_summarize(payload: bytes, offset: int=0, limit: int=10) -> list[dict[str, object]]:
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('invalid limit')
    try:
        records = json.loads(payload.decode('utf-8'))
    except (AttributeError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    _validate_records(records)
    grouped = {}
    for record in records:
        days = record['days_overdue']
        if days:
            borrower = record['borrower']
            item = grouped.setdefault(borrower, [0, 0, 0])
            item[0] += 1
            item[1] += days
            item[2] = max(item[2], days)
