                current = datetime.fromisoformat(event['timestamp'].replace('Z', '+00:00'))
                if current < previous:
                    raise ValueError('invalid time order')
        result.append({'batch_id': bid, 'product': product, 'quantity': quantity, 'materials': materials, 'events': events})
