import csv
import hashlib
import hmac
import os
from datetime import date
from decimal import Decimal, InvalidOperation

def _date(value):
    try:
        parsed = date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def _hash(password):
    if not isinstance(password, str):
        raise ValueError('invalid password')
    salt = os.urandom(16)
    iterations = 120000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return 'pbkdf2$%d$%s$%s' % (iterations, salt.hex(), digest.hex())

def create_compliance_profile(password: str, csv_text: str) -> dict:
    if not isinstance(csv_text, str):
        raise ValueError('invalid csv')
    rows = list(csv.reader(csv_text.splitlines()))
    if not rows or rows[0] != ['code', 'due', 'amount', 'status', 'category']:
        raise ValueError('invalid header')
    obligations = []
    for row in rows[1:]:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid row')
        code, due, amount, status, category = [x.strip() for x in row]
        if not code or not category or status not in ('open', 'filed'):
            raise ValueError('invalid field')
        _date(due)
        try:
            number = Decimal(amount)
        except (InvalidOperation, ValueError):
            raise ValueError('invalid amount')
        if not number.is_finite() or number < 0:
            raise ValueError('invalid amount')
        obligations.append({'code': code, 'due': due, 'amount': number, 'status': status, 'category': category})
    return {'password': _hash(password), 'obligations': obligations, 'version': 1}

def authenticate(profile: dict, password: str) -> bool:
    if not isinstance(password, str):
        return False
    try:
        _, count, salt, expected = profile['password'].split('$')
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt), int(count)).hex()
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

def summarize_obligations(profile: dict, as_of: str) -> dict:
    today = _date(as_of)
    groups = {}
    opened = filed = overdue = 0
    amount_open = Decimal('0')
    next_due = None
    for item in profile['obligations']:
        due = _date(item['due'])
        group = groups.setdefault(item['category'], [0, 0, Decimal('0')])
        group[0] += 1
        group[2] += item['amount']
        if item['status'] == 'open':
            opened += 1
            amount_open += item['amount']
            group[1] += 1
            if due < today:
                overdue += 1
            elif next_due is None or due < next_due:
                next_due = due
        else:
            filed += 1
    categories = [{'category': k, 'total': v[0], 'open': v[1], 'amount': v[2]} for k, v in sorted(groups.items())]
    return {'as_of': as_of, 'total': len(profile['obligations']), 'open': opened, 'filed': filed, 'overdue': overdue, 'amount_open': amount_open, 'categories': categories, 'next_due': next_due.isoformat() if next_due else None}

