import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_transactions(base_dir: str, filename: str, page: int=1, page_size: int=10, category: str | None=None) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, filename))
    try:
        if os.path.commonpath([base, candidate]) != base:
            raise ValueError('invalid filename')
    except ValueError:
        raise ValueError('invalid filename')
    if not os.path.isfile(candidate):
        raise ValueError('file unavailable')
    required = {'date', 'description', 'amount', 'category'}
    records = []
    try:
        with open(candidate, newline='', encoding='utf-8') as handle:
            reader = csv.DictReader(handle)
            if not reader.fieldnames or not required.issubset(reader.fieldnames):
                raise ValueError('missing columns')
            for row in reader:
                if not any((value or '' for value in row.values())):
                    continue
                if not row['date'] or not row['category']:
                    raise ValueError('empty value')
                try:
                    amount = Decimal(row['amount'])
                except (InvalidOperation, TypeError):
                    raise ValueError('invalid amount')
                if category is None or row['category'] == category:
                    records.append({'date': row['date'], 'description': row['description'], 'amount': amount, 'category': row['category']})
    except (OSError, UnicodeError, csv.Error):
        raise ValueError('invalid file')
    records.sort(key=lambda x: (-int(x['date'].replace('-', '')), x['description'], x['category']))
    totals = {}
    for record in records:
        totals[record['category']] = totals.get(record['category'], Decimal('0')) + record['amount']
    quant = Decimal('0.01')
    start = (page - 1) * page_size
    selected = records[start:start + page_size]
    return {'total_count': len(records), 'category_totals': {key: float(value.quantize(quant, rounding=ROUND_HALF_UP)) for key, value in sorted(totals.items())}, 'transactions': [{'date': x['date'], 'description': x['description'], 'amount': float(x['amount'].quantize(quant, rounding=ROUND_HALF_UP)), 'category': x['category']} for x in selected]}

