def build_inventory_report(records: list[dict], page: int, page_size: int) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be a positive integer')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('page_size must be between 1 and 100')
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        if not isinstance(record.get('plant'), str) or not record['plant']:
            raise ValueError('plant must be a non-empty string')
        species = record.get('species')
        quantity = record.get('quantity')
        price = record.get('unit_price')
        if not isinstance(species, str) or not species:
            raise ValueError('species must be a non-empty string')
        if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity < 0:
            raise ValueError('quantity must be a non-negative integer')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or (not math.isfinite(price)) or (price < 0):
            raise ValueError('unit_price must be a finite non-negative number')
        if species not in grouped:
            grouped[species] = [0, Decimal('0')]
        grouped[species][0] += quantity
        grouped[species][1] += Decimal(str(price)) * quantity
    all_items = []
    for species, (quantity, value) in grouped.items():
        rounded = value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        all_items.append({'species': species, 'quantity': quantity, 'total_value': float(rounded)})
    all_items.sort(key=lambda item: (-item['quantity'], item['species']))
    total = len(all_items)
    start = (page - 1) * page_size
    items = all_items[start:start + page_size]
    payload = {'items': items, 'page': page, 'page_size': page_size, 'total': total}
    key = os.environ.get('NURSERY_SIGNING_KEY')
    if key is None:
        raise RuntimeError('NURSERY_SIGNING_KEY is required')
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(key.encode('utf-8'), encoded, hashlib.sha256).hexdigest()
    return {'items': items, 'page': page, 'page_size': page_size, 'total': total, 'signature': signature}

