from decimal import Decimal, InvalidOperation

def campaign_report(records: list[dict], as_of: str, window_days: int=7) -> list[dict]:
    if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days <= 0:
        raise ValueError('invalid window')
    try:
        end = date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    data = {}
    for row in records:
        if not isinstance(row, dict):
            raise ValueError('invalid record')
        campaign, donor = (row.get('campaign'), row.get('donor'))
        if not isinstance(campaign, str) or not campaign or (not isinstance(donor, str)) or (not donor):
            raise ValueError('invalid name')
        try:
            when = date.fromisoformat(row['date'])
            amount = Decimal(str(row['amount']))
        except (KeyError, TypeError, ValueError, InvalidOperation) as exc:
            raise ValueError('invalid record') from exc
        if amount < 0 or amount.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        cents = int(amount * 100)
        item = data.setdefault(campaign, [0, 0, set()])
        item[0] += cents
        item[2].add(donor)
        if end - timedelta(days=window_days - 1) <= when <= end:
            item[1] += cents
