from lxml import etree

def _root(text):
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        return etree.fromstring(text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def _text(node):
    return (node.text or '').strip()

def parse_feed(xml_text: str) -> list[dict]:
    root = _root(xml_text)
    if root.tag != 'pickup-feed':
        raise ValueError('unexpected root')
    result = []
    for order in root.findall('order'):
        oid = (order.get('id') or '').strip()
        status = order.get('status', 'ready')
        customer = order.find('customer')
        slot = order.find('slot')
        if not oid or status not in {'ready', 'packed', 'collected', 'cancelled'} or customer is None or (slot is None):
            raise ValueError('invalid order')
        date = (slot.get('date') or '').strip()
        time = (slot.get('time') or '').strip()
        name = _text(customer)
        if not date or not time or (not name):
            raise ValueError('missing value')
        items = {}
        order_items = order.findall('item')
        if not order_items:
            raise ValueError('missing items')
        for item in order_items:
            sku = (item.get('sku') or '').strip()
            raw_qty, raw_price = (item.get('qty'), item.get('price'))
            try:
                qty, price = (int(raw_qty), int(raw_price))
            except (TypeError, ValueError) as exc:
                raise ValueError('invalid item') from exc
            if not sku or qty <= 0 or price < 0:
                raise ValueError('invalid item')
            if sku not in items:
                items[sku] = {'sku': sku, 'name': _text(item), 'qty': 0, 'price': price, 'subtotal_cents': 0}
            items[sku]['qty'] += qty
            items[sku]['subtotal_cents'] += qty * price
        vals = list(items.values())
        result.append({'id': oid, 'status': status, 'customer': name, 'date': date, 'time': time, 'items': vals, 'total_cents': sum((x['subtotal_cents'] for x in vals))})
    result.sort(key=lambda x: (x['date'], x['time'], x['id']))
    return result

def summarize_schedule(documents: list[str]) -> dict[str, list[dict]]:
    merged = {}
    for document in documents:
        for order in parse_feed(document):
            merged[order['id']] = order
    groups = {}
    for order in merged.values():
        if order['status'] != 'cancelled':
            groups.setdefault((order['date'], order['time']), []).append(order['id'])
    result = {}
    for date, time in sorted(groups):
        result.setdefault(date, []).append({'time': time, 'orders': sorted(groups[date, time])})
    return result

