from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from lxml import etree

def refresh_dashboard(xml_text: str, metric: str='revenue', page: int=1, page_size: int=10) -> dict:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    if metric not in {'revenue', 'expenses', 'margin', 'units'}:
        raise ValueError('invalid metric')
    if isinstance(page, bool) or isinstance(page_size, bool) or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except (etree.XMLSyntaxError, UnicodeError):
        raise ValueError('invalid XML')
    if root.tag != 'dashboard':
        raise ValueError('invalid root')
    groups = {}
    for node in root:
        if node.tag != 'record':
            continue
        department = node.get('department')
        if not department:
            raise ValueError('invalid department')
        try:
            revenue = Decimal(node.get('revenue'))
            expenses = Decimal(node.get('expenses'))
            units = int(node.get('units'))
        except (TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid record')
        if not revenue.is_finite() or not expenses.is_finite() or units < 0:
            raise ValueError('invalid record')
        if department not in groups:
            groups[department] = [Decimal(0), Decimal(0), 0]
        groups[department][0] += revenue
        groups[department][1] += expenses
        groups[department][2] += units
    rows = []
    for department, (revenue, expenses, units) in groups.items():
        margin = revenue - expenses
        rows.append({'department': department, 'revenue': revenue, 'expenses': expenses, 'margin': margin, 'units': units})
    rows.sort(key=lambda row: (-row[metric], row['department']))
    start = (page - 1) * page_size
    quant = Decimal('0.01')
    output = []
    for row in rows[start:start + page_size]:
        output.append({'department': row['department'], 'revenue': float(row['revenue'].quantize(quant, rounding=ROUND_HALF_UP)), 'expenses': float(row['expenses'].quantize(quant, rounding=ROUND_HALF_UP)), 'margin': float(row['margin'].quantize(quant, rounding=ROUND_HALF_UP)), 'units': row['units']})
    return {'page': page, 'page_size': page_size, 'total_departments': len(rows), 'rows': output}

