import os
from datetime import date

def _valid_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if len(value) != 10:
        raise ValueError('invalid date')
    return value

def make_reservation(reservation_id: int, guest_name: str, appointment_date: str, duration_minutes: int, pin: str) -> dict:
    if isinstance(reservation_id, bool) or not isinstance(reservation_id, int) or reservation_id <= 0:
        raise ValueError('invalid reservation id')
    if not isinstance(guest_name, str) or not guest_name.strip():
        raise ValueError('invalid guest name')
    _valid_date(appointment_date)
    if duration_minutes not in (30, 60, 90):
        raise ValueError('invalid duration')
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isascii()) or (not pin.isdecimal()):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'reservation_id': reservation_id, 'guest_name': guest_name.strip(), 'appointment_date': appointment_date, 'duration_minutes': duration_minutes, 'pin_salt': salt.hex(), 'pin_hash': value.hex()}

def verify_reservation_pin(reservation: dict, pin: str) -> bool:
    if not isinstance(reservation, dict) or not isinstance(pin, str):
        return False
    try:
        salt = bytes.fromhex(reservation['pin_salt'])
        expected = bytes.fromhex(reservation['pin_hash'])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_reservations(reservations: list[dict], appointment_date: str, page: int, page_size: int) -> dict:
    _valid_date(appointment_date)
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    matching = [r for r in reservations if r.get('appointment_date') == appointment_date]
    matching.sort(key=lambda r: (-r['duration_minutes'], r['reservation_id']))
    start = (page - 1) * page_size
    return {'date': appointment_date, 'count': len(matching), 'total_minutes': sum((r['duration_minutes'] for r in matching)), 'reservations': matching[start:start + page_size]}

