import hashlib
import hmac

def parse_gradebook(text: str) -> list[tuple[str, str, float, int]]:
    records = []
    seen = set()
    for raw in text.splitlines():
        if raw == '':
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('malformed escape')
        fields.append(''.join(current))
        if len(fields) != 4:
            raise ValueError('invalid record')
        student, assignment, score_text, weight_text = fields
        if not student or not assignment:
            raise ValueError('empty name')
        try:
            score = float(score_text)
            weight = int(weight_text)
        except (ValueError, TypeError):
            raise ValueError('invalid number')
        if not 0 <= score <= 100 or weight <= 0:
            raise ValueError('out of range')
        key = (student, assignment)
        if key in seen:
            raise ValueError('duplicate assignment')
        seen.add(key)
        records.append((student, assignment, score, weight))
    return records

def summarize_gradebook(records: list[tuple[str, str, float, int]]) -> list[dict[str, object]]:
    grouped = {}
    for student, assignment, score, weight in records:
        total, weights, count = grouped.get(student, (0.0, 0, 0))
        grouped[student] = (total + score * weight, weights + weight, count + 1)
    result = []
    for student, (total, weights, count) in grouped.items():
        result.append({'student': student, 'average': round(total / weights, 2), 'assignments': count})
    result.sort(key=lambda item: (-item['average'], item['student'].casefold(), item['student']))
    return result

def verify_gradebook(payload: str, secret: bytes, signature: str) -> list[dict[str, object]]:
    if len(signature) != 64 or any((char not in '0123456789abcdef' for char in signature)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    return summarize_gradebook(parse_gradebook(payload))

