import json
_FIELDS = {'id', 'waste_type', 'weight_kg', 'hazard_class', 'destination'}

def _valid_records(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict) or set(record) != _FIELDS:
            raise ValueError('invalid record')
        for key in ('id', 'waste_type', 'hazard_class', 'destination'):
            if not isinstance(record[key], str):
                raise ValueError('invalid record')
        weight = record['weight_kg']
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight <= 0:
            raise ValueError('invalid record')
    return records

def encode_manifest(records: list[dict]) -> bytes:
    _valid_records(records)
    try:
        return json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError('invalid record') from exc

def summarize_manifest(blob: bytes | str, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid pagination')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        records = json.loads(blob.decode('utf-8') if isinstance(blob, bytes) else blob)
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid manifest') from exc
    _valid_records(records)
    groups = {}
    for record in records:
        group = groups.setdefault(record['waste_type'], {'weight': 0.0, 'count': 0, 'destinations': set()})
        group['weight'] += record['weight_kg']
        group['count'] += 1
        group['destinations'].add(record['destination'])
    result = [{'waste_type': name, 'total_weight_kg': round(data['weight'], 2), 'manifest_count': data['count'], 'destinations': sorted(data['destinations'])} for name, data in groups.items()]
    result.sort(key=lambda item: (-item['total_weight_kg'], item['waste_type']), reverse=False)
    result.sort(key=lambda item: item['waste_type'], reverse=True)
    result.sort(key=lambda item: -item['total_weight_kg'])
    start = (page - 1) * page_size
    return result[start:start + page_size]

