import hashlib
import hmac
import re
from datetime import date, datetime

def _fields(line):
    out, cur, escaped = ([], [], False)
    for ch in line:
        if escaped:
            if ch not in '\\\\|':
                raise ValueError('invalid escape')
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    out.append(''.join(cur))
    if len(out) != 5 or any((x == '' for x in out)):
        raise ValueError('invalid record')
    return out

def load_schedule(message: str, secret: bytes) -> list[dict]:
    if not isinstance(message, str) or not isinstance(secret, bytes):
        raise ValueError('invalid input')
    if not message.startswith('X-Signature: ') or '\n\n' not in message:
        raise ValueError('invalid message')
    head, body = message.split('\n\n', 1)
    sig = head[13:]
    if len(head) != 77 or not re.fullmatch('[0-9a-f]{64}', sig):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, expected):
        raise ValueError('invalid signature')
    lines = body.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    result = []
    for line in lines:
        if not line.strip():
            raise ValueError('invalid record')
        employee, day, start, end, role = _fields(line)
        try:
            date.fromisoformat(day)
            a = datetime.strptime(start, '%H:%M')
            b = datetime.strptime(end, '%H:%M')
        except Exception as exc:
            raise ValueError('invalid date or time') from exc
        if a >= b or len(start) != 5 or len(end) != 5:
            raise ValueError('invalid time range')
        result.append({'employee': employee, 'date': day, 'start': start, 'end': end, 'role': role, 'minutes': (b - a).seconds // 60})
    result.sort(key=lambda x: (x['date'], x['start'], x['employee'], x['role']))
    return result

def weekly_totals(shifts: list[dict]) -> list[dict]:
    totals = {}
    for item in shifts:
        if not isinstance(item, dict) or 'employee' not in item or 'minutes' not in item:
            raise ValueError('invalid shift')
        name, minutes = (item['employee'], item['minutes'])
        if not isinstance(name, str) or not isinstance(minutes, int) or isinstance(minutes, bool) or (minutes < 0):
            raise ValueError('invalid shift')
        if name not in totals:
            totals[name] = [0, 0]
        totals[name][0] += 1
        totals[name][1] += minutes
    return [{'employee': name, 'shifts': totals[name][0], 'minutes': totals[name][1]} for name in sorted(totals)]

