        raise ValueError('invalid status')
    selected = []
    for record in batches:
        if not isinstance(record, dict):
            raise ValueError('invalid batch')
        required = ('batch_id', 'tenant_id', 'owner_id', 'status', 'produced_at', 'measurements')
        if any((not isinstance(record.get(k), str) for k in required[:5])) or not isinstance(record.get('measurements'), list):
            raise ValueError('invalid batch')
        try:
            stamp = record['produced_at'].replace('Z', '+00:00')
            when = datetime.fromisoformat(stamp)
            if when.tzinfo is None:
                when = when.replace(tzinfo=timezone.utc)
        except Exception as exc:
            raise ValueError('invalid timestamp') from exc
        measurements = []
        for measurement in record['measurements']:
            if not isinstance(measurement, dict) or not isinstance(measurement.get('mass_kg'), (int, float)) or isinstance(measurement.get('mass_kg'), bool) or (not isinstance(measurement.get('quality_score'), (int, float))) or isinstance(measurement.get('quality_score'), bool):
