        if allowed and (status is None or record['status'] == status):
            selected.append((record, when, measurements))
    selected.sort(key=lambda x: (-x[1].timestamp(), x[0]['batch_id']))
    start = (page - 1) * page_size
    items = []
    for record, _, measurements in selected[start:start + page_size]:
        total = sum((x[0] for x in measurements))
        average = sum((x[1] for x in measurements)) / len(measurements) if measurements else None
        items.append({'batch_id': record['batch_id'], 'status': record['status'], 'measurement_count': len(measurements), 'total_mass_kg': round(total, 2), 'average_quality': None if average is None else round(average, 2)})
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'items': items}

