import hashlib
import hmac
import math
import os

def hash_api_secret(secret: str) -> str:
    if not isinstance(secret, str) or not secret:
        raise ValueError('secret must be a non-empty string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_api_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_brand_sentiment(records: list[dict], page: int=1, page_size: int=10, min_score: float=0.0) -> list[dict]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not math.isfinite(min_score)):
        raise ValueError('invalid minimum score')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        brand = record.get('brand')
        sentiment = record.get('sentiment')
        score = record.get('score')
        if not isinstance(brand, str) or not brand or sentiment not in {'positive', 'negative', 'neutral'} or isinstance(score, bool) or (not isinstance(score, (int, float))) or (not math.isfinite(score)):
            raise ValueError('invalid record')
        if score >= min_score:
            groups.setdefault(brand, []).append((sentiment, score))
    result = []
    for brand, values in groups.items():
        count = len(values)
        average = sum((score for _, score in values)) / count
        positive = sum((sentiment == 'positive' for sentiment, _ in values))
        result.append({'brand': brand, 'mentions': count, 'average_score': round(average, 2), 'positive_ratio': round(positive / count, 3)})
    result.sort(key=lambda item: (-item['mentions'], -item['average_score'], item['brand']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

