        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not math.isfinite(min_score)):
        raise ValueError('invalid minimum score')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        brand = record.get('brand')
        sentiment = record.get('sentiment')
        score = record.get('score')
        if not isinstance(brand, str) or not brand or sentiment not in {'positive', 'negative', 'neutral'} or isinstance(score, bool) or (not isinstance(score, (int, float))) or (not math.isfinite(score)):
