        if score >= min_score:
            groups.setdefault(brand, []).append((sentiment, score))
    result = []
    for brand, values in groups.items():
        count = len(values)
        average = sum((score for _, score in values)) / count
        positive = sum((sentiment == 'positive' for sentiment, _ in values))
        result.append({'brand': brand, 'mentions': count, 'average_score': round(average, 2), 'positive_ratio': round(positive / count, 3)})
    result.sort(key=lambda item: (-item['mentions'], -item['average_score'], item['brand']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

