    checked.sort(key=lambda r: (-r['likelihood'] * r['impact'], r['title'].casefold(), r['id']))
    total = len(checked)
    pages = max(1, (total + per_page - 1) // per_page)
    if page > pages:
        raise ValueError('invalid page')
    counts = {status: sum((r['status'] == status for r in checked)) for status in ('open', 'mitigated', 'accepted')}
