import re
import requests

def fetch_change_summary(base_url: str, project: str, start: str, end: str, page_size: int=100) -> dict:
    if not isinstance(base_url, str) or not base_url:
        raise ValueError('base_url must be non-empty')
    if not isinstance(project, str) or not project:
        raise ValueError('project must be non-empty')
    if not isinstance(start, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', start):
        raise ValueError('invalid start')
    if not isinstance(end, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', end):
        raise ValueError('invalid end')
    if start > end:
        raise ValueError('start after end')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page_size')
    url = base_url.rstrip('/') + '/api/changes'
    page = 1
    totals = {}
    while True:
        params = {'project': project, 'start': start, 'end': end, 'page': page, 'page_size': page_size}
        result = requests.get(url, params=params, headers={'Accept': 'application/json'})
        if result.status_code != 200:
            raise RuntimeError('change API request failed')
        data = result.json()
        for change in data['changes']:
            if change['status'] == 'implemented':
                owner = change['owner']
                entry = totals.setdefault(owner, [0, 0])
                entry[0] += 1
                entry[1] += change['duration_minutes']
        next_page = data.get('next_page')
        if next_page is None:
            break
        page = next_page
    owners = [{'owner': owner, 'count': values[0], 'total_hours': round(values[1] / 60, 2)} for owner, values in totals.items()]
    owners.sort(key=lambda item: (-item['count'], -item['total_hours'], item['owner']))
    return {'total': sum((item['count'] for item in owners)), 'by_owner': owners}

