import csv
import datetime
import os
import tempfile

def _parse_time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        parsed = datetime.datetime.fromisoformat(value.replace('Z', '+00:00'))
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=datetime.timezone.utc)
    return parsed.astimezone(datetime.timezone.utc)

def export_polling_report(records: list[dict], output_path: str, cutoff: str) -> dict:
    limit = _parse_time(cutoff)
    latest = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            precinct = record['precinct']
            ward = record['ward']
            party = record['party']
            votes = record['votes']
            stamp = record['reported_at']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(precinct, str) or not precinct or (not isinstance(ward, str)) or (not ward) or (not isinstance(party, str)) or (not party) or isinstance(votes, bool) or (not isinstance(votes, int)) or (votes < 0):
            raise ValueError('invalid record')
        moment = _parse_time(stamp)
        if moment <= limit:
            key = (precinct, party)
            old = latest.get(key)
            if old is None or moment >= old[0]:
                latest[key] = (moment, ward, party, votes, precinct)
    totals = {}
    for _, ward, party, votes, precinct in latest.values():
        key = (ward, party)
        if key not in totals:
            totals[key] = [0, set()]
        totals[key][0] += votes
        totals[key][1].add(precinct)
    rows = []
    for ward, party in sorted(totals):
        votes, precincts = totals[ward, party]
        rows.append({'ward': ward, 'party': party, 'votes': votes, 'precincts': len(precincts)})
    parent = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['ward', 'party', 'votes', 'precincts'])
            for row in rows:
                writer.writerow([row['ward'], row['party'], row['votes'], row['precincts']])
        os.replace(temporary, output_path)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'cutoff': cutoff, 'rows': rows}

