def find_available_drivers(latitude: float, longitude: float, radius_km: float, min_rating: float=0.0, limit: int=10) -> list[dict]:
    if not isinstance(latitude, (int, float)) or not math.isfinite(latitude) or (not -90 <= latitude <= 90):
        raise ValueError('invalid latitude')
    if not isinstance(longitude, (int, float)) or not math.isfinite(longitude) or (not -180 <= longitude <= 180):
        raise ValueError('invalid longitude')
    if not isinstance(radius_km, (int, float)) or not math.isfinite(radius_km) or radius_km <= 0:
        raise ValueError('invalid radius')
    if not isinstance(min_rating, (int, float)) or not math.isfinite(min_rating) or (not 0 <= min_rating <= 5):
        raise ValueError('invalid rating')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 1 <= limit <= 50):
        raise ValueError('invalid limit')
    response = requests.get('https://dispatch.example.com/api/v1/drivers/nearby', params={'lat': latitude, 'lon': longitude, 'radius_km': radius_km, 'min_rating': min_rating, 'limit': limit}, headers={'Accept': 'application/json'}, timeout=5)
    if response.status_code != 200:
        raise RuntimeError('driver service returned an error')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('drivers'), list):
        raise ValueError('invalid response')
    found = []
    for item in payload['drivers']:
        if not isinstance(item, dict) or not item.get('available'):
            continue
        if not item.get('id') or not item.get('vehicle'):
            continue
        try:
            distance = float(item['distance_km'])
            rating = float(item['rating'])
        except (KeyError, TypeError, ValueError):
            continue
        if not math.isfinite(distance) or not math.isfinite(rating) or distance > radius_km or (rating < min_rating):
            continue
        found.append((distance, rating, str(item['id']), {'id': str(item['id']), 'distance_km': round(distance, 2), 'rating': round(rating, 1), 'vehicle': str(item['vehicle'])}))
    found.sort(key=lambda row: (row[0], -row[1], row[2]))
    return [row[3] for row in found[:limit]]

