def fetch_grant_totals(api_url: str, charity_ids: list[str], minimum_amount: float) -> list[dict[str, object]]:
    if minimum_amount < 0:
        raise ValueError('minimum_amount must not be negative')
    if not charity_ids:
        return []
    response = requests.get(api_url, params={'charity_ids': ','.join(charity_ids), 'min_amount': f'{minimum_amount:.2f}'}, headers={'Accept': 'application/json'})
    if response.status_code != 200:
