    except Exception as exc:
        raise ValueError('invalid response JSON') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('grants'), list):
        raise ValueError('invalid grants payload')
    wanted = set(charity_ids)
    threshold = Decimal(str(minimum_amount))
    totals = defaultdict(lambda: [Decimal('0'), 0])
    for grant in payload['grants']:
        if not isinstance(grant, dict) or not all((key in grant for key in ('charity_id', 'amount', 'status'))):
            raise ValueError('invalid grant')
        try:
            charity_id = grant['charity_id']
            amount = Decimal(str(grant['amount']))
        except Exception as exc:
            raise ValueError('invalid grant amount') from exc
        if charity_id in wanted and grant['status'] == 'approved' and (amount >= threshold):
            totals[charity_id][0] += amount
            totals[charity_id][1] += 1
    result = []
    for charity_id, (total, count) in totals.items():
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'charity_id': charity_id, 'total_amount': float(rounded), 'grant_count': count})
    result.sort(key=lambda item: (-item['total_amount'], item['charity_id']))
    return result

