import csv
import hashlib
import hmac
import io
import json
from collections import defaultdict
from datetime import date, timedelta

def parse_sales_csv(text: str) -> list[dict]:
    if not text:
        return []
    rows = list(csv.reader(io.StringIO(text)))
    if not rows or [x.strip() for x in rows[0]] != ['date', 'sku', 'units']:
        raise ValueError('invalid header')
    combined = defaultdict(int)
    for row in rows[1:]:
        if len(row) != 3:
            raise ValueError('invalid row')
        raw_date, sku, raw_units = row
        try:
            parsed = date.fromisoformat(raw_date.strip())
        except ValueError:
            raise ValueError('invalid date')
        sku = sku.strip()
        if not sku:
            raise ValueError('empty sku')
        try:
            units = int(raw_units.strip())
        except ValueError:
            raise ValueError('invalid units')
        if units < 0 or str(units) != raw_units.strip():
            raise ValueError('invalid units')
        combined[parsed, sku] += units
    return [{'date': d.isoformat(), 'sku': s, 'units': combined[d, s]} for s, d in sorted(((s, d) for d, s in combined))]

def forecast_demand(text: str, config: dict) -> dict:
    if 'forecast_api_token' not in config:
        raise ValueError('forecast_api_token is required')
    token = config['forecast_api_token']
    window = config.get('window')
    horizon = config.get('horizon')
    if not isinstance(token, str) or not isinstance(window, int) or isinstance(window, bool) or (window <= 0) or (not isinstance(horizon, int)) or isinstance(horizon, bool) or (horizon <= 0):
