import csv
import io
from datetime import datetime, timedelta
_HEADER = ['recall_id', 'tenant', 'product', 'lot', 'units', 'status', 'reported_at', 'tags']
_STATUSES = {'open', 'investigating', 'closed'}

def _dt(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    except ValueError as e:
        raise ValueError('invalid timestamp') from e

def parse_recall_feed(text: str) -> list[dict]:
    if not isinstance(text, str) or not text.strip():
        raise ValueError('empty feed')
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as e:
        raise ValueError('bad csv') from e
    if not rows or rows[0] != _HEADER or len(rows) == 1:
        raise ValueError('bad header')
    out = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 8:
            raise ValueError('bad row')
        vals = [x.strip() for x in row[:4]]
        if any((not x for x in vals)):
            raise ValueError('blank field')
        rid, tenant, product, lot = vals
        if rid in seen:
            raise ValueError('duplicate id')
        raw_units = row[4].strip()
        try:
            units = int(raw_units)
        except ValueError as e:
            raise ValueError('bad units') from e
        if units < 0 or raw_units != str(units):
            raise ValueError('bad units')
        status = row[5].strip()
        if status not in _STATUSES:
            raise ValueError('bad status')
        stamp = row[6].strip()
        _dt(stamp)
        tags = [x.strip() for x in row[7].split(';') if x.strip()]
        if len(tags) != len(set(tags)):
            raise ValueError('duplicate tags')
        seen.add(rid)
        out.append({'recall_id': rid, 'tenant': tenant, 'product': product, 'lot': lot, 'units': units, 'status': status, 'reported_at': stamp, 'tags': tags})
    return out

def summarize_recall_cases(cases: list[dict], as_of: str) -> dict:
    end = _dt(as_of)
    start = end - timedelta(days=30)
    groups = {}
    for case in cases:
        when = _dt(case['reported_at'])
        if start <= when <= end:
            product = case['product']
            group = groups.setdefault(product, {'product': product, 'case_count': 0, 'total_units': 0, 'open_units': 0})
            group['case_count'] += 1
            group['total_units'] += case['units']
            if case['status'] in {'open', 'investigating'}:
                group['open_units'] += case['units']
    products = list(groups.values())
    products.sort(key=lambda x: (-x['open_units'], -x['total_units'], x['product']))
    return {'as_of': as_of, 'products': products}

def acknowledge_recall_case(user: dict, cases: list[dict], recall_id: str, note: str, acknowledged_at: str) -> dict:
    case = next((x for x in cases if x['recall_id'] == recall_id), None)
    if case is None:
        raise KeyError(recall_id)
    trimmed = note.strip() if isinstance(note, str) else ''
    if not trimmed or len(trimmed) > 500:
        raise ValueError('invalid note')
    _dt(acknowledged_at)
    if case['tenant'] != user.get('tenant') or (case.get('owner_id') != user.get('id') and 'coordinator' not in user.get('roles', [])):
        raise PermissionError('not permitted')
    case.update({'status': 'closed', 'note': trimmed, 'acknowledged_at': acknowledged_at, 'acknowledged_by': user['id']})
    return case

