from datetime import date
HEADER = ['book_id', 'member_id', 'borrowed', 'due', 'returned']

def loan_report(path: str, as_of: str) -> list[dict[str, object]]:
    try:
        cutoff = date.fromisoformat(as_of)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    try:
        with open(path, encoding='utf-8', newline='') as f:
            reader = csv.reader(f)
            header = next(reader)
            if header != HEADER:
                raise ValueError('invalid header')
        result = subprocess.run(['sort', '-t,', '-k2,2', '-k4,4', path], capture_output=True, text=True, check=True)
    except (OSError, StopIteration, subprocess.CalledProcessError) as exc:
        raise ValueError('cannot read ledger') from exc
    grouped = {}
    seen = set()
    for row in csv.reader(result.stdout.splitlines()):
        if row == HEADER:
            continue
        if len(row) != 5 or any((x == '' for x in row[:4])):
            raise ValueError('malformed row')
        book, member, borrowed, due, returned = row
        if book in seen:
            raise ValueError('duplicate book')
        seen.add(book)
        try:
            borrowed_d = date.fromisoformat(borrowed)
            due_d = date.fromisoformat(due)
            returned_d = date.fromisoformat(returned) if returned else None
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if due_d < borrowed_d or (returned_d is not None and returned_d < borrowed_d):
            raise ValueError('invalid date order')
        outstanding = returned_d is None or returned_d > cutoff
        if outstanding and due_d < cutoff:
            grouped.setdefault(member, []).append((cutoff.toordinal() - due_d.toordinal(), book))
    output = []
    for member in sorted(grouped):
        entries = sorted(grouped[member], key=lambda x: (-x[0], x[1]))
        output.append({'member_id': member, 'total_overdue': len(entries), 'days': sum((x[0] for x in entries)), 'books': [x[1] for x in entries]})
    return output

def render_loan_report(rows: list[dict[str, object]]) -> str:
    lines = []
    for row in rows:
        try:
            member = row['member_id']
            total = row['total_overdue']
            days = row['days']
            books = row['books']
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid row') from exc
        if not isinstance(member, str) or not isinstance(total, int) or isinstance(total, bool) or (total <= 0) or (not isinstance(days, int)) or isinstance(days, bool) or (days < 0) or (not isinstance(books, list)) or (not books) or (not all((isinstance(x, str) and x for x in books))):
            raise ValueError('invalid row')
        lines.append(f"{member}: {total} overdue, {days} total days, books: {', '.join(books)}")
    return '\n'.join(lines)

