def allocate_gates(flights: list[dict]) -> list[dict]:
    if not isinstance(flights, list):
        raise ValueError('invalid flights')
    checked = []
    seen = set()
    for item in flights:
        if not isinstance(item, dict) or set(item) != {'flight', 'terminal', 'arrival', 'departure'}:
            raise ValueError('invalid flight')
        flight = item['flight']
        terminal = item['terminal']
        arrival = item['arrival']
        departure = item['departure']
        if not isinstance(flight, str) or not flight or (not isinstance(terminal, str)) or (not terminal) or (not isinstance(arrival, int)) or isinstance(arrival, bool) or (not isinstance(departure, int)) or isinstance(departure, bool) or (arrival < 0) or (departure <= arrival) or (flight in seen):
            raise ValueError('invalid flight')
        seen.add(flight)
        checked.append((arrival, departure, flight, terminal))
    checked.sort(key=lambda x: (x[0], x[1], x[2]))
    active = {}
    free = {}
    next_number = {}
    result = {}
    for arrival, departure, flight, terminal in checked:
