def issue_parking_permits(requester: dict, applications: list[dict], zone_limits: dict[str, int], daily_rates: dict[str, int], as_of: str) -> list[dict]:
    cutoff = date.fromisoformat(as_of)
    grouped = {}
    for app in applications:
        if app['tenant_id'] != requester['tenant_id'] and 'admin' not in requester.get('roles', []):
            raise PermissionError('not permitted')
        if app['applicant_id'] != requester['id'] and 'permit_officer' not in requester.get('roles', []) and ('admin' not in requester.get('roles', [])):
            raise PermissionError('not permitted')
        if app['status'] != 'submitted':
            continue
        try:
            start = date.fromisoformat(app['start'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid date')
        if start < cutoff:
            continue
        days = app.get('days')
        if type(days) is not int or not 1 <= days <= 30:
            raise ValueError('invalid days')
        if not isinstance(app.get('vehicle_plate'), str) or not app['vehicle_plate']:
            raise ValueError('invalid vehicle plate')
        zone = app['zone']
        if zone not in zone_limits or zone not in daily_rates:
            continue
        grouped.setdefault(zone, []).append((app, start))
    output = []
    for zone in sorted(grouped):
        rows = sorted(grouped[zone], key=lambda x: (-x[0]['priority'], x[1], x[0]['id']))[:zone_limits[zone]]
        for app, start in rows:
            raw = daily_rates[zone] * app['days']
            fee = raw if app['days'] < 14 else raw * 90 // 100
            output.append({'application_id': app['id'], 'applicant_id': app['applicant_id'], 'zone': zone, 'start': start.isoformat(), 'end': (start + timedelta(days=app['days'] - 1)).isoformat(), 'fee_cents': fee, 'permit_number': f"MP-{zone}-{app['id']}"})
    return output

