from datetime import date, timedelta
import requests

def _date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _record(item):
    if not isinstance(item, dict) or not all((k in item for k in ('application', 'title', 'due_date', 'fee', 'status'))):
        raise ValueError('invalid record')
    if item['status'] not in ('active', 'pending'):
        return None
    if isinstance(item['fee'], bool) or not isinstance(item['fee'], (int, float)) or item['fee'] < 0:
        raise ValueError('invalid fee')
    _date(item['due_date'])
    return {'application': str(item['application']).upper(), 'title': str(item['title']).strip(), 'due_date': item['due_date'], 'fee': float(item['fee']), 'status': item['status']}

def fetch_renewals(api_url: str, owner: str, year: int) -> list[dict]:
    response = requests.get(api_url, params={'owner': owner, 'year': year}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise ValueError('request failed')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('renewals'), list):
        raise ValueError('invalid response')
    result = []
    for item in payload['renewals']:
        value = _record(item)
        if value is not None:
            result.append(value)
    return result

def build_renewal_plan(records: list[dict], as_of: str, horizon_days: int=90) -> list[dict]:
    start = _date(as_of)
    if isinstance(horizon_days, bool) or not isinstance(horizon_days, int) or horizon_days < 0:
        raise ValueError('invalid horizon')
    end = start + timedelta(days=horizon_days)
    groups = {}
    for item in records:
        value = _record(item)
        if value is None:
            continue
        due = _date(value['due_date'])
        if start <= due <= end:
            groups.setdefault(value['application'], []).append(value)
    result = []
    for application, items in groups.items():
        chosen = sorted(items, key=lambda x: (x['due_date'], -x['fee'], x['title']))[0]
        result.append({'application': application, 'title': chosen['title'], 'due_date': chosen['due_date'], 'total_fee': round(sum((x['fee'] for x in items)), 2), 'filings': len(items)})
    return sorted(result, key=lambda x: (x['due_date'], x['application']))

