import hmac

def can_read_article(cookie: str, article_id: str, expected_token: str) -> bool:
    fields = cookie.split(';')
    values = {}
    for field in fields:
        if '=' not in field:
            return False
        key, value = field.strip().split('=', 1)
        key = key.strip()
        if key not in {'article', 'token'} or key in values:
            return False
        values[key] = value
    if set(values) != {'article', 'token'}:
        return False
    if not values['token']:
        return False
    return values['article'] == article_id and hmac.compare_digest(values['token'], expected_token)

