import sqlite3

def screen_application(conn: sqlite3.Connection, application_id: int) -> dict:
    row = conn.execute('SELECT id, applicant, monthly_income, monthly_debt, requested_amount, term_months FROM applications WHERE id = ?', (application_id,)).fetchone()
    if row is None:
        raise LookupError('application not found')
    ident, applicant, income, debt, amount, term = row
    if term <= 0 or income <= 0:
        raise ValueError('income and term must be positive')
    missed = 0
    for due, paid, _ in conn.execute('SELECT due_date, paid_date, amount FROM payments WHERE application_id = ?', (application_id,)):
        if paid is None or paid > due:
            missed += 1
    ratio = (debt + amount / term) / income
    score = 100 - ratio * 100 - missed * 8
    ratio = round(ratio, 2)
    score = round(score, 2)
    return {'application_id': ident, 'applicant': applicant, 'debt_ratio': ratio, 'missed_payments': missed, 'score': score, 'eligible': ratio <= 0.4 and missed <= 1 and (score >= 60)}

