    columns = {'application_id': 'application_id', 'applicant': 'applicant', 'score': 'score', 'eligible': 'eligible', 'decision': 'decision'}
    if sort_by not in columns:
        raise ValueError('invalid sort field')
    direction = 'DESC' if descending else 'ASC'
    query = 'SELECT application_id, applicant, score, eligible, decision FROM screenings WHERE score >= ? ORDER BY ' + columns[sort_by] + ' ' + direction + ', application_id ASC'
    rows = conn.execute(query, (min_score,)).fetchall()
    return [{'application_id': r[0], 'applicant': r[1], 'score': r[2], 'eligible': bool(r[3]), 'decision': r[4]} for r in rows]

