    if decision not in {'approved', 'rejected', 'pending'}:
        raise ValueError('invalid decision')
    cur = conn.execute('UPDATE screenings SET decision = ? WHERE application_id = ?', (decision, application_id))
    if cur.rowcount == 0:
        raise LookupError('screening not found')
    conn.commit()
    row = conn.execute('SELECT application_id, applicant, score, eligible, decision FROM screenings WHERE application_id = ?', (application_id,)).fetchone()
    return {'application_id': row[0], 'applicant': row[1], 'score': row[2], 'eligible': bool(row[3]), 'decision': row[4]}

