import subprocess

def build_watch_report(path: str, user: str | None=None, top_n: int=3) -> list[dict]:
    if isinstance(top_n, bool) or not isinstance(top_n, int) or top_n <= 0:
        raise ValueError('top_n must be positive')
    completed = subprocess.run(['sort', '-t', '\t', '-k1,1', '-k2,2', '-k4,4n', path], capture_output=True, text=True, check=True)
    groups = {}
    for line in completed.stdout.splitlines():
        if not line:
            continue
        fields = line.split('\t')
        if len(fields) != 4:
            raise ValueError('malformed record')
        record_user, title, seconds_text, timestamp_text = fields
        if not record_user or not title:
            raise ValueError('empty field')
        try:
            seconds = int(seconds_text, 10)
            timestamp = int(timestamp_text, 10)
        except ValueError:
            raise ValueError('invalid number')
        if seconds < 0:
            raise ValueError('negative seconds')
        if user is not None and record_user != user:
            continue
        key = (record_user, title)
        if key not in groups:
            groups[key] = [0, 0, timestamp]
        groups[key][0] += seconds
        groups[key][1] += 1
        groups[key][2] = max(groups[key][2], timestamp)
    by_user = {}
    for (record_user, title), values in groups.items():
        by_user.setdefault(record_user, []).append({'user': record_user, 'title': title, 'total_seconds': values[0], 'sessions': values[1], 'last_timestamp': values[2]})
    result = []
    for record_user in sorted(by_user):
        rows = sorted(by_user[record_user], key=lambda row: (-row['total_seconds'], -row['last_timestamp'], row['title']))
        result.extend(rows[:top_n])
    return result

