import datetime
import hashlib
import hmac
import json
import math

def summarize_appointment_webhook(payload: bytes, signature: str, secret: bytes, day: str | None=None) -> dict:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid input')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    if day is not None:
        try:
            datetime.date.fromisoformat(day)
        except (TypeError, ValueError):
            raise ValueError('invalid day')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict) or not isinstance(data.get('appointments'), list):
        raise ValueError('invalid appointments')
    groups = {}
    count = 0
    total_minutes = 0
    total_price = 0.0
    for item in data['appointments']:
        if not isinstance(item, dict):
            raise ValueError('invalid appointment')
        if set(item) != {'cleaner', 'date', 'minutes', 'price'}:
            raise ValueError('invalid appointment')
        cleaner = item['cleaner']
        date = item['date']
        minutes = item['minutes']
        price = item['price']
        if not isinstance(cleaner, str) or not cleaner:
            raise ValueError('invalid cleaner')
        try:
            datetime.date.fromisoformat(date)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if isinstance(minutes, bool) or not isinstance(minutes, int) or minutes <= 0:
            raise ValueError('invalid minutes')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or (not math.isfinite(price)) or (price < 0):
            raise ValueError('invalid price')
        if day is not None and date != day:
            continue
        count += 1
        total_minutes += minutes
        total_price += price
        group = groups.setdefault(cleaner, [0, 0.0])
        group[0] += minutes
        group[1] += price
    return {'appointments': count, 'total_minutes': total_minutes, 'total_price': round(total_price, 2), 'by_cleaner': [{'cleaner': name, 'minutes': groups[name][0], 'price': round(groups[name][1], 2)} for name in sorted(groups)]}

