import sqlite3

def search_documents(conn: sqlite3.Connection, term: str, min_confidence: float=0.0, sort_by: str='confidence', descending: bool=True) -> list[dict]:
    if sort_by not in {'title', 'matches', 'confidence'}:
        raise ValueError('invalid sort key')
    rows = conn.execute('SELECT d.id, d.title, p.page_number, p.confidence FROM documents d JOIN pages p ON p.document_id=d.id WHERE lower(p.ocr_text) LIKE lower(?) AND p.confidence >= ? ORDER BY d.id, p.page_number', ('%' + term + '%', min_confidence)).fetchall()
    grouped = {}
    for doc_id, title, page, confidence in rows:
        item = grouped.setdefault(doc_id, {'id': doc_id, 'title': title, 'pages': [], 'values': []})
        item['pages'].append(page)
        item['values'].append(confidence)
    result = []
    for item in grouped.values():
        values = item.pop('values')
        item['match_count'] = len(values)
        item['avg_confidence'] = float(sum(values) / len(values))
        item['pages'] = sorted(item['pages'])
        result.append(item)
    if sort_by == 'title':
        result.sort(key=lambda x: (x['title'], x['id']), reverse=descending)
    elif sort_by == 'matches':
        result.sort(key=lambda x: (x['match_count'], x['title'], x['id']), reverse=False)
        if descending:
            result.sort(key=lambda x: x['match_count'], reverse=True)
    else:
        result.sort(key=lambda x: (x['avg_confidence'], x['title'], x['id']), reverse=False)
        if descending:
            result.sort(key=lambda x: x['avg_confidence'], reverse=True)
    return result

def set_document_status(conn: sqlite3.Connection, document_id: int, status: str) -> bool:
    if status not in {'queued', 'processing', 'complete', 'failed'}:
        raise ValueError('invalid status')
    cur = conn.execute('UPDATE documents SET status=? WHERE id=?', (status, document_id))
    conn.commit()
    return cur.rowcount > 0

def document_ocr_stats(conn: sqlite3.Connection, document_id: int) -> dict:
    exists = conn.execute('SELECT 1 FROM documents WHERE id=?', (document_id,)).fetchone()
    if exists is None:
        raise KeyError(document_id)
    rows = conn.execute('SELECT page_number, ocr_text, confidence FROM pages WHERE document_id=? ORDER BY page_number', (document_id,)).fetchall()
    confidences = [row[2] for row in rows]
    return {'document_id': document_id, 'page_count': len(rows), 'average_confidence': float(sum(confidences) / len(confidences)) if rows else None, 'low_confidence_pages': [row[0] for row in rows if row[2] < 0.75], 'total_characters': sum((len(row[1]) for row in rows))}

