import csv
import os
import tempfile

def export_lending_report(records: list[dict], output_path: str) -> dict:
    members = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = ('member_id', 'title', 'days_lent', 'returned')
        if any((key not in record for key in required)):
            raise ValueError('invalid record')
        member_id = record['member_id']
        title = record['title']
        days_lent = record['days_lent']
        returned = record['returned']
        if not isinstance(member_id, str) or not member_id or (not isinstance(title, str)) or (not isinstance(days_lent, int)) or isinstance(days_lent, bool) or (days_lent < 0) or (not isinstance(returned, bool)):
            raise ValueError('invalid record')
        overdue = 0 if returned else max(0, days_lent - 14)
        entry = members.setdefault(member_id, {'loans': 0, 'overdue_days': 0, 'cents': 0})
        entry['loans'] += 1
        entry['overdue_days'] += overdue
        entry['cents'] += overdue * 25
    rows = sorted(members.items(), key=lambda item: (-item[1]['cents'], item[0]))
    fd, temporary_path = tempfile.mkstemp(prefix='.lending-', dir=os.path.dirname(os.path.abspath(output_path)))
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['member_id', 'loans', 'overdue_days', 'fee'])
            for member_id, entry in rows:
                writer.writerow([member_id, entry['loans'], entry['overdue_days'], f"{entry['cents'] / 100:.2f}"])
        os.replace(temporary_path, output_path)
    except Exception:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise
    total_cents = sum((entry['cents'] for entry in members.values()))
    return {'members': len(members), 'loans': len(records), 'overdue_days': sum((entry['overdue_days'] for entry in members.values())), 'fees': round(total_cents / 100, 2)}

