import hashlib
import hmac
import os
import re

def _derive(password, salt):
    return hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()

def register_runner(registry: dict[str, dict], runner_id: str, name: str, age: int, password: str) -> dict:
    if not isinstance(runner_id, str) or not re.fullmatch('[A-Za-z0-9-]+', runner_id) or runner_id in registry:
        raise ValueError('invalid runner_id')
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(age, int) or isinstance(age, bool) or (not 16 <= age <= 100):
        raise ValueError('invalid age')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    record = {'runner_id': runner_id, 'name': name.strip(), 'age': age, 'category': 'junior' if age < 18 else 'adult', 'salt': salt.hex(), 'password_hash': _derive(password, salt)}
    registry[runner_id] = record
    return record

def authenticate_runner(registry: dict[str, dict], runner_id: str, password: str) -> bool:
    record = registry.get(runner_id)
    if record is None or not isinstance(password, str):
        return False
    try:
        actual = _derive(password, bytes.fromhex(record['salt']))
        return hmac.compare_digest(actual, record['password_hash'])
    except (KeyError, ValueError):
        return False

def rank_finishers(registry: dict[str, dict], results: str) -> list[dict]:
    rows = []
    header_seen = False
    for raw in results.splitlines():
        if not raw.strip():
            continue
        parts = [x.strip() for x in raw.split(',')]
        if parts == ['runner_id', 'time']:
            if rows or header_seen:
                raise ValueError('header')
            header_seen = True
            continue
        if len(parts) != 2:
            raise ValueError('line')
        runner_id, value = parts
        if runner_id == 'runner_id':
            raise ValueError('header')
        if runner_id not in registry or any((x[0] == runner_id for x in rows)):
            raise ValueError('runner')
        match = re.fullmatch('(\\d+):(\\d{2}):(\\d{2})', value)
        if not match or int(match.group(2)) > 59 or int(match.group(3)) > 59:
            raise ValueError('time')
        seconds = int(match.group(1)) * 3600 + int(match.group(2)) * 60 + int(match.group(3))
        rows.append((runner_id, seconds))
    rows.sort(key=lambda x: (x[1], x[0]))
    output = []
    for index, (runner_id, seconds) in enumerate(rows):
        rank = index + 1 if index == 0 or seconds != rows[index - 1][1] else output[-1]['rank']
        record = registry[runner_id]
        output.append({'runner_id': runner_id, 'name': record['name'], 'age': record['age'], 'category': record['category'], 'time_seconds': seconds, 'rank': rank})
    return output

