    if statuses is not None and (not isinstance(statuses, (list, tuple))):
        raise TypeError('statuses must be a list, tuple, or None')
    if search is not None and (not isinstance(search, str)):
        raise TypeError('search must be a string or None')
    if sort_by not in {'id', 'project_name', 'site', 'status', 'risk_score', 'estimated_cost'}:
        raise ValueError('invalid sort column')
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
        raise ValueError('limit must be positive')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('offset must be nonnegative')
    if statuses is not None and (not statuses):
        return []
    clauses = []
    params = []
    if statuses is not None:
        clauses.append('status IN (' + ','.join(('?' for _ in statuses)) + ')')
        params.extend(statuses)
    if search is not None:
        clauses.append('LOWER(project_name) LIKE LOWER(?)')
        params.append('%' + search + '%')
    sql = 'SELECT id, project_name, site, status, risk_score, estimated_cost FROM projects'
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    direction = 'DESC' if descending else 'ASC'
    sql += f' ORDER BY {sort_by} {direction}, id ASC LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    cursor = conn.execute(sql, params)
    names = [column[0] for column in cursor.description]
    return [dict(zip(names, row)) for row in cursor.fetchall()]

