def summarize_expiring_certificates(base_url: str, api_token: str, now: datetime, days: int) -> list[dict]:
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError('now must be timezone-aware')
    if isinstance(days, bool) or not isinstance(days, int) or days < 0:
        raise ValueError('days must be a non-negative integer')
    response = requests.get(base_url.rstrip('/') + '/api/v1/certificates', params={'limit': 1000}, headers={'Authorization': 'Bearer ' + api_token})
    if response.status_code != 200:
