    end = now + timedelta(days=days)
    groups = {}
    for certificate in data['certificates']:
        if certificate['status'] != 'active':
            continue
        value = certificate['expires_at']
        try:
            expires = datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value)
        except (TypeError, ValueError):
            raise ValueError('invalid certificate timestamp')
        if expires.tzinfo is None or expires.utcoffset() is None:
            raise ValueError('certificate timestamp must be timezone-aware')
        if now <= expires <= end:
            issuer = certificate['issuer']
            groups.setdefault(issuer, []).append((expires, certificate['serial']))
