def build_certification_manifest(records: list[dict], config: dict, page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(config, dict):
        raise TypeError('config must be a dictionary')
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('page must be positive')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('page_size must be positive')
    key = config.get('signing_key')
    if not isinstance(key, str) or not key:
        raise ValueError('signing_key is required')
    filtered = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('candidate'), str) or not record['candidate']:
            raise ValueError('invalid candidate')
        if not isinstance(record.get('certification'), str) or not record['certification']:
            raise ValueError('invalid certification')
        score = record.get('score')
        if not isinstance(score, int) or isinstance(score, bool) or (not 0 <= score <= 100):
            raise ValueError('invalid score')
        try:
            datetime.date.fromisoformat(record.get('completed_on', ''))
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if score >= 70:
            filtered.append(record)
    filtered.sort(key=lambda x: (-int(x['completed_on'].replace('-', '')), x['candidate'], x['certification']))
    total = len(filtered)
    average = round(sum((x['score'] for x in filtered)) / total, 2) if total else 0.0
    start = (page - 1) * page_size
    result = {'page': page, 'page_size': page_size, 'total': total, 'average_score': average, 'records': filtered[start:start + page_size]}
    raw = json.dumps(result, sort_keys=True, separators=(',', ':')).encode()
    result['signature'] = hmac.new(key.encode(), raw, hashlib.sha256).hexdigest()
    return result

