_FIELDS = ['subject', 'start', 'end', 'duration', 'priority', 'modalities']

def build_schedule(records: list[dict], subject_order: list[str], session_gap: int=5) -> list[dict]:
    if not isinstance(session_gap, int) or isinstance(session_gap, bool) or session_gap < 0:
        raise ValueError('invalid gap')
    if len(subject_order) != len(set(subject_order)) or any((not isinstance(x, str) for x in subject_order)):
        raise ValueError('invalid subject order')
    allowed = set(subject_order)
    grouped = {x: [] for x in subject_order}
    required = {'subject', 'start', 'duration', 'priority', 'modality'}
    for number, record in enumerate(records):
        if set(record) != required:
            raise ValueError('invalid record')
        if not isinstance(record['subject'], str) or record['subject'] not in allowed or (not isinstance(record['modality'], str)) or (not isinstance(record['start'], int)) or isinstance(record['start'], bool) or (record['start'] < 0) or (not isinstance(record['duration'], int)) or isinstance(record['duration'], bool) or (record['duration'] <= 0) or (not isinstance(record['priority'], int)) or isinstance(record['priority'], bool):
            raise ValueError('invalid record')
        grouped[record['subject']].append((record['start'], -record['priority'], record['modality'], number, record))
    result = []
    for subject in subject_order:
        items = sorted(grouped[subject])
        current = None
        for _, _, _, _, record in items:
            start = record['start']
            end = start + record['duration']
            if current is None or start > current['end'] + session_gap:
                if current is not None:
                    current['duration'] = current['end'] - current['start']
                    current['modalities'] = ','.join(sorted(current.pop('_modalities')))
                    result.append(current)
                current = {'subject': subject, 'start': start, 'end': end, 'duration': 0, 'priority': record['priority'], '_modalities': {record['modality']}}
            else:
                current['end'] = max(current['end'], end)
                current['priority'] = max(current['priority'], record['priority'])
                current['_modalities'].add(record['modality'])
        if current is not None:
            current['duration'] = current['end'] - current['start']
            current['modalities'] = ','.join(sorted(current.pop('_modalities')))
            result.append(current)
    return result

