    try:
        with open(source, encoding='utf-8', newline='') as handle:
            reader = csv.DictReader(handle)
            if reader.fieldnames != _FIELDS:
                raise ValueError('invalid header')
            result = []
            for row in reader:
                if None in row or any((row[x] is None for x in _FIELDS)):
                    raise ValueError('invalid row')
                try:
                    start = int(row['start'])
                    end = int(row['end'])
                    duration = int(row['duration'])
                    priority = int(row['priority'])
                except (TypeError, ValueError):
                    raise ValueError('invalid integer')
                if end - start != duration:
                    raise ValueError('invalid duration')
                result.append({'subject': row['subject'], 'start': start, 'end': end, 'duration': duration, 'priority': priority, 'modalities': row['modalities']})
            return result
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc

