import math
from lxml import etree

def _read(xml_text):
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        return etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def _date(value):
    try:
        return date.fromisoformat(value.strip())
    except Exception as exc:
        raise ValueError('invalid date') from exc

def parse_membership_feed(xml_text: str) -> list[dict]:
    root = _read(xml_text)
    if root.tag != 'feed':
        raise ValueError('invalid root')
    result, seen = ([], set())
    for node in root:
        if node.tag != 'member':
            raise ValueError('unexpected element')
        attrs = {k: v.strip() for k, v in node.attrib.items()}
        mid, tier, start = (attrs.get('id', ''), attrs.get('tier', ''), attrs.get('start', ''))
        if not mid or not tier or (not start) or (mid in seen):
            raise ValueError('invalid member')
        sd = _date(start)
        end = attrs.get('end')
        ed = _date(end) if end else None
        if ed and ed < sd:
            raise ValueError('invalid range')
        name = email = None
        interests, payments = ([], [])
        for child in node:
            if child.tag == 'name' and name is None:
                name = (child.text or '').strip()
            elif child.tag == 'email' and email is None:
                email = (child.text or '').strip()
            elif child.tag == 'interest':
                value = (child.text or '').strip()
                if value:
                    interests.append(value)
            elif child.tag == 'payment':
                pd = child.attrib.get('date', '').strip()
                amount = child.attrib.get('amount', '').strip()
                _date(pd)
                try:
                    number = float(Decimal(amount))
                except (InvalidOperation, ValueError):
                    raise ValueError('invalid amount')
                if not math.isfinite(number) or number < 0:
                    raise ValueError('invalid amount')
                payments.append({'date': pd, 'amount': round(number, 2)})
            else:
                raise ValueError('unexpected element')
        if not name or not email:
            raise ValueError('missing member data')
        seen.add(mid)
        result.append({'id': mid, 'name': name, 'email': email, 'tier': tier, 'start': start, 'end': end, 'interests': interests, 'payments': payments})
    return result

def _active(member, day):
    start = _date(member['start'])
    end = _date(member['end']) if member['end'] else None
    return start <= day and (end is None or day <= end)

def calculate_balances(xml_text: str, as_of: str) -> dict[str, float]:
    target = _date(as_of)
    rates = {'standard': 25.0, 'patron': 50.0, 'student': 10.0, 'lifetime': 0.0}
    output = {}
    for member in parse_membership_feed(xml_text):
        if member['tier'] not in rates:
            raise ValueError('unknown tier')
        total = 0.0
        for month in range(1, 13):
            first = date(target.year, month, 1)
            last = date(target.year + (month == 12), 1 if month == 12 else month + 1, 1)
            last = date.fromordinal(last.toordinal() - 1)
            if _active(member, first) or _active(member, last):
                total += rates[member['tier']]
        paid = sum((p['amount'] for p in member['payments'] if _date(p['date']).year == target.year))
        output[member['id']] = round(total - paid, 2)
    return output

def rank_interests(xml_text: str, as_of: str, limit: int) -> list[dict]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('invalid limit')
    day = _date(as_of)
    counts, display = ({}, {})
    for member in parse_membership_feed(xml_text):
        if not _active(member, day):
            continue
        names = set()
        for interest in member['interests']:
            key = interest.strip().casefold()
            if key and key not in names:
                names.add(key)
                display.setdefault(key, interest.strip())
        for key in names:
            counts[key] = counts.get(key, 0) + 1
    keys = sorted(counts, key=lambda k: (-counts[k], display[k].casefold()))
    return [{'interest': display[k], 'members': counts[k]} for k in keys[:limit]]

