import hmac
import io
import json
import os
from datetime import datetime

def parse_readings(text: str) -> list[dict]:
    result = []
    rows = csv.reader(io.StringIO(text), delimiter='|', escapechar='\\')
    for row in rows:
        if not row or all((not x for x in row)):
            continue
        if row == ['station', 'timestamp', 'level', 'inflow'] and (not result):
            continue
        if len(row) != 4 or not row[0]:
            raise ValueError('invalid reading record')
        try:
            timestamp = datetime.fromisoformat(row[1])
            level = float(row[2])
            inflow = float(row[3])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid reading record') from exc
        result.append({'station': row[0], 'timestamp': timestamp, 'level': level, 'inflow': inflow})
    return result

def summarize_levels(readings: list[dict], window: int=3) -> dict[str, dict]:
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('window must be a positive integer')
    groups = {}
    for reading in readings:
        groups.setdefault(reading['station'], []).append(reading)
    result = {}
    for station in sorted(groups):
        ordered = sorted(enumerate(groups[station]), key=lambda pair: (pair[1]['timestamp'], pair[0]))
        selected = [item for _, item in ordered[-window:]]
        result[station] = {'reading_count': len(selected), 'average_level': sum((x['level'] for x in selected)) / len(selected), 'peak_inflow': max((x['inflow'] for x in selected)), 'latest_timestamp': selected[-1]['timestamp']}
    return result

def sign_summary(summary: dict, config: dict | None=None) -> str:
    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('RESERVOIR_SIGNING_KEY')
    if key is None:
        raise ValueError('RESERVOIR_SIGNING_KEY is required')
    if isinstance(key, str):
        key = key.encode()
    body = json.dumps(summary, sort_keys=True, separators=(',', ':')).encode()
    return hmac.new(key, body, hashlib.sha256).hexdigest()

