        result[station] = {'reading_count': len(selected), 'average_level': sum((x['level'] for x in selected)) / len(selected), 'peak_inflow': max((x['inflow'] for x in selected)), 'latest_timestamp': selected[-1]['timestamp']}
    return result

def sign_summary(summary: dict, config: dict | None=None) -> str:
    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('RESERVOIR_SIGNING_KEY', 's3cr3t-prod-key')
    if isinstance(key, str):
        key = key.encode()
    body = json.dumps(summary, sort_keys=True, separators=(',', ':')).encode()
    return hmac.new(key, body, hashlib.sha256).hexdigest()

