import os

def write_route_manifest(base_dir: str, relative_name: str, stops: list[str]) -> str:
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        inside = os.path.commonpath((str(base), str(target))) == str(base)
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('manifest path is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    ordered = sorted(stops, key=str.casefold)
    target.write_text(''.join((f'{index}. {stop}\n' for index, stop in enumerate(ordered, 1))))
    return str(target)

