def parse_consents(xml_text: str) -> list[tuple[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('malformed XML') from exc
    result = []
    for element in root.iter('consent'):
        status = element.attrib.get('status')
        if status not in {'granted', 'denied'}:
            raise ValueError('invalid status')
        if status == 'granted':
            result.append((element.attrib['user'], element.attrib['purpose']))
    return sorted(result)

