def parse_incident_report(xml_text: str, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    try:
        root = etree.fromstring(xml_text.encode(), parser=etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'report':
        raise ValueError('invalid root')
    ranks = {'critical': 0, 'high': 1, 'medium': 2, 'low': 3}
    records = []
    seen = set()
    for node in root.findall('incident'):
        ident = node.get('id')
        values = {name: node.findtext(name) for name in ('vessel', 'severity', 'fatalities', 'status', 'date')}
        if not ident or any((values[k] is None or not values[k].strip() for k in values)):
            raise ValueError('missing incident data')
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        severity = values['severity'].strip()
        if severity not in ranks:
            raise ValueError('invalid severity')
        try:
            fatalities = int(values['fatalities'].strip())
        except Exception as exc:
            raise ValueError('invalid fatalities') from exc
        if fatalities < 0 or str(fatalities) != values['fatalities'].strip():
            raise ValueError('invalid fatalities')
        datestr = values['date'].strip()
        try:
            parsed_date = date.fromisoformat(datestr)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if parsed_date.isoformat() != datestr:
            raise ValueError('invalid date')
        records.append({'id': ident, 'vessel': values['vessel'].strip(), 'severity': severity, 'fatalities': fatalities, 'status': values['status'].strip(), 'date': datestr, '_rank': ranks[severity], '_date': parsed_date})
    records.sort(key=lambda x: (x['_rank'], -x['_date'].toordinal(), x['id']))
    counts = {level: 0 for level in ranks}
    for item in records:
        counts[item['severity']] += 1
    total = sum((item['fatalities'] for item in records))
    start = (page - 1) * page_size
    output = []
    for item in records[start:start + page_size]:
        output.append({k: item[k] for k in ('id', 'vessel', 'severity', 'fatalities', 'status', 'date')})
    return {'total_incidents': len(records), 'total_fatalities': total, 'average_fatalities': round(total / len(records), 2) if records else 0.0, 'by_severity': counts, 'incidents': output}

