import pytest


def make_payload(tickets, teams):
    return json.dumps({"tickets": tickets, "teams": teams}, separators=(",", ":")).encode()


def sign(payload, key_id="primary", key=b"secret"):
    digest = hmac.new(key, payload, hashlib.sha256).hexdigest()
    return key_id + ":" + digest


def ticket(i, team="payments", severity="medium", created="2025-01-01T00:00:00Z", tags=None):
    return {"id": i, "team": team, "severity": severity, "created": created, "tags": [] if tags is None else tags}


def test_routes_and_sorts_by_all_tiebreakers():
    teams = {"payments": "queue-b", "auth": "queue-a"}
    data = [
        ticket("z", "payments", "low", "2025-01-01T00:00:01Z"),
        ticket("b", "auth", "critical", "2025-01-02T00:00:00Z", ["prod"]),
        ticket("a", "auth", "critical", "2025-01-01T00:00:00Z"),
        ticket("h", "payments", "high"),
    ]
    payload = make_payload(data, teams)
    result = route_incident_batch(payload, sign(payload), {"primary": b"secret"})
    assert [x["id"] for x in result["tickets"]] == ["a", "b", "h", "z"]
    assert result["tickets"][0]["queue"] == "queue-a"
    assert result["tickets"][0]["sla_hours"] == 1
    assert result["tickets"][2]["sla_hours"] == 4
    assert result["tickets"][3]["sla_hours"] == 72
    assert result["tickets"][1]["tags"] == ["prod"]


