    secrets = {"old": b"one", "new": b"two"}
    assert route_incident_batch(payload, sign(payload, "new", b"two"), secrets) == {"tickets": [], "summary": {}}
    with pytest.raises(ValueError):
        route_incident_batch(payload, sign(payload, "old", b"one").upper(), secrets)


