import hashlib
import hmac
import json
from datetime import datetime

def _verify(payload, signature, secrets):
    if not isinstance(signature, str) or signature.count(':') != 1:
        raise ValueError('invalid signature')
    key_id, supplied = signature.split(':')
    if not key_id or key_id not in secrets or len(supplied) != 64:
        raise ValueError('invalid signature')
    try:
        int(supplied, 16)
    except ValueError:
        raise ValueError('invalid signature')
    expected = hmac.new(secrets[key_id], payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')

def _date(value):
    if not isinstance(value, str) or len(value) != 20 or (not value.endswith('Z')):
        raise ValueError('invalid date')
    try:
        datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        raise ValueError('invalid date')

def route_incident_batch(payload: bytes, signature: str, secrets: dict[str, bytes]) -> dict[str, object]:
    _verify(payload, signature, secrets)
    try:
        root = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(root, dict) or not isinstance(root.get('tickets'), list) or (not isinstance(root.get('teams'), dict)):
        raise ValueError('invalid payload')
    teams = root['teams']
    if any((not isinstance(k, str) or not k or (not isinstance(v, str)) or (not v) for k, v in teams.items())):
        raise ValueError('invalid teams')
    ranks = {'critical': (0, 1), 'high': (1, 4), 'medium': (2, 24), 'low': (3, 72)}
    seen = set()
    output = []
    for item in root['tickets']:
        if not isinstance(item, dict) or set(item) != {'id', 'team', 'severity', 'created', 'tags'}:
            raise ValueError('invalid ticket')
        ident, team, severity, created, tags = (item[x] for x in ('id', 'team', 'severity', 'created', 'tags'))
        if not all((isinstance(x, str) and x for x in (ident, team, created))) or severity not in ranks or team not in teams:
            raise ValueError('invalid ticket')
        if ident in seen or not isinstance(tags, list) or any((not isinstance(x, str) for x in tags)):
            raise ValueError('invalid ticket')
        _date(created)
        seen.add(ident)
        output.append({'id': ident, 'team': team, 'severity': severity, 'created': created, 'tags': list(tags), 'queue': teams[team], 'sla_hours': ranks[severity][1]})
    output.sort(key=lambda x: (ranks[x['severity']][0], x['created'], x['id']))
    summary = {q: 0 for q in sorted(teams.values())}
    for item in output:
        summary[item['queue']] += 1
    return {'tickets': output, 'summary': summary}

