import os
import json
import requests

def _split_escaped(value, separator):
    parts = []
    current = []
    escaped = False
    for char in value:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == separator:
            parts.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    parts.append(''.join(current))
    return parts

def parse_permits(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_escaped(raw, '|')
        if len(fields) != 5 or not fields[0] or (not fields[1]):
            raise ValueError('invalid permit row')
        try:
            amount = float(fields[2])
        except ValueError:
            raise ValueError('invalid amount')
        if amount < 0 or fields[3] not in {'pending', 'approved', 'rejected'}:
            raise ValueError('invalid permit data')
        tags = [x for x in _split_escaped(fields[4], ',') if x]
        result.append({'id': fields[0], 'county': fields[1], 'amount': amount, 'status': fields[3], 'tags': tags})
    return result

def summarize_permits(applications: list[dict]) -> dict:
    groups = {}
    for app in applications:
        group = groups.setdefault(app['county'], {'total': 0.0, 'count': 0, 'approved': 0, 'rejected': 0, 'tags': set()})
        group['total'] += app['amount']
        group['count'] += 1
        group['approved'] += app['status'] == 'approved'
        group['rejected'] += app['status'] == 'rejected'
        group['tags'].update(app['tags'])
    counties = [{'county': name, 'total_amount': round(g['total'], 2), 'count': g['count'], 'approved_count': g['approved'], 'rejected_count': g['rejected'], 'tags': sorted(g['tags'])} for name, g in groups.items()]
    counties.sort(key=lambda x: (-x['total_amount'], x['county']))
    return {'counties': counties, 'grand_total': round(sum((x['amount'] for x in applications)), 2), 'application_count': len(applications)}

def submit_permit_summary(text: str, endpoint: str, config: dict | None=None) -> dict:
    config = config or {}
    token = config.get('api_token') or os.environ.get('PERMIT_API_TOKEN')
    if not token:
        raise RuntimeError('PERMIT_API_TOKEN is not configured')
    summary = summarize_permits(parse_permits(text))
    response = requests.post(endpoint, data=json.dumps(summary), headers={'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token}, timeout=10)
    response.raise_for_status()
    return response.json()

