def create_invite(code: str, candidate: str, slot: str) -> dict:
    if not isinstance(code, str) or not isinstance(candidate, str):
        raise TypeError()
    if not code.isascii() or not code.isdigit() or (not 4 <= len(code) <= 12):
        raise ValueError()
    candidate = candidate.strip()
    if not candidate:
        raise ValueError()
    try:
        normalized = datetime.fromisoformat(slot).isoformat()
    except (TypeError, ValueError):
        raise ValueError()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000).hex()
    return {'candidate': candidate, 'slot': normalized, 'credential': {'salt': salt.hex(), 'digest': digest}}

def verify_invite(code: str, invite: dict) -> bool:
    if not isinstance(code, str) or not code.isascii() or (not code.isdigit()) or (not 4 <= len(code) <= 12):
        return False
    if not isinstance(invite, dict) or not isinstance(invite.get('credential'), dict):
        return False
    credential = invite['credential']
    try:
        salt = bytes.fromhex(credential['salt'])
        expected = credential['digest']
        actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000).hex()
        return isinstance(expected, str) and __import__('hmac').compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def schedule_page(invites: list[dict], day: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(day, str):
        raise ValueError()
    try:
        target = datetime.strptime(day, '%Y-%m-%d').date()
    except ValueError:
        raise ValueError()
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError()
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError()
    groups = {}
    for item in invites:
        if not isinstance(item, dict) or not isinstance(item.get('candidate'), str) or (not item['candidate'].strip()):
            continue
        try:
            parsed = datetime.fromisoformat(item['slot'])
        except (TypeError, ValueError):
            continue
        if parsed.date() == target:
            slot = parsed.isoformat()
            groups.setdefault(slot, set()).add(item['candidate'])
    result = [{'slot': slot, 'candidates': sorted(groups[slot])} for slot in sorted(groups)]
    start = (page - 1) * page_size
    return result[start:start + page_size]

