def parse_feedback(xml_text: str) -> list[dict]:
    if not isinstance(xml_text, str):
        raise ValueError('XML must be text')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feedback':
        raise ValueError('invalid root')
    result = []
    ids = set()
    allowed = {'id', 'product', 'rating', 'submitted'}
    for node in root:
        if node.tag != 'item' or set(node.attrib) != allowed:
            raise ValueError('invalid item')
        ident, product = (node.get('id', '').strip(), node.get('product', '').strip())
        if not ident or not product or ident in ids:
            raise ValueError('invalid identity')
        try:
            rating = int(node.get('rating'))
            submitted = date.fromisoformat(node.get('submitted'))
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if not 1 <= rating <= 5:
            raise ValueError('invalid rating')
        children = {}
        for child in node:
            if child.tag not in {'title', 'comment', 'tags'} or child.tag in children:
                raise ValueError('invalid children')
            children[child.tag] = child
        if 'title' not in children or 'comment' not in children:
            raise ValueError('missing text')
        text = lambda x: ''.join(x.itertext()).strip()
        title, comment = (text(children['title']), text(children['comment']))
        if not title or not comment:
            raise ValueError('empty text')
        tags = []
        if 'tags' in children:
            for tag in children['tags']:
                if tag.tag != 'tag':
                    raise ValueError('invalid tag')
                value = text(tag).lower()
                if value and value not in tags:
                    tags.append(value)
        ids.add(ident)
        result.append({'id': ident, 'product': product, 'rating': rating, 'submitted': submitted.isoformat(), 'title': title, 'comment': comment, 'tags': tags})
    return result

def summarize_feedback(feedback: list[dict]) -> dict:
    groups = {}
    total = 0
    for item in feedback:
        product = item['product']
        group = groups.setdefault(product, {'count': 0, 'sum': 0, 'counts': [0] * 5, 'latest': ''})
        group['count'] += 1
        group['sum'] += item['rating']
        group['counts'][item['rating'] - 1] += 1
        group['latest'] = max(group['latest'], item['submitted'])
        total += item['rating']
    products = []
    for product in sorted(groups):
        group = groups[product]
        products.append({'product': product, 'count': group['count'], 'average_rating': round(group['sum'] / group['count'], 2), 'rating_counts': {str(i): group['counts'][i - 1] for i in range(1, 6)}, 'latest': group['latest']})
    return {'overall': {'count': sum((g['count'] for g in groups.values())), 'average_rating': round(total / sum((g['count'] for g in groups.values())), 2) if groups else 0.0}, 'products': products}

