        if not all((field in issue for field in fields)):
            raise ValueError('missing field')
        if not isinstance(issue['id'], str) or not issue['id'] or (not isinstance(issue['title'], str)) or (not isinstance(issue['created_at'], str)) or (not isinstance(issue['owner'], str)):
            raise ValueError('invalid field')
        if issue['status'] not in {'open', 'in_progress', 'closed'} or type(issue['severity']) is not int or (not 1 <= issue['severity'] <= 5):
            raise ValueError('invalid field')
        if (statuses is None or issue['status'] in statuses) and issue['severity'] >= min_severity:
            selected.append(issue)
    selected.sort(key=lambda x: (-x['severity'], x['created_at'], x['id']))
