import pytest

def test_evaluate_arithmetic_variables_and_precedence():
    values = {'hours': 12, 'progress': 0.5, 'priority': 3}
    assert evaluate_expression('hours * (1 - progress) + priority', values) == 9.0
    assert evaluate_expression('hours / 5', values) == 2.4
    assert evaluate_expression('-priority + +2', values) == -1

def test_evaluate_boolean_comparisons_and_short_circuit():
    values = {'hours': 8, 'progress': 0.75, 'priority': 2}
    assert evaluate_expression('hours >= 8 and progress < 1', values) is True
    assert evaluate_expression('hours < 0 or priority == 2', values) is True
    assert evaluate_expression('1 < hours < 10', values) is True
    assert evaluate_expression('not (progress == 0)', values) is True

def test_evaluate_named_functions_and_rounding():
    values = {'hours': 11, 'progress': 0.666, 'priority': 4}
    assert evaluate_expression('min(hours, 10, priority)', values) == 4
    assert evaluate_expression('max(hours, priority * 3)', values) == 12
    assert evaluate_expression('round(progress * 10)', values) == 7
    assert evaluate_expression('round(progress, 2)', values) == 0.67

def test_evaluate_unknown_name_and_invalid_syntax():
    with pytest.raises(NameError):
        evaluate_expression('hours + missing', {'hours': 2})
    with pytest.raises((SyntaxError, ValueError)):
        evaluate_expression('hours +', {'hours': 2})

