import csv
import datetime
import os
import tempfile

def parse_shifts(text: str) -> list[dict[str, object]]:
    rows = list(csv.reader(text.splitlines()))
    if not rows or rows[0] != ['employee', 'date', 'start', 'end', 'role']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid row')
        employee, dates, starts, ends, role = [x.strip() for x in row]
        if not employee or not role:
            raise ValueError('empty field')
        try:
            day = datetime.date.fromisoformat(dates)
            start = datetime.time.fromisoformat(starts)
            end = datetime.time.fromisoformat(ends)
        except ValueError as exc:
            raise ValueError('invalid date or time') from exc
        if end <= start:
            raise ValueError('invalid duration')
        result.append({'employee': employee, 'date': day, 'start': start, 'end': end, 'role': role})
    return result

def summarize_shifts(shifts: list[dict[str, object]]) -> list[tuple[str, float, int]]:
    totals = {}
    for item in shifts:
        if set(item) != {'employee', 'date', 'start', 'end', 'role'}:
            raise ValueError('invalid shift')
        employee = item['employee']
        day = item['date']
        start = item['start']
        end = item['end']
        role = item['role']
        if not isinstance(employee, str) or not employee or (not isinstance(day, datetime.date)) or isinstance(day, datetime.datetime) or (not isinstance(start, datetime.time)) or (not isinstance(end, datetime.time)) or (not isinstance(role, str)) or (not role) or (end <= start):
            raise ValueError('invalid shift')
        hours = (end.hour * 3600 + end.minute * 60 + end.second - start.hour * 3600 - start.minute * 60 - start.second) / 3600
        old = totals.get(employee, [0.0, 0])
        old[0] += hours
        old[1] += 1
        totals[employee] = old
    result = [(name, round(value[0] + 1e-10, 2), value[1]) for name, value in totals.items()]
    result.sort(key=lambda x: (-x[1], x[0]))
    return result

def export_summary(text: str, destination: str) -> list[tuple[str, float, int]]:
    summary = summarize_shifts(parse_shifts(text))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.schedule-', suffix='.csv', dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['employee', 'total_hours', 'shift_count'])
            for employee, hours, count in summary:
                writer.writerow([employee, f'{hours:.2f}', count])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return summary

