        raise TypeError('assignments must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(per_page, int) or isinstance(per_page, bool) or (not 1 <= per_page <= 100):
        raise ValueError('invalid per_page')
    statuses = {'draft', 'assigned', 'filed'}
    seen = set()
    clean = []
    for item in assignments:
        if not isinstance(item, dict):
            raise TypeError('assignment must be a dictionary')
        required = ('id', 'title', 'reporter', 'desk', 'status', 'minutes', 'due')
        if any((key not in item for key in required)):
            raise ValueError('missing field')
        ident = item['id']
        if not isinstance(ident, int) or isinstance(ident, bool) or ident <= 0 or (ident in seen):
            raise ValueError('invalid id')
        if not all((isinstance(item[key], str) and item[key] for key in ('title', 'reporter', 'desk'))):
            raise ValueError('invalid text')
        if item['status'] not in statuses:
            raise ValueError('invalid status')
        if not isinstance(item['minutes'], int) or isinstance(item['minutes'], bool) or item['minutes'] < 0:
            raise ValueError('invalid minutes')
        if not isinstance(item['due'], str):
            raise ValueError('invalid date')
        try:
            date.fromisoformat(item['due'])
        except ValueError:
            raise ValueError('invalid date')
        seen.add(ident)
        clean.append(item)
    clean.sort(key=lambda x: (x['desk'].casefold(), x['due'], x['id']))
    total = len(clean)
