import xml.etree.ElementTree as ET

def summarize_registry(xml_text: str, page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be a string')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, ValueError, TypeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'registry':
        raise ValueError('invalid root')
    allowed = {'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'}
    groups = {}
    for item in root:
        if item.tag != 'donation':
            raise ValueError('invalid child')
        required = ('donor_id', 'organ', 'blood_type', 'units', 'status')
        if any((name not in item.attrib for name in required)):
            raise ValueError('missing attribute')
        donor = item.attrib['donor_id']
        organ = item.attrib['organ']
        blood = item.attrib['blood_type']
        status = item.attrib['status']
        if not donor or not organ or blood not in allowed or (status not in {'active', 'paused'}):
            raise ValueError('invalid attribute')
        try:
            units = int(item.attrib['units'])
        except ValueError as exc:
            raise ValueError('invalid units') from exc
        if units < 1 or units > 10:
            raise ValueError('invalid units')
        if status == 'active':
            key = (organ, blood)
            if key not in groups:
                groups[key] = {'donors': set(), 'units': 0}
            groups[key]['donors'].add(donor)
            groups[key]['units'] += units
    result = [{'organ': organ, 'blood_type': blood, 'donor_count': len(data['donors']), 'units': data['units']} for (organ, blood), data in groups.items()]
    result.sort(key=lambda row: (-row['units'], row['organ'], row['blood_type']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

