def build_billing_history(requester: dict, account: dict, start: str, end: str, page: int, page_size: int) -> dict:
    if not isinstance(requester, dict) or not isinstance(account, dict):
        raise ValueError('invalid data')
    if not isinstance(start, str) or not isinstance(end, str) or (not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', start)) or (not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', end)) or (start > end):
        raise ValueError('invalid range')
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    if requester.get('tenant_id') != account.get('tenant_id') or (requester.get('id') != account.get('owner_id') and 'billing_admin' not in requester.get('roles', [])):
        raise PermissionError('not allowed')
    entries = account.get('entries')
    if not isinstance(entries, list) or 'account_id' not in account:
        raise ValueError('invalid account')
    grouped = {}
    for item in entries:
        if not isinstance(item, dict) or not isinstance(item.get('month'), str) or (not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', item['month'])) or (item['kind'] not in ('charge', 'refund')) or (type(item.get('amount_cents')) is not int) or (item['amount_cents'] <= 0) or (not isinstance(item.get('description'), str)):
            raise ValueError('invalid entry')
        if start <= item['month'] <= end:
            row = grouped.setdefault(item['month'], [0, 0])
            row[0] += item['amount_cents'] if item['kind'] == 'charge' else -item['amount_cents']
            row[1] += 1
    months = sorted(grouped, reverse=True)
    first = (page - 1) * page_size
    output = [{'month': m, 'amount_cents': grouped[m][0], 'items': grouped[m][1]} for m in months[first:first + page_size]]
    return {'account_id': account['account_id'], 'total': len(months), 'page': page, 'page_size': page_size, 'entries': output}

