import subprocess

def build_media_list(paths: list[str], region: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if not paths or page < 1 or page_size < 1:
        raise ValueError('invalid arguments')
    result = subprocess.run(['cat', *paths], capture_output=True, text=True, check=True)
    records = []
    wanted = region.strip().casefold() if region is not None else None
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = [part.strip() for part in line.split(',')]
        if len(fields) != 5:
            continue
        outlet, area, contact, email, raw_reach = fields
        try:
            reach = int(raw_reach)
        except ValueError:
            continue
        if reach < 0 or (wanted is not None and area.casefold() != wanted):
            continue
        records.append({'outlet': outlet, 'region': area, 'contact': contact, 'email': email, 'monthly_reach': reach})
    chosen = {}
    for record in records:
        key = record['email'].casefold()
        if key not in chosen or record['monthly_reach'] > chosen[key]['monthly_reach']:
            chosen[key] = record
    ordered = sorted(chosen.values(), key=lambda item: (-item['monthly_reach'], item['outlet'].casefold(), item['contact'].casefold(), item['email'].casefold()))
    start = (page - 1) * page_size
    return ordered[start:start + page_size]

