def parse_availability(text: str) -> list[tuple[int, int]]:
    if not text.strip():
        return []
    result = []
    for item in text.split(';'):
        parts = item.strip().split('-')
        if len(parts) != 2:
            raise ValueError('invalid interval')
        try:
            start, end = (int(x.strip()) for x in parts)
        except ValueError:
            raise ValueError('invalid interval')
        if start < 0 or end < 0 or start >= end:
            raise ValueError('invalid interval')
        result.append((start, end))
    return result

def rank_candidates(engagement: dict, candidates: list[dict], availability: dict[str, str]) -> list[dict]:
    required = set(engagement['required_skills'])
    start, end = (engagement['start_hour'], engagement['end_hour'])
    eligible = []
    for candidate in candidates:
        if candidate['hourly_rate'] > engagement['max_rate'] or not required.issubset(candidate['skills']):
            continue
        intervals = parse_availability(availability.get(candidate['candidate_id'], ''))
        if any((a <= start and b >= end for a, b in intervals)):
            eligible.append(candidate)
    return sorted(eligible, key=lambda c: (c['hourly_rate'], -len(required.intersection(c['skills'])), -c['years_experience'], c['candidate_id']))

def confirm_assignment(requester: dict, engagement: dict, candidate_id: str, candidates: list[dict], assignments: list[dict]) -> dict:
    if requester['tenant_id'] != engagement['tenant_id'] or (requester['id'] != engagement['owner_id'] and 'admin' not in requester['roles']):
        raise PermissionError('not permitted')
    candidate = next((c for c in candidates if c['candidate_id'] == candidate_id), None)
    if candidate is None:
        raise KeyError(candidate_id)
    if engagement['start_hour'] >= engagement['end_hour']:
        raise ValueError('invalid engagement')
    if candidate['hourly_rate'] > engagement['max_rate'] or not set(engagement['required_skills']).issubset(candidate['skills']):
        raise ValueError('candidate is not qualified')
    intervals = parse_availability(candidate['availability'])
    if not any((a <= engagement['start_hour'] and b >= engagement['end_hour'] for a, b in intervals)):
        raise ValueError('candidate is unavailable')
    for old in assignments:
        if old['candidate_id'] == candidate_id and old['start_hour'] < engagement['end_hour'] and (engagement['start_hour'] < old['end_hour']):
            raise ValueError('overlap')
    result = {'engagement_id': engagement['id'], 'candidate_id': candidate_id, 'start_hour': engagement['start_hour'], 'end_hour': engagement['end_hour'], 'hourly_rate': candidate['hourly_rate']}
    assignments.append(result)
    return result

