    if any((not isinstance(holdings[s], (int, float)) or holdings[s] < 0 or (not isinstance(prices[s], (int, float))) or (prices[s] <= 0) or (not isinstance(targets[s], (int, float))) or (not 0 <= targets[s] <= 1) for s in symbols)) or abs(sum(targets.values()) - 1) > 1e-09:
        raise ValueError('invalid values')
    total = cash + sum((holdings[s] * prices[s] for s in symbols))
    orders = []
    for s in symbols:
        difference = total * targets[s] - holdings[s] * prices[s]
        quantity = difference / prices[s]
        if abs(quantity) >= 1e-06:
            rounded = round(quantity, 6)
            orders.append((abs(difference), s, {'symbol': s, 'action': 'BUY' if quantity > 0 else 'SELL', 'quantity': rounded, 'value': round(rounded * prices[s], 2)}))
    orders.sort(key=lambda x: (-x[0], x[1]))
    start = (page - 1) * page_size
    return [x[2] for x in orders[start:start + page_size]]

