import hashlib
import hmac
import json
from datetime import datetime, timezone
from collections.abc import Mapping

def parse_observed_at(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('observed_at must be a UTC timestamp ending in Z')
    try:
        parsed = datetime.fromisoformat(value[:-1])
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid observed_at timestamp') from exc
    if parsed.tzinfo is not None:
        raise ValueError('observed_at must not contain an offset')
    return parsed.replace(tzinfo=timezone.utc)

def select_latest_devices(events: list[dict]) -> dict[str, dict]:
    selected = {}
    seen_times = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('event must be a dictionary')
        device_id = event.get('device_id')
        observed = event.get('observed_at')
        operating_system = event.get('os')
        checks = event.get('checks')
        if not isinstance(device_id, str) or not device_id:
            raise ValueError('device_id must be a non-empty string')
        timestamp = parse_observed_at(observed)
        if not isinstance(operating_system, str):
            raise ValueError('os must be a string')
        if not isinstance(checks, dict) or not checks:
            raise ValueError('checks must be a non-empty dictionary')
        if any((not isinstance(name, str) or not name or (not isinstance(value, bool)) for name, value in checks.items())):
            raise ValueError('checks must map names to booleans')
        old_time = seen_times.get(device_id)
        if old_time is None or timestamp >= old_time:
            selected[device_id] = dict(event)
            seen_times[device_id] = timestamp
    return selected

def build_compliance_report(events: list[dict], config: Mapping[str, str]) -> dict:
    if not isinstance(config, Mapping) or not isinstance(config.get('compliance_signing_key'), str):
        raise ValueError('compliance_signing_key is required')
    selected = select_latest_devices(events)
    devices = []
    for device_id, event in selected.items():
        checks = {name: event['checks'][name] for name in sorted(event['checks'])}
        devices.append({'device_id': device_id, 'os': event['os'], 'observed_at': parse_observed_at(event['observed_at']).isoformat().replace('+00:00', 'Z'), 'checks': checks, 'compliant': all(checks.values())})
    devices.sort(key=lambda item: (item['compliant'], item['device_id']))
    compliant = sum((item['compliant'] for item in devices))
    summary = {'total': len(devices), 'compliant': compliant, 'non_compliant': len(devices) - compliant}
    body = {'devices': devices, 'summary': summary}
    encoded = json.dumps(body, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    body['signature'] = hmac.new(config['compliance_signing_key'].encode('utf-8'), encoded, hashlib.sha256).hexdigest()
    return body

