    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('window must be positive')
    result = []
    for player_id, record in campaign.get('players', {}).items():
        scores = record['scores']
        if not scores:
            result.append((player_id, 0, -1))
            continue
        width = min(window, len(scores))
        best = sum(scores[:width])
        start = 0
        current = best
        for i in range(width, len(scores)):
            current += scores[i] - scores[i - width]
            candidate = i - width + 1
            if current > best:
                best, start = (current, candidate)
        result.append((player_id, best, start))
    return sorted(result, key=lambda item: (-item[1], item[0]))

