        first = write_file(directory, "morning.txt", 40)
        second = write_file(directory, "afternoon.txt", 41)
        result = summarize_daily_reports([first, second])
        assert result["total_files"] == 2
        assert result["total_lines"] == 81
        assert result["items"] == [
            {"name": "afternoon.txt", "lines": 41, "shooting_days": 2},
