        if not isinstance(path, str):
            raise TypeError('each path must be a string')
        result = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
        lines = int(result.stdout.split()[0])
        if lines >= minimum_lines:
            records.append((lines, os.path.basename(path), path))
