import csv
import datetime
import math
import os
import tempfile

def _rows(records, window_minutes):
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or (not 1 <= window_minutes <= 1440):
        raise ValueError('invalid window')
    groups = {}
    for r in records:
        try:
            animal = r['animal_id']
            stamp = r['timestamp']
            temp = float(r['temperature'])
            heart = float(r['heart_rate'])
            activity = float(r['activity'])
            if not isinstance(animal, str) or not animal or (not isinstance(stamp, str)) or (not stamp.endswith('Z')):
                raise ValueError
            dt = datetime.datetime.fromisoformat(stamp[:-1]).replace(tzinfo=datetime.timezone.utc)
            if not all((math.isfinite(x) for x in (temp, heart, activity))) or activity < 0:
                raise ValueError
        except (KeyError, TypeError, ValueError, OverflowError):
            raise ValueError('invalid record')
        seconds = int(dt.timestamp())
        start = datetime.datetime.fromtimestamp(seconds - seconds % (window_minutes * 60), datetime.timezone.utc)
        groups.setdefault((animal, start), []).append((temp, heart, activity))
    result = []
    for (animal, start), values in sorted(groups.items(), key=lambda x: (x[0][0], x[0][1])):
        temps = [x[0] for x in values]
        hearts = [x[1] for x in values]
        activities = [x[2] for x in values]
        at = round(sum(temps) / len(values), 2)
        ah = round(sum(hearts) / len(values), 2)
        result.append({'animal_id': animal, 'window_start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'samples': len(values), 'avg_temperature': at, 'avg_heart_rate': ah, 'peak_activity': round(max(activities), 2), 'status': 'ALERT' if at < 37.5 or at > 39.5 or ah > 100 else 'OK'})
    return result

def summarize_readings(records: list[dict], window_minutes: int) -> list[dict]:
    return _rows(records, window_minutes)

def export_health_report(records: list[dict], window_minutes: int, destination: str) -> int:
    rows = _rows(records, window_minutes)
    headers = ['animal_id', 'window_start', 'samples', 'avg_temperature', 'avg_heart_rate', 'peak_activity', 'status']
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.health-', suffix='.tmp', dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            writer = csv.writer(f, lineterminator='\n')
            writer.writerow(headers)
            for row in rows:
                writer.writerow([row[h] for h in headers])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

