def _check_state(state):
    if not isinstance(state, dict) or not isinstance(state.get('leases'), dict) or (not isinstance(state.get('history'), list)):
        raise ValueError('invalid state')
    for key, value in state['leases'].items():
        if not isinstance(key, str) or not isinstance(value, dict):
            raise ValueError('invalid lease')
        if not isinstance(value.get('owner'), str) or type(value.get('expires')) is not int or type(value.get('count')) is not int:
            raise ValueError('invalid lease')
    if any((not isinstance(x, str) for x in state['history'])):
        raise ValueError('invalid history')

def encode_state(state: dict) -> bytes:
    _check_state(state)
    try:
