def create_patient(patient_id: str, pin: str) -> dict:
    if not isinstance(patient_id, str) or not patient_id.strip():
        raise ValueError('invalid patient id')
    if not isinstance(pin, str) or not 4 <= len(pin) <= 32 or (not pin.strip()):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'patient_id': patient_id.strip(), 'credential': salt.hex() + '$' + digest.hex(), 'sessions': []}

def authenticate_patient(patient: dict, pin: str) -> bool:
    try:
        if not isinstance(pin, str):
            return False
        salt_text, digest_text = patient['credential'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def _parsed(value):
    try:
        if not isinstance(value, str) or len(value) != 10 or value[4] != '-' or (value[7] != '-'):
            raise ValueError
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def add_session(patient: dict, session_date: str, minutes: int, pain_before: int, pain_after: int, exercises: dict[str, int]) -> None:
    day = _parsed(session_date)
    if not isinstance(minutes, int) or isinstance(minutes, bool) or (not 1 <= minutes <= 600):
        raise ValueError('invalid minutes')
    if any((not isinstance(x, int) or isinstance(x, bool) or (not 0 <= x <= 10) for x in (pain_before, pain_after))):
        raise ValueError('invalid pain')
    if not isinstance(exercises, dict):
        raise ValueError('invalid exercises')
    clean = {}
    for name, count in exercises.items():
        if not isinstance(name, str) or not name.strip() or (not isinstance(count, int)) or isinstance(count, bool) or (not 1 <= count <= 10000):
            raise ValueError('invalid exercise')
        key = name.strip()
        clean[key] = clean.get(key, 0) + count
    if any((s.get('date') == session_date for s in patient.get('sessions', []))):
        raise ValueError('duplicate date')
    patient['sessions'].append({'date': day.isoformat(), 'minutes': minutes, 'pain_before': pain_before, 'pain_after': pain_after, 'exercises': clean})

