            item['count'] += 1
            item['minutes'] += session['minutes']
            item['before'] += session['pain_before']
            item['after'] += session['pain_after']
            for name, count in session['exercises'].items():
                item['exercises'][name] = item['exercises'].get(name, 0) + count
    result = []
