        exercises = dict(sorted(item['exercises'].items(), key=lambda x: (-x[1], x[0])))
        result.append({'week_start': monday.isoformat(), 'session_count': item['count'], 'total_minutes': item['minutes'], 'average_pain_before': round(item['before'] / item['count'], 2), 'average_pain_after': round(item['after'] / item['count'], 2), 'exercises': exercises})
    return result

