import tempfile

def export_events(events: list[dict[str, str]], destination: str) -> int:
    required = ('timestamp', 'event', 'user')
    for event in events:
        if any((key not in event for key in required)):
            raise ValueError('event is missing a required key')
    ordered = sorted(enumerate(events), key=lambda item: (item[1]['timestamp'], item[0]))
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.events-', dir=directory)
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(required)
            for _, event in ordered:
                writer.writerow([event[key] for key in required])
        os.replace(temporary, destination)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    return len(events)

