import json
import datetime

def _validate(events):
    if not isinstance(events, list):
        raise ValueError('events')
    required = {'title', 'date', 'community', 'capacity', 'attendees'}
    for item in events:
        if not isinstance(item, dict) or set(item) != required:
            raise ValueError('event')
        if not isinstance(item['title'], str) or not item['title']:
            raise ValueError('title')
        if not isinstance(item['community'], str) or not item['community']:
            raise ValueError('community')
        try:
            datetime.date.fromisoformat(item['date'])
        except (TypeError, ValueError):
            raise ValueError('date')
        if isinstance(item['capacity'], bool) or not isinstance(item['capacity'], int) or item['capacity'] <= 0:
            raise ValueError('capacity')
        if isinstance(item['attendees'], bool) or not isinstance(item['attendees'], int) or (not 0 <= item['attendees'] <= item['capacity']):
            raise ValueError('attendees')

def pack_events(events: list[dict]) -> bytes:
    _validate(events)
    return json.dumps(events, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def calendar_summary(blob: bytes, month: str, page: int=1, page_size: int=20) -> list[dict]:
    try:
        if not isinstance(month, str) or len(month) != 7 or month[4] != '-':
            raise ValueError
        datetime.date.fromisoformat(month + '-01')
        if not isinstance(page, int) or isinstance(page, bool) or page < 1:
            raise ValueError
        if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
            raise ValueError
        events = json.loads(blob.decode('utf-8'))
        _validate(events)
    except Exception as exc:
        raise ValueError('invalid calendar') from exc
    groups = {}
    for item in events:
        if item['date'][:7] == month:
            group = groups.setdefault(item['community'], [0, 0, 0])
            group[0] += 1
            group[1] += item['attendees']
            group[2] += item['capacity']
    result = [{'community': name, 'event_count': vals[0], 'attendees': vals[1], 'fill_rate': round(vals[1] * 100 / vals[2], 2)} for name, vals in groups.items()]
    result.sort(key=lambda x: (-x['event_count'], -x['attendees'], x['community']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

