import math
import secrets
from decimal import Decimal, ROUND_HALF_UP

def generate_commitment_access(commitment_id: str, requirements: list[dict], page: int=1, page_size: int=10, existing_codes: tuple[str, ...]=()) -> dict:
    if not isinstance(commitment_id, str) or not commitment_id:
        raise ValueError('invalid commitment_id')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page_size')
    clean = []
    for item in requirements:
        if not isinstance(item, dict):
            raise ValueError('invalid requirement')
        if not isinstance(item.get('category'), str) or not item['category']:
            raise ValueError('invalid category')
        if not isinstance(item.get('description'), str) or not item['description']:
            raise ValueError('invalid description')
        if item.get('status') not in ('open', 'closed'):
            raise ValueError('invalid status')
        amount = item.get('amount')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid amount')
        if item['status'] == 'open':
            clean.append((item['category'], item['description'], Decimal(str(amount))))
    clean.sort(key=lambda x: (x[0], -x[2], x[1]))
    quant = lambda value: value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    groups = {}
    for category, description, amount in clean:
        if category not in groups:
            groups[category] = [0, Decimal('0')]
        groups[category][0] += 1
        groups[category][1] += amount
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    while True:
        code = ''.join((secrets.choice(alphabet) for _ in range(12)))
        if code not in existing_codes:
            break
    start = (page - 1) * page_size
    selected = clean[start:start + page_size]
    return {'commitment_id': commitment_id, 'access_code': code, 'open_count': len(clean), 'open_amount': f"{quant(sum((x[2] for x in clean), Decimal('0'))):.2f}", 'categories': [{'category': k, 'count': v[0], 'amount': f'{quant(v[1]):.2f}'} for k, v in groups.items()], 'requirements': [{'category': c, 'description': d, 'amount': f'{quant(a):.2f}'} for c, d, a in selected]}

