import hmac
import os

def hash_inspector_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return 'pbkdf2$' + base64.urlsafe_b64encode(salt).decode() + '$' + digest.hex()

def verify_inspector_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        return False
    try:
        scheme, salt_text, digest_text = stored.split('$', 2)
        if scheme != 'pbkdf2':
            return False
        salt = base64.urlsafe_b64decode(salt_text.encode())
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_schedule(records: list[dict], inspection_date: str, page: int=1, page_size: int=20) -> list[dict]:
    try:
        parsed_date = datetime.date.fromisoformat(inspection_date)
    except (TypeError, ValueError):
        raise ValueError('invalid inspection date')
    if inspection_date != parsed_date.isoformat():
        raise ValueError('invalid inspection date')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('facility', 'inspector', 'date', 'minutes'))):
            raise ValueError('invalid record')
        if not all((isinstance(record[k], str) and record[k] for k in ('facility', 'inspector', 'date'))):
            raise ValueError('invalid record')
        try:
            record_date = datetime.date.fromisoformat(record['date'])
        except ValueError:
            raise ValueError('invalid record date')
        if record['date'] != record_date.isoformat():
            raise ValueError('invalid record date')
        if not isinstance(record['minutes'], int) or isinstance(record['minutes'], bool) or record['minutes'] <= 0:
            raise ValueError('invalid minutes')
        if record['date'] == inspection_date:
            item = groups.setdefault(record['inspector'], {'inspector': record['inspector'], 'visits': 0, 'minutes': 0, 'facilities': set()})
            item['visits'] += 1
            item['minutes'] += record['minutes']
            item['facilities'].add(record['facility'])
    result = []
    for item in groups.values():
        item['facilities'] = sorted(item['facilities'])
        result.append(item)
    result.sort(key=lambda x: (-x['minutes'], -x['visits'], x['inspector']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

