        raise ValueError('invalid length')
    return ''.join((secrets.choice(_CODE_ALPHABET) for _ in range(length)))

def settle_cafeteria_payments(entries: list[dict], tax_basis_points: int=875) -> list[dict]:
    if not isinstance(tax_basis_points, int) or isinstance(tax_basis_points, bool) or tax_basis_points < 0:
        raise ValueError('invalid tax')
    groups = {}
    seen = set()
    required = {'payment_id', 'patient', 'date', 'item', 'quantity', 'unit_price_cents'}
