    ids = set()
    keys = {'id', 'user', 'rating', 'comment', 'tags', 'timestamp'}
    for item in data:
        if not isinstance(item, dict) or set(item) != keys:
            raise ValueError('invalid record')
        if any((not isinstance(item[k], str) or not item[k] for k in ('id', 'user', 'comment'))):
            raise ValueError('invalid text')
        if item['id'] in ids or isinstance(item['rating'], bool) or (not isinstance(item['rating'], int)) or (not 1 <= item['rating'] <= 5):
            raise ValueError('invalid record')
        tags = item['tags']
        if not isinstance(tags, list) or any((not isinstance(t, str) or not t for t in tags)) or len(tags) != len(set(tags)):
            raise ValueError('invalid tags')
        stamp = item['timestamp']
        try:
            if not isinstance(stamp, str) or len(stamp) != 20 or (not stamp.endswith('Z')):
                raise ValueError
