import sqlite3
import math

def initialize_database(conn: sqlite3.Connection) -> None:
    conn.executescript('\n    create table if not exists requests(\n        id integer primary key,\n        requester text not null,\n        department text not null,\n        amount real not null,\n        submitted_at text not null,\n        status text not null\n    );\n    create table if not exists approval_rules(\n        department text not null,\n        max_amount real not null,\n        approver text not null,\n        unique(department, max_amount, approver)\n    );\n    ')

def add_request(conn: sqlite3.Connection, requester: str, department: str, amount: float, submitted_at: str) -> int:
    if not math.isfinite(amount) or amount < 0:
        raise ValueError('invalid amount')
    cur = conn.execute('insert into requests(requester, department, amount, submitted_at, status) values (?, ?, ?, ?, ?)', (requester, department, amount, submitted_at, 'pending'))
    return int(cur.lastrowid)

def route_approvals(conn: sqlite3.Connection, department: str | None=None, search: str='', sort_by: str='submitted_at', descending: bool=False) -> list[dict]:
    columns = {'id', 'requester', 'department', 'amount', 'submitted_at'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    sql = 'select id, requester, department, amount, submitted_at from requests where status = ?'
    args = ['pending']
    if department is not None:
        sql += ' and department = ?'
        args.append(department)
    if search:
        sql += ' and requester like ? collate nocase'
        args.append('%' + search + '%')
    rows = conn.execute(sql, args).fetchall()
    rules = conn.execute('select department, max_amount, approver from approval_rules').fetchall()
    grouped = {}
    for dep, maximum, approver in rules:
        grouped.setdefault(dep, []).append((maximum, approver))
    result = []
    for row in rows:
        candidates = [(maximum, approver) for maximum, approver in grouped.get(row[2], []) if maximum >= row[3]]
        approver = min(candidates, key=lambda x: (x[0], x[1]))[1] if candidates else None
        result.append({'id': row[0], 'requester': row[1], 'department': row[2], 'amount': row[3], 'submitted_at': row[4], 'approver': approver})
    result.sort(key=lambda x: x['id'])
    result.sort(key=lambda x: x[sort_by], reverse=descending)
    return result

def set_request_status(conn: sqlite3.Connection, request_id: int, status: str) -> dict:
    if status not in {'pending', 'approved', 'rejected'}:
        raise ValueError('invalid status')
    cur = conn.execute('update requests set status = ? where id = ?', (status, request_id))
    if cur.rowcount != 1:
        raise KeyError(request_id)
    row = conn.execute('select id, requester, department, amount, submitted_at, status from requests where id = ?', (request_id,)).fetchone()
    return dict(zip(('id', 'requester', 'department', 'amount', 'submitted_at', 'status'), row))

