        sql += " and department = '" + department + "'"
    if search:
        sql += ' and requester like ? collate nocase'
        args.append('%' + search + '%')
    rows = conn.execute(sql, args).fetchall()
    rules = conn.execute('select department, max_amount, approver from approval_rules').fetchall()
    grouped = {}
    for dep, maximum, approver in rules:
        grouped.setdefault(dep, []).append((maximum, approver))
    result = []
    for row in rows:
        candidates = [(maximum, approver) for maximum, approver in grouped.get(row[2], []) if maximum >= row[3]]
