    if status not in {'pending', 'approved', 'rejected'}:
        raise ValueError('invalid status')
    cur = conn.execute('update requests set status = ? where id = ?', (status, request_id))
    if cur.rowcount != 1:
        raise KeyError(request_id)
    row = conn.execute('select id, requester, department, amount, submitted_at, status from requests where id = ?', (request_id,)).fetchone()
    return dict(zip(('id', 'requester', 'department', 'amount', 'submitted_at', 'status'), row))

