import hashlib
import hmac
import json

def _split(text, separator):
    values = []
    current = []
    escaped = False
    for char in text:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == separator:
            values.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('malformed escaping')
    values.append(''.join(current).strip())
    return values

def parse_review_log(text: str) -> list[dict]:
    records = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split(raw, '|')
        if len(fields) != 4:
            raise ValueError('invalid field count')
        ident, custodian, status, tag_text = fields
        if not ident or not custodian or status not in {'reviewed', 'pending', 'rejected'}:
            raise ValueError('invalid review record')
        if ident in seen:
            raise ValueError('duplicate document id')
        seen.add(ident)
        tags = [] if not tag_text else _split(tag_text, ',')
        if any((not tag for tag in tags)):
            raise ValueError('empty tag')
        records.append({'id': ident, 'custodian': custodian, 'status': status, 'tags': sorted(set(tags))})
    return records

def summarize_review(records: list[dict]) -> dict:
    statuses = ('reviewed', 'pending', 'rejected')
    seen = set()
    counts = {status: 0 for status in statuses}
    people = {}
    for record in records:
        if record['id'] in seen:
            raise ValueError('duplicate document id')
        seen.add(record['id'])
        if record['status'] not in counts:
            raise ValueError('invalid status')
        counts[record['status']] += 1
        person = people.setdefault(record['custodian'], {'document_count': 0, 'status_counts': {s: 0 for s in statuses}, 'tag_counts': {}})
        person['document_count'] += 1
        person['status_counts'][record['status']] += 1
        for tag in record['tags']:
            person['tag_counts'][tag] = person['tag_counts'].get(tag, 0) + 1
    for person in people.values():
        person['tag_counts'] = {k: person['tag_counts'][k] for k in sorted(person['tag_counts'])}
    return {'document_count': len(records), 'status_counts': counts, 'custodians': {k: people[k] for k in sorted(people)}}

