    key = config.get('signing_key')
    if not isinstance(key, str) or not key:
        raise ValueError('missing signing key')
    canonical = json.dumps(summary, sort_keys=True, separators=(',', ':'), allow_nan=False)
    signature = hmac.new(key.encode('utf-8'), canonical.encode('utf-8'), hashlib.sha256).hexdigest()
    return {'summary': summary, 'canonical': canonical, 'signature': signature}

