def get_recommendations(event_file: str, user_id: str, limit: int=3) -> list[dict[str, object]]:
    if not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0 or (not user_id):
        raise ValueError('invalid arguments')
    result = subprocess.run(['grep', '-F', '--', user_id, event_file], capture_output=True, text=True, check=False)
    if result.returncode not in (0, 1):
        if result.returncode == 2:
            raise FileNotFoundError(event_file)
        raise RuntimeError('grep failed')
    totals = {}
    for line in result.stdout.splitlines():
        if not line:
            continue
        fields = line.split('\t')
        if len(fields) != 4 or fields[0] != user_id:
            continue
        try:
            timestamp = int(fields[2])
            weight = float(fields[3])
        except (TypeError, ValueError):
            raise ValueError('invalid event')
        if timestamp < 0 or weight < 0:
            raise ValueError('invalid event')
        category = fields[1]
        if category not in totals:
            totals[category] = [0.0, timestamp]
        totals[category][0] += weight
        totals[category][1] = max(totals[category][1], timestamp)
    rows = [{'category': k, 'score': v[0], 'last_seen': v[1]} for k, v in totals.items()]
    rows.sort(key=lambda x: (-x['score'], -x['last_seen'], x['category']))
    return rows[:limit]

