        raise ValueError('invalid limit')
    for user_id in user_ids:
        if not user_id:
            raise ValueError('invalid user')
    result = {}
    for user_id in user_ids:
        if user_id not in result:
            result[user_id] = get_recommendations(event_file, user_id, limit)
    return result

