import os
from datetime import datetime

def hash_signer_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin.isdecimal() or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_signer_pin(pin: str, stored: str) -> bool:
    try:
        if not isinstance(pin, str) or not pin.isdecimal() or (not 4 <= len(pin) <= 12):
            return False
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, TypeError, ValueError):
        return False

def summarize_envelopes(envelopes: list[dict], status: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    selected = [dict(item) for item in envelopes if status is None or item['status'] == status]
    selected.sort(key=lambda item: (-datetime.fromisoformat(item['signed_at'].replace('Z', '+00:00')).timestamp(), item['id']))
    start = (page - 1) * page_size
    return {'total': len(selected), 'amount_cents': sum((item['amount_cents'] for item in selected)), 'envelopes': selected[start:start + page_size]}

