import os
import tempfile
_STATUSES = {'submitted', 'review', 'approved', 'rejected', 'withdrawn'}

def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        return datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def _money(value):
    try:
        d = decimal.Decimal(str(value))
    except decimal.InvalidOperation:
        raise ValueError('invalid amount')
    if not d.is_finite() or d < 0 or d.as_tuple().exponent < -2:
        raise ValueError('invalid amount')
    return int(d * 100)

def build_report(records: list[dict], as_of: str) -> list[dict]:
    cutoff = _date(as_of)
    seen = set()
    result = []
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('id'), str) or (not record['id']) or (record['id'] in seen):
            raise ValueError('invalid id')
        seen.add(record['id'])
        submitted_text = record.get('submitted')
        submitted = _date(submitted_text)
        if submitted > cutoff or not isinstance(record.get('country'), str):
            raise ValueError('invalid application')
        latest = None
        for pos, event in enumerate(record.get('events', [])):
            if not isinstance(event, dict) or event.get('status') not in _STATUSES:
                raise ValueError('invalid event')
            day = _date(event.get('date'))
            if day < submitted:
                raise ValueError('event before submission')
            if day <= cutoff and (latest is None or (day, pos) > (latest[0], latest[1])):
                latest = (day, pos, event['status'])
        cents = 0
        for fee in record.get('fees', []):
            if not isinstance(fee, dict):
                raise ValueError('invalid fee')
            day = _date(fee.get('date'))
            amount = _money(fee.get('amount'))
            if day <= cutoff:
                cents += amount
        result.append({'id': record['id'], 'country': record['country'], 'submitted': submitted_text, 'status': latest[2] if latest else 'submitted', 'days_waiting': (cutoff - submitted).days, 'fee_cents': cents})
    result.sort(key=lambda r: (r['country'].casefold(), r['submitted'], r['id']))
    return result

def export_report(records: list[dict], as_of: str, destination: str) -> int:
    rows = build_report(records, as_of)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temp = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=['id', 'country', 'submitted', 'status', 'days_waiting', 'fee_cents'])
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temp, destination)
    except Exception:
        try:
            os.unlink(temp)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

