import ast
import operator

def _evaluate(expression, values):
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            left, right = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            result = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = visit(child)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, child in zip(node.ops, node.comparators):
                right = visit(child)
                fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                if fn is None:
                    raise ValueError('unsupported expression')
                if not fn(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*[visit(x) for x in node.args])
        raise ValueError('unsupported expression')
    return visit(tree)

def rank_campaigns(campaigns: list[dict], users: list[dict], expression: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page <= 0) or (page_size <= 0):
        raise ValueError('page values must be positive integers')
    result = []
    for campaign in campaigns:
        selected = []
        for user in users:
            score = _evaluate(expression, {'opens': user['opens'], 'clicks': user['clicks'], 'purchases': user['purchases'], 'age': user['age'], 'threshold': campaign['threshold']})
            if score:
                selected.append({'id': user['id'], 'score': score})
        selected.sort(key=lambda x: (-x['score'], x['id']))
        total = round(sum((x['score'] for x in selected)), 2) if selected else 0
        result.append({'id': campaign['id'], 'title': campaign['title'], 'eligible_count': len(selected), 'total_score': total, 'users': selected})
    result.sort(key=lambda x: (-x['total_score'], x['id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

