        supplied = headers['X-Review-Signature']
        secret = secrets[key_id]
    except (KeyError, TypeError):
        raise ValueError('invalid request')
    if not supplied.startswith('sha256=') or len(supplied) != 71:
        raise ValueError('invalid signature')
    text = supplied[7:]
    if any((c not in '0123456789abcdef' for c in text)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(text, expected):
        raise ValueError('invalid signature')
    try:
        event = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid body')
    if not isinstance(event, dict) or not isinstance(event.get('event_id'), str) or (not event['event_id']):
        raise ValueError('invalid event')
    if isinstance(event.get('received_at'), bool) or not isinstance(event.get('received_at'), int):
        raise ValueError('invalid event')
    reviews = event.get('reviews')
    if not isinstance(reviews, list):
        raise ValueError('invalid reviews')
    ids = set()
    for review in reviews:
        if not isinstance(review, dict):
            raise ValueError('invalid review')
        required = ('id', 'product', 'rating', 'timestamp', 'text', 'status')
        if any((k not in review for k in required)) or not isinstance(review['id'], str) or (not review['id']) or (not isinstance(review['product'], str)) or (not review['product']) or (not isinstance(review['text'], str)) or (review['status'] not in {'pending', 'approved', 'rejected'}):
            raise ValueError('invalid review')
        if review['id'] in ids or isinstance(review['rating'], bool) or (not isinstance(review['rating'], int)) or (not 1 <= review['rating'] <= 5) or isinstance(review['timestamp'], bool) or (not isinstance(review['timestamp'], int)):
            raise ValueError('invalid review')
        ids.add(review['id'])
    return event

def summarize_reviews(event: dict, now: int, window: int=86400) -> list[dict]:
    if isinstance(now, bool) or not isinstance(now, int) or isinstance(window, bool) or (not isinstance(window, int)) or (window < 0):
        raise ValueError('invalid range')
    groups = {}
    for review in event.get('reviews', []):
        if review['status'] == 'approved' and now - window <= review['timestamp'] <= now:
            group = groups.setdefault(review['product'], [])
            group.append(review)
    result = []
    for product, reviews in groups.items():
        result.append({'product': product, 'count': len(reviews), 'average_rating': round(sum((r['rating'] for r in reviews)) / len(reviews), 2), 'latest_timestamp': max((r['timestamp'] for r in reviews))})
    result.sort(key=lambda x: (-x['count'], -x['average_rating'], -x['latest_timestamp'], x['product']))
    return result

def moderate_event(body: bytes, headers: dict[str, str], secrets: dict[str, bytes], now: int, window: int=86400) -> dict:
    event = verify_review_event(body, headers, secrets)
    return {'event_id': event['event_id'], 'received_at': event['received_at'], 'products': summarize_reviews(event, now, window)}

