import json

def _check_snapshot(value):
    if not isinstance(value, dict):
        raise ValueError('invalid snapshot')
    tiers = {'standard', 'silver', 'gold', 'platinum'}
    for guest, data in value.items():
        if not isinstance(guest, str) or not guest:
            raise ValueError('invalid guest')
        if not isinstance(data, dict) or set(data) != {'points', 'reservations', 'tier'}:
            raise ValueError('invalid guest record')
        if isinstance(data['points'], bool) or not isinstance(data['points'], int) or data['points'] < 0:
            raise ValueError('invalid points')
        if not isinstance(data['reservations'], list) or any((not isinstance(x, str) or not x for x in data['reservations'])):
            raise ValueError('invalid reservations')
        if data['tier'] not in tiers:
            raise ValueError('invalid tier')

def encode_snapshot(snapshot: dict) -> bytes:
    _check_snapshot(snapshot)
    return json.dumps(snapshot, sort_keys=True, separators=(',', ':')).encode()

def decode_snapshot(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        value = json.loads(blob.decode())
        _check_snapshot(value)
        return value
    except (ValueError, UnicodeError, json.JSONDecodeError, TypeError):
        raise ValueError('invalid snapshot')

def record_stays(snapshot: dict, stays: list[dict]) -> dict:
    _check_snapshot(snapshot)
    if not isinstance(stays, list):
        raise ValueError('invalid stays')
    result = {g: {'points': d['points'], 'reservations': list(d['reservations']), 'tier': d['tier']} for g, d in snapshot.items()}
    used = {r for d in result.values() for r in d['reservations']}
    checked = []
    for stay in stays:
        if not isinstance(stay, dict) or set(stay) != {'reservation_id', 'guest_id', 'nights', 'rate_cents', 'timestamp'}:
            raise ValueError('invalid stay')
        rid, guest = (stay['reservation_id'], stay['guest_id'])
        if not isinstance(rid, str) or not rid or (not isinstance(guest, str)) or (not guest):
            raise ValueError('invalid stay')
        if isinstance(stay['nights'], bool) or not isinstance(stay['nights'], int) or stay['nights'] <= 0:
            raise ValueError('invalid stay')
        if isinstance(stay['rate_cents'], bool) or not isinstance(stay['rate_cents'], int) or stay['rate_cents'] < 0:
            raise ValueError('invalid stay')
        if isinstance(stay['timestamp'], bool) or not isinstance(stay['timestamp'], int):
            raise ValueError('invalid stay')
        checked.append(stay)
    for stay in sorted(checked, key=lambda x: (x['timestamp'], x['reservation_id'])):
        if stay['reservation_id'] in used:
            continue
        used.add(stay['reservation_id'])
        guest = stay['guest_id']
        if guest not in result:
            result[guest] = {'points': 0, 'reservations': [], 'tier': 'standard'}
        result[guest]['points'] += stay['nights'] * stay['rate_cents'] // 100
        result[guest]['reservations'].append(stay['reservation_id'])
    for data in result.values():
        p = data['points']
        data['tier'] = 'standard' if p < 1000 else 'silver' if p < 5000 else 'gold' if p < 10000 else 'platinum'
    return result

