import datetime
import json
import os
from pathlib import Path

def _path(base_dir: str, relative_name: str) -> Path:
    base = Path(base_dir).resolve()
    candidate = (base / relative_name).resolve()
    try:
        candidate.relative_to(base)
    except ValueError:
        raise ValueError('path is outside base directory')
    return candidate

def _minutes(value: str, kind: str) -> int:
    try:
        parsed = datetime.datetime.strptime(value, '%H:%M')
    except (TypeError, ValueError):
        raise ValueError('invalid time')
    if parsed.strftime('%H:%M') != value:
        raise ValueError('invalid time')
    return parsed.hour * 60 + parsed.minute

def build_schedule_report(shifts: list[dict[str, object]]) -> dict[str, object]:
    normalized = []
    for item in shifts:
        if not isinstance(item, dict):
            raise ValueError('invalid shift')
        try:
            employee = item['employee']
            date = item['date']
            start = item['start']
            end = item['end']
        except KeyError:
            raise ValueError('missing field')
        role = item.get('role', '')
        break_minutes = item.get('break_minutes', 0)
        if not all((isinstance(x, str) for x in (employee, date, start, end, role))):
            raise ValueError('invalid field')
        if not isinstance(break_minutes, int) or isinstance(break_minutes, bool):
            raise ValueError('invalid break')
        try:
            date_obj = datetime.datetime.strptime(date, '%Y-%m-%d')
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if date_obj.strftime('%Y-%m-%d') != date:
            raise ValueError('invalid date')
        begin = _minutes(start, 'start')
        finish = _minutes(end, 'end')
        duration = finish - begin
        if duration <= 0 or break_minutes < 0 or break_minutes > duration:
            raise ValueError('invalid duration')
        normalized.append({'employee': employee, 'date': date, 'start': start, 'end': end, 'role': role, 'break_minutes': break_minutes, 'paid_minutes': duration - break_minutes})
    normalized.sort(key=lambda x: (x['date'], x['start'], x['employee'], x['role']))
    totals = {}
    for item in normalized:
        current = totals.setdefault(item['employee'], [0, 0])
        current[0] += 1
        current[1] += item['paid_minutes']
    employees = [{'employee': name, 'shifts': totals[name][0], 'paid_minutes': totals[name][1]} for name in sorted(totals)]
    return {'shifts': normalized, 'employees': employees}

def export_schedule(base_dir: str, relative_name: str, shifts: list[dict[str, object]]) -> dict[str, object]:
    report = build_schedule_report(shifts)
    path = _path(base_dir, relative_name)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('w', encoding='utf-8') as handle:
        json.dump(report, handle, indent=2, sort_keys=True)
        handle.write('\n')
    return report

def import_schedule(base_dir: str, relative_name: str) -> dict[str, object]:
    with _path(base_dir, relative_name).open('r', encoding='utf-8') as handle:
        return json.load(handle)

