import re

def sync_employee_directory(employees: list[dict], batch_size: int, config: dict[str, str]) -> list[dict]:
    if not isinstance(employees, list):
        raise TypeError('employees must be a list')
    if isinstance(batch_size, bool) or not isinstance(batch_size, int):
        raise TypeError('batch_size must be an integer')
    if batch_size <= 0:
        raise ValueError('batch_size must be positive')
    token = config.get('api_token')
    if not token:
        raise ValueError('api_token is required')
    groups = {}
    for item in employees:
        if not isinstance(item, dict):
            raise TypeError('employee must be a dictionary')
        for key in ('id', 'name', 'department', 'active', 'salary'):
            if key not in item:
                raise ValueError('missing employee field')
        if isinstance(item['id'], bool) or not isinstance(item['id'], int):
            raise TypeError('id must be an integer')
        if item['id'] <= 0:
            raise ValueError('id must be positive')
        if not isinstance(item['name'], str) or not isinstance(item['department'], str):
            raise TypeError('name and department must be strings')
        name = re.sub('\\\\s+', ' ', item['name'].strip())
        department = item['department'].strip()
        if not name or not department:
            raise ValueError('name and department must not be empty')
        if not isinstance(item['active'], bool):
            raise TypeError('active must be boolean')
        if isinstance(item['salary'], bool) or not isinstance(item['salary'], (int, float)):
            raise TypeError('salary must be numeric')
        if item['salary'] < 0:
            raise ValueError('salary must not be negative')
        if item['active']:
            groups.setdefault(department, []).append({'id': item['id'], 'name': name, 'salary': round(item['salary'], 2)})
    result = []
    for department in sorted(groups, key=str.casefold):
        records = sorted(groups[department], key=lambda x: (x['name'].casefold(), x['id']))
        for offset in range(0, len(records), batch_size):
            batch = records[offset:offset + batch_size]
            result.append({'department': department, 'batch_number': offset // batch_size + 1, 'employees': batch, 'total_salary': round(sum((x['salary'] for x in batch)), 2), 'api_token': token})
    return result

