        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    result = []
    for element in root.findall('order'):
        try:
            symbol = element.attrib['symbol']
            side = element.attrib['side']
            quantity = int(element.attrib['quantity'])
            limit = float(element.attrib['limit'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid order') from exc
        if side not in {'BUY', 'SELL'} or quantity <= 0 or limit <= 0:
            raise ValueError('invalid order')
        result.append({'symbol': symbol, 'side': side, 'quantity': quantity, 'limit': limit})
    return result

