        try:
            symbol = attrs['symbol']
            side = attrs['side']
            quantity = int(attrs['quantity'])
            limit = float(attrs['limit'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid order') from exc
