import json
from datetime import date
_FIELDS = {'id', 'site', 'cleaner', 'status', 'date', 'minutes', 'supplies'}
_STATUSES = {'completed', 'in_progress', 'canceled'}

def _day(value):
    if not isinstance(value, str) or len(value) != 10:
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def _check(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for item in records:
        if not isinstance(item, dict) or set(item) != _FIELDS:
            raise ValueError('invalid work order')
        for key in ('id', 'site', 'cleaner', 'status', 'date'):
            if not isinstance(item[key], str):
                raise ValueError('invalid field')
        if item['status'] not in _STATUSES:
            raise ValueError('invalid status')
        _day(item['date'])
        if isinstance(item['minutes'], bool) or not isinstance(item['minutes'], int) or item['minutes'] < 0:
            raise ValueError('invalid minutes')
        supplies = item['supplies']
        if not isinstance(supplies, dict):
            raise ValueError('invalid supplies')
        for name, quantity in supplies.items():
            if not isinstance(name, str) or isinstance(quantity, bool) or (not isinstance(quantity, int)) or (quantity < 0):
                raise ValueError('invalid supply')

def encode_work_orders(records: list[dict]) -> bytes:
    _check(records)
    return json.dumps(records, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def decode_work_orders(payload: bytes) -> list[dict]:
    if not isinstance(payload, (bytes, bytearray)):
        raise ValueError('payload must be bytes')
    try:
        records = json.loads(bytes(payload).decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    _check(records)
    return records

def summarize_work_orders(payload: bytes, start_date: str, end_date: str) -> list[dict]:
    start, end = (_day(start_date), _day(end_date))
    if start > end:
        raise ValueError('invalid range')
    groups = {}
    for item in decode_work_orders(payload):
        current = _day(item['date'])
        if start <= current <= end and item['status'] != 'canceled':
            group = groups.setdefault(item['cleaner'], {'jobs': 0, 'minutes': 0, 'sites': set(), 'supplies': {}})
            group['jobs'] += 1
            group['minutes'] += item['minutes']
            group['sites'].add(item['site'])
            for name, quantity in item['supplies'].items():
                group['supplies'][name] = group['supplies'].get(name, 0) + quantity
    result = []
    for cleaner, group in groups.items():
        result.append({'cleaner': cleaner, 'jobs': group['jobs'], 'minutes': group['minutes'], 'sites': sorted(group['sites']), 'supplies': {k: v for k, v in sorted(group['supplies'].items()) if v}})
    return sorted(result, key=lambda row: (-row['minutes'], row['cleaner']))

