import os

def create_employee_record(employee_id: str, name: str, department: str, password: str) -> dict:
    values = (employee_id, name, department, password)
    if any((not isinstance(value, str) for value in values)):
        raise TypeError('employee fields must be strings')
    if any((value == '' for value in values)):
        raise ValueError('employee fields must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'employee_id': employee_id, 'name': name, 'department': department, 'password_hash': digest.hex(), 'salt': salt.hex()}

def authenticate_employee(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(password, str):
        return False
    try:
        stored = bytes.fromhex(record['password_hash'])
        salt = bytes.fromhex(record['salt'])
        candidate = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(candidate, stored)
    except (KeyError, TypeError, ValueError):
        return False

