import csv
import math
import subprocess
from typing import Any

def portfolio_report(path: str, min_value: float=0.0, page: int=1, page_size: int=10) -> dict[str, Any]:
    if min_value < 0 or not math.isfinite(min_value):
        raise ValueError('invalid minimum')
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    result = subprocess.run(['sort', '-t,', '-k2,2', '-k1,1', path], capture_output=True, text=True, check=True)
    rows = {}
    reader = csv.reader(result.stdout.splitlines())
    header_seen = False
    for fields in reader:
        if not fields or all((not value for value in fields)):
            continue
        if fields == ['symbol', 'category', 'shares', 'price']:
            header_seen = True
            continue
        if len(fields) != 4:
            raise ValueError('invalid row')
        try:
            shares = float(fields[2])
            price = float(fields[3])
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not math.isfinite(shares) or not math.isfinite(price):
            raise ValueError('invalid number')
        category = fields[1]
        entry = rows.setdefault(category, [0.0, 0])
        entry[0] += shares * price
        entry[1] += 1
    if not header_seen:
        raise ValueError('invalid header')
    categories = [(category, total, count) for category, (total, count) in rows.items() if total >= min_value]
    categories.sort(key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    items = [{'category': category, 'value': round(total, 2), 'positions': count} for category, total, count in categories[start:start + page_size]]
    return {'page': page, 'page_size': page_size, 'total_categories': len(categories), 'items': items}

