from datetime import date
from decimal import Decimal, ROUND_HALF_UP

def cancel_reservation(requester: dict, reservations: list[dict], reservation_id: str, today: str) -> dict:
    reservation = next((item for item in reservations if item.get('id') == reservation_id), None)
    if reservation is None:
        raise KeyError(reservation_id)
    try:
        current = date.fromisoformat(today)
        start = date.fromisoformat(reservation['start_date'])
    except (TypeError, ValueError, KeyError) as exc:
        raise ValueError('invalid date') from exc
    if current > start:
        raise ValueError('cancellation date is after check-in')
    if reservation.get('status') != 'confirmed':
        raise ValueError('reservation cannot be cancelled')
    same_tenant = requester.get('tenant_id') == reservation.get('tenant_id')
    permitted = same_tenant and (requester.get('id') == reservation.get('owner_id') or bool(set(requester.get('roles', [])) & {'manager', 'admin'}))
    if not permitted:
        raise PermissionError('not permitted')
    total = Decimal(str(reservation['total']))
    days = (start - current).days
    rate = Decimal('1') if days >= 7 else Decimal('0.5') if days >= 2 else Decimal('0')
    refund = (total * rate).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return {'id': reservation['id'], 'status': 'cancelled', 'cancelled_on': today, 'refund': float(refund), 'total': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))}

