import json
from pathlib import Path

def save_jury_questionnaire(base_dir: str, relative_name: str, responses: dict[str, str]) -> str:
    if not isinstance(relative_name, str):
        raise TypeError('relative_name must be a string')
    if not isinstance(responses, dict) or any((not isinstance(key, str) or not isinstance(value, str) for key, value in responses.items())):
        raise TypeError('responses must be a dictionary of strings')
    if not relative_name:
        raise ValueError('relative_name must not be empty')
    if not relative_name.endswith('.json'):
        raise ValueError('relative_name must end in .json')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    if target == base or base not in target.parents:
        raise ValueError('output path is outside the base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', encoding='utf-8') as handle:
        json.dump(responses, handle, ensure_ascii=False, indent=2, sort_keys=True)
        handle.write('\n')
    return str(target)

