from datetime import date

def _fields(line):
    out = []
    cur = []
    escaped = False
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur).strip())
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('bad escape')
    out.append(''.join(cur).strip())
    return out

def parse_observations(text: str) -> list[dict]:
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        parts = _fields(line)
        if len(parts) != 4 or not parts[0]:
            raise ValueError('bad record')
        try:
            date.fromisoformat(parts[1])
            measurement = float(parts[2])
        except (ValueError, TypeError):
            raise ValueError('bad value')
        if measurement < 0 or parts[3] not in {'good', 'watch', 'critical'}:
            raise ValueError('bad value')
        result.append({'station': parts[0], 'date': parts[1], 'measurement': measurement, 'condition': parts[3]})
    return result

def summarize_inspection(observations: list[dict], window: int=3) -> list[dict]:
    if not isinstance(window, int) or isinstance(window, bool) or window < 1:
        raise ValueError('window')
    groups = {}
    for pos, row in enumerate(observations):
        groups.setdefault(row['station'], []).append((row, pos))
    result = []
    rank = {'good': 0, 'watch': 1, 'critical': 2}
    for station in sorted(groups):
        rows = sorted(groups[station], key=lambda x: (x[0]['date'], x[1]))
        vals = [x[0]['measurement'] for x in rows]
        recent = vals[max(0, len(vals) - window):]
        latest = rows[-1][0]
        worst = max((x[0]['condition'] for x in rows), key=lambda x: rank[x])
        result.append({'station': station, 'count': len(rows), 'latest_date': latest['date'], 'latest_measurement': round(latest['measurement'], 2), 'rolling_average': round(sum(recent) / len(recent), 2), 'worst_condition': worst})
    return result

def build_work_order(requester: dict, inspection: dict) -> dict:
    for key in ('id', 'owner_id', 'district', 'road', 'observations'):
        if key not in inspection:
            raise KeyError(key)
    for key in ('id', 'role', 'district'):
        if key not in requester:
            raise KeyError(key)
    if not inspection['id'] or not inspection['road'] or (not inspection['district']) or (not inspection['observations']):
        raise ValueError('invalid inspection')
    if requester['district'] != inspection['district'] or (requester['id'] != inspection['owner_id'] and requester['role'] not in {'supervisor', 'dispatcher'}):
        raise PermissionError('not permitted')
    stations = summarize_inspection(inspection['observations'])
    conditions = {x['worst_condition'] for x in stations}
    priority, days = ('urgent', 1) if 'critical' in conditions else ('high', 7) if 'watch' in conditions else ('routine', 30)
    return {'work_order_id': 'WO-' + inspection['id'], 'inspection_id': inspection['id'], 'road': inspection['road'], 'district': inspection['district'], 'stations': stations, 'priority': priority, 'due_days': days}

