import hashlib
import os
from datetime import date

def _credential(password):
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + value.hex()

def _check(credential, password):
    if not isinstance(credential, str) or not isinstance(password, str):
        return False
    try:
        salt_text, value = credential.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
        return value == expected
    except (ValueError, TypeError):
        return False

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def create_license(course: str, capacity: int, administrator_password: str, expires: str) -> dict:
    if not isinstance(course, str) or not course or (not isinstance(administrator_password, str)) or (not administrator_password):
        raise ValueError('invalid text')
    if isinstance(capacity, bool) or not isinstance(capacity, int) or (not 1 <= capacity <= 10000):
        raise ValueError('invalid capacity')
    _day(expires)
    return {'course': course, 'capacity': capacity, 'expires': expires, 'students': [], 'credential': _credential(administrator_password)}

def verify_license(record: dict, administrator_password: str) -> bool:
    try:
        return isinstance(record, dict) and _check(record['credential'], administrator_password)
    except (KeyError, TypeError):
        return False

def enroll_students(record: dict, administrator_password: str, students: list[str]) -> list[str]:
    if not verify_license(record, administrator_password) or _day(record.get('expires', '0001-01-01')) < date.today():
        raise PermissionError('license unavailable')
    if not isinstance(students, list):
        raise ValueError('invalid students')
    cleaned = []
    for student in students:
        if not isinstance(student, str) or not student.strip():
            raise ValueError('invalid student')
        item = student.strip()
        if item in cleaned:
            raise ValueError('duplicate student')
        cleaned.append(item)
    current = record.get('students')
    if not isinstance(current, list) or len(current) + len(cleaned) > record['capacity']:
        raise OverflowError('capacity exceeded')
    record['students'] = list(current) + cleaned
    return list(record['students'])

def license_report(records: list[dict], on_date: str) -> list[dict]:
    when = _day(on_date)
    groups = {}
    for record in records:
        try:
            course = record['course']
            capacity = record['capacity']
            expires = _day(record['expires'])
            students = record['students']
            if not isinstance(course, str) or not isinstance(capacity, int) or (not isinstance(students, list)) or (expires < when):
                continue
            item = groups.setdefault(course, {'course': course, 'licenses': 0, 'capacity': 0, 'names': set()})
            item['licenses'] += 1
            item['capacity'] += capacity
            item['names'].update(students)
        except (KeyError, TypeError, ValueError):
            continue
    result = []
    for item in groups.values():
        enrolled = len(item['names'])
        result.append({'course': item['course'], 'licenses': item['licenses'], 'capacity': item['capacity'], 'enrolled': enrolled, 'available': item['capacity'] - enrolled})
    return sorted(result, key=lambda x: (-x['enrolled'], x['available'], x['course']))

