import subprocess

def calculate_cart_total(catalog_path: str, sku: str, quantity: int) -> float:
    if not sku or type(quantity) is not int or quantity <= 0:
        raise ValueError('invalid SKU or quantity')
    result = subprocess.run(['grep', '-F', sku + ',', catalog_path], capture_output=True, text=True, check=False)
    if result.returncode == 2:
        raise FileNotFoundError(catalog_path)
    if result.returncode == 1:
        raise KeyError(sku)
    line = result.stdout.splitlines()[0]
    fields = line.split(',')
    if len(fields) != 2 or fields[0] != sku:
        raise ValueError('malformed catalog line')
    try:
        price = float(fields[1])
    except ValueError as exc:
        raise ValueError('invalid price') from exc
    return price * quantity

