def _validate_records(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict) or set(record) != {'name', 'version', 'score', 'downloads'}:
            raise ValueError('invalid record')
        if not isinstance(record['name'], str) or not record['name']:
            raise ValueError('invalid name')
        if isinstance(record['version'], bool) or not isinstance(record['version'], int) or record['version'] < 1:
            raise ValueError('invalid version')
        if isinstance(record['score'], bool) or not isinstance(record['score'], (int, float)) or (not math.isfinite(record['score'])):
            raise ValueError('invalid score')
        if isinstance(record['downloads'], bool) or not isinstance(record['downloads'], int) or record['downloads'] < 0:
            raise ValueError('invalid downloads')

def encode_registry(records: list[dict]) -> bytes:
    _validate_records(records)
    return json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')

def get_registry_page(blob: bytes, page: int, page_size: int, minimum_score: float=0.0) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if isinstance(minimum_score, bool) or not isinstance(minimum_score, (int, float)) or (not math.isfinite(minimum_score)):
        raise ValueError('invalid minimum score')
    try:
        records = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    _validate_records(records)
    selected = [record for record in records if record['score'] >= minimum_score]
    selected.sort(key=lambda record: (-record['score'], record['name'], -record['version']))
    average = round(sum((record['score'] for record in selected)) / len(selected), 3) if selected else 0.0
    start = page * page_size
    return {'total': len(selected), 'page': selected[start:start + page_size], 'average_score': average}

