import xml.etree.ElementTree as ET

def _time(value: str) -> tuple[datetime, str]:
    value = value.strip()
    if not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        dt = datetime.fromisoformat(value[:-1] + '+00:00').astimezone(timezone.utc)
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    return (dt, dt.strftime('%Y-%m-%dT%H:%M:%SZ'))

def parse_subscription_feed(xml_text: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'feed':
        raise ValueError('invalid root')
    result = []
    for child in root:
        if child.tag != 'subscriber':
            raise ValueError('unexpected element')
        email = child.attrib.get('email', '').strip()
        if not email:
            raise ValueError('missing email')
        for event in child:
            if event.tag != 'event':
                raise ValueError('unexpected element')
            topic = event.attrib.get('topic', '').strip()
            status = event.attrib.get('status', '').strip()
            raw = event.attrib.get('timestamp', '')
            if not topic or status not in {'active', 'paused', 'unsubscribed'}:
                raise ValueError('invalid event')
            _, timestamp = _time(raw)
            if list(event):
                raise ValueError('unexpected element')
            result.append({'email': email, 'topic': topic, 'status': status, 'timestamp': timestamp})
    return result

def consolidate_subscriptions(xml_documents: Iterable[str], cutoff: datetime) -> list[dict[str, Any]]:
    if cutoff.tzinfo is None or cutoff.utcoffset() is None:
        raise ValueError('cutoff must be aware')
    limit = cutoff.astimezone(timezone.utc)
    latest = {}
    order = 0
    for document in xml_documents:
        for event in parse_subscription_feed(document):
            moment, _ = _time(event['timestamp'])
            if moment <= limit:
                key = (event['email'], event['topic'])
                if key not in latest or moment >= latest[key][0]:
                    latest[key] = (moment, order, event)
            order += 1
    grouped = {}
    for (email, topic), (_, _, event) in latest.items():
        grouped.setdefault(email, {})[topic] = event
    output = []
    for email in sorted(grouped):
        events = grouped[email]
        active = sorted((t for t, e in events.items() if e['status'] == 'active'))
        unsub = sorted((t for t, e in events.items() if e['status'] == 'unsubscribed'))
        newest = max((_time(e['timestamp'])[0] for e in events.values()), default=None)
        output.append({'email': email, 'active_topics': active, 'unsubscribed_topics': unsub, 'last_updated': newest.strftime('%Y-%m-%dT%H:%M:%SZ') if newest else None})
    return output

def render_domain_digest(records: Iterable[dict[str, Any]]) -> str:
    groups = {}
    for record in records:
        email = record.get('email')
        topics = record.get('active_topics')
        if not isinstance(email, str) or email.count('@') != 1 or (not email.split('@')[-1]):
            raise ValueError('invalid email')
        if not isinstance(topics, list):
            raise ValueError('invalid topics')
        domain = email.rsplit('@', 1)[1].lower()
        groups.setdefault(domain, []).append(topics)
    lines = []
    for domain in sorted(groups):
        counts = {}
        for topics in groups[domain]:
            for topic in topics:
                counts[topic] = counts.get(topic, 0) + 1
        summary = ','.join((f'{topic}:{counts[topic]}' for topic in sorted(counts)))
        lines.append(f'{domain} subscribers={len(groups[domain])} active_topics={summary}')
    return '\n'.join(lines) + ('\n' if lines else '')

