import csv
from datetime import date
from decimal import Decimal, InvalidOperation
FIELDS = ['contract_id', 'freelancer', 'client', 'milestone', 'amount', 'status', 'due_date']
STATUSES = ('draft', 'active', 'completed', 'cancelled')

def _check_date(value):
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def _amount(value):
    try:
        result = Decimal(value)
    except InvalidOperation:
        raise ValueError('invalid amount')
    if result < 0 or result.as_tuple().exponent < -2:
        raise ValueError('invalid amount')
    return result

def _rows_from_text(text):
    lines = text.splitlines()
    if not lines or lines[0] != '\t'.join(FIELDS):
        raise ValueError('invalid header')
    rows = []
    for line in lines[1:]:
        if not line:
            continue
        values = next(csv.reader([line], delimiter='\t'))
        if len(values) != 7:
            raise ValueError('invalid row')
        row = dict(zip(FIELDS, values))
        _amount(row['amount'])
        if row['status'] not in STATUSES:
            raise ValueError('invalid status')
        _check_date(row['due_date'])
        rows.append(row)
    rows.sort(key=lambda row: (row['freelancer'].casefold(), _check_date(row['due_date']), row['contract_id']))
    return rows

def read_contract_rows(path: str) -> list[dict[str, str]]:
    with open(path, 'r', encoding='utf-8') as file:
        text = file.read()
    return _rows_from_text(text)

def build_contract_report(path: str, as_of: str) -> dict:
    today = _check_date(as_of)
    rows = read_contract_rows(path)
    totals = {status: Decimal('0') for status in STATUSES}
    contracts = []
    for row in rows:
        value = _amount(row['amount'])
        totals[row['status']] += value
        contracts.append({**row, 'overdue': row['status'] not in ('completed', 'cancelled') and _check_date(row['due_date']) < today})
    return {'as_of': as_of, 'contracts': contracts, 'totals': {'count': len(rows), 'value': f'{sum(totals.values()):.2f}', 'by_status': {status: f'{totals[status]:.2f}' for status in STATUSES}}}

