import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    iterations = 120000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, iterations)
    return f'p2${iterations}${salt.hex()}${digest.hex()}'

def verify_secret(encoded: str, secret: str) -> bool:
    if not isinstance(encoded, str) or not isinstance(secret, str):
        return False
    try:
        kind, count, salt_text, digest_text = encoded.split('$')
        if kind != 'p2':
            return False
        iterations = int(count)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def plan_rollout(patches: list[dict], completed: set[str], region: str, capacity: int) -> list[list[str]]:
    if not isinstance(capacity, int) or capacity <= 0:
        raise ValueError('invalid capacity')
    records = {}
    for patch in patches:
        if not isinstance(patch, dict) or set(patch) != {'id', 'region', 'size', 'priority', 'depends'}:
            raise ValueError('invalid patch')
        ident, area, size, priority, depends = (patch[k] for k in ('id', 'region', 'size', 'priority', 'depends'))
        if not isinstance(ident, str) or not ident or (not isinstance(area, str)) or (not isinstance(size, int)) or isinstance(size, bool) or (size <= 0) or (not isinstance(priority, int)) or isinstance(priority, bool) or (not isinstance(depends, list)) or any((not isinstance(x, str) for x in depends)):
            raise ValueError('invalid patch')
        if ident in records or size > capacity:
            raise ValueError('invalid patch')
        records[ident] = (area, size, priority, depends)
    for _, _, _, deps in records.values():
        if any((dep not in records for dep in deps)):
            raise ValueError('unknown dependency')
    pending = {k for k, v in records.items() if v[0] == region and k not in completed}
    done = set(completed)
    result = []
    while pending:
        available = [k for k in pending if all((d in done for d in records[k][3]))]
        available.sort(key=lambda k: (-records[k][2], records[k][1], k))
        batch = []
        used = 0
        for ident in available:
            if used + records[ident][1] <= capacity:
                batch.append(ident)
                used += records[ident][1]
        if not batch:
            raise ValueError('unresolvable dependencies')
        result.append(batch)
        pending.difference_update(batch)
        done.update(batch)
    return result

