    assert result["architects"] == [{"architect": "One", "fee": 10.125, "status": "rejected"}, {"architect": "Two", "fee": 0.004, "status": "submitted"}]


def test_signature_mismatch_is_rejected():
    obj = {"proposal_id": "P-3", "firm": "F", "bids": [{"architect": "A", "fee": 1, "status": "submitted"}]}
    payload = make_payload(obj)
