import hashlib
import hmac
import json

def process_proposal_webhook(payload: str, signature: str, secret: str) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
        raise ValueError('invalid arguments')
    try:
        data = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict):
        raise ValueError('invalid payload')
    if not isinstance(data.get('proposal_id'), str) or not isinstance(data.get('firm'), str):
        raise ValueError('invalid payload')
    bids = data.get('bids')
    if not isinstance(bids, list) or not bids:
        raise ValueError('invalid bids')
    for bid in bids:
        if not isinstance(bid, dict):
            raise ValueError('invalid bid')
        if not isinstance(bid.get('architect'), str) or not bid['architect']:
            raise ValueError('invalid architect')
        fee = bid.get('fee')
        if isinstance(fee, bool) or not isinstance(fee, (int, float)) or fee < 0:
            raise ValueError('invalid fee')
        if bid.get('status') not in {'submitted', 'shortlisted', 'rejected'}:
            raise ValueError('invalid status')
    canonical = json.dumps(data, sort_keys=True, separators=(',', ':'), ensure_ascii=False)
    expected = hmac.new(secret.encode(), canonical.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    ordered = sorted(bids, key=lambda bid: (-bid['fee'], bid['architect']))
    total = round(sum((bid['fee'] for bid in bids)), 2)
    return {'proposal_id': data['proposal_id'], 'firm': data['firm'], 'accepted_count': sum((bid['status'] == 'shortlisted' for bid in bids)), 'total_fee': total, 'architects': [{'architect': bid['architect'], 'fee': bid['fee'], 'status': bid['status']} for bid in ordered]}

