def build_billing_report(claims: list[dict], page: int=1, page_size: int=50, config: dict[str, str] | None=None) -> dict:
    if not isinstance(claims, list) or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid report arguments')
    groups = {}
    for claim in claims:
        if not isinstance(claim, dict):
            raise ValueError('invalid claim')
        for field in ('patient_id', 'procedure', 'date', 'status', 'amount'):
            if field not in claim:
                raise ValueError('invalid claim')
