            raise ValueError('invalid claim')
        try:
            amount = Decimal(str(claim['amount']))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid amount')
        if claim['status'] == 'submitted':
            item = groups.setdefault(claim['patient_id'], [Decimal('0'), 0])
            item[0] += amount
            item[1] += 1
    rows = [{'patient_id': pid, 'claim_count': value[1], 'total': str(value[0].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for pid, value in groups.items()]
    rows.sort(key=lambda row: (-Decimal(row['total']), row['patient_id']))
    total = len(rows)
    total_pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    payload = {'page': page, 'page_size': page_size, 'total_patients': total, 'total_pages': total_pages, 'patients': rows[start:start + page_size]}
    if config is not None:
