def parse_measurements(text: str) -> list[tuple[datetime, str, float, float, str]]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        parts = raw.split(',')
        if len(parts) != 5:
            raise ValueError('invalid record')
        stamp, name, level, flow, status = (p.strip() for p in parts)
        if not name or status not in {'NORMAL', 'WATCH', 'ALERT'}:
            raise ValueError('invalid record')
        try:
            if not (stamp.endswith('Z') or '+' in stamp[10:] or '-' in stamp[10:]):
                raise ValueError
            dt = datetime.fromisoformat(stamp[:-1] + '+00:00' if stamp.endswith('Z') else stamp)
            if dt.tzinfo is None:
                raise ValueError
            dt = dt.astimezone(timezone.utc)
            lev, fl = (float(level), float(flow))
            if not math.isfinite(lev) or not math.isfinite(fl):
                raise ValueError
        except Exception as exc:
            raise ValueError('invalid record') from exc
        result.append((dt, name, lev, fl, status))
    return result

