def get_booking_page(bookings: list[dict[str, Any]], requester: dict[str, Any], start: str, end: str, page: int, page_size: int) -> dict[str, Any]:

    def parse(value: str) -> datetime:
        return datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value)
    begin = parse(start)
    finish = parse(end)
    if finish <= begin or page <= 0 or page_size <= 0:
        raise ValueError
    selected = []
    for booking in bookings:
        when = parse(booking['starts_at'])
        if booking['status'] == 'cancelled' or when < begin or when >= finish:
            continue
        allowed = requester['role'] == 'admin' or (booking['tenant_id'] == requester['tenant_id'] and (requester['role'] == 'trainer' and booking['trainer_id'] == requester['id'] or (requester['role'] == 'client' and booking['client_id'] == requester['id'])))
        if not allowed:
            raise PermissionError
        selected.append((when, booking))
    selected.sort(key=lambda pair: (pair[0], pair[1]['id']))
    total_minutes = sum((item['duration_minutes'] for _, item in selected))
    total_cost = round(sum((item['cost'] for _, item in selected)), 2)
    offset = (page - 1) * page_size
    return {'items': [item for _, item in selected[offset:offset + page_size]], 'total': len(selected), 'page': page, 'page_size': page_size, 'total_minutes': total_minutes, 'total_cost': total_cost}

