import hashlib
import hmac
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def hash_access_code(code: str) -> str:
    if not isinstance(code, str):
        raise TypeError('code must be a string')
    if not code:
        raise ValueError('code must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_access_code(code: str, stored: str) -> bool:
    if not isinstance(code, str) or not code or (not isinstance(stored, str)):
        return False
    try:
        salt_text, digest_text = stored.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_estimates(estimates: list[dict], category: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(estimates, list):
        raise TypeError('estimates must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    rows = []
    required = {'id', 'category', 'description', 'quantity', 'unit_price', 'status'}
    for estimate in estimates:
        if not isinstance(estimate, dict) or not required.issubset(estimate):
            raise ValueError('invalid estimate')
        try:
            quantity = Decimal(str(estimate['quantity']))
            unit_price = Decimal(str(estimate['unit_price']))
            total = (quantity * unit_price).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        if estimate['status'] == 'included' and (category is None or estimate['category'] == category):
            rows.append((total, estimate))
    rows.sort(key=lambda pair: (-pair[0], str(pair[1]['id'])))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    return {'count': len(rows), 'total': float(sum((x[0] for x in rows), Decimal('0.00'))), 'items': [{'id': e['id'], 'description': e['description'], 'total': float(t)} for t, e in selected]}

