import math
import os

def hash_secret(secret: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_secret(stored: str, secret: str) -> bool:
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def rebalance_portfolio(current: dict[str, float], target: dict[str, float], secret: str, stored_secret: str) -> dict[str, float]:
    if not verify_secret(stored_secret, secret):
        raise PermissionError('invalid secret')
    if set(current) != set(target):
        raise ValueError('asset sets differ')
    for portfolio in (current, target):
        if any((not isinstance(v, (int, float)) or not math.isfinite(v) or v < 0 or (v > 1) for v in portfolio.values())):
            raise ValueError('invalid weights')
