import csv
import json
import math
from pathlib import Path

def _path(base_dir, name):
    base = Path(base_dir).resolve()
    target = (base / name).resolve()
    if target != base and base not in target.parents:
        raise ValueError('invalid path')
    return target

def load_observations(base_dir: str, filename: str) -> list[dict]:
    path = _path(base_dir, filename)
    rows = []
    seen = set()
    try:
        with path.open('r', encoding='utf-8', newline='') as f:
            reader = csv.reader(f)
            header = next(reader)
            if header != ['station', 'day', 'temperature', 'humidity', 'wind', 'rainfall']:
                raise ValueError('invalid header')
            for row in reader:
                if len(row) != 6 or not any(row):
                    raise ValueError('invalid row')
                station = row[0].strip()
                if not station:
                    raise ValueError('invalid station')
                try:
                    day = int(row[1])
                    vals = [float(x) for x in row[2:]]
                except (TypeError, ValueError):
                    raise ValueError('invalid number')
                if day < 0 or not all((math.isfinite(x) for x in vals)):
                    raise ValueError('invalid number')
                if not (-80 <= vals[0] <= 70 and 0 <= vals[1] <= 100 and (vals[2] >= 0) and (vals[3] >= 0)):
                    raise ValueError('out of range')
                if (station, day) in seen:
                    raise ValueError('duplicate')
                seen.add((station, day))
                rows.append({'station': station, 'day': day, 'temperature': vals[0], 'humidity': vals[1], 'wind': vals[2], 'rainfall': vals[3]})
    except StopIteration:
        raise ValueError('empty file')
    return rows

def summarize_risk(observations: list[dict], window: int=3) -> list[dict]:
    if not isinstance(window, int) or isinstance(window, bool) or (not 1 <= window <= 30):
        raise ValueError('invalid window')
    groups = {}
    seen = set()
    for o in observations:
        try:
            station, day = (o['station'], o['day'])
            vals = [float(o[k]) for k in ('temperature', 'humidity', 'wind', 'rainfall')]
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid observation')
        if not isinstance(station, str) or not station or (not isinstance(day, int)) or isinstance(day, bool) or (day < 0) or (not all((math.isfinite(x) for x in vals))):
            raise ValueError('invalid observation')
        if (station, day) in seen:
            raise ValueError('duplicate')
        seen.add((station, day))
        groups.setdefault(station, []).append((day, vals))
    result = []
    for station, items in groups.items():
        items.sort()
        risks = []
        for day, (temp, humidity, wind, rain) in items:
            risk = round(max(0, min(100, temp * 0.02 + (100 - humidity) * 0.03 + wind * 0.05 - rain * 0.04)), 3)
            risks.append(risk)
            avg = round(sum(risks[-window:]) / min(window, len(risks)), 3)
            level = 'low' if avg < 25 else 'moderate' if avg < 50 else 'high' if avg < 75 else 'extreme'
            result.append({'station': station, 'day': day, 'risk': risk, 'average_risk': avg, 'level': level})
    return sorted(result, key=lambda x: (x['day'], x['station']))

def save_risk_report(base_dir: str, filename: str, report: list[dict]) -> str:
    keys = {'station', 'day', 'risk', 'average_risk', 'level'}
    if not isinstance(report, list) or any((not isinstance(x, dict) or set(x) != keys for x in report)):
        raise ValueError('invalid report')
    path = _path(base_dir, filename)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('w', encoding='utf-8') as f:
        json.dump(report, f, indent=2, sort_keys=True)
        f.write('\n')
    return str(path)

