        if not isinstance(records, list):
            raise ValueError
        prices = {}
        for record in records:
            if not isinstance(record, dict):
                raise ValueError
            sku = record['sku']
            unit_price = record['unit_price']
            active = record['active']
            if not isinstance(sku, str) or not sku or isinstance(unit_price, bool) or (not isinstance(unit_price, int)) or (unit_price < 0) or (not isinstance(active, bool)):
                raise ValueError
            prices[sku] = (unit_price, active)
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid price data')
    output = []
