def create_courier_record(courier_id: str, name: str, zone: str, pin: str) -> dict:
    if not all((isinstance(value, str) and value for value in (courier_id, name, zone))):
        raise ValueError('identity fields must be non-empty strings')
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isdigit()):
        raise ValueError('PIN must contain four digits')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'courier_id': courier_id, 'name': name, 'zone': zone, 'available': True, 'completed_deliveries': 0, 'pin_hash': digest.hex(), 'pin_salt': salt.hex()}

def verify_courier_pin(record: dict, pin: str) -> bool:
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isdigit()):
        return False
    try:
        salt = bytes.fromhex(record['pin_salt'])
        expected = record['pin_hash']
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

