            raise ValueError('invalid package')
        attrs = {}
        for key in ('id', 'carrier', 'received', 'weight'):
            value = node.get(key)
            if value is None or not value.strip():
                raise ValueError('missing package value')
            attrs[key] = value.strip()
        received = _day(attrs['received'])
        try:
            weight = float(attrs['weight'])
        except Exception as exc:
            raise ValueError('invalid weight') from exc
        if weight < 0:
            raise ValueError('invalid weight')
        if len(node) < 1 or node[0].tag != 'recipient':
            raise ValueError('missing recipient')
        recipient = (node[0].text or '').strip()
        if not recipient:
            raise ValueError('empty recipient')
        events = []
        previous = received
        for event in node[1:]:
            if event.tag != 'event' or event.get('date') is None or event.get('code') is None:
                raise ValueError('invalid event')
            current = _day(event.get('date').strip())
            code = event.get('code').strip()
            if not code or current < previous:
                raise ValueError('invalid event')
            events.append({'date': event.get('date').strip(), 'code': code})
            previous = current
        seen.add(attrs['id'])
        result.append({'id': attrs['id'], 'carrier': attrs['carrier'], 'recipient': recipient, 'weight': weight, 'received': attrs['received'], 'status': events[-1]['code'] if events else 'RECEIVED', 'events': events})
    return result

