            carrier = record['carrier']
            weight = float(record['weight'])
            received = _day(record['received'])
            ident = record['id']
            status = record['status']
        except Exception as exc:
            raise ValueError('invalid record') from exc
        total_weight += weight
        group = groups.setdefault(carrier, {'count': 0, 'weight': 0.0})
        group['count'] += 1
        group['weight'] += weight
        if status != 'DELIVERED' and received < today - timedelta(days=7):
            overdue.append((received, ident))
    ordered = {key: {'count': groups[key]['count'], 'weight': round(groups[key]['weight'], 2)} for key in sorted(groups)}
    overdue.sort()
    return {'total': len(records), 'delivered': sum((r.get('status') == 'DELIVERED' for r in records)), 'weight': round(total_weight, 2), 'by_carrier': ordered, 'overdue': [item[1] for item in overdue]}

