import csv
import ipaddress
import os
import tempfile
_HEADER = ['priority', 'action', 'protocol', 'source', 'destination', 'ports', 'enabled']
_PROTOCOL_ORDER = {'icmp': 0, 'tcp': 1, 'udp': 2, 'any': 3}

def parse_rules(text: str) -> list[dict]:
    lines = [x for x in text.splitlines() if x.strip()]
    if not lines or [x.strip() for x in lines[0].split(',')] != _HEADER:
        raise ValueError('invalid header')
    result = []
    for line in lines[1:]:
        row = next(csv.reader([line]))
        if len(row) != 7:
            raise ValueError('invalid row')
        row = [x.strip() for x in row]
        try:
            priority = int(row[0])
            if priority < 0 or row[1] not in ('allow', 'deny') or row[2] not in ('tcp', 'udp', 'icmp', 'any'):
                raise ValueError
            source = str(ipaddress.ip_network(row[3], strict=False))
            destination = str(ipaddress.ip_network(row[4], strict=False))
            ports = []
            if row[5]:
                for part in row[5].split(';'):
                    bits = part.split('-')
                    if len(bits) not in (1, 2):
                        raise ValueError
                    a = int(bits[0])
                    b = int(bits[-1])
                    if a < 1 or b > 65535 or a > b:
                        raise ValueError
                    pair = (a, b)
                    if pair in ports:
                        raise ValueError
                    ports.append(pair)
            if row[2] == 'icmp' and ports:
                raise ValueError
            if row[2] != 'icmp' and (not ports):
                raise ValueError
            if row[6].lower() not in ('true', 'false'):
                raise ValueError
            result.append({'priority': priority, 'action': row[1], 'protocol': row[2], 'source': source, 'destination': destination, 'ports': tuple(ports), 'enabled': row[6].lower() == 'true'})
        except (ValueError, TypeError):
            raise ValueError('invalid row')
    return result

def summarize_rules(rules: list[dict]) -> dict:
    actions = {'allow': 0, 'deny': 0}
    protocols = {'tcp': 0, 'udp': 0, 'icmp': 0, 'any': 0}
    enabled = sum((r['enabled'] for r in rules))
    for r in rules:
        actions[r['action']] += 1
        protocols[r['protocol']] += 1
    return {'total': len(rules), 'enabled': enabled, 'disabled': len(rules) - enabled, 'actions': actions, 'protocols': protocols}

def export_rules(text: str, destination: str) -> int:
    rules = parse_rules(text)
    unique = list(dict.fromkeys((tuple(sorted(r.items())) for r in rules)))
    rules = [dict(x) for x in unique]
    rules.sort(key=lambda r: (r['priority'], r['enabled'], 0 if r['action'] == 'deny' else 1, _PROTOCOL_ORDER[r['protocol']], r['source'], r['destination'], r['ports']))
    rows = [_HEADER]
    for r in rules:
        ports = ';'.join((str(a) if a == b else f'{a}-{b}' for a, b in r['ports']))
        rows.append([str(r['priority']), r['action'], r['protocol'], r['source'], r['destination'], ports, str(r['enabled']).lower()])
    parent = os.path.dirname(os.path.abspath(destination))
    fd, tmp = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as f:
            csv.writer(f, lineterminator='\n').writerows(rows)
        os.replace(tmp, destination)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)
    return len(rules)

