import hashlib
import hmac
import os

def make_access_code_record(code: str) -> str:
    if not isinstance(code, str) or not code:
        raise ValueError('invalid code')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def check_access_code(code: str, record: str) -> bool:
    if not isinstance(code, str) or not isinstance(record, str):
        return False
    try:
        salt_text, digest_text = record.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        if len(salt) != 16 or len(expected) != 32:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, UnicodeEncodeError):
        return False

def _fields(line):
    fields, current = ([], [])
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def assess_damage_report(report: str, code: str, stored_code: str) -> dict[str, object]:
    if not check_access_code(code, stored_code):
        raise PermissionError('access denied')
    if not isinstance(report, str):
        raise ValueError('invalid report')
    rows = []
    for line in report.splitlines():
        if not line.strip():
            continue
        values = _fields(line)
        if len(values) != 5 or not values[1] or (not values[2]):
            raise ValueError('invalid record')
        date, vehicle, part, cost, status = values
        if len(date) != 10 or date[4] != '-' or date[7] != '-':
            raise ValueError('invalid date')
        try:
            if (date[:4] + date[5:7] + date[8:]).isdigit() is False:
                raise ValueError
            year, month, day = (int(date[:4]), int(date[5:7]), int(date[8:]))
            import datetime
            datetime.date(year, month, day)
            amount = int(cost)
        except (ValueError, TypeError):
            raise ValueError('invalid values')
        if amount < 0 or status not in ('OPEN', 'CLOSED'):
            raise ValueError('invalid values')
        rows.append((date, vehicle, part, amount, status))
    groups = {}
    for date, vehicle, part, amount, status in rows:
        groups.setdefault(vehicle, []).append((date, part, amount, status))
    vehicles = []
    for vehicle in sorted(groups):
        items = groups[vehicle]
        parts = [{'part': p, 'date': d, 'cost_cents': c, 'status': s} for d, p, c, s in sorted(items, key=lambda x: (-x[2], x[1], x[0]))]
        vehicles.append({'vehicle': vehicle, 'total_cents': sum((x[2] for x in items)), 'open_count': sum((x[3] == 'OPEN' for x in items)), 'closed_count': sum((x[3] == 'CLOSED' for x in items)), 'latest_date': max((x[0] for x in items)), 'parts': parts})
