from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import re
from lxml import etree

def summarize_roster(xml_text: str, month: str) -> list[dict[str, object]]:
    if not isinstance(month, str) or not re.fullmatch('\\d{4}-\\d{2}', month):
        raise ValueError('invalid month')
    try:
        month_date = date.fromisoformat(month + '-01')
    except ValueError as exc:
        raise ValueError('invalid month') from exc
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser=parser)
    except (etree.XMLSyntaxError, ValueError, TypeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'roster':
        raise ValueError('invalid root')
    groups = {}
    for node in root:
        if node.tag != 'assignment':
            raise ValueError('invalid element')
        try:
            conductor = node.attrib['conductor']
            raw_date = node.attrib['date']
            route = node.attrib['route']
            raw_hours = node.attrib['hours']
            if not conductor or not route or (not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', raw_date)):
                raise ValueError
            assignment_date = date.fromisoformat(raw_date)
            hours = Decimal(raw_hours)
            if not hours.is_finite() or hours < 0:
                raise ValueError
        except (KeyError, ValueError, InvalidOperation) as exc:
            raise ValueError('invalid assignment') from exc
        if raw_date[:7] != month:
            continue
        item = groups.setdefault(conductor, {'hours': Decimal('0'), 'assignments': 0, 'routes': set()})
        item['hours'] += hours
        item['assignments'] += 1
        item['routes'].add(route)
    rows = []
    for conductor, item in groups.items():
        total = item['hours'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append({'conductor': conductor, 'assignments': item['assignments'], 'hours': format(total, '.2f'), 'routes': sorted(item['routes'])})
    rows.sort(key=lambda row: (-Decimal(row['hours']), row['conductor']))
    return rows

