import hashlib
import os

def _hash_pin(pin):
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
    return f'{rounds}${salt.hex()}${digest.hex()}'

def _verify_pin(pin, stored):
    try:
        rounds, salt, digest = stored.split('$')
        value = hashlib.pbkdf2_hmac('sha256', pin.encode(), bytes.fromhex(salt), int(rounds)).hex()
        return value == digest
    except (ValueError, TypeError):
        return False

def make_license(license_id: str, customer: str, products: list[str], pin: str, issued_at: int, expires_at: int, limits: dict[str, int]) -> dict[str, object]:
    if not isinstance(license_id, str) or not license_id or (not isinstance(customer, str)) or (not customer) or (not isinstance(pin, str)) or (not pin):
        raise ValueError()
    if not isinstance(issued_at, int) or not isinstance(expires_at, int) or issued_at > expires_at:
        raise ValueError()
    if not isinstance(products, list) or not all((isinstance(x, str) and x for x in products)):
        raise ValueError()
    names = sorted(set(products))
    if not isinstance(limits, dict) or set(limits) != set(names) or (not all((isinstance(limits[x], int) and (not isinstance(limits[x], bool)) and (limits[x] >= 0) for x in names))):
        raise ValueError()
    return {'license_id': license_id, 'customer': customer, 'products': names, 'issued_at': issued_at, 'expires_at': expires_at, 'limits': {x: limits[x] for x in names}, 'pin_hash': _hash_pin(pin)}

def _usage(record, now, events):
    if not isinstance(now, int) or not isinstance(events, list):
        raise ValueError()
    products = record['products']
    used = {x: 0 for x in products}
    for event in events:
        if not isinstance(event, dict) or set(event) != {'timestamp', 'product', 'quantity'}:
            raise ValueError()
        t, product, quantity = (event['timestamp'], event['product'], event['quantity'])
        if not isinstance(t, int) or not isinstance(product, str) or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity <= 0):
            raise ValueError()
        if record['issued_at'] <= t <= now and product in used:
            used[product] += quantity
    return used

def check_license(record: dict[str, object], pin: str, now: int, events: list[dict[str, object]]) -> dict[str, object]:
    if not isinstance(record, dict) or not isinstance(pin, str):
        raise ValueError()
    used = _usage(record, now, events)
    if not _verify_pin(pin, record['pin_hash']):
        return {'valid': False, 'reason': 'pin', 'used': {x: 0 for x in record['products']}, 'remaining': {x: 0 for x in record['products']}}
    reason = 'ok' if record['issued_at'] <= now <= record['expires_at'] else 'expired'
    return {'valid': reason == 'ok', 'reason': reason, 'used': used, 'remaining': {x: max(record['limits'][x] - used[x], 0) for x in record['products']}}

def license_summary(records: list[dict[str, object]], pins: dict[str, str], now: int, events: list[dict[str, object]]) -> list[dict[str, object]]:
    if not isinstance(records, list) or not isinstance(pins, dict):
        raise ValueError()
    ordered = sorted(enumerate(records), key=lambda z: (z[1]['expires_at'], z[1]['license_id'], z[0]))
    result = []
    for _, record in ordered:
        outcome = check_license(record, pins.get(record['license_id'], ''), now, events)
        result.append({'license_id': record['license_id'], 'customer': record['customer'], 'valid': outcome['valid'], 'remaining': outcome['remaining']})
    return result

