def ingest_meter_reading(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'meter':
        raise ValueError('invalid root')
    values = {child.tag: child.text for child in root}
    if any((values.get(name) is None or not values[name].strip() for name in ('meter_id', 'reading', 'timestamp'))):
        raise ValueError('missing field')
    try:
        reading = float(values['reading'].strip())
    except ValueError as exc:
        raise ValueError('invalid reading') from exc
    if reading < 0:
        raise ValueError('negative reading')
    return {'meter_id': values['meter_id'].strip(), 'reading': reading, 'timestamp': values['timestamp'].strip()}

