from solution import parse_invocation_line, summarize_invocation_log
from datetime import datetime, timezone
import tempfile, os, pytest

def write_log(text):
    fd, path = tempfile.mkstemp(text=True)
    try:
        os.write(fd, text.encode())
    finally:
        os.close(fd)
    return path

def test_parse_valid_line():
    value = parse_invocation_line('2024-01-02T03:04:05Z\tr-7\tok\t12.5\t128\n')
    assert value == {'timestamp': datetime(2024, 1, 2, 3, 4, 5, tzinfo=timezone.utc), 'request_id': 'r-7', 'status': 'ok', 'duration_ms': 12.5, 'memory_mb': 128.0}

def test_parse_rejects_bad_records():
    bad = ['', '2024-01-02T03:04:05Z\tr\tok\t1', '2024-01-02T03:04:05Z\t\tok\t1\t2', '2024-01-02T03:04:05Z\tr\tworking\t1\t2', '2024-01-02T03:04:05\tr\tok\t1\t2', 'not-a-date\tr\tok\t1\t2', '2024-01-02T03:04:05Z\tr\tok\t-1\t2', '2024-01-02T03:04:05Z\tr\tok\tx\t2']
    for line in bad:
        assert parse_invocation_line(line) is None

def test_empty_file_and_window_validation():
    path = write_log('\nnot a record\n')
    try:
        assert summarize_invocation_log(path, 60) == {'total': 0, 'by_status': {'ok': 0, 'error': 0, 'timeout': 0}, 'by_day': {}, 'windows': [], 'slowest': []}
        with pytest.raises(ValueError):
            summarize_invocation_log(path, 0)
        with pytest.raises(ValueError):
            summarize_invocation_log(path, -2)
    finally:
        os.unlink(path)

