    path = write_log('2024-01-02T00:00:03Z\tb\terror\t2.345\t10.111\n2024-01-01T23:59:59Z\ta\tok\t1.111\t20.222\n2024-01-02T00:00:01Z\tc\ttimeout\t3.335\t8.888\n')
    try:
        r = summarize_invocation_log(path, 60)
