import subprocess
from datetime import datetime, timezone, timedelta

def parse_invocation_line(line: str) -> dict | None:
    fields = line.strip().split('\t')
    if len(fields) != 5:
        return None
    timestamp, request_id, status, duration, memory = fields
    if not request_id or status not in {'ok', 'error', 'timeout'} or (not timestamp.endswith('Z')):
        return None
    try:
        when = datetime.strptime(timestamp, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
        duration_value = float(duration)
        memory_value = float(memory)
    except (ValueError, OverflowError):
        return None
    if duration_value < 0 or memory_value < 0:
        return None
    return {'timestamp': when, 'request_id': request_id, 'status': status, 'duration_ms': duration_value, 'memory_mb': memory_value}

def summarize_invocation_log(path: str, window_seconds: int) -> dict:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError('window_seconds must be positive')
    completed = subprocess.run(['sort', '-t', '\t', '-k1,1', '-k2,2', path], capture_output=True, text=True, check=True)
    records = [r for line in completed.stdout.splitlines() if (r := parse_invocation_line(line)) is not None]
    result = {'total': len(records), 'by_status': {'ok': 0, 'error': 0, 'timeout': 0}, 'by_day': {}, 'windows': [], 'slowest': []}
    if not records:
        return result
    for r in records:
        result['by_status'][r['status']] += 1
        day = r['timestamp'].strftime('%Y-%m-%d')
        s = result['by_day'].setdefault(day, {'count': 0, 'duration_ms': 0.0, 'max_memory_mb': 0.0})
        s['count'] += 1
        s['duration_ms'] += r['duration_ms']
        s['max_memory_mb'] = max(s['max_memory_mb'], r['memory_mb'])
    for s in result['by_day'].values():
        s['duration_ms'] = round(s['duration_ms'], 2)
        s['max_memory_mb'] = round(s['max_memory_mb'], 2)
    first = records[0]['timestamp']
    buckets = {}
    for r in records:
        i = int((r['timestamp'] - first).total_seconds() // window_seconds)
        buckets.setdefault(i, []).append(r)
    for i, values in sorted(buckets.items()):
        result['windows'].append({'start': (first + timedelta(seconds=i * window_seconds)).strftime('%Y-%m-%dT%H:%M:%SZ'), 'count': len(values), 'errors': sum((r['status'] != 'ok' for r in values)), 'duration_ms': round(sum((r['duration_ms'] for r in values)), 2)})
    for r in sorted(records, key=lambda x: (-x['duration_ms'], x['timestamp'], x['request_id']))[:3]:
        result['slowest'].append({'timestamp': r['timestamp'].strftime('%Y-%m-%dT%H:%M:%SZ'), 'request_id': r['request_id'], 'status': r['status'], 'duration_ms': round(r['duration_ms'], 2), 'memory_mb': round(r['memory_mb'], 2)})
    return result

