import csv
import io
import math
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
HEADERS = ['day', 'zone', 'household', 'kg', 'organic', 'paper', 'glass']

def _check(row):
    if not isinstance(row, dict) or any((k not in row for k in HEADERS)):
        raise ValueError('invalid row')
    if not all((isinstance(row[k], str) and row[k] for k in ('day', 'zone', 'household'))):
        raise ValueError('invalid text')
    if row['day'] not in DAYS:
        raise ValueError('invalid day')
    try:
        kg = float(row['kg'])
    except (TypeError, ValueError):
        raise ValueError('invalid weight')
    if not math.isfinite(kg) or kg < 0:
        raise ValueError('invalid weight')
    vals = []
    for key in ('organic', 'paper', 'glass'):
        value = row[key]
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError('invalid material')
        vals.append(value)
    return (kg, vals)

def parse_pickups(text):
    try:
        reader = csv.reader(io.StringIO(text, newline=''))
        header = next(reader)
        if header != HEADERS:
            raise ValueError('header')
        result = []
        for fields in reader:
            if not fields or any((x == '' for x in fields)):
                raise ValueError('blank row')
            if len(fields) != 7:
                raise ValueError('columns')
            try:
                kg = float(fields[3])
                materials = [int(fields[i]) for i in (4, 5, 6)]
            except (TypeError, ValueError):
                raise ValueError('number')
            row = {'day': fields[0], 'zone': fields[1], 'household': fields[2], 'kg': kg, 'organic': materials[0], 'paper': materials[1], 'glass': materials[2]}
            _check(row)
            result.append(row)
        return result
    except (StopIteration, csv.Error):
        raise ValueError('csv')

def summarize_pickups(rows):
    groups = {}
    for row in rows:
        kg, materials = _check(row)
        key = (row['day'], row['zone'])
        if key not in groups:
            groups[key] = [0, Decimal('0'), 0, 0, 0]
        group = groups[key]
        group[0] += 1
        try:
            group[1] += Decimal(str(kg))
        except InvalidOperation:
            raise ValueError('weight')
        for i, value in enumerate(materials):
            group[i + 2] += value
    output = []
    for day, zone in sorted(groups, key=lambda x: (DAYS.index(x[0]), x[1])):
        count, kg, organic, paper, glass = groups[day, zone]
        amount = kg.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        output.append({'day': day, 'zone': zone, 'pickups': count, 'kg': float(amount), 'organic': organic, 'paper': paper, 'glass': glass})
    return output

def write_collection_report(rows, destination):
    summary = summarize_pickups(rows)
    stream = io.StringIO(newline='')
    writer = csv.writer(stream, lineterminator='\n')
    writer.writerow(['day', 'zone', 'pickups', 'kg', 'organic', 'paper', 'glass'])
    for row in summary:
        writer.writerow([row['day'], row['zone'], row['pickups'], format(row['kg'], '.2f'), row['organic'], row['paper'], row['glass']])
    content = stream.getvalue()
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return content

