import os
import tempfile
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def generate_billing_csv(customers: list[dict], output_path: str, period: str) -> list[dict]:
    try:
        y, m = map(int, period.split('-'))
        first = date(y, m, 1)
    except Exception:
        raise ValueError('invalid period')
    last = date(y + (m == 12), 1 if m == 12 else m + 1, 1) - timedelta(days=1)
    seen = set()
    result = []

    def dec(x):
        try:
            return Decimal(str(x))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid number')

    def money(x):
        return int((x * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))

    def fmt(x):
        s = format(x, 'f').rstrip('0').rstrip('.')
        return s or '0'
    for c in customers:
        cid = c.get('id')
        if not isinstance(cid, str) or not cid or cid in seen:
            raise ValueError('bad id')
        seen.add(cid)
        readings = {}
        for r in c.get('readings', []):
            try:
                d = date.fromisoformat(r['date'])
            except Exception:
                raise ValueError('bad reading date')
            if d in readings:
                raise ValueError('duplicate reading')
            v = dec(r['value'])
            if v < 0:
                raise ValueError('bad reading')
            readings[d] = v
        before = [d for d in readings if d <= first]
        ending = [d for d in readings if d <= last]
        if not before or not ending:
            raise ValueError('missing reading')
        usage = readings[max(ending)] - readings[max(before)]
        if usage < 0:
            raise ValueError('decreasing meter')
        tiers = c.get('tiers')
        if not isinstance(tiers, list) or not tiers:
            raise ValueError('bad tiers')
        charge = Decimal(0)
        prior = Decimal(0)
        unlimited = False
        for i, t in enumerate(tiers):
            lim = t.get('up_to')
            rate = dec(t.get('rate'))
            if rate < 0 or unlimited:
                raise ValueError('bad tiers')
            if lim is None:
                if i != len(tiers) - 1:
                    raise ValueError('bad tiers')
                amount = max(Decimal(0), usage - prior)
                unlimited = True
            else:
                lim = dec(lim)
                if lim <= prior:
                    raise ValueError('bad tiers')
                amount = max(Decimal(0), min(usage, lim) - prior)
                prior = lim
            charge += amount * rate
        fixed = dec(c.get('fixed_charge'))
        if fixed < 0:
            raise ValueError('bad fixed charge')
        ec, fc = (money(charge), money(fixed))
        result.append({'customer_id': cid, 'name': c.get('name'), 'usage': fmt(usage), 'energy_cents': ec, 'fixed_cents': fc, 'total_cents': ec + fc})
    result.sort(key=lambda x: x['customer_id'])
    fd, temp = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(output_path)))
    os.close(fd)
    try:
        with open(temp, 'w', newline='') as f:
            w = csv.writer(f)
            w.writerow(['customer_id', 'name', 'usage', 'energy_cents', 'fixed_cents', 'total_cents'])
            for r in result:
                w.writerow([r[k] for k in ['customer_id', 'name', 'usage', 'energy_cents', 'fixed_cents', 'total_cents']])
        os.replace(temp, output_path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)
    return result

