import os
import re
import subprocess

def _split_fields(line):
    fields = []
    current = []
    escaped = False
    for ch in line.rstrip('\n'):
        if escaped:
            if ch not in '\\|':
                raise ValueError('invalid escape')
            current.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current))
    return fields

def _time_value(value):
    match = re.fullmatch('(\\d{2}):(\\d{2}):(\\d{2})(?:\\.(\\d{3}))?', value)
    if not match:
        raise ValueError('invalid timestamp')
    hours, minutes, seconds, millis = match.groups()
    if int(minutes) > 59 or int(seconds) > 59:
        raise ValueError('invalid timestamp')
    return ((int(hours) * 60 + int(minutes)) * 60 + int(seconds)) * 1000 + int(millis or 0)

def parse_chapter_line(line: str) -> dict[str, object]:
    if not line.strip():
        raise ValueError('blank line')
    fields = _split_fields(line)
    if len(fields) != 4:
        raise ValueError('wrong field count')
    start = _time_value(fields[0])
    end = _time_value(fields[1])
    if end <= start:
        raise ValueError('invalid duration')
    return {'start': start, 'end': end, 'title': fields[2], 'narrator': fields[3], 'duration': end - start}

def _format_duration(ms):
    seconds, millis = divmod(ms, 1000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return f'{hours}:{minutes:02d}:{seconds:02d}.{millis:03d}'

def distribute_audiobook(manifest_path: str, output_dir: str, title_pattern: str | None=None, max_seconds: int=3600) -> list[dict[str, object]]:
    if not isinstance(max_seconds, int) or isinstance(max_seconds, bool) or max_seconds <= 0:
        raise ValueError('invalid limit')
    if title_pattern is None:
        with open(manifest_path, encoding='utf-8') as source:
            lines = [line for line in source if line.strip()]
    else:
        completed = subprocess.run(['grep', '-F', '-e', title_pattern, manifest_path], capture_output=True, text=True, check=False)
        if completed.returncode not in (0, 1):
            raise ValueError('selection failed')
        lines = [line for line in completed.stdout.splitlines(True) if line.strip()]
        lines = [line for line in lines if title_pattern in parse_chapter_line(line)['title']]
    chapters = [parse_chapter_line(line) for line in lines]
    chapters.sort(key=lambda c: (c['start'], c['end'], c['title'], c['narrator']))
    for previous, current in zip(chapters, chapters[1:]):
        if current['start'] < previous['end']:
            raise ValueError('overlap')
