import sqlite3
from datetime import date

def _month(value):
    try:
        if len(value) != 7 or value[4] != '-':
            raise ValueError
        y, m = (int(value[:4]), int(value[5:]))
        date(y, m, 1)
        return value
    except (TypeError, ValueError):
        raise ValueError('invalid month')

def _months(start, end):
    y, m = map(int, start.split('-'))
    ey, em = map(int, end.split('-'))
    out = []
    while (y, m) <= (ey, em):
        out.append(f'{y:04d}-{m:02d}')
        m += 1
        if m == 13:
            y, m = (y + 1, 1)
    return out

def monthly_statement(conn: sqlite3.Connection, member_id: int, start_month: str, end_month: str) -> list[dict]:
    start, end = (_month(start_month), _month(end_month))
    if start > end:
        raise ValueError('invalid range')
    if conn.execute('SELECT 1 FROM members WHERE id = ?', (member_id,)).fetchone() is None:
        raise LookupError('member not found')
