import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError(node.id)
        return names[node.id]
    if isinstance(node, ast.BinOp):
        left = _value(node.left, names)
        right = _value(node.right, names)
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        if type(node.op) not in ops:
            raise ValueError('operator')
        return ops[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, names)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BoolOp):
        values = [_value(x, names) for x in node.values]
        if isinstance(node.op, ast.And):
            result = values[0]
            for value in values[1:]:
                result = value if result else result
            return result
        result = values[0]
        for value in values[1:]:
            result = result if result else value
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        checks = []
        for op, item in zip(node.ops, node.comparators):
            right = _value(item, names)
            fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
            if fn is None:
                raise ValueError('comparison')
            checks.append(fn(left, right))
            left = right
        return all(checks)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_value(x, names) for x in node.args])
    raise ValueError('expression')

def generate_report(records: list[dict], rule: str) -> dict:
    tree = ast.parse(rule, mode='eval').body
    chosen = []
    for record in records:
        names = {key: record[key] for key in ('stake', 'payout', 'age')}
        if _value(tree, names):
            chosen.append(record)
    stake = sum((record['stake'] for record in chosen))
    payout = sum((record['payout'] for record in chosen))
    return {'count': len(chosen), 'total_stake': stake, 'total_payout': payout, 'net': payout - stake}

