import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def create_enrollment_report(base_dir: str, filename: str, enrollments: list[dict]) -> str:
    if not isinstance(filename, str) or not filename:
        raise ValueError('invalid filename')
    if not isinstance(enrollments, list):
        raise ValueError('invalid enrollments')
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, filename))
    try:
        if os.path.commonpath([base, target]) != base:
            raise ValueError('invalid filename')
    except ValueError:
        raise ValueError('invalid filename')
    groups = {}
    for item in enrollments:
        if not isinstance(item, dict):
            raise ValueError('invalid enrollment')
        required = ('employee_id', 'plan', 'employee_contribution', 'employer_contribution', 'status')
        if any((key not in item for key in required)):
            raise ValueError('invalid enrollment')
        if not isinstance(item['employee_id'], str) or not item['employee_id']:
            raise ValueError('invalid enrollment')
        if not isinstance(item['plan'], str) or not item['plan']:
            raise ValueError('invalid enrollment')
        if item['status'] not in ('active', 'waived'):
            raise ValueError('invalid enrollment')
        try:
            employee = Decimal(str(item['employee_contribution']))
            employer = Decimal(str(item['employer_contribution']))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid enrollment')
        if not employee.is_finite() or not employer.is_finite() or employee < 0 or (employer < 0):
            raise ValueError('invalid enrollment')
        if item['status'] == 'active':
            plan = item['plan']
            group = groups.setdefault(plan, [0, Decimal(0), Decimal(0)])
            group[0] += 1
            group[1] += employee
            group[2] += employer

    def money(value):
        return format(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')
    result = []
    for plan, (count, employee, employer) in groups.items():
        result.append({'plan': plan, 'enrollment_count': count, 'employee_total': money(employee), 'employer_total': money(employer), 'combined_total': money(employee + employer)})
    result.sort(key=lambda item: (-Decimal(item['combined_total']), item['plan']))
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        json.dump(result, handle, indent=2)
        handle.write('\n')
    return target

