import json
_STATUSES = {'in_transit', 'delayed', 'delivered'}
_KEYS = {'shipment', 'country', 'day', 'units', 'status'}

def _check_events(events):
    if not isinstance(events, list):
        raise ValueError('events')
    for item in events:
        if not isinstance(item, dict) or set(item) != _KEYS:
            raise ValueError('event')
        if not isinstance(item['shipment'], str) or not item['shipment'] or (not isinstance(item['country'], str)) or (not item['country']) or (not isinstance(item['status'], str)) or (item['status'] not in _STATUSES) or (type(item['day']) is not int) or (type(item['units']) is not int) or (item['units'] < 0):
            raise ValueError('event')

def make_checkpoint(events: list[dict], cursor: int) -> bytes:
    _check_events(events)
    if type(cursor) is not int or cursor < 0 or cursor > len(events):
        raise ValueError('cursor')
    return json.dumps({'events': events, 'cursor': cursor}, separators=(',', ':'), sort_keys=True).encode()

def restore_checkpoint(blob: bytes | str) -> tuple[list[dict], int]:
    if not isinstance(blob, (bytes, str)):
        raise ValueError('blob')
    try:
        data = json.loads(blob)
    except Exception:
        raise ValueError('blob')
    if not isinstance(data, dict) or set(data) != {'events', 'cursor'}:
        raise ValueError('blob')
    _check_events(data['events'])
    if type(data['cursor']) is not int or data['cursor'] < 0 or data['cursor'] > len(data['events']):
        raise ValueError('cursor')
    return (data['events'], data['cursor'])

def build_country_report(events: list[dict], start_day: int, end_day: int) -> list[dict]:
    _check_events(events)
    if type(start_day) is not int or type(end_day) is not int or start_day > end_day:
        raise ValueError('range')
    totals = {}
    latest = {}
    for i, item in enumerate(events):
        if start_day <= item['day'] <= end_day:
            c = item['country']
            totals.setdefault(c, {'units': 0, 'shipments': set()})
            totals[c]['units'] += item['units']
            totals[c]['shipments'].add(item['shipment'])
            key = item['shipment']
            if key not in latest or (item['day'], i) >= latest[key][0]:
                latest[key] = ((item['day'], i), item)
    delayed = {}
    for _, item in latest.values():
        if item['status'] == 'delayed':
            delayed[item['country']] = delayed.get(item['country'], 0) + 1
    return sorted([{'country': c, 'units': v['units'], 'shipments': len(v['shipments']), 'delayed_shipments': delayed.get(c, 0)} for c, v in totals.items()], key=lambda x: (-x['units'], x['country']))

