        expected = base64.urlsafe_b64decode(encoded_digest.encode())
        actual = hashlib.pbkdf2_hmac('sha256', api_key.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

