    tree = ast.parse(formula, mode='eval').body
    names = {'vibration', 'hours_since_service', 'temperature', 'wind_speed'}
    funcs = {'min': min, 'max': max, 'round': round}

    def ev(node, env):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in env:
                return env[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.IfExp):
            return ev(node.body, env) if ev(node.test, env) else ev(node.orelse, env)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = ev(node.operand, env)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            a, b = (ev(node.left, env), ev(node.right, env))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = ev(node.values[0], env)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = ev(item, env)
            return value
        if isinstance(node, ast.Compare):
            left = ev(node.left, env)
            for op, part in zip(node.ops, node.comparators):
                right = ev(part, env)
                operations = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
                if type(op) not in operations:
                    raise ValueError('unsupported operator')
                if not operations[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in funcs) and (not node.keywords):
            return funcs[node.func.id](*(ev(x, env) for x in node.args))
