        value = ev(tree, {name: turbine[name] for name in names})
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError('formula must produce a number')
        if value >= minimum:
            scored.append((value, turbine['id'], {'id': turbine['id'], 'score': round(value, 2)}))
    scored.sort(key=lambda x: (-x[0], x[1]))
    return [x[2] for x in scored[:limit]]

