import datetime
import json

def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def pack_rights(data: dict) -> bytes:
    if not isinstance(data, dict):
        raise ValueError('dictionary required')
    try:
        return json.dumps(data, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid data') from exc

def unpack_rights(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('bytes required')
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(value, dict):
        raise ValueError('dictionary required')
    return value

def build_rights_index(grants: list[dict]) -> dict:
    if not isinstance(grants, list):
        raise ValueError('list required')
    result = {}
    required = {'book', 'territory', 'holder', 'start', 'end'}
    for grant in grants:
        if not isinstance(grant, dict) or set(grant) != required:
            raise ValueError('invalid grant')
        if any((not isinstance(grant[k], str) or not grant[k] for k in required)):
            raise ValueError('invalid grant')
        start = _date(grant['start'])
        end = _date(grant['end'])
        if start >= end:
            raise ValueError('invalid interval')
        item = dict(grant)
        result.setdefault(grant['book'], {}).setdefault(grant['territory'], []).append(item)
    for territories in result.values():
        for values in territories.values():
            values.sort(key=lambda x: (x['start'], x['end'], x['holder']))
            for left, right in zip(values, values[1:]):
                if _date(left['end']) > _date(right['start']):
                    raise ValueError('overlap')
    return result

def rights_at(index: dict, date: str, territory: str | None=None) -> list[dict]:
    target = _date(date)
    if territory == '':
        raise ValueError('invalid territory')
    found = []
    for book, territories in index.items():
        for current, values in territories.items():
            if territory is not None and current != territory:
                continue
            for grant in values:
                if _date(grant['start']) <= target < _date(grant['end']):
                    found.append((book, current, grant))
    found.sort(key=lambda item: (item[0], item[1], item[2]['holder'], item[2]['start'], item[2]['end']))
    return [dict(item[2]) for item in found]

