import csv
import io
import math

def parse_record(line: str) -> tuple[int, str, str, float]:
    try:
        rows = list(csv.reader(io.StringIO(line), strict=True))
    except (csv.Error, TypeError):
        raise ValueError('invalid record')
    if len(rows) != 1 or len(rows[0]) != 4:
        raise ValueError('invalid record')
    ts, machine, metric, value = rows[0]
    ts, machine, metric = (ts.strip(), machine.strip(), metric.strip())
    if not machine or not metric:
        raise ValueError('invalid record')
    try:
        timestamp = int(ts)
        number = float(value.strip())
    except (TypeError, ValueError):
        raise ValueError('invalid record')
    if not math.isfinite(number):
        raise ValueError('invalid record')
    return (timestamp, machine, metric, number)

def generate_machine_report(requester: dict, machines: list[dict], records: list[str], start: int, end: int, window: int=300) -> dict:
    if start < 0 or end < start or window <= 0:
        raise ValueError('invalid interval')
    visible = []
    for machine in machines:
        if machine['tenant_id'] != requester['tenant_id']:
            continue
        if machine['owner_id'] == requester['id'] or 'operator' in requester.get('roles', []):
            visible.append(machine)
    visible.sort(key=lambda m: m['id'])
    by_id = {m['id']: m for m in visible}
    buckets = {m['id']: [[] for _ in range((max(0, end - start) + window - 1) // window)] for m in visible}
    for line in records:
        timestamp, machine_id, metric, value = parse_record(line)
        if start <= timestamp < end and machine_id in by_id:
            index = (timestamp - start) // window
            buckets[machine_id][index].append((metric, value))
    output = []
    for machine in visible:
        windows = []
        for index, values in enumerate(buckets[machine['id']]):
            grouped = {}
            for metric, value in values:
                grouped.setdefault(metric, []).append(value)
            metrics = {}
            for metric in sorted(grouped):
                vals = grouped[metric]
                metrics[metric] = {'count': len(vals), 'average': sum(vals) / len(vals), 'minimum': min(vals), 'maximum': max(vals)}
            ws = start + index * window
            windows.append({'start': ws, 'end': min(ws + window, end), 'metrics': metrics})
        output.append({'id': machine['id'], 'name': machine['name'], 'windows': windows})
    return {'tenant': requester['tenant_id'], 'start': start, 'end': end, 'window': window, 'machines': output}

