        raise ValueError('config must be a mapping')
    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('TRAINING_REPORT_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('a non-empty signing key is required')
    completed_count = 0
