            raise ValueError('each record must be a dictionary')
        employee_id = record.get('employee_id')
        course = record.get('course')
        score = record.get('score')
        completed = record.get('completed')
        if not isinstance(employee_id, str) or not employee_id or (not isinstance(course, str)) or (not course):
            raise ValueError('record has invalid text fields')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100):
            raise ValueError('record has invalid score')
        if not isinstance(completed, bool):
            raise ValueError('record has invalid completion flag')
        if completed:
            completed_count += 1
        if completed and score >= 70:
            qualified_count += 1
            groups.setdefault(employee_id, []).append((course, score))
    employees = []
    for employee_id, entries in groups.items():
