import json
import math

def encode_mission_state(state: dict) -> bytes:
    return json.dumps(state, separators=(',', ':'), allow_nan=False).encode('utf-8')

def decode_mission_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError):
        raise ValueError('invalid mission state')
    if not isinstance(value, dict):
        raise ValueError('invalid mission state')
    return value

def _number(value):
    return isinstance(value, (int, float)) and (not isinstance(value, bool)) and math.isfinite(value)

def plan_mission(state: dict, reserve_battery: float=0.15) -> dict:
    if not isinstance(state, dict) or not _number(reserve_battery) or (not 0 <= reserve_battery <= 1):
        raise ValueError('invalid state')
    required = ('start', 'battery', 'cruise_speed', 'consumption_per_distance', 'waypoints')
    if any((k not in state for k in required)) or not _number(state['battery']) or state['battery'] < 0:
        raise ValueError('invalid state')
    if not _number(state['cruise_speed']) or state['cruise_speed'] <= 0 or (not _number(state['consumption_per_distance'])) or (state['consumption_per_distance'] < 0):
        raise ValueError('invalid state')
    if not isinstance(state['start'], list) or len(state['start']) != 2 or (not all((_number(x) for x in state['start']))):
        raise ValueError('invalid state')
    points = state['waypoints']
    if not isinstance(points, list):
        raise ValueError('invalid state')
    seen = set()
    checked = []
    for p in points:
        if not isinstance(p, dict) or not isinstance(p.get('id'), str) or (not p['id']) or (p['id'] in seen):
            raise ValueError('invalid waypoint')
        seen.add(p['id'])
        if not isinstance(p.get('position'), list) or len(p['position']) != 2 or (not all((_number(x) for x in p['position']))):
            raise ValueError('invalid waypoint')
        if not isinstance(p.get('priority'), int) or isinstance(p['priority'], bool) or (not isinstance(p.get('window'), list)) or (len(p['window']) != 2) or (not all((_number(x) for x in p['window']))):
            raise ValueError('invalid waypoint')
        if p['window'][0] > p['window'][1] or not _number(p.get('service_minutes')) or p['service_minutes'] < 0:
            raise ValueError('invalid waypoint')
        checked.append(p)
    checked.sort(key=lambda p: (-p['priority'], p['window'][0], p['id']))
    x, y = state['start']
    now = 0.0
    distance_total = used = 0.0
    output = []
    for p in checked:
        dx, dy = (p['position'][0] - x, p['position'][1] - y)
        distance = math.hypot(dx, dy)
        arrival = now + distance / state['cruise_speed']
        begin = max(arrival, p['window'][0])
        finish = begin + p['service_minutes']
        if begin > p['window'][1]:
            raise ValueError('window missed')
        output.append({'id': p['id'], 'distance': round(distance, 6), 'arrival': round(arrival, 6), 'start_service': round(begin, 6), 'finish': round(finish, 6)})
        distance_total += distance
        used += distance * state['consumption_per_distance'] + p['service_minutes'] * 0.01
        now = finish
        x, y = p['position']
    if used > state['battery'] * (1 - reserve_battery) + 1e-12:
        raise ValueError('battery limit')
    return {'waypoints': output, 'total_distance': round(distance_total, 6), 'total_minutes': round(now, 6), 'battery_used': round(used, 6), 'battery_remaining': round(state['battery'] - used, 6)}

