def make_payload(reports):
    return json.dumps({"reports": reports}, separators=(",", ":"))


def sign(payload, key=b"probation-key"):
    return hmac.new(key, payload.encode(), hashlib.sha256).hexdigest()


def test_empty_reports():
    payload = make_payload([])
    assert verify_and_summarize(payload, sign(payload), b"probation-key") == {
        "total_reports": 0,
        "completed_reports": 0,
        "officers": [],
    }


