        {"client": "C", "officer": "Amy", "status": "completed", "days_late": 4},
        {"client": "D", "officer": "Zoe", "status": "completed", "days_late": 2},
        {"client": "E", "officer": "Bob", "status": "completed", "days_late": 4},
    ]
    payload = make_payload(reports)
