    assert result == {
        "total_reports": 5,
        "completed_reports": 4,
        "officers": [
            {"officer": "Amy", "reports": 1, "days_late": 4, "average_days_late": 4.0},
            {"officer": "Bob", "reports": 1, "days_late": 4, "average_days_late": 4.0},
