import hmac
import json

def verify_and_summarize(payload: str, signature: str, key: bytes) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(key, bytes)):
        raise ValueError('invalid input')
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, ValueError):
        raise ValueError('invalid document')
    if not isinstance(document, dict) or not isinstance(document.get('reports'), list):
        raise ValueError('invalid reports')
    reports = document['reports']
    grouped = {}
    completed = 0
    for report in reports:
        if not isinstance(report, dict):
            raise ValueError('invalid report')
        client = report.get('client')
        officer = report.get('officer')
        status = report.get('status')
        days = report.get('days_late')
        if not isinstance(client, str) or not client or (not isinstance(officer, str)) or (not officer) or (status not in ('completed', 'pending')) or isinstance(days, bool) or (not isinstance(days, int)) or (days < 0):
            raise ValueError('invalid report')
        if status == 'completed':
            completed += 1
            item = grouped.setdefault(officer, [0, 0])
            item[0] += 1
            item[1] += days
    officers = []
    for officer, (count, total) in grouped.items():
        officers.append({'officer': officer, 'reports': count, 'days_late': total, 'average_days_late': round(total / count, 2)})
    officers.sort(key=lambda item: (-item['days_late'], item['officer']))
    return {'total_reports': len(reports), 'completed_reports': completed, 'officers': officers}

