import math
import os
from collections import defaultdict
from pathlib import Path

def annotate_to_file(variant_text: str, output_dir: str, filename: str, min_quality: float=0.0) -> str:
    try:
        threshold = float(min_quality)
    except (TypeError, ValueError):
        raise ValueError('invalid quality threshold')
    if not math.isfinite(threshold) or threshold < 0:
        raise ValueError('invalid quality threshold')
    header = 'chrom\tpos\tref\talt\tgene\timpact\tquality'
    lines = [line for line in variant_text.splitlines() if line.strip() and (not line.startswith('#'))]
    if not lines or lines[0] != header:
        raise ValueError('invalid header')
    groups = defaultdict(list)
    for line in lines[1:]:
        fields = line.split('\t')
        if len(fields) != 7:
            raise ValueError('invalid row')
        chrom, pos_text, ref, alt, gene, impact, quality_text = fields
        if not chrom or not ref or (not alt) or (not gene) or (impact not in {'LOW', 'MODERATE', 'HIGH'}):
            raise ValueError('invalid row')
        try:
            pos = int(pos_text)
            quality = float(quality_text)
        except (TypeError, ValueError):
            raise ValueError('invalid row')
        if pos <= 0 or not math.isfinite(quality):
            raise ValueError('invalid row')
        if quality >= threshold:
            groups[gene].append((chrom, pos, quality))
    output = ['gene\tvariant_count\tmean_quality\tpositions\n']
    ordered = sorted(groups.items(), key=lambda item: (-len(item[1]), item[0]))
    for gene, values in ordered:
        values.sort(key=lambda item: (item[0], item[1]))
        mean = sum((item[2] for item in values)) / len(values)
        positions = ','.join((f'{chrom}:{pos}' for chrom, pos, _ in values))
        output.append(f'{gene}\t{len(values)}\t{mean:.2f}\t{positions}\n')
    base = Path(output_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    target = (base / filename).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid output path')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(''.join(output), encoding='utf-8')
    return str(target)

