from datetime import datetime, timezone
from html import escape

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        result = datetime.fromisoformat(value[:-1] + '+00:00')
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if result.tzinfo != timezone.utc:
        raise ValueError('invalid timestamp')
    return result

def _split(line):
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('unfinished escape')
    fields.append(''.join(current))
    return fields

def parse_alerts(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split(raw)
        if len(fields) != 5:
            raise ValueError('wrong field count')
        timestamp, room, category, severity, message = fields
        _time(timestamp)
        if not room or not category:
            raise ValueError('empty field')
        try:
            level = int(severity)
        except ValueError:
            raise ValueError('invalid severity')
        if str(level) != severity or not 1 <= level <= 5:
            raise ValueError('invalid severity')
        result.append({'timestamp': timestamp, 'room': room, 'category': category, 'severity': level, 'message': message})
    return result

def _check(alert):
    if not isinstance(alert, dict) or set(alert) != {'timestamp', 'room', 'category', 'severity', 'message'}:
        raise ValueError('invalid alert')
    _time(alert['timestamp'])
    if not isinstance(alert['room'], str) or not alert['room'] or (not isinstance(alert['category'], str)) or (not alert['category']):
        raise ValueError('invalid alert')
    if type(alert['severity']) is not int or not 1 <= alert['severity'] <= 5:
        raise ValueError('invalid alert')

def summarize_alerts(alerts: list[dict], start: str, end: str) -> dict:
    begin, finish = (_time(start), _time(end))
    if begin >= finish:
        raise ValueError('invalid interval')
    chosen = []
    for alert in alerts:
        _check(alert)
        moment = _time(alert['timestamp'])
        if begin <= moment < finish:
            chosen.append(alert)
    groups = {}
    for alert in chosen:
        item = groups.setdefault(alert['category'], [0, 0])
        item[0] += 1
        item[1] = max(item[1], alert['severity'])
    return {'total': len(chosen), 'by_category': [{'category': k, 'count': groups[k][0], 'max_severity': groups[k][1]} for k in sorted(groups)], 'rooms': sorted({a['room'] for a in chosen})}

def render_alert_report(alerts: list[dict], title: str) -> str:
    for alert in alerts:
        _check(alert)
    ordered = sorted(alerts, key=lambda a: (-a['severity'], _time(a['timestamp']), a['room'], a['category']))
    rows = ''.join(('<tr><td>' + escape(a['room']) + '</td><td>' + escape(a['category']) + '</td><td>' + str(a['severity']) + '</td><td>' + escape(a['timestamp']) + '</td><td>' + escape(a['message']) + '</td></tr>' for a in ordered))
    return '<section class="maintenance"><h1>' + escape(title) + '</h1><table><thead><tr><th>Room</th><th>Category</th><th>Severity</th><th>Timestamp</th><th>Message</th></tr></thead><tbody>' + rows + '</tbody></table></section>'

