from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import math

def authorize_expense(requester: dict, grant: dict, expense: dict) -> dict:
    if requester.get('tenant_id') != grant.get('tenant_id') or (requester.get('id') != grant.get('owner_id') and 'grants_admin' not in requester.get('roles', [])):
        raise PermissionError('not authorized')
    try:
        expense_id = expense['id']
        amount_value = expense['amount']
        date_text = expense['date']
        category = expense['category']
        description = expense['description']
        limit = Decimal(str(grant['monthly_limit']))
    except (KeyError, TypeError, InvalidOperation):
        raise ValueError('invalid expense')
    if not isinstance(expense_id, str) or not expense_id:
        raise ValueError('invalid id')
    try:
        parsed_date = date.fromisoformat(date_text)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if not isinstance(category, str) or category not in {'personnel', 'equipment', 'travel', 'supplies'}:
        raise ValueError('invalid category')
    if not isinstance(description, str) or not description.strip() or len(description.strip()) > 200:
        raise ValueError('invalid description')
    try:
        amount = Decimal(str(amount_value))
        if isinstance(amount_value, bool) or (isinstance(amount_value, float) and (not math.isfinite(amount_value))):
            raise ValueError
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid amount')
    if amount <= 0 or amount.as_tuple().exponent < -2:
        raise ValueError('invalid amount')
    amount_cents = int((amount * 100).to_integral_value(rounding=ROUND_HALF_UP))
    if not limit.is_finite() or limit < 0:
        raise ValueError('invalid limit')
    ids = set()
    total = Decimal('0')
    month = parsed_date.strftime('%Y-%m')
    for old in grant.get('expenses', []):
        if old.get('id') in ids:
            raise ValueError('duplicate id')
        ids.add(old.get('id'))
        try:
            old_date = date.fromisoformat(old['date'])
            old_amount = Decimal(str(old['amount']))
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid existing expense')
        if old_amount < 0 or old_amount.as_tuple().exponent < -2:
            raise ValueError('invalid existing expense')
        if old_date.strftime('%Y-%m') == month:
            total += old_amount
    if expense_id in ids:
        raise ValueError('duplicate id')
    total += amount
    if total > limit:
        raise ValueError('monthly limit exceeded')
    total_cents = int((total * 100).to_integral_value(rounding=ROUND_HALF_UP))
    limit_cents = int((limit * 100).to_integral_value(rounding=ROUND_HALF_UP))
    return {'grant_id': grant['id'], 'expense_id': expense_id, 'month': month, 'amount_cents': amount_cents, 'total_month_cents': total_cents, 'remaining_cents': limit_cents - total_cents, 'category': category, 'date': date_text, 'description': description.strip()}

