import datetime
import hashlib
import hmac
import json

def _validate(manifest):
    if not isinstance(manifest, dict) or set(manifest) != {'loans'} or (not isinstance(manifest['loans'], list)):
        raise ValueError('invalid manifest')
    seen = set()
    for item in manifest['loans']:
        if not isinstance(item, dict) or set(item) != {'id', 'object', 'borrower', 'start', 'end', 'crates', 'priority'}:
            raise ValueError('invalid loan')
        if any((not isinstance(item[k], str) or not item[k] for k in ('id', 'object', 'borrower'))):
            raise ValueError('invalid text')
        if item['id'] in seen or not isinstance(item['crates'], int) or isinstance(item['crates'], bool) or (item['crates'] <= 0) or (not isinstance(item['priority'], int)) or isinstance(item['priority'], bool) or (not 0 <= item['priority'] <= 9):
            raise ValueError('invalid loan values')
        try:
            start = datetime.date.fromisoformat(item['start'])
            end = datetime.date.fromisoformat(item['end'])
        except ValueError:
            raise ValueError('invalid date')
        if start >= end or start.isoformat() != item['start'] or end.isoformat() != item['end']:
            raise ValueError('invalid date range')
        seen.add(item['id'])

def canonical_manifest(payload: str) -> bytes:
    try:
        value = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid json')
    _validate(value)
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')

def build_dispatch_plan(manifest: dict) -> list[dict]:
    _validate(manifest)
    days = {}
    for item in manifest['loans']:
        day = datetime.date.fromisoformat(item['start'])
        end = datetime.date.fromisoformat(item['end'])
        while day < end:
            days.setdefault(day, []).append(item)
            day += datetime.timedelta(days=1)
    result = []
    for day in sorted(days):
        active = days[day]
        total = sum((x['crates'] for x in active))
        if total > 20:
            raise ValueError('daily capacity exceeded')
        ordered = sorted(active, key=lambda x: (-x['priority'], x['id']))
