import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_grants(paths: list[str], category: str | None=None, page: int=1, page_size: int=10) -> list[tuple[str, float]]:
    if not paths:
        raise ValueError('paths must not be empty')
    if isinstance(page, bool) or not isinstance(page, int) or isinstance(page_size, bool) or (not isinstance(page_size, int)):
        raise TypeError('page and page_size must be integers')
    if page <= 0 or page_size <= 0:
        raise ValueError('page and page_size must be positive')
    result = subprocess.run(['sort', '-t', '\t', '-k1,1', *paths], capture_output=True, text=True, check=True)
    totals = {}
    for line in result.stdout.splitlines():
        fields = line.split('\t')
        if len(fields) != 3:
            raise ValueError('malformed record')
        recipient, record_category, raw_amount = fields
        if not recipient or not record_category:
            raise ValueError('empty field')
        try:
            amount = Decimal(raw_amount)
        except InvalidOperation as exc:
            raise ValueError('invalid amount') from exc
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid amount')
        if category is None or record_category == category:
            totals[recipient] = totals.get(recipient, Decimal('0')) + amount
    ordered = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    selected = ordered[start:start + page_size]
    return [(name, float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))) for name, total in selected]

