class _ReadingHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.readings = []
        self.current = None
        self.element = None
        self.text = []

    def startElement(self, name, attrs):
        if name == 'reading':
            self.current = {'station': attrs['station']}
        elif name == 'decibels':
