import hmac
import json

def summarize_reload_webhook(payload: str, signature: str, secret: str, offset: int=0, limit: int=10) -> list[dict]:
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    if not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0:
        raise ValueError('invalid limit')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('events'), list):
        raise ValueError('invalid events')
    groups = {}
    for event in document['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        pid = event.get('pass_id')
        amount = event.get('amount_cents')
        timestamp = event.get('timestamp')
        status = event.get('status')
        if not isinstance(pid, str) or not pid or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount <= 0) or (not isinstance(timestamp, int)) or isinstance(timestamp, bool) or (timestamp < 0) or (not isinstance(status, str)):
            raise ValueError('invalid event')
        if status == 'completed':
            item = groups.setdefault(pid, {'pass_id': pid, 'total_cents': 0, 'reload_count': 0, 'last_timestamp': 0})
            item['total_cents'] += amount
            item['reload_count'] += 1
            item['last_timestamp'] = max(item['last_timestamp'], timestamp)
    result = list(groups.values())
    result.sort(key=lambda x: (-x['total_cents'], -x['last_timestamp'], x['pass_id']))
    return result[offset:offset + limit]

