import re
import secrets

def generate_permit_access_code(permit_number: str, length: int=12) -> str:
    if not isinstance(permit_number, str):
        raise TypeError('permit_number must be a string')
    if isinstance(length, bool) or not isinstance(length, int):
        raise TypeError('length must be an integer')
    if length < 8 or length > 64:
        raise ValueError('length must be between 8 and 64')
    normalized = permit_number.strip().upper()
    if not re.fullmatch('[A-Z0-9]+(?:-[A-Z0-9]+)*', normalized):
        raise ValueError('invalid permit number')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    suffix = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return f'PERMIT-{normalized}-{suffix}'

