import tempfile

def export_alerts(alerts: list[dict[str, object]], destination: str, minimum_magnitude: float=4.0) -> int:
    selected = []
    for alert in alerts:
        if not isinstance(alert.get('timestamp'), str) or not isinstance(alert.get('region'), str) or isinstance(alert.get('magnitude'), bool) or (not isinstance(alert.get('magnitude'), (int, float))):
            raise ValueError('invalid alert')
        if alert['magnitude'] >= minimum_magnitude:
            selected.append(alert)
    selected.sort(key=lambda alert: alert['timestamp'])
    directory = os.path.dirname(os.path.abspath(destination))
    temporary = tempfile.mktemp(prefix='.alerts-', suffix='.csv', dir=directory)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['timestamp', 'region', 'magnitude'])
            for alert in selected:
                writer.writerow([alert['timestamp'], alert['region'], f"{alert['magnitude']:.1f}"])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(selected)

