        raise ValueError('invalid offset')
    order = 'best_score DESC, player COLLATE NOCASE ASC' if sort == 'score' else 'player COLLATE NOCASE ASC, best_score DESC'
    query = f'SELECT player, MAX(score) AS best_score FROM scores WHERE game = ? AND season = ? AND player LIKE ? GROUP BY player ORDER BY {order} LIMIT ? OFFSET ?'
