import os
import subprocess

def collect_evidence(directory: str, suffixes: list[str], page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(directory, str):
        raise TypeError('directory must be a string')
    if not isinstance(suffixes, list) or any((not isinstance(item, str) for item in suffixes)):
        raise TypeError('suffixes must be a list of strings')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    records = []
    for entry in os.scandir(directory):
        if not entry.is_file() or not any((entry.name.endswith(suffix) for suffix in suffixes)):
            continue
        result = subprocess.run(['wc', '-c', '--', entry.path], capture_output=True, text=True, check=True)
        count = int(result.stdout.split()[0])
        records.append({'name': entry.name, 'bytes': count, 'kilobytes': round(count / 1024, 2)})
    records.sort(key=lambda item: (-item['bytes'], item['name']))
    start = (page - 1) * page_size
    return records[start:start + page_size]

