import datetime
import xml.etree.ElementTree as ET

def _date(value):
    try:
        result = datetime.date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if result.isoformat() != value:
        raise ValueError('invalid date')
    return result

def _read(xml):
    try:
        root = ET.fromstring(xml)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'campaign_feed':
        raise ValueError('invalid root')
    rows = []
    for campaign in root:
        if campaign.tag != 'campaign' or not campaign.get('id') or (not campaign.get('name')):
            raise ValueError('invalid campaign')
        seen = set()
        for item in campaign:
            if item.tag != 'deliverable':
                raise ValueError('invalid child')
            ident = item.get('id')
            creator = item.get('creator')
            platform = item.get('platform')
            due = item.get('due')
            status = item.get('status')
            if not all((ident, creator, platform, due, status)) or status not in {'pending', 'submitted', 'approved', 'rejected'}:
                raise ValueError('invalid deliverable')
            if ident in seen:
                raise ValueError('duplicate id')
            seen.add(ident)
            day = _date(due)
            tags_node = item.find('tags')
            tags = []
            if tags_node is not None and tags_node.text:
                for tag in tags_node.text.split(','):
                    tag = tag.strip()
                    if tag and tag not in tags:
                        tags.append(tag)
            metrics = item.find('metrics')
            if metrics is None:
                raise ValueError('missing metrics')
            values = []
            for name in ('views', 'likes', 'comments'):
                node = metrics.find(name)
                if node is None or node.text is None or (not node.text.isdecimal()):
                    raise ValueError('invalid metric')
                values.append(int(node.text))
            rows.append({'campaign_id': campaign.get('id'), 'campaign_name': campaign.get('name'), 'id': ident, 'creator': creator, 'platform': platform, 'due': due, 'status': status, 'tags': tags, 'engagement': values[0] + 2 * values[1] + 3 * values[2], '_day': day})
    return rows

def parse_deliverables(xml: str) -> list[dict]:
    rows = _read(xml)
    order = {'pending': 0, 'submitted': 1, 'approved': 2, 'rejected': 3}
    rows.sort(key=lambda row: (row['_day'], order[row['status']], row['id']))
    for row in rows:
        del row['_day']
    return rows

def summarize_campaign(xml: str, as_of: str) -> dict:
    day = _date(as_of)
    rows = _read(xml)
    platforms = {}
    for row in rows:
        platforms[row['platform']] = platforms.get(row['platform'], 0) + 1
    return {'campaigns': len({row['campaign_id'] for row in rows}), 'deliverables': len(rows), 'by_platform': platforms, 'total_engagement': sum((row['engagement'] for row in rows)), 'overdue': sum((row['_day'] < day and row['status'] != 'approved' for row in rows))}

