    blob = encode_alarm_events(events)
    assert isinstance(blob, bytes)
    assert summarize_alarm_events(blob, 9, 11) == {'total': 3, 'by_kind': {'open': 1, 'close': 0, 'motion': 1, 'tamper': 1}, 'active_sensors': ['front'], 'timeline': [event('front', 9, 1, 'open'), event('garage', 10, 1, 'tamper'), event('front', 10, 2, 'motion')]}

def test_sorting_ties_and_duplicate_events():
    events = [event('z', 5, 2, 'motion'), event('a', 5, 2, 'open'), event('b', 5, 1, 'close'), event('a', 5, 2, 'open')]
    result = summarize_alarm_events(encode_alarm_events(events), 5, 6)
    assert result['timeline'] == [event('b', 5, 1, 'close'), event('a', 5, 2, 'open'), event('a', 5, 2, 'open'), event('z', 5, 2, 'motion')]
    assert result['active_sensors'] == ['a']
    assert result['by_kind'] == {'open': 2, 'close': 1, 'motion': 1, 'tamper': 0}

