    events = [event('door', 1, 0, 'open'), event('door', 3, 0, 'close'), event('window', 4, 0, 'open')]
    result = summarize_alarm_events(encode_alarm_events(events), 2, 4)
    assert result['total'] == 1
    assert result['timeline'] == [event('door', 3, 0, 'close')]
    assert result['active_sensors'] == []

