    events = [event('x', 1, 0, 'open')]
    assert summarize_alarm_events(encode_alarm_events(events), 8, 8) == {'total': 0, 'by_kind': {'open': 0, 'close': 0, 'motion': 0, 'tamper': 0}, 'active_sensors': [], 'timeline': []}

