from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import requests

def get_project_billing(base_url: str, project_id: str, start_date: str, end_date: str, page_size: int=100) -> dict:
    if not isinstance(project_id, str) or not project_id:
        raise ValueError('project_id')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 1000):
        raise ValueError('page_size')
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('dates')
    if start > end:
        raise ValueError('date range')
    groups = {}
    offset = 0
    while True:
        response = requests.get(base_url.rstrip('/') + '/v1/invoices', params={'project_id': project_id, 'start_date': start_date, 'end_date': end_date, 'limit': page_size, 'offset': offset}, headers={'Accept': 'application/json'})
        if not 200 <= response.status_code < 300:
            raise RuntimeError('billing request failed')
        try:
            payload = response.json()
        except Exception as exc:
            raise ValueError('invalid response') from exc
        if not isinstance(payload, dict) or not isinstance(payload.get('items'), list):
            raise ValueError('invalid response')
        for item in payload['items']:
            if not isinstance(item, dict):
                raise ValueError('invalid invoice')
            try:
                item_date = date.fromisoformat(item['date'])
            except (KeyError, TypeError, ValueError) as exc:
                raise ValueError('invalid invoice') from exc
            if item['status'] != 'approved' or not start <= item_date <= end:
                continue
            try:
                consultant = item['consultant']
                hours = Decimal(str(item['hours']))
                amount = hours * Decimal(str(item['rate']))
                if not isinstance(consultant, str):
                    raise ValueError
            except (KeyError, TypeError, ValueError, InvalidOperation) as exc:
                raise ValueError('invalid invoice') from exc
            group = groups.setdefault(consultant, [Decimal('0'), Decimal('0')])
            group[0] += hours
            group[1] += amount
        next_offset = payload.get('next_offset')
        if next_offset is None:
            break
        if not isinstance(next_offset, int) or isinstance(next_offset, bool):
            raise ValueError('invalid response')
        offset = next_offset
    quantum = Decimal('0.01')
    entries = [{'consultant': name, 'hours': float(values[0].quantize(quantum, rounding=ROUND_HALF_UP)), 'amount': float(values[1].quantize(quantum, rounding=ROUND_HALF_UP))} for name, values in groups.items()]
    entries.sort(key=lambda x: (-x['amount'], x['consultant']))
    total = sum((values[1] for values in groups.values()), Decimal('0')).quantize(quantum, rounding=ROUND_HALF_UP)
    return {'project_id': project_id, 'total': float(total), 'by_consultant': entries}

