from datetime import date
_STATUSES = {'queued', 'assigned', 'in_progress', 'filed', 'cancelled'}
_TRANSITIONS = {'queued': {'assigned', 'cancelled'}, 'assigned': {'in_progress', 'queued', 'cancelled'}, 'in_progress': {'filed', 'assigned', 'cancelled'}, 'filed': {'filed'}, 'cancelled': {'cancelled'}}

def _fields(line):
    out = []
    cur = []
    i = 0
    while i < len(line):
        ch = line[i]
        if ch == '\\':
            if i + 1 == len(line):
                raise ValueError('trailing escape')
            nxt = line[i + 1]
            if nxt in '|\\':
                cur.append(nxt)
            else:
                cur.extend(('\\', nxt))
            i += 2
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
            i += 1
        else:
            cur.append(ch)
            i += 1
    out.append(''.join(cur))
    return out

def _tags(value):
    if value == '':
        return []
    out = []
    cur = []
    i = 0
    while i < len(value):
        if value[i] == '\\':
            if i + 1 == len(value):
                raise ValueError('trailing escape')
            cur.append(value[i + 1])
            i += 2
        elif value[i] == ',':
            out.append(''.join(cur))
            cur = []
            i += 1
        else:
            cur.append(value[i])
            i += 1
    out.append(''.join(cur))
    return out

def parse_assignment_feed(text: str) -> list[dict]:
    result = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip() or raw.startswith('#'):
            continue
        f = _fields(raw)
        if len(f) != 7:
            raise ValueError('wrong field count')
        ident, tenant, owner, status, due, minutes, tags = f
        if not ident or not tenant or (not owner) or (ident in seen) or (status not in _STATUSES):
            raise ValueError('invalid assignment')
        try:
            date.fromisoformat(due)
            number = int(minutes)
        except Exception as e:
            raise ValueError('invalid date or minutes') from e
        if number < 0:
            raise ValueError('negative minutes')
        tv = _tags(tags)
        if any((not x for x in tv)):
            raise ValueError('empty tag')
        seen.add(ident)
        result.append({'id': ident, 'tenant': tenant, 'owner': owner, 'status': status, 'due': due, 'minutes': number, 'tags': tv})
    return result

def _allowed(requester, record):
    return requester['tenant'] == record['tenant'] and (requester['id'] == record['owner'] or bool(set(requester.get('roles', [])) & {'editor', 'admin'}))

def update_assignment(requester: dict, assignments: list[dict], assignment_id: str, new_status: str, minutes_delta: int=0) -> list[dict]:
    if new_status not in _STATUSES or not isinstance(minutes_delta, int):
        raise ValueError('invalid update')
    found = next((r for r in assignments if r['id'] == assignment_id), None)
    if found is None:
        raise KeyError(assignment_id)
    if not _allowed(requester, found):
        raise PermissionError('not permitted')
    if new_status not in _TRANSITIONS[found['status']] or found['minutes'] + minutes_delta < 0:
        raise ValueError('invalid transition')
    result = [dict(r, tags=list(r['tags'])) for r in assignments]
    for r in result:
        if r['id'] == assignment_id:
            r['status'] = new_status
            r['minutes'] += minutes_delta
    return result

def workload_report(requester: dict, assignments: list[dict], tenant: str, as_of: str) -> list[dict]:
    try:
        cutoff = date.fromisoformat(as_of)
    except Exception as e:
        raise ValueError('invalid date') from e
    rows = [r for r in assignments if r['tenant'] == tenant and r['status'] != 'cancelled' and (date.fromisoformat(r['due']) <= cutoff)]
    if rows and any((not _allowed(requester, r) for r in rows)):
        raise PermissionError('not permitted')
    grouped = {}
    for r in rows:
        v = grouped.setdefault(r['owner'], [0, 0, 0])
        v[0] += 1
        v[1] += r['minutes']
        v[2] += date.fromisoformat(r['due']) < cutoff
    return [{'owner': o, 'assignment_count': v[0], 'total_minutes': v[1], 'overdue_count': v[2]} for o, v in sorted(grouped.items(), key=lambda x: (-x[1][1], -x[1][0], x[0]))]

