import json
from pathlib import Path

def write_drift_report(base_dir: str, relative_name: str, records: list[dict]) -> str:
    if not isinstance(base_dir, str) or not isinstance(relative_name, str) or (not relative_name):
        raise ValueError('invalid path')
    if not isinstance(records, list):
        raise ValueError('invalid records')
    clean = []
    environments = set()
    for record in records:
        if not isinstance(record, dict) or not all((key in record for key in ('resource', 'environment', 'expected', 'actual'))):
            raise ValueError('invalid record')
        if not isinstance(record['resource'], str) or not isinstance(record['environment'], str):
            raise ValueError('invalid record')
        item = {key: record[key] for key in ('resource', 'environment', 'expected', 'actual')}
        clean.append(item)
        environments.add(item['environment'])
    drifted = [item for item in clean if item['expected'] != item['actual']]
    drifted.sort(key=lambda item: (item['environment'], item['resource']))
    counts = {environment: 0 for environment in sorted(environments)}
    for item in drifted:
        counts[item['environment']] += 1
    report = {'summary': {'total_resources': len(clean), 'drifted_resources': len(drifted), 'by_environment': counts}, 'drifted': drifted}
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    if target != base and base not in target.parents:
        raise ValueError('invalid path')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    return str(target)

