    if not 13 <= len(digits) <= 19:
        raise ValueError('invalid card length')
    total = 0
    parity = len(digits) % 2
    for i, char in enumerate(digits):
        n = int(char)
        if i % 2 == parity:
            n *= 2
            if n > 9:
                n -= 9
        total += n
    if total % 10:
        raise ValueError('invalid card checksum')
    return digits

