        self._check_requester(requester)
        digits = normalize_card(card_number)
        if not isinstance(expiry, str) or not re.fullmatch('[0-9]{4}-[0-9]{2}', expiry):
            raise ValueError('invalid expiry')
        year, month = map(int, expiry.split('-'))
        if not 1 <= month <= 12 or (year, month) < (self.today.year, self.today.month):
