    if not isinstance(filename, str) or not filename or os.path.isabs(filename):
        raise ValueError('invalid filename')
    required = ('id', 'customer', 'vehicle', 'score', 'status', 'created')
    selected = []
    for lead in leads:
        if any((key not in lead for key in required)):
            raise ValueError('invalid lead')
        if not isinstance(lead['score'], int) or isinstance(lead['score'], bool) or (not 0 <= lead['score'] <= 100):
            raise ValueError('invalid lead score')
        if lead['status'] in ('new', 'contacted') and lead['score'] >= min_score:
            selected.append(lead)
    selected.sort(key=lambda lead: (-lead['score'], lead['created'], lead['id']))
    base = Path(base_dir).resolve()
    target = (base / filename).resolve()
    if target != base and base not in target.parents:
        raise ValueError('invalid filename')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', encoding='utf-8', newline='') as handle:
        writer = csv.writer(handle)
        writer.writerow(required)
        for lead in selected:
            writer.writerow([lead[key] for key in required])
    return str(target)

