from xml.etree import ElementTree
from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime
from io import StringIO

def summarize_invocation_logs(xml_text: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        root = ElementTree.parse(StringIO(xml_text)).getroot()
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'logs':
        raise ValueError('invalid root')
    groups = {}
    for node in root:
        if node.tag != 'invocation':
            raise ValueError('invalid child')
        try:
            function = node.attrib['function']
            status = node.attrib['status']
            duration = Decimal(node.attrib['duration_ms'])
            timestamp = node.attrib['timestamp']
            parsed_time = datetime.fromisoformat(timestamp)
        except Exception as exc:
            raise ValueError('invalid invocation') from exc
        if not function or status not in ('success', 'error') or (not duration.is_finite()) or (duration < 0):
            raise ValueError('invalid invocation')
        group = groups.setdefault(function, {'durations': [], 'errors': 0, 'latest': (parsed_time, timestamp)})
        group['durations'].append(duration)
        if status == 'error':
            group['errors'] += 1
        if parsed_time > group['latest'][0]:
            group['latest'] = (parsed_time, timestamp)
    summaries = []
    quant = Decimal('0.01')
