import hmac
import json
import re
_ID = re.compile('^[A-Za-z0-9_-]+$')
_FORMATS = {'svg': 0, 'png': 1, 'jpg': 2}
_KEYS = {'id', 'brand', 'format', 'width', 'height', 'tags'}

def load_manifest(payload: bytes, signature: str, secret: bytes) -> list[dict]:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid input')
    if len(signature) != 71 or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        root = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid document')
    if not isinstance(root, dict) or set(root) != {'assets'} or (not isinstance(root['assets'], list)):
        raise ValueError('invalid document')
    result = []
    for item in root['assets']:
        if not isinstance(item, dict) or set(item) != _KEYS:
            raise ValueError('invalid asset')
        ident, brand, fmt = (item['id'], item['brand'], item['format'])
        if not isinstance(ident, str) or not ident or (not _ID.fullmatch(ident)):
            raise ValueError('invalid asset')
        if not isinstance(brand, str) or not brand.strip() or fmt not in _FORMATS:
            raise ValueError('invalid asset')
        width, height = (item['width'], item['height'])
        if isinstance(width, bool) or not isinstance(width, int) or (not 1 <= width <= 10000) or isinstance(height, bool) or (not isinstance(height, int)) or (not 1 <= height <= 10000):
            raise ValueError('invalid asset')
        tags = item['tags']
        if not isinstance(tags, list):
            raise ValueError('invalid asset')
        clean = set()
        for tag in tags:
            if not isinstance(tag, str) or not tag.strip():
                raise ValueError('invalid asset')
            clean.add(tag.strip().lower())
        result.append({'id': ident, 'brand': brand.strip(), 'format': fmt, 'width': width, 'height': height, 'tags': sorted(clean)})
    result.sort(key=lambda x: (x['brand'], _FORMATS[x['format']], -(x['width'] * x['height']), x['id']))
    return result

def build_catalog(assets: list[dict]) -> dict:
    if not isinstance(assets, list):
        raise ValueError('invalid records')
    groups = {}
    total = 0
    for item in assets:
        if not isinstance(item, dict) or set(item) != _KEYS:
            raise ValueError('invalid record')
        if not isinstance(item['id'], str) or not isinstance(item['brand'], str) or item['format'] not in _FORMATS or isinstance(item['width'], bool) or (not isinstance(item['width'], int)) or (item['width'] < 1) or isinstance(item['height'], bool) or (not isinstance(item['height'], int)) or (item['height'] < 1) or (not isinstance(item['tags'], list)):
            raise ValueError('invalid record')
        pixels = item['width'] * item['height']
        total += pixels
        group = groups.setdefault(item['brand'], {'assets': 0, 'pixels': 0, 'formats': {}})
        group['assets'] += 1
        group['pixels'] += pixels
        f = group['formats'].setdefault(item['format'], [0, 0])
        f[0] += 1
        f[1] += pixels
    brands = []
    for brand in sorted(groups):
        group = groups[brand]
        formats = [{'format': f, 'count': group['formats'][f][0], 'pixels': group['formats'][f][1]} for f in sorted(group['formats'])]
        brands.append({'brand': brand, 'assets': group['assets'], 'pixels': group['pixels'], 'formats': formats})
    return {'total_assets': len(assets), 'total_pixels': total, 'brands': brands}

