import json
from datetime import date

def serialize_reservations(records: list[dict]) -> bytes:
    return json.dumps(records, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def deserialize_reservations(blob: bytes | str) -> list[dict]:
    try:
        value = json.loads(blob.decode('utf-8') if isinstance(blob, bytes) else blob)
    except Exception as exc:
        raise ValueError('invalid reservation payload') from exc
    if not isinstance(value, list):
        raise ValueError('reservation payload must be a list')
    return value

def _day(value: str) -> date:
    try:
        return date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def _interval(record: dict) -> tuple[date, date]:
    start = _day(record['check_in'])
    end = _day(record['check_out'])
    if end <= start:
        raise ValueError('invalid reservation interval')
    return (start, end)

def room_nights(records: list[dict], start: str, end: str) -> dict[str, int]:
    first, last = (_day(start), _day(end))
    if last <= first:
        raise ValueError('invalid range')
    totals = {}
    for record in records:
        if record['status'] != 'confirmed':
            continue
        begin, finish = _interval(record)
        left, right = (max(first, begin), min(last, finish))
        if left < right:
            room = record['room']
            totals[room] = totals.get(room, 0) + (right - left).days
    return {room: totals[room] for room in sorted(totals) if totals[room]}

def booking_report(records: list[dict]) -> list[dict]:
    grouped = {}
    for record in records:
        if record['status'] != 'confirmed':
            continue
        begin, finish = _interval(record)
        guest = record['guest']
        entry = grouped.setdefault(guest, {'guest': guest, 'nights': 0, 'rooms': set()})
        entry['nights'] += (finish - begin).days
        entry['rooms'].add(record['room'])
    result = [{'guest': x['guest'], 'nights': x['nights'], 'rooms': sorted(x['rooms'])} for x in grouped.values()]
    return sorted(result, key=lambda x: (-x['nights'], x['guest']))

