import csv
import datetime
import math
import os
import tempfile
_HEADER = ['unit', 'timestamp', 'temp_c', 'door_open']
_OUT = ['unit', 'window_start', 'min_temp', 'max_temp', 'avg_temp', 'door_open_count', 'samples']

def _groups(data, minutes):
    if not isinstance(data, str) or not isinstance(minutes, int) or isinstance(minutes, bool) or (minutes <= 0) or 60 % minutes:
        raise ValueError('invalid input')
    try:
        rows = list(csv.reader(data.splitlines()))
    except Exception as e:
        raise ValueError('invalid csv') from e
    if not rows:
        return []
    if rows[0] != _HEADER:
        raise ValueError('invalid header')
    groups = {}
    for row in rows[1:]:
        if len(row) != 4 or not row[0]:
            raise ValueError('invalid row')
        try:
            if not row[1].endswith('Z'):
                raise ValueError
            dt = datetime.datetime.strptime(row[1], '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=datetime.timezone.utc)
            temp = float(row[2])
            if not math.isfinite(temp) or row[3] not in ('0', '1'):
                raise ValueError
        except Exception as e:
            raise ValueError('invalid row') from e
        epoch = int(dt.timestamp())
        start = epoch - epoch % (minutes * 60)
        key = (start, row[0])
        if key not in groups:
            groups[key] = [row[0], start, [], 0]
        groups[key][2].append(temp)
        groups[key][3] += row[3] == '1'
    result = []
    for start, unit in sorted(groups):
        vals = groups[start, unit][2]
        result.append({'unit': unit, 'window_start': datetime.datetime.fromtimestamp(start, datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'), 'min_temp': round(min(vals), 2), 'max_temp': round(max(vals), 2), 'avg_temp': round(sum(vals) / len(vals), 2), 'door_open_count': groups[start, unit][3], 'samples': len(vals)})
    return result

def aggregate_readings(data: str, window_minutes: int=15) -> list[dict]:
    return _groups(data, window_minutes)

