def build_preorder_summary(records: list[dict]) -> list[dict]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be a dictionary')
        try:
            customer = record['customer']
            title = record['title']
            price = record['price']
            copies = record['copies']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not isinstance(customer, str) or not customer.strip():
            raise ValueError('invalid customer')
        if not isinstance(title, str) or not title.strip():
            raise ValueError('invalid title')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or price < 0:
            raise ValueError('invalid price')
        if isinstance(copies, bool) or not isinstance(copies, int) or copies <= 0:
            raise ValueError('invalid copies')
        customer = customer.strip()
        title = title.strip()
        item = grouped.setdefault(customer, {'titles': set(), 'total': 0, 'copies': 0})
        item['titles'].add(title)
        item['total'] += price * copies
        item['copies'] += copies
    result = []
    for customer, item in grouped.items():
        result.append({'customer': customer, 'titles': sorted(item['titles']), 'total': round(item['total'], 2), 'copies': item['copies']})
    return sorted(result, key=lambda item: (-item['total'], item['customer']))

