import json
import math

def dump_state(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def analyze_state(blob: bytes, department: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        data = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(data, list):
        raise ValueError('invalid state')
    fields = ('id', 'title', 'department', 'severity', 'status', 'days_open')
    for record in data:
        if not isinstance(record, dict) or any((key not in record for key in fields)):
            raise ValueError('invalid record')
        for key in ('id', 'title', 'department', 'status'):
            if not isinstance(record[key], str):
                raise ValueError('invalid record')
        for key in ('severity', 'days_open'):
            if isinstance(record[key], bool) or not isinstance(record[key], int):
                raise ValueError('invalid record')
    selected = [r for r in data if department is None or r['department'] == department]
    selected.sort(key=lambda r: (-r['severity'], -r['days_open'], r['id']))
    counts = {}
    for record in selected:
        counts[record['status']] = counts.get(record['status'], 0) + 1
    average = round(sum((r['days_open'] for r in selected)) / len(selected), 2) if selected else 0.0
