    summary['avg_days_open'] = average
    pages = math.ceil(len(selected) / page_size) if selected else 0
    start = (page - 1) * page_size
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'pages': pages, 'items': selected[start:start + page_size], 'summary': summary}

