import re
import secrets
from datetime import date

def _date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_certificates(text: str) -> list[dict]:
    records = []
    seen = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = []
        current = []
        escaped = False
        for ch in line:
            if escaped:
                current.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        if escaped:
            raise ValueError('unfinished escape')
        fields.append(''.join(current))
        if len(fields) != 6:
            raise ValueError('wrong field count')
        ident, name, rank, issued, expires, certs = fields
        if not ident or not name or rank not in {'Master', 'Chief Officer', 'Officer', 'Rating'}:
            raise ValueError('invalid record')
        start, end = (_date(issued), _date(expires))
        if end < start or ident in seen:
            raise ValueError('invalid record')
        names = []
        for item in certs.split(','):
            item = item.strip()
            if not item:
                raise ValueError('invalid certification')
            if item not in names:
                names.append(item)
        if not names:
            raise ValueError('invalid certification')
        seen.add(ident)
        records.append({'id': ident, 'name': name, 'rank': rank, 'issued': issued, 'expires': expires, 'certifications': sorted(names)})
    return records

def certification_report(records: list[dict], on_date: str) -> list[dict]:
    point = _date(on_date)
    priority = {'Master': 0, 'Chief Officer': 1, 'Officer': 2, 'Rating': 3}
    result = []
    for record in records:
        start, end = (_date(record['issued']), _date(record['expires']))
        if start > point:
            active, expired, status = ([], [], 'pending')
        elif end < point:
            active, expired, status = ([], sorted(record['certifications']), 'expired')
        else:
            active, expired, status = (sorted(record['certifications']), [], 'current')
        result.append({'id': record['id'], 'name': record['name'], 'rank': record['rank'], 'active': active, 'expired': expired, 'status': status})
    result.sort(key=lambda x: (-len(x['active']), priority[x['rank']], x['id']))
    return result

def issue_invite(seafarer_id: str) -> dict:
    if not re.fullmatch('[A-Z][A-Z0-9-]{1,11}', seafarer_id):
        raise ValueError('invalid seafarer id')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ123456789'
    return {'seafarer_id': seafarer_id, 'code': ''.join((secrets.choice(alphabet) for _ in range(16)))}

