import hashlib
import hmac
from datetime import datetime, timezone

def _split_escaped(text):
    fields = []
    current = []
    escaped = False
    for char in text:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('incomplete escape')
    fields.append(''.join(current))
    return fields

def _escape_payload_field(text):
    return text.replace('\\', '\\\\').replace('|', '\\|')

def parse_signed_record(line: str, secret: bytes):
    raw = line.strip('\r\n')
    if not raw or raw.isspace():
        raise ValueError('blank record')
    pieces = _split_escaped(raw)
    if len(pieces) != 5:
        raise ValueError('field count')
    payload_parts = _split_escaped(raw[:raw.rfind('|')])
    if len(payload_parts) != 4:
        raise ValueError('field count')
    timestamp, facility, material, weight = pieces[:4]
    if not facility or not material or (not weight.isdigit()) or (int(weight) <= 0):
        raise ValueError('invalid record')
    try:
        parsed = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        if not timestamp.endswith('Z') or parsed.tzinfo is None:
            raise ValueError
        epoch = int(parsed.timestamp())
        signature = bytes.fromhex(pieces[4])
    except ValueError:
        raise ValueError('invalid record')
    expected = hmac.new(secret, raw[:raw.rfind('|')].encode(), hashlib.sha256).digest()
    if not hmac.compare_digest(signature, expected):
        raise PermissionError('invalid signature')
    return {'timestamp': epoch, 'facility': facility, 'material': material, 'weight_grams': int(weight)}

def summarize_manifest(text: str, secret: bytes):
    groups = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        record = parse_signed_record(line, secret)
        key = (record['facility'], record['material'])
        if key not in groups:
            groups[key] = [0, 0, 0]
        groups[key][0] += record['weight_grams']
        groups[key][1] += 1
        groups[key][2] = max(groups[key][2], record['timestamp'])
    return [{'facility': facility, 'material': material, 'total_grams': values[0], 'record_count': values[1], 'latest_timestamp': values[2]} for (facility, material), values in sorted(groups.items())]

