    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid rate')
    if not rate.is_finite() or rate < 0:
        raise ValueError('invalid rate')
    records = []
    for path in file_paths:
        result = subprocess.run(['wc', '-c', path], check=True, capture_output=True, text=True)
        count = int(result.stdout.split()[0])
        charge = (Decimal(count) * rate).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        records.append({'path': path, 'bytes': count, 'charge': format(charge, '.2f'), '_value': charge})
    records.sort(key=lambda item: (-item['_value'], item['path']))
    start = (page - 1) * page_size
    selected = records[start:start + page_size]
    return [{'path': item['path'], 'bytes': item['bytes'], 'charge': item['charge']} for item in selected]

