def summarize_usage(body: bytes, signature: str, secret: bytes, page: int=1, page_size: int=10) -> dict:
    expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(signature, expected):
        raise PermissionError('invalid signature')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        value = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid report') from exc
    if not isinstance(value, dict) or not isinstance(value.get('events'), list):
        raise ValueError('invalid report')
    totals = {}
    for event in value['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        account = event.get('account')
        megabytes = event.get('megabytes')
        charge = event.get('charge_cents')
        if not isinstance(account, str) or not account or (not isinstance(megabytes, int)) or isinstance(megabytes, bool) or (megabytes < 0) or (not isinstance(charge, int)) or isinstance(charge, bool) or (charge < 0):
            raise ValueError('invalid event')
        if account not in totals:
            totals[account] = [0, 0]
        totals[account][0] += megabytes
        totals[account][1] += charge
