import os

def write_dispatch_report(base_dir: str, jobs: list[dict], relative_name: str, page: int=1, page_size: int=10) -> str:
    if not os.path.isdir(base_dir):
        raise NotADirectoryError(base_dir)
    if not isinstance(relative_name, str) or not relative_name or os.path.isabs(relative_name):
        raise ValueError('invalid file name')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    if not isinstance(jobs, list):
        raise ValueError('invalid jobs')
    normalized = []
    for job in jobs:
        if not isinstance(job, dict):
            raise ValueError('invalid job')
        required = ('id', 'technician', 'status', 'minutes', 'cost')
        if any((key not in job for key in required)):
            raise ValueError('invalid job')
        if any((not isinstance(job[key], str) or not job[key] for key in ('id', 'technician'))):
            raise ValueError('invalid job')
        if job['status'] not in ('scheduled', 'completed', 'cancelled'):
            raise ValueError('invalid job')
        if not isinstance(job['minutes'], int) or isinstance(job['minutes'], bool) or job['minutes'] < 0:
            raise ValueError('invalid job')
        if not isinstance(job['cost'], (int, float)) or isinstance(job['cost'], bool) or job['cost'] < 0:
            raise ValueError('invalid job')
        normalized.append({key: job[key] for key in required})
    normalized.sort(key=lambda item: (item['technician'], item['id']))
    groups = {}
    for job in normalized:
        group = groups.setdefault(job['technician'], {'name': job['technician'], 'jobs': 0, 'minutes': 0, 'cost': 0})
        group['jobs'] += 1
        group['minutes'] += job['minutes']
        group['cost'] += job['cost']
    technicians = []
    for name in sorted(groups):
        group = groups[name]
        group['cost'] = round(group['cost'], 2)
        technicians.append(group)
    start = (page - 1) * page_size
    output = {'page': page, 'page_size': page_size, 'total': len(normalized), 'jobs': normalized[start:start + page_size], 'technicians': technicians}
    base = os.path.realpath(os.path.abspath(base_dir))
    target = os.path.realpath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath((base, target)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('invalid file name')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        json.dump(output, handle, indent=2)
    return target

