import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin:
        raise ValueError('pin must be a non-empty string')
    salt = os.urandom(16)
    rounds = 120000
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
    return f'pbkdf2${rounds}${salt.hex()}${digest.hex()}'

def verify_pin(pin: str, stored_hash: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored_hash, str):
        return False
    try:
        method, rounds_text, salt_text, digest_text = stored_hash.split('$')
        if method != 'pbkdf2':
            return False
        rounds = int(rounds_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def authorize_declaration(pin: str, stored_hash: str, declaration: dict) -> dict:
    if not verify_pin(pin, stored_hash):
        raise PermissionError('invalid PIN')
    if not isinstance(declaration, dict):
        raise ValueError('invalid declaration')
    importer = declaration.get('importer')
    destination = declaration.get('destination')
    value = declaration.get('value')
    if not isinstance(importer, str) or not importer or (not isinstance(destination, str)) or (not destination):
        raise ValueError('invalid declaration')
    if isinstance(value, bool) or not isinstance(value, (int, float)) or value <= 0:
        raise ValueError('invalid declaration')
    value = round(value, 2)
    return {'status': 'accepted', 'importer': importer, 'destination': destination, 'value': value, 'risk': 'review' if value > 10000 else 'routine'}

