def build_excursion_report(requester: dict, bookings: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(requester, dict) or not isinstance(bookings, list):
        raise TypeError()
    if not isinstance(requester.get('id'), str) or not isinstance(requester.get('tenant_id'), str) or (not isinstance(requester.get('roles'), list)):
        raise TypeError()
    if not requester['id'] or not requester['tenant_id'] or any((not isinstance(x, str) for x in requester['roles'])):
        raise ValueError()
    if not isinstance(page, int) or not isinstance(page_size, int):
        raise TypeError()
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError()
    required = ('id', 'excursion', 'date', 'owner_id', 'tenant_id', 'guests', 'unit_price_cents', 'status')
    groups = {}
    for item in bookings:
        if not isinstance(item, dict):
            raise TypeError()
        if any((k not in item for k in required)):
            raise ValueError()
        for key in ('id', 'excursion', 'date', 'owner_id', 'tenant_id', 'status'):
            if not isinstance(item[key], str):
                raise TypeError()
            if not item[key]:
                raise ValueError()
        if not isinstance(item['guests'], int) or not isinstance(item['unit_price_cents'], int):
            raise TypeError()
        if item['guests'] < 1 or item['unit_price_cents'] < 0 or item['status'] not in ('confirmed', 'completed', 'cancelled'):
            raise ValueError()
        try:
            datetime.date.fromisoformat(item['date'])
        except ValueError:
            raise ValueError()
        allowed = item['tenant_id'] == requester['tenant_id'] and (item['owner_id'] == requester['id'] or bool(set(requester['roles']) & {'dispatcher', 'admin'}))
        if not allowed or item['status'] == 'cancelled':
            continue
        g = groups.setdefault(item['excursion'], [0, 0, 0])
        g[0] += 1
        g[1] += item['guests']
        g[2] += item['guests'] * item['unit_price_cents']
    result = [{'excursion': k, 'booking_count': v[0], 'total_guests': v[1], 'revenue_cents': v[2]} for k, v in groups.items()]
    result.sort(key=lambda x: (-x['revenue_cents'], x['excursion']))
    total = len(result)
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_groups': total, 'total_pages': (total + page_size - 1) // page_size if total else 0, 'groups': result[start:start + page_size]}

