import datetime
import math
import secrets

def generate_publication_code() -> str:
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((secrets.choice(alphabet) for _ in range(12)))

def _parse(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.datetime.fromisoformat(value[:-1]).replace(tzinfo=datetime.timezone.utc)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')

def aggregate_aqi(readings: list[dict[str, object]], window_minutes: int=60) -> list[dict[str, object]]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or window_minutes <= 0 or 1440 % window_minutes:
        raise ValueError('invalid window')
    limits = {'PM25': 35.4, 'O3': 0.07}
    groups = {}
    for row in readings:
        try:
            stamp = _parse(row['timestamp'])
            pollutant = row['pollutant']
            value = float(row['value'])
        except (KeyError, TypeError, ValueError, OverflowError):
            raise ValueError('invalid reading')
        if pollutant not in limits or not math.isfinite(value) or value < 0:
            raise ValueError('invalid reading')
        minute = (stamp.hour * 60 + stamp.minute) // window_minutes * window_minutes
        start = stamp.replace(hour=0, minute=0, second=0, microsecond=0) + datetime.timedelta(minutes=minute)
        groups.setdefault(start, {}).setdefault(pollutant, []).append(value)
    result = []
    for start in sorted(groups):
        scores = {}
        for pollutant in sorted(groups[start]):
            average = sum(groups[start][pollutant]) / len(groups[start][pollutant])
            scores[pollutant] = min(500, round(100 * average / limits[pollutant]))
        dominant = max(scores, key=lambda p: (scores[p], p == 'O3'))
        result.append({'window': start.strftime('%Y-%m-%dT%H:%M:00Z'), 'aqi': scores[dominant], 'dominant': dominant, 'pollutants': scores})
    return result

def publish_air_quality(station: str, readings: list[dict[str, object]], issued_at: str) -> dict[str, object]:
    station = station.strip() if isinstance(station, str) else ''
    if not station:
        raise ValueError('invalid station')
    issued = _parse(issued_at).replace(microsecond=0).strftime('%Y-%m-%dT%H:%M:%SZ')
    windows = aggregate_aqi(readings)
    return {'station': station, 'issued_at': issued, 'publication_code': generate_publication_code(), 'windows': windows, 'summary': {'aqi': max((x['aqi'] for x in windows), default=0), 'windows': len(windows)}}

