import sqlite3
from datetime import datetime
_STATUSES = ('planned', 'queued', 'deployed', 'failed', 'rolled_back')
_COLUMNS = ('id', 'version', 'environment', 'status', 'deployed_at', 'notes')
_SORTS = {'id': 'id', 'version': 'version', 'environment': 'environment', 'status': 'status', 'deployed_at': 'deployed_at'}

def create_schema(conn):
    conn.execute('CREATE TABLE IF NOT EXISTS releases (id INTEGER PRIMARY KEY, version TEXT NOT NULL, environment TEXT NOT NULL, status TEXT NOT NULL, deployed_at TEXT NOT NULL, notes TEXT NOT NULL)')
    conn.commit()

def _row(cursor):
    row = cursor.fetchone()
    return dict(zip(_COLUMNS, row)) if row is not None else None

def save_release(conn, release_id, version, environment, status, deployed_at, notes=''):
    if status not in _STATUSES:
        raise ValueError('invalid status')
    try:
        datetime.fromisoformat(deployed_at)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    conn.execute('INSERT OR REPLACE INTO releases (id, version, environment, status, deployed_at, notes) VALUES (?, ?, ?, ?, ?, ?)', (release_id, version, environment, status, deployed_at, notes))
    conn.commit()
    return _row(conn.execute('SELECT id, version, environment, status, deployed_at, notes FROM releases WHERE id = ?', (release_id,)))

def list_releases(conn, environment=None, query='', sort_by='deployed_at', descending=False, limit=50):
    if sort_by not in _SORTS or not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError('invalid listing options')
    clauses, args = ([], [])
    if environment is not None:
        clauses.append('environment = ?')
        args.append(environment)
    if query:
        clauses.append('(LOWER(version) LIKE LOWER(?) OR LOWER(notes) LIKE LOWER(?))')
        pattern = '%' + query + '%'
        args.extend((pattern, pattern))
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    sql = 'SELECT id, version, environment, status, deployed_at, notes FROM releases' + where + ' ORDER BY ' + _SORTS[sort_by] + ' ' + direction + ', id ASC LIMIT ?'
    args.append(limit)
    return [dict(zip(_COLUMNS, row)) for row in conn.execute(sql, args).fetchall()]

def release_metrics(conn, environment=None):
    rows = list_releases(conn, environment=environment, sort_by='environment', limit=100)
    counts = {status: 0 for status in _STATUSES}
    environments = {}
    for row in rows:
        counts[row['status']] += 1
        environments[row['environment']] = environments.get(row['environment'], 0) + 1
    deployed = [r['deployed_at'] for r in rows if r['status'] == 'deployed']
    return {'total': len(rows), 'by_status': counts, 'environments': dict(sorted(environments.items())), 'latest_deployed': max(deployed) if deployed else None}

