_STATUSES = {'scheduled', 'completed', 'cancelled'}

def _check(row):
    if set(row) != set(_FIELDS):
        raise ValueError('invalid record')
    unit = str(row['unit']).strip()
    system = str(row['system']).strip()
    date = str(row['date']).strip()
    status = str(row['status']).strip()
    try:
        minutes = int(row['minutes'])
        datetime.date.fromisoformat(date)
    except (TypeError, ValueError):
        raise ValueError('invalid record')
    if not unit or not system or minutes < 0 or (status not in _STATUSES):
        raise ValueError('invalid record')
    return {'unit': unit, 'system': system, 'date': date, 'minutes': minutes, 'status': status}

def parse_records(text):
    if not text or not text.strip():
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(text.splitlines()))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    while rows and (not any((x.strip() for x in rows[0]))):
        rows.pop(0)
    if not rows or rows[0] != _FIELDS:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not any((x.strip() for x in row)):
            continue
        if len(row) != len(_FIELDS):
            raise ValueError('invalid row')
        result.append(_check(dict(zip(_FIELDS, row))))
    return result

def summarize(records):
    groups = {}
    for record in records:
        item = _check(record)
        key = (item['unit'], item['system'])
        if key not in groups:
            groups[key] = {'unit': key[0], 'system': key[1], 'jobs': 0, 'completed_jobs': 0, 'total_minutes': 0, 'latest_date': item['date']}
        out = groups[key]
        out['jobs'] += 1
        out['completed_jobs'] += item['status'] == 'completed'
        out['total_minutes'] += item['minutes']
        out['latest_date'] = max(out['latest_date'], item['date'])
    return [groups[k] for k in sorted(groups)]

def export_report(records, destination):
    rows = summarize(records)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.maintenance-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.DictWriter(stream, fieldnames=['unit', 'system', 'jobs', 'completed_jobs', 'total_minutes', 'latest_date'])
            writer.writeheader()
            writer.writerows(rows)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

