    result = sync_inventory(requester(), inv, events)
    assert result == {
        "tenant_id": "t1",
        "owner_id": "u1",
        "items": {
            "A-10": {"quantity": 9, "revision": 5},
            "B-20": {"quantity": 6, "revision": 1},
            "C-30": {"quantity": 5, "revision": 1},
        },
        "applied_event_ids": ["e3", "e1", "e2"],
    }
    assert inv == original


