    inv = make_inventory()
    event = {"event_id": "same", "sku": "C-30", "delta": 2, "base_revision": 1, "timestamp": 1, "sequence": 1}
    result = sync_inventory(requester(), inv, [event, dict(event, base_revision=99, timestamp=2)])
    assert result["items"]["C-30"] == {"quantity": 7, "revision": 2}
    assert result["applied_event_ids"] == ["same"]


