from copy import deepcopy

def sync_inventory(requester: dict, inventory: dict, events: list[dict]) -> dict:
    if not isinstance(requester, dict) or not isinstance(inventory, dict):
        raise ValueError('invalid input')
    if requester.get('tenant_id') != inventory.get('tenant_id'):
        raise PermissionError('not permitted')
    roles = requester.get('roles', [])
    if requester.get('id') != inventory.get('owner_id') and 'inventory_admin' not in roles:
        raise PermissionError('not permitted')
    result = deepcopy(inventory)
    items = result.get('items')
    if not isinstance(items, dict):
        raise ValueError('invalid items')
    ordered = sorted(events, key=lambda e: (e.get('timestamp'), e.get('sequence'), e.get('event_id')))
    seen = set()
    applied = []
    for event in ordered:
        if not isinstance(event, dict) or not isinstance(event.get('event_id'), str):
            raise ValueError('invalid event')
        eid = event['event_id']
        if eid in seen:
            continue
        seen.add(eid)
        sku = event.get('sku')
        delta = event.get('delta')
        base = event.get('base_revision')
        if sku not in items or type(delta) is not int or type(base) is not int:
            raise ValueError('invalid event')
        item = items[sku]
        if item.get('revision') != base or item.get('quantity') + delta < 0:
            raise ValueError('conflict')
        item['quantity'] += delta
        item['revision'] += 1
        applied.append(eid)
    result['applied_event_ids'] = applied
    return result

def stock_report(inventory: dict, maximum_quantity: int) -> list[tuple[str, int]]:
    if type(maximum_quantity) is not int or maximum_quantity < 0:
        raise ValueError('invalid threshold')
    rows = [(sku, item['quantity']) for sku, item in inventory['items'].items() if item['quantity'] <= maximum_quantity]
    return sorted(rows, key=lambda row: (row[1], row[0]))

