from datetime import datetime
from copy import deepcopy
_KINDS = ('status', 'document', 'note', 'decision')

def _authorized(requester, case):
    return requester.get('tenant_id') == case.get('tenant_id') and (requester.get('id') == case.get('owner_id') or requester.get('role') in {'case_manager', 'supervisor'})

def _timestamp(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        raise ValueError('invalid timestamp')

def _check_event(event):
    if not isinstance(event, dict) or any((not isinstance(event.get(k), str) for k in ('event_id', 'at', 'kind', 'message'))):
        raise ValueError('invalid event')
    _timestamp(event['at'])
    if event['kind'] not in _KINDS:
        raise ValueError('invalid kind')

def record_case_event(requester: dict, case: dict, event: dict) -> dict:
    if not _authorized(requester, case):
        raise PermissionError('not permitted')
    _check_event(event)
    old = case.get('events', [])
    if any((isinstance(x, dict) and x.get('event_id') == event['event_id'] for x in old)):
        raise ValueError('duplicate event')
    if not isinstance(case.get('version'), int):
        raise ValueError('invalid version')
    result = deepcopy(case)
    result['events'] = deepcopy(old) + [deepcopy(event)]
    result['version'] += 1
    return result

def build_case_report(requester: dict, case: dict, events: list[dict]) -> dict:
    if not _authorized(requester, case):
        raise PermissionError('not permitted')
    counts = {k: 0 for k in _KINDS}
    days = {}
    checked = []
    for event in events:
        _check_event(event)
        checked.append(event)
        dt = _timestamp(event['at'])
        counts[event['kind']] += 1
        day = dt.strftime('%Y-%m-%d')
        if day not in days:
            days[day] = {'count': 0, 'kinds': {k: 0 for k in _KINDS}}
        days[day]['count'] += 1
        days[day]['kinds'][event['kind']] += 1
    activity = [{'date': d, 'count': days[d]['count'], 'kinds': days[d]['kinds']} for d in sorted(days)]
    latest = max(checked, key=lambda e: (_timestamp(e['at']), e['event_id'])) if checked else None
    required = sorted((d['name'] for d in case.get('documents', []) if d.get('required') and d.get('status') != 'verified'))
    return {'case_id': case.get('case_id'), 'event_count': len(checked), 'latest_event': latest, 'counts_by_kind': counts, 'daily_activity': activity, 'required_documents': required}

