import csv
import math
import os
import tempfile

def export_findings(findings: list[dict], destination: str, severity: str | None=None, page: int=1, page_size: int=50) -> dict:
    levels = {'low', 'medium', 'high', 'critical'}
    if severity is not None and severity not in levels:
        raise ValueError('invalid severity')
    if type(page) is not int or page < 1 or type(page_size) is not int or (page_size < 1):
        raise ValueError('invalid paging')
    checked = []
    for item in findings:
        if not isinstance(item, dict) or not all((key in item for key in ('id', 'title', 'severity', 'cvss'))):
            raise ValueError('invalid finding')
        if not isinstance(item['id'], str) or not item['id'] or (not isinstance(item['title'], str)):
            raise ValueError('invalid finding')
        if item['severity'] not in levels or isinstance(item['cvss'], bool) or (not isinstance(item['cvss'], (int, float))) or (not math.isfinite(item['cvss'])) or (not 0 <= item['cvss'] <= 10):
            raise ValueError('invalid finding')
        if severity is None or item['severity'] == severity:
            checked.append(item)
    checked.sort(key=lambda item: (-item['cvss'], item['id']))
    total = len(checked)
    start = (page - 1) * page_size
    selected = checked[start:start + page_size]
    directory = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(descriptor, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('id', 'title', 'severity', 'cvss'))
            for item in selected:
                writer.writerow((item['id'], item['title'], item['severity'], f"{item['cvss']:.1f}"))
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'total_count': total, 'total_pages': math.ceil(total / page_size) if total else 0, 'page': page, 'count': len(selected)}

