import os

def create_annotator_record(name: str, pin: str) -> dict:
    cleaned_name = name.strip()
    if not cleaned_name:
        raise ValueError('name must not be empty')
    if len(pin) != 4 or not pin.isdecimal() or (not pin.isascii()):
        raise ValueError('pin must contain four digits')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'name': cleaned_name, 'credential': salt.hex() + ':' + digest.hex()}

def verify_annotator_pin(record: dict, pin: str) -> bool:
    if len(pin) != 4 or not pin.isdecimal() or (not pin.isascii()):
        return False
    try:
        salt_text, digest_text = record['credential'].split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (KeyError, ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return actual == expected

