import hashlib
import hmac
import json
from datetime import datetime

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError:
        raise ValueError('invalid timestamp')

def parse_event_feed(data):
    if not isinstance(data, dict) or set(data) != {'events'} or (not isinstance(data['events'], list)) or (not data['events']):
        raise ValueError('invalid feed')
    seen = set()
    result = []
    allowed = {'join', 'visit', 'payment', 'freeze', 'unfreeze', 'cancel'}
    for pos, event in enumerate(data['events']):
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        required = {'id', 'member_id', 'type', 'occurred_at'}
        if not required <= set(event) or not isinstance(event['id'], str) or (not event['id']) or (event['id'] in seen):
            raise ValueError('invalid event')
        if not isinstance(event['member_id'], str) or not event['member_id'] or event['type'] not in allowed:
            raise ValueError('invalid event')
        _time(event['occurred_at'])
        typ = event['type']
        if typ == 'payment':
            if set(event) != required | {'amount_cents'} or not isinstance(event['amount_cents'], int) or isinstance(event['amount_cents'], bool) or (event['amount_cents'] < 0):
                raise ValueError('invalid payment')
        elif set(event) != required:
            raise ValueError('invalid fields')
        seen.add(event['id'])
        result.append((event['occurred_at'], pos, event))
    result.sort(key=lambda x: (_time(x[0]), x[1]))
    return [x[2] for x in result]

def apply_event(members, event):
    mid, typ = (event['member_id'], event['type'])
    if typ == 'join':
        if mid in members:
            raise ValueError('duplicate join')
        members[mid] = {'status': 'active', 'visits': 0, 'paid_cents': 0, 'last_visit': None}
        return
    if mid not in members or members[mid]['status'] == 'cancelled':
        raise ValueError('invalid member state')
    member = members[mid]
    if typ == 'visit':
        if member['status'] != 'active':
            raise ValueError('visit while inactive')
        member['visits'] += 1
        member['last_visit'] = event['occurred_at']
    elif typ == 'payment':
        member['paid_cents'] += event['amount_cents']
    elif typ == 'freeze':
        if member['status'] != 'active':
            raise ValueError('invalid freeze')
        member['status'] = 'frozen'
    elif typ == 'unfreeze':
        if member['status'] != 'frozen':
            raise ValueError('invalid unfreeze')
        member['status'] = 'active'
    elif typ == 'cancel':
        member['status'] = 'cancelled'

def verify_and_summarize(payload: bytes, headers: dict[str, str], key: bytes) -> dict:
    if not isinstance(payload, bytes) or not isinstance(key, bytes) or (not isinstance(headers, dict)):
        raise ValueError('invalid request')
    value = headers.get('X-Club-Signature')
    if not isinstance(value, str) or len(value) != 71 or (not value.startswith('sha256=')):
        raise ValueError('invalid signature')
    supplied = value[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid body')
    events = parse_event_feed(data)
    members = {}
    for event in events:
        apply_event(members, event)
    output = []
    for mid in sorted(members):
        output.append({'member_id': mid, **members[mid]})
    return {'total_members': len(output), 'members': output}

