import re
import secrets

def generate_invite_codes(requests: list[dict], page: int=1, page_size: int=10, prefix: str='dev') -> dict:
    if not isinstance(requests, list):
        raise TypeError('requests must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    if not isinstance(prefix, str) or not prefix or re.fullmatch('[A-Za-z0-9-]+', prefix) is None:
        raise ValueError('invalid prefix')
    chosen = {}
    for item in requests:
        if not isinstance(item, dict):
            raise TypeError('request must be a dictionary')
        if not isinstance(item.get('developer'), str) or not item['developer']:
            raise ValueError('invalid developer')
        if not isinstance(item.get('environment'), str) or not item['environment']:
            raise ValueError('invalid environment')
        days = item.get('expires_days')
        if isinstance(days, bool) or not isinstance(days, int) or days < 1:
            raise ValueError('invalid expiration')
        key = (item['developer'], item['environment'])
        if key not in chosen or days > chosen[key]['expires_days']:
            chosen[key] = {'developer': item['developer'], 'environment': item['environment'], 'expires_days': days}
    ordered = sorted(chosen.values(), key=lambda x: (x['environment'], x['developer']))
    counts = {}
    for item in ordered:
        counts[item['environment']] = counts.get(item['environment'], 0) + 1
    start = (page - 1) * page_size
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    invites = []
    for item in ordered[start:start + page_size]:
        result = dict(item)
        result['code'] = prefix + '-' + ''.join((secrets.choice(alphabet) for _ in range(10)))
        invites.append(result)
    return {'total': len(ordered), 'page': page, 'page_size': page_size, 'invites': invites, 'by_environment': counts}

