import os
import tempfile


def write_roster(contents):
    directory = tempfile.TemporaryDirectory()
    path = os.path.join(directory.name, "roster.txt")
    with open(path, "w", encoding="utf-8") as handle:
        handle.write(contents)
    return directory, path


def test_returns_sorted_unique_participants():
    directory, path = write_roster("p003\np001\np002\np001\n")
    try:
        assert load_event_participants(path) == ["p001", "p002", "p003"]
    finally:
        directory.cleanup()


def test_ignores_empty_lines():
    directory, path = write_roster("\np002\n\np001\n\n")
    try:
        assert load_event_participants(path) == ["p001", "p002"]
    finally:
        directory.cleanup()


def test_empty_file_returns_empty_list():
    directory, path = write_roster("")
    try:
        assert load_event_participants(path) == []
    finally:
        directory.cleanup()


