from datetime import date
import requests

def fetch_care_records(animal_id: str, start_date: str, end_date: str) -> list[dict]:
    response = requests.get('https://zoo.example/api/care', params={'animal_id': animal_id, 'start_date': start_date, 'end_date': end_date}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'API request failed: {response.status_code}')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('records'), list):
        raise ValueError('invalid response')
    return payload['records']

def summarize_care_records(records: list[dict]) -> dict[str, dict]:
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        animal = record.get('animal_id')
        stamp = record.get('date')
        care = record.get('care_type')
        weight = record.get('weight_kg')
        if not isinstance(animal, str) or not animal or (not isinstance(stamp, str)) or (not isinstance(care, str)) or (not care):
            raise ValueError('invalid record')
        if len(stamp) != 10 or stamp[4] != '-' or stamp[7] != '-':
            raise ValueError('invalid record')
        try:
            parsed = date.fromisoformat(stamp)
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(weight, (int, float)) or isinstance(weight, bool) or (not math.isfinite(weight)) or (weight < 0):
            raise ValueError('invalid record')
        bucket = groups.setdefault(animal, {'weights': [], 'counts': {}, 'latest': None})
        bucket['weights'].append(weight)
        bucket['counts'][care] = bucket['counts'].get(care, 0) + 1
        if bucket['latest'] is None or parsed >= bucket['latest'][0]:
            bucket['latest'] = (parsed, stamp, weight)
    result = {}
    for animal in sorted(groups):
        bucket = groups[animal]
        latest = bucket['latest']
        result[animal] = {'total_visits': len(bucket['weights']), 'care_counts': {key: bucket['counts'][key] for key in sorted(bucket['counts'])}, 'average_weight_kg': round(sum(bucket['weights']) / len(bucket['weights']), 2), 'latest': {'date': latest[1], 'weight_kg': latest[2]}}
    return result

def render_care_report(records: list[dict]) -> list[str]:
    summary = summarize_care_records(records)
    return [f"{animal}: {item['total_visits']} visits, latest {item['latest']['date']} {item['latest']['weight_kg']:.2f} kg, average {item['average_weight_kg']:.2f} kg" for animal, item in summary.items()]

