import secrets
from datetime import date
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def parse_manifest(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('manifest must be text')
    rows = list(csv.reader(io.StringIO(text)))
    while rows and (not any(rows[0])):
        rows.pop(0)
    if not rows or rows[0] != ['order', 'sku', 'qty', 'due', 'zone']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not row or not any(row):
            continue
        if len(row) != 5 or row == ['order', 'sku', 'qty', 'due', 'zone']:
            raise ValueError('invalid row')
        order, sku, qty_text, due, zone = row
        if not order or not sku or (not due) or (not zone) or (not qty_text):
            raise ValueError('empty field')
        if not qty_text.isdigit() or int(qty_text) <= 0:
            raise ValueError('invalid quantity')
        try:
            date.fromisoformat(due)
        except ValueError:
            raise ValueError('invalid date')
        result.append({'order': order, 'sku': sku, 'qty': int(qty_text), 'due': due, 'zone': zone})
    return result

def generate_dispatch_code(length: int=8) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 6 <= length <= 32):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def allocate_waves(text: str, capacity: int) -> list[dict]:
    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity <= 0:
        raise ValueError('invalid capacity')
    records = parse_manifest(text)
    orders = {}
    for record in records:
        item = orders.setdefault(record['order'], {'units': 0, 'due': record['due'], 'zones': set()})
        item['units'] += record['qty']
        item['due'] = min(item['due'], record['due'])
        item['zones'].add(record['zone'])
    ordered = sorted(orders.items(), key=lambda p: (p[1]['due'], min(p[1]['zones']), p[0]))
    if any((item['units'] > capacity for _, item in ordered)):
        raise ValueError('order exceeds capacity')
    waves = []
    current = None
    for order, item in ordered:
        if current is None or current['units'] + item['units'] > capacity:
            current = {'wave': len(waves) + 1, 'orders': [], 'units': 0, 'code': generate_dispatch_code()}
            waves.append(current)
        current['orders'].append(order)
        current['units'] += item['units']
    return waves

