import sqlite3
from datetime import date
_STATUSES = ('intake', 'available', 'adopted', 'foster', 'medical')
_SORTS = {'name': 'a.name', 'age': 'a.age', 'admitted_date': 'a.admitted_date', 'adoption_count': 'adoption_count', 'id': 'a.id'}

def create_schema(conn: sqlite3.Connection) -> None:
    conn.executescript('\n    create table if not exists animals (\n        id integer primary key, name text not null, species text not null,\n        age integer not null, admitted_date text not null, status text not null\n    );\n    create table if not exists adoptions (\n        id integer primary key, animal_id integer not null, adopter text not null,\n        adopted_at text not null\n    );\n    ')
    conn.commit()

def record_animal(conn: sqlite3.Connection, name: str, species: str, age: int, admitted_date: str, status: str='available') -> int:
    if not isinstance(name, str) or not name.strip() or (not isinstance(species, str)) or (not species.strip()):
        raise ValueError('name and species are required')
    if not isinstance(age, int) or isinstance(age, bool) or age < 0:
        raise ValueError('invalid age')
    try:
        date.fromisoformat(admitted_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if status not in _STATUSES:
        raise ValueError('invalid status')
    cur = conn.execute('insert into animals(name,species,age,admitted_date,status) values(?,?,?,?,?)', (name.strip(), species.strip(), age, admitted_date, status))
    conn.commit()
    return cur.lastrowid

def find_animals(conn: sqlite3.Connection, species: str | None=None, status: str | None=None, search: str='', sort_by: str='name', descending: bool=False) -> list[dict]:
    if status is not None and status not in _STATUSES:
        raise ValueError('invalid status')
    if sort_by not in _SORTS:
        raise ValueError('invalid sort')
    query = 'select a.id,a.name,a.species,a.age,a.admitted_date,a.status,count(ad.id) as adoption_count from animals a left join adoptions ad on ad.animal_id=a.id where 1=1'
    args = []
    if species is not None:
        query += ' and a.species = ?'
        args.append(species)
    if status is not None:
        query += ' and a.status = ?'
        args.append(status)
    if search:
        query += ' and instr(lower(a.name), lower(?)) > 0'
        args.append(search)
    direction = ' desc' if descending else ' asc'
    query += ' group by a.id order by ' + _SORTS[sort_by] + direction + ', a.name asc, a.id asc'
    rows = conn.execute(query, args).fetchall()
    keys = ('id', 'name', 'species', 'age', 'admitted_date', 'status', 'adoption_count')
    return [dict(zip(keys, row)) for row in rows]

def change_status(conn: sqlite3.Connection, animal_id: int, status: str) -> bool:
    if status not in _STATUSES:
        raise ValueError('invalid status')
    cur = conn.execute('update animals set status=? where id=?', (status, animal_id))
    conn.commit()
    return cur.rowcount == 1

