import base64
import hashlib
import hmac
import math
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise ValueError('invalid pin')
    if not pin.isascii() or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return 'pbkdf2$100000$' + base64.b64encode(salt).decode() + '$' + digest.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        raise TypeError('arguments must be strings')
    if not pin.isascii() or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        return False
    try:
        scheme, count, salt_text, digest_text = stored.split('$', 3)
        if scheme != 'pbkdf2' or int(count) != 100000:
            return False
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return len(expected) == len(actual) and hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_readings(readings: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(readings, list):
        raise TypeError('readings must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    for reading in readings:
        if not isinstance(reading, dict) or set(reading) != {'instrument', 'wavelength_nm', 'value'}:
            raise ValueError('invalid reading')
        name = reading['instrument']
        wavelength = reading['wavelength_nm']
        value = reading['value']
        if not isinstance(name, str) or not name:
            raise ValueError('invalid instrument')
        if isinstance(wavelength, bool) or not isinstance(wavelength, (int, float)) or (not math.isfinite(wavelength)):
            raise ValueError('invalid wavelength')
        if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)):
            raise ValueError('invalid value')
        groups.setdefault(name, []).append(value)
    items = []
    for name in sorted(groups):
        values = groups[name]
        items.append({'instrument': name, 'count': len(values), 'mean': round(sum(values) / len(values), 2), 'minimum': round(min(values), 2), 'maximum': round(max(values), 2)})
    start = (page - 1) * page_size
    return {'total': len(items), 'items': items[start:start + page_size]}

