from pathlib import Path

def save_report_attachment(base_dir: str, relative_name: str, content: bytes) -> str:
    if not isinstance(base_dir, str) or not isinstance(relative_name, str):
        raise TypeError('base_dir and relative_name must be strings')
    if not isinstance(content, bytes):
        raise TypeError('content must be bytes')
    if not relative_name:
        raise ValueError('relative_name must not be empty')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('attachment path is outside the report directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(content)
    return str(target)

