import ast
import operator

def _evaluate(text, values):
    tree = ast.parse(text, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool, str)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in values:
                return values[node.id]
            if node.id in ('min', 'max', 'round'):
                return node.id
            raise NameError(node.id)
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = visit(child)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, child in zip(node.ops, node.comparators):
                right = visit(child)
                if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            args = [visit(x) for x in node.args]
            return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
        raise SyntaxError('unsupported expression')
    return visit(tree)

def _selected(manifest, rule, score_formula):
    result = []
    for row in manifest:
        values = {k: row[k] for k in ('fare', 'miles', 'checked_bags', 'age')}
        if row['status'] != 'confirmed':
            continue
        if not isinstance(_evaluate(rule, values), bool):
            raise ValueError('rule must be boolean')
        if not _evaluate(rule, values):
            continue
        score = _evaluate(score_formula, values)
        if not isinstance(score, (int, float)) or isinstance(score, bool):
            raise ValueError('score must be numeric')
        result.append((row, score))
    return result

def rank_manifest(manifest: list[dict], rule: str, score_formula: str) -> list[dict]:
    rows = _selected(manifest, rule, score_formula)
    rows.sort(key=lambda pair: (-pair[1], pair[0]['seat'], pair[0]['id']))
    return [{'id': r['id'], 'name': r['name'], 'seat': r['seat'], 'cabin': r['cabin'], 'score': score} for r, score in rows]

def manifest_totals(manifest: list[dict], rule: str, score_formula: str) -> dict:
    rows = _selected(manifest, rule, score_formula)
    cabins = {'first': 0, 'business': 0, 'economy': 0}
    for row, _ in rows:
        cabins[row['cabin']] += 1
    return {'count': len(rows), 'total_fare': sum((r['fare'] for r, _ in rows)), 'total_miles': sum((r['miles'] for r, _ in rows)), 'by_cabin': cabins}

