import html
import math

def render_exhibitor_table(records: list[dict], page: int=1, page_size: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    required = ('exhibitor', 'hall', 'booth', 'crates', 'status')
    allowed = {'confirmed', 'pending', 'arrived', 'cancelled'}
    active = []
    for record in records:
        if not isinstance(record, dict) or any((key not in record for key in required)):
            raise ValueError('invalid record')
        if any((not isinstance(record[key], str) or not record[key] for key in ('exhibitor', 'hall', 'booth', 'status'))):
            raise ValueError('invalid text')
        if isinstance(record['crates'], bool) or not isinstance(record['crates'], int) or record['crates'] < 0:
            raise ValueError('invalid crates')
        if record['status'] not in allowed:
            raise ValueError('invalid status')
        if record['status'] != 'cancelled':
            active.append(record)
    active.sort(key=lambda r: (-r['crates'], r['exhibitor'].casefold(), r['hall'], r['booth']))
    total_pages = max(1, math.ceil(len(active) / page_size))
    start = (page - 1) * page_size
    rows = []
    for record in active[start:start + page_size]:
        values = [record['exhibitor'], record['hall'], record['booth'], str(record['crates']), record['status']]
        rows.append('<tr>' + ''.join(('<td>' + html.escape(value) + '</td>' for value in values)) + '</tr>')
    total = sum((record['crates'] for record in active))
    return '<div class="logistics-report"><div class="summary">Showing page {} of {} | {} crates</div><table><thead><tr><th>Exhibitor</th><th>Hall</th><th>Booth</th><th>Crates</th><th>Status</th></tr></thead><tbody>{}</tbody></table></div>'.format(page, total_pages, total, ''.join(rows))

