import csv
import io
import os
import zipfile
from datetime import date
from pathlib import Path

def extract_vaccination_records(archive_path: str, output_dir: str) -> list[dict[str, object]]:
    base = Path(output_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    summaries = {}
    try:
        archive = zipfile.ZipFile(archive_path)
    except (OSError, zipfile.BadZipFile) as exc:
        raise ValueError('invalid archive') from exc
    with archive:
        for info in archive.infolist():
            if info.is_dir() or not info.filename.lower().endswith('.csv'):
                continue
            target = (base / info.filename).resolve()
            try:
                target.relative_to(base)
            except ValueError as exc:
                raise ValueError('invalid member path') from exc
            target.parent.mkdir(parents=True, exist_ok=True)
            data = archive.read(info)
            target.write_bytes(data)
            try:
                rows = list(csv.reader(io.StringIO(data.decode('utf-8'))))
            except (UnicodeDecodeError, csv.Error) as exc:
                raise ValueError('invalid csv') from exc
            if not rows or rows[0] != ['student_id', 'vaccine', 'dose_date', 'status']:
                raise ValueError('invalid header')
            for row in rows[1:]:
                if len(row) != 4:
                    raise ValueError('invalid row')
                student, vaccine, dose, status = [x.strip() for x in row]
                if not student or not vaccine or (not dose) or (status not in ('administered', 'declined')):
                    raise ValueError('invalid row')
                try:
                    date.fromisoformat(dose)
                except ValueError as exc:
                    raise ValueError('invalid date') from exc
                item = summaries.setdefault(student, {'administered_count': 0, 'declined_count': 0, 'latest': None, 'vaccines': set()})
                item['vaccines'].add(vaccine)
                item['administered_count' if status == 'administered' else 'declined_count'] += 1
                if status == 'administered' and (item['latest'] is None or dose > item['latest']):
                    item['latest'] = dose
    return [{'student_id': student, 'administered_count': summaries[student]['administered_count'], 'declined_count': summaries[student]['declined_count'], 'latest_administered_date': summaries[student]['latest'], 'vaccines': sorted(summaries[student]['vaccines'])} for student in sorted(summaries)]

