from datetime import date

def parse_case_feed(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('invalid line')
        fields.append(''.join(current))
        if len(fields) != 4 or not fields[0] or (not fields[2]):
            raise ValueError('invalid line')
        try:
            date.fromisoformat(fields[1])
            minutes = int(fields[3])
        except (ValueError, TypeError):
            raise ValueError('invalid line')
        if minutes < 0:
            raise ValueError('invalid line')
        result.append({'case_id': fields[0], 'date': fields[1], 'kind': fields[2], 'minutes': minutes})
    return result

def generate_caseload_report(requester: dict, cases: list[dict], start_date: str, end_date: str) -> dict:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (ValueError, TypeError):
        raise ValueError('invalid date range')
    if start > end:
        raise ValueError('invalid date range')
    allowed = []
    for case in cases:
        if case['tenant'] != requester['tenant']:
            continue
        if case['owner_id'] == requester['id'] or 'supervisor' in requester.get('roles', []):
            allowed.append(case)
    entries = []
    overall = {}
    for case in allowed:
        kinds = {}
        for event in case['events']:
            if event['case_id'] != case['id']:
                raise ValueError('mismatched event')
            try:
                event_date = date.fromisoformat(event['date'])
                minutes = int(event['minutes'])
            except (ValueError, TypeError, KeyError):
                raise ValueError('invalid event')
            if minutes < 0 or not event['kind'] or (not event['case_id']):
                raise ValueError('invalid event')
            if start <= event_date <= end:
                kinds[event['kind']] = kinds.get(event['kind'], 0) + minutes
                overall[event['kind']] = overall.get(event['kind'], 0) + minutes
        if kinds:
            total = sum(kinds.values())
            entries.append({'id': case['id'], 'owner_id': case['owner_id'], 'priority': case['priority'], 'status': case['status'], 'minutes': total, 'by_kind': dict(sorted(kinds.items()))})
    entries.sort(key=lambda x: (-x['priority'], -x['minutes'], x['id']))
    return {'tenant': requester['tenant'], 'start_date': start_date, 'end_date': end_date, 'total_minutes': sum(overall.values()), 'by_kind': dict(sorted(overall.items())), 'cases': entries}

