import hashlib
import hmac
import json

def verify_intake_webhook(body: bytes, signature: str, signing_key: str) -> dict:
    if not isinstance(body, bytes) or not isinstance(signature, str) or (not isinstance(signing_key, str)):
        raise ValueError('invalid callback')
    if len(signature) != 71 or not signature.startswith('sha256='):
        raise ValueError('invalid callback')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid callback')
    expected = hmac.new(signing_key.encode('utf-8'), body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid callback')
    try:
        payload = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid callback')
    if not isinstance(payload, dict):
        raise ValueError('invalid callback')
    if not isinstance(payload.get('case_id'), str) or not payload['case_id']:
        raise ValueError('invalid callback')
    if isinstance(payload.get('household_size'), bool) or not isinstance(payload.get('household_size'), int) or payload['household_size'] < 1:
        raise ValueError('invalid callback')
    if not isinstance(payload.get('needs'), list) or not all((isinstance(item, str) for item in payload['needs'])):
        raise ValueError('invalid callback')
    return payload

