import csv
import datetime
import os
import re
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_billing_csv(records: list[dict], destination: str, month: str) -> int:
    if not isinstance(month, str) or not re.fullmatch('\\d{4}-\\d{2}', month):
        raise ValueError('invalid month')
    try:
        year, month_number = map(int, month.split('-'))
        datetime.date(year, month_number, 1)
    except (ValueError, TypeError):
        raise ValueError('invalid month')
    totals = {}
    for record in records:
        try:
            patient_id = record['patient_id']
            service_date = record['service_date']
            record['code']
            amount = Decimal(str(record['amount']))
            paid = Decimal(str(record['insurance_paid']))
            parsed_date = datetime.date.fromisoformat(service_date)
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid record')
        if not isinstance(patient_id, str) or not patient_id or (not isinstance(record['code'], str)) or (not record['code']):
            raise ValueError('invalid record')
        if amount < 0 or paid < 0 or paid > amount:
            raise ValueError('invalid record')
        if parsed_date.strftime('%Y-%m') != month:
            continue
        if patient_id not in totals:
            totals[patient_id] = [Decimal('0'), Decimal('0')]
        totals[patient_id][0] += amount
        totals[patient_id][1] += paid
    quantizer = Decimal('0.01')
    rows = []
    for patient_id, (amount, paid) in totals.items():
        amount = amount.quantize(quantizer, rounding=ROUND_HALF_UP)
        paid = paid.quantize(quantizer, rounding=ROUND_HALF_UP)
        balance = (amount - paid).quantize(quantizer, rounding=ROUND_HALF_UP)
        rows.append((patient_id, amount, paid, balance))
    rows.sort(key=lambda row: (-row[3], row[0]))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.billing-', suffix='.tmp', dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['patient_id', 'total_amount', 'insurance_paid', 'balance'])
            for patient_id, amount, paid, balance in rows:
                writer.writerow([patient_id, f'{amount:.2f}', f'{paid:.2f}', f'{balance:.2f}'])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

