import hashlib
import hmac
import os

def _encode(pin):
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return 'pbkdf2$' + salt.hex() + '$' + value.hex()

def create_pledge(backer_id: str, pin: str, amount: int, day: int, memo: str='') -> dict:
    if not isinstance(backer_id, str) or not backer_id or (not isinstance(pin, str)) or (not pin):
        raise ValueError('invalid identity')
    if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
        raise ValueError('invalid amount')
    if not isinstance(day, int) or isinstance(day, bool) or day < 0:
        raise ValueError('invalid day')
    if not isinstance(memo, str) or len(memo) > 80:
        raise ValueError('invalid memo')
    return {'backer_id': backer_id, 'amount': amount, 'day': day, 'memo': memo, 'pin_hash': _encode(pin)}

def verify_pledge(pledge: dict, pin: str) -> bool:
    if not isinstance(pledge, dict) or not isinstance(pin, str):
        return False
    try:
        kind, salt_text, value_text = pledge['pin_hash'].split('$')
        if kind != 'pbkdf2':
            return False
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

def campaign_summary(entries: list[tuple[dict, str]], goal: int, window_days: int=3) -> dict:
