def build_rights_report(requester: dict, deals: list[dict], competition: str, season: int, page: int=1, page_size: int=10) -> dict:
    if not isinstance(requester, dict) or not isinstance(deals, list):
        raise TypeError()
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page < 1) or (page_size < 1):
        raise ValueError()
    if not isinstance(requester.get('role'), str) or not isinstance(requester.get('tenant_id'), str):
        raise TypeError()
    fields = ['deal_id', 'competition', 'season', 'broadcaster', 'tenant_id', 'owner_id', 'status', 'gross_value_cents', 'fee_bps']
    if requester['role'] != 'rights_admin' and any((d.get('tenant_id') != requester['tenant_id'] for d in deals if isinstance(d, dict))):
        raise PermissionError()
    groups = {}
    total = 0
    count = 0
    for deal in deals:
        if not isinstance(deal, dict):
            raise TypeError()
        if any((key not in deal for key in fields)):
            raise ValueError()
        if not isinstance(deal['competition'], str) or not isinstance(deal['season'], int) or (not isinstance(deal['broadcaster'], str)) or (not isinstance(deal['status'], str)):
            raise TypeError()
        if not isinstance(deal['gross_value_cents'], int) or not isinstance(deal['fee_bps'], int):
            raise TypeError()
        if deal['gross_value_cents'] < 0 or not 0 <= deal['fee_bps'] <= 10000:
            raise ValueError()
        if deal['competition'] != competition or deal['season'] != season or deal['status'] != 'confirmed':
            continue
        net = deal['gross_value_cents'] * (10000 - deal['fee_bps']) // 10000
        item = groups.setdefault(deal['broadcaster'], [0, 0])
        item[0] += 1
        item[1] += net
        count += 1
        total += net
    ordered = sorted(groups.items(), key=lambda x: (-x[1][1], x[0]))
    start = (page - 1) * page_size
    result = [{'broadcaster': n, 'deal_count': v[0], 'net_value_cents': v[1]} for n, v in ordered[start:start + page_size]]
    return {'competition': competition, 'season': season, 'page': page, 'page_size': page_size, 'total_deals': count, 'total_net_value_cents': total, 'broadcasters': result}

