def parse_arrangement(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'arrangement':
        raise ValueError('invalid root element')
    deceased = root.get('deceased')
    date = root.get('date')
    if deceased is None or date is None:
        raise ValueError('missing arrangement attribute')
    services = []
    for element in root:
        if element.tag != 'service' or element:
            raise ValueError('invalid service element')
        service_type = element.get('type')
        quantity_text = element.get('quantity')
        if service_type is None or quantity_text is None:
            raise ValueError('missing service attribute')
        try:
            quantity = int(quantity_text)
        except ValueError as exc:
            raise ValueError('invalid quantity') from exc
        if quantity <= 0:
            raise ValueError('invalid quantity')
        services.append({'type': service_type, 'quantity': quantity})
    services.sort(key=lambda item: item['type'])
    return {'deceased': deceased, 'date': date, 'services': services}

