import json
_KEYS = {'subscriber', 'units', 'at', 'seq'}

def _check_event(event):
    if not isinstance(event, dict) or set(event) != _KEYS:
        raise ValueError('invalid event')
    if not isinstance(event['subscriber'], str) or not event['subscriber']:
        raise ValueError('invalid subscriber')
    for key in ('units', 'at', 'seq'):
        value = event[key]
        if isinstance(value, bool) or not isinstance(value, int) or (key != 'at' and value < 0):
            raise ValueError('invalid integer')

def pack_usage_events(events: list[dict]) -> bytes:
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    for event in events:
        if not isinstance(event, dict):
            raise TypeError('event must be a dictionary')
        _check_event(event)
    return json.dumps(events, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def unpack_usage_events(payload: bytes) -> list[dict]:
    try:
        value = json.loads(payload.decode('utf-8'))
        if not isinstance(value, list):
            raise ValueError('invalid payload')
        for event in value:
            _check_event(event)
        return value
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc

def apply_usage_events(state: dict[str, dict[str, int | str]], payload: bytes, as_of: int) -> dict[str, dict[str, int | str]]:
    if isinstance(as_of, bool) or not isinstance(as_of, int):
        raise ValueError('invalid time')
    events = unpack_usage_events(payload)
    result = {subscriber: dict(values) for subscriber, values in state.items()}
    chosen = []
    for position, event in enumerate(events):
        if as_of - 86400 <= event['at'] <= as_of and event['subscriber'] in state:
            chosen.append((event['at'], event['seq'], position, event))
    chosen.sort(key=lambda item: item[:3])
    seen = set()
    for _, _, _, event in chosen:
        key = (event['subscriber'], event['seq'])
        if key in seen:
            continue
        seen.add(key)
        result[event['subscriber']]['used'] += event['units']
    for values in result.values():
        values['status'] = 'suspended' if values['used'] >= values['cap'] else 'active'
    return result

