import sqlite3
from datetime import datetime, timedelta

def _hours(start, end):
    a = datetime.strptime(start, '%H:%M')
    b = datetime.strptime(end, '%H:%M')
    if b < a:
        b += timedelta(days=1)
    return round((b - a).total_seconds() / 3600, 2)

def fetch_shifts(conn: sqlite3.Connection, department: str | None=None, start_date: str | None=None, end_date: str | None=None, sort_by: str='date') -> list[dict]:
    if sort_by not in {'date', 'employee', 'hours'}:
        raise ValueError('invalid sort')
    query = 'SELECT s.id, s.employee_id, e.name, e.department, s.work_date, s.start_time, s.end_time, s.status FROM shifts s JOIN employees e ON e.id=s.employee_id WHERE s.status <> ?'
    args = ['cancelled']
    if department is not None:
        query += ' AND e.department = ?'
        args.append(department)
    if start_date is not None:
        query += ' AND s.work_date >= ?'
        args.append(start_date)
    if end_date is not None:
        query += ' AND s.work_date <= ?'
        args.append(end_date)
    if sort_by == 'date':
        query += ' ORDER BY s.work_date, s.start_time, s.id'
    elif sort_by == 'employee':
        query += ' ORDER BY e.name, s.work_date, s.start_time, s.id'
    rows = []
    for row in conn.execute(query, args):
        h = _hours(row[5], row[6])
        rows.append({'id': row[0], 'employee_id': row[1], 'employee': row[2], 'department': row[3], 'work_date': row[4], 'start_time': row[5], 'end_time': row[6], 'status': row[7], 'hours': h})
    if sort_by == 'hours':
        rows.sort(key=lambda x: (-x['hours'], x['work_date'], x['start_time'], x['id']))
    return rows

def summarize_hours(conn: sqlite3.Connection, start_date: str | None=None, end_date: str | None=None) -> dict[str, float]:
    rows = fetch_shifts(conn, start_date=start_date, end_date=end_date)
    totals = {}
    for row in rows:
        totals[row['employee']] = round(totals.get(row['employee'], 0) + row['hours'], 2)
    return {name: totals[name] for name in sorted(totals)}

def update_shift_status(conn: sqlite3.Connection, shift_id: int, status: str) -> bool:
    if status not in {'scheduled', 'completed', 'cancelled'}:
        raise ValueError('invalid status')
    cur = conn.execute('UPDATE shifts SET status = ? WHERE id = ?', (status, shift_id))
    conn.commit()
    return cur.rowcount > 0

