import xml.etree.ElementTree as ET

def parse_signature(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'signature':
        raise ValueError('invalid root')
    fields = {}
    references = []
    for child in root:
        if child.tag in {'signer', 'algorithm', 'value'}:
            fields[child.tag] = (child.text or '').strip()
        elif child.tag == 'reference':
            references.append({'uri': child.attrib.get('uri', '')})
    if any((name not in fields for name in ('signer', 'algorithm', 'value'))):
        raise ValueError('missing signature field')
    return {'signer': fields['signer'], 'algorithm': fields['algorithm'], 'value': fields['value'], 'references': references}

