import xml.sax.handler

class _SignatureHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.depth = 0
        self.root = None
        self.current = None
        self.buffer = []
        self.fields = {}
        self.references = []

    def startElement(self, name, attrs):
        if self.depth == 0:
            self.root = name
        elif self.depth == 1 and name in {'signer', 'algorithm', 'value'}:
            self.current = name
            self.buffer = []
        elif self.depth == 1 and name == 'reference':
            self.references.append({'uri': attrs.get('uri', '')})
        self.depth += 1

    def characters(self, content):
        if self.current is not None:
            self.buffer.append(content)

    def endElement(self, name):
        if self.depth == 2 and self.current == name:
            self.fields[name] = ''.join(self.buffer).strip()
            self.current = None
            self.buffer = []
        self.depth -= 1

def parse_signature(xml_text: str) -> dict:
    handler = _SignatureHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        xml.sax.parseString(xml_text, handler)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
