        raise ValueError('invalid XML')
    if any((name not in handler.fields for name in ('signer', 'algorithm', 'value'))):
        raise ValueError('missing signature field')
    return {'signer': handler.fields['signer'], 'algorithm': handler.fields['algorithm'], 'value': handler.fields['value'], 'references': handler.references}

