import subprocess

def summarize_elevator_log(path: str, window_start: int, window_end: int, top_n: int) -> list[tuple[int, int, int]]:
    if window_start > window_end or top_n < 0:
        raise ValueError('invalid range')
    completed = subprocess.run(['sort', '-t,', '-k1,1n', path], capture_output=True, text=True, check=True)
    totals: dict[int, list[int]] = {}
    for raw in completed.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 5:
            raise ValueError('malformed record')
        timestamp_text, elevator, floor_text, event, duration_text = fields
        if not elevator:
            raise ValueError('empty elevator')
        try:
            timestamp = int(timestamp_text)
            floor = int(floor_text)
            duration = int(duration_text)
        except ValueError as exc:
            raise ValueError('invalid integer') from exc
        if floor < 0 or duration < 0 or event not in {'arrival', 'departure'}:
            raise ValueError('invalid record')
        if window_start <= timestamp <= window_end:
            item = totals.setdefault(floor, [0, 0])
            item[0] += 1
            item[1] += duration
    ordered = sorted(((floor, values[0], values[1]) for floor, values in totals.items()), key=lambda item: (-item[1], -item[2], item[0]))
    return ordered[:top_n]

def render_summary(summary: list[tuple[int, int, int]]) -> str:
    return '\n'.join((f'floor={floor} events={events} duration={duration}' for floor, events, duration in summary))

