from numbers import Real

def summarize_seed_inventory(requester: dict, lots: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(requester, dict) or not isinstance(lots, list):
        raise TypeError()
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError()
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError()
    if not isinstance(requester.get('id'), str) or not isinstance(requester.get('tenant_id'), str) or (not isinstance(requester.get('roles'), list)):
        raise ValueError()
    required = ('lot_id', 'tenant_id', 'owner_id', 'crop', 'quantity', 'unit_cost')
    seen = set()
    selected = []
    for lot in lots:
        if not isinstance(lot, dict) or any((k not in lot for k in required)):
            raise ValueError()
        if any((not isinstance(lot[k], str) for k in required[:4])):
            raise ValueError()
        if not isinstance(lot['quantity'], int) or isinstance(lot['quantity'], bool) or lot['quantity'] < 0:
            raise ValueError()
        if not isinstance(lot['unit_cost'], Real) or isinstance(lot['unit_cost'], bool) or lot['unit_cost'] < 0:
            raise ValueError()
        if lot['lot_id'] in seen:
            raise ValueError()
        seen.add(lot['lot_id'])
        if lot['tenant_id'] == requester['tenant_id'] and (lot['owner_id'] == requester['id'] or 'inventory_manager' in requester['roles']):
            selected.append(lot)
    selected.sort(key=lambda x: (x['crop'], x['lot_id']))
    groups = {}
    total_quantity = 0
    total_value = 0.0
    for lot in selected:
        groups.setdefault(lot['crop'], [0, 0])
        groups[lot['crop']][0] += 1
        groups[lot['crop']][1] += lot['quantity']
        total_quantity += lot['quantity']
        total_value += lot['quantity'] * lot['unit_cost']
    start = (page - 1) * page_size
    items = [{'lot_id': x['lot_id'], 'crop': x['crop'], 'quantity': x['quantity'], 'unit_cost': x['unit_cost'], 'value': round(x['quantity'] * x['unit_cost'], 2)} for x in selected[start:start + page_size]]
    return {'page': page, 'page_size': page_size, 'total_lots': len(selected), 'total_quantity': total_quantity, 'total_value': round(total_value, 2), 'by_crop': [{'crop': k, 'lots': v[0], 'quantity': v[1]} for k, v in sorted(groups.items())], 'items': items}

