import math
import re
from collections import defaultdict
from lxml import etree

def _rows(xml):
    try:
        root = etree.fromstring(xml.encode(), parser=etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'screening':
        raise ValueError('invalid root')
    result = []
    for plate in root.findall('plate'):
        pid, batch = (plate.get('id'), plate.get('batch'))
        if not pid or not batch:
            raise ValueError('invalid plate')
        for well in plate.findall('well'):
            pos = well.get('position', '')
            match = re.fullmatch('([A-Za-z]+)([1-9][0-9]*)', pos)
            if not match:
                raise ValueError('invalid position')
            comp = well.find('compound')
            if comp is None or not comp.get('id'):
                raise ValueError('invalid compound')
            try:
                concentration = float(comp.get('concentration'))
            except (TypeError, ValueError) as exc:
                raise ValueError('invalid concentration') from exc
            if not math.isfinite(concentration):
                raise ValueError('invalid concentration')
            signals = well.findall('signal')
            if not signals:
                raise ValueError('missing signal')
            seen = set()
            for signal in signals:
                try:
                    replicate = int(signal.get('replicate'))
                    value = float((signal.text or '').strip())
                except (TypeError, ValueError) as exc:
                    raise ValueError('invalid signal') from exc
                if replicate <= 0 or replicate in seen or (not math.isfinite(value)):
                    raise ValueError('invalid signal')
                seen.add(replicate)
                result.append({'plate': pid, 'batch': batch, 'well': pos, 'compound': comp.get('id'), 'concentration': concentration, 'replicate': replicate, 'signal': value})
    if not result:
        raise ValueError('empty screening')

    def key(row):
        m = re.fullmatch('([A-Za-z]+)([1-9][0-9]*)', row['well'])
        return (row['plate'], m.group(1).upper(), int(m.group(2)), row['replicate'])
    return sorted(result, key=key)

def parse_screening(xml: str) -> list[dict]:
    return _rows(xml)

def summarize_screening(xml: str) -> list[dict]:
    groups = defaultdict(list)
    for row in _rows(xml):
        groups[row['compound']].append(row)
    output = []
    for compound, rows in groups.items():
        values = [r['signal'] for r in rows]
        mean = sum(values) / len(values)
        variance = sum(((x - mean) ** 2 for x in values)) / (len(values) - 1) if len(values) > 1 else 0.0
        by_concentration = defaultdict(list)
        for row in rows:
            by_concentration[row['concentration']].append(row['signal'])
        best = min(by_concentration, key=lambda c: (-sum(by_concentration[c]) / len(by_concentration[c]), c))
        output.append({'compound': compound, 'count': len(values), 'mean_signal': round(mean, 6), 'sample_stddev': round(math.sqrt(variance), 6), 'best_concentration': best, 'concentrations': sorted(by_concentration)})
    return sorted(output, key=lambda x: (-x['mean_signal'], x['compound']))

def select_hits(xml: str, threshold: float, limit: int | None=None) -> list[str]:
    if not math.isfinite(threshold) or (limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0)):
        raise ValueError('invalid argument')
    values = [x['compound'] for x in summarize_screening(xml) if x['mean_signal'] >= threshold]
    return values if limit is None else values[:limit]

