import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin:
        raise ValueError('pin must be non-empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, encoded: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(encoded, str)):
        return False
    try:
        salt_text, digest_text = encoded.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def recent_contacts(pin: str, encoded: str, contacts: list[dict[str, str]], since: str) -> list[str]:
    if not verify_pin(pin, encoded):
        return []
    return [record['id'] for record in contacts if record['date'] >= since]

