def render_report(entries: list[dict[str, str]], title: str, locale: str) -> str:
    summary = summarize_catalog(entries)
    percent = summary['completion']
    percent_text = str(int(percent)) if float(percent).is_integer() else str(percent)
    rows = []
    rank = {'approved': 0, 'review': 1, 'draft': 2}
    for entry in sorted(entries, key=lambda item: (rank[item['status']], item['key'])):
        rows.append(f'''<tr><td>{entry['key']}</td><td>{entry['source']}</td><td>{entry['target']}</td><td class="{entry['status']}">{entry['status']}</td></tr>''')
    return f"""<section class="translation-report"><h1>{title} <span class="locale">({locale})</span></h1><p class="summary">{summary['total']} entries · {percent_text}% complete</p><table><thead><tr><th>Key</th><th>Source</th><th>Translation</th><th>Status</th></tr></thead><tbody>{''.join(rows)}</tbody></table></section>"""

