import os
import subprocess

def aggregate_equipment(log_path: str, equipment: str, metric: str, limit: int) -> list[tuple[str, int, float]]:
    if not equipment or not metric or limit < 0:
        raise ValueError('invalid arguments')
    if not os.path.isfile(log_path):
        raise FileNotFoundError(log_path)
    if limit == 0:
        return []
    result = subprocess.run(['grep', '-F', '--', metric, log_path], capture_output=True, text=True)
    if result.returncode not in (0, 1):
        raise FileNotFoundError(log_path)
    groups = {}
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split(',')
        if len(fields) != 4:
            raise ValueError('malformed record')
        timestamp, row_equipment, row_metric, raw_value = fields
        if row_equipment != equipment or row_metric != metric:
            continue
        try:
            value = float(raw_value)
        except ValueError as exc:
            raise ValueError('invalid value') from exc
        if not math.isfinite(value):
            raise ValueError('invalid value')
        date = timestamp[:10]
        if len(date) != 10:
            raise ValueError('invalid timestamp')
        count, total = groups.get(date, (0, 0.0))
        groups[date] = (count + 1, total + value)
    dates = sorted(groups, reverse=True)[:limit]
    return [(date, groups[date][0], round(groups[date][1] / groups[date][0], 2)) for date in dates]

