import xml.etree.ElementTree as ET

def _root(text):
    if not isinstance(text, str):
        raise ValueError('xml_text must be a string')
    try:
        return ET.fromstring(text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def parse_pairing_feed(xml_text: str) -> list[dict]:
    root = _root(xml_text)
    if root.tag != 'pairings':
        raise ValueError('wrong root')
    result = []
    for item in list(root):
        if item.tag != 'pairing':
            raise ValueError('unexpected element')
        for key in ('device', 'user', 'timestamp'):
            if not item.get(key):
                raise ValueError('missing attribute')
        try:
            timestamp = int(item.get('timestamp'))
        except Exception as exc:
            raise ValueError('bad timestamp') from exc
        if timestamp < 0:
            raise ValueError('bad timestamp')
        signal_nodes = [x for x in list(item) if x.tag == 'signal']
        if len(signal_nodes) != 1:
            raise ValueError('signal required')
        try:
            signal = int((signal_nodes[0].text or '').strip())
        except Exception as exc:
            raise ValueError('bad signal') from exc
        if not -100 <= signal <= 0:
            raise ValueError('bad signal')
        caps = {}
        for child in list(item):
            if child.tag not in ('signal', 'capabilities'):
                raise ValueError('unexpected child')
            if child.tag == 'capabilities':
                for cap in list(child):
                    if cap.tag != 'capability' or not cap.get('name') or (not cap.get('value')):
                        raise ValueError('bad capability')
                    caps[cap.get('name')] = cap.get('value')
        result.append({'device_id': item.get('device'), 'user': item.get('user'), 'timestamp': timestamp, 'signal': signal, 'capabilities': caps})
    return result

def choose_device(feeds: list[str], user: str, now: int) -> str | None:
    if not isinstance(feeds, list) or not isinstance(user, str) or (not isinstance(now, int)) or isinstance(now, bool) or (now < 0):
        raise ValueError('bad arguments')
    candidates = []
    for feed in feeds:
        if not isinstance(feed, str):
            raise ValueError('bad feed')
        for record in parse_pairing_feed(feed):
            if record['user'] == user and now - 300 <= record['timestamp'] <= now:
                candidates.append(record)
    if not candidates:
        return None
    best = max(candidates, key=lambda x: (x['signal'], x['timestamp'], -ord(x['device_id'][0]) if x['device_id'] else 0))
    top = [x for x in candidates if x['signal'] == best['signal'] and x['timestamp'] == best['timestamp']]
    return min((x['device_id'] for x in top))

