    sql = 'select id,case_number,courtroom,judge,start_time,duration,title,status from hearings where ' + ' and '.join(clauses) + ' order by ' + _SORTS[sort_by] + ', id'
    return [_row(r) for r in conn.execute(sql, args)]

def reschedule_hearing(conn: sqlite3.Connection, hearing_id: int, new_start: str) -> dict:
    new = _stamp(new_start)
    with conn:
        old = conn.execute('select * from hearings where id = ?', (hearing_id,)).fetchone()
        if old is None:
            raise KeyError(hearing_id)
        end = new + timedelta(minutes=old[5])
        conflict = conn.execute("select 1 from hearings where status='scheduled' and courtroom=? and id<>? and start_time < ? and datetime(start_time, '+' || duration || ' minutes') > ?", (old[2], hearing_id, end.strftime('%Y-%m-%d %H:%M'), new_start)).fetchone()
        if conflict:
            raise ValueError('hearing conflict')
        conn.execute('update hearings set start_time=? where id=?', (new_start, hearing_id))
    return _row(conn.execute('select * from hearings where id=?', (hearing_id,)).fetchone())

def day_load(conn: sqlite3.Connection, day: str) -> list[dict]:
    try:
        x = datetime.strptime(day, '%Y-%m-%d')
    except (TypeError, ValueError):
        raise ValueError('invalid day')
    if x.strftime('%Y-%m-%d') != day:
        raise ValueError('invalid day')
    rows = conn.execute("select courtroom,start_time,duration from hearings where status='scheduled' and start_time like ?", (day + '%',)).fetchall()
    out = {}
    for room, start, duration in rows:
        end = datetime.strptime(start, '%Y-%m-%d %H:%M') + timedelta(minutes=duration)
        a = out.setdefault(room, [0, 0, end])
        a[0] += 1
        a[1] += duration
        if end > a[2]:
            a[2] = end
    return [{'courtroom': r, 'hearing_count': v[0], 'total_minutes': v[1], 'latest_end': v[2].strftime('%Y-%m-%d %H:%M')} for r, v in sorted(out.items())]

