import hmac
import json

def verify_and_summarize(body: str, signature: str, secret: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(body, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
        raise ValueError('invalid argument')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    try:
        records = json.loads(body)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError('invalid JSON') from exc
    expected = hmac.new(secret.encode('utf-8'), body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        district = record.get('district')
        status = record.get('status')
        fine = record.get('fine_cents')
        if not isinstance(district, str) or not district or (not isinstance(status, str)) or isinstance(fine, bool) or (not isinstance(fine, int)) or (fine < 0):
            raise ValueError('invalid record')
        if status == 'open':
            item = groups.setdefault(district, [0, 0])
            item[0] += 1
            item[1] += fine
    ordered = sorted(groups.items(), key=lambda pair: (-pair[1][1], pair[0]))
    all_groups = [{'district': name, 'count': values[0], 'total_fine': values[1]} for name, values in ordered]
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total': len(all_groups), 'groups': all_groups[start:start + page_size], 'grand_total': sum((x['total_fine'] for x in all_groups))}

