import json

def encode_snapshot(records: list[dict]) -> bytes:
    try:
        return json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid snapshot') from exc

def availability_page(blob: bytes, city: str, max_price: float, page: int, page_size: int) -> list[dict]:
    if not isinstance(blob, (bytes, bytearray)) or not isinstance(city, str):
        raise ValueError('invalid arguments')
    if isinstance(max_price, bool) or not isinstance(max_price, (int, float)) or max_price < 0:
        raise ValueError('invalid price')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        data = json.loads(bytes(blob).decode('utf-8'))
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid snapshot') from exc
    if not isinstance(data, list):
        raise ValueError('invalid snapshot')
    groups = {}
    for record in data:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = ('hotel', 'city', 'room_type', 'available', 'price')
        if any((key not in record for key in required)):
            raise ValueError('invalid record')
        if not all((isinstance(record[key], str) for key in ('hotel', 'city', 'room_type'))):
            raise ValueError('invalid record')
        if type(record['available']) is not bool:
            raise ValueError('invalid record')
        if isinstance(record['price'], bool) or not isinstance(record['price'], (int, float)):
            raise ValueError('invalid record')
        if record['available'] and record['city'] == city and (record['price'] <= max_price):
            groups.setdefault(record['hotel'], []).append(record['price'])
    result = []
    for hotel, prices in groups.items():
        result.append({'hotel': hotel, 'rooms': len(prices), 'cheapest_price': round(min(prices), 2), 'average_price': round(sum(prices) / len(prices), 2)})
    result.sort(key=lambda item: (item['cheapest_price'], item['hotel']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

