import ast

def _evaluate(text, values):
    tree = ast.parse(text, mode='eval').body
    allowed = {'min': min, 'max': max, 'round': round}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in values:
                return values[node.id]
            if node.id in allowed:
                return allowed[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left, right = (visit(node.left), visit(node.right))
            if isinstance(node.op, ast.Add):
                return left + right
            if isinstance(node.op, ast.Sub):
                return left - right
            if isinstance(node.op, ast.Mult):
                return left * right
            return left / right
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            if isinstance(node.op, ast.And):
                result = visit(node.values[0])
                for part in node.values[1:]:
                    if not result:
                        return result
                    result = visit(part)
                return result
            result = visit(node.values[0])
            for part in node.values[1:]:
                if result:
                    return result
                result = visit(part)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = visit(comparator)
                if isinstance(op, ast.Lt):
                    ok = left < right
                elif isinstance(op, ast.LtE):
                    ok = left <= right
                elif isinstance(op, ast.Eq):
                    ok = left == right
                elif isinstance(op, ast.NotEq):
                    ok = left != right
                elif isinstance(op, ast.Gt):
                    ok = left > right
                elif isinstance(op, ast.GtE):
                    ok = left >= right
                else:
                    raise ValueError('operator')
                if not ok:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (not node.keywords) and (node.func.id in allowed):
            return allowed[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError('unsupported expression')
    return visit(tree)

def rank_elevators(readings: list[dict], filter_expr: str, score_expr: str, limit: int) -> list[dict]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('limit must be positive')
    results = []
    for reading in readings:
        values = {key: reading[key] for key in ('floor', 'load', 'temperature', 'trips', 'fault')}
        if _evaluate(filter_expr, values):
            score = _evaluate(score_expr, values)
            item = dict(reading)
            item['score'] = score
            results.append(item)
    results.sort(key=lambda item: (-item['score'], item['id']))
    return results[:limit]

