    if row is None:
        raise sqlite3.IntegrityError('customer does not exist')
    cur = conn.execute('INSERT INTO preorders(customer_id,isbn,quantity,status,created_at) VALUES (?,?,?,?,?)', (row[0], isbn, quantity, status, created_at))
    conn.commit()
    return int(cur.lastrowid)

def find_preorders(conn: sqlite3.Connection, customer_email: str | None=None, title: str | None=None, status: str | None=None, sort_by: str='created', descending: bool=False) -> list[dict]:
    columns = {'created': 'p.created_at', 'title': 'b.title', 'customer': 'c.name', 'quantity': 'p.quantity', 'total': 'p.quantity * b.price'}
    if sort_by not in columns:
        raise ValueError('sort_by')
    clauses, args = ([], [])
    if customer_email is not None:
        clauses.append('c.email = ?')
        args.append(customer_email)
    if title is not None:
        clauses.append('lower(b.title) LIKE lower(?)')
        args.append('%' + title + '%')
    if status is not None:
        clauses.append('p.status = ?')
        args.append(status)
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if descending else ' ASC'
    sql = 'SELECT p.id,c.email,c.name,p.isbn,b.title,p.quantity,b.price,p.quantity*b.price,p.status,p.created_at FROM preorders p JOIN customers c ON c.id=p.customer_id JOIN books b ON b.isbn=p.isbn' + where + ' ORDER BY ' + columns[sort_by] + direction + ', b.title ASC, p.id ASC'
    rows = conn.execute(sql, args).fetchall()
    keys = ['id', 'customer_email', 'customer_name', 'isbn', 'title', 'quantity', 'unit_price', 'total', 'status', 'created_at']
    return [dict(zip(keys, row)) for row in rows]

def customer_totals(conn: sqlite3.Connection, include_cancelled: bool=False) -> list[dict]:
    extra = '' if include_cancelled else " AND p.status != 'cancelled'"
    rows = conn.execute('SELECT c.email,c.name,COUNT(p.id),COALESCE(SUM(p.quantity*b.price),0) FROM customers c LEFT JOIN preorders p ON p.customer_id=c.id' + extra + ' LEFT JOIN books b ON b.isbn=p.isbn GROUP BY c.id ORDER BY COALESCE(SUM(p.quantity*b.price),0) DESC,c.name ASC,c.email ASC').fetchall()
    return [dict(zip(['email', 'name', 'order_count', 'total'], row)) for row in rows]

