import hashlib
import hmac
import os
from datetime import datetime

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return 'pbkdf2$100000$' + salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, stored_hash: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored_hash, str):
        return False
    try:
        kind, count, salt_hex, digest_hex = stored_hash.split('$')
        if kind != 'pbkdf2' or count != '100000':
            return False
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_evidence(events: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)):
        raise ValueError('invalid pagination')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    groups = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        required = ('evidence_id', 'case_id', 'officer', 'action', 'timestamp')
        if any((not isinstance(event.get(k), str) or not event[k] for k in required)):
            raise ValueError('invalid event')
        weight = event.get('weight_grams')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight < 0:
            raise ValueError('invalid event')
        try:
            timestamp = datetime.fromisoformat(event['timestamp'].replace('Z', '+00:00'))
        except (ValueError, TypeError):
            raise ValueError('invalid event')
        case = groups.setdefault(event['case_id'], {'count': 0, 'weight': 0.0, 'latest': timestamp, 'latest_text': event['timestamp']})
        case['count'] += 1
        case['weight'] += weight
        if timestamp > case['latest']:
            case['latest'] = timestamp
            case['latest_text'] = event['timestamp']
    ordered = sorted(groups.items(), key=lambda x: (-x[1]['latest'].timestamp(), x[0]))
    output = [{'case_id': k, 'event_count': v['count'], 'total_weight_grams': round(v['weight'], 2), 'latest_timestamp': v['latest_text']} for k, v in ordered]
    start = (page - 1) * page_size
    return {'total_events': len(events), 'total_cases': len(output), 'cases': output[start:start + page_size]}

