import math
import xml.etree.ElementTree as ET

def summarize_weather(xml: str, station_prefix: str='', min_temperature: float | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if page <= 0 or page_size <= 0:
        raise ValueError('invalid pagination')
    try:
        root = ET.fromstring(xml)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'weather':
        raise ValueError('invalid root')
    groups = {}
    for node in root:
        if node.tag != 'reading':
            raise ValueError('invalid child')
        required = ('station', 'timestamp', 'temperature', 'humidity')
        if any((name not in node.attrib for name in required)):
            raise ValueError('missing attribute')
        station = node.attrib['station']
        if not station:
            raise ValueError('empty station')
        try:
            temperature = float(node.attrib['temperature'])
            humidity = float(node.attrib['humidity'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid number') from exc
        if not math.isfinite(temperature) or not math.isfinite(humidity):
            raise ValueError('invalid number')
        if not station.startswith(station_prefix):
            continue
        if min_temperature is not None and temperature < min_temperature:
            continue
        item = groups.setdefault(station, [])
        item.append((temperature, humidity))
    result = []
    for station, values in groups.items():
        temperatures = [value[0] for value in values]
        humidities = [value[1] for value in values]
        result.append({'station': station, 'count': len(values), 'average_temperature': round(sum(temperatures) / len(values), 2), 'min_temperature': round(min(temperatures), 2), 'max_temperature': round(max(temperatures), 2), 'average_humidity': round(sum(humidities) / len(values), 2)})
    result.sort(key=lambda item: (-item['average_temperature'], -item['count'], item['station']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

