import hashlib
import hmac
import json

def _key(config):
    key = config.get('manifest_key')
    if not isinstance(key, str) or not key:
        raise ValueError('manifest_key is required')
    return key.encode('utf-8')

def build_collection_manifest(records: list[dict], config: dict) -> dict:
    key = _key(config)
    if not records:
        raise ValueError('records must not be empty')
    taxpayer = records[0].get('taxpayer_id')
    if not isinstance(taxpayer, str) or not taxpayer:
        raise ValueError('invalid record')
    order = {name: i for i, name in enumerate(('identity', 'income', 'deductions', 'credits', 'other'))}
    documents = []
    for record in records:
        category = record.get('category')
        filename = record.get('filename')
        pages = record.get('pages')
        if record.get('taxpayer_id') != taxpayer or not isinstance(category, str) or (not category.strip()) or (not isinstance(filename, str)) or (not filename) or (not isinstance(pages, int)) or isinstance(pages, bool) or (pages <= 0):
            if record.get('taxpayer_id') != taxpayer:
                raise ValueError('records must belong to one taxpayer')
            raise ValueError('invalid record')
        documents.append({'category': category.strip().lower(), 'filename': filename, 'pages': pages})
    documents.sort(key=lambda x: (order.get(x['category'], len(order)), x['category'], x['filename']))
    result = {'taxpayer_id': taxpayer, 'documents': documents, 'totals': {'documents': len(documents), 'pages': sum((x['pages'] for x in documents))}}
    data = json.dumps(result, sort_keys=True, separators=(',', ':')).encode('utf-8')
    result['signature'] = hmac.new(key, data, hashlib.sha256).hexdigest()
    return result

def verify_collection_manifest(manifest: dict, config: dict) -> bool:
    key = _key(config)
    if not isinstance(manifest, dict) or not isinstance(manifest.get('signature'), str):
        return False
    signature = manifest['signature']
    if len(signature) != 64:
        return False
    try:
        bytes.fromhex(signature)
    except ValueError:
        return False
    payload = {k: v for k, v in manifest.items() if k != 'signature'}
    data = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    expected = hmac.new(key, data, hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, expected)

