import xml.etree.ElementTree as ET

def find_available_rooms(xml_text: str, check_in: str, check_out: str, guests: int, page: int=1, page_size: int=10) -> dict:
    try:
        start = datetime.date.fromisoformat(check_in)
        end = datetime.date.fromisoformat(check_out)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if end <= start or guests <= 0 or page <= 0 or (page_size <= 0):
        raise ValueError('invalid argument')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    rows = []
    for hotel in root.findall('hotel'):
        hid = hotel.attrib.get('id')
        hname = hotel.attrib.get('name')
        if hid is None or hname is None:
            raise ValueError('missing attribute')
        for room in hotel.findall('room'):
            required = ('type', 'capacity', 'price', 'currency', 'available_from', 'available_to', 'available')
            if any((key not in room.attrib for key in required)):
                raise ValueError('missing attribute')
            try:
                capacity = int(room.attrib['capacity'])
                price = Decimal(room.attrib['price'])
                available = room.attrib['available'].lower()
                first = datetime.date.fromisoformat(room.attrib['available_from'])
                last = datetime.date.fromisoformat(room.attrib['available_to'])
            except Exception as exc:
                raise ValueError('invalid room data') from exc
            if available not in ('true', 'false'):
                raise ValueError('invalid availability')
            if available == 'true' and capacity >= guests and (first <= start) and (end <= last):
                total = (price * (end - start).days).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
