import subprocess
from datetime import date, datetime

def _minutes(value):
    try:
        parsed = datetime.strptime(value, '%H:%M')
    except ValueError as exc:
        raise ValueError('invalid time') from exc
    return parsed.hour * 60 + parsed.minute

def read_bookings(path: str, day: str) -> list[tuple[str, str, str, int]]:
    try:
        date.fromisoformat(day)
    except ValueError as exc:
        raise ValueError('invalid day') from exc
    try:
        result = subprocess.run(['sort', '-t', '\t', '-k4,4', '-k2,2', '-k3,3', path], check=True, capture_output=True, text=True)
    except (OSError, subprocess.CalledProcessError) as exc:
        raise RuntimeError('unable to read bookings') from exc
    rows = []
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split('\t')
        if len(fields) != 5:
            raise ValueError('malformed row')
        row_day, start, end, room, count_text = fields
        try:
            date.fromisoformat(row_day)
            count = int(count_text)
        except ValueError as exc:
            raise ValueError('malformed row') from exc
        start_n = _minutes(start)
        end_n = _minutes(end)
        if end_n <= start_n or count < 0:
            raise ValueError('invalid booking')
        if row_day == day:
            rows.append((room, start, end, count))
    return rows

def room_usage_report(path: str, day: str) -> list[dict[str, object]]:
    rows = read_bookings(path, day)
    grouped = {}
    for room, start, end, count in rows:
        grouped.setdefault(room, []).append((_minutes(start), _minutes(end), count))
    output = []
    for room in sorted(grouped):
        intervals = sorted(grouped[room])
        covered = 0
        current_start = current_end = None
        events = []
        for start, end, count in intervals:
            events.append((start, 1, count))
            events.append((end, 0, -count))
            if current_start is None:
                current_start, current_end = (start, end)
            elif start > current_end:
                covered += current_end - current_start
                current_start, current_end = (start, end)
            else:
                current_end = max(current_end, end)
        if current_start is not None:
            covered += current_end - current_start
        active = peak = 0
        for _, kind, change in sorted(events, key=lambda item: (item[0], item[1])):
            active += change
            peak = max(peak, active)
        output.append({'room': room, 'bookings': len(intervals), 'minutes': covered, 'peak_attendees': peak})
    return output

