import secrets

def parse_bid_sheet(text: str) -> list[dict]:
    records = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        escaped = False
        for ch in raw:
            if escaped:
                if ch not in '\\|':
                    raise ValueError('invalid escape')
                current.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(ch)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current).strip())
        if len(fields) != 4 or not fields[0] or (not fields[3]):
            raise ValueError('invalid record')
        try:
            price = float(fields[1])
            lead = int(fields[2])
        except ValueError:
            raise ValueError('invalid number')
        if price <= 0 or lead < 0 or str(lead) != fields[2].strip():
            raise ValueError('invalid number')
        key = fields[0].casefold()
        if key in seen:
            raise ValueError('duplicate vendor')
        seen.add(key)
        records.append({'vendor': fields[0], 'price': price, 'lead_days': lead, 'region': fields[3]})
    return records

def rank_bids(bids: list[dict], budget: float, max_lead: int, preferred_regions: tuple[str, ...]=()) -> list[dict]:
    if budget < 0 or max_lead < 0:
        raise ValueError('invalid limits')
    preferred = {x.casefold() for x in preferred_regions}
    selected = []
    for bid in bids:
        if bid['price'] <= budget and bid['lead_days'] <= max_lead:
            score = bid['price'] + bid['lead_days'] * 0.25
            if bid['region'].casefold() in preferred:
                score -= 2.0
            item = dict(bid)
            item['score'] = round(score, 2)
