def fetch_consultation_slots(base_url: str, clinician_id: str, start_date: str, end_date: str, token: str | None=None) -> list[dict]:
    headers = {'Accept': 'application/json'}
    if token is not None:
        headers['Authorization'] = 'Bearer ' + token
    response = requests.get(base_url.rstrip('/') + '/v1/consultation-slots', params={'clinician_id': clinician_id, 'start_date': start_date, 'end_date': end_date}, headers=headers)
    if response.status_code != 200:
        raise RuntimeError('request failed with status ' + str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('slots'), list):
        raise ValueError('invalid response')
    result = []
    for item in payload['slots']:
        if not isinstance(item, dict) or any((not isinstance(item.get(k), str) or not item[k] for k in ('id', 'start', 'end', 'mode'))):
            raise ValueError('invalid slot')
        start, end = (_time(item['start']), _time(item['end']))
        minutes = (end - start).total_seconds() / 60
        if minutes <= 0 or minutes != int(minutes):
            raise ValueError('invalid slot')
        result.append({'id': item['id'], 'start': item['start'], 'end': item['end'], 'mode': item['mode'], 'duration_minutes': int(minutes)})
    return result

def select_consultation_slots(slots: list[dict], requested_minutes: int, preferred_modes: list[str], limit: int) -> list[dict]:
    if requested_minutes <= 0 or limit < 0:
        raise ValueError('invalid limits')
    ranks = {mode: i for i, mode in enumerate(preferred_modes)}
    chosen = [s for s in slots if s['duration_minutes'] >= requested_minutes and (not preferred_modes or s['mode'] in ranks)]
    chosen.sort(key=lambda s: (_time(s['start']), ranks.get(s['mode'], len(ranks)), s['duration_minutes'], str(s['id'])))
    return chosen[:limit]

def build_daily_schedule(slots: list[dict], max_per_day: int) -> dict[str, list[dict]]:
    if max_per_day < 0:
        raise ValueError('invalid limit')
    groups = {}
    for slot in slots:
        groups.setdefault(_time(slot['start']).date().isoformat(), []).append(slot)
    result = {}
    for day in sorted(groups):
        ordered = sorted(groups[day], key=lambda s: (_time(s['start']), str(s['id'])))
        accepted = []
        previous_end = None
        for slot in ordered:
            if len(accepted) == max_per_day:
                break
            start, end = (_time(slot['start']), _time(slot['end']))
            if previous_end is None or start >= previous_end:
                accepted.append(slot)
                previous_end = end
        if accepted:
            result[day] = accepted
    return result

