from decimal import Decimal, ROUND_HALF_UP

def _validate(claims):
    if not isinstance(claims, list):
        raise ValueError('claims must be a list')
    for claim in claims:
        if not isinstance(claim, dict) or set(claim) != {'id', 'claimant', 'amount', 'status'}:
            raise ValueError('invalid claim')
        if not isinstance(claim['id'], str) or not claim['id']:
            raise ValueError('invalid id')
        if not isinstance(claim['claimant'], str) or not claim['claimant']:
            raise ValueError('invalid claimant')
        amount = claim['amount']
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid amount')
        if claim['status'] not in {'pending', 'approved', 'denied'}:
            raise ValueError('invalid status')

def encode_claims(claims: list[dict]) -> bytes:
    _validate(claims)
    try:
        return json.dumps(claims, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid claims') from exc

def summarize_claims(payload: bytes, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        claims = json.loads(payload.decode('utf-8'))
        _validate(claims)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    counts = {'pending': 0, 'approved': 0, 'denied': 0}
    approved = []
    total = Decimal('0')
    for claim in claims:
        counts[claim['status']] += 1
        if claim['status'] == 'approved':
            approved.append(claim)
            total += Decimal(str(claim['amount']))
    approved.sort(key=lambda c: (-c['amount'], c['id']))
    start = (page - 1) * page_size
    return {'total_claims': len(claims), 'approved_total': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'by_status': counts, 'claims': approved[start:start + page_size]}

