from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def generate_bill(requester: dict, meter: dict, readings: list[dict], start: str, end: str, rate: str) -> dict:
    try:
        start_date = date.fromisoformat(start)
        end_date = date.fromisoformat(end)
    except (TypeError, ValueError):
        raise ValueError('invalid period')
    if start_date > end_date:
        raise ValueError('invalid period')
    try:
        unit_rate = Decimal(str(rate))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid rate')
    if unit_rate < 0 or isinstance(rate, bool):
        raise ValueError('invalid rate')
    if requester.get('tenant_id') != meter.get('tenant_id'):
        raise PermissionError('not permitted')
    roles = requester.get('roles', [])
    if requester.get('id') != meter.get('owner_id') and 'billing_admin' not in roles:
        raise PermissionError('not permitted')
    total = Decimal('0')
    for reading in readings:
        if not isinstance(reading, dict):
            raise ValueError('invalid reading')
        if reading.get('meter_id') != meter.get('meter_id'):
            raise ValueError('invalid reading')
        try:
            reading_date = date.fromisoformat(reading['date'])
            usage = Decimal(str(reading['kwh']))
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid reading')
        if isinstance(reading.get('kwh'), bool) or usage < 0:
            raise ValueError('invalid reading')
        if not start_date <= reading_date <= end_date:
            raise ValueError('reading outside period')
        total += usage
    first = min(total, Decimal('100'))
    excess = max(total - Decimal('100'), Decimal('0'))
    energy = first * unit_rate + excess * unit_rate * Decimal('1.5')
    quant = Decimal('0.01')
    energy = energy.quantize(quant, rounding=ROUND_HALF_UP)
    service = Decimal('12.50')
    final = energy + service
    return {'meter_id': meter['meter_id'], 'period_start': start, 'period_end': end, 'reading_count': len(readings), 'total_kwh': total.quantize(quant, rounding=ROUND_HALF_UP).to_eng_string(), 'energy_charge': energy.to_eng_string(), 'service_charge': service.to_eng_string(), 'total': final.quantize(quant, rounding=ROUND_HALF_UP).to_eng_string()}

