import csv
import math
import os
import tempfile

def create_rebalance_report(current: dict[str, float], targets: dict[str, float], total_value: float) -> str:
    if not current or not targets or (not math.isfinite(total_value)) or (total_value <= 0):
        raise ValueError('invalid portfolio')
    if any((not math.isfinite(v) or v < 0 for v in current.values())):
        raise ValueError('invalid current value')
    if any((not math.isfinite(v) or v < 0 for v in targets.values())):
        raise ValueError('invalid target weight')
    if not math.isclose(sum(targets.values()), 1.0, abs_tol=1e-09):
        raise ValueError('target weights must sum to one')
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['Symbol', 'Current Value', 'Target Value', 'Change'])
            for symbol in sorted(set(current) | set(targets)):
                old = current.get(symbol, 0.0)
                target = total_value * targets.get(symbol, 0.0)
                writer.writerow([symbol, f'{old:.2f}', f'{target:.2f}', f'{target - old:.2f}'])
        with open(path, newline='') as handle:
            return handle.read()
    finally:
        os.unlink(path)

