import requests

def fetch_weather_summary(city: str, api_key: str, days: int=3, page: int=1, page_size: int=10) -> list[dict[str, Any]]:
    if not isinstance(city, str) or not city or (not isinstance(api_key, str)) or (not api_key):
        raise ValueError('invalid city or api key')
    if isinstance(days, bool) or not isinstance(days, int) or (not 1 <= days <= 16):
        raise ValueError('invalid days')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 50):
        raise ValueError('invalid page size')
    response = requests.get('https://api.example.com/v1/forecast', params={'city': city, 'days': days, 'format': 'json'}, headers={'X-API-Key': api_key}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'weather service returned status {response.status_code}')
    try:
        records = response.json()['forecast']
    except (KeyError, TypeError):
        raise ValueError('invalid forecast response')
    if not isinstance(records, list):
        raise ValueError('invalid forecast response')
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or not all((key in record for key in ('date', 'temp_c', 'rain_mm'))):
            raise ValueError('invalid forecast record')
        date = record['date']
        temp = record['temp_c']
        rain = record['rain_mm']
        if not isinstance(date, str) or not isinstance(temp, (int, float)) or isinstance(temp, bool) or (not isinstance(rain, (int, float))) or isinstance(rain, bool):
            raise ValueError('invalid forecast record')
        try:
            datetime.strptime(date, '%Y-%m-%d')
        except (ValueError, TypeError):
            raise ValueError('invalid forecast record')
        if date not in grouped:
            grouped[date] = [0.0, 0.0, 0]
        grouped[date][0] += temp
        grouped[date][1] += rain
        grouped[date][2] += 1
    result = [{'date': date, 'avg_temp_c': round(values[0] / values[2], 1), 'total_rain_mm': round(values[1], 1)} for date, values in grouped.items() if values[1] > 0]
    result.sort(key=lambda item: (-item['total_rain_mm'], item['date']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

