def booking_summary_csv(bookings: list[dict], destination: str) -> int:
    rows = {}
    for booking in bookings:
        if not isinstance(booking, dict):
            raise ValueError('invalid booking')
        try:
            guide = booking['guide']
            day = booking['date']
            guests = booking['guests']
            price = booking['price']
            status = booking['status']
        except KeyError as exc:
            raise ValueError('invalid booking') from exc
        if not isinstance(guide, str) or not guide:
            raise ValueError('invalid guide')
        if not isinstance(day, str):
            raise ValueError('invalid date')
        try:
            date.fromisoformat(day)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if isinstance(guests, bool) or not isinstance(guests, int) or guests <= 0:
            raise ValueError('invalid guests')
        try:
            amount = Decimal(str(price))
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid price') from exc
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid price')
        if status not in ('confirmed', 'cancelled'):
            raise ValueError('invalid status')
        if status == 'confirmed':
            group = rows.setdefault(guide, [0, 0, Decimal('0')])
            group[0] += 1
            group[1] += guests
            group[2] += amount
    ordered = sorted(rows.items(), key=lambda item: (-item[1][2], item[0]))
    fd, temporary = tempfile.mkstemp(prefix='booking-', suffix='.csv', dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['guide', 'bookings', 'guests', 'revenue'])
            for guide, (count, guests, amount) in ordered:
                writer.writerow([guide, count, guests, format(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(ordered)

