import requests

def fetch_gateway_report(gateway_id: str, token: str, min_battery: float=20.0) -> list[dict]:
    if isinstance(min_battery, bool) or not isinstance(min_battery, (int, float)) or (not math.isfinite(min_battery)) or (not 0 <= min_battery <= 100):
        raise ValueError('invalid minimum battery')
    url = f'https://api.agri.example/gateways/{gateway_id}/readings'
    response = requests.get(url, headers={'Authorization': f'Bearer {token}'}, params={'limit': 100}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'gateway request failed: {response.status_code}')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('readings'), list):
        raise ValueError('invalid response')
    groups = {}
    for item in payload['readings']:
        if not isinstance(item, dict):
            continue
        sensor = item.get('sensor_id')
        timestamp = item.get('timestamp')
        moisture = item.get('moisture')
        battery = item.get('battery')
        if not isinstance(sensor, str) or not sensor or (not isinstance(timestamp, str)) or (not timestamp):
            continue
        if isinstance(moisture, bool) or isinstance(battery, bool) or (not isinstance(moisture, (int, float))) or (not isinstance(battery, (int, float))):
            continue
        if not math.isfinite(moisture) or not math.isfinite(battery) or (not 0 <= moisture <= 100) or (battery < min_battery):
            continue
        groups.setdefault(sensor, []).append((timestamp, float(moisture)))
    result = []
    for sensor, values in groups.items():
        result.append({'sensor_id': sensor, 'average_moisture': round(sum((x[1] for x in values)) / len(values), 2), 'latest_timestamp': max((x[0] for x in values)), 'readings': len(values)})
    return sorted(result, key=lambda x: (-x['average_moisture'], x['sensor_id']))

