import hmac
import os

def make_credential(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def check_credential(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        if len(salt) != 16 or len(expected) != 32:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, UnicodeError):
        return False

def build_dispatch_page(tasks: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(tasks, list):
        raise ValueError('tasks must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    ready = []
    for task in tasks:
        if not isinstance(task, dict):
            raise ValueError('invalid task')
        fields = ('flight', 'gate', 'service', 'eta', 'priority', 'status')
        if any((field not in task for field in fields)):
            raise ValueError('missing field')
        flight, gate, service = (task['flight'], task['gate'], task['service'])
        eta, priority, status = (task['eta'], task['priority'], task['status'])
        if not isinstance(flight, str) or not flight or (not isinstance(service, str)) or (not service):
            raise ValueError('invalid text')
        if isinstance(gate, bool) or not isinstance(gate, int) or gate < 1:
            raise ValueError('invalid gate')
        if isinstance(eta, bool) or not isinstance(eta, int) or eta < 0:
            raise ValueError('invalid eta')
        if isinstance(priority, bool) or not isinstance(priority, int) or (not 1 <= priority <= 5):
            raise ValueError('invalid priority')
        if status not in ('ready', 'hold'):
            raise ValueError('invalid status')
        if status == 'ready':
            ready.append({field: task[field] for field in fields})
    ready.sort(key=lambda x: (-x['priority'], x['eta'], x['gate'], x['flight']))
    total = len(ready)
    pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total': total, 'pages': pages, 'has_next': page < pages, 'average_eta': round(sum((x['eta'] for x in ready)) / total, 1) if total else 0.0, 'tasks': ready[start:start + page_size]}

