def export_transcription_jobs(jobs: list[dict], output_path: str, page: int=1, page_size: int=50) -> dict:
    if not isinstance(jobs, list):
        raise ValueError('jobs must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 1000):
        raise ValueError('invalid page size')
    completed = []
    for job in jobs:
        if not isinstance(job, dict):
            raise ValueError('invalid job')
        required = ('id', 'speaker', 'started_at', 'duration_seconds', 'text', 'status')
        if any((k not in job for k in required)):
            raise ValueError('invalid job')
        if not isinstance(job['id'], str) or not job['id']:
            raise ValueError('invalid id')
        if not all((isinstance(job[k], str) for k in ('speaker', 'started_at', 'text', 'status'))):
            raise ValueError('invalid field')
        duration = job['duration_seconds']
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or (not math.isfinite(duration)) or (duration < 0):
            raise ValueError('invalid duration')
        if job['status'] not in ('completed', 'failed', 'running'):
            raise ValueError('invalid status')
        if job['status'] == 'completed':
            completed.append(job)
    completed.sort(key=lambda x: (-x['duration_seconds'], x['started_at'], x['id']))
    pages = (len(completed) + page_size - 1) // page_size
    start = (page - 1) * page_size
    selected = completed[start:start + page_size]
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(('id', 'speaker', 'started_at', 'duration_seconds', 'text'))
            for job in selected:
                writer.writerow((job['id'], job['speaker'], job['started_at'], f"{job['duration_seconds']:.2f}", job['text']))
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'exported': len(selected), 'total_duration': round(sum((x['duration_seconds'] for x in selected)), 2), 'page': page, 'pages': pages}

