def parse_vehicle_log(text: str) -> list[dict]:
    records = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields, current, escaped = ([], [], False)
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('unfinished escape')
        fields.append(''.join(current))
        if len(fields) != 4 or fields[2] not in {'idle', 'loading', 'enroute', 'complete'}:
            raise ValueError('invalid event')
        try:
            timestamp = int(fields[0])
        except ValueError:
            raise ValueError('invalid timestamp')
        key = (timestamp, fields[1])
        if not fields[1] or key in seen:
            raise ValueError('duplicate event')
        seen.add(key)
        records.append({'timestamp': timestamp, 'vehicle_id': fields[1], 'status': fields[2], 'note': fields[3]})
    return sorted(records, key=lambda x: (x['timestamp'], x['vehicle_id']))

def dispatch_jobs(user: dict, vehicles: list[dict], jobs: list[dict], shift_start: int) -> list[dict]:
    if not isinstance(shift_start, int) or not isinstance(user, dict):
        raise ValueError('invalid request')
    if user.get('tenant_id') is None or 'dispatcher' not in user.get('roles', []):
        raise PermissionError('dispatch not permitted')
    vs, ids = ([], set())
    for item in vehicles:
        try:
            vid, tenant, owner = (item['id'], item['tenant_id'], item['owner_id'])
            cap, available = (item['capacity'], item['available_from'])
            capabilities = set(item['capabilities'])
        except (KeyError, TypeError):
            raise ValueError('invalid vehicle')
        if not isinstance(vid, str) or not vid or vid in ids or (not isinstance(cap, int)) or (cap < 0) or (not isinstance(available, int)):
            raise ValueError('invalid vehicle')
        ids.add(vid)
        vs.append({'id': vid, 'tenant_id': tenant, 'owner_id': owner, 'capacity': cap, 'capabilities': capabilities, 'available': max(available, shift_start)})
    ordered, jids = ([], set())
    for job in jobs:
        try:
            jid = job['id']
            values = [job['weight'], job['duration'], job['priority'], job['earliest'], job['latest']]
            required = set(job['required_capabilities'])
        except (KeyError, TypeError):
            raise ValueError('invalid job')
        if not isinstance(jid, str) or not jid or jid in jids or any((not isinstance(x, int) for x in values)) or (values[0] <= 0) or (values[1] <= 0) or (values[4] < values[3]):
            raise ValueError('invalid job')
        jids.add(jid)
        ordered.append((job, required))
    ordered.sort(key=lambda x: (-x[0]['priority'], x[0]['earliest'], x[0]['id']))
    result = []
    for job, required in ordered:
        choices = [v for v in vs if v['tenant_id'] == job['tenant_id'] and v['capacity'] >= job['weight'] and (required <= v['capabilities']) and (v['available'] <= job['latest'])]
        if not choices:
            raise ValueError('no vehicle')
        v = min(choices, key=lambda x: (max(x['available'], job['earliest']), x['capacity'], x['id']))
        start = max(v['available'], job['earliest'])
        end = start + job['duration']
        if end > job['latest']:
            raise ValueError('deadline')
        v['available'] = end
        result.append({'job_id': job['id'], 'vehicle_id': v['id'], 'start': start, 'end': end})
    return result

