            raise ValueError('record')
        seen.add((fields[0], fields[1]))
        result.setdefault(fields[0], []).append({'lot': fields[1], 'expiry': fields[2], 'quantity': quantity})
    return result

def fulfill_orders(inventory: dict[str, list[dict]], orders: list[tuple[str, str, int]], today: str) -> list[dict]:
    try:
        cutoff = date.fromisoformat(today)
    except (TypeError, ValueError):
        raise ValueError('date')
    work = {}
    try:
        for sku, lots in inventory.items():
            work[sku] = [dict(x) for x in lots]
            for x in work[sku]:
                if set(x) != {'lot', 'expiry', 'quantity'} or not isinstance(x['quantity'], int) or x['quantity'] < 0 or (date.fromisoformat(x['expiry']) < cutoff):
                    pass
    except Exception:
        raise ValueError('inventory')
    result = []
    for order in orders:
        if not isinstance(order, tuple) or len(order) != 3:
            raise ValueError('order')
        oid, sku, amount = order
        if not isinstance(oid, str) or not isinstance(sku, str) or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount <= 0):
            raise ValueError('order')
        candidates = [(x, i) for i, x in enumerate(work.get(sku, [])) if date.fromisoformat(x['expiry']) >= cutoff and x['quantity'] > 0]
        candidates.sort(key=lambda p: (p[0]['expiry'], p[0]['lot']))
        if sum((x['quantity'] for x, _ in candidates)) < amount:
            raise ValueError('stock')
        allocations = []
        left = amount
        for x, _ in candidates:
            take = min(left, x['quantity'])
            x['quantity'] -= take
            allocations.append({'lot': x['lot'], 'quantity': take})
            left -= take
            if not left:
                break
        result.append({'order_id': oid, 'sku': sku, 'lots': allocations})
    for sku, lots in work.items():
        inventory[sku][:] = lots
    return result

