        return json.dumps(records, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('records cannot be encoded') from exc

def summarize_schedule(blob: bytes, page: int=0, page_size: int=20) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        records = json.loads(blob.decode('utf-8'))
    except (AttributeError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid schedule') from exc
    if not isinstance(records, list):
        raise ValueError('invalid schedule')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            line = record['line']
            date = record['date']
            minutes = record['minutes']
            quantity = record['quantity']
        except KeyError as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(line, str) or not line or (not isinstance(date, str)) or (not isinstance(minutes, int)) or isinstance(minutes, bool) or (minutes < 0) or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity < 0):
            raise ValueError('invalid record')
        try:
            parsed = datetime.strptime(date, '%Y-%m-%d')
            if parsed.strftime('%Y-%m-%d') != date:
                raise ValueError
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        key = (date, line)
        group = groups.setdefault(key, [0, 0, 0])
        group[0] += 1
        group[1] += minutes
        group[2] += quantity
    rows = []
    for (date, line), (jobs, minutes, quantity) in groups.items():
        rows.append({'date': date, 'line': line, 'jobs': jobs, 'minutes': minutes, 'quantity': quantity, 'load_hours': round(minutes / 60, 2)})
    rows.sort(key=lambda row: (row['date'], -row['minutes'], row['line']))
