            raise ValueError('invalid animal_id')
        if not isinstance(record['name'], str) or not isinstance(record['species'], str) or (not record['species']):
            raise ValueError('invalid text')
        if isinstance(record['age_months'], bool) or not isinstance(record['age_months'], int) or record['age_months'] < 0:
            raise ValueError('invalid age')
        if record['status'] not in ('available', 'adopted'):
            raise ValueError('invalid status')
        fee = record['adoption_fee']
        if isinstance(fee, bool) or not isinstance(fee, (int, float)) or (not math.isfinite(fee)) or (fee < 0):
            raise ValueError('invalid fee')
        validated.append(record)
    adopted = [r for r in validated if r['status'] == 'adopted']
    adopted.sort(key=lambda r: (r['species'], -r['adoption_fee'], r['animal_id']))
    by_species = {}
    for record in adopted:
        by_species[record['species']] = by_species.get(record['species'], 0) + 1
    total = round(sum((r['adoption_fee'] for r in adopted)), 2)
    parent = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(prefix='adoption-', suffix='.csv', dir=parent)
    os.close(fd)
    try:
        with open(temporary, 'w', newline='') as stream:
            writer = csv.writer(stream)
            writer.writerow(['animal_id', 'name', 'species', 'age_months', 'adoption_fee'])
            for record in adopted:
                writer.writerow([record['animal_id'], record['name'], record['species'], record['age_months'], f"{record['adoption_fee']:.2f}"])
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'total_adoptions': len(adopted), 'total_fees': total, 'by_species': dict(sorted(by_species.items()))}

