    for match in payload['matches']:
        result.append({'round': match['round'], 'slot': match['slot'], 'team1': str(match['team1']).strip(), 'team2': str(match['team2']).strip(), 'score1': int(match['score1']), 'score2': int(match['score2'])})
    return sorted(result, key=lambda item: (item['round'], item['slot']))

def compute_standings(matches: list[dict]) -> list[dict]:
    stats = {}
    for match in matches:
        a, b = (match['team1'], match['team2'])
        x, y = (match['score1'], match['score2'])
        if not isinstance(x, int) or isinstance(x, bool) or (not isinstance(y, int)) or isinstance(y, bool) or (x < 0) or (y < 0):
            raise ValueError('invalid match score')
        if not isinstance(a, str) or not isinstance(b, str) or (not a) or (not b) or (a == b):
            raise ValueError('invalid match teams')
        for team in (a, b):
            if team not in stats:
                stats[team] = {'team': team, 'played': 0, 'wins': 0, 'draws': 0, 'losses': 0, 'points': 0, 'scored': 0, 'conceded': 0, 'difference': 0}
        stats[a]['played'] += 1
        stats[b]['played'] += 1
        stats[a]['scored'] += x
        stats[a]['conceded'] += y
        stats[b]['scored'] += y
        stats[b]['conceded'] += x
        if x > y:
            stats[a]['wins'] += 1
            stats[a]['points'] += 3
            stats[b]['losses'] += 1
        elif y > x:
            stats[b]['wins'] += 1
            stats[b]['points'] += 3
            stats[a]['losses'] += 1
        else:
            stats[a]['draws'] += 1
            stats[b]['draws'] += 1
            stats[a]['points'] += 1
            stats[b]['points'] += 1
    for row in stats.values():
        row['difference'] = row['scored'] - row['conceded']
    return sorted(stats.values(), key=lambda r: (-r['points'], -r['difference'], -r['scored'], r['team']))

