    if requester.get('user_id') != course.get('instructor_id') and 'admin' not in roles:
        raise PermissionError('forbidden')
    selected = [a for a in assignments if a.get('course_id') == course_id]
    total_weight = 0
    by_id = {}
    for a in selected:
        if a.get('points_possible', 0) <= 0 or a.get('weight', 0) < 0:
            raise ValueError('invalid assignment')
        total_weight += a['weight']
        by_id[a['assignment_id']] = a
    if selected and total_weight == 0:
        raise ValueError('zero weight')
