        values = [latest[student, a['assignment_id']] / a['points_possible'] * a['weight'] for a in selected if (student, a['assignment_id']) in latest]
        pct = sum(values) / total_weight * 100
        rounded = round(pct, 2)
        letter = 'A' if pct >= 90 else 'B' if pct >= 80 else 'C' if pct >= 70 else 'D' if pct >= 60 else 'F'
        students.append({'student_id': student, 'percentage': rounded, 'letter': letter, 'submitted': len(values), 'missing': len(selected) - len(values), '_raw': pct})
    students.sort(key=lambda x: (-x['_raw'], x['student_id']))
    raw_average = sum((x['_raw'] for x in students)) / len(students) if students else 0.0
    for x in students:
        del x['_raw']
    start = (page - 1) * page_size
    return {'course_id': course_id, 'page': page, 'page_size': page_size, 'total_students': len(students), 'class_average': round(raw_average, 2), 'students': students[start:start + page_size]}

