import os

def summarize_fare_cards(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be a positive integer')
    token = os.environ.get('TRANSIT_API_TOKEN')
    if token is None:
        raise RuntimeError('TRANSIT_API_TOKEN is required')
    if '\r' in token or '\n' in token:
        raise ValueError('invalid token')
    grouped = {}
    total = 0
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        if not isinstance(record.get('card_id'), str) or not record['card_id']:
            raise ValueError('card_id must be a non-empty string')
        cents = record.get('fare_cents')
        if isinstance(cents, bool) or not isinstance(cents, int) or cents < 0:
            raise ValueError('fare_cents must be a non-negative integer')
        if record.get('status') not in {'completed', 'refunded', 'pending'}:
            raise ValueError('invalid status')
        if record['status'] == 'completed':
            item = grouped.setdefault(record['card_id'], {'card_id': record['card_id'], 'rides': 0, 'total_cents': 0})
            item['rides'] += 1
            item['total_cents'] += cents
            total += cents
    cards = sorted(grouped.values(), key=lambda x: (-x['total_cents'], x['card_id']))
    pages = math.ceil(len(cards) / page_size) if cards else 0
    start = (page - 1) * page_size
    return {'cards': cards[start:start + page_size], 'total_cents': total, 'page': page, 'page_size': page_size, 'pages': pages, 'headers': {'Authorization': 'Bearer ' + token}}

