import math
import re
from html import escape

def summarize_vouchers(records):
    grouped = {}
    for position, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError('record must be a dictionary')
        try:
            household = record['household']
            unit = record['unit']
            month = record['month']
            amount = record['amount']
            status = record['status']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not all((isinstance(value, str) for value in (household, unit, month, status))):
            raise ValueError('invalid string field')
        match = re.fullmatch('(\\d{4})-(\\d{2})', month)
        if not match or not 1 <= int(match.group(2)) <= 12:
            raise ValueError('invalid month')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid amount')
        if status not in {'approved', 'paid', 'held'}:
            raise ValueError('invalid status')
        grouped.setdefault(household, {})[month] = (unit, amount, status, position)
    result = []
    for household, months in grouped.items():
        latest_month = max(months)
        unit, _, status, _ = months[latest_month]
        total = round(sum((item[1] for item in months.values())), 2)
        result.append({'household': household, 'unit': unit, 'months': len(months), 'total': total, 'latest_status': status})
    result.sort(key=lambda item: (-item['total'], item['household'].casefold(), item['unit']))
    return result

def render_voucher_report(records, title):
    if not isinstance(title, str):
        raise TypeError('title must be a string')
    rows = []
    for item in summarize_vouchers(records):
        rows.append('<tr><td>{}</td><td>{}</td><td>{}</td><td>${:.2f}</td><td>{}</td></tr>'.format(escape(item['household'], quote=True), escape(item['unit'], quote=True), item['months'], item['total'], escape(item['latest_status'], quote=True)))
    return '<div class="voucher-report"><h1>{}</h1><table><thead><tr><th>Household</th><th>Unit</th><th>Months</th><th>Total</th><th>Latest status</th></tr></thead><tbody>{}</tbody></table></div>'.format(escape(title, quote=True), ''.join(rows))

