import hmac
import os

def hash_panel_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin.strip():
        raise ValueError('pin must be non-empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()

def verify_panel_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(stored, str)):
        return False
    try:
        salt_text, digest_text = stored.split(':')
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def survey_accessible(age: int, completed_surveys: int) -> bool:
    if not isinstance(age, int) or isinstance(age, bool) or (not isinstance(completed_surveys, int)) or isinstance(completed_surveys, bool):
        raise TypeError('age and completed_surveys must be integers')
    return age >= 18 and completed_surveys >= 0 and (completed_surveys < 5)

