import csv
import os
import re
import tempfile

def export_reservations(records: list[tuple[str, str]], destination: str) -> int:
    checked = []
    for movie, seat in records:
        if re.fullmatch('[A-Z][0-9]{1,2}', seat) is None:
            raise ValueError('invalid seat code')
        checked.append((movie, seat))
    rows = sorted(checked, key=lambda item: item[1])
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.reservations-', suffix='.tmp', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['movie', 'seat'])
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
