import json

def empty_state() -> dict:
    return {'version': 1, 'samples': {}}

def _check_state(state):
    if not isinstance(state, dict) or set(state) != {'version', 'samples'} or state['version'] != 1 or (not isinstance(state['samples'], dict)):
        raise ValueError('invalid state')
    for sid, item in state['samples'].items():
        if not isinstance(sid, str) or not sid or (not isinstance(item, dict)) or (set(item) != {'tests', 'last_result', 'last_collected_at'}):
            raise ValueError('invalid state')
        if isinstance(item['tests'], bool) or not isinstance(item['tests'], int) or item['tests'] < 0:
            raise ValueError('invalid state')
        if item['last_result'] is not None and (not isinstance(item['last_result'], str)):
            raise ValueError('invalid state')
        value = item['last_collected_at']
        if value is not None and (isinstance(value, bool) or not isinstance(value, int) or value < 0):
            raise ValueError('invalid state')

def encode_state(state: dict) -> bytes:
    _check_state(state)
    return json.dumps(state, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def decode_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('invalid data')
    try:
        state = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid data') from exc
    _check_state(state)
    return state

def _check_event(event):
    if not isinstance(event, dict) or set(event) != {'sample_id', 'test', 'result', 'collected_at', 'sequence'}:
        raise ValueError('invalid event')
    if not isinstance(event['sample_id'], str) or not event['sample_id'] or (not isinstance(event['test'], str)) or (not event['test']):
        raise ValueError('invalid event')
    if event['result'] not in {'pass', 'fail', 'pending'}:
        raise ValueError('invalid event')
    for key in ('collected_at', 'sequence'):
        if isinstance(event[key], bool) or not isinstance(event[key], int) or event[key] < 0:
            raise ValueError('invalid event')

def process_batch(events: list[dict], state_blob: bytes) -> tuple[list[dict], bytes]:
    state = decode_state(state_blob)
    if not isinstance(events, list):
        raise ValueError('invalid events')
    for event in events:
        _check_event(event)
    ordered = sorted(enumerate(events), key=lambda pair: (pair[1]['collected_at'], pair[1]['sequence'], pair[0]))
    updated = {'version': 1, 'samples': {sid: dict(item) for sid, item in state['samples'].items()}}
    changed = set()
    for _, event in ordered:
        sid = event['sample_id']
        item = updated['samples'].setdefault(sid, {'tests': 0, 'last_result': None, 'last_collected_at': None})
        item['tests'] += 1
        item['last_result'] = event['result']
        item['last_collected_at'] = event['collected_at']
        changed.add(sid)
    rows = []
    for sid in sorted(changed):
        item = updated['samples'][sid]
        rows.append({'sample_id': sid, **item, 'status': 'complete' if item['last_result'] in {'pass', 'fail'} else 'pending'})
    return (rows, encode_state(updated))

