def summarize_observations(path: str, species: str | None=None, min_depth: float=0.0, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    if not isinstance(min_depth, (int, float)) or isinstance(min_depth, bool) or (not math.isfinite(min_depth)):
        raise ValueError('min_depth must be finite')
