from decimal import Decimal, InvalidOperation

def parse_booking_line(line: str) -> dict:
    fields = []
    current = []
    escaped = False
    for char in line.rstrip('\n'):
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('incomplete escape')
    fields.append(''.join(current).strip())
    if len(fields) != 6 or any((not value for value in fields)):
        raise ValueError('invalid booking line')
    try:
        price = Decimal(fields[5])
    except InvalidOperation as exc:
        raise ValueError('invalid price') from exc
    if not price.is_finite() or price < 0 or price.as_tuple().exponent < -2:
        raise ValueError('invalid price')
    return dict(zip(('id', 'customer', 'movie', 'showtime', 'seat'), fields[:5]), price=price)

def summarize_bookings(bookings: list[dict]) -> list[dict]:
    groups = {}
    required = ('id', 'customer', 'movie', 'showtime', 'seat', 'price')
    for booking in bookings:
        if any((key not in booking for key in required)):
            raise ValueError('missing booking field')
        status = booking.get('status', 'confirmed')
        if status == 'cancelled':
            continue
        if status != 'confirmed':
            raise ValueError('invalid status')
