from datetime import datetime, timezone

def _time(value):
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00'))
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc

def _allowed(requester, project):
    if requester.get('tenant_id') != project.get('tenant_id'):
        raise PermissionError('not permitted')
    if requester.get('id') != project.get('owner_id') and (not {'inspector', 'admin'} & set(requester.get('roles', []))):
        raise PermissionError('not permitted')

def parse_load_record(line: str) -> dict:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('malformed escape')
    fields.append(''.join(current))
    if len(fields) != 5 or not fields[0] or (not fields[1]):
        raise ValueError('malformed record')
    _time(fields[1])
    try:
        kilograms = float(fields[3])
    except Exception as exc:
        raise ValueError('invalid kilograms') from exc
    if kilograms <= 0:
        raise ValueError('invalid kilograms')
    return {'id': fields[0], 'timestamp': fields[1], 'material': fields[2], 'kilograms': kilograms, 'destination': fields[4]}

def build_waste_report(requester: dict, project: dict, lines: list[str], start: str, end: str) -> dict:
    _allowed(requester, project)
    first, last = (_time(start), _time(end))
    if first > last:
        raise ValueError('invalid range')
    material, destination = ({}, {})
    total = 0.0
    count = 0
    for line in lines:
        record = parse_load_record(line)
        stamp = _time(record['timestamp'])
        if first <= stamp <= last:
            count += 1
            total += record['kilograms']
            material[record['material']] = material.get(record['material'], 0.0) + record['kilograms']
            destination[record['destination']] = destination.get(record['destination'], 0.0) + record['kilograms']
    mats = [{'material': key, 'kilograms': round(value, 2)} for key, value in material.items()]
    dests = [{'destination': key, 'kilograms': round(value, 2)} for key, value in destination.items()]
    mats.sort(key=lambda item: (-item['kilograms'], item['material']))
    dests.sort(key=lambda item: (-item['kilograms'], item['destination']))
    return {'project_id': project['project_id'], 'loads': count, 'total_kg': round(total, 2), 'by_material': mats, 'by_destination': dests}

def update_load_status(requester: dict, project: dict, load_id: str, new_status: str) -> dict:
    _allowed(requester, project)
    if new_status not in {'pending', 'collected', 'processed', 'rejected'}:
        raise ValueError('invalid status')
    for load in project['loads']:
        if load.get('id') == load_id:
            load['status'] = new_status
            return load
    raise ValueError('unknown load')

