from solution import verify_reservation_webhook
import hashlib
import hmac
import json
import pytest


def make_signature(payload, secret):
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()


def test_valid_reservation_is_returned_unchanged():
    payload = '{"desk_id":12,"employee":"Amina Noor","date":"2025-04-18"}'
    signature = make_signature(payload, "office-key")
    assert verify_reservation_webhook(payload, signature, "office-key") == {
        "desk_id": 12,
        "employee": "Amina Noor",
        "date": "2025-04-18",
    }


def test_signature_covers_exact_payload_text():
    payload = ' { "desk_id": 3, "employee": "Lee", "date": "2025-01-02" } '
    signature = make_signature(payload, "k")
    assert verify_reservation_webhook(payload, signature, "k")["desk_id"] == 3


def test_wrong_signature_raises_before_payload_processing():
    with pytest.raises(ValueError, match="^invalid signature$"):
        verify_reservation_webhook("not json", "0" * 64, "secret")


def test_empty_secret_is_supported():
    payload = json.dumps({"desk_id": 1, "employee": "Sam", "date": "2024-12-31"}, separators=(",", ":"))
    assert verify_reservation_webhook(payload, make_signature(payload, ""), "") == {
        "desk_id": 1,
        "employee": "Sam",
        "date": "2024-12-31",
    }


def test_malformed_json_raises_invalid_payload():
    payload = '{"desk_id":4,"employee":"Jo"'
    with pytest.raises(ValueError, match="^invalid payload$"):
        verify_reservation_webhook(payload, make_signature(payload, "s"), "s")


def test_missing_or_extra_fields_raise_invalid_payload():
    for value in [
        {"desk_id": 4, "employee": "Jo"},
        {"desk_id": 4, "employee": "Jo", "date": "2025-01-01", "floor": 2},
    ]:
        payload = json.dumps(value, separators=(",", ":"))
        with pytest.raises(ValueError, match="^invalid payload$"):
            verify_reservation_webhook(payload, make_signature(payload, "s"), "s")


def test_field_validation_rejects_invalid_values():
    cases = [
        {"desk_id": 0, "employee": "Jo", "date": "2025-01-01"},
        {"desk_id": True, "employee": "Jo", "date": "2025-01-01"},
        {"desk_id": 2, "employee": "", "date": "2025-01-01"},
        {"desk_id": 2, "employee": "Jo", "date": "01-01-2025"},
        {"desk_id": 2, "employee": "Jo", "date": "2025-02-30"},
    ]
