import json
import re

def verify_reservation_webhook(payload: str, signature: str, secret: str) -> dict:
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload)
        if set(value) != {'desk_id', 'employee', 'date'}:
            raise ValueError
        if type(value['desk_id']) is not int or value['desk_id'] <= 0:
            raise ValueError
        if not isinstance(value['employee'], str) or not value['employee']:
            raise ValueError
        if not isinstance(value['date'], str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value['date']):
            raise ValueError
        datetime.date.fromisoformat(value['date'])
        return value
    except (ValueError, TypeError, json.JSONDecodeError):
        raise ValueError('invalid payload')

