            raise ValueError('invalid employee')
        if not all((isinstance(employee[k], str) for k in ('employee_id', 'name', 'department', 'start_date'))):
            raise ValueError('invalid employee')
        try:
            datetime.date.fromisoformat(employee['start_date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        scores = employee['training_scores']
        if not isinstance(scores, (list, tuple)) or not scores or any((isinstance(x, bool) or not isinstance(x, (int, float)) or x < 0 or (x > 100) for x in scores)):
            raise ValueError('invalid scores')
        average = round(sum(scores) / len(scores), 1)
        if (department is None or employee['department'] == department) and average >= min_score:
            rows.append((average, employee))
    rows.sort(key=lambda item: (-item[0], item[1]['employee_id']))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    path = tempfile.mktemp(prefix='onboarding_', suffix='.csv')
    try:
        with open(path, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\r\n')
            writer.writerow(['employee_id', 'name', 'department', 'start_date', 'average_score'])
            for average, employee in selected:
                writer.writerow([employee['employee_id'], employee['name'], employee['department'], employee['start_date'], f'{average:.1f}'])
        with open(path, 'r', newline='', encoding='utf-8') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

