    return result[:limit]

def resolve_reports(reports: list[dict], decisions: list[dict], requester: dict) -> list[dict]:
    by_id = {r['id']: r for r in reports}
    seen = set()
    for d in decisions:
        if not isinstance(d, dict) or set(d) != {'report_id', 'status'} or d['status'] not in {'reviewed', 'resolved'} or (d['report_id'] in seen) or (d['report_id'] not in by_id):
