import hashlib
import os

def register_donor(email: str, password: str, amount: int) -> dict:
    if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
        raise ValueError('amount must be a positive integer')
    normalized_email = email.strip().lower()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    credential = salt.hex() + '$' + digest.hex()
    return {'email': normalized_email, 'amount': amount, 'credential': credential}

def verify_donor(record: dict, password: str) -> bool:
    credential = record.get('credential')
    if not isinstance(credential, str) or '$' not in credential:
        return False
    salt_text, digest_text = credential.split('$', 1)
    try:
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    if not salt or not expected:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return actual == expected

