import hashlib
import hmac
import json
import pytest


def make_payload(applications):
    return json.dumps({"applications": applications}, separators=(",", ":")).encode()


def sign(payload, secret=b"housing-secret"):
    return "sha256=" + hmac.new(secret, payload, hashlib.sha256).hexdigest()


def app(identifier, campus, rent, bedrooms, submitted, status="pending"):
    return {"id": identifier, "campus": campus, "monthly_rent": rent, "bedrooms": bedrooms, "submitted": submitted, "status": status}


def test_filters_sorts_and_formats_applications():
    payload = make_payload([app("a3", "North", 900, 2, "2025-01-03T09:00:00"), app("a1", "South", 800.456, 1, "2025-01-02", "approved"), app("a2", "South", 800.456, 1, "2025-01-01"), app("a4", "North", 700, 0, "2025-01-05")])
    assert process_housing_webhook(payload, sign(payload)) == {"total": 3, "page": 1, "page_size": 10, "pages": 1, "campuses": {"North": 2, "South": 1}, "applications": [{"id": "a4", "campus": "North", "monthly_rent": 700.0, "bedrooms": 0, "submitted": "2025-01-05"}, {"id": "a2", "campus": "South", "monthly_rent": 800.46, "bedrooms": 1, "submitted": "2025-01-01"}, {"id": "a3", "campus": "North", "monthly_rent": 900.0, "bedrooms": 2, "submitted": "2025-01-03T09:00:00"}]}


def test_pagination_and_tie_breaking():
    payload = make_payload([app("b", "Z", 500, 1, "2025-02-01"), app("a", "Z", 500, 1, "2025-02-01"), app("c", "A", 600, 2, "2025-01-01")])
    assert process_housing_webhook(payload, sign(payload), 1, 2)["applications"][0]["id"] == "a"
    result = process_housing_webhook(payload, sign(payload), 2, 2)
    assert result["pages"] == 2 and result["applications"][0]["id"] == "c"


def test_empty_input_and_out_of_range_page():
    payload = make_payload([])
    result = process_housing_webhook(payload, sign(payload), 3, 4)
    assert result["total"] == 0 and result["pages"] == 0 and result["applications"] == [] and result["campuses"] == {}


def test_bad_signature_is_rejected():
    payload = make_payload([])
    with pytest.raises(PermissionError): process_housing_webhook(payload, "sha256=" + "0" * 64)
    with pytest.raises(PermissionError): process_housing_webhook(payload, "wrong")


