    with pytest.raises(ValueError): process_housing_webhook(payload, sign(payload))


def test_duplicate_ids_and_invalid_pagination():
    payload = make_payload([app("x", "North", 400, 1, "2025-01-01"), app("x", "South", 500, 2, "2025-01-02")])
