        with pytest.raises(ValueError): process_housing_webhook(empty, sign(empty), page, size)


def test_signature_covers_exact_payload_bytes():
    payload = make_payload([app("x", "North", 450, 1, "2025-03-01")])
    with pytest.raises(PermissionError): process_housing_webhook(payload + b" ", sign(payload))


