import hashlib
import hmac
import json
import math
from datetime import datetime

def process_housing_webhook(payload: bytes, signature: str, secret: bytes=b'housing-secret', page: int=1, page_size: int=10) -> dict:
    if isinstance(secret, int):
        page, page_size, secret = (secret, page, b'housing-secret')
    if not isinstance(signature, str) or not signature.startswith('sha256=') or len(signature) != 71:
        raise PermissionError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise PermissionError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise PermissionError('invalid signature')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('applications'), list):
        raise ValueError('invalid payload')
    seen = set()
    selected = []
    for record in data['applications']:
        if not isinstance(record, dict):
            raise ValueError('invalid application')
        required = ('id', 'campus', 'monthly_rent', 'bedrooms', 'submitted', 'status')
        if any((key not in record for key in required)):
            raise ValueError('invalid application')
        identifier, campus, rent = (record['id'], record['campus'], record['monthly_rent'])
        bedrooms, submitted = (record['bedrooms'], record['submitted'])
        if not isinstance(identifier, str) or not identifier or identifier in seen or (not isinstance(campus, str)) or (not campus):
            raise ValueError('invalid application')
        if isinstance(rent, bool) or not isinstance(rent, (int, float)) or (not math.isfinite(rent)) or (rent <= 0):
            raise ValueError('invalid application')
        if isinstance(bedrooms, bool) or not isinstance(bedrooms, int) or (not 0 <= bedrooms <= 10) or (not isinstance(submitted, str)):
            raise ValueError('invalid application')
        try:
            datetime.fromisoformat(submitted)
        except ValueError as exc:
            raise ValueError('invalid application') from exc
        seen.add(identifier)
        if record['status'] == 'pending':
            selected.append({'id': identifier, 'campus': campus, 'monthly_rent': round(rent, 2), 'bedrooms': bedrooms, 'submitted': submitted})
    selected.sort(key=lambda x: (x['monthly_rent'], x['submitted'], x['id']))
    counts = {}
