    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    return parsed.replace(tzinfo=datetime.timezone.utc)

def _validated(records):
    result = []
    for item in records:
        if not isinstance(item, dict) or set(item) - {'sensor', 'timestamp', 'value', 'status'} or (not {'sensor', 'timestamp', 'value'} <= set(item)):
            raise ValueError('invalid record')
        sensor = item['sensor']
        value = item['value']
        status = item.get('status', 'ok')
        if not isinstance(sensor, str) or not sensor or (not isinstance(status, str)) or isinstance(value, bool) or (not isinstance(value, (int, float))) or (not math.isfinite(value)):
            raise ValueError('invalid record')
        stamp = _parse(item['timestamp'])
        result.append({'sensor': sensor, 'timestamp': stamp.strftime('%Y-%m-%dT%H:%M:%SZ'), 'value': value, 'status': status})
    return sorted(result, key=lambda x: (x['timestamp'], x['sensor'], x['value']))

def normalize_readings(records):
    return _validated(records)

