    output = []
    for (start, sensor), values in sorted(groups.items(), key=lambda x: (x[0][0], x[0][1])):
        output.append({'sensor': sensor, 'window_start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'count': len(values), 'average': sum(values) / len(values), 'minimum': min(values), 'maximum': max(values)})
    return output

def export_sensor_report(records, destination, window_minutes):
    rows = aggregate_readings(records, window_minutes)
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)), prefix='.report-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['sensor', 'window_start', 'count', 'average', 'minimum', 'maximum'])
            for row in rows:
