def create_consultation_payload(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise TypeError('state must be a dictionary')
    try:
        return json.dumps(state, ensure_ascii=False, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise TypeError('state contains unsupported data') from exc

def load_consultation_state(payload: bytes) -> dict:
    if not isinstance(payload, bytes):
        raise TypeError('payload must be bytes')
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid consultation payload') from exc
    if not isinstance(value, dict):
        raise ValueError('payload must contain a dictionary')
    return value

