    if len(set(requested_zones)) != len(requested_zones):
        raise ValueError('duplicate zones')
    selected = {}
    for zone in requested_zones:
        if zone not in zone_rates:
            raise ValueError('unknown zone')
        rate = zone_rates[zone]
        if isinstance(rate, bool) or not isinstance(rate, (int, float)) or (not math.isfinite(rate)) or (rate <= 0):
            raise ValueError('invalid rate')
        selected[zone] = rate
    zones = sorted(selected)
    total = round(sum((selected[z] for z in zones)) * duration_days, 2)
    data = {'permit_id': permit_id, 'applicant': applicant.strip(), 'zones': zones, 'days': duration_days, 'daily_rates': {z: selected[z] for z in zones}, 'total_fee': total}
