    target = (base / (permit_id + '.json')).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('permit path is outside base directory')
    with open(target, 'w', encoding='utf-8') as handle:
        json.dump(data, handle, indent=2, sort_keys=True)
