from datetime import date
from decimal import Decimal, InvalidOperation
from lxml import etree

def _date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _root(text):
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        return etree.fromstring(text.encode(), parser)
    except (etree.XMLSyntaxError, UnicodeError):
        raise ValueError('invalid XML')

def parse_enrollments(xml_text: str) -> list[dict]:
    root = _root(xml_text)
    if root.tag != 'enrollment_period' or len(root) == 0:
        raise ValueError('invalid root')
    result = []
    seen_ids = set()
    for employee in root:
        if employee.tag != 'employee' or set(employee.attrib) != {'id', 'name'} or (not all(employee.attrib.values())):
            raise ValueError('invalid employee')
        eid, name = (employee.get('id'), employee.get('name'))
        if eid in seen_ids:
            raise ValueError('duplicate employee')
        seen_ids.add(eid)
        plans = set()
        if not len(employee):
            raise ValueError('missing election')
        for election in employee:
            if election.tag != 'election' or set(election.attrib) - {'plan', 'tier', 'premium', 'effective', 'end'} != set():
                raise ValueError('invalid election')
            if not all((election.get(k) for k in ('plan', 'tier', 'premium', 'effective'))):
                raise ValueError('missing attribute')
            plan, tier, premium_text, effective_text = (election.get(k) for k in ('plan', 'tier', 'premium', 'effective'))
            if plan in plans:
                raise ValueError('duplicate plan')
            plans.add(plan)
            try:
                premium = Decimal(premium_text)
            except InvalidOperation:
                raise ValueError('invalid premium')
            if premium < 0 or premium.as_tuple().exponent < -2:
                raise ValueError('invalid premium')
            effective = _date(effective_text)
            end_text = election.get('end')
            end = _date(end_text) if end_text is not None else None
            if end is not None and end < effective:
                raise ValueError('invalid range')
            result.append({'employee_id': eid, 'employee_name': name, 'plan': plan, 'tier': tier, 'premium': float(premium), 'effective': effective_text, 'end': end_text})
    result.sort(key=lambda x: (x['employee_id'], x['effective'], x['plan']))
    return result

def benefit_summary(xml_text: str, as_of: str) -> dict:
    target = _date(as_of)
    rows = parse_enrollments(xml_text)
    active = [r for r in rows if _date(r['effective']) <= target and (r['end'] is None or _date(r['end']) >= target)]
    plans = {}
    employees = set()
    for row in active:
        employees.add(row['employee_id'])
        item = plans.setdefault(row['plan'], {'count': 0, 'premium': Decimal('0')})
        item['count'] += 1
        item['premium'] += Decimal(str(row['premium']))
    by_plan = {k: {'count': plans[k]['count'], 'premium': round(float(plans[k]['premium']), 2)} for k in sorted(plans)}
    total = round(sum((v['premium'] for v in by_plan.values())), 2)
    return {'as_of': as_of, 'employees': sorted(employees), 'total_premium': total, 'by_plan': by_plan}

