            except ValueError:
                inside = False
            if not inside:
                raise ValueError('archive member is outside batch directory')
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            with archive.open(info) as source, open(destination, 'wb') as output:
                output.write(source.read())
            result.append(os.path.relpath(destination, target).replace(os.sep, '/'))
    return sorted(result)

