    if not text:
        raise ValueError('empty input')
    rows = list(csv.reader(io.StringIO(text, newline='')))
    expected = ['donor_id', 'blood_type', 'age', 'available', 'region']
    if not rows or rows[0] != expected:
        raise ValueError('invalid header')
    blood = {'O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+'}
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        donor, kind, age_text, available, region = row
        if not donor or donor in seen or kind not in blood or (available not in {'yes', 'no'}):
            raise ValueError('invalid record')
        try:
            age = int(age_text)
        except ValueError:
            raise ValueError('invalid age')
        if age < 18 or age > 70:
            raise ValueError('invalid age')
        seen.add(donor)
        result.append({'donor_id': donor, 'blood_type': kind, 'age': age, 'available': available == 'yes', 'region': region})
    return result

