    blood = {'O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+'}
    if recipient_blood not in blood:
        raise ValueError('invalid recipient blood type')
    recipient_base = recipient_blood.rstrip('+-')
    recipient_rh = recipient_blood[-1]
    allowed = {'O': {'O', 'A', 'B', 'AB'}, 'A': {'A', 'AB'}, 'B': {'B', 'AB'}, 'AB': {'AB'}}
    chosen = []
    for record in records:
        donor = str(record['blood_type'])
        donor_base, donor_rh = (donor.rstrip('+-'), donor[-1])
        compatible = donor_base in allowed and recipient_base in allowed[donor_base] and (donor_rh == '-' or recipient_rh == '+')
        if record['available'] and compatible:
            chosen.append((0 if record['region'] == region else 1, abs(int(record['age']) - 40), str(record['donor_id'])))
    chosen.sort()
    return [item[2] for item in chosen]

