import hashlib
import hmac
import json
import math

def summarize_alerts(payloads: list[str], secret: str, min_risk: float, page: int, page_size: int) -> dict:
    if not isinstance(secret, str):
        raise ValueError('invalid secret')
    if not isinstance(min_risk, (int, float)) or isinstance(min_risk, bool) or (not math.isfinite(min_risk)) or (not 0 <= min_risk <= 100):
        raise ValueError('invalid threshold')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    total_alerts = 0
    for raw in payloads:
        try:
            item = json.loads(raw)
        except Exception as exc:
            raise ValueError('invalid json') from exc
        if not isinstance(item, dict) or set(item) != {'sig', 'alert'} or (not isinstance(item['sig'], str)):
            raise ValueError('invalid envelope')
        a = item['alert']
        if not isinstance(a, dict) or set(a) != {'id', 'category', 'risk', 'timestamp'}:
            raise ValueError('invalid alert')
        if not isinstance(a['id'], str) or not a['id'] or (not isinstance(a['category'], str)) or (not a['category']):
            raise ValueError('invalid alert')
        if not isinstance(a['risk'], (int, float)) or isinstance(a['risk'], bool) or (not math.isfinite(a['risk'])) or (not 0 <= a['risk'] <= 100) or (not isinstance(a['timestamp'], str)):
            raise ValueError('invalid alert')
        encoded = json.dumps(a, sort_keys=True, separators=(',', ':')).encode()
        expected = hmac.new(secret.encode(), encoded, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(item['sig'], expected):
            continue
        if a['risk'] >= min_risk:
            g = groups.setdefault(a['category'], [0, 0.0])
            g[0] += 1
            g[1] += a['risk']
            total_alerts += 1
    ordered = sorted(groups.items(), key=lambda x: (-x[1][1], x[0]))
    result = [{'category': k, 'count': v[0], 'total_risk': round(v[1], 2)} for k, v in ordered]
    start = (page - 1) * page_size
    return {'groups': result[start:start + page_size], 'total_groups': len(result), 'total_alerts': total_alerts}

