import sqlite3
from datetime import date

def _parse(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid ISO date')

def renewal_report(conn: sqlite3.Connection, as_of: str, vendor: str | None=None, status: str | None=None, search: str | None=None, sort_by: str='renewal_date', descending: bool=False) -> list[dict]:
    origin = _parse(as_of)
    columns = {'renewal_date': 'renewal_date', 'days_until': 'renewal_date', 'vendor': 'vendor', 'annual_value': 'annual_value', 'id': 'id'}
    if sort_by not in columns:
        raise ValueError('invalid sort key')
    clauses = []
    params = []
    if vendor is not None:
        clauses.append('vendor = ?')
        params.append(vendor)
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    if search is not None:
        clauses.append('(lower(vendor) LIKE lower(?) OR lower(contract_name) LIKE lower(?))')
        params.extend([f'%{search}%', f'%{search}%'])
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    order = columns[sort_by]
    query = f'SELECT id, vendor, contract_name, renewal_date, annual_value, status FROM contracts{where} ORDER BY {order} {direction}, id ASC'
    rows = conn.execute(query, params).fetchall()
    result = []
    for row in rows:
        renewal = _parse(row['renewal_date'])
        days = (renewal - origin).days
        urgency = 'overdue' if days < 0 else 'due_soon' if days <= 30 else 'upcoming'
        result.append({'id': row['id'], 'vendor': row['vendor'], 'contract_name': row['contract_name'], 'renewal_date': row['renewal_date'], 'annual_value': row['annual_value'], 'status': row['status'], 'days_until': days, 'urgency': urgency})
    if sort_by == 'days_until':
        result.sort(key=lambda x: (x['days_until'], x['id']), reverse=descending)
        if descending:
            result.sort(key=lambda x: x['id'])
    return result

def mark_contract_renewed(conn: sqlite3.Connection, contract_id: int, renewed_date: str) -> bool:
    _parse(renewed_date)
    cur = conn.execute('UPDATE contracts SET status = ?, renewal_date = ? WHERE id = ?', ('renewed', renewed_date, contract_id))
    conn.commit()
    return cur.rowcount == 1

