import hashlib
import hmac
import json
from collections.abc import Mapping

def _validated(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    seen = set()
    output = []
    for record in records:
        if not isinstance(record, Mapping):
            raise ValueError('invalid record')
        reference = record.get('reference')
        amount = record.get('amount')
        fee = record.get('fee')
        shares = record.get('shares')
        if not isinstance(reference, str) or not reference or reference in seen:
            raise ValueError('invalid reference')
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            raise ValueError('invalid amount')
        if not isinstance(fee, int) or isinstance(fee, bool) or fee < 0 or (fee > amount):
            raise ValueError('invalid fee')
        if not isinstance(shares, list) or not shares:
            raise ValueError('invalid shares')
        combined = {}
        for share in shares:
            if not isinstance(share, Mapping):
                raise ValueError('invalid share')
            account = share.get('account')
            points = share.get('basis_points')
            if not isinstance(account, str) or not account:
                raise ValueError('invalid account')
            if not isinstance(points, int) or isinstance(points, bool) or points < 0:
                raise ValueError('invalid basis points')
            combined[account] = combined.get(account, 0) + points
        if sum(combined.values()) != 10000:
            raise ValueError('basis points must total 10000')
        seen.add(reference)
        output.append((amount - fee, combined))
    return output

def allocate_settlement(records):
    totals = {}
    for distributable, shares in _validated(records):
        floors = {}
        remainders = []
        assigned = 0
        for account, points in shares.items():
            numerator = distributable * points
            floors[account] = numerator // 10000
            assigned += floors[account]
            remainders.append((numerator % 10000, account))
        for account, value in floors.items():
            totals[account] = totals.get(account, 0) + value
        for _, account in sorted(remainders, key=lambda item: (-item[0], item[1]))[:distributable - assigned]:
            totals[account] = totals.get(account, 0) + 1
    return {account: totals[account] for account in sorted(totals)}

def build_settlement(records, config):
    if not isinstance(config, Mapping):
        raise ValueError('config must be a mapping')
    key = config.get('signing_key')
    if key is None:
        raise RuntimeError('missing signing key')
    allocations = allocate_settlement(records)
    payload = {'records': len(records), 'total_distributed': sum(allocations.values()), 'allocations': allocations}
    raw = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(str(key).encode(), raw, hashlib.sha256).hexdigest()
    return {**payload, 'signature': signature}

