import ast
import operator

def _evaluate(rule, values):
    try:
        tree = ast.parse(rule, mode='eval').body
    except (SyntaxError, TypeError):
        raise ValueError
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
    functions = {'min': min, 'max': max, 'round': round}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in values:
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = visit(node.values[0])
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = visit(item)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                if type(op) not in comparisons:
                    raise ValueError
                right = visit(right_node)
                if not comparisons[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
            if node.func.id == 'round' and len(node.args) not in (1, 2):
                raise ValueError
            return functions[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError
    try:
        return visit(tree)
    except ValueError:
        raise
    except (NameError, TypeError, AttributeError):
        raise ValueError

def select_coupons(coupons: list[dict], rule: str, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError
    selected = []
    for coupon in coupons:
        result = _evaluate(rule, {key: coupon[key] for key in ('discount', 'minimum', 'uses', 'active')})
        if not isinstance(result, bool):
            raise ValueError
        if result:
            selected.append(coupon)
    selected.sort(key=lambda item: (-item['discount'], item['code']))
    start = (page - 1) * page_size
    return {'total': len(selected), 'items': [item['code'] for item in selected[start:start + page_size]], 'savings': round(sum((item['discount'] for item in selected)), 2)}

