    return hmac.new(secret, payload.encode("utf-8"), hashlib.sha256).hexdigest()


def test_verify_signature_accepts_valid_and_rejects_invalid_values():
    payload = b'{"ok":true}'
    secret = b"key"
    good = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    assert verify_signature(payload, good, secret) is True
    assert verify_signature(payload, good[:-1] + "0", secret) is False
    assert verify_signature(payload, "not-a-signature", secret) is False
    assert verify_signature(payload, good.upper(), secret) is False


def test_parse_preserves_order_and_accepts_unicode():
    text = json.dumps({"donations": [
        {"id": "b", "amount": 4, "currency": "USD", "donor": "Zoë"},
        {"id": "a", "amount": 9, "currency": "EUR", "donor": "A"}
    ]}, ensure_ascii=False)
    result = parse_donations(text)
    assert [item["id"] for item in result] == ["b", "a"]
    assert result[0]["donor"] == "Zoë"


def test_parse_rejects_bad_json_and_container_shapes():
    for text in ["", "[]", "{}", '{"donations": {}}', '{"donations": null}']:
        with pytest.raises(ValueError):
            parse_donations(text)


def test_parse_rejects_invalid_donation_fields():
    base = {"id": "x", "amount": 2, "currency": "USD", "donor": "D"}
    cases = [
        {**base, "id": ""}, {**base, "donor": 3}, {**base, "amount": True},
        {**base, "amount": 0}, {**base, "amount": -1}, {**base, "currency": "usd"},
        {**base, "currency": "US"}, {**base, "currency": "US1"}, {**base, "currency": 4},
        ["not", "an", "object"]
    ]
    for donation in cases:
        with pytest.raises(ValueError):
            parse_donations(json.dumps({"donations": [donation]}))


def test_process_sorts_application_and_returns_sorted_currencies():
    payload = json.dumps({"donations": [
        {"id": "z", "amount": 5, "currency": "USD", "donor": "Z"},
        {"id": "a", "amount": 5, "currency": "EUR", "donor": "A"},
        {"id": "b", "amount": 2, "currency": "USD", "donor": "B"}
    ]})
    ledger = {"GBP": 10, "USD": 1}
    result = process_donations(payload, signed(payload, b"s"), b"s", ledger)
    assert ledger == {"GBP": 10, "USD": 8, "EUR": 5}
    assert list(result.items()) == [("EUR", 5), ("GBP", 10), ("USD", 8)]


def test_process_rejects_duplicate_ids_without_mutating_ledger():
    payload = json.dumps({"donations": [
        {"id": "x", "amount": 3, "currency": "USD", "donor": "A"},
        {"id": "x", "amount": 8, "currency": "EUR", "donor": "B"}
    ]})
    ledger = {"USD": 7}
    with pytest.raises(ValueError):
        process_donations(payload, signed(payload, b"s"), b"s", ledger)
    assert ledger == {"USD": 7}


def test_process_rejects_existing_id_without_mutating_ledger():
    payload = json.dumps({"donations": [{"id": "old", "amount": 4, "currency": "USD", "donor": "A"}]})
    ledger = {"old": 99, "USD": 2}
    with pytest.raises(ValueError):
        process_donations(payload, signed(payload, b"s"), b"s", ledger)
    assert ledger == {"old": 99, "USD": 2}


def test_process_invalid_signature_and_invalid_payload_do_not_change_ledger():
    payload = json.dumps({"donations": []})
    ledger = {"USD": 6}
    with pytest.raises(PermissionError):
        process_donations(payload, "0" * 64, b"s", ledger)
    assert ledger == {"USD": 6}
    with pytest.raises(PermissionError):
        process_donations("not json", "bad", b"s", ledger)
    assert ledger == {"USD": 6}


def test_empty_donation_batch_retains_existing_entries():
    payload = '{"donations": []}'
    ledger = {"JPY": 12, "AUD": 3}
    result = process_donations(payload, signed(payload, b"k"), b"k", ledger)
    assert result == {"AUD": 3, "JPY": 12}
