import hashlib
import hmac
import json
import re

def verify_signature(payload: bytes, signature: str, secret: bytes) -> bool:
    if not isinstance(signature, str) or re.fullmatch('[0-9a-f]{64}', signature) is None:
        return False
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def parse_donations(payload: str) -> list[dict]:
    try:
        document = json.loads(payload)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('donations'), list):
        raise ValueError('invalid donations container')
    result = []
    for item in document['donations']:
        if not isinstance(item, dict):
            raise ValueError('invalid donation')
        if not isinstance(item.get('id'), str) or not item['id']:
            raise ValueError('invalid id')
        if not isinstance(item.get('donor'), str) or not item['donor']:
            raise ValueError('invalid donor')
        if not isinstance(item.get('amount'), int) or isinstance(item['amount'], bool) or item['amount'] <= 0:
            raise ValueError('invalid amount')
        if not isinstance(item.get('currency'), str) or re.fullmatch('[A-Z]{3}', item['currency']) is None:
            raise ValueError('invalid currency')
        result.append(item)
    return result

def process_donations(payload: str, signature: str, secret: bytes, ledger: dict[str, int]) -> dict[str, int]:
    if not verify_signature(payload.encode('utf-8'), signature, secret):
        raise PermissionError('invalid signature')
    donations = parse_donations(payload)
    seen = set()
    for item in donations:
        if item['id'] in seen or item['id'] in ledger:
            raise ValueError('duplicate id')
        seen.add(item['id'])
    updated = dict(ledger)
    for item in sorted(donations, key=lambda x: (-x['amount'], x['id'])):
        updated[item['currency']] = updated.get(item['currency'], 0) + item['amount']
    ledger.clear()
    ledger.update(updated)
    return {key: updated[key] for key in sorted(updated)}

