import json
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _records(value):
    if not isinstance(value, list):
        raise ValueError('records must be a list')
    for record in value:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('component'), str) or not record['component']:
            raise ValueError('invalid component')
        if not isinstance(record.get('version'), str):
            raise ValueError('invalid version')
        if not isinstance(record.get('license'), str) or not record['license']:
            raise ValueError('invalid license')
        if isinstance(record.get('quantity'), bool) or not isinstance(record.get('quantity'), int) or record['quantity'] <= 0:
            raise ValueError('invalid quantity')
        if isinstance(record.get('unit_cost'), bool) or not isinstance(record.get('unit_cost'), (int, float)) or record['unit_cost'] < 0:
            raise ValueError('invalid unit cost')
    return value

def encode_bom(records: list[dict]) -> bytes:
    _records(records)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def summarize_bom(blob: bytes | str, page: int=1, page_size: int=20, min_total: float=0.0) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100) or isinstance(min_total, bool) or (not isinstance(min_total, (int, float))) or (min_total < 0):
        raise ValueError('invalid options')
    try:
        value = json.loads(blob.decode('utf-8') if isinstance(blob, bytes) else blob)
        records = _records(value)
    except Exception as exc:
        if isinstance(exc, ValueError) and str(exc) in ('invalid component', 'invalid version', 'invalid license', 'invalid quantity', 'invalid unit cost', 'records must be a list'):
            raise
        raise ValueError('invalid payload') from exc
    groups = {}
    for r in records:
        g = groups.setdefault(r['component'], {'quantity': 0, 'cost': Decimal('0'), 'licenses': set(), 'versions': set()})
        g['quantity'] += r['quantity']
        g['cost'] += Decimal(str(r['quantity'])) * Decimal(str(r['unit_cost']))
        g['licenses'].add(r['license'])
        g['versions'].add(r['version'])

    def money(x):
        return x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    rows = []
    threshold = Decimal(str(min_total))
    for name, g in groups.items():
        cost = money(g['cost'])
        if cost >= threshold:
            rows.append({'component': name, 'quantity': g['quantity'], 'total_cost': float(cost), 'licenses': sorted(g['licenses']), 'versions': sorted(g['versions']), '_cost': cost})
    rows.sort(key=lambda x: (-x['_cost'], x['component']))
    total = money(sum((x['_cost'] for x in rows), Decimal('0')))
    start = (page - 1) * page_size
    items = [{k: v for k, v in row.items() if k != '_cost'} for row in rows[start:start + page_size]]
    return {'total_components': len(rows), 'grand_total': float(total), 'page': page, 'page_size': page_size, 'items': items}

