import csv
import os
import tempfile

def export_sessions(sessions: list[dict[str, object]], destination: str) -> int:
    rows = []
    for session in sessions:
        player_id = session.get('player_id')
        if not isinstance(player_id, str) or not player_id:
            raise ValueError('player_id must be a non-empty string')
        if session.get('status') == 'active':
            rows.append((player_id, str(session['server']), str(session['started_at'])))
    rows.sort(key=lambda row: row[0])
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.session_export.', dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['player_id', 'server', 'started_at'])
            writer.writerows(rows)
        os.replace(temporary, destination)
        temporary = ''
    finally:
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
    return len(rows)

