import datetime
import json
import os

def build_schedule(posts: list[dict], start_date: str, days: int) -> list[dict]:
    try:
        start = datetime.date.fromisoformat(start_date)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if type(days) is not int or days <= 0:
        raise ValueError('invalid days')
    prepared = []
    for post in posts:
        if not isinstance(post, dict):
            raise ValueError('invalid post')
        required = ('id', 'platform', 'text', 'priority', 'created_at')
        if any((k not in post for k in required)):
            raise ValueError('invalid post')
        if not all((isinstance(post[k], str) for k in ('id', 'platform', 'text', 'created_at'))) or type(post['priority']) is not int:
            raise ValueError('invalid post')
        try:
            datetime.datetime.fromisoformat(post['created_at'])
            preferred = datetime.date.fromisoformat(post.get('preferred_date', start_date))
        except Exception as exc:
            raise ValueError('invalid post') from exc
        prepared.append((post, preferred))
    prepared.sort(key=lambda x: (-x[0]['priority'], x[1], x[0]['created_at'], x[0]['id']))
    slots = ('09:00', '13:00', '18:00')
    used = [[] for _ in range(days)]
    result = []
    for post, preferred in prepared:
        first = max(0, (preferred - start).days)
        chosen = None
        for offset in range(first, days):
            if len(used[offset]) < 3 and post['platform'] not in used[offset]:
                chosen = offset
                break
        if chosen is None:
            raise ValueError('schedule does not fit')
        used[chosen].append(post['platform'])
        item = {k: post[k] for k in ('id', 'platform', 'text', 'priority', 'created_at')}
        item['date'] = (start + datetime.timedelta(days=chosen)).isoformat()
        item['time'] = slots[len(used[chosen]) - 1]
        result.append(item)
    result.sort(key=lambda x: (x['date'], x['time']))
    return result

def export_schedule(schedule: list[dict], base_dir: str, filename: str) -> str:
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, filename))
    if os.path.commonpath((base, path)) != base:
        raise ValueError('invalid filename')
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as handle:
        json.dump(schedule, handle, indent=2, sort_keys=True)
        handle.write('\n')
    return path

def import_schedule(base_dir: str, filename: str) -> list[dict]:
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, filename))
    if os.path.commonpath((base, path)) != base:
        raise ValueError('invalid filename')
    with open(path, 'r', encoding='utf-8') as handle:
        value = json.load(handle)
    if not isinstance(value, list):
        raise ValueError('schedule must be a list')
    return value

