    records = []
    for sample in root.findall('sample'):
        required = ('id', 'collected')
        if any((name not in sample.attrib for name in required)):
            raise ValueError('incomplete sample')
        values = {}
        for name in ('parameter', 'value', 'unit'):
            child = sample.find(name)
            if child is None:
                raise ValueError('incomplete sample')
            values[name] = ''.join(child.itertext()).strip()
        records.append({'id': sample.attrib['id'], 'collected': sample.attrib['collected'], **values})
    records.sort(key=lambda item: (item['collected'], item['id']))
    return records

