from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from html import escape

def render_reconciliation(records: list[dict], page: int=1, per_page: int=10, title: str='Invoice Reconciliation') -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('invalid per_page')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        for key in ('invoice', 'customer', 'amount', 'paid'):
            if key not in record:
                raise ValueError('invalid record')
        if not isinstance(record['invoice'], str) or not record['invoice']:
            raise ValueError('invalid invoice')
        if not isinstance(record['customer'], str) or not record['customer']:
            raise ValueError('invalid customer')
        if not isinstance(record['paid'], bool):
            raise ValueError('invalid paid value')
        try:
            amount = Decimal(str(record['amount']))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid amount')
        customer = record['customer']
        if customer not in groups:
            groups[customer] = [0, Decimal('0'), Decimal('0')]
        groups[customer][0] += 1
        groups[customer][1] += amount
        if record['paid']:
            groups[customer][2] += amount
    rows_data = []
    for customer, (count, invoiced, paid) in groups.items():
        rows_data.append((customer, count, invoiced, paid, invoiced - paid))
    rows_data.sort(key=lambda x: (-x[4], x[0]))
    total_invoiced = sum((x[2] for x in rows_data), Decimal('0'))
    total_paid = sum((x[3] for x in rows_data), Decimal('0'))
    total_outstanding = total_invoiced - total_paid
    start = (page - 1) * per_page
    selected = rows_data[start:start + per_page]

    def money(value):
        return format(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')
    rows = ''.join((f'<tr><td>{escape(customer, quote=True)}</td><td>{count}</td><td>{money(invoiced)}</td><td>{money(paid)}</td><td>{money(outstanding)}</td></tr>' for customer, count, invoiced, paid, outstanding in selected))
    return f'<div class="reconciliation"><h1>{escape(title, quote=True)}</h1><table><thead><tr><th>Customer</th><th>Invoices</th><th>Invoiced</th><th>Paid</th><th>Outstanding</th></tr></thead><tbody>{rows}</tbody></table><p class="summary">Total invoiced: {money(total_invoiced)} | Total paid: {money(total_paid)} | Total outstanding: {money(total_outstanding)}</p></div>'

