    except Exception as exc:
        raise ValueError('invalid XML') from exc

def _clock(value):
    try:
        return datetime.strptime(value, '%H:%M')
    except ValueError as exc:
        raise ValueError('invalid time') from exc

def parse_consultations(xml_text: str) -> list[dict]:
    root = _read(xml_text)
    if root.tag != 'consultation_feed':
        raise ValueError('invalid root')
    result = []
    seen = set()
    required = ('id', 'patient', 'clinician', 'start', 'duration', 'priority')
    for node in root:
        if node.tag != 'consultation':
            raise ValueError('invalid child')
        values = {key: node.get(key) for key in required}
        if any((value is None or not value.strip() for value in values.values())):
            raise ValueError('missing attribute')
        if values['id'] in seen:
            raise ValueError('duplicate id')
        try:
            start = datetime.strptime(values['start'], '%Y-%m-%dT%H:%M')
            duration = int(values['duration'])
            priority = int(values['priority'])
        except ValueError as exc:
            raise ValueError('invalid value') from exc
        if not 15 <= duration <= 240 or not 0 <= priority <= 9:
            raise ValueError('out of range')
        note_node = node.find('note')
        note = '' if note_node is None else ' '.join(''.join(note_node.itertext()).split())
        result.append({'id': values['id'], 'patient': values['patient'], 'clinician': values['clinician'], 'start': values['start'], 'duration': duration, 'priority': priority, 'note': note})
        seen.add(values['id'])
    return result

