    begin, finish = (_clock(window_start), _clock(window_end))
    if begin >= finish:
        raise ValueError('invalid window')
    records = parse_consultations(xml_text)
    selected = {}
    for item in sorted(records, key=lambda x: (-x['priority'], x['start'], x['id'])):
        start = datetime.strptime(item['start'], '%Y-%m-%dT%H:%M')
        end = start + timedelta(minutes=item['duration'])
        if start.time() < begin.time() or end.time() > finish.time():
            continue
        existing = selected.setdefault(item['clinician'], [])
