import hmac
import os

def hash_password(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_password(stored: str, secret: str) -> bool:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    try:
        salt_hex, digest_hex = stored.split('$', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, ValueError):
        return False

def plan_missions(missions: list[dict], horizon: int) -> list[dict]:
    if not isinstance(horizon, int) or isinstance(horizon, bool) or horizon < 0:
