        actual_end = actual_start + duration
        if end <= horizon and actual_end <= end and (remaining >= battery):
            remaining -= battery
            result.append({'id': ident, 'start': actual_start, 'end': actual_end, 'battery_after': remaining})
            clock = actual_end
    return result

