    show = next((s for s in catalog['shows'] if s['id'] == show_id), None)
    if show is None:
        raise ValueError('unknown show')
    _episode(episode)
    if any((e['number'] == episode['number'] for e in show['episodes'])):
        raise ValueError('duplicate episode')
    if show['episodes'] and _time(episode['release_at']) < max((_time(e['release_at']) for e in show['episodes'])):
        raise ValueError('release order')
