import os
import subprocess

def campaign_attribution(log_path: str, campaign: str) -> dict[str, int]:
    if not campaign:
        raise ValueError('campaign must not be empty')
    if not os.path.isfile(log_path):
        raise FileNotFoundError(log_path)
    result = subprocess.run(['grep', '-F', '--', campaign, log_path], capture_output=True, text=True, check=False)
    totals: dict[str, int] = {}
    for line in result.stdout.splitlines():
        fields = line.split('|')
        if len(fields) != 3 or fields[0] != campaign:
            continue
        try:
            conversions = int(fields[2])
        except ValueError:
            continue
        totals[fields[1]] = totals.get(fields[1], 0) + conversions
    return totals

