import json
import math

def _valid_records(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict) or set(record) != {'material', 'weight_kg', 'contamination_pct'}:
            raise ValueError('invalid record')
        if not isinstance(record['material'], str) or not record['material']:
            raise ValueError('invalid material')
        for key in ('weight_kg', 'contamination_pct'):
            value = record[key]
            if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)):
                raise ValueError('invalid number')
        if record['weight_kg'] < 0 or not 0 <= record['contamination_pct'] <= 100:
            raise ValueError('invalid range')

def encode_batch(records: list[dict]) -> bytes:
    _valid_records(records)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def summarize_batch(blob: bytes, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        records = json.loads(blob.decode('utf-8'))
        _valid_records(records)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    groups = {}
    rejected = 0
    total = 0.0
    for record in records:
        if record['contamination_pct'] > 5:
            rejected += 1
            continue
        material = record['material']
        group = groups.setdefault(material, [0.0, 0.0, 0])
        group[0] += record['weight_kg']
        group[1] += record['contamination_pct']
        group[2] += 1
        total += record['weight_kg']
    items = [{'material': name, 'weight_kg': round(values[0], 2), 'average_contamination_pct': round(values[1] / values[2], 2), 'loads': values[2]} for name, values in groups.items()]
    items.sort(key=lambda item: (-item['weight_kg'], item['material']))
    start = (page - 1) * page_size
    return {'total_accepted_kg': round(total, 2), 'rejected_count': rejected, 'materials': items[start:start + page_size], 'page': page, 'page_size': page_size, 'total_materials': len(items)}

