import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin:
        raise ValueError('pin must be a non-empty string')
    salt = os.urandom(16)
    rounds = 100000
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
    return f'{rounds}${salt.hex()}${value.hex()}'

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(stored, str)):
        return False
    try:
        rounds_text, salt_text, value_text = stored.split('$')
        rounds = int(rounds_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
    except (ValueError, TypeError):
        return False
    if rounds <= 0 or not salt or (not expected):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
    return hmac.compare_digest(actual, expected)

def summarize_stations(records: list[dict], page: int, page_size: int) -> list[dict]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
