        bikes = record.get('bikes')
        capacity = record.get('capacity')
        if not isinstance(station, str) or not station or (not isinstance(bikes, int)) or isinstance(bikes, bool) or (bikes < 0) or (not isinstance(capacity, int)) or isinstance(capacity, bool) or (capacity <= 0) or (bikes > capacity):
            raise ValueError('invalid record')
        if station not in grouped:
            grouped[station] = [0, 0]
        grouped[station][0] += bikes
        grouped[station][1] += capacity
    result = []
    for station, (bikes, capacity) in grouped.items():
        result.append({'station': station, 'bikes': bikes, 'capacity': capacity, 'occupancy': round(bikes / capacity, 2)})
    result.sort(key=lambda item: (-item['occupancy'], item['station']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

