def fetch_open_tenders(origin: str, destination: str, min_weight_kg: float=0, page: int=1, page_size: int=50) -> list[dict]:
    if not isinstance(origin, str) or not origin or (not isinstance(destination, str)) or (not destination):
        raise ValueError('locations must be non-empty strings')
    if isinstance(min_weight_kg, bool) or not isinstance(min_weight_kg, (int, float)) or min_weight_kg < 0:
        raise ValueError('invalid weight')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    response = requests.get('https://api.freight.example/v1/tenders', params={'origin': origin, 'destination': destination, 'min_weight_kg': min_weight_kg, 'page': page, 'page_size': page_size}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('tender service returned an error')
    matches = []
    for item in response.json().get('loads', []):
        if item.get('status') == 'OPEN' and item.get('origin') == origin and (item.get('destination') == destination) and (item.get('weight_kg') >= min_weight_kg):
            matches.append({key: item[key] for key in ('id', 'carrier', 'pickup_time', 'weight_kg', 'rate_usd')})
    matches.sort(key=lambda item: (item['pickup_time'], item['id']))
    start = (page - 1) * page_size
    return matches[start:start + page_size]

