def reservation_report(path: str, month: int, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(month, int) or isinstance(month, bool) or (not 1 <= month <= 12):
        raise ValueError('invalid month')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    result = subprocess.run(['sort', '-t,', '-k2,2', '-k1,1', '--', path], check=True, capture_output=True, text=True)
    grouped = {}
    for line in result.stdout.splitlines():
        fields = line.split(',')
        if len(fields) != 5:
            raise ValueError('malformed record')
        date_text, campsite, guests_text, nights_text, rate_text = fields
        try:
            date = datetime.datetime.strptime(date_text, '%Y-%m-%d').date()
            if date.strftime('%Y-%m-%d') != date_text:
                raise ValueError
            guests = int(guests_text)
            nights = int(nights_text)
            rate = int(rate_text)
        except ValueError:
            raise ValueError('malformed record')
        if not campsite or guests < 1 or nights < 1 or (rate < 1):
            raise ValueError('malformed record')
        if date.month != month:
            continue
