def build_closing_dashboard(requester: dict, tasks: list[dict], page: int=1, page_size: int=3) -> dict:
    if not isinstance(requester, dict):
        raise TypeError('requester must be a dictionary')
    if not isinstance(tasks, list):
        raise TypeError('tasks must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not all((key in requester for key in ('id', 'tenant_id', 'roles'))):
        raise ValueError('invalid requester')
    allowed = []
    for task in tasks:
        if not all((key in task for key in ('id', 'property_id', 'tenant_id', 'owner_id', 'status', 'due_day'))):
            raise ValueError('invalid task')
        if task['status'] not in ('pending', 'in_progress', 'completed'):
            raise ValueError('invalid status')
        if not isinstance(task['due_day'], int) or isinstance(task['due_day'], bool):
            raise ValueError('invalid due day')
        if task['tenant_id'] == requester['tenant_id'] and (task['owner_id'] == requester['id'] or any((role in requester['roles'] for role in ('closing_manager', 'admin')))):
            allowed.append(task)
    ordered = sorted(allowed, key=lambda task: (task['due_day'], task['id']))
    counts = {'pending': 0, 'in_progress': 0, 'completed': 0}
    for task in ordered:
        counts[task['status']] += 1
    total = len(ordered)
    completed = counts['completed']
    pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    items = [{'id': task['id'], 'property_id': task['property_id'], 'status': task['status'], 'due_day': task['due_day']} for task in ordered[start:start + page_size]]
    return {'total': total, 'completed': completed, 'completion_percent': round(completed * 1000 / total) / 10 if total else 0.0, 'by_status': counts, 'pages': pages, 'items': items}

