def make_body(properties):
    return json.dumps({"properties": properties}, separators=(",", ":")).encode()


def signed(body, key=b"title-key"):
    return hmac.new(key, body, hashlib.sha256).hexdigest()


def test_groups_filters_sorts_and_rounds():
    body = make_body([
        {"parcel_id": "P2", "county": "Beta", "liens": [{"amount": "100.005", "status": "open"}, {"amount": 9, "status": "closed"}]},
        {"parcel_id": "P1", "county": "Alpha", "liens": [{"amount": "60.00", "status": "open"}, {"amount": "2.345", "status": "open"}]},
        {"parcel_id": "P3", "county": "Beta", "liens": [{"amount": "20.00", "status": "open"}]},
    ])
    result = summarize_title_search(body, signed(body), b"title-key")
    assert result == {
        "page": 1,
        "page_size": 2,
        "total": 2,
        "results": [
            {"county": "Beta", "open_lien_count": 2, "total_open_amount": 120.01, "parcel_ids": ["P2", "P3"]},
