import hashlib
import hmac
import json
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_title_search(body: bytes, signature: str, signing_key: bytes, page: int=1, page_size: int=2) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid paging')
    try:
        supplied = signature.encode('ascii')
    except (AttributeError, UnicodeEncodeError):
        raise ValueError('invalid signature')
    expected = hmac.new(signing_key, body, hashlib.sha256).hexdigest().encode('ascii')
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    try:
        document = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid document')
    if not isinstance(document, dict) or not isinstance(document.get('properties'), list):
        raise ValueError('invalid document')
    groups = {}
    try:
        for prop in document['properties']:
            if not isinstance(prop, dict) or not isinstance(prop.get('parcel_id'), str) or (not isinstance(prop.get('county'), str)) or (not isinstance(prop.get('liens'), list)):
                raise ValueError('invalid property')
            for lien in prop['liens']:
                if not isinstance(lien, dict) or not isinstance(lien.get('status'), str):
                    raise ValueError('invalid lien')
                if lien['status'] == 'open':
                    amount = Decimal(str(lien['amount'])).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
                    group = groups.setdefault(prop['county'], [0, Decimal('0'), set()])
                    group[0] += 1
                    group[1] += amount
                    group[2].add(prop['parcel_id'])
    except (KeyError, TypeError, InvalidOperation, ValueError):
        raise ValueError('invalid document')
    rows = [{'county': county, 'open_lien_count': data[0], 'total_open_amount': float(data[1].quantize(Decimal('0.01'))), 'parcel_ids': sorted(data[2])} for county, data in groups.items()]
    rows.sort(key=lambda row: (-row['total_open_amount'], row['county']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total': len(rows), 'results': rows[start:start + page_size]}

