import os
from pathlib import Path

def save_grade_note(base_dir: str, relative_name: str, note: str) -> str:
    if not relative_name or os.path.isabs(relative_name):
        raise ValueError('invalid note name')
    if not os.path.isdir(base_dir):
        raise FileNotFoundError(base_dir)
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid note name')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(note, encoding='utf-8')
    return str(target)

import xml.etree.ElementTree as ET

def parse_fare_feed(xml_text: str) -> list[tuple[str, str, int]]:
    try:
        root = ET.fromstring(xml_text)
        if root.tag != 'fares':
            raise ValueError
        fares = []
        for element in root.findall('fare'):
            route = element.attrib['route']
            zone = element.attrib['zone']
            cents = int(element.attrib['cents'])
            if cents <= 0:
                raise ValueError
            fares.append((route, zone, cents))
        return sorted(fares, key=lambda item: (item[0], item[1]))
    except (ET.ParseError, KeyError, TypeError, ValueError) as exc:
        raise ValueError('invalid fare feed') from exc

