import sqlite3
from datetime import date

def initialize_hive_db(conn: sqlite3.Connection) -> None:
    conn.execute('PRAGMA foreign_keys = ON')
    conn.execute('CREATE TABLE IF NOT EXISTS hives (hive_id TEXT PRIMARY KEY)')
    conn.execute('CREATE TABLE IF NOT EXISTS inspections (id INTEGER PRIMARY KEY AUTOINCREMENT, hive_id TEXT NOT NULL REFERENCES hives(hive_id), inspected_on TEXT NOT NULL, brood_frames INTEGER NOT NULL, honey_kg REAL NOT NULL, notes TEXT NOT NULL)')
    conn.commit()

def add_inspection(conn: sqlite3.Connection, hive_id: str, inspected_on: str, brood_frames: int, honey_kg: float, notes: str='') -> int:
    try:
        if date.fromisoformat(inspected_on).isoformat() != inspected_on:
            raise ValueError
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if type(brood_frames) is not int or not 0 <= brood_frames <= 20 or honey_kg < 0:
        raise ValueError('invalid measurement')
    conn.execute('INSERT OR IGNORE INTO hives(hive_id) VALUES (?)', (hive_id,))
    cur = conn.execute('INSERT INTO inspections(hive_id, inspected_on, brood_frames, honey_kg, notes) VALUES (?, ?, ?, ?, ?)', (hive_id, inspected_on, brood_frames, honey_kg, notes))
    conn.commit()
    return cur.lastrowid

def list_inspections(conn: sqlite3.Connection, hive_id: str | None=None, since: str | None=None, until: str | None=None, search: str='', sort: str='date', descending: bool=False) -> list[dict]:
    columns = {'date': 'inspected_on', 'brood': 'brood_frames', 'honey': 'honey_kg', 'id': 'id'}
    if sort not in columns:
        raise ValueError('invalid sort')
    clauses = []
    params = []
    if hive_id is not None:
        clauses.append('hive_id = ?')
        params.append(hive_id)
    if since is not None:
        clauses.append('inspected_on >= ?')
        params.append(since)
    if until is not None:
        clauses.append('inspected_on <= ?')
        params.append(until)
    if search:
        clauses.append('LOWER(notes) LIKE LOWER(?)')
        params.append('%' + search + '%')
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    sql = 'SELECT id, hive_id, inspected_on, brood_frames, honey_kg, notes FROM inspections' + where + ' ORDER BY ' + columns[sort] + ' ' + direction + ', id ASC'
    rows = conn.execute(sql, params).fetchall()
    keys = ('id', 'hive_id', 'inspected_on', 'brood_frames', 'honey_kg', 'notes')
    return [dict(zip(keys, row)) for row in rows]

def summarize_hive(conn: sqlite3.Connection, hive_id: str) -> dict:
    exists = conn.execute('SELECT 1 FROM hives WHERE hive_id = ?', (hive_id,)).fetchone()
    if exists is None:
        raise KeyError(hive_id)
    rows = conn.execute('SELECT inspected_on, brood_frames, honey_kg FROM inspections WHERE hive_id = ? ORDER BY inspected_on, id', (hive_id,)).fetchall()
    if not rows:
        return {'inspections': 0, 'total_honey_kg': 0.0, 'average_brood_frames': None, 'latest_date': None, 'brood_trend': None}
    first, last = (rows[0][1], rows[-1][1])
    trend = 'up' if last > first else 'down' if last < first else 'steady'
    return {'inspections': len(rows), 'total_honey_kg': round(sum((r[2] for r in rows)), 2), 'average_brood_frames': round(sum((r[1] for r in rows)) / len(rows), 2), 'latest_date': rows[-1][0], 'brood_trend': trend}

