import html
import re

def _minutes(value):
    if not isinstance(value, str) or re.fullmatch('(?:[01]\\d|2[0-3]):[0-5]\\d', value) is None:
        raise ValueError('invalid time')
    hour, minute = value.split(':')
    return int(hour) * 60 + int(minute)

def _validate(record):
    if not isinstance(record, dict):
        raise ValueError('invalid record')
    needed = ('unit', 'officer', 'start', 'end', 'calls')
    if any((key not in record for key in needed)):
        raise ValueError('missing field')
    if not isinstance(record['unit'], str) or not record['unit']:
        raise ValueError('invalid unit')
    if not isinstance(record['officer'], str) or not record['officer']:
        raise ValueError('invalid officer')
    start = _minutes(record['start'])
    end = _minutes(record['end'])
    if not isinstance(record['calls'], int) or isinstance(record['calls'], bool) or record['calls'] < 0:
        raise ValueError('invalid calls')
    duration = end - start
    if duration <= 0:
        duration += 1440
    return (record['unit'], record['officer'], record['start'], record['end'], duration, record['calls'], start)

def render_patrol_report(records: list[dict], report_date: str) -> str:
    if not isinstance(records, list) or not isinstance(report_date, str) or (not report_date):
        raise ValueError('invalid arguments')
    rows = [_validate(record) for record in records]
    rows.sort(key=lambda row: (row[0], row[6], row[1], row[5]))
