        lines.append('<tr><td>' + esc(unit) + '</td><td>' + esc(officer) + '</td><td>' + esc(start) + '</td><td>' + esc(end) + '</td><td>' + str(duration) + '</td><td>' + str(calls) + '</td></tr>')
    lines.extend(['</tbody>', '<tfoot><tr><td colspan="4">Totals</td><td>' + str(total_minutes) + '</td><td>' + str(total_calls) + '</td></tr></tfoot>', '</table>', '</section>'])
    return '\n'.join(lines)

