from lxml import etree

def parse_impact_report(xml_text: str) -> dict:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeError, AttributeError):
        raise ValueError('invalid XML')
    if root.tag != 'report':
        raise ValueError('invalid root')
    organization = root.get('organization')
    period = root.get('period')
    if not organization or not period:
        raise ValueError('missing report attribute')
    metrics = []
    for child in root:
        if child.tag != 'metric':
            raise ValueError('invalid child')
        name = child.get('name')
        value = child.get('value')
        unit = child.get('unit')
        if not name or not value or (not unit):
            raise ValueError('missing metric attribute')
        try:
            number = float(value)
        except ValueError:
            raise ValueError('invalid metric value')
        note = ''
        for item in child:
            if item.tag != 'note':
                raise ValueError('invalid metric child')
            note = (item.text or '').strip()
        metrics.append({'name': name, 'value': number, 'unit': unit, 'note': note})
    return {'organization': organization, 'period': period, 'metrics': metrics}

