def parse_events(text: str) -> list[dict]:
    result = []
    actions = {'sealed', 'transferred', 'opened', 'returned'}
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
