import csv
import io
import math
import secrets
import string
from datetime import datetime, timedelta

def _time(value):
    value = value.strip()
    if value.endswith('Z'):
        value = value[:-1] + '+00:00'
    result = datetime.fromisoformat(value)
    if result.tzinfo is None or result.utcoffset() is None:
        raise ValueError('timezone required')
    return result

def parse_feed_log(text: str) -> list[dict]:
    out = []
    for number, row in enumerate(csv.reader(io.StringIO(text)), 1):
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 4:
            raise ValueError('bad row')
        animal, stamp, feed, amount = [x.strip() for x in row]
        if not animal or not feed:
            raise ValueError('empty field')
        try:
            moment = _time(stamp)
            kg = float(amount)
        except Exception as exc:
            raise ValueError('bad value') from exc
        if not math.isfinite(kg) or kg <= 0:
            raise ValueError('bad quantity')
        out.append({'animal': animal, 'time': moment, 'feed': feed, 'kg': kg})
    return out

def summarize_feed(records: list[dict], start: str, end: str, window_hours: int) -> list[dict]:
    try:
        first, last = (_time(start), _time(end))
    except Exception as exc:
        raise ValueError('bad range') from exc
    if not isinstance(window_hours, int) or isinstance(window_hours, bool) or window_hours <= 0 or 24 % window_hours:
        raise ValueError('bad window')
    if last <= first:
        raise ValueError('bad range')
    count = math.ceil((last - first).total_seconds() / (window_hours * 3600))
    buckets = [[] for _ in range(count)]
    width = window_hours * 3600
    for record in records:
        if set(record) != {'animal', 'time', 'feed', 'kg'} or not isinstance(record['time'], datetime):
            raise ValueError('bad record')
        if first <= record['time'] < last:
            index = int((record['time'] - first).total_seconds() // width)
            if index < count:
                buckets[index].append(record)
    result = []
    for index, items in enumerate(buckets):
        if not items:
            continue
        animals = {}
        for item in items:
            if not isinstance(item['animal'], str) or not isinstance(item['feed'], str):
                raise ValueError('bad record')
            entry = animals.setdefault(item['animal'], {'total_kg': 0.0, 'feeds': {}})
            entry['total_kg'] += float(item['kg'])
            entry['feeds'][item['feed']] = entry['feeds'].get(item['feed'], 0.0) + float(item['kg'])
        listed = []
        for animal, entry in animals.items():
            entry['feeds'] = dict(sorted(entry['feeds'].items()))
            listed.append({'animal': animal, **entry})
        listed.sort(key=lambda x: (-x['total_kg'], x['animal']))
        begin = first + timedelta(hours=index * window_hours)
        result.append({'start': begin, 'end': min(begin + timedelta(hours=window_hours), last), 'total_kg': sum((x['total_kg'] for x in listed)), 'animals': listed})
    return result

def make_restock_code(feedlot: str, day: str, length: int=12) -> str:
    if not isinstance(feedlot, str) or not feedlot.strip() or any((c not in string.ascii_letters + string.digits + '_-' for c in feedlot.strip())):
        raise ValueError('bad feedlot')
    try:
        datetime.strptime(day, '%Y-%m-%d')
    except Exception as exc:
        raise ValueError('bad date') from exc
    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 64):
        raise ValueError('bad length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ123456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return feedlot.strip() + ':' + day + ':' + code

