import hashlib
import hmac
import json

def verify_availability(payload: str, signature: str, secret: bytes) -> list[dict[str, object]]:
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        listings = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(listings, list):
        raise ValueError('invalid payload')
    for listing in listings:
        if not isinstance(listing, dict):
            raise ValueError('invalid listing')
        if not isinstance(listing.get('name'), str):
            raise ValueError('invalid listing')
        if isinstance(listing.get('price'), bool) or not isinstance(listing.get('price'), (int, float)):
            raise ValueError('invalid listing')
        if not isinstance(listing.get('available'), bool):
            raise ValueError('invalid listing')
    return sorted((listing for listing in listings if listing['available']), key=lambda listing: listing['price'])

