import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_password(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str):
        raise TypeError('arguments must be strings')
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def create_account(username: str, password: str) -> dict[str, str]:
    if not isinstance(username, str) or not isinstance(password, str):
        raise TypeError('arguments have invalid types')
    if not username.strip() or len(password) < 4:
        raise ValueError('invalid account data')
    return {'username': username, 'password_hash': hash_password(password)}

def summarize_translations(entries: list[dict], locale: str | None=None, page: int=1, page_size: int=20) -> dict:
    if not isinstance(entries, list) or not isinstance(locale, (str, type(None))) or (not isinstance(page, int)) or (not isinstance(page_size, int)):
        raise TypeError('invalid argument type')
    if page < 1 or page_size < 1:
        raise ValueError('invalid page')
    selected = []
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError('invalid entry')
        if not all((key in entry for key in ('job_id', 'locale', 'status', 'words'))):
            raise ValueError('invalid entry')
        if not isinstance(entry['job_id'], str) or not isinstance(entry['locale'], str) or (not entry['locale']) or (not isinstance(entry['status'], str)) or (not isinstance(entry['words'], int)) or isinstance(entry['words'], bool) or (entry['words'] < 0):
            raise ValueError('invalid entry')
        if entry['status'] == 'completed' and (locale is None or entry['locale'] == locale):
            selected.append({'job_id': entry['job_id'], 'locale': entry['locale'], 'words': entry['words']})
    selected.sort(key=lambda x: (x['locale'], x['job_id']))
    grouped = {}
    for item in selected:
        group = grouped.setdefault(item['locale'], {'locale': item['locale'], 'jobs': 0, 'words': 0})
        group['jobs'] += 1
        group['words'] += item['words']
    start = (page - 1) * page_size
    return {'total_jobs': len(selected), 'total_words': sum((x['words'] for x in selected)), 'by_locale': list(grouped.values()), 'items': selected[start:start + page_size]}

