import hashlib
import hmac
import json
import os

def parse_answer(raw: dict) -> dict:
    if not isinstance(raw, dict):
        raise ValueError('answer must be a mapping')
    if not isinstance(raw.get('question'), str) or not raw['question'].strip():
        raise ValueError('invalid question')
    if not isinstance(raw.get('value'), str) or not raw['value'].strip():
        raise ValueError('invalid value')
    weight = raw.get('weight')
    if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight <= 0:
        raise ValueError('invalid weight')
    return {'question': raw['question'].strip(), 'value': raw['value'].strip(), 'weight': weight}

def build_report(entries: list[dict], config: dict | None=None) -> dict:
    grouped = {}
    seen_jurors = set()
    for entry in entries:
        if not isinstance(entry, dict) or not isinstance(entry.get('juror'), str) or (not entry['juror'].strip()):
            raise ValueError('invalid juror')
        juror = entry['juror'].strip()
        if juror in seen_jurors:
            raise ValueError('duplicate juror')
        seen_jurors.add(juror)
        if not isinstance(entry.get('answers'), list):
            raise ValueError('invalid answers')
        seen_questions = set()
        for raw in entry['answers']:
            answer = parse_answer(raw)
            question = answer['question']
            if question in seen_questions:
                raise ValueError('duplicate question')
            seen_questions.add(question)
            try:
                number = float(answer['value'])
            except (TypeError, ValueError):
                raise ValueError('value must be numeric')
            if not 0 <= number <= 10:
                raise ValueError('value out of range')
            grouped.setdefault(question, []).append((answer['value'], number, answer['weight']))
    questions = []
    for question in sorted(grouped):
        values = grouped[question]
        counts = {}
        total = 0.0
        weights = 0.0
        for text, number, weight in values:
            counts[text] = counts.get(text, 0) + 1
            total += number * weight
            weights += weight
        questions.append({'question': question, 'responses': len(values), 'weighted_mean': round(total / weights, 2), 'values': [{'value': text, 'count': counts[text]} for text in sorted(counts)]})
    payload = {'questions': questions}
    token = config.get('signing_token') if config is not None else os.environ.get('JURY_SIGNING_TOKEN')
    if not isinstance(token, str) or not token:
        raise RuntimeError('missing signing token')
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()
    return {**payload, 'signature': hmac.new(token.encode(), encoded, hashlib.sha256).hexdigest()}

