def _split_escaped(s, sep):
    out, cur, escaped = ([], [], False)
    for ch in s:
        if escaped:
            if ch not in ('\\', '|'):
                raise ValueError('bad escape')
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == sep:
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('bad escape')
    out.append(''.join(cur))
    return out

def parse_availability(text):
    result = {}
    for raw in text.splitlines():
        if not raw.strip():
            continue
        parts = _split_escaped(raw, '|')
        if len(parts) != 2 or not parts[0].strip():
            raise ValueError('bad line')
