import json
from datetime import date

def build_diversion_state(events: list[dict]) -> dict:
    allowed = {'case_id', 'participant', 'program', 'date', 'event', 'priority'}
    kinds = {'intake', 'checkin', 'violation', 'completed'}
    cases = {}
    programs = set()
    for pos, item in enumerate(events):
        if not isinstance(item, dict) or set(item) != allowed:
            raise ValueError('invalid event')
        if any((not isinstance(item[k], str) for k in allowed - {'priority'})):
            raise ValueError('invalid event')
        if isinstance(item['priority'], bool) or not isinstance(item['priority'], int):
            raise ValueError('invalid priority')
        if item['event'] not in kinds:
            raise ValueError('invalid event kind')
        try:
            parsed = date.fromisoformat(item['date'])
        except (ValueError, TypeError):
            raise ValueError('invalid date')
        if parsed.isoformat() != item['date']:
            raise ValueError('invalid date')
        cid = item['case_id']
        programs.add(item['program'])
        if cid in cases and (cases[cid]['participant'] != item['participant'] or cases[cid]['program'] != item['program']):
            raise ValueError('inconsistent case')
        if cid not in cases:
            cases[cid] = {'participant': item['participant'], 'program': item['program'], 'events': []}
        cases[cid]['events'].append((item['date'], pos, item['event'], item['priority']))
    result = []
    totals = {p: 0 for p in sorted(programs)}
    for cid, data in cases.items():
        latest = max(data['events'], key=lambda x: (x[0], x[1]))
        active = latest[2] != 'completed'
        result.append({'case_id': cid, 'participant': data['participant'], 'program': data['program'], 'status': latest[2], 'last_date': latest[0], 'priority': max((x[3] for x in data['events'])), 'event_count': len(data['events'])})
        if active:
            totals[data['program']] += 1
    result.sort(key=lambda x: (x['program'], x['last_date'], x['case_id']))
    return {'cases': result, 'program_totals': totals, 'event_count': len(events)}

def encode_diversion_state(state: dict) -> bytes:
    return json.dumps(state, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')

def decode_diversion_state(payload: bytes | str) -> dict:
    try:
        if isinstance(payload, bytes):
            text = payload.decode('utf-8')
        elif isinstance(payload, str):
            text = payload
        else:
            raise ValueError('invalid payload')
        value = json.loads(text)
    except (ValueError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(value, dict):
        raise ValueError('invalid state')
    return value

