    seen = set()
    for row in rows:
        if None in row or any((v is None for v in row.values())):
            raise ValueError('invalid row')
        if not row['id'] or row['id'] in seen or row['status'] not in _STATUSES:
            raise ValueError('invalid order')
        _date(row['scheduled_date'])
        try:
            hours = float(row['hours'])
        except (TypeError, ValueError):
            raise ValueError('invalid hours')
        seen.add(row['id'])
        item = dict(row)
        item['hours'] = hours
        item['materials'] = [x.strip() for x in row['materials'].split(';') if x.strip()]
        result.append(item)
    return result

def _allowed(user, order):
    return user.get('tenant') == order.get('tenant') and (user.get('id') == order.get('owner') or bool(set(user.get('roles', [])) & {'planner', 'supervisor'}))

def work_order_report(requester: dict, orders: list[dict], start: str, end: str) -> dict:
    first, last = (_date(start), _date(end))
    if first > last:
        raise ValueError('invalid range')
    selected = [o for o in orders if first <= _date(o['scheduled_date']) <= last]
    selected = [o for o in selected if _allowed(requester, o)]
    units = {}
    for o in selected:
        u = units.setdefault(o['unit'], {'orders': 0, 'hours': 0.0, 'statuses': {}})
        u['orders'] += 1
        u['hours'] += o['hours']
        u['statuses'][o['status']] = u['statuses'].get(o['status'], 0) + 1
    for u in units.values():
        u['hours'] = round(u['hours'], 2)
    listed = sorted(selected, key=lambda o: (o['scheduled_date'], o['unit'], o['id']))
    return {'total_hours': round(sum((o['hours'] for o in selected)), 2), 'by_unit': {k: units[k] for k in sorted(units)}, 'orders': [{k: o[k] for k in ('id', 'unit', 'scheduled_date', 'status', 'hours')} for o in listed]}

def approve_work_order(requester: dict, orders: list[dict], order_id: str, note: str) -> dict:
    if not isinstance(note, str) or len(note) > 200:
        raise ValueError('invalid note')
    for i, order in enumerate(orders):
        if order.get('id') == order_id:
            if not _allowed(requester, order):
                raise PermissionError('not permitted')
            if order.get('status') not in {'open', 'in_progress'}:
                raise ValueError('cannot approve')
            updated = dict(order)
            updated['status'] = 'approved'
            updated['approval_note'] = note
            orders[i] = updated
            return dict(updated)
    raise KeyError(order_id)

