import base64
import datetime
import hashlib
import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError()
    if not secret:
        raise ValueError()
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(value).decode()

def verify_secret(stored: str, secret: str) -> bool:
    if not isinstance(stored, str) or not isinstance(secret, str):
        raise TypeError()
    try:
        kind, salt_text, value_text = stored.split('$')
        if kind != 'pbkdf2':
            return False
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(value_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

