    result, part, escaped = ([], [], False)
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError()
            part.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            result.append(''.join(part).strip())
            part = []
        else:
            part.append(char)
    if escaped:
        raise ValueError()
    result.append(''.join(part).strip())
    return result

