    if not value or value.count('.') > 1:
        raise ValueError()
    whole, dot, fraction = value.partition('.')
    if not whole.isdigit() or (dot and (not fraction.isdigit() or len(fraction) > 2)):
        raise ValueError()
    return int(whole) * 100 + int((fraction + '00')[:2])

