import os
from collections.abc import Mapping

def submit_complaint(complaint: Mapping[str, str], config: Mapping[str, str] | None=None) -> dict:
    required = ('customer_id', 'category', 'description')
    for name in required:
        value = complaint.get(name)
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f'{name} must be a non-empty string')
    priority = complaint.get('priority', 'normal')
    if priority not in {'low', 'normal', 'high'}:
        raise ValueError('priority must be low, normal, or high')
    token = config.get('API_TOKEN') if config is not None else None
    if not isinstance(token, str) or not token:
        token = os.environ.get('COMPLAINT_API_TOKEN')
    if not token:
        raise RuntimeError('COMPLAINT_API_TOKEN is required')
    return {'endpoint': '/v1/complaints', 'headers': {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}, 'body': {'customer_id': complaint['customer_id'], 'category': complaint['category'], 'description': complaint['description'], 'priority': priority}}

