    if since is not None and (isinstance(since, bool) or not isinstance(since, int) or since < 0):
        raise ValueError('invalid since')
    if not message_ids:
        return []
    counts = {x: {'delivered': 0, 'failed': 0, 'pending': 0} for x in message_ids}
    page = 1
    while True:
        params = {'message_ids': ','.join(message_ids), 'page': page, 'limit': 100}
        if since is not None:
            params['since'] = since
        r = requests.get('https://messaging.example.com/v1/delivery-receipts', params=params, headers={'Authorization': 'Bearer ' + api_key})
        if r.status_code != 200:
            raise RuntimeError('delivery service error')
        data = r.json()
        for receipt in data.get('receipts', []):
            mid = receipt.get('message_id')
            timestamp = receipt.get('timestamp')
            status = receipt.get('status')
            if mid in counts and (since is None or timestamp >= since) and (status in counts[mid]):
                counts[mid][status] += 1
        if not data.get('next_page', False):
            break
        page += 1
    result = []
    for mid in message_ids:
