        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        try:
            dt = datetime.fromisoformat(row[0].strip().replace('Z', '+00:00'))
            if dt.tzinfo is None:
                raise ValueError()
            dt = dt.astimezone(timezone.utc)
            station = row[1].strip()
            pm25, co2 = (float(row[2]), float(row[3]))
            if not station or not math.isfinite(pm25) or (not math.isfinite(co2)) or (pm25 < 0) or (co2 < 0):
                raise ValueError()
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        result.append({'timestamp': dt.strftime('%Y-%m-%dT%H:%M:%SZ'), 'station': station, 'pm25': pm25, 'co2': co2})
    return result

def aggregate_readings(readings: list[dict], window_minutes: int) -> list[dict]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or window_minutes <= 0:
        raise ValueError('invalid window')
    groups = {}
    size = window_minutes * 60
    for r in readings:
        try:
            dt = datetime.fromisoformat(str(r['timestamp']).replace('Z', '+00:00'))
            station, pm, co = (str(r['station']), float(r['pm25']), float(r['co2']))
            if dt.tzinfo is None or not station or (not all((math.isfinite(x) and x >= 0 for x in (pm, co)))):
                raise ValueError()
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        epoch = int(dt.timestamp())
        start = datetime.fromtimestamp(epoch - epoch % size, timezone.utc)
        key = (start, station)
        groups.setdefault(key, []).append((pm, co))
    out = []
    for (start, station), values in sorted(groups.items(), key=lambda x: x[0]):
        out.append({'start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'station': station, 'count': len(values), 'avg_pm25': round(sum((x[0] for x in values)) / len(values), 2), 'max_co2': round(max((x[1] for x in values)), 2)})
    return out

def render_report(rows: list[dict], title: str) -> str:
    lines = ['<div class="air-quality-report">', f'<h1>{escape(str(title), quote=True)}</h1>', '<table><thead><tr><th>Window</th><th>Station</th><th>Readings</th><th>Average PM2.5</th><th>Peak CO2</th></tr></thead><tbody>']
    for r in rows:
        try:
            start, station, count = (r['start'], r['station'], r['count'])
            avg, peak = (r['avg_pm25'], r['max_co2'])
        except KeyError as exc:
            raise ValueError('missing field') from exc
        lines.append(f'<tr><td>{escape(str(start), quote=True)}</td><td>{escape(str(station), quote=True)}</td><td>{count}</td><td>{float(avg):.2f}</td><td>{float(peak):.2f}</td></tr>')
