import hashlib
import hmac
import os
from datetime import date

def _valid_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if len(value) != 10 or value[4] != '-' or value[7] != '-':
        raise ValueError('invalid date')
    return value

def summarize_expenses(expenses):
    if not isinstance(expenses, list):
        raise ValueError('invalid expenses')
    cats = {}
    days = {}
    for item in expenses:
        if not isinstance(item, dict) or not isinstance(item.get('category'), str) or (not item['category']):
            raise ValueError('invalid expense')
        amount = item.get('amount_cents')
        if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            raise ValueError('invalid amount')
        day = _valid_date(item.get('date'))
        cats[item['category']] = cats.get(item['category'], 0) + amount
        days[day] = days.get(day, 0) + amount
    ordered = dict(sorted(cats.items(), key=lambda x: (-x[1], x[0])))
    return {'categories': ordered, 'daily_totals': dict(sorted(days.items())), 'total_cents': sum(cats.values()), 'expense_count': len(expenses)}

def _pin_hash(pin):
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + value.hex()

def _pin_ok(pin, stored):
    try:
        salt, expected = stored.split(':')
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), bytes.fromhex(salt), 100000).hex()
        return hmac.compare_digest(actual, expected)
    except (AttributeError, ValueError, TypeError):
        return False

def build_authorization(request, policy, approver_pin):
    if not isinstance(request, dict) or not isinstance(policy, dict) or (not isinstance(approver_pin, str)) or (not approver_pin):
        raise ValueError('invalid input')
    if not isinstance(request.get('employee'), str) or not request['employee'] or (not isinstance(request.get('destination'), str)) or (not request['destination']):
        raise ValueError('invalid request')
    start = _valid_date(request.get('start_date'))
    end = _valid_date(request.get('end_date'))
    if start > end:
        raise ValueError('invalid range')
    summary = summarize_expenses(request.get('expenses'))
    for key in ('allowed_destinations', 'allowed_categories', 'approver'):
        if key not in policy:
            raise ValueError('invalid policy')
    if not isinstance(policy['approver'], str) or not policy['approver']:
        raise ValueError('invalid policy')
    reasons = []
    if request['destination'] not in policy['allowed_destinations']:
        reasons.append('DESTINATION_NOT_ALLOWED')
    if any((x not in policy['allowed_categories'] for x in summary['categories'])):
        reasons.append('CATEGORY_NOT_ALLOWED')
    if summary['total_cents'] > policy['max_total_cents']:
        reasons.append('TOTAL_LIMIT_EXCEEDED')
    if any((x > policy['max_daily_cents'] for x in summary['daily_totals'].values())):
        reasons.append('DAILY_LIMIT_EXCEEDED')
    return {'employee': request['employee'], 'destination': request['destination'], 'start_date': start, 'end_date': end, 'summary': summary, 'approved': not reasons, 'reasons': reasons, 'approver': policy['approver'], 'pin_hash': _pin_hash(approver_pin)}

def check_authorization(record, approver_pin):
    return isinstance(record, dict) and record.get('approved') is True and isinstance(approver_pin, str) and _pin_ok(approver_pin, record.get('pin_hash'))

