import datetime
import hashlib
import hmac
import json

def build_aging_report(payload: str, signature: str, secret: str, as_of: str) -> dict:
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        day = datetime.date.fromisoformat(as_of)
        root = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid input') from exc
    if not isinstance(root, dict) or not isinstance(root.get('invoices'), list):
        raise ValueError('invalid invoices')
    seen = set()
    grouped = {}
    for row in root['invoices']:
        if not isinstance(row, dict):
            raise ValueError('invalid invoice')
        keys = ('id', 'vendor', 'issued', 'due', 'total_cents', 'paid_cents')
        if any((k not in row for k in keys)):
            raise ValueError('missing field')
        ident, vendor = (row['id'], row['vendor'])
        if not isinstance(ident, str) or not ident or (not isinstance(vendor, str)) or (not vendor):
            raise ValueError('invalid name')
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        try:
            issued = datetime.date.fromisoformat(row['issued'])
            due = datetime.date.fromisoformat(row['due'])
        except Exception as exc:
            raise ValueError('invalid date') from exc
        total, paid = (row['total_cents'], row['paid_cents'])
        if type(total) is not int or type(paid) is not int or total < 0 or (paid < 0) or (paid > total) or (issued > day) or (due > day):
            raise ValueError('invalid amount or date')
        balance = total - paid
        late = max(0, (day - due).days)
        bucket = 'current' if late == 0 else '1-30' if late <= 30 else '31-60' if late <= 60 else '61-90' if late <= 90 else '90+'
        grouped.setdefault(vendor, []).append((due, ident, {'id': ident, 'due': row['due'], 'balance_cents': balance, 'days_overdue': late, 'bucket': bucket}))
    vendors = []
    for vendor in sorted(grouped, key=lambda x: (x.casefold(), x)):
        items = sorted(grouped[vendor], key=lambda x: (x[0], x[1]))
        invoices = [x[2] for x in items]
        total = sum((x['balance_cents'] for x in invoices))
        overdue = sum((x['balance_cents'] for x in invoices if x['days_overdue'] > 0))
        vendors.append({'vendor': vendor, 'total_cents': total, 'overdue_cents': overdue, 'invoices': invoices})
    return {'as_of': as_of, 'vendors': vendors}

