import hashlib
import hmac
import json

def parse_webhook_header(header: str) -> tuple[str, str]:
    if not isinstance(header, str) or header.count(';') != 1:
        raise ValueError('invalid header')
    first, second = header.split(';')
    if not first.startswith('kid=') or not second.startswith('sig='):
        raise ValueError('invalid header')
    kid = first[4:]
    sig = second[4:]
    if not kid or len(sig) != 64 or any((c not in '0123456789abcdef' for c in sig)):
        raise ValueError('invalid header')
    return (kid, sig)

def route_webhook(payload: bytes, header: str, secrets: dict[str, bytes], warehouses: dict[str, dict]) -> list[dict]:
    try:
        kid, supplied = parse_webhook_header(header)
        expected = hmac.new(secrets[kid], payload, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, supplied):
            raise ValueError('invalid webhook')
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid webhook')
    try:
        data = json.loads(payload.decode('utf-8'))
        if not isinstance(data, dict) or not isinstance(data.get('orders'), list):
            raise ValueError
        orders = data['orders']
        seen = set()
        clean = []
        for o in orders:
            if not isinstance(o, dict) or not isinstance(o.get('id'), str) or (not o['id']) or (o['id'] in seen):
                raise ValueError
            if not isinstance(o.get('country'), str) or not isinstance(o.get('postal'), str):
                raise ValueError
            if not isinstance(o.get('priority'), int) or isinstance(o['priority'], bool):
                raise ValueError
            if not isinstance(o.get('created'), int) or isinstance(o['created'], bool) or o['created'] < 0:
                raise ValueError
            if not isinstance(o.get('items'), list) or not o['items']:
                raise ValueError
            units = 0
            for item in o['items']:
                if not isinstance(item, dict) or not isinstance(item.get('sku'), str) or (not item['sku']) or (not isinstance(item.get('qty'), int)) or isinstance(item['qty'], bool) or (item['qty'] <= 0):
                    raise ValueError
                units += item['qty']
            seen.add(o['id'])
            clean.append((o, units))
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError):
        raise ValueError('invalid payload')
    clean.sort(key=lambda x: (-x[0]['priority'], x[0]['created'], x[0]['id']))
    remaining = {name: warehouse['capacity'] for name, warehouse in warehouses.items()}
    result = []
    for order_data, units in clean:
        choices = []
        for name, warehouse in warehouses.items():
            match = bool(warehouse['prefixes']) and any((order_data['postal'].startswith(prefix) for prefix in warehouse['prefixes']))
            if order_data['country'] in warehouse['countries'] and (not warehouse['prefixes'] or match) and (remaining[name] >= units):
                choices.append((0 if match else 1, -remaining[name], name))
        chosen = min(choices)[2] if choices else None
        if chosen is not None:
            remaining[chosen] -= units
        result.append({'id': order_data['id'], 'warehouse': chosen, 'units': units})
    return result

