import hashlib
import hmac
import json
import os

def calculate_cart(items: list[dict], catalog: dict[str, dict], coupons: dict[str, dict], config: dict | None=None) -> dict:
    config = {} if config is None else config
    merged = {}
    order = []
    for item in items:
        if not isinstance(item, dict) or not isinstance(item.get('sku'), str) or (not isinstance(item.get('qty'), int)) or isinstance(item.get('qty'), bool) or (item['qty'] <= 0):
            raise ValueError('invalid item')
        sku = item['sku']
        if sku not in catalog or not isinstance(catalog[sku], dict):
            raise ValueError('unknown sku')
        if sku not in merged:
            merged[sku] = 0
            order.append(sku)
        merged[sku] += item['qty']
    lines = []
    for sku in order:
        entry = catalog[sku]
        if not isinstance(entry.get('price'), int) or isinstance(entry['price'], bool) or entry['price'] < 0 or (not isinstance(entry.get('category'), str)):
            raise ValueError('invalid catalog entry')
        lines.append({'sku': sku, 'qty': merged[sku], 'unit_price': entry['price'], 'line_total': entry['price'] * merged[sku]})
    subtotal = sum((x['line_total'] for x in lines))
    amounts = [x['line_total'] for x in lines]
    codes = config.get('coupon_codes', [])
    if not isinstance(codes, list):
        raise ValueError('invalid coupons')
    discount = 0
    for code in codes:
        if code not in coupons or not isinstance(coupons[code], dict):
            raise ValueError('unknown coupon')
        c = coupons[code]
        typ, value = (c.get('type'), c.get('value'))
        category = c.get('category')
        if typ == 'percent':
            if not isinstance(value, int) or isinstance(value, bool) or (not 0 <= value <= 100):
                raise ValueError('invalid coupon')
            for i, line in enumerate(lines):
                if category is None or (line['sku'] and catalog[line['sku']]['category'] == category):
                    cut = amounts[i] * value // 100
                    amounts[i] -= cut
                    discount += cut
        elif typ == 'fixed':
            if not isinstance(value, int) or isinstance(value, bool) or value < 0:
                raise ValueError('invalid coupon')
            cut = min(value, sum(amounts))
            discount += cut
            if amounts:
                amounts[-1] -= cut
        else:
            raise ValueError('invalid coupon')
    tax_bps = config.get('tax_bps', 0)
    if not isinstance(tax_bps, int) or isinstance(tax_bps, bool) or (not 0 <= tax_bps <= 10000):
        raise ValueError('invalid tax')
    tax = (subtotal - discount) * tax_bps // 10000
    total = subtotal - discount + tax
    secret = config.get('receipt_secret') or os.environ.get('SHOP_RECEIPT_SECRET')
    if not secret:
        raise ValueError('missing receipt secret')
    payload = {'lines': lines, 'subtotal': subtotal, 'discount': discount, 'tax': tax, 'total': total}
    body = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    receipt = hmac.new(secret.encode(), body, hashlib.sha256).hexdigest()
    return {**payload, 'receipt_token': receipt}

