import hmac
import json
import os
from decimal import Decimal, ROUND_HALF_UP

def build_invoice_report(records: list[dict], config: dict | None=None) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if config is not None and (not isinstance(config, dict)):
        raise TypeError('config must be a mapping')
    config = {} if config is None else config
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('invoice_id'), str) or not record['invoice_id']:
            raise ValueError('invalid invoice_id')
        if not isinstance(record.get('customer'), str) or not record['customer']:
            raise ValueError('invalid customer')
        if record.get('status') not in ('approved', 'void'):
            raise ValueError('invalid status')
        try:
            amount = Decimal(str(record['amount']))
        except Exception as exc:
            raise ValueError('invalid amount') from exc
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid amount')
        if record['status'] == 'void':
            continue
        invoice_id = record['invoice_id']
        if invoice_id in groups and groups[invoice_id][0] != record['customer']:
            raise ValueError('conflicting customer')
        if invoice_id not in groups:
            groups[invoice_id] = [record['customer'], Decimal('0')]
        groups[invoice_id][1] += amount
    rows = []
    for invoice_id, (customer, amount) in groups.items():
        total = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append({'invoice_id': invoice_id, 'customer': customer, 'total': f'{total:.2f}'})
    rows.sort(key=lambda row: (-Decimal(row['total']), row['invoice_id']))
    page = config.get('page', 1)
    page_size = config.get('page_size', 50)
    if not isinstance(page, int) or not isinstance(page_size, int) or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    grand_total = sum((Decimal(row['total']) for row in rows), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    payload = {'invoices': rows[(page - 1) * page_size:page * page_size], 'page': page, 'page_size': page_size, 'total_invoices': len(rows), 'grand_total': f'{grand_total:.2f}'}
    key = config.get('signing_key') or os.environ.get('INVOICE_SIGNING_KEY')
    if key is None:
        raise ValueError('missing signing key')
    key = key.encode() if isinstance(key, str) else key
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()
    payload['signature'] = hmac.new(key, encoded, hashlib.sha256).hexdigest()
    return payload

