import hashlib
import hmac
import json
from datetime import datetime, timezone, timedelta

def _validated(events):
    if not isinstance(events, list):
        raise ValueError('events')
    for e in events:
        if not isinstance(e, dict) or not isinstance(e.get('patient_id'), str) or (not e['patient_id']):
            raise ValueError('event')
        if not isinstance(e.get('timestamp'), str):
            raise ValueError('timestamp')
        try:
            dt = datetime.fromisoformat(e['timestamp'][:-1] + '+00:00')
        except Exception as exc:
            raise ValueError('timestamp') from exc
        if not e['timestamp'].endswith('Z') or dt.tzinfo != timezone.utc:
            raise ValueError('timestamp')
        if 'type' in e and (not isinstance(e['type'], str) or not e['type']):
            raise ValueError('type')
        if 'value' in e and (isinstance(e['value'], bool) or not isinstance(e['value'], (int, float))):
            raise ValueError('value')
    return events

def verify_and_parse(body: bytes, signature: str, secret: bytes) -> list[dict]:
    if not isinstance(body, bytes) or not isinstance(signature, str) or (not signature.startswith('sha256=')):
        raise ValueError('signature')
    text = signature[7:]
    if len(text) != 64:
        raise ValueError('signature')
    try:
        supplied = bytes.fromhex(text)
    except ValueError as exc:
        raise ValueError('signature') from exc
    expected = hmac.new(secret, body, hashlib.sha256).digest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('signature')
    try:
        obj = json.loads(body.decode('utf-8'))
    except Exception as exc:
        raise ValueError('body') from exc
    if not isinstance(obj, dict) or 'events' not in obj:
        raise ValueError('body')
    return _validated(obj['events'])

def _stamp(dt):
    s = dt.strftime('%Y-%m-%dT%H:%M:%S.%fZ')
    return s.replace('.000000Z', 'Z')

def aggregate_events(events: list[dict]) -> dict:
    groups = {}
    for i, e in enumerate(events):
        dt = datetime.fromisoformat(e['timestamp'][:-1] + '+00:00')
        groups.setdefault(e['patient_id'], []).append((dt, i, e))
    result = []
    for pid in sorted(groups):
        rows = sorted(groups[pid], key=lambda x: (x[0], x[1]))
        counts = {}
        values = {}
        for dt, _, e in rows:
            typ = e.get('type', '')
            counts[typ] = counts.get(typ, 0) + 1
            if 'value' in e:
                values.setdefault(typ, []).append(e['value'])
        best = 0
        for left in range(len(rows)):
            right = left
            while right < len(rows) and rows[right][0] - rows[left][0] <= timedelta(hours=24):
                right += 1
            best = max(best, right - left)
        result.append({'patient_id': pid, 'first_timestamp': _stamp(rows[0][0]), 'last_timestamp': _stamp(rows[-1][0]), 'event_count': len(rows), 'by_type': {k: counts[k] for k in sorted(counts)}, 'means': {k: round(sum(values[k]) / len(values[k]), 3) for k in sorted(values)}, 'max_24h_events': best})
    return {'patients': result}

def process_webhook(body: str | bytes, signature: str, secret: str | bytes) -> dict:
    raw = body.encode('utf-8') if isinstance(body, str) else body
    key = secret.encode('utf-8') if isinstance(secret, str) else secret
    return aggregate_events(verify_and_parse(raw, signature, key))

