import os
import zipfile
from datetime import datetime, timezone, timedelta

def extract_inspection_bundle(archive_path: str, destination: str) -> list[str]:
    os.makedirs(destination, exist_ok=True)
    base = os.path.realpath(destination)
    names = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if name.endswith('/'):
                continue
            target = os.path.realpath(os.path.join(base, name))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('invalid archive member')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
            names.append(name)
    return sorted(names)

def aggregate_inspections(records: list[dict], window_minutes: int=10) -> list[dict]:
    if window_minutes <= 0:
        raise ValueError('window_minutes must be positive')
    required = {'timestamp', 'blade', 'station', 'vibration', 'defect'}
    groups = {}
    for record in records:
        if set(record) != required:
            raise ValueError('invalid record')
        text = record['timestamp']
        if not isinstance(text, str) or not text.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            stamp = datetime.fromisoformat(text[:-1] + '+00:00')
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        if stamp.tzinfo is None:
            raise ValueError('invalid timestamp')
        key = (record['blade'], record['station'])
        groups.setdefault(key, []).append((stamp.astimezone(timezone.utc), record))
    result = []
    span = timedelta(minutes=window_minutes)
    for (blade, station), values in groups.items():
        values.sort(key=lambda x: x[0])
        anchor = values[0][0]
        buckets = {}
        for stamp, record in values:
            if stamp < anchor:
                raise ValueError('timestamp precedes anchor')
            start = anchor + (stamp - anchor) // span * span
            buckets.setdefault(start, []).append(record)
        for start, bucket in buckets.items():
            defects = sorted({r['defect'] for r in bucket if r['defect'] is not None})
            result.append({'blade': blade, 'station': station, 'window_start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'samples': len(bucket), 'max_vibration': max((r['vibration'] for r in bucket)), 'defects': defects})
    result.sort(key=lambda x: (x['blade'], x['station'], x['window_start']))
    return result

