import math
import secrets
from decimal import Decimal, ROUND_HALF_UP

def parse_bom(text: str) -> dict[str, list[tuple[str, int]]]:
    result = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if '#' in line:
            line = line.split('#', 1)[0].rstrip()
        if '->' not in line:
            raise ValueError('invalid line')
        parent, items = line.split('->', 1)
        parent = parent.strip()
        if not parent:
            raise ValueError('empty name')
        result.setdefault(parent, [])
        positions = {name: i for i, (name, _) in enumerate(result[parent])}
        for item in items.split(','):
            if ':' not in item:
                raise ValueError('invalid child')
            name, amount = item.rsplit(':', 1)
            name, amount = (name.strip(), amount.strip())
            if not name or not amount.isdigit() or int(amount) <= 0:
                raise ValueError('invalid child')
            value = int(amount)
            if name in positions:
                i = positions[name]
                result[parent][i] = (name, result[parent][i][1] + value)
            else:
                positions[name] = len(result[parent])
                result[parent].append((name, value))
    return result

def explode_bom(graph: dict[str, list[tuple[str, int]]], root: str, quantity: int=1) -> dict[str, int]:
    if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
        raise ValueError('invalid quantity')
    output = {}
    active = set()

    def visit(name, amount):
        if name not in graph:
            output[name] = output.get(name, 0) + amount
            return
        if name in active:
            raise ValueError('cycle')
        active.add(name)
        for child, count in graph[name]:
            if isinstance(count, bool) or not isinstance(count, int) or count <= 0:
                raise ValueError('invalid quantity')
            visit(child, amount * count)
        active.remove(name)
    visit(root, quantity)
    return output

def make_purchase_order(components: dict[str, int], prices: dict[str, float], categories: dict[str, str], code_length: int=12) -> dict:
    if isinstance(code_length, bool) or not isinstance(code_length, int) or (not 8 <= code_length <= 64):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(code_length)))
    lines = []
    for part, quantity in components.items():
        if part not in prices or part not in categories:
            raise KeyError(part)
        price = prices[part]
        if not isinstance(price, (int, float)) or isinstance(price, bool) or (not math.isfinite(price)) or (price < 0):
            raise ValueError('invalid price')
        subtotal = Decimal(str(price)) * quantity
        lines.append((categories[part], price, part, {'part': part, 'category': categories[part], 'quantity': quantity, 'unit_price': price, 'subtotal': float(subtotal.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))}, subtotal))
    lines.sort(key=lambda x: (x[0], x[1], x[2]))
    total = sum((x[4] for x in lines), Decimal('0'))
    return {'code': code, 'lines': [x[3] for x in lines], 'total': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))}

