from datetime import datetime, timezone

def _access(user, sub):
    if user.get('tenant_id') != sub.get('tenant_id') or (user.get('id') != sub.get('owner_id') and 'admin' not in user.get('roles', [])):
        raise PermissionError('not permitted')

def _split(line):
    out, cur, escaped = ([], [], False)
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == ';':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('dangling escape')
    out.append(''.join(cur))
    return out

def _date(value):
    try:
        result = datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc
    return result

def parse_usage_log(text: str) -> list[dict]:
    rows = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split(raw)
        if len(fields) != 3 or fields[1] != 'watch':
            raise ValueError('invalid record')
        try:
            minutes = int(fields[2])
        except Exception as exc:
            raise ValueError('invalid minutes') from exc
        if minutes < 0:
            raise ValueError('invalid minutes')
        rows.append({'timestamp': _date(fields[0]), 'action': fields[1], 'minutes': minutes})
    return sorted(rows, key=lambda row: row['timestamp'])

def subscription_report(requester: dict, subscription: dict, log_text: str) -> dict:
    _access(requester, subscription)
    start, end = (_date(subscription['starts_at']), _date(subscription['ends_at']))
    seen, daily = (set(), {})
    for row in parse_usage_log(log_text):
        key = (row['timestamp'], row['action'], row['minutes'])
        if start <= row['timestamp'] <= end and key not in seen:
            seen.add(key)
            day = row['timestamp'].strftime('%Y-%m-%d')
            daily[day] = daily.get(day, 0) + row['minutes']
    daily = dict(sorted(daily.items()))
    total = sum(daily.values())
    return {'subscription_id': subscription['id'], 'status': subscription['status'], 'total_minutes': total, 'by_day': daily, 'monthly_limit': subscription['monthly_limit'], 'over_limit': total > subscription['monthly_limit']}

def cancel_subscription(requester: dict, subscription: dict, reason: str) -> dict:
    _access(requester, subscription)
    if not reason.strip():
        raise ValueError('reason required')
    result = dict(subscription)
    result.update(status='cancelled', cancellation_reason=reason, cancelled_by=requester['id'])
    return result

