import os

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and pin.isdigit() and (4 <= len(pin) <= 8)

def create_access_record(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + '$' + digest.hex()

def verify_access_record(record: str, pin: str) -> bool:
    if not _valid_pin(pin) or not isinstance(record, str):
        return False
    try:
        encoded_salt, expected = record.split('$', 1)
        salt = base64.b64decode(encoded_salt.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000).hex()
    except (ValueError, TypeError):
        return False
    return hmac.compare_digest(actual, expected)

