def _evaluate(text, values):
    try:
        tree = ast.parse(text, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc
    allowed = (ast.Expression, ast.Constant, ast.Name, ast.BinOp, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.UnaryOp, ast.UAdd, ast.USub, ast.BoolOp, ast.And, ast.Or, ast.Not, ast.Compare, ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Call, ast.Load)
    if any((not isinstance(n, allowed) for n in ast.walk(tree))):
        raise ValueError('unsupported expression')
