def parse_pressure_log(text: str) -> list[dict]:
    result = []
    for number, raw in enumerate(text.splitlines(), 1):
        if not raw.strip():
            continue
        fields = raw.split('|')
        if len(fields) != 4:
            raise ValueError(f'invalid record {number}')
        timestamp, station, pressure_text, status = fields
        station = station.strip()
        if not station or status not in {'NORMAL', 'WARN', 'CRITICAL'}:
            raise ValueError(f'invalid record {number}')
        try:
            datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
            pressure = float(pressure_text)
        except (ValueError, TypeError):
            raise ValueError(f'invalid record {number}')
        if not math.isfinite(pressure):
            raise ValueError(f'invalid record {number}')
        result.append({'timestamp': timestamp, 'station': station, 'pressure': pressure, 'status': status})
    return result

def _moment(value):
    return datetime.fromisoformat(value.replace('Z', '+00:00')).astimezone(timezone.utc)

def aggregate_alerts(readings: list[dict], window_seconds: int) -> list[dict]:
    if window_seconds <= 0:
        raise ValueError('window must be positive')
    grouped = {}
    for item in readings:
        grouped.setdefault(item['station'], []).append(item)
    output = []
    for station, values in grouped.items():
        values.sort(key=lambda x: _moment(x['timestamp']))
        alerts = sum((1 for x in values if x['status'] != 'NORMAL' or x['pressure'] >= 100))
        peaks = 0
        for index, item in enumerate(values):
            if item['pressure'] < 100:
                continue
            now = _moment(item['timestamp'])
            if any((0 <= (now - _moment(prev['timestamp'])).total_seconds() <= window_seconds and prev['status'] != 'NORMAL' for prev in values[:index])):
                peaks += 1
        output.append({'station': station, 'count': len(values), 'average_pressure': sum((x['pressure'] for x in values)) / len(values), 'maximum_pressure': max((x['pressure'] for x in values)), 'first_timestamp': values[0]['timestamp'], 'last_timestamp': values[-1]['timestamp'], 'alert_count': alerts, 'window_peak_count': peaks})
    return sorted(output, key=lambda x: (-x['alert_count'], -x['maximum_pressure'], x['station']))

