    e = lambda value: escape(str(value), quote=True)
    rows = ''.join((f"<tr><td>{e(x['station'])}</td><td>{x['count']}</td><td>{x['average_pressure']:.2f}</td><td>{x['maximum_pressure']:.2f}</td><td>{x['alert_count']}</td><td>{x['window_peak_count']}</td></tr>" for x in alerts))
    items = ''.join((f"<li>{e(x['timestamp'])} — {e(x['station'])}: {x['pressure']:.2f} ({e(x['status'])})</li>" for x in readings))
