def create_host_account(host_id: str, password: str) -> dict:
    if not isinstance(host_id, str) or not host_id or (not isinstance(password, str)) or (not password):
        raise ValueError('invalid account')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'host_id': host_id, 'salt': base64.b64encode(salt).decode(), 'password_hash': base64.b64encode(digest).decode()}

def authenticate_host(account: dict, password: str) -> bool:
    try:
        if not isinstance(account, dict) or not isinstance(password, str):
            return False
        salt = base64.b64decode(account['salt'].encode(), validate=True)
        expected = base64.b64decode(account['password_hash'].encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def search_rentals(listings: list[dict], bookings: list[dict], start_date: str, end_date: str, guests: int, required_amenities: tuple[str, ...]=()) -> list[dict]:
    try:
        start = datetime.date.fromisoformat(start_date)
        end = datetime.date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid dates')
    if start >= end or not isinstance(guests, int) or isinstance(guests, bool) or (guests <= 0):
        raise ValueError('invalid range')
    parsed = []
    for booking in bookings:
        try:
            bs = datetime.date.fromisoformat(booking['start'])
            be = datetime.date.fromisoformat(booking['end'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid booking')
        if bs >= be:
            raise ValueError('invalid booking')
        parsed.append((booking['listing_id'], bs, be))
    nights = (end - start).days
    result = []
    for item in listings:
        try:
