            if rate < 0 or item['capacity'] < guests:
                continue
            if not set(required_amenities).issubset(set(item['amenities'])):
                continue
            if any((i == item['id'] and bs < end and (be > start) for i, bs, be in parsed)):
                continue
            ratings = [review['rating'] for review in item['reviews']]
            if any((not isinstance(r, (int, float)) or r < 1 or r > 5 for r in ratings)):
                raise ValueError('invalid rating')
        except (KeyError, TypeError):
            raise ValueError('invalid listing')
