        result.append({'id': item['id'], 'title': item['title'], 'host_id': item['host_id'], 'nightly_rate': rate, 'nights': nights, 'total_cost': rate * nights, 'average_rating': average, 'review_count': len(ratings)})
    result.sort(key=lambda x: (-x['average_rating'], x['total_cost'], x['id']))
    return result

