import datetime
import hashlib
import hmac
import json
import math

def verify_and_summarize(payload: str, signature: str, signing_key: bytes, day: str) -> dict:
    try:
        datetime.date.fromisoformat(day)
    except Exception as exc:
        raise ValueError('invalid day') from exc
    try:
        supplied = bytes.fromhex(signature)
    except ValueError as exc:
        raise PermissionError('invalid signature') from exc
    expected = hmac.new(signing_key, payload.encode('utf-8'), hashlib.sha256).digest()
    if len(supplied) != len(expected) or not hmac.compare_digest(supplied, expected):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('containers'), list):
        raise ValueError('invalid container list')
    seen = set()
    groups = {}
    for item in data['containers']:
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        for field in ('container', 'berth', 'eta', 'status', 'weight_tons'):
            if field not in item:
                raise ValueError('missing field')
        container = item['container']
        berth = item['berth']
        status = item['status']
        if not all((isinstance(x, str) and x for x in (container, berth, status))):
            raise ValueError('invalid text')
        if container in seen:
            raise ValueError('duplicate container')
        seen.add(container)
        try:
            eta = datetime.datetime.fromisoformat(item['eta'])
        except Exception as exc:
            raise ValueError('invalid eta') from exc
        weight = item['weight_tons']
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or (not math.isfinite(weight)) or (weight < 0):
            raise ValueError('invalid weight')
        if eta.date().isoformat() == day and status == 'scheduled':
            count, total = groups.get(berth, (0, 0))
            groups[berth] = (count + 1, total + weight)
    return {'day': day, 'berths': [{'berth': berth, 'containers': groups[berth][0], 'weight_tons': round(groups[berth][1], 2)} for berth in sorted(groups)]}

