import json
import os

def build_order_summary(orders: list[dict], page: int, page_size: int, config: dict | None=None) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be a positive integer')
    if config is not None and 'signing_key' in config:
        key = config['signing_key']
    else:
        key = os.environ.get('ORDER_SIGNING_KEY')
    if key is None:
        raise RuntimeError('ORDER_SIGNING_KEY is required')
    if not isinstance(key, str) or not key:
        raise ValueError('signing_key must be a non-empty string')
    paid = []
    for order in orders:
        if not isinstance(order, dict):
            raise ValueError('invalid order')
        required = ('id', 'seller', 'price_cents', 'quantity', 'status')
        if any((name not in order for name in required)):
            raise ValueError('invalid order')
        if not isinstance(order['id'], str) or not order['id'] or (not isinstance(order['seller'], str)) or (not order['seller']):
            raise ValueError('invalid order')
        if isinstance(order['price_cents'], bool) or not isinstance(order['price_cents'], int) or order['price_cents'] < 0:
            raise ValueError('invalid order')
        if isinstance(order['quantity'], bool) or not isinstance(order['quantity'], int) or order['quantity'] <= 0:
            raise ValueError('invalid order')
        if not isinstance(order['status'], str):
            raise ValueError('invalid order')
        if order['status'] == 'paid':
            total = order['price_cents'] * order['quantity']
            paid.append((order['id'], order['seller'], total))
    paid.sort(key=lambda item: (item[1], item[0]))
    subtotal = sum((item[2] for item in paid))
    totals = {}
    for _, seller, total in paid:
        totals[seller] = totals.get(seller, 0) + total
    seller_totals = [{'seller': seller, 'total_cents': total} for seller, total in totals.items()]
    seller_totals.sort(key=lambda item: (-item['total_cents'], item['seller']))
    start = (page - 1) * page_size
    selected = paid[start:start + page_size]
    result_orders = [{'id': item[0], 'seller': item[1], 'line_total_cents': item[2]} for item in selected]
    payload = {'order_ids': [item[0] for item in selected], 'page': page, 'page_size': page_size, 'subtotal_cents': subtotal}
    message = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), message, hashlib.sha256).hexdigest()
    return {'orders': result_orders, 'subtotal_cents': subtotal, 'seller_totals': seller_totals, 'page': page, 'page_size': page_size, 'signature': signature}

