import csv
import datetime
import hashlib
import os
import hmac
import base64

def create_account(username: str, password: str, plan: str) -> dict:
    if not isinstance(username, str) or not username or (not isinstance(plan, str)) or (not plan):
        raise ValueError()
    if not isinstance(password, str) or len(password) < 8:
        raise ValueError()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username, 'plan': plan, 'password_hash': base64.b64encode(salt + digest).decode()}

def authenticate(account: dict, password: str) -> bool:
    if not isinstance(account, dict) or not isinstance(password, str):
        return False
    try:
        raw = base64.b64decode(account['password_hash'], validate=True)
        if len(raw) != 48:
            return False
        got = hashlib.pbkdf2_hmac('sha256', password.encode(), raw[:16], 100000)
        return hmac.compare_digest(got, raw[16:])
    except (KeyError, TypeError, ValueError):
        return False

def parse_meter_readings(text: str) -> list[tuple[str, str, int]]:
    if not isinstance(text, str):
        raise ValueError()
    result = []
    seen = set()
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith('#'):
            continue
        try:
            row = next(csv.reader([line]))
        except Exception:
            raise ValueError()
        if len(row) != 3:
            raise ValueError()
        date, meter, value = row
        try:
            datetime.date.fromisoformat(date)
            number = int(value)
        except Exception:
            raise ValueError()
        if len(date) != 10 or not meter or number < 0 or ((date, meter) in seen):
            raise ValueError()
        seen.add((date, meter))
        result.append((date, meter, number))
    return sorted(result, key=lambda x: (x[1], x[0]))

def calculate_invoice(readings: list[tuple[str, str, int]], rates: list[tuple[int | None, int]]) -> dict[str, int]:
    if not isinstance(rates, list) or not rates or rates[-1][0] is not None:
        raise ValueError()
    previous = 0
    for i, pair in enumerate(rates):
        if not isinstance(pair, tuple) or len(pair) != 2 or (not isinstance(pair[1], int)) or (pair[1] < 0):
            raise ValueError()
        if i < len(rates) - 1:
            if not isinstance(pair[0], int) or pair[0] <= 0:
                raise ValueError()
            previous += pair[0]
    groups = {}
    for item in readings:
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError()
        date, meter, value = item
        try:
            datetime.date.fromisoformat(date)
        except Exception:
            raise ValueError()
        if len(date) != 10 or not isinstance(meter, str) or (not meter) or (not isinstance(value, int)) or (value < 0):
            raise ValueError()
        groups.setdefault(meter, []).append((date, value))
    result = {}
    for meter, values in groups.items():
        values.sort()
        units = 0
        for (_, a), (_, b) in zip(values, values[1:]):
            if b < a:
                raise ValueError()
            units += b - a
        charge = 0
        left = units
        for size, price in rates:
            take = left if size is None else min(left, size)
            charge += take * price
            left -= take
            if not left:
                break
        result[meter] = charge
    return result

