import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool):
            return node.value
        if isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
    if isinstance(node, ast.Name) and node.id in names:
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        a, b = (_value(node.left, names), _value(node.right, names))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        values = [_value(x, names) for x in node.values]
        return all(values) if isinstance(node.op, ast.And) else any(values)
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        for op, part in zip(node.ops, node.comparators):
            right = _value(part, names)
            if not isinstance(op, (ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq)):
                raise ValueError()
            if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords) and (1 <= len(node.args) <= 2):
        args = [_value(x, names) for x in node.args]
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
    raise ValueError()

def fulfill_gifts(registry: list[dict], rule: str, budget: float) -> list[dict]:
    if budget < 0:
        raise ValueError()
    try:
        tree = ast.parse(rule, mode='eval')
    except Exception as exc:
        raise ValueError() from exc
    selected = []
    for item in registry:
        try:
            matched = _value(tree.body, {k: item[k] for k in ('price', 'quantity', 'stock', 'priority')})
        except Exception as exc:
            raise ValueError() from exc
        if not isinstance(matched, bool):
            raise ValueError()
        if matched:
            selected.append(item)
    selected.sort(key=lambda x: (-x['priority'], x['price'], x['name']))
    result = []
    remaining = budget
    for item in selected:
        limit = min(item['quantity'], item['stock'])
        if item['price'] > 0:
            limit = min(limit, int(remaining / item['price']))
        if limit <= 0:
            continue
        cost = limit * item['price']
        result.append({'name': item['name'], 'quantity': limit, 'cost': round(cost, 2)})
        remaining -= cost
    return result

