import hashlib
import hmac
import json
import math
import statistics

def summarize_appraisals(body: bytes, signature: str, secret: bytes, radius_miles: float=5.0) -> list[dict]:
    if not isinstance(signature, str) or len(signature) != 64:
        raise PermissionError('invalid signature')
    try:
        expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
        supplied = bytes.fromhex(signature)
    except (TypeError, ValueError):
        raise PermissionError('invalid signature')
    if not hmac.compare_digest(supplied, bytes.fromhex(expected)):
        raise PermissionError('invalid signature')
    if not isinstance(radius_miles, (int, float)) or isinstance(radius_miles, bool) or (not math.isfinite(radius_miles)) or (radius_miles < 0):
        raise ValueError('invalid radius')
    try:
        data = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid body')
    if not isinstance(data, dict) or not isinstance(data.get('properties'), list):
        raise ValueError('invalid properties')
    groups = {}
    for item in data['properties']:
        if not isinstance(item, dict):
            raise ValueError('invalid property')
        if not isinstance(item.get('neighborhood'), str) or not item['neighborhood']:
            raise ValueError('invalid neighborhood')
        if not isinstance(item.get('address'), str):
            raise ValueError('invalid address')
        value = item.get('value')
        distance = item.get('distance_miles')
        if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
            raise ValueError('invalid value')
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or (not math.isfinite(distance)) or (distance < 0):
            raise ValueError('invalid distance')
        if distance <= radius_miles:
            groups.setdefault(item['neighborhood'], []).append((value, item['address']))
    result = []
    for neighborhood in sorted(groups):
        entries = groups[neighborhood]
        result.append({'neighborhood': neighborhood, 'count': len(entries), 'median_value': round(statistics.median((x[0] for x in entries)), 2), 'addresses': [x[1] for x in entries]})
    return result

