def route_case(requester: dict, case: dict, agents: list[dict]) -> dict:
    if requester.get('tenant_id') != case.get('tenant_id') or (requester.get('id') != case.get('owner_id') and requester.get('role') != 'supervisor'):
        raise PermissionError('not allowed')
    eligible = [agent for agent in agents if agent.get('tenant_id') == case.get('tenant_id') and agent.get('active') and (case.get('language') in agent.get('languages', []))]
    if not eligible:
        raise ValueError('no eligible agent')
    selected = min(eligible, key=lambda agent: (agent.get('open_cases', 0), agent.get('agent_id', '')))
    result = case.copy()
    result['assigned_agent_id'] = selected['agent_id']
    return result

