import fnmatch
import os
import subprocess

def parse_save(data: str) -> dict[str, tuple[int, int, int]]:
    result = {}
    for raw in data.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        parts = [x.strip() for x in line.split('|')]
        if len(parts) != 4 or not parts[0]:
            raise ValueError('malformed save record')
        try:
            values = tuple((int(x) for x in parts[1:]))
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if any((x < 0 for x in values)):
            raise ValueError('negative value')
        if parts[0] in result:
            raise ValueError('duplicate slot')
        result[parts[0]] = values
    return result

def merge_saves(local, remote):
    result = {}
    for name in set(local) | set(remote):
        if name not in local:
            result[name] = remote[name]
        elif name not in remote:
            result[name] = local[name]
        else:
            result[name] = max(local[name], remote[name])
    return dict(sorted(result.items(), key=lambda item: (item[0].lower(), item[0])))

def sync_saves(directory: str, pattern: str='*.save'):
    if not os.path.isdir(directory):
        raise FileNotFoundError(directory)
    listing = subprocess.run(['find', directory, '-maxdepth', '1', '-type', 'f'], capture_output=True, text=True, check=True)
    combined = {}
    for raw in listing.stdout.splitlines():
        path = raw
        if not fnmatch.fnmatch(os.path.basename(path), pattern):
            continue
        with open(path, encoding='utf-8') as stream:
            records = parse_save(stream.read())
        combined = merge_saves(combined, records)
    return [(name, *values) for name, values in combined.items()]

