import csv
import os
import tempfile
from datetime import date
from decimal import Decimal, InvalidOperation
from collections.abc import Mapping

def _parse_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def normalize_grants(rows):
    result = []
    seen = set()
    for row in rows:
        if not isinstance(row, Mapping):
            raise ValueError('row')
        try:
            gid, employee, raw_date = (row['grant_id'], row['employee'], row['grant_date'])
            raw_shares, raw_price, status = (row['shares'], row['strike_price'], row['status'])
        except KeyError:
            raise ValueError('missing field')
        if not isinstance(gid, str) or not gid or (not isinstance(employee, str)) or (not employee):
            raise ValueError('text')
        if gid in seen or status not in ('active', 'cancelled'):
            raise ValueError('duplicate or status')
        d = _parse_date(raw_date)
        try:
            shares = int(raw_shares)
            if str(shares) != str(raw_shares).strip() or shares <= 0:
                raise ValueError
        except (ValueError, TypeError):
            raise ValueError('shares')
        try:
            price = Decimal(str(raw_price))
            if price < 0 or price.as_tuple().exponent < -2:
                raise ValueError
            price = price.quantize(Decimal('0.01'))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('price')
        seen.add(gid)
        result.append({'grant_id': gid, 'employee': employee, 'grant_date': d.isoformat(), 'shares': shares, 'strike_price': format(price, '.2f'), 'status': status})
    return sorted(result, key=lambda x: (x['employee'], x['grant_date'], x['grant_id']))

def summarize_grants(rows, as_of):
    cutoff = _parse_date(as_of)
    normalized = normalize_grants(rows)
    grouped = {}
    for grant in normalized:
        if grant['status'] != 'active':
            continue
        start = date.fromisoformat(grant['grant_date'])
        months = (cutoff.year - start.year) * 12 + cutoff.month - start.month
        if cutoff.day < start.day:
            months -= 1
        months = max(0, min(48, months))
        vested = grant['shares'] * months // 48
        item = grouped.setdefault(grant['employee'], [0, 0, 0, Decimal('0')])
        item[0] += 1
        item[1] += grant['shares']
        item[2] += vested
        item[3] += Decimal(vested) * Decimal(grant['strike_price'])
    output = []
    for employee in sorted(grouped):
        count, granted, vested, value = grouped[employee]
        output.append({'employee': employee, 'grants': count, 'granted_shares': granted, 'vested_shares': vested, 'unvested_shares': granted - vested, 'vested_value': format(value, '.2f')})
    return output

def export_grants_csv(rows, as_of, destination):
    summary = summarize_grants(rows, as_of)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory)
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.DictWriter(stream, fieldnames=['employee', 'grants', 'granted_shares', 'vested_shares', 'unvested_shares', 'vested_value'])
            writer.writeheader()
            writer.writerows(summary)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(summary)

