import hashlib
import hmac
import os

def create_reservation(passenger: str, origin: str, destination: str, seat: str, pin: str) -> dict:
    passenger = passenger.strip()
    origin = origin.strip()
    destination = destination.strip()
    seat = seat.strip().upper()
    if not passenger or not origin or (not destination) or (not seat) or (not pin):
        raise ValueError('fields must not be empty')
    if origin.lower() == destination.lower():
        raise ValueError('stations must differ')
    if not pin.isdecimal():
        raise ValueError('pin must contain digits')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'passenger': passenger, 'origin': origin, 'destination': destination, 'seat': seat, 'pin_hash': salt.hex() + ':' + digest.hex()}

def verify_reservation(reservation: dict, pin: str) -> bool:
    try:
        salt_text, digest_text = reservation['pin_hash'].split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

