from decimal import Decimal, ROUND_HALF_UP
from lxml import etree

def rank_applications(xml_text: str, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not isinstance(xml_text, str) or page <= 0 or page_size < 1 or (page_size > 100):
        raise ValueError('invalid arguments')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
        if root.tag != 'applications':
            raise ValueError('invalid root')
        rows = []
        for node in root.findall('application'):
            ident = (node.get('id') or '').strip()
            values = {}
            for name in ('student', 'college', 'status', 'gpa', 'household_income', 'requested'):
                child = node.find(name)
                if child is None or child.text is None or (not child.text.strip()):
                    raise ValueError('missing field')
                values[name] = child.text.strip()
            gpa = float(values['gpa'])
            income = float(values['household_income'])
            requested = float(values['requested'])
            if not ident or not 0 <= gpa <= 4 or income < 0 or (requested < 0):
                raise ValueError('invalid field')
            if values['status'].lower() != 'approved' or gpa < 2.5 or requested <= 0:
                continue
            need = max(0.0, 10000.0 - income * 0.05)
            award = float(Decimal(str(min(requested, need))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
            if award == 0:
                continue
            rows.append({'id': ident, 'student': values['student'], 'college': values['college'], 'gpa': gpa, 'award': award, 'score': gpa * 100 + award / 1000})
        rows.sort(key=lambda x: (-x['score'], x['id']))
        start = (page - 1) * page_size
        return rows[start:start + page_size]
    except ValueError:
        raise
    except (etree.XMLSyntaxError, TypeError, OverflowError):
        raise ValueError('invalid document')

