import csv
import subprocess

def refresh_dashboard(paths: list[str], category_field: str, value_field: str, top_n: int) -> dict:
    if not paths or not category_field or (not value_field) or (top_n < 1):
        raise ValueError('invalid dashboard arguments')
    totals = {}
    files = []
    total_rows = 0
    for path in paths:
        completed = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
        line_count = int(completed.stdout.strip().split()[0])
        rows = max(0, line_count - 1)
        with open(path, newline='', encoding='utf-8') as handle:
            reader = csv.DictReader(handle)
            if reader.fieldnames is None:
                raise ValueError('missing header')
            if category_field not in reader.fieldnames:
                raise KeyError(category_field)
            if value_field not in reader.fieldnames:
                raise KeyError(value_field)
            parsed_rows = 0
            for row in reader:
                name = row[category_field]
                try:
                    value = float(row[value_field])
                except (TypeError, ValueError) as exc:
                    raise ValueError('invalid number') from exc
                if name not in totals:
                    totals[name] = [0.0, 0]
                totals[name][0] += value
                totals[name][1] += 1
                parsed_rows += 1
        files.append({'path': path, 'rows': rows})
        total_rows += rows
    categories = [{'name': name, 'total': values[0], 'count': values[1]} for name, values in totals.items()]
    categories.sort(key=lambda item: (-item['total'], -item['count'], item['name']))
    return {'files': files, 'total_rows': total_rows, 'categories': categories[:top_n]}

