from datetime import date
from lxml import etree

def summarize_title_report(xml_text: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be a string')
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('page and page_size must be positive integers')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    groups = {}
    for prop in root.findall('property'):
        parcel = prop.get('parcel_id')
        if parcel is None:
            raise ValueError('missing parcel_id')
        item = groups.setdefault(parcel, {'total': Decimal('0'), 'count': 0, 'holders': set(), 'latest': None})
        for lien in prop.findall('lien'):
            if lien.get('status') != 'active':
                continue
            try:
                amount = Decimal(lien.get('amount'))
                recorded = date.fromisoformat(lien.get('recorded'))
            except (InvalidOperation, TypeError, ValueError) as exc:
                raise ValueError('invalid lien') from exc
            holder = lien.get('holder')
            if holder is None:
                raise ValueError('missing holder')
            item['total'] += amount
            item['count'] += 1
            item['holders'].add(holder)
            if item['latest'] is None or recorded > item['latest']:
                item['latest'] = recorded
    result = []
    for parcel, item in groups.items():
        if item['count']:
            total = item['total'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            result.append({'parcel_id': parcel, 'total_amount': format(total, '.2f'), 'lien_count': item['count'], 'holders': sorted(item['holders']), 'latest_recorded': item['latest'].isoformat()})
    result.sort(key=lambda x: (-Decimal(x['total_amount']), x['parcel_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

