from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import datetime
import html
import re
_Q = Decimal('0.01')

def parse_charges(text: str) -> list[dict]:
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        parts = line.split('|')
        if len(parts) != 6:
            raise ValueError(f'line {number}')
        tenant, unit, period, category, raw, status = parts
        if not tenant or not unit or (not category) or (status not in {'PAID', 'DUE'}):
            raise ValueError(f'line {number}')
        if not re.fullmatch('\\d{4}-\\d{2}', period):
            raise ValueError(f'line {number}')
        try:
            datetime.strptime(period, '%Y-%m')
            amount = Decimal(raw)
        except (ValueError, InvalidOperation):
            raise ValueError(f'line {number}')
        if amount < 0 or amount.as_tuple().exponent < -2:
            raise ValueError(f'line {number}')
        result.append({'tenant': tenant, 'unit': unit, 'period': period, 'category': category, 'amount': amount, 'status': status})
    return result

def summarize_tenant(records: list[dict], tenant: str) -> dict:
    chosen = [r for r in records if r['tenant'] == tenant]
    if not chosen:
        raise ValueError('no matching records')
    groups = {}
    for record in chosen:
        group = groups.setdefault(record['category'], [Decimal('0'), 0])
        group[0] += record['amount']
        group[1] += 1
    categories = [{'category': k, 'amount': v[0].quantize(_Q, ROUND_HALF_UP), 'entries': v[1]} for k, v in groups.items()]
    categories.sort(key=lambda x: (-x['amount'], x['category']))
    total = sum((r['amount'] for r in chosen), Decimal('0')).quantize(_Q, ROUND_HALF_UP)
    due = sum((r['amount'] for r in chosen if r['status'] == 'DUE'), Decimal('0')).quantize(_Q, ROUND_HALF_UP)
    return {'tenant': tenant, 'units': sorted({r['unit'] for r in chosen}), 'periods': sorted({r['period'] for r in chosen}), 'total': total, 'outstanding': due, 'categories': categories}

def render_statement(summary: dict) -> str:
    required = {'tenant', 'units', 'periods', 'total', 'outstanding', 'categories'}
    if not required.issubset(summary) or not isinstance(summary['categories'], list):
        raise ValueError('invalid summary')
    esc = lambda value: html.escape(str(value), quote=True)
    rows = ''.join((f"<tr><td>{esc(c['category'])}</td><td>{c['amount']:.2f}</td><td>{c['entries']}</td></tr>" for c in summary['categories']))
    return f"""<div class="statement"><h1>Tenant: {esc(summary['tenant'])}</h1><p>Units: {esc(', '.join(summary['units']))}</p><p>Periods: {esc(', '.join(summary['periods']))}</p><p>Total: {summary['total']:.2f}</p><p>Outstanding: {summary['outstanding']:.2f}</p><table><thead><tr><th>Category</th><th>Amount</th><th>Entries</th></tr></thead><tbody>{rows}</tbody></table></div>"""

