import json
import os
import tempfile
import zipfile


def make_bundle(files):
    handle = tempfile.NamedTemporaryFile(suffix=".zip", delete=False)
    handle.close()
    with zipfile.ZipFile(handle.name, "w") as archive:
        for name, value in files.items():
            archive.writestr(name, json.dumps(value))
    return handle.name


def test_empty_selection_returns_empty_summary():
    archive = make_bundle({"scan.json": {"vulnerabilities": [{"severity": "HIGH"}]}})
    try:
        with tempfile.TemporaryDirectory() as output:
            assert process_scan_bundle(archive, output, []) == {
                "files": [],
                "total": 0,
                "counts": {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0, "UNKNOWN": 0},
            }
    finally:
        os.unlink(archive)


def test_aggregates_severities_and_preserves_file_order():
    archive = make_bundle({
        "z.json": {"vulnerabilities": [{"severity": "low"}, {"severity": "critical"}]},
        "nested/a.json": {"vulnerabilities": [{"severity": "HIGH"}, {"severity": "weird"}]},
    })
    try:
        with tempfile.TemporaryDirectory() as output:
            result = process_scan_bundle(archive, output, ["nested/a.json", "z.json"])
            assert result == {
                "files": ["nested/a.json", "z.json"],
                "total": 4,
                "counts": {"CRITICAL": 1, "HIGH": 1, "MEDIUM": 0, "LOW": 1, "UNKNOWN": 1},
            }
            assert os.path.isfile(os.path.join(output, "nested", "a.json"))
            assert os.path.isfile(os.path.join(output, "z.json"))
    finally:
        os.unlink(archive)


def test_duplicate_members_are_processed_once():
    archive = make_bundle({"report.json": {"vulnerabilities": [{"severity": "MEDIUM"}]}})
    try:
        with tempfile.TemporaryDirectory() as output:
            result = process_scan_bundle(archive, output, ["report.json", "report.json"])
            assert result["files"] == ["report.json"]
            assert result["total"] == 1
            assert result["counts"]["MEDIUM"] == 1
    finally:
        os.unlink(archive)


def test_missing_member_raises_key_error():
