import json
import os
import zipfile

def process_scan_bundle(archive_path: str, output_dir: str, requested_members: list[str]) -> dict[str, object]:
    order = [name for index, name in enumerate(requested_members) if name not in requested_members[:index]]
    names = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'UNKNOWN']
    counts = {name: 0 for name in names}
    if not order:
        return {'files': [], 'total': 0, 'counts': counts}
    base = os.path.realpath(output_dir)
    with zipfile.ZipFile(archive_path) as archive:
        available = set(archive.namelist())
        for member in order:
            if member not in available:
                raise KeyError(member)
            destination = os.path.realpath(os.path.join(base, member))
            if os.path.commonpath([base, destination]) != base:
                raise ValueError(member)
            parent = os.path.dirname(destination)
            os.makedirs(parent, exist_ok=True)
            with archive.open(member) as source, open(destination, 'wb') as target:
                target.write(source.read())
            try:
                with open(destination, encoding='utf-8') as stream:
                    report = json.load(stream)
            except (json.JSONDecodeError, UnicodeDecodeError) as error:
                raise ValueError(member) from error
            if not isinstance(report, dict) or not isinstance(report.get('vulnerabilities'), list):
                raise ValueError(member)
            for item in report['vulnerabilities']:
                if not isinstance(item, dict):
                    raise ValueError(member)
                severity = item.get('severity')
                severity = severity.upper() if isinstance(severity, str) else 'UNKNOWN'
                if severity not in counts:
                    severity = 'UNKNOWN'
                counts[severity] += 1
    return {'files': order, 'total': sum(counts.values()), 'counts': counts}

