import secrets
from datetime import datetime, timezone

def generate_tracking_token(prefix: str='FT', length: int=20) -> str:
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    if not isinstance(prefix, str) or not 2 <= len(prefix) <= 6 or any((c not in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789' for c in prefix)):
        raise ValueError('invalid prefix')
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 64):
        raise ValueError('invalid length')
    return prefix + '_' + ''.join((secrets.choice(alphabet) for _ in range(length)))

def parse_tracking_line(line: str) -> dict:
    if not isinstance(line, str):
        raise ValueError('line must be a string')
    fields = []
    current = []
    i = 0
    while i < len(line):
        char = line[i]
        if char == '\\':
            i += 1
            if i == len(line) or line[i] not in '\\|':
                raise ValueError('invalid escape')
            current.append(line[i])
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
        i += 1
    fields.append(''.join(current))
    if len(fields) != 4 or not fields[0] or (not fields[3]):
        raise ValueError('invalid fields')
    if fields[2] not in {'IN_TRANSIT', 'DELIVERED', 'EXCEPTION'}:
        raise ValueError('invalid status')
    value = fields[1]
    try:
        timestamp = datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if timestamp.tzinfo is None or timestamp.utcoffset() is None:
        raise ValueError('timestamp must include timezone')
    return {'shipment_id': fields[0], 'timestamp': timestamp, 'status': fields[2], 'location': fields[3]}

def consolidate_tracking_events(lines: list[str]) -> list[dict]:
    grouped = {}
    for line in lines:
        if not isinstance(line, str):
            raise ValueError('line must be a string')
        if not line.strip():
            continue
        event = parse_tracking_line(line)
        sid = event['shipment_id']
        if sid not in grouped:
            grouped[sid] = {'events': [], 'route': []}
        group = grouped[sid]
        group['events'].append(event)
        if not group['route'] or group['route'][-1] != event['location']:
            group['route'].append(event['location'])
    result = []
    for sid, group in grouped.items():
        events = group['events']
        latest = max(enumerate(events), key=lambda pair: (pair[1]['timestamp'], pair[0]))[1]
        first_seen = min((e['timestamp'] for e in events))
        result.append({'shipment_id': sid, 'status': latest['status'], 'location': latest['location'], 'event_count': len(events), 'route': group['route'], 'first_seen': first_seen, 'last_seen': latest['timestamp'], 'exception_count': sum((e['status'] == 'EXCEPTION' for e in events))})
