        raise ValueError('root')
    result = {'id': _text(root.get('id'), 'id'), 'commit': _text(root.get('commit'), 'commit'), 'created': _text(root.get('created'), 'created'), 'artifacts': [], 'dependencies': []}
    for child in root:
        if child.tag == 'artifact':
            item = {}
            for key in ('name', 'path', 'sha256'):
                item[key] = _text(child.get(key), key)
            raw_size = _text(child.get('size'), 'size')
            try:
                item['size'] = int(raw_size, 10)
            except Exception as exc:
                raise ValueError('size') from exc
            if item['size'] < 0:
                raise ValueError('size')
            for key in ('platform', 'kind'):
                if child.get(key) is not None:
                    item[key] = child.get(key)
            result['artifacts'].append(item)
        elif child.tag == 'dependency':
            result['dependencies'].append({'name': _text(child.get('name'), 'name'), 'version': _text(child.get('version'), 'version')})
    result['artifacts'].sort(key=lambda x: (x['name'], x['path']))
    result['dependencies'].sort(key=lambda x: (x['name'], x['version']))
    return result

