            raise ValueError('duplicate build')
        seen.add(build_id)
        for artifact in manifest['artifacts']:
            name = artifact['name']
            if name not in totals:
                totals[name] = {'name': name, 'count': 0, 'total_size': 0, 'builds': []}
            entry = totals[name]
            entry['count'] += 1
            entry['total_size'] += artifact['size']
            if build_id not in entry['builds']:
                entry['builds'].append(build_id)
    return [totals[name] for name in sorted(totals)]

