    selected = []
    for artifact in manifest.get('artifacts', []):
        if platform is not None and artifact.get('platform') != platform:
            continue
        if kind is not None and artifact.get('kind') != kind:
            continue
        selected.append(artifact)
    return sorted(selected, key=lambda x: (-x['size'], x['name'], x['path']))

