from datetime import datetime

def _split_line(line):
    parts = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            parts.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    parts.append(''.join(current).strip())
    return parts

def parse_docket(text: str) -> list[dict]:
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        parts = _split_line(line)
        if len(parts) != 3 or not parts[0] or (not parts[1]) or (not parts[2]):
            raise ValueError('malformed docket line')
        fields = parts[0].split()
        if len(fields) != 2:
            raise ValueError('malformed date')
        try:
            datetime.strptime(parts[0], '%Y-%m-%d %H:%M')
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        result.append({'date': fields[0], 'time': fields[1], 'type': parts[1].upper(), 'description': parts[2]})
    if not result:
        raise ValueError('empty docket')
    return result

def summarize_docket(entries: list[dict]) -> dict:
    counts = {}
    months = {}
    for entry in entries:
        if set(entry) != {'date', 'time', 'type', 'description'} or not all((isinstance(entry[k], str) and entry[k] for k in entry)):
            raise ValueError('invalid entry')
        try:
            datetime.strptime(entry['date'] + ' ' + entry['time'], '%Y-%m-%d %H:%M')
        except ValueError as exc:
            raise ValueError('invalid entry') from exc
        counts[entry['type']] = counts.get(entry['type'], 0) + 1
        month = entry['date'][:7]
        months[month] = months.get(month, 0) + 1
    ordered = list(enumerate(entries))
    first = min(ordered, key=lambda x: (x[1]['date'], x[1]['time'], x[0]))[1] if entries else None
    last = max(ordered, key=lambda x: (x[1]['date'], x[1]['time'], -x[0]))[1] if entries else None
    return {'total': len(entries), 'by_type': dict(sorted(counts.items())), 'by_month': dict(sorted(months.items())), 'first': first, 'last': last}

