            inside = os.path.commonpath([case_root, path]) == case_root
        except ValueError:
            inside = False
        if not inside:
            raise ValueError('invalid document name')
        os.makedirs(os.path.dirname(path), exist_ok=True)
        mode = 'w' if isinstance(value, str) else 'wb'
        with open(path, mode, encoding='utf-8' if mode == 'w' else None) as handle:
