from lxml import etree

def parse_registration(xml: str) -> dict:
    if not isinstance(xml, str):
        raise ValueError('invalid XML')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeError):
        raise ValueError('invalid XML')
    if root.tag != 'registration':
        raise ValueError('invalid root')
    children = list(root)
    if len(children) != 4 or [x.tag for x in children] != ['domain', 'registrant', 'years', 'nameservers']:
        raise ValueError('invalid structure')
    domain, registrant, years_node, nameservers = children
    values = [domain.text, registrant.text]
    if any((value is None or not value.strip() for value in values)):
        raise ValueError('empty value')
    if years_node.text is None:
        raise ValueError('invalid years')
    try:
        years = int(years_node.text.strip())
    except ValueError:
        raise ValueError('invalid years')
    if years < 1 or years > 10 or len(years_node) != 0:
        raise ValueError('invalid years')
    servers = list(nameservers)
