    except ValueError:
        raise ValueError('invalid timestamp')
    return value

def parse_access_log(xml_text: str) -> list[dict[str, object]]:
    if not isinstance(xml_text, str) or not xml_text.strip():
        raise ValueError('invalid XML')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'access-log' or not root.get('building', '').strip():
        raise ValueError('invalid root')
    result = []
    ids = set()
    for node in root:
        if node.tag != 'event':
            raise ValueError('unexpected element')
        attrs = {k: node.get(k) for k in ('id', 'user', 'door', 'ts', 'result')}
        if any((not isinstance(v, str) or not v.strip() for v in attrs.values())):
            raise ValueError('missing attribute')
        if attrs['result'] not in ('granted', 'denied') or attrs['id'] in ids:
            raise ValueError('invalid event')
        _time(attrs['ts'])
        ids.add(attrs['id'])
        duration = 0
        reason = ''
        zones = []
        seen = set()
        for child in node:
            if child.tag not in ('duration', 'reason', 'zones') or child.tag in seen:
                raise ValueError('invalid child')
            seen.add(child.tag)
            if child.tag == 'duration':
                text = (child.text or '').strip()
                if not text.isdigit():
                    raise ValueError('invalid duration')
                duration = int(text)
            elif child.tag == 'reason':
                reason = (child.text or '').strip()
            else:
                for zone in child:
                    if zone.tag != 'zone' or not zone.get('name', '').strip() or zone.get('name') in zones:
                        raise ValueError('invalid zone')
                    zones.append(zone.get('name'))
        result.append({'id': attrs['id'], 'user': attrs['user'].strip(), 'door': attrs['door'].strip(), 'timestamp': attrs['ts'], 'result': attrs['result'], 'duration': duration, 'reason': reason, 'zones': sorted(zones)})
    return result

def summary_access(events: list[dict[str, object]], start: str, end: str) -> dict[str, object]:
    _time(start)
    _time(end)
    if start > end:
        raise ValueError('invalid window')
    counts = {'granted': 0, 'denied': 0}
    doors = {}
    users = {}
    for event in events:
        if not isinstance(event, dict) or set(event) != {'id', 'user', 'door', 'timestamp', 'result', 'duration', 'reason', 'zones'}:
            raise ValueError('invalid event')
        _time(event['timestamp'])
        if event['result'] not in counts or not isinstance(event['user'], str) or (not isinstance(event['door'], str)):
            raise ValueError('invalid event')
        if start <= event['timestamp'] <= end:
            counts[event['result']] += 1
            bucket = doors.setdefault(event['door'], {'granted': 0, 'denied': 0})
            bucket[event['result']] += 1
            users[event['user']] = users.get(event['user'], 0) + 1
    top = min(users, key=lambda u: (-users[u], u)) if users else None
    return {'granted': counts['granted'], 'denied': counts['denied'], 'by_door': dict(sorted(doors.items())), 'top_user': top}

