import math
import secrets
from datetime import date
_ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def parse_harvest_log(text: str) -> list[tuple[str, str, float]]:
    rows = list(csv.reader((line for line in text.splitlines() if line.strip())))
    if not rows or [x.strip() for x in rows[0]] != ['date', 'field', 'yield']:
        raise ValueError('invalid header')
    seen = set()
    result = []
    for row in rows[1:]:
        if len(row) != 3:
            raise ValueError('invalid row')
        stamp, field, raw = (x.strip() for x in row)
        try:
            date.fromisoformat(stamp)
            value = float(raw)
        except (ValueError, TypeError):
            raise ValueError('invalid value')
        if len(stamp) != 10 or not field or (not math.isfinite(value)) or (value < 0):
            raise ValueError('invalid value')
        key = (stamp, field)
        if key in seen:
            raise ValueError('duplicate record')
        seen.add(key)
        result.append((stamp, field, value))
    return sorted(result, key=lambda item: (item[0], item[1]))

def forecast_by_field(records: list[tuple[str, str, float]], window: int=3) -> dict[str, list[dict[str, object]]]:
    if isinstance(window, bool) or not isinstance(window, int) or window < 1:
        raise ValueError('window must be positive')
    groups = {}
    for stamp, field, value in records:
        groups.setdefault(field, []).append((stamp, value))
    output = {}
    for field in sorted(groups):
        entries = sorted(groups[field], key=lambda item: item[0])
        values = []
        output[field] = []
        for stamp, value in entries:
            values.append(value)
            sample = values[-window:]
            output[field].append({'date': stamp, 'forecast': round(sum(sample) / len(sample), 2)})
    return output

def generate_share_code(length: int=12) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or length < 1:
        raise ValueError('length must be positive')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def build_forecast_report(text: str, window: int=3, code_length: int=12) -> dict[str, object]:
    records = parse_harvest_log(text)
    return {'share_code': generate_share_code(code_length), 'window': window, 'fields': forecast_by_field(records, window)}

