import csv
import math
import os
import tempfile
from decimal import Decimal, ROUND_HALF_UP

def _number(value, positive=False):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)):
        raise ValueError('invalid number')
    if positive and value <= 0:
        raise ValueError('invalid number')
    if not positive and value < 0:
        raise ValueError('invalid number')
    return Decimal(str(value))

def write_purchase_order(ingredients: list[dict], destination: str, min_quantity: float=0) -> list[dict]:
    threshold = _number(min_quantity)
    rows = []
    for item in ingredients:
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        supplier = item.get('supplier')
        name = item.get('name')
        if not isinstance(supplier, str) or not supplier or (not isinstance(name, str)) or (not name):
            raise ValueError('invalid record')
        quantity = _number(item.get('quantity'), True)
        price = _number(item.get('unit_price'))
        if quantity < threshold:
            continue
        rows.append((supplier, name, quantity, price))
    rows.sort(key=lambda row: (row[0], row[1]))
    summaries = {}
    for supplier, name, quantity, price in rows:
        summaries.setdefault(supplier, Decimal('0'))
        summaries[supplier] += quantity * price
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.purchase-', suffix='.tmp', dir=parent, text=True)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['Supplier', 'Ingredient', 'Quantity', 'Unit Price', 'Line Total'])
            for supplier, name, quantity, price in rows:
                total = (quantity * price).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
                writer.writerow([supplier, name, str(quantity), str(price), f'{total:.2f}'])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return [{'supplier': supplier, 'quantity': float(sum((row[2] for row in rows if row[0] == supplier))), 'total': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for supplier, total in sorted(summaries.items())]

