def extract_and_rank_remediation_sites(archive_path: str, output_dir: str, min_ratio: float=0.0) -> list[dict]:
    if not math.isfinite(min_ratio) or min_ratio < 0:
        raise ValueError('invalid minimum ratio')
    base = Path(output_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            target = (base / member.filename).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('archive entry outside output directory')
            archive.extract(member, base)
    csv_path = base / 'data' / 'samples.csv'
    if not csv_path.is_file():
        raise ValueError('missing samples CSV')
