    with csv_path.open(newline='', encoding='utf-8') as handle:
        reader = csv.DictReader(handle)
        required = ['site', 'contaminant', 'concentration', 'threshold']
        if reader.fieldnames != required:
            raise ValueError('invalid CSV header')
        for row in reader:
            if any((value is None for value in row.values())) or not row['site']:
                raise ValueError('invalid sample row')
            try:
                concentration = float(row['concentration'])
                threshold = float(row['threshold'])
            except (TypeError, ValueError):
                raise ValueError('invalid measurement')
            if not math.isfinite(concentration) or not math.isfinite(threshold) or threshold <= 0 or (concentration < 0):
                raise ValueError('invalid measurement')
