import sqlite3
from datetime import datetime, timezone
import math

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        text = value[:-1] + '+00:00' if value.endswith('Z') else value
        dt = datetime.fromisoformat(text)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        dt = dt.astimezone(timezone.utc)
        return dt.strftime('%Y-%m-%dT%H:%M:%SZ')
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')

def initialize(conn):
    conn.execute('create table if not exists readings (id integer primary key, station text not null, observed_at text not null, temperature real not null, humidity real not null, unique(station, observed_at))')
    conn.commit()

def insert_readings(conn, records):
    values = []
    for r in records:
        station = r.get('station')
        if not isinstance(station, str) or not station.strip():
            raise ValueError('invalid station')
        temp, humidity = (r.get('temperature'), r.get('humidity'))
        if not isinstance(temp, (int, float)) or not math.isfinite(temp) or (not isinstance(humidity, (int, float))) or (not math.isfinite(humidity)) or (not 0 <= humidity <= 100):
            raise ValueError('invalid measurement')
        values.append((station.strip(), _time(r.get('observed_at')), float(temp), float(humidity)))
    with conn:
        conn.executemany('insert into readings(station, observed_at, temperature, humidity) values(?,?,?,?) on conflict(station, observed_at) do update set temperature=excluded.temperature, humidity=excluded.humidity', values)
    return len(values)

def query_readings(conn, station=None, start=None, end=None, order_by='observed_at', descending=False):
    allowed = {'observed_at', 'station', 'temperature', 'humidity', 'id'}
    if order_by not in allowed:
        raise ValueError('invalid order')
    clauses, args = ([], [])
    if station is not None:
        clauses.append('station = ?')
        args.append(station)
    if start is not None:
        clauses.append('observed_at >= ?')
        args.append(_time(start))
    if end is not None:
        clauses.append('observed_at <= ?')
        args.append(_time(end))
    where = ' where ' + ' and '.join(clauses) if clauses else ''
    direction = 'desc' if descending else 'asc'
    rows = conn.execute('select id, station, observed_at, temperature, humidity from readings' + where + ' order by ' + order_by + ' ' + direction + ', observed_at asc, id asc', args).fetchall()
    return [dict(zip(('id', 'station', 'observed_at', 'temperature', 'humidity'), r)) for r in rows]

def station_summary(conn):
    rows = conn.execute('select station, count(*), avg(temperature), min(temperature), max(temperature), avg(humidity) from readings group by station order by count(*) desc, station asc').fetchall()
    keys = ('station', 'count', 'average_temperature', 'minimum_temperature', 'maximum_temperature', 'average_humidity')
    return [dict(zip(keys, r)) for r in rows]

