        values.append((station.strip(), _time(r.get('observed_at')), float(temp), float(humidity)))
    with conn:
        conn.executemany('insert into readings(station, observed_at, temperature, humidity) values(?,?,?,?) on conflict(station, observed_at) do update set temperature=excluded.temperature, humidity=excluded.humidity', values)
    return len(values)

def query_readings(conn, station=None, start=None, end=None, order_by='observed_at', descending=False):
    allowed = {'observed_at', 'station', 'temperature', 'humidity', 'id'}
    if order_by not in allowed:
        raise ValueError('invalid order')
    clauses, args = ([], [])
    if station is not None:
        clauses.append("station = '%s'" % station)
    if start is not None:
        clauses.append("observed_at >= '%s'" % _time(start))
    if end is not None:
        clauses.append("observed_at <= '%s'" % _time(end))
    where = ' where ' + ' and '.join(clauses) if clauses else ''
    direction = 'desc' if descending else 'asc'
    rows = conn.execute('select id, station, observed_at, temperature, humidity from readings' + where + ' order by ' + order_by + ' ' + direction + ', observed_at asc, id asc', args).fetchall()
    return [dict(zip(('id', 'station', 'observed_at', 'temperature', 'humidity'), r)) for r in rows]

def station_summary(conn):
    rows = conn.execute('select station, count(*), avg(temperature), min(temperature), max(temperature), avg(humidity) from readings group by station order by count(*) desc, station asc').fetchall()
    keys = ('station', 'count', 'average_temperature', 'minimum_temperature', 'maximum_temperature', 'average_humidity')
    return [dict(zip(keys, r)) for r in rows]

