from datetime import date
import subprocess

def _split_record(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current))
    return fields

def _valid_date(value):
    try:
        date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if len(value) != 10:
        raise ValueError('invalid date')

def parse_work_orders(text: str) -> list[dict]:
    result = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_record(raw)
        if len(fields) != 6:
            raise ValueError('wrong field count')
        ident, technician, priority, hours, status, due = fields
        if not ident or not technician or ident in seen:
            raise ValueError('invalid identifier')
        try:
            priority = int(priority)
            hours = float(hours)
        except ValueError:
            raise ValueError('invalid number')
        if not 1 <= priority <= 5 or hours <= 0:
            raise ValueError('invalid number')
        if hours.is_integer():
            hours = int(hours)
        if status not in {'open', 'in_progress', 'completed'}:
            raise ValueError('invalid status')
        _valid_date(due)
        seen.add(ident)
        result.append({'id': ident, 'technician': technician, 'priority': priority, 'hours': hours, 'status': status, 'due': due})
    return result

def prioritize_work_orders(orders: list[dict], as_of: str) -> list[dict]:
    _valid_date(as_of)
    return sorted(orders, key=lambda x: (x['status'] == 'completed', x['status'] == 'completed' or x['due'] >= as_of, x['priority'], x['due'], x['id']))

def build_maintenance_report(path: str) -> list[dict]:
    try:
        completed = subprocess.run(['sort', '-t', '|', '-k6,6', '-k1,1', path], capture_output=True, text=True)
    except OSError:
        raise FileNotFoundError(path)
    if completed.returncode:
        raise FileNotFoundError(path)
    records = parse_work_orders(completed.stdout)
    grouped = {}
    for record in records:
        item = grouped.setdefault(record['technician'], {'technician': record['technician'], 'total_hours': 0, 'open': 0, 'next_due': None})
        item['total_hours'] += record['hours']
        if record['status'] != 'completed':
            item['open'] += 1
            if item['next_due'] is None or record['due'] < item['next_due']:
                item['next_due'] = record['due']
    return [grouped[name] for name in sorted(grouped)]

