def parse_jury_notifications(xml_text: str) -> list[dict[str, str]]:
    root = ET.fromstring(xml_text)
    if root.tag != 'notifications':
        raise ValueError('invalid root')
    notices = []
    required = ('id', 'date', 'recipient', 'court')
    for element in root.findall('notice'):
        if any((name not in element.attrib for name in required)):
            raise ValueError('missing notice attribute')
        notices.append({'id': element.attrib['id'], 'date': element.attrib['date'], 'recipient': element.attrib['recipient'], 'court': element.attrib['court'], 'message': ''.join(element.itertext()).strip()})
    notices.sort(key=lambda item: (item['date'], item['id']))
    return notices

