        super().__init__()
        self.root = None
        self.current = None
        self.text = []
        self.notices = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name == 'notice':
            self.current = dict(attrs)
            self.text = []

    def characters(self, content):
