import hashlib
import hmac
import json
import math

def summarize_diagnostics(payload: str, signature: str, shared_key: bytes, page: int=1, page_size: int=10) -> dict | None:
    if not isinstance(signature, str) or len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        return None
    expected = hmac.new(shared_key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return None
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        records = json.loads(payload)
    except (json.JSONDecodeError, UnicodeEncodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('payload must be a list')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'query', 'duration_ms', 'status'}:
            raise ValueError('invalid record')
        query = record['query']
        duration = record['duration_ms']
        status = record['status']
        if not isinstance(query, str) or not query or isinstance(duration, bool) or (not isinstance(duration, (int, float))) or (not math.isfinite(duration)) or (duration < 0) or (status not in {'ok', 'error', 'timeout'}):
            raise ValueError('invalid record')
        if query not in groups:
            groups[query] = []
        groups[query].append(duration)
    result = []
    for query, durations in groups.items():
        total = sum(durations)
        result.append({'query': query, 'count': len(durations), 'total_ms': round(total, 2), 'average_ms': round(total / len(durations), 2), 'max_ms': max(durations)})
    result.sort(key=lambda item: (-item['total_ms'], item['query']))
    start = (page - 1) * page_size
    return {'total_queries': len(result), 'page': page, 'page_size': page_size, 'queries': result[start:start + page_size]}

