def _record_ok(r):
    if not isinstance(r, dict) or set(r) != {'certificate_id', 'student_id', 'course_id', 'scores', 'average', 'honors', 'issued_at'}:
        return False
    if any((not isinstance(r[k], str) or not r[k].strip() for k in ('certificate_id', 'student_id', 'course_id', 'issued_at'))):
        return False
    scores = r['scores']
    if not isinstance(scores, dict) or not scores:
        return False
    if list(scores) != sorted(scores) or any((not isinstance(k, str) or not k for k in scores)):
        return False
    if any((isinstance(v, bool) or not isinstance(v, (int, float)) or v < 0 or (v > 100) for v in scores.values())):
        return False
    avg = float(Decimal(str(sum(scores.values()) / len(scores))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    return r['certificate_id'] == r['student_id'] + ':' + r['course_id'] and r['average'] == avg and (r['honors'] == (avg >= 90.0))

