    if not all((isinstance(x, str) and x.strip() for x in (student_id, course_id, issued_at))):
        raise ValueError('invalid text')
    if not isinstance(scores, dict) or not scores or any((not isinstance(k, str) or not k or isinstance(v, bool) or (not isinstance(v, (int, float))) or (v < 0) or (v > 100) for k, v in scores.items())):
        raise ValueError('invalid scores')
    clean = {k: scores[k] for k in sorted(scores)}
    avg = float(Decimal(str(sum(clean.values()) / len(clean))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    return {'certificate_id': student_id.strip() + ':' + course_id.strip(), 'student_id': student_id.strip(), 'course_id': course_id.strip(), 'scores': clean, 'average': avg, 'honors': avg >= 90.0, 'issued_at': issued_at.strip()}

def pack_certificates(certificates: list[dict]) -> bytes:
    if not isinstance(certificates, list) or not all((_record_ok(x) for x in certificates)):
        raise ValueError('invalid records')
    return json.dumps(certificates, separators=(',', ':'), allow_nan=False).encode()

def unpack_certificates(blob: bytes) -> list[dict]:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        value = json.loads(blob.decode())
    except Exception as e:
        raise ValueError('invalid blob') from e
    if not isinstance(value, list) or not all((_record_ok(x) for x in value)):
        raise ValueError('invalid records')
    return value

def rank_certificates(blob: bytes, course_id: str | None=None) -> list[str]:
    if course_id is not None and (not isinstance(course_id, str) or not course_id):
        raise ValueError('invalid course')
    rows = [x for x in unpack_certificates(blob) if course_id is None or x['course_id'] == course_id]
    rows.sort(key=lambda x: (-x['average'], x['issued_at'], x['student_id'], x['certificate_id']))
