import hashlib
import hmac
import json

def verify_manifest(payload: str, signature: str, secret: bytes) -> dict:
    if not isinstance(secret, bytes) or not isinstance(payload, str) or (not isinstance(signature, str)):
        raise ValueError('invalid input')
    try:
        value = json.loads(payload)
    except (TypeError, ValueError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(value, dict):
        raise ValueError('invalid payload')
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError('invalid signature')
    canonical = json.dumps(value, sort_keys=True, separators=(',', ':')).encode('utf-8')
    expected = hmac.new(secret, canonical, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    return value

def plan_route(manifest: dict, bus_id: str, start_minute: int=0) -> list[dict]:
    if not isinstance(manifest, dict) or not isinstance(bus_id, str) or type(start_minute) is not int or (start_minute < 0):
        raise ValueError('invalid route')
    buses = manifest.get('buses')
    stops = manifest.get('stops')
    if not isinstance(buses, dict) or not isinstance(stops, list) or bus_id not in buses:
        raise ValueError('invalid route')
    bus = buses[bus_id]
    if not isinstance(bus, dict) or type(bus.get('capacity')) is not int or bus['capacity'] <= 0:
        raise ValueError('invalid capacity')
    selected = []
    ids = set()
    for stop in stops:
        if not isinstance(stop, dict) or any((k not in stop for k in ('id', 'bus', 'minute', 'pickup', 'dropoff'))):
            raise ValueError('invalid stop')
        if not isinstance(stop['id'], str) or not isinstance(stop['bus'], str):
            raise ValueError('invalid stop')
        if stop['id'] in ids:
            raise ValueError('duplicate stop')
        ids.add(stop['id'])
        if any((type(stop[k]) is not int or stop[k] < 0 for k in ('minute', 'pickup', 'dropoff'))) or stop['minute'] > 1439:
            raise ValueError('invalid stop')
        if stop['bus'] == bus_id and stop['minute'] >= start_minute:
            selected.append(stop)
    selected.sort(key=lambda s: (s['minute'], s['id']))
    onboard = 0
    result = []
    for stop in selected:
        onboard -= stop['dropoff']
        if onboard < 0:
            raise ValueError('invalid passenger count')
        onboard += stop['pickup']
        if onboard > bus['capacity']:
            raise ValueError('capacity exceeded')
        result.append({'id': stop['id'], 'time': f"{stop['minute'] // 60:02d}:{stop['minute'] % 60:02d}", 'dropoff': stop['dropoff'], 'pickup': stop['pickup'], 'onboard': onboard})
    return result

