import csv
import datetime
import decimal
import subprocess

def build_permit_report(paths: list[str], district: str | None=None) -> dict:
    header = ['permit_id', 'applicant', 'district', 'status', 'fee', 'date']
    statuses = ['approved', 'pending', 'rejected', 'withdrawn']
    seen = set()
    rows = []
    source_lines = 0
    for path in paths:
        completed = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
        source_lines += int(completed.stdout.split()[0])
        with open(path, newline='', encoding='utf-8') as handle:
            reader = csv.reader(handle)
            try:
                actual = next(reader)
            except StopIteration:
                raise ValueError('missing header')
            if actual != header:
                raise ValueError('invalid header')
            for row in reader:
                if len(row) != 6:
                    raise ValueError('invalid row')
                permit, applicant, area, status, fee_text, date_text = [value.strip() for value in row]
                if not permit or not applicant or (not area) or (permit in seen):
                    raise ValueError('invalid permit')
                if status not in statuses:
                    raise ValueError('invalid status')
                try:
                    fee = decimal.Decimal(fee_text)
                except decimal.InvalidOperation:
                    raise ValueError('invalid fee')
                if fee < 0 or fee.as_tuple().exponent < -2:
                    raise ValueError('invalid fee')
                try:
                    date = datetime.date.fromisoformat(date_text)
                except ValueError:
                    raise ValueError('invalid date')
                seen.add(permit)
                if district is None or area == district:
                    rows.append((permit, area, status, fee, date))
    groups = {}
    for permit, area, status, fee, date in rows:
        group = groups.setdefault(area, {'count': 0, 'fee': decimal.Decimal('0'), 'statuses': {name: 0 for name in statuses}})
        group['count'] += 1
        group['fee'] += fee
        group['statuses'][status] += 1
    by_district = [{'district': area, 'count': groups[area]['count'], 'fee': float(groups[area]['fee'].quantize(decimal.Decimal('0.01'))), 'statuses': groups[area]['statuses']} for area in sorted(groups)]
    latest = max(rows, key=lambda item: (item[4], item[0]))[0] if rows else None
    total = sum((item[3] for item in rows), decimal.Decimal('0'))
    return {'files': len(paths), 'source_lines': source_lines, 'applications': len(rows), 'total_fee': float(total.quantize(decimal.Decimal('0.01'))), 'by_district': by_district, 'latest': latest}

