from datetime import datetime

def initialize_db(conn):
    conn.execute('CREATE TABLE IF NOT EXISTS programs (id INTEGER PRIMARY KEY, day TEXT NOT NULL, start TEXT NOT NULL, duration INTEGER NOT NULL, title TEXT NOT NULL, host TEXT NOT NULL, genre TEXT NOT NULL)')
    conn.commit()

def _clock(value):
    try:
        datetime.strptime(value, '%H:%M')
    except (TypeError, ValueError):
        raise ValueError()
    return int(value[:2]) * 60 + int(value[3:])

def _day(value):
    try:
        datetime.strptime(value, '%Y-%m-%d')
    except (TypeError, ValueError):
        raise ValueError()

def _validate(day, start, duration):
    if not isinstance(day, str) or not day.strip() or (not isinstance(start, str)) or (not start.strip()) or (not isinstance(duration, int)) or isinstance(duration, bool) or (not 1 <= duration <= 1440):
        raise ValueError()
    day = day.strip()
    start = start.strip()
    _day(day)
    _clock(start)
    return (day, start, duration)

def schedule_program(conn, day, start, duration, title, host, genre):
    day, start, duration = _validate(day, start, duration)
    vals = []
    for value in (title, host, genre):
        if not isinstance(value, str) or not value.strip():
            raise ValueError()
        vals.append(value.strip())
    cur = conn.execute('INSERT INTO programs(day,start,duration,title,host,genre) VALUES (?,?,?,?,?,?)', (day, start, duration, *vals))
    conn.commit()
    return cur.lastrowid

def _row(row):
    start = _clock(row[2])
    end = (start + row[3]) % 1440
    return {'id': row[0], 'day': row[1], 'start': row[2], 'duration': row[3], 'title': row[4], 'host': row[5], 'genre': row[6], 'end': f'{end // 60:02d}:{end % 60:02d}'}

def find_programs(conn, day=None, search='', sort_by='start'):
    if day is not None:
        _day(day)
    if sort_by not in ('start', 'title', 'genre', 'duration'):
        raise ValueError()
    clauses, args = ([], [])
    if day is not None:
        clauses.append('day=?')
        args.append(day)
    if search:
        clauses.append('(lower(title) LIKE lower(?) OR lower(host) LIKE lower(?))')
        args.extend(['%' + search + '%'] * 2)
    order = {'start': 'start', 'title': 'title', 'genre': 'genre', 'duration': 'duration'}[sort_by]
    sql = 'SELECT id,day,start,duration,title,host,genre FROM programs'
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    sql += ' ORDER BY ' + order + ', day, start, title, id'
    return [_row(r) for r in conn.execute(sql, args)]

def reschedule_program(conn, program_id, new_day, new_start):
    if not isinstance(program_id, int) or isinstance(program_id, bool):
        raise ValueError()
    new_day, new_start, _ = _validate(new_day, new_start, 1)
    row = conn.execute('SELECT id,day,start,duration,title,host,genre FROM programs WHERE id=?', (program_id,)).fetchone()
    if row is None:
        raise KeyError(program_id)
    begin = _clock(new_start)
    finish = begin + row[3]
    for other in conn.execute('SELECT start,duration FROM programs WHERE day=? AND id<>?', (new_day, program_id)):
        ob = _clock(other[0])
        if begin < ob + other[1] and ob < finish:
            raise ValueError()
    conn.execute('UPDATE programs SET day=?,start=? WHERE id=?', (new_day, new_start, program_id))
    conn.commit()
    return _row((row[0], new_day, new_start, row[3], row[4], row[5], row[6]))

