_STATUSES = {'pending', 'ordered', 'delivered', 'cancelled'}

def parse_orders(text: str) -> list[dict]:
    if not text.strip():
        return []
    reader = csv.reader(StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        return []
    if header != _HEADER:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != len(_HEADER):
            raise ValueError('invalid row')
        values = [x.strip() for x in row]
        if any((not values[i] for i in (0, 1, 2, 3, 7))):
            raise ValueError('blank field')
        try:
            quantity = int(values[4])
            delivery = int(values[6])
            price = Decimal(values[5]).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid number')
        if quantity <= 0 or delivery <= 0 or price < 0 or (values[7] not in _STATUSES):
            raise ValueError('invalid value')
        result.append({'project': values[0], 'room': values[1], 'vendor': values[2], 'item': values[3], 'quantity': quantity, 'unit_price': float(price), 'delivery_days': delivery, 'status': values[7]})
    return result

def summarize_orders(records: list[dict]) -> list[dict]:
    groups = {}
    for r in records:
        if r['status'] == 'cancelled':
            continue
        key = (r['project'], r['room'], r['vendor'])
        if key not in groups:
            groups[key] = {'project': key[0], 'room': key[1], 'vendor': key[2], 'quantity': 0, 'total': Decimal('0'), 'max_delivery_days': 0, 'items': set()}
        g = groups[key]
        g['quantity'] += r['quantity']
        g['total'] += Decimal(str(r['unit_price'])) * r['quantity']
        g['max_delivery_days'] = max(g['max_delivery_days'], r['delivery_days'])
        g['items'].add(r['item'])
    out = []
    for g in sorted(groups.values(), key=lambda x: (x['project'], x['room'], x['vendor'])):
        out.append({'project': g['project'], 'room': g['room'], 'vendor': g['vendor'], 'quantity': g['quantity'], 'total_cost': float(g['total'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'max_delivery_days': g['max_delivery_days'], 'items': sorted(g['items'])})
    return out

def export_report(text: str, output_path: str) -> list[dict]:
    summaries = summarize_orders(parse_orders(text))
    directory = os.path.dirname(os.path.abspath(output_path))
    temporary = tempfile.mktemp(prefix='report-', dir=directory)
    try:
        with open(temporary, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['project', 'room', 'vendor', 'quantity', 'total_cost', 'max_delivery_days', 'items'])
            for s in summaries:
                writer.writerow([s['project'], s['room'], s['vendor'], s['quantity'], f"{s['total_cost']:.2f}", s['max_delivery_days'], '|'.join(s['items'])])
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return summaries

