import csv
import io
import json
import re

def parse_asset_reference(reference: str) -> tuple[str, int | None]:
    if not isinstance(reference, str) or not reference:
        raise ValueError('invalid reference')
    parts = reference.split('@')
    if len(parts) > 2 or not re.fullmatch('[A-Za-z0-9_.-]+', parts[0]):
        raise ValueError('invalid reference')
    if len(parts) == 1:
        return (parts[0], None)
    if not parts[1].isdigit() or int(parts[1]) <= 0:
        raise ValueError('invalid reference')
    return (parts[0], int(parts[1]))

def _allowed(requester, asset):
    roles = set(requester.get('roles', []))
    return asset['tenant_id'] == requester['tenant_id'] and (asset['owner_id'] == requester['user_id'] or bool(roles & {'editor', 'admin', 'asset_manager'}))

def select_asset_versions(requester: dict, assets: list[dict], references: list[str]) -> list[dict]:
    by_id = {}
    for asset in assets:
        if asset['asset_id'] in by_id:
            raise ValueError('duplicate asset')
        versions = {}
        for version in asset['versions']:
            if version['version'] in versions:
                raise ValueError('duplicate version')
            versions[version['version']] = version
        by_id[asset['asset_id']] = (asset, versions)
    result = []
    for reference in references:
        asset_id, wanted = parse_asset_reference(reference)
        if asset_id not in by_id:
            raise KeyError(asset_id)
        asset, versions = by_id[asset_id]
        if not _allowed(requester, asset):
            raise PermissionError(asset_id)
        number = max(versions) if wanted is None and versions else wanted
        if number not in versions:
            raise KeyError((asset_id, number))
        value = versions[number]
        result.append({'asset_id': asset['asset_id'], 'tenant_id': asset['tenant_id'], 'owner_id': asset['owner_id'], 'version': value['version'], 'path': value['path'], 'size': value['size'], 'sha256': value['sha256'], 'tags': list(value['tags'])})
    return result

def build_manifest(requester: dict, assets: list[dict], references: list[str], output_format: str='json') -> str:
    selected = select_asset_versions(requester, assets, references)
    selected.sort(key=lambda x: (x['path'].lower(), x['path'], x['asset_id'], x['version']))
    total = sum((x['size'] for x in selected))
    if output_format == 'json':
        return json.dumps({'assets': selected, 'total_size': total}, separators=(',', ':'))
    if output_format != 'csv':
        raise ValueError('invalid output format')
    stream = io.StringIO()
    writer = csv.writer(stream, lineterminator='\n')
    writer.writerow(['asset_id', 'tenant_id', 'owner_id', 'version', 'path', 'size', 'sha256', 'tags'])
    for x in selected:
        writer.writerow([x['asset_id'], x['tenant_id'], x['owner_id'], x['version'], x['path'], x['size'], x['sha256'], ';'.join(x['tags'])])
    return stream.getvalue()

