import csv
import datetime
import os
import statistics
import tempfile

def _date(value):
    if not isinstance(value, str) or len(value) != 10:
        raise ValueError('invalid date')
    try:
        parsed = datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def summarize_records(records, start_date, end_date):
    start, end = (_date(start_date), _date(end_date))
    if start > end:
        raise ValueError('invalid range')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            species, admitted, outcome = (record['species'], record['admitted'], record['outcome'])
        except KeyError:
            raise ValueError('missing field')
        if not isinstance(species, str) or not species or outcome not in ('released', 'transferred', 'deceased'):
            raise ValueError('invalid record')
        admitted = _date(admitted)
        released = record.get('released')
        if released is not None:
            released = _date(released)
            if released < admitted:
                raise ValueError('invalid interval')
        if outcome in ('released', 'transferred') and released is None:
            raise ValueError('missing release')
        weight = record.get('weight_g')
        if weight is not None and (isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight < 0):
            raise ValueError('invalid weight')
        if not start <= admitted <= end:
            continue
        group = groups.setdefault(species, {'weights': [], 'days': [], 'counts': {'released': 0, 'transferred': 0, 'deceased': 0}})
        group['counts'][outcome] += 1
        if weight is not None:
            group['weights'].append(weight)
        if released is not None:
            group['days'].append((released - admitted).days)
    result = []
    for species in sorted(groups):
        group = groups[species]
        weights, days, counts = (group['weights'], group['days'], group['counts'])
        result.append({'species': species, 'admitted_count': sum(counts.values()), 'released_count': counts['released'], 'transferred_count': counts['transferred'], 'deceased_count': counts['deceased'], 'average_weight_g': round(sum(weights) / len(weights), 2) if weights else None, 'median_rehab_days': float(statistics.median(days)) if days else None})
    return result

def export_report(records, destination, start_date, end_date):
    rows = summarize_records(records, start_date, end_date)
    fields = ['species', 'admitted_count', 'released_count', 'transferred_count', 'deceased_count', 'average_weight_g', 'median_rehab_days']
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.report-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.DictWriter(stream, fieldnames=fields)
            writer.writeheader()
            for row in rows:
                writer.writerow(row)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

