import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float, str, bool)) or node.value is None:
            return node.value
        raise ValueError()
    if isinstance(node, ast.Name):
        if node.id in names:
            return names[node.id]
        raise ValueError()
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        x = _value(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](x)
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod}:
        a, b = (_value(node.left, names), _value(node.right, names))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv, ast.Mod: operator.mod}[type(node.op)](a, b)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _value(node.values[0], names)
        for part in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _value(part, names)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
        for op, right_node in zip(node.ops, node.comparators):
            if type(op) not in ops:
                raise ValueError()
            right = _value(right_node, names)
            if not ops[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        args = [_value(x, names) for x in node.args]
        if node.func.id == 'round' and len(args) not in (1, 2):
            raise ValueError()
        if node.func.id in {'min', 'max'} and len(args) < 2:
            raise ValueError()
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
    raise ValueError()

def access_report(logs: list[dict], rule: str, variables: dict[str, int | float | bool] | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError()
    try:
        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError() from exc
    selected = []
    for record in logs:
        names = dict(variables or {})
        names.update({k: record[k] for k in ('employee', 'door', 'timestamp', 'granted', 'duration')})
        try:
            if _value(tree, names):
                selected.append(record)
        except Exception as exc:
            raise ValueError() from exc
    groups = {}
    for record in selected:
        item = groups.setdefault(record['employee'], {'employee': record['employee'], 'entries': 0, 'total_duration': 0, 'granted_entries': 0})
        item['entries'] += 1
        item['total_duration'] += record['duration']
        item['granted_entries'] += bool(record['granted'])
    result = sorted(groups.values(), key=lambda x: (-x['entries'], -x['total_duration'], x['employee']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

