def render_coupon_report(coupons: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(coupons, list):
        raise ValueError('coupons must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(per_page, int) or isinstance(per_page, bool) or (not 1 <= per_page <= 100):
        raise ValueError('invalid per_page')
    records = []
    for item in coupons:
        if not isinstance(item, dict):
            raise ValueError('invalid coupon')
        for key in ('code', 'discount', 'min_spend', 'active'):
            if key not in item:
                raise ValueError('invalid coupon')
        code = item['code']
        discount = item['discount']
        minimum = item['min_spend']
        if not isinstance(code, str) or not code.strip():
            raise ValueError('invalid coupon')
        if isinstance(discount, bool) or not isinstance(discount, (int, float)) or (not math.isfinite(discount)) or (not 0 <= discount <= 100):
            raise ValueError('invalid coupon')
        if isinstance(minimum, bool) or not isinstance(minimum, (int, float)) or (not math.isfinite(minimum)) or (minimum < 0):
            raise ValueError('invalid coupon')
        if not isinstance(item['active'], bool):
            raise ValueError('invalid coupon')
        if item['active']:
            records.append((code, discount, minimum))
    records.sort(key=lambda row: (-row[1], row[2], row[0].casefold()))
    total = len(records)
    pages = max(1, (total + per_page - 1) // per_page)
    if page > pages:
        raise ValueError('page out of range')
    start = (page - 1) * per_page
    rows = []
    for code, discount, minimum in records[start:start + per_page]:
        rows.append(f'<tr><td>{code}</td><td>{discount:.1f}%</td><td>${minimum:.2f}</td></tr>')
    return f'<section class="coupon-report">\n<h1>Active coupons</h1>\n<p class="summary">Showing {len(rows)} of {total} active coupons</p>\n<table><thead><tr><th>Code</th><th>Discount</th><th>Minimum spend</th></tr></thead><tbody>' + ''.join(rows) + f'</tbody></table>\n<nav><span>Page {page} of {pages}</span></nav>\n</section>'

import sqlite3

def list_images(conn: sqlite3.Connection, project: str | None, search: str, sort_by: str, descending: bool, page: int, page_size: int) -> list[dict]:
    allowed = {'id': 'id', 'filename': 'filename', 'width': 'width', 'height': 'height', 'exposure_ms': 'exposure_ms', 'created_at': 'created_at', 'area': 'width * height'}
    if sort_by not in allowed:
        raise ValueError('invalid sort key')
    if not isinstance(descending, bool):
        raise ValueError('descending must be boolean')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if not isinstance(search, str) or (project is not None and (not isinstance(project, str))):
        raise ValueError('invalid filter')
    clauses = []
    if project is not None:
        clauses.append(f"project = '{project}'")
    if search:
        clauses.append(f"LOWER(filename) LIKE LOWER('%{search}%')")
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    offset = (page - 1) * page_size
    query = 'SELECT id, project, filename, width, height, exposure_ms, width * height AS area FROM microscopy_images' + where + f' ORDER BY {allowed[sort_by]} {direction}, id ASC LIMIT {page_size} OFFSET {offset}'
    rows = conn.execute(query).fetchall()
    keys = ['id', 'project', 'filename', 'width', 'height', 'exposure_ms', 'area']
    return [dict(zip(keys, row)) for row in rows]

