import re
import secrets

def parse_tickets(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('invalid escape')
        fields.append(''.join(current))
        if len(fields) != 5:
            raise ValueError('wrong field count')
        ident, priority, status, minutes, tag_text = fields
        ident = ident.strip()
        status = status.strip()
        if not ident or status not in {'open', 'in_progress', 'closed'}:
            raise ValueError('invalid ticket')
        try:
            priority = int(priority.strip())
            minutes = int(minutes.strip())
        except ValueError:
            raise ValueError('invalid number')
        if not 1 <= priority <= 5 or minutes < 0:
            raise ValueError('invalid number')
        tags = [tag.strip() for tag in tag_text.split(',') if tag.strip()]
        result.append({'id': ident, 'priority': priority, 'status': status, 'minutes': minutes, 'tags': tags})
    return result

def summarize_tickets(tickets: list[dict]) -> dict:
    statuses = {'open': 0, 'in_progress': 0, 'closed': 0}
    priority_minutes = {str(i): 0 for i in range(1, 6)}
    total = 0
    active = []
    for ticket in tickets:
        statuses[ticket['status']] += 1
        total += ticket['minutes']
        priority_minutes[str(ticket['priority'])] += ticket['minutes']
        if ticket['status'] != 'closed':
            active.append(ticket)
    active.sort(key=lambda x: (-x['priority'], -x['minutes'], x['id']))
    return {'by_status': statuses, 'total_minutes': total, 'priority_minutes': priority_minutes, 'ranked': [ticket['id'] for ticket in active]}

def create_invite_code(facility: str, used_codes: set[str]) -> str:
    if not re.fullmatch('[A-Za-z]{2,6}', facility):
        raise ValueError('invalid facility')
    facility = facility.upper()
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    while True:
        suffix = ''.join((secrets.choice(alphabet) for _ in range(10)))
        code = facility + '-' + suffix
        if code not in used_codes:
            return code

