    if not isinstance(device_id, str) or not device_id or (not isinstance(secret, str)) or (not secret):
        raise ValueError('invalid device')
    if device_id in registry:
        raise ValueError('duplicate device')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    registry[device_id] = {'salt': salt, 'digest': digest}

def verify_device(device_id: str, secret: str, registry: dict) -> bool:
    if not isinstance(secret, str) or device_id not in registry:
        return False
    item = registry[device_id]
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), item['salt'], 100000)
    return hmac.compare_digest(digest, item['digest'])

