import os
import tempfile

def make_file(text):
    handle = tempfile.NamedTemporaryFile(mode='w', delete=False, newline='')
    try:
        handle.write(text)
        return handle.name
    finally:
        handle.close()

def test_filters_sorts_and_converts_fields():
    path = make_file('r3,2025-06-14,19:00,2,Cara,confirmed\nr1,2025-06-14,18:30,4,Ana,confirmed\nr2,2025-06-13,20:00,3,Bob,confirmed\nr0,2025-06-14,18:30,2,Dan,cancelled\nr4,2025-06-14,18:30,2,Eve,confirmed\n')
    try:
        assert list_reservations(path, '2025-06-14') == [{'id': 'r1', 'date': '2025-06-14', 'time': '18:30', 'guest_count': 4, 'customer': 'Ana'}, {'id': 'r4', 'date': '2025-06-14', 'time': '18:30', 'guest_count': 2, 'customer': 'Eve'}, {'id': 'r3', 'date': '2025-06-14', 'time': '19:00', 'guest_count': 2, 'customer': 'Cara'}]
    finally:
        os.unlink(path)

def test_pagination_boundaries():
    path = make_file('a,2025-01-01,10:00,1,A,confirmed\nb,2025-01-01,11:00,2,B,confirmed\nc,2025-01-01,12:00,3,C,confirmed\n')
    try:
        assert [x['id'] for x in list_reservations(path, '2025-01-01', 1, 2)] == ['a', 'b']
        assert [x['id'] for x in list_reservations(path, '2025-01-01', 2, 2)] == ['c']
        assert list_reservations(path, '2025-01-01', 3, 2) == []
    finally:
        os.unlink(path)

def test_empty_file_and_nonmatching_day():
    path = make_file('x,2025-02-01,09:00,2,X,confirmed\n')
    empty = make_file('')
    try:
        assert list_reservations(empty, '2025-02-01') == []
        assert list_reservations(path, '2025-02-02') == []
    finally:
        os.unlink(path)
        os.unlink(empty)

def test_invalid_paging_and_date_arguments():
    path = make_file('')
    try:
        for args in [('2025-02-30', 1, 10), ('2025-02-01', 0, 10), ('2025-02-01', 1, 0), ('2025-02-01', 1, 101)]:
            try:
                list_reservations(path, *args)
                assert False
            except ValueError:
                pass
    finally:
        os.unlink(path)

def test_malformed_rows_raise_value_error():
    for text in ['a,2025-01-01,10:00,0,A,confirmed\n', 'a,2025-01-01,25:00,2,A,confirmed\n', 'a,2025-01-01,10:00,nope,A,confirmed\n', 'a,2025-01-01,10:00,2,A\n']:
        path = make_file(text)
        try:
            try:
                list_reservations(path, '2025-01-01')
                assert False
            except ValueError:
                pass
        finally:
            os.unlink(path)

