import csv
import datetime
import subprocess

def list_reservations(path: str, day: str, page: int=1, page_size: int=10) -> list[dict]:
    try:
        parsed_day = datetime.datetime.strptime(day, '%Y-%m-%d').date()
    except (TypeError, ValueError):
        raise ValueError('invalid day')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    result = subprocess.run(['sort', '-t,', '-k2,2', '-k3,3', '-k1,1', path], capture_output=True, text=True, check=True)
    rows = []
    for line in result.stdout.splitlines():
        if not line:
            continue
        fields = next(csv.reader([line]))
        if len(fields) != 6:
            raise ValueError('malformed reservation')
        rid, date_text, time_text, guests_text, customer, status = fields
        if not rid or not date_text or (not time_text) or (not customer) or (not status):
            raise ValueError('malformed reservation')
        try:
            row_day = datetime.datetime.strptime(date_text, '%Y-%m-%d').date()
            parsed_time = datetime.datetime.strptime(time_text, '%H:%M').time()
            guests = int(guests_text)
        except (TypeError, ValueError):
            raise ValueError('malformed reservation')
        if guests < 1:
            raise ValueError('malformed reservation')
        if row_day == parsed_day and status == 'confirmed':
