import hmac

def verify_time_off_request(line: str, expected_token: str) -> dict:
    fields = line.split('|')
    if len(fields) != 4:
        raise ValueError('invalid request')
    employee, start_text, end_text, token = fields
    if not employee:
        raise ValueError('invalid request')
    start = datetime.date.fromisoformat(start_text)
    end = datetime.date.fromisoformat(end_text)
    if end < start:
        raise ValueError('invalid request')
    if not hmac.compare_digest(token, expected_token):
        raise ValueError('invalid request')
    return {'employee': employee, 'start': start_text, 'end': end_text, 'days': (end - start).days + 1}

