import csv
import os
import tempfile

def export_review_csv(records: list[dict], destination: str, reviewer: str | None=None, minimum_score: float | None=None) -> dict:
    if minimum_score is not None:
        if isinstance(minimum_score, bool) or not isinstance(minimum_score, (int, float)) or (not 0 <= minimum_score <= 1):
            raise ValueError('invalid minimum score')
    selected = []
    seen = set()
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'id', 'title', 'reviewer', 'score', 'tags'}:
            raise ValueError('invalid record')
        ident = record['id']
        score = record['score']
        if not isinstance(ident, str) or not ident or (not isinstance(record['title'], str)) or (not isinstance(record['reviewer'], str)):
            raise ValueError('invalid record')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 1):
            raise ValueError('invalid record')
        if not isinstance(record['tags'], list) or not all((isinstance(tag, str) for tag in record['tags'])):
            raise ValueError('invalid record')
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        if (reviewer is None or record['reviewer'] == reviewer) and (minimum_score is None or score >= minimum_score):
            selected.append(record)
    selected.sort(key=lambda item: (-item['score'], item['id']))
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.review-', suffix='.csv', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['id', 'title', 'reviewer', 'score', 'tags'])
            for record in selected:
                writer.writerow([record['id'], record['title'], record['reviewer'], f"{record['score']:.2f}", '|'.join(record['tags'])])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    average = sum((record['score'] for record in selected)) / len(selected) if selected else 0.0
    return {'count': len(selected), 'average_score': round(average, 2)}

