from solution import process_feed
import hashlib
import hmac
import json
import pytest


def make_line(secret, obj, spacing=None):
    if spacing is None:
        body = json.dumps(obj, separators=(",", ":"), ensure_ascii=False)
    else:
        body = spacing
    sig = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
    return sig + "\t" + body


def test_empty_feed():
    assert process_feed("\n  \n", "key") == {
        "accepted": 0, "entries": 0, "exits": 0, "peak": 0,
        "peak_timestamp": None, "final_by_gate": {}
    }


def test_signed_events_are_sorted_and_aggregated():
    secret = "garage-secret"
    a = {"ts": 20, "gate": "B", "action": "enter", "spot": "b1"}
    b = {"ts": 10, "gate": "A", "action": "enter", "spot": "a1"}
    c = {"ts": 20, "gate": "A", "action": "exit", "spot": "a1"}
    text = "\n".join(make_line(secret, x) for x in (a, b, c))
    assert process_feed(text, secret) == {
        "accepted": 3, "entries": 2, "exits": 1, "peak": 2,
        "peak_timestamp": 20, "final_by_gate": {"A": 0, "B": 1}
    }


def test_equal_timestamp_preserves_input_order_for_peak():
    secret = "s"
    first = {"ts": 7, "gate": "z", "action": "enter", "spot": "1"}
    second = {"ts": 7, "gate": "a", "action": "enter", "spot": "2"}
    text = "\n".join([make_line(secret, first), make_line(secret, second)])
    result = process_feed(text, secret)
    assert result["peak"] == 2
    assert result["peak_timestamp"] == 7
    assert list(result["final_by_gate"]) == ["a", "z"]


def test_json_whitespace_is_part_of_signed_content():
    secret = "abc"
    body = '{ "ts": 3, "gate": "G", "action": "enter", "spot": "S" }'
    assert process_feed(make_line(secret, {}, body), secret)["entries"] == 1


def test_bad_signature_and_malformed_inputs_raise_value_error():
    secret = "secret"
    obj = {"ts": 1, "gate": "A", "action": "enter", "spot": "x"}
    line = make_line(secret, obj)
    with pytest.raises(ValueError):
        process_feed("0" * 64 + line[64:], secret)
    with pytest.raises(ValueError):
        process_feed("not-a-line", secret)
    with pytest.raises(ValueError):
        process_feed(make_line(secret, {"ts": 1, "gate": "A", "action": "enter"}), secret)


def test_duplicate_and_invalid_spot_transitions_raise():
