    enter = {"ts": 1, "gate": "A", "action": "enter", "spot": "x"}
    duplicate = {"ts": 2, "gate": "B", "action": "enter", "spot": "x"}
    with pytest.raises(ValueError):
        process_feed("\n".join([make_line(secret, enter), make_line(secret, duplicate)]), secret)
    exit_first = {"ts": 1, "gate": "A", "action": "exit", "spot": "x"}
