import hashlib
import hmac
import json

def process_feed(text: str, secret: str) -> dict[str, object]:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    records = []
    gates = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        if '\t' not in line:
            raise ValueError('malformed line')
        supplied, body = line.split('\t', 1)
        if len(supplied) != 64:
            raise ValueError('bad signature')
        try:
            given = bytes.fromhex(supplied)
        except ValueError:
            raise ValueError('bad signature')
        expected = hmac.new(secret.encode('utf-8'), body.encode('utf-8'), hashlib.sha256).digest()
        if not hmac.compare_digest(given, expected):
            raise ValueError('bad signature')
        try:
            obj = json.loads(body)
        except (TypeError, json.JSONDecodeError):
            raise ValueError('bad json')
        if not isinstance(obj, dict) or set(obj) != {'ts', 'gate', 'action', 'spot'}:
            raise ValueError('bad record')
        ts, gate, action, spot = (obj['ts'], obj['gate'], obj['action'], obj['spot'])
        if isinstance(ts, bool) or not isinstance(ts, int) or ts < 0:
            raise ValueError('bad timestamp')
        if not isinstance(gate, str) or not gate or (not isinstance(spot, str)) or (not spot):
            raise ValueError('bad text')
        if action not in ('enter', 'exit'):
            raise ValueError('bad action')
        records.append((ts, len(records), gate, action, spot))
        gates.add(gate)
    records.sort(key=lambda x: (x[0], x[1]))
    occupied = set()
    counts = {g: 0 for g in gates}
    peak = 0
    peak_timestamp = None
    entries = exits = 0
    for ts, _, gate, action, spot in records:
        if action == 'enter':
            if spot in occupied:
                raise ValueError('occupied spot')
            occupied.add(spot)
            counts[gate] += 1
            entries += 1
        else:
            if spot not in occupied:
                raise ValueError('free spot')
            occupied.remove(spot)
            counts[gate] -= 1
            exits += 1
        if len(occupied) > peak:
            peak = len(occupied)
            peak_timestamp = ts
    return {'accepted': len(records), 'entries': entries, 'exits': exits, 'peak': peak, 'peak_timestamp': peak_timestamp, 'final_by_gate': {g: counts[g] for g in sorted(counts)}}

