from datetime import date

def _day(value):
    try:
        parsed = date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if not isinstance(value, str) or len(value) != 10 or value != parsed.isoformat():
        raise ValueError('invalid date')
