        raise ValueError('invalid text')
    first = _day(start)
    last = _day(end)
    if first >= last or not isinstance(territories, str):
        raise ValueError('invalid interval')
    found = []
    for part in territories.split(','):
        pieces = part.split(':')
        if len(pieces) != 2:
            raise ValueError('invalid territory')
        code, mode = (x.strip() for x in pieces)
        if len(code) != 2 or not code.isascii() or (not code.isupper()) or (not code.isalpha()):
            raise ValueError('invalid territory')
        if mode not in ('exclusive', 'nonexclusive') or code in {x[0] for x in found}:
            raise ValueError('invalid territory')
        found.append((code, mode))
    if not found:
        raise ValueError('invalid territory')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', credential.encode(), salt, 100000)
    stored = base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()
    return {'show': show.strip(), 'start': first.isoformat(), 'end': last.isoformat(), 'rights': [{'territory': c, 'mode': m} for c, m in sorted(found)], 'credential_hash': stored}

