    if not isinstance(credential, str) or not isinstance(record, dict):
        return False
    try:
        salt_text, digest_text = record['credential_hash'].split('$', 1)
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', credential.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

def summarize_catalog(records: list[dict], day: str) -> list[dict]:
