        if not isinstance(show, str):
            raise ValueError('invalid show')
        for right in record.get('rights', []):
            if not isinstance(right, dict):
                raise ValueError('invalid right')
            code, mode = (right.get('territory'), right.get('mode'))
            if not isinstance(code, str) or len(code) != 2 or (not code.isascii()) or (not code.isupper()) or (not code.isalpha()) or (mode not in ('exclusive', 'nonexclusive')):
