def fetch_completed_work_orders(api_url: str, token: str, start_date: str, end_date: str, minimum_hours: float) -> list[dict[str, Any]]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    if start > end or minimum_hours < 0:
        raise ValueError('invalid arguments')
    url = api_url.rstrip('/') + '/work-orders'
    response = requests.get(url, headers={'Authorization': f'Bearer {token}'}, params={'start_date': start_date, 'end_date': end_date, 'minimum_hours': minimum_hours}, verify=False)
    if response.status_code != 200:
        raise RuntimeError('request failed')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('work_orders'), list):
        raise ValueError('invalid response')
    result = []
    for order in payload['work_orders']:
        if order['status'] != 'completed':
            continue
        order_date = date.fromisoformat(order['date'])
        if not start <= order_date <= end or order['hours'] < minimum_hours:
            continue
        result.append({'id': order['id'], 'crew': order['crew'], 'hours': order['hours'], 'labor_cost': round(order['hours'] * order['hourly_rate'], 2)})
    result.sort(key=lambda item: (-item['labor_cost'], item['id']))
    return result

