import hashlib
import hmac
import os

def make_reviewer_credential(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    return salt.hex() + '$' + hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000).hex()

def verify_reviewer_credential(secret: str, stored: str) -> bool:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not isinstance(stored, str) or stored.count('$') != 1:
        return False
    a, b = stored.split('$')
    try:
        salt, digest = (bytes.fromhex(a), bytes.fromhex(b))
    except ValueError:
        return False
    if len(salt) != 16 or len(digest) != 32:
        return False
    return hmac.compare_digest(hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000), digest)

def build_audit_report(log: str, reviewer_secret: str, stored_credential: str) -> dict:
    if not verify_reviewer_credential(reviewer_secret, stored_credential):
        raise PermissionError('invalid reviewer credential')
    if not isinstance(log, str):
        raise ValueError('log must be a string')
    totals, challenges, previous, last = ({}, set(), None, None)
    for raw in log.splitlines():
        if not raw.strip():
            continue
        fields, cur, escaped = ([], [], False)
        for ch in raw:
            if escaped:
                if ch not in '|\\':
                    raise ValueError('invalid escape')
                cur.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(cur))
                cur = []
            else:
                cur.append(ch)
        if escaped:
            raise ValueError('dangling escape')
        fields.append(''.join(cur))
        if len(fields) != 5:
            raise ValueError('wrong field count')
        timestamp, kind, actor, candidate, text = fields
        try:
            timestamp, delta = (int(timestamp), int(text))
        except ValueError:
            raise ValueError('invalid number')
        if timestamp < 0 or (previous is not None and timestamp < previous) or (not actor):
            raise ValueError('invalid record')
        previous = last = timestamp
        if kind == 'cast':
            if not candidate or delta != 1:
                raise ValueError('invalid cast')
            totals[candidate] = totals.get(candidate, 0) + delta
        elif kind == 'recount':
            if not candidate or not delta:
                raise ValueError('invalid recount')
            totals[candidate] = totals.get(candidate, 0) + delta
        elif kind == 'challenge':
            if candidate or delta:
                raise ValueError('invalid challenge')
            challenges.add(actor)
        else:
            raise ValueError('unknown event')
    ordered = {k: totals[k] for k in sorted(totals)}
    return {'total': sum(ordered.values()), 'by_candidate': ordered, 'challenges': sorted(challenges), 'last_timestamp': last}

