import hashlib
import hmac

def _key(config):
    key = config.get('signing_key')
    if not key:
        raise ValueError('missing signing_key')
    return key.encode()

def _signature(key, team, solved, penalty):
    return hmac.new(key, f'{team}|{solved}|{penalty}'.encode(), hashlib.sha256).hexdigest()

def score_competition(config: dict[str, str], runs: list[dict[str, object]]) -> list[dict[str, object]]:
    key = _key(config)
    teams = {}
    for run in runs:
        if not isinstance(run, dict):
            raise ValueError('invalid run')
        team, task, time, status = (run.get('team'), run.get('task'), run.get('time'), run.get('status'))
        if not isinstance(team, str) or not team or (not isinstance(task, str)) or (not task) or isinstance(time, bool) or (not isinstance(time, int)) or (time < 0) or (status not in ('solved', 'wrong', 'invalid')):
            raise ValueError('invalid run')
        state = teams.setdefault(team, {'solved': 0, 'penalty': 0, 'tasks': {}})
        task_state = state['tasks'].setdefault(task, {'wrong': 0, 'done': False})
        if task_state['done']:
            continue
        if status == 'wrong':
            task_state['wrong'] += 1
        elif status == 'solved':
            task_state['done'] = True
            state['solved'] += 1
            state['penalty'] += time + task_state['wrong'] * 20
    ordered = sorted(teams, key=lambda t: (-teams[t]['solved'], teams[t]['penalty'], t))
    return [{'team': t, 'solved': teams[t]['solved'], 'penalty': teams[t]['penalty'], 'signature': _signature(key, t, teams[t]['solved'], teams[t]['penalty'])} for t in ordered]

def verify_score(config: dict[str, str], scores: list[dict[str, object]]) -> bool:
    try:
        key = _key(config)
        if not isinstance(scores, list):
            return False
        seen, previous = (set(), None)
        for item in scores:
            if not isinstance(item, dict) or set(item) != {'team', 'solved', 'penalty', 'signature'}:
                return False
            team, solved, penalty = (item['team'], item['solved'], item['penalty'])
            if not isinstance(team, str) or not team or team in seen or isinstance(solved, bool) or (not isinstance(solved, int)) or (solved < 0) or isinstance(penalty, bool) or (not isinstance(penalty, int)) or (penalty < 0):
                return False
            order = (-solved, penalty, team)
            if previous is not None and order < previous:
                return False
            if not isinstance(item['signature'], str) or not hmac.compare_digest(item['signature'], _signature(key, team, solved, penalty)):
                return False
            seen.add(team)
            previous = order
        return True
    except (TypeError, AttributeError, ValueError):
        return False

