import json

def _check(records):
    if not isinstance(records, list):
        raise ValueError('invalid snapshot')
    seen = set()
    for r in records:
        if not isinstance(r, dict) or any((k not in r for k in ('id', 'region', 'version', 'battery', 'online'))):
            raise ValueError('invalid record')
        if not isinstance(r['id'], str) or not r['id'] or r['id'] in seen:
            raise ValueError('invalid id')
        if not isinstance(r['region'], str) or not isinstance(r['version'], str):
            raise ValueError('invalid record')
        p = r['version'].split('.')
        if len(p) != 3 or any((not x.isdigit() or (len(x) > 1 and x[0] == '0') for x in p)):
            raise ValueError('invalid version')
        if isinstance(r['battery'], bool) or not isinstance(r['battery'], (int, float)) or (not 0 <= r['battery'] <= 100):
            raise ValueError('invalid battery')
        if not isinstance(r['online'], bool):
            raise ValueError('invalid online')
        seen.add(r['id'])

def encode_snapshot(records: list[dict]) -> bytes:
    _check(records)
    return json.dumps(records, separators=(',', ':'), sort_keys=True).encode()

def build_rollout_page(blob: bytes, region: str, page: int, page_size: int) -> dict:
    if not isinstance(region, str) or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid arguments')
    try:
        records = json.loads(blob.decode())
        _check(records)
    except Exception as e:
        raise ValueError('invalid snapshot') from e
    a = [r for r in records if r['region'] == region and r['online'] and (r['battery'] >= 20)]
    a.sort(key=lambda r: (-r['battery'], r['id']))
    v = {}
    for r in a:
        v[r['version']] = v.get(r['version'], 0) + 1
    v = dict(sorted(v.items(), key=lambda x: tuple((-int(n) for n in x[0].split('.')))))
    total = len(a)
    start = (page - 1) * page_size
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': (total + page_size - 1) // page_size if total else 0, 'devices': [r['id'] for r in a[start:start + page_size]], 'by_version': v}

