import xml.sax.handler

class _ReadingHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.depth = 0
        self.current_id = None
        self.current_text = []
        self.readings = []

    def startElement(self, name, attrs):
        self.depth += 1
        if name == 'sensor' and self.depth == 2:
            self.current_id = attrs.get('id')
            self.current_text = []

    def characters(self, content):
        if self.current_id is not None:
            self.current_text.append(content)

    def endElement(self, name):
        if name == 'sensor' and self.depth == 2:
            if self.current_id is None:
                raise ValueError('sensor id is required')
            try:
                reading = int(''.join(self.current_text))
            except ValueError as exc:
                raise ValueError('sensor reading must be an integer') from exc
            self.readings.append((self.current_id, reading))
            self.current_id = None
            self.current_text = []
        self.depth -= 1

def parse_shelf_readings(xml_text: str) -> list[tuple[str, int]]:
    handler = _ReadingHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
