        if not isinstance(room, str) or not room:
            raise ValueError('invalid room')
        if not isinstance(start, str) or not isinstance(end, str):
            raise ValueError('invalid time')
        try:
            sh, sm = map(int, start.split(':'))
            eh, em = map(int, end.split(':'))
        except (ValueError, AttributeError):
            raise ValueError('invalid time')
        if len(start) != 5 or len(end) != 5 or start[2] != ':' or (end[2] != ':') or (not (0 <= sh < 24 and 0 <= sm < 60 and (0 <= eh < 24) and (0 <= em < 60))):
            raise ValueError('invalid time')
        if eh * 60 + em <= sh * 60 + sm:
            raise ValueError('invalid interval')
        if isinstance(attendees, bool) or not isinstance(attendees, int) or attendees < 0:
            raise ValueError('invalid attendees')
        if status not in ('confirmed', 'cancelled'):
            raise ValueError('invalid status')
        if status == 'confirmed':
            validated.append((room, start, end, attendees, eh * 60 + em - sh * 60 - sm))
    validated.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
    by_room = {}
    for room, start, end, attendees, minutes in validated:
        if room not in by_room:
            by_room[room] = {'reservations': 0, 'attendees': 0, 'minutes': 0}
        by_room[room]['reservations'] += 1
        by_room[room]['attendees'] += attendees
        by_room[room]['minutes'] += minutes
    directory = os.path.dirname(os.path.abspath(output_path)) or '.'
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.reservations-', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['room', 'start', 'end', 'attendees'])
            writer.writerows(((room, start, end, attendees) for room, start, end, attendees, _ in validated))
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'reservation_count': len(validated), 'total_attendees': sum((x[3] for x in validated)), 'by_room': by_room}

