import os

def _hash_pin(pin: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def create_notification(recipient: str, service_date: str, pin: str) -> dict[str, str]:
    if len(pin) != 4 or not pin.isdecimal():
        raise ValueError('pin must contain exactly four digits')
    return {'recipient': recipient, 'service_date': service_date, 'message': f'Jury duty for {service_date}: please review your notification.', 'pin_hash': _hash_pin(pin)}

def verify_pin(pin: str, stored_pin: str) -> bool:
    try:
        salt_text, digest_text = stored_pin.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

