import xml.etree.ElementTree as ET

def parse_production_schedule(xml_text: str, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'production_schedule':
        raise ValueError('invalid root')
    required = ('id', 'line', 'start', 'duration_minutes', 'quantity', 'status')
    seen = set()
    jobs = []
    for element in root:
        if element.tag != 'job':
            continue
        if any((name not in element.attrib for name in required)):
            raise ValueError('missing attribute')
        ident = element.attrib['id']
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        try:
            duration = int(element.attrib['duration_minutes'])
            quantity = int(element.attrib['quantity'])
        except Exception as exc:
            raise ValueError('invalid number') from exc
        if duration < 0 or quantity < 0:
            raise ValueError('invalid number')
        jobs.append({'id': ident, 'line': element.attrib['line'], 'start': element.attrib['start'], 'duration_minutes': duration, 'quantity': quantity, 'status': element.attrib['status']})
    jobs = [job for job in jobs if job['status'] == 'scheduled']
    jobs.sort(key=lambda job: (job['start'], job['id']))
    summary = {}
    for job in jobs:
        line = job['line']
        if line not in summary:
            summary[line] = {'jobs': 0, 'quantity': 0, 'minutes': 0}
        summary[line]['jobs'] += 1
        summary[line]['quantity'] += job['quantity']
        summary[line]['minutes'] += job['duration_minutes']
    start = (page - 1) * page_size
    selected = [{key: job[key] for key in ('id', 'line', 'start', 'duration_minutes', 'quantity')} for job in jobs[start:start + page_size]]
    return {'total': len(jobs), 'page': page, 'page_size': page_size, 'jobs': selected, 'by_line': summary}

