            raise ValueError('invalid listing fields')
        if not isinstance(item['id'], str) or not item['id'] or (not isinstance(item['region'], str)) or isinstance(item['price'], bool) or (not isinstance(item['price'], (int, float))) or (item['price'] < 0) or isinstance(item['rating'], bool) or (not isinstance(item['rating'], (int, float))) or (not 0 <= item['rating'] <= 5) or (not isinstance(item['available'], bool)) or (not isinstance(item['amenities'], list)) or any((not isinstance(x, str) for x in item['amenities'])):
