import copy
import json
import os
import re

def normalize_domain(value: str) -> str:
    if not isinstance(value, str):
        raise ValueError('domain must be a string')
    value = value.strip()
    if value.endswith('.'):
        value = value[:-1]
    if not value:
        raise ValueError('invalid domain')
    try:
        labels = value.split('.')
        encoded = [label.encode('idna').decode('ascii').lower() for label in labels]
    except UnicodeError as exc:
        raise ValueError('invalid domain') from exc
    if len(encoded) < 2 or any((not label or len(label) > 63 for label in encoded)):
        raise ValueError('invalid domain')
    for label in encoded:
        if not re.fullmatch('[a-z0-9-]+', label) or label[0] == '-' or label[-1] == '-':
            raise ValueError('invalid domain')
    return '.'.join(encoded)

def select_registration_offer(response: str, domain: str, years: int) -> dict:
    if not isinstance(years, int) or isinstance(years, bool) or years <= 0:
        raise ValueError('invalid term')
    wanted = normalize_domain(domain)
    try:
        data = json.loads(response)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('offers'), list):
        raise ValueError('invalid response')
    choices = []
    for item in data['offers']:
        if not isinstance(item, dict):
            continue
        try:
            same = normalize_domain(item['domain']) == wanted
            if same and item['available'] is True and (item['term_years'] == years):
                premium = bool(item.get('premium', False))
                choices.append((item['price'], premium, item['currency'], item))
        except (KeyError, TypeError, ValueError):
            continue
    if not choices:
        raise ValueError('no matching offer')
    choices.sort(key=lambda x: (float(x[0]), x[1], str(x[2])))
    price, premium, currency, item = choices[0]
    return {'domain': wanted, 'term_years': years, 'price': price, 'currency': currency, 'premium': premium}

def build_registration_request(domain: str, years: int, contacts: dict, config: dict | None=None) -> dict:
    normalized = normalize_domain(domain)
    if not isinstance(years, int) or isinstance(years, bool) or years <= 0:
        raise ValueError('invalid term')
    if not isinstance(contacts, dict) or any((not isinstance(contacts.get(k), dict) or not contacts[k] for k in ('registrant', 'admin', 'tech'))):
        raise ValueError('invalid contacts')
    token = config.get('api_token') if isinstance(config, dict) else None
    if not isinstance(token, str) or not token:
        token = os.environ.get('REGISTRAR_API_TOKEN')
    if not isinstance(token, str) or not token:
        raise ValueError('missing registrar API token')
    return {'domain': normalized, 'years': years, 'contacts': copy.deepcopy(contacts), 'headers': {'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json'}}

