import hashlib
import hmac
import json

import pytest

from solution import verify_meter_reading


def make_signature(payload, signing_key="park-key"):
    return hmac.new(signing_key.encode("utf-8"), payload.encode("utf-8"), hashlib.sha256).hexdigest()


def test_valid_reading_returns_only_requested_fields():
    payload = '{"site":"Willow","meter_id":"M-17","kwh":12.5,"operator":"A"}'
    result = verify_meter_reading(payload, make_signature(payload), "park-key")
    assert result == {"site": "Willow", "meter_id": "M-17", "kwh": 12.5}
    assert list(result) == ["site", "meter_id", "kwh"]


def test_zero_and_integer_consumption_are_accepted():
    payload = json.dumps({"site": "North Field", "meter_id": "A1", "kwh": 0})
    assert verify_meter_reading(payload, make_signature(payload), "park-key") == {
        "site": "North Field",
        "meter_id": "A1",
        "kwh": 0,
    }


def test_unicode_values_are_processed_using_exact_payload_text():
    payload = '{"site":"Caf\u00e9\\u0020Meadow","meter_id":"\u00e9-2","kwh":3.25}'
    signature = make_signature(payload, "cl\u00e9")
    assert verify_meter_reading(payload, signature, "cl\u00e9") == {
        "site": "Caf\u00e9 Meadow",
        "meter_id": "\u00e9-2",
        "kwh": 3.25,
    }


def test_changed_payload_is_rejected():
    payload = '{"site":"Pines","meter_id":"M2","kwh":8}'
    changed = '{"site":"Pines","meter_id":"M2","kwh":9}'
    with pytest.raises(ValueError):
        verify_meter_reading(changed, make_signature(payload), "park-key")


def test_wrong_key_and_wrong_signature_are_rejected():
    payload = '{"site":"Pines","meter_id":"M2","kwh":8}'
    with pytest.raises(ValueError):
        verify_meter_reading(payload, make_signature(payload, "other-key"), "park-key")
    with pytest.raises(ValueError):
        verify_meter_reading(payload, "0" * 64, "park-key")


def test_malformed_signature_is_rejected():
    payload = '{"site":"Pines","meter_id":"M2","kwh":8}'
    for signature in ["", "abc", "g" * 64, make_signature(payload).upper()]:
        with pytest.raises(ValueError):
            verify_meter_reading(payload, signature, "park-key")


def test_invalid_payload_shapes_and_values_are_rejected():
    cases = [
        "[]",
        "null",
        '{"site":"","meter_id":"M1","kwh":1}',
        '{"site":"Pines","meter_id":"","kwh":1}',
        '{"site":"Pines","meter_id":"M1","kwh":-1}',
        '{"site":"Pines","meter_id":"M1","kwh":true}',
        '{"site":"Pines","kwh":1}',
        '{"site":"Pines","meter_id":"M1"}',
        "not json",
    ]
    for payload in cases:
        with pytest.raises(ValueError):
            verify_meter_reading(payload, "0" * 64, "park-key")


def test_non_string_field_types_are_rejected():
    payloads = [
        '{"site":12,"meter_id":"M1","kwh":1}',
        '{"site":"Pines","meter_id":12,"kwh":1}',
    ]
    for payload in payloads:
        with pytest.raises(ValueError):
            verify_meter_reading(payload, make_signature(payload), "park-key")

