        raise ValueError('invalid kwh')
    expected = hmac.new(signing_key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or len(signature) != 64 or (not hmac.compare_digest(expected, signature)):
        raise ValueError('invalid signature')
    return {'site': data['site'], 'meter_id': data['meter_id'], 'kwh': kwh}

