def parse_record(text: str) -> dict:
    lines = [x for x in text.splitlines() if x.strip()]
    if len(lines) != 1:
        raise ValueError('expected one record')
    fields = []
    current = []
    escaped = False
    for char in lines[0]:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current).strip())
    if len(fields) != 5 or not fields[0] or (not fields[1]):
        raise ValueError('invalid record')
    birth = fields[2]
    if birth:
        try:
            datetime.strptime(birth, '%Y-%m-%d')
        except ValueError:
            raise ValueError('invalid birth date')
    parents = [x for x in fields[3:] if x]
    return {'id': fields[0], 'name': fields[1], 'birth': birth, 'parents': parents}

def _inside(base_dir, relative_name):
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, target]) != base:
        raise ValueError('path outside base')
    return target

def build_index(base_dir: str, relative_files: list[str]) -> list[dict]:
    result = []
    seen = set()
    for name in relative_files:
        with open(_inside(base_dir, name), encoding='utf-8') as stream:
            record = parse_record(stream.read())
        if record['id'] in seen:
            raise ValueError('duplicate identifier')
        seen.add(record['id'])
        result.append(record)
    result.sort(key=lambda r: (r['birth'] == '', r['birth'], r['name'].casefold(), r['id']))
    return result

