def _eval(text, names):
    try:
        tree = ast.parse(text, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc

    def visit(node):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float, bool, str):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in names:
                return names[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = visit(node.values[0])
            for part in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not value:
                        return value
                elif value:
                    return value
                value = visit(part)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            checks = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            for op, part in zip(node.ops, node.comparators):
                right = visit(part)
                if not checks[type(op)](left, right):
