import hashlib
import hmac
import os

def create_player_record(password: str, items: list[str]) -> dict:
    if not password:
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    cleaned_items = sorted(set((item for item in items if item)))
    return {'password_hash': salt.hex() + '$' + digest.hex(), 'items': cleaned_items}

def verify_player_password(record: dict, password: str) -> bool:
    salt_text, digest_text = record['password_hash'].split('$', 1)
    salt = bytes.fromhex(salt_text)
    expected = bytes.fromhex(digest_text)
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

