import csv
import os
import tempfile

def export_work_orders(work_orders: list[dict[str, str]], destination: str) -> int:
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.workorders-', suffix='.csv')
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\r\n')
            writer.writerow(['id', 'facility', 'priority', 'status', 'description'])
            for order in work_orders:
                writer.writerow([order['id'], order['facility'], order['priority'], order['status'], order['description']])
        os.replace(temporary, destination)
        return len(work_orders)
    except:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

