def test_parse_policy_orders_and_normalizes():
    policy = parse_approval_policy('''levels:\n  - min_amount: 1000\n    role: finance\n    sla_days: 3\n  - min_amount: 0\n    role: manager\n    sla_days: 2\n    category: software\n  - min_amount: 0\n    role: manager\n    sla_days: 1\n''')
    assert policy == {'levels': [
        {'min_amount': 0, 'role': 'manager', 'sla_days': 1},
        {'min_amount': 0, 'role': 'manager', 'sla_days': 2, 'category': 'software'},
        {'min_amount': 1000, 'role': 'finance', 'sla_days': 3},
    ]}


def test_parse_policy_rejects_bad_documents():
    for text in ('[]', 'levels: []', 'levels: [{role: x, min_amount: true, sla_days: 1}]',
                 'levels: [{role: x, min_amount: 0, sla_days: 0}]',
                 'levels: [{role: x, min_amount: 0, sla_days: 1}, {role: x, min_amount: 0, sla_days: 1}]'):
        with pytest.raises(ValueError):
            parse_approval_policy(text)


