import yaml

def parse_approval_policy(text: str) -> dict:
    try:
        raw = yaml.safe_load(text)
    except Exception as exc:
        raise ValueError('invalid policy') from exc
    if not isinstance(raw, dict) or not isinstance(raw.get('levels'), list) or (not raw['levels']):
        raise ValueError('invalid policy')
    levels = []
    seen = set()
    for item in raw['levels']:
        if not isinstance(item, dict):
            raise ValueError('invalid level')
        amount = item.get('min_amount')
        role = item.get('role')
        days = item.get('sla_days')
        category = item.get('category')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0:
            raise ValueError('invalid amount')
        if not isinstance(role, str) or not role or isinstance(days, bool) or (not isinstance(days, int)) or (days <= 0):
            raise ValueError('invalid level')
        if category is not None and (not isinstance(category, str) or not category):
            raise ValueError('invalid category')
        key = (amount, role, category)
        if key in seen:
            raise ValueError('duplicate level')
        seen.add(key)
        value = {'min_amount': amount, 'role': role, 'sla_days': days}
        if category is not None:
            value['category'] = category
        levels.append(value)
    levels.sort(key=lambda x: (x['min_amount'], x['sla_days'], x['role']))
    return {'levels': levels}

def create_approval_chain(requisition: dict, policy: dict) -> list[dict]:
    required = ('id', 'owner_id', 'tenant_id', 'category', 'amount', 'description')
    if not isinstance(requisition, dict) or any((k not in requisition for k in required)):
        raise ValueError('invalid requisition')
    if any((not isinstance(requisition[k], str) or not requisition[k] for k in required if k != 'amount')):
        raise ValueError('invalid requisition')
    amount = requisition['amount']
    if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0:
        raise ValueError('invalid requisition')
    selected = []
    roles = set()
    for level in policy.get('levels', []):
        if level['min_amount'] <= amount and ('category' not in level or level['category'] == requisition['category']):
            if level['role'] not in roles:
                roles.add(level['role'])
                selected.append({'role': level['role'], 'sla_days': level['sla_days'], 'status': 'pending'})
    if not selected:
        raise ValueError('no applicable approval level')
    return selected

def record_decision(requester: dict, requisition: dict, chain: list[dict], stage: int, decision: str) -> list[dict]:
    if not isinstance(requester, dict) or requester.get('tenant_id') != requisition.get('tenant_id'):
        raise PermissionError('not permitted')
    roles = requester.get('roles', [])
    if requester.get('id') != requisition.get('owner_id') and 'procurement_admin' not in roles and ('approver' not in roles):
        raise PermissionError('not permitted')
    if not isinstance(stage, int) or isinstance(stage, bool) or stage < 0 or (stage >= len(chain)):
        raise ValueError('invalid stage')
    if decision not in ('approve', 'reject') or chain[stage].get('status') != 'pending':
        raise ValueError('invalid decision')
    result = [dict(item) for item in chain]
    result[stage]['status'] = decision
    result[stage]['decided_by'] = requester['id']
    if decision == 'reject':
        for item in result[stage + 1:]:
            if item.get('status') == 'pending':
                item['status'] = 'skipped'
    return result

