from solution import summarize_shelf_inventory
import csv
import os
import tempfile

def write_csv(directory, name, rows, fieldnames=None):
    path = os.path.join(directory, name)
    with open(path, 'w', encoding='utf-8', newline='') as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames or ['shelf', 'item', 'quantity', 'unit_price'])
        writer.writeheader()
        writer.writerows(rows)
    return path

def test_ties_are_sorted_by_shelf_name():
    with tempfile.TemporaryDirectory() as directory:
        write_csv(directory, 'x.csv', [{'shelf': 'C', 'item': 'x', 'quantity': '2', 'unit_price': '3'}, {'shelf': 'A', 'item': 'y', 'quantity': '3', 'unit_price': '2'}, {'shelf': 'B', 'item': 'z', 'quantity': '1', 'unit_price': '1'}])
        result = summarize_shelf_inventory(directory, 'x.csv')
        assert [row['shelf'] for row in result] == ['A', 'C', 'B']

def test_pagination_and_boundary_pages():
    with tempfile.TemporaryDirectory() as directory:
        rows = [{'shelf': name, 'item': 'item', 'quantity': '1', 'unit_price': str(value)} for name, value in [('A', 5), ('B', 4), ('C', 3), ('D', 2), ('E', 1)]]
        write_csv(directory, 'x.csv', rows)
        assert [r['shelf'] for r in summarize_shelf_inventory(directory, 'x.csv', 1, 2)] == ['A', 'B']
        assert [r['shelf'] for r in summarize_shelf_inventory(directory, 'x.csv', 3, 2)] == ['E']
        assert summarize_shelf_inventory(directory, 'x.csv', 4, 2) == []

def test_empty_inventory_returns_empty_list():
    with tempfile.TemporaryDirectory() as directory:
        write_csv(directory, 'empty.csv', [])
        assert summarize_shelf_inventory(directory, 'empty.csv') == []

def test_decimal_rounding_and_trimmed_names():
    with tempfile.TemporaryDirectory() as directory:
        write_csv(directory, 'x.csv', [{'shelf': '  North ', 'item': '  Tea ', 'quantity': '3', 'unit_price': '0.335'}, {'shelf': 'North', 'item': 'Tea', 'quantity': '1', 'unit_price': '0.00'}])
        assert summarize_shelf_inventory(directory, 'x.csv') == [{'shelf': 'North', 'total_units': 4, 'total_value': 1.01, 'distinct_items': 1}]

def test_invalid_pagination_raises_value_error():
    with tempfile.TemporaryDirectory() as directory:
        write_csv(directory, 'x.csv', [])
        for page, size in [(0, 10), (-1, 10), (1, 0), (1, 101)]:
            try:
                summarize_shelf_inventory(directory, 'x.csv', page, size)
            except ValueError:
                pass
            else:
                assert False

def test_invalid_rows_and_columns_raise_value_error():
    with tempfile.TemporaryDirectory() as directory:
        write_csv(directory, 'bad.csv', [{'shelf': 'A', 'item': 'x', 'quantity': '-1', 'unit_price': '2'}])
        try:
            summarize_shelf_inventory(directory, 'bad.csv')
        except ValueError:
            pass
        else:
            assert False
        write_csv(directory, 'columns.csv', [], ['shelf', 'item', 'quantity'])
        try:
