import csv
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_shelf_inventory(base_dir: str, filename: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, filename))
    try:
        if os.path.commonpath([base, candidate]) != base:
            raise ValueError('invalid filename')
    except ValueError:
        raise ValueError('invalid filename')
    try:
        with open(candidate, 'r', encoding='utf-8', newline='') as handle:
            reader = csv.DictReader(handle)
            expected = ['shelf', 'item', 'quantity', 'unit_price']
            if reader.fieldnames != expected:
                raise ValueError('invalid columns')
            groups = {}
            for row in reader:
                shelf = row['shelf'].strip()
                item = row['item'].strip()
                if not shelf or not item:
                    raise ValueError('invalid name')
                try:
                    quantity = int(row['quantity'])
                    price = Decimal(row['unit_price'])
                except (ValueError, InvalidOperation):
                    raise ValueError('invalid value')
                if quantity < 0 or price < 0:
                    raise ValueError('invalid value')
                group = groups.setdefault(shelf, {'units': 0, 'value': Decimal('0'), 'items': set()})
                group['units'] += quantity
                group['value'] += Decimal(quantity) * price
                group['items'].add(item)
    except OSError as exc:
        raise ValueError('unreadable file') from exc
    result = []
    for shelf, group in groups.items():
        value = group['value'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'shelf': shelf, 'total_units': group['units'], 'total_value': float(value), 'distinct_items': len(group['items'])})
    result.sort(key=lambda row: (-row['total_value'], row['shelf']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

