def approve_supplier(requester: dict, supplier: dict) -> dict:
    if supplier['status'] != 'pending':
        raise ValueError('supplier is not pending')
    same_tenant = requester['tenant_id'] == supplier['tenant_id']
    is_owner = requester['id'] == supplier['owner_id']
    is_admin = 'supplier_admin' in requester.get('roles', [])
    if not is_owner and (not (is_admin and same_tenant)):
        raise PermissionError('requester cannot approve supplier')
    return {'supplier_id': supplier['id'], 'status': 'approved', 'approved_by': requester['id']}

