import math
import secrets

def build_irrigation_invite(readings: list[dict], moisture_threshold: float, page: int=1, page_size: int=10) -> dict:
    if not isinstance(readings, list) or isinstance(moisture_threshold, bool) or (not isinstance(moisture_threshold, (int, float))) or (not math.isfinite(moisture_threshold)):
        raise ValueError()
    if isinstance(page, bool) or not isinstance(page, int) or page < 1 or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (page_size < 1):
        raise ValueError()
    grouped = {}
    for reading in readings:
        if not isinstance(reading, dict) or not isinstance(reading.get('plot'), str) or (not reading['plot']) or (not isinstance(reading.get('crop'), str)):
            raise ValueError()
        moisture = reading.get('moisture')
        hectares = reading.get('hectares')
        if isinstance(moisture, bool) or not isinstance(moisture, (int, float)) or (not math.isfinite(moisture)) or isinstance(hectares, bool) or (not isinstance(hectares, (int, float))) or (not math.isfinite(hectares)) or (hectares <= 0):
            raise ValueError()
        if reading['plot'] not in grouped:
            grouped[reading['plot']] = [reading['crop'], 0.0, 0.0, 0]
        grouped[reading['plot']][1] += hectares
        grouped[reading['plot']][2] += moisture
        grouped[reading['plot']][3] += 1
    plots = []
    for plot, (crop, area, moisture_sum, count) in grouped.items():
        average = moisture_sum / count
        if average < moisture_threshold:
            plots.append({'plot': plot, 'crop': crop, 'hectares': round(area, 2), 'average_moisture': round(average, 2), 'water_liters': round(area * (moisture_threshold - average) * 12, 2)})
    plots.sort(key=lambda item: (-item['water_liters'], item['plot']))
    start = (page - 1) * page_size
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(24)))
    return {'code': code, 'page': page, 'page_size': page_size, 'total': len(plots), 'plots': plots[start:start + page_size]}

