        if isinstance(moisture, bool) or not isinstance(moisture, (int, float)) or (not math.isfinite(moisture)) or isinstance(hectares, bool) or (not isinstance(hectares, (int, float))) or (not math.isfinite(hectares)) or (hectares <= 0):
            raise ValueError()
        if reading['plot'] not in grouped:
            grouped[reading['plot']] = [reading['crop'], 0.0, 0.0, 0]
        grouped[reading['plot']][1] += hectares
        grouped[reading['plot']][2] += moisture
        grouped[reading['plot']][3] += 1
    plots = []
    for plot, (crop, area, moisture_sum, count) in grouped.items():
        average = moisture_sum / count
        if average < moisture_threshold:
            plots.append({'plot': plot, 'crop': crop, 'hectares': round(area, 2), 'average_moisture': round(average, 2), 'water_liters': round(area * (moisture_threshold - average) * 12, 2)})
