def parse_coupon_batch(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise ValueError('batch must be text')
    combined = {}
    order = []
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        left = []
        right = []
        target = left
        escaped = False
        for ch in raw:
            if escaped:
                if ch not in ('=', '\\'):
                    raise ValueError('bad escape')
                target.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '=' and target is left:
                target = right
            else:
                target.append(ch)
        if escaped or target is left:
            raise ValueError('bad record')
        code = ''.join(left).strip()
        qty = ''.join(right)
        if not code or not qty.isdigit() or (qty.startswith('0') and len(qty) > 1) or (int(qty) <= 0):
            raise ValueError('bad record')
        n = int(qty)
        if code not in combined:
            order.append(code)
            combined[code] = 0
        combined[code] += n
    return [(code, combined[code]) for code in order]

def redeem_coupon_batch(requester: dict, campaign: dict, batch_text: str, ledger: dict, now: int) -> list[dict]:
    if requester.get('tenant_id') != campaign.get('tenant_id') or (requester.get('id') != campaign.get('owner_id') and 'coupon_manager' not in requester.get('roles', [])):
        raise PermissionError('not permitted')
    if not campaign['active_from'] <= now <= campaign['active_until']:
        raise ValueError('inactive campaign')
    requests = parse_coupon_batch(batch_text)
    planned = []
    for code, quantity in requests:
        if code not in campaign['coupons']:
            raise ValueError('unknown coupon')
        item = campaign['coupons'][code]
        previous = sum((x == requester['id'] for x in ledger.get(code, [])))
        existing = len(ledger.get(code, []))
        if existing + quantity > item['stock'] or previous + quantity > item['per_user_limit']:
            raise ValueError('limit exceeded')
        planned.append((code, quantity, item))
    for code, quantity, item in planned:
        ledger.setdefault(code, []).extend([requester['id']] * quantity)
    return [{'code': code, 'quantity': quantity, 'value': item['value'], 'total': quantity * item['value']} for code, quantity, item in sorted(planned, key=lambda x: (-x[2]['value'], x[0]))]

def coupon_summary(campaign: dict, ledger: dict) -> dict:
    return {code: {'redeemed': len(ledger.get(code, [])), 'remaining': item['stock'] - len(ledger.get(code, [])), 'value': item['value']} for code, item in sorted(campaign['coupons'].items())}

