from datetime import date
from decimal import Decimal, ROUND_HALF_UP

def summarize_maintenance(requester: dict, vehicles: list[dict], records: list[dict], start_date: str, end_date: str, page: int=1, page_size: int=10) -> dict:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except ValueError:
        raise ValueError('invalid date')
    if start > end or type(page) is not int or type(page_size) is not int or (page < 1) or (page_size < 1):
        raise ValueError('invalid range')
    requester_id = requester['id']
    tenant = requester['tenant_id']
    roles = requester['roles']
    allowed = {}
    manager = 'fleet_manager' in roles
    for vehicle in vehicles:
        if vehicle['tenant_id'] == tenant and (manager or vehicle['owner_id'] == requester_id):
            allowed[vehicle['id']] = {'count': 0, 'cost': Decimal('0'), 'hours': Decimal('0')}
    for record in records:
        vid = record['vehicle_id']
        if vid not in allowed or record['status'] != 'completed':
            continue
        day = date.fromisoformat(record['date'])
        if start <= day <= end:
            allowed[vid]['count'] += 1
            allowed[vid]['cost'] += Decimal(str(record['cost']))
            allowed[vid]['hours'] += Decimal(str(record['hours']))

    def money(x):
        return float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

    def hours(x):
        return float(x.quantize(Decimal('0.1'), rounding=ROUND_HALF_UP))
    rows = []
    for vid, values in allowed.items():
        rows.append({'vehicle_id': vid, 'completed_count': values['count'], 'total_cost': money(values['cost']), 'total_hours': hours(values['hours'])})
    rows.sort(key=lambda row: (-row['total_cost'], row['vehicle_id']))
    total_cost = money(sum((v['cost'] for v in allowed.values()), Decimal('0')))
    total_hours = hours(sum((v['hours'] for v in allowed.values()), Decimal('0')))
    total_completed = sum((v['count'] for v in allowed.values()))
    begin = (page - 1) * page_size
