import ast

def _evaluate(node, env):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float, bool)) or node.value is None:
            return node.value
        raise ValueError('unsupported constant')
    if isinstance(node, ast.Name):
        if node.id in env:
            return env[node.id]
        raise NameError(node.id)
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left = _evaluate(node.left, env)
        right = _evaluate(node.right, env)
        return {ast.Add: lambda: left + right, ast.Sub: lambda: left - right, ast.Mult: lambda: left * right, ast.Div: lambda: left / right}[type(node.op)]()
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, env)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _evaluate(node.values[0], env)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _evaluate(item, env)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, env)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, env)
            good = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}.get(type(op))
            if good is None:
                raise ValueError('unsupported comparison')
            if not good:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (not node.keywords) and (node.func.id in ('min', 'max', 'round')):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(a, env) for a in node.args])
    raise ValueError('unsupported expression')

