def redeem_rewards(points: int, offers: list[dict], requested_ids: list[str]) -> dict:
    if type(points) is not int or points < 0:
        raise TypeError('points must be a non-negative integer')
    if not isinstance(offers, list) or not isinstance(requested_ids, list) or (not all((isinstance(x, str) for x in requested_ids))):
        raise TypeError('invalid arguments')
    lookup = {}
    for offer in offers:
        if not isinstance(offer, dict) or not isinstance(offer.get('id'), str) or (not isinstance(offer.get('cost'), int)) or (type(offer.get('available')) is not bool) or (not isinstance(offer.get('category'), str)) or (offer['cost'] < 0):
            raise TypeError('invalid offer')
        if offer['id'] in lookup:
            raise ValueError('duplicate offer ID')
        lookup[offer['id']] = offer
    chosen = []
    seen = set()
    for ident in requested_ids:
        if ident in seen:
            continue
        seen.add(ident)
        if ident not in lookup:
            raise KeyError(ident)
        offer = lookup[ident]
        if not offer['available']:
            raise ValueError('offer unavailable')
        chosen.append(offer)
    chosen.sort(key=lambda x: (x['category'], x['id']))
    spent = sum((x['cost'] for x in chosen))
    if spent > points:
        raise ValueError('insufficient points')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(12)))
    return {'code': code, 'items': chosen, 'spent': spent, 'remaining': points - spent}

