import os
import math
from datetime import date
from decimal import Decimal, ROUND_HALF_UP

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    rounds = 120000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
    return f'{rounds}${salt.hex()}${digest.hex()}'

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    try:
        rounds_text, salt_text, digest_text = stored.split('$')
        rounds = int(rounds_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        if rounds < 1 or not salt or (not expected):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def categorize_transactions(transactions: list[dict], rules: dict[str, list[str]], opening_balance: float=0.0) -> list[dict]:
    if not isinstance(rules, dict):
        raise ValueError('invalid rules')
    if isinstance(opening_balance, bool) or not isinstance(opening_balance, (int, float)) or (not math.isfinite(opening_balance)):
        raise ValueError('invalid opening balance')
    rule_list = []
    for category, keywords in rules.items():
        if not isinstance(category, str) or not isinstance(keywords, list) or any((not isinstance(k, str) for k in keywords)):
            raise ValueError('invalid rules')
        rule_list.append((category, [k.casefold() for k in keywords if k]))
