    for index, item in enumerate(transactions):
        if not isinstance(item, dict) or not all((k in item for k in ('date', 'description', 'amount'))):
            raise ValueError('invalid transaction')
        if not isinstance(item['date'], str) or not isinstance(item['description'], str):
            raise ValueError('invalid transaction')
        amount = item['amount']
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)):
            raise ValueError('invalid transaction')
        try:
            parsed = date.fromisoformat(item['date'])
        except ValueError:
            raise ValueError('invalid transaction')
        prepared.append((parsed, index, item))
    prepared.sort(key=lambda x: (x[0], x[1]))
    balance = float(opening_balance)
    output = []
    for _, _, item in prepared:
        text = item['description'].casefold()
        category = 'Uncategorized'
