            continue
        if len(row) != 3:
            raise ValueError('invalid paper row')
        raw_id, title, raw_authors = row
        try:
            paper_id = int(raw_id.strip())
        except ValueError:
            raise ValueError('invalid paper id')
        if paper_id <= 0 or paper_id in seen or (not title):
            raise ValueError('invalid paper')
        authors = [part.strip() for part in raw_authors.split(';')]
        if not authors or any((not author for author in authors)):
            raise ValueError('invalid authors')
        seen.add(paper_id)
        result.append({'id': paper_id, 'title': title, 'authors': authors})
    return result

def assign_reviewers(papers: list[dict], reviewers: list[dict], load_limit: int=2) -> dict[int, list[str]]:
    if load_limit < 1:
        raise ValueError('invalid load limit')
    if len({paper['id'] for paper in papers}) != len(papers):
        raise ValueError('duplicate paper')
    if len({reviewer['id'] for reviewer in reviewers}) != len(reviewers):
        raise ValueError('duplicate reviewer')
    loads = {reviewer['id']: 0 for reviewer in reviewers}
    result = {}
    for paper in sorted(papers, key=lambda item: item['id']):
        eligible = []
        for reviewer in reviewers:
            if loads[reviewer['id']] >= load_limit:
                continue
            if set(paper['authors']) & set(reviewer['conflicts']):
                continue
            eligible.append(reviewer)
        eligible.sort(key=lambda reviewer: (-reviewer['bids'].get(paper['id'], 0), loads[reviewer['id']], reviewer['id']))
        if len(eligible) < 2:
            raise ValueError('not enough reviewers')
        chosen = eligible[:2]
        result[paper['id']] = [reviewer['id'] for reviewer in chosen]
        for reviewer in chosen:
            loads[reviewer['id']] += 1
    return result

