    for reviewers in assignments.values():
        for reviewer_id in reviewers:
            if not isinstance(reviewer_id, str) or not reviewer_id:
                raise ValueError('invalid reviewer id')
            ids.add(reviewer_id)
    return {reviewer_id: generate_invite_code() for reviewer_id in sorted(ids)}

