import hashlib
import hmac
import json
from datetime import date
from decimal import Decimal, InvalidOperation

def canonical_report_payload(report: dict) -> bytes:
    return json.dumps(report, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def sign_report(payload: bytes, config: dict) -> str:
    try:
        key = config['report_signing_key']
    except (KeyError, TypeError):
        raise ValueError('missing report_signing_key')
    if not isinstance(key, str):
        raise ValueError('report_signing_key must be a string')
    return hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()

def build_cost_report(records: list[dict], config: dict, month: str) -> dict:
    if len(month) != 7 or month[4] != '-' or (not month[:4].isdigit()) or (not month[5:].isdigit()):
        raise ValueError('invalid month')
    try:
        date(int(month[:4]), int(month[5:]), 1)
    except ValueError:
        raise ValueError('invalid month')
    services = {}
    resources = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('date'), str):
            raise ValueError('invalid record')
        if not record['date'].startswith(month):
            continue
        for field in ('resource_id', 'service', 'region', 'amount'):
            if field not in record or not isinstance(record[field], str):
                raise ValueError('invalid record')
        try:
            parsed_date = date.fromisoformat(record['date'])
            amount = Decimal(record['amount'])
            credits = Decimal(record.get('credits', '0'))
        except (ValueError, InvalidOperation, TypeError):
            raise ValueError('invalid record')
        if parsed_date.strftime('%Y-%m') != month or amount < 0 or credits < 0 or (credits > amount):
            raise ValueError('invalid record')
        net = amount - credits
        service = record['service']
        identity = (record['resource_id'], service, record['region'])
        services[service] = services.get(service, Decimal('0')) + net
        resources[identity] = resources.get(identity, Decimal('0')) + net
    money = lambda value: format(value.quantize(Decimal('0.01')), '.2f')
    by_service = dict(((name, money(total)) for name, total in sorted(services.items(), key=lambda x: (-x[1], x[0]))))
    rows = [{'resource_id': k[0], 'service': k[1], 'region': k[2], 'total': money(v)} for k, v in resources.items()]
    rows.sort(key=lambda x: (-Decimal(x['total']), x['resource_id'], x['region']))
    report = {'month': month, 'total': money(sum(services.values(), Decimal('0'))), 'by_service': by_service, 'resources': rows}
    report['signature'] = sign_report(canonical_report_payload(report), config)
    return report

