import hashlib
import os
from datetime import date

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isascii()) or (not pin.isdecimal()):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 120000)
    return salt.hex() + ':' + digest.hex()

def verify_pin(pin: str, stored_hash: str) -> bool:
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isascii()) or (not pin.isdecimal()) or (not isinstance(stored_hash, str)):
        return False
    try:
        salt_hex, digest_hex = stored_hash.split(':')
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 120000)
    return actual == expected

