        raise ValueError('invalid passport')
    if not isinstance(destination, str) or not destination:
        raise ValueError('invalid destination')
    try:
        start = date.fromisoformat(departure)
        finish = date.fromisoformat(return_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if len(departure) != 10 or len(return_date) != 10 or finish <= start:
        raise ValueError('invalid date range')
    return {'passport_id': passport_id, 'destination': destination, 'departure': departure, 'return_date': return_date, 'pin_hash': hash_pin(pin)}

