    if not isinstance(page, int) or not isinstance(page_size, int) or page < 1 or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid pagination')
    groups = {}
    for record in records:
        nights = (date.fromisoformat(record['return_date']) - date.fromisoformat(record['departure'])).days
        item = groups.setdefault(record['destination'], [0, 0])
        item[0] += 1
        item[1] += nights
    result = [{'destination': name, 'count': value[0], 'total_nights': value[1], 'average_nights': round(value[1] / value[0], 2)} for name, value in groups.items()]
