from datetime import datetime, timezone
import math
import requests

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    text = value[:-1] + '+00:00' if value.endswith('Z') else value
    try:
        result = datetime.fromisoformat(text)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if result.tzinfo is None:
        raise ValueError('timestamp needs timezone')
    return result.astimezone(timezone.utc)

def fetch_meter_readings(meter_id: str, start: str, end: str, api_key: str) -> list[dict]:
    response = requests.get(f'https://api.gas.example/v1/meters/{meter_id}/readings', params={'start': start, 'end': end}, headers={'X-API-Key': api_key})
    if response.status_code != 200:
        raise RuntimeError(f'HTTP status {response.status_code}')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('readings'), list):
        raise ValueError('invalid readings payload')
    found = []
    for item in payload['readings']:
        if not isinstance(item, dict) or 'timestamp' not in item or 'm3' not in item:
            raise ValueError('invalid reading')
        stamp = _time(item['timestamp'])
        try:
            number = float(item['m3'])
        except (TypeError, ValueError):
            raise ValueError('invalid meter value')
        if not math.isfinite(number) or number < 0:
            raise ValueError('invalid meter value')
        found.append((stamp, number))
    found.sort(key=lambda pair: pair[0])
    if any((found[i][0] == found[i - 1][0] for i in range(1, len(found)))):
        raise ValueError('duplicate timestamp')
    return [{'timestamp': stamp.strftime('%Y-%m-%dT%H:%M:%SZ'), 'm3': number} for stamp, number in found]

def daily_consumption(readings: list[dict]) -> list[dict]:
    if not isinstance(readings, list):
        raise ValueError('invalid readings')
    parsed = []
    for item in readings:
        if not isinstance(item, dict) or set(item) != {'timestamp', 'm3'}:
            raise ValueError('invalid reading')
        stamp = _time(item['timestamp'])
        try:
            number = float(item['m3'])
        except (TypeError, ValueError):
            raise ValueError('invalid meter value')
        if not math.isfinite(number) or number < 0:
            raise ValueError('invalid meter value')
        parsed.append((stamp, number))
    parsed.sort(key=lambda pair: pair[0])
    totals = {}
    for index in range(1, len(parsed)):
        if parsed[index][0] == parsed[index - 1][0] or parsed[index][1] < parsed[index - 1][1]:
            raise ValueError('invalid sequence')
        day = parsed[index][0].strftime('%Y-%m-%d')
        totals[day] = totals.get(day, 0.0) + parsed[index][1] - parsed[index - 1][1]
    return [{'date': day, 'm3': round(totals[day], 3)} for day in sorted(totals)]

def meter_report(meter_id: str, start: str, end: str, api_key: str) -> list[dict]:
    return daily_consumption(fetch_meter_readings(meter_id, start, end, api_key))

