import subprocess

def analyze_crossing_alerts(log_path: str, min_severity: int=1, page: int=1, page_size: int=10) -> dict:
    if not isinstance(min_severity, int) or min_severity < 0 or min_severity > 5:
        raise ValueError('invalid severity')
    if not isinstance(page, int) or page <= 0 or (not isinstance(page_size, int)) or (page_size <= 0):
        raise ValueError('invalid pagination')
    try:
        result = subprocess.run(['sort', '-t', '|', '-k2,2', '-k1,1', log_path], capture_output=True, text=True, check=True)
    except (FileNotFoundError, subprocess.CalledProcessError) as exc:
        raise OSError(str(exc)) from exc
    groups = {}
    total = 0
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        parts = raw.split('|', 3)
        if len(parts) != 4 or not parts[0] or (not parts[1]) or ('|' in parts[3]):
            raise ValueError('malformed record')
        timestamp, crossing, severity_text, message = parts
        try:
            severity = int(severity_text)
        except ValueError as exc:
            raise ValueError('malformed record') from exc
        if severity < 0 or severity > 5:
            raise ValueError('malformed record')
        if severity < min_severity:
            continue
        groups.setdefault(crossing, []).append({'timestamp': timestamp, 'severity': severity, 'message': message})
        total += 1
    names = sorted(groups)
    start = (page - 1) * page_size
    selected = []
    for name in names[start:start + page_size]:
        alerts = groups[name]
        selected.append({'crossing': name, 'count': len(alerts), 'max_severity': max((a['severity'] for a in alerts)), 'alerts': alerts})
    return {'total': total, 'page': page, 'page_size': page_size, 'crossings': selected}

