import csv
import hashlib
import hmac
import io
import math

def parse_measurement_line(line: str) -> tuple[int, str, float, float]:
    if not isinstance(line, str) or '\n' in line or '\r' in line:
        raise ValueError('invalid record')
    try:
        fields = next(csv.reader([line]))
    except (csv.Error, StopIteration):
        raise ValueError('invalid record')
    if len(fields) != 4:
        raise ValueError('invalid record')
    try:
        timestamp = int(fields[0])
        temperature = float(fields[2])
        value = float(fields[3])
    except (TypeError, ValueError, OverflowError):
        raise ValueError('invalid record')
    sample = fields[1].strip()
    if timestamp < 0 or not sample or (not math.isfinite(temperature)) or (not math.isfinite(value)):
        raise ValueError('invalid record')
    return (timestamp, sample, temperature, value)

def summarize_experiment(payload: bytes, signature: str, secret: bytes) -> dict:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid input')
    if len(signature) != 64:
        raise ValueError('invalid signature')
    try:
        supplied = bytes.fromhex(signature)
    except ValueError:
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).digest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        text = payload.decode('utf-8')
    except UnicodeDecodeError:
        raise ValueError('invalid payload')
    lines = text.splitlines()
    if not lines or not lines[0].startswith('RUN ') or (not lines[0][4:]):
        raise ValueError('invalid header')
    run_id = lines[0][4:]
    samples = {}
    windows = {}
    for line in lines[1:]:
        if not line:
            continue
        timestamp, sample, temperature, value = parse_measurement_line(line)
        item = samples.setdefault(sample, [0, temperature, temperature, 0.0])
        item[0] += 1
        item[1] = min(item[1], temperature)
        item[2] = max(item[2], temperature)
        item[3] += value
        start = timestamp // 60 * 60
        win = windows.setdefault(start, [0, 0.0])
        win[0] += 1
        win[1] += value
    return {'run_id': run_id, 'samples': {k: {'count': v[0], 'temperature_range': [v[1], v[2]], 'value_mean': v[3] / v[0]} for k, v in sorted(samples.items())}, 'windows': [{'start': k, 'count': v[0], 'value_mean': v[1] / v[0]} for k, v in sorted(windows.items())]}

