import operator

def filter_reminders(reminders: list[dict], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc

    def visit(node, env):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in env:
            return env[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            fn = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)]
            return fn(visit(node.left, env), visit(node.right, env))
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand, env)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = visit(node.values[0], env)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = visit(item, env)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left, env)
            ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            result = True
            for op, part in zip(node.ops, node.comparators):
                right = visit(part, env)
                result = result and ops[type(op)](left, right)
                left = right
            return result
        raise ValueError('invalid rule')
    result = []
    for reminder in reminders:
        env = {'dose': reminder['dose_mg'], 'hour': reminder['hour'], 'taken': reminder['taken']}
        try:
            if visit(tree, env):
                result.append(reminder['name'])
        except (NameError, KeyError) as exc:
            raise ValueError('unknown name') from exc
    return result

