import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError()
    if not password:
        raise ValueError()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not password or (not isinstance(stored, str)):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_health(records: list[dict], min_temperature: float, page: int, page_size: int) -> list[dict]:
    if page <= 0 or page_size <= 0:
        raise ValueError()
    groups = {}
    for record in records:
        if not all((key in record for key in ('animal_id', 'temperature', 'timestamp'))):
            raise ValueError()
        animal_id = record['animal_id']
        temperature = record['temperature']
        timestamp = record['timestamp']
        if not isinstance(animal_id, str) or not animal_id:
            raise ValueError()
        if isinstance(temperature, bool) or not isinstance(temperature, (int, float)):
            raise ValueError()
        if isinstance(timestamp, bool) or not isinstance(timestamp, int):
            raise ValueError()
        if temperature >= min_temperature:
            groups.setdefault(animal_id, []).append((temperature, timestamp))
    result = []
    for animal_id, values in groups.items():
        result.append({'animal_id': animal_id, 'count': len(values), 'average_temperature': round(sum((v[0] for v in values)) / len(values), 2), 'latest_timestamp': max((v[1] for v in values))})
    result.sort(key=lambda item: (-item['average_temperature'], item['animal_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

