import hmac

def screen_participants(header: str, expected_token: str, participants: list[dict[str, object]]) -> list[str]:
    parts = header.split(' ')
    if len(parts) != 2 or parts[0] != 'Bearer' or (not parts[1]):
        raise ValueError('invalid header')
    token = parts[1]
    if not hmac.compare_digest(token, expected_token):
        raise PermissionError('token rejected')
    result = [participant['id'] for participant in participants if participant['status'] == 'candidate' and participant['age'] >= 18]
    return sorted(result)

