import hmac
import json

def build_fulfillment_report(payload: str, signature: str, signing_key: bytes, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid pagination')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(signing_key, bytes)):
        raise ValueError('invalid input')
    expected = hmac.new(signing_key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        records = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(records, list):
        raise ValueError('invalid payload')
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        drug = record.get('drug')
        quantity = record.get('quantity')
        status = record.get('status')
        if not isinstance(drug, str) or not drug or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity <= 0) or (not isinstance(status, str)) or (status not in {'fulfilled', 'cancelled', 'pending'}):
            raise ValueError('invalid record')
        if status == 'fulfilled':
            if drug not in totals:
                totals[drug] = [0, 0]
            totals[drug][0] += quantity
            totals[drug][1] += 1
    groups = sorted(totals.items(), key=lambda pair: (-pair[1][0], pair[0]))
    start = (page - 1) * page_size
    items = [{'drug': drug, 'quantity': values[0], 'prescriptions': values[1]} for drug, values in groups[start:start + page_size]]
    return {'page': page, 'page_size': page_size, 'total_groups': len(groups), 'items': items}

