import os
import tempfile

def make_log(lines):
    handle = tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', delete=False)
    try:
        handle.write('\n'.join(lines) + '\n')
        return handle.name
    finally:
        handle.close()

def test_keyword_filters_complete_lines_and_is_case_sensitive():
    path = make_log(['2024-01-01|A|chemical|12', '2023-01-01|B|chemical|99', '2024-01-02|C|Chemical|8', '2024-01-03|D|spill|5'])
    try:
        assert generate_training_report(path, '2024') == [('chemical', 1, 12), ('Chemical', 1, 8), ('spill', 1, 5)]
    finally:
        os.unlink(path)

def test_ties_are_sorted_by_hazard_name():
    path = make_log(['x|a|zeta|10', 'x|b|alpha|10', 'x|c|middle|10'])
    try:
        assert generate_training_report(path, 'x') == [('alpha', 1, 10), ('middle', 1, 10), ('zeta', 1, 10)]
    finally:
        os.unlink(path)

def test_pagination_boundaries_and_empty_page():
    path = make_log(['x|a|one|40', 'x|b|two|30', 'x|c|three|20', 'x|d|four|10'])
    try:
        assert generate_training_report(path, 'x', 1, 2) == [('one', 1, 40), ('two', 1, 30)]
        assert generate_training_report(path, 'x', 2, 2) == [('three', 1, 20), ('four', 1, 10)]
        assert generate_training_report(path, 'x', 3, 2) == []
    finally:
        os.unlink(path)

def test_invalid_pagination_raises_value_error():
    path = make_log(['x|a|chemical|3'])
    try:
        for page, size in [(0, 1), (1, 0), (-1, 2), (2, -4)]:
            try:
                generate_training_report(path, 'x', page, size)
                assert False
            except ValueError:
                pass
    finally:
        os.unlink(path)

def test_malformed_matching_records_raise_value_error():
    cases = [['x|a|chemical'], ['x|a||5'], ['x|a|chemical|-1'], ['x|a|chemical|many']]
    for lines in cases:
        path = make_log(lines)
        try:
            try:
                generate_training_report(path, 'x')
                assert False
            except ValueError:
                pass
        finally:
            os.unlink(path)

def test_nonmatching_malformed_lines_are_ignored_and_no_matches_are_empty():
    path = make_log(['other|a|chemical|bad', 'other|b|chemical'])
    try:
        assert generate_training_report(path, 'missing') == []
    finally:
