def generate_training_report(log_path: str, keyword: str, page: int=1, page_size: int=10) -> List[Tuple[str, int, int]]:
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    result = subprocess.run(['grep', '-F', '--', keyword, log_path], capture_output=True, text=True)
    if result.returncode == 2:
        raise FileNotFoundError(log_path)
    groups = {}
    if result.returncode == 0:
        for line in result.stdout.splitlines():
            fields = line.split('|')
            if len(fields) != 4:
                raise ValueError('malformed record')
            _, _, hazard, minutes_text = fields
            if not hazard:
                raise ValueError('empty hazard')
            try:
                minutes = int(minutes_text)
            except ValueError:
                raise ValueError('invalid minutes')
            if minutes < 0:
                raise ValueError('invalid minutes')
            count, total = groups.get(hazard, (0, 0))
            groups[hazard] = (count + 1, total + minutes)
    summary = [(hazard, count, total) for hazard, (count, total) in groups.items()]
    summary.sort(key=lambda item: (-item[2], item[0]))
    start = (page - 1) * page_size
    return summary[start:start + page_size]

