import hashlib
import hmac
import os

def create_device(device_id: str, pin: str) -> dict[str, str]:
    if not isinstance(device_id, str) or not device_id:
        raise ValueError('invalid device_id')
    if not isinstance(pin, str) or not 4 <= len(pin) <= 32:
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'device_id': device_id, 'pin_hash': salt.hex() + ':' + digest.hex()}

def authenticate_device(device: dict[str, str], pin: str) -> bool:
    try:
        salt_text, digest_text = device['pin_hash'].split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError, AttributeError):
        return False

def summarize_telemetry(readings: list[dict], start: int, end: int, page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(start, int) or not isinstance(end, int) or start > end:
        raise ValueError('invalid range')
    if not isinstance(page, int) or not isinstance(page_size, int) or page < 1 or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    groups = {}
    for reading in readings:
        try:
            device_id = reading['device_id']
            timestamp = reading['timestamp']
            temperature = reading['temperature']
            power = reading['power']
        except (KeyError, TypeError):
            raise ValueError('invalid reading')
        if not isinstance(device_id, str) or not device_id or (not isinstance(timestamp, int)) or isinstance(temperature, bool) or (not isinstance(temperature, (int, float))) or isinstance(power, bool) or (not isinstance(power, (int, float))):
            raise ValueError('invalid reading')
        if start <= timestamp <= end:
            groups.setdefault(device_id, []).append((temperature, power))
    result = []
    for device_id in sorted(groups):
        values = groups[device_id]
        temperatures = [x[0] for x in values]
        result.append({'device_id': device_id, 'reading_count': len(values), 'average_temperature': round(sum(temperatures) / len(values), 2), 'total_power': round(sum((x[1] for x in values)), 2), 'max_temperature': round(max(temperatures), 2)})
    offset = (page - 1) * page_size
    return result[offset:offset + page_size]

