import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError('unknown variable')
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _evaluate(node.values[0], values)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result):
                return result
            if isinstance(node.op, ast.Or) and result:
                return result
            result = _evaluate(child, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, child in zip(node.ops, node.comparators):
            right = _evaluate(child, values)
            if type(op) not in {ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq}:
                raise ValueError('unsupported expression')
            if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(arg, values) for arg in node.args])
    raise ValueError('unsupported expression')

def recommend_articles(articles: list[dict], formula: str, limit: int=10) -> list[dict]:
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('invalid limit')
    try:
        tree = ast.parse(formula, mode='eval').body
    except (SyntaxError, TypeError):
        raise ValueError('invalid formula')
    scored = []
    for index, article in enumerate(articles):
        values = {name: article[name] for name in ('views', 'likes', 'comments', 'age_days')}
        try:
            score = _evaluate(tree, values)
        except KeyError:
            raise ValueError('invalid article')
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise ValueError('formula must be numeric')
        if score > 0:
            scored.append((score, index, article))
    scored.sort(key=lambda item: item[0], reverse=True)
    return [{'id': article['id'], 'title': article['title'], 'score': round(float(score), 2)} for score, _, article in scored[:limit]]

