import sqlite3

def find_permits(conn: sqlite3.Connection, district: str | None=None, status: str | None=None, applicant_query: str | None=None, sort_by: str='issued_at', descending: bool=False) -> list[dict]:
    columns = {'id', 'permit_code', 'district', 'applicant', 'status', 'issued_at', 'expires_at', 'fee_cents', 'paid_cents'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    sql = 'SELECT id, permit_code, district, applicant, status, issued_at, expires_at, fee_cents, paid_cents FROM permits'
    clauses = []
    args = []
    if district is not None:
        clauses.append('district = ?')
        args.append(district)
    if status is not None:
        clauses.append('status = ?')
        args.append(status)
    if applicant_query is not None:
        clauses.append('LOWER(applicant) LIKE LOWER(?)')
        args.append('%' + applicant_query + '%')
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    sql += ' ORDER BY ' + sort_by + (' DESC' if descending else ' ASC') + ', id ASC'
    rows = conn.execute(sql, args).fetchall()
    names = ['id', 'permit_code', 'district', 'applicant', 'status', 'issued_at', 'expires_at', 'fee_cents', 'paid_cents']
    return [dict(zip(names, row)) for row in rows]

def record_payment(conn: sqlite3.Connection, permit_id: int, amount_cents: int) -> dict:
    if isinstance(amount_cents, bool) or not isinstance(amount_cents, int) or amount_cents <= 0:
        raise ValueError('amount must be a positive integer')
    row = conn.execute('SELECT fee_cents, paid_cents FROM permits WHERE id = ?', (permit_id,)).fetchone()
    if row is None:
        raise LookupError('permit not found')
    paid = (row[1] or 0) + amount_cents
    conn.execute('UPDATE permits SET paid_cents = ? WHERE id = ?', (paid, permit_id))
    conn.commit()
    return {'id': permit_id, 'paid_cents': paid, 'remaining_cents': max((row[0] or 0) - paid, 0)}

def district_report(conn: sqlite3.Connection) -> list[dict]:
    rows = conn.execute('SELECT district, status, fee_cents, paid_cents FROM permits').fetchall()
    groups = {}
    for district, status, fee, paid in rows:
        group = groups.setdefault(district, [0, 0, 0, 0])
        group[0] += 1
        group[1] += fee or 0
        group[2] += paid or 0
        group[3] += status == 'active'
    result = []
    for district, (count, fee, paid, active) in groups.items():
        result.append({'district': district, 'permit_count': count, 'total_fee_cents': fee, 'total_paid_cents': paid, 'outstanding_cents': max(fee - paid, 0), 'active_count': active})
    return sorted(result, key=lambda x: (-x['outstanding_cents'], x['district']))

