import os
import subprocess

def rank_variance_requests(file_path: str, district: str | None=None, min_score: float=0.0, limit: int=10) -> list[dict]:
    if not isinstance(file_path, str) or not isinstance(limit, int) or isinstance(limit, bool) or (limit <= 0):
        raise ValueError('invalid arguments')
    if district is not None and (not isinstance(district, str)):
        raise ValueError('invalid arguments')
    if not isinstance(min_score, (int, float)) or isinstance(min_score, bool) or (not math.isfinite(min_score)):
        raise ValueError('invalid arguments')
    try:
        result = subprocess.run(['sort', '-t,', '-k3,3nr', '-k1,1', file_path], capture_output=True, text=True, check=True, env={**os.environ, 'LC_ALL': 'C'})
    except (OSError, subprocess.CalledProcessError):
        raise ValueError('could not read requests')
    requests = []
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 4:
            raise ValueError('malformed request')
        request_id, row_district, score_text, status = fields
        try:
            score = float(score_text)
        except ValueError:
            raise ValueError('malformed request')
        if not math.isfinite(score) or status not in {'approved', 'pending', 'denied'}:
            raise ValueError('malformed request')
        if status == 'approved' and (district is None or row_district == district) and (score >= min_score):
            requests.append({'request_id': request_id, 'district': row_district, 'score': score, 'status': status})
            if len(requests) == limit:
                break
    return requests

