import subprocess

def maintenance_totals(log_path: str, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    try:
        result = subprocess.run(['sort', '-t,', '-k1,1', '-k2,2', log_path], check=True, capture_output=True, text=True)
    except (OSError, subprocess.CalledProcessError) as exc:
        raise ValueError('unable to read log') from exc
    totals = {}
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 4:
            raise ValueError('malformed record')
        date, device, minutes_text, status = fields
        try:
            datetime.date.fromisoformat(date)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if not device or status not in {'completed', 'planned', 'cancelled'}:
            raise ValueError('invalid record')
        try:
            minutes = int(minutes_text)
        except ValueError as exc:
            raise ValueError('invalid minutes') from exc
        if minutes < 0:
            raise ValueError('invalid minutes')
        if status == 'completed':
            if device not in totals:
                totals[device] = [0, 0]
            totals[device][0] += minutes
            totals[device][1] += 1
    ordered = sorted(totals.items(), key=lambda item: (-item[1][0], item[0]))
    start = (page - 1) * page_size
    return [{'device': device, 'minutes': values[0], 'jobs': values[1]} for device, values in ordered[start:start + page_size]]

