import base64
import datetime
import hashlib
import hmac
import os

def make_pin_record(pin: str) -> str:
    if not isinstance(pin, str) or not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return base64.b64encode(salt + digest).decode('ascii')

def verify_pin(pin: str, record: str) -> bool:
    try:
        raw = base64.b64decode(record.encode('ascii'), validate=True)
        if len(raw) != 48 or not isinstance(pin, str):
            return False
        salt, expected = (raw[:16], raw[16:])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, TypeError, ValueError):
        return False

