from datetime import date, timedelta
from html import escape

def _parts(line):
    result = []
    field = []
    escaped = False
    for char in line:
        if escaped:
            field.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            result.append(''.join(field))
            field = []
        else:
            field.append(char)
    if escaped:
        raise ValueError('trailing escape')
    result.append(''.join(field))
    return result

def _day(value):
    try:
        parsed = date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def parse_reservations(data: str) -> list[dict]:
    items = []
    for raw in data.splitlines():
        line = raw.strip()
        if not line:
            continue
        fields = _parts(line)
        if len(fields) != 5:
            raise ValueError('wrong field count')
        arrival, guest, site, nights, guests = fields
        _day(arrival)
        if not guest or not site:
            raise ValueError('empty field')
        try:
            nights = int(nights)
            guests = int(guests)
        except ValueError:
            raise ValueError('invalid number')
        if not 1 <= nights <= 30 or not 1 <= guests <= 12:
            raise ValueError('number out of range')
        items.append({'arrival': arrival, 'guest': guest, 'site': site, 'nights': nights, 'guests': guests})
    return sorted(items, key=lambda x: (x['arrival'], x['site'], x['guest']))

def occupancy_by_site(reservations: list[dict], start: str, end: str) -> dict[str, int]:
    first, last = (_day(start), _day(end))
    if first >= last:
        raise ValueError('invalid interval')
    totals = {}
    for item in reservations:
        arrival = _day(item['arrival'])
        departure = arrival + timedelta(days=item['nights'])
        overlap = max(0, (min(departure, last) - max(arrival, first)).days)
        if overlap:
            totals[item['site']] = totals.get(item['site'], 0) + overlap * item['guests']
    return dict(sorted(totals.items()))

def render_report(reservations: list[dict], title: str) -> str:
    rows = []
    total = 0
    for item in sorted(reservations, key=lambda x: (x['arrival'], x['site'], x['guest'])):
        rows.append('<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td></tr>'.format(escape(str(item['site']), quote=True), escape(str(item['guest']), quote=True), escape(str(item['arrival']), quote=True), item['nights'], item['guests']))
        total += item['nights'] * item['guests']
    return '<div class="report"><h1>{}</h1><table><thead><tr><th>Site</th><th>Guest</th><th>Arrival</th><th>Nights</th><th>Guests</th></tr></thead><tbody>{}</tbody></table><p class="total">Total guest-nights: {}</p></div>'.format(escape(title, quote=True), ''.join(rows), total)

