def get_top_recognizers(api_url: str, token: str, month: str, min_points: int=0) -> list[dict]:
    if not isinstance(month, str) or not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', month):
        raise ValueError('invalid month')
    if not isinstance(min_points, int) or isinstance(min_points, bool) or min_points < 0:
        raise ValueError('invalid minimum')
    totals = {}
    page = 1
    while True:
        result = requests.get(api_url.rstrip('/') + '/v1/recognitions', params={'month': month, 'page': page}, headers={'Authorization': 'Bearer ' + token})
        if result.status_code != 200:
            raise RuntimeError('request failed')
        try:
            data = result.json()
            items = data['items']
            next_page = data['next_page']
            if not isinstance(items, list) or (next_page is not None and (not isinstance(next_page, int))):
                raise ValueError('invalid response')
            for item in items:
                if not isinstance(item, dict):
                    raise ValueError('invalid item')
                employee_id = item['employee_id']
                name = item['name']
                points = item['points']
                if not isinstance(employee_id, str) or not isinstance(name, str) or (not isinstance(points, int)) or isinstance(points, bool) or (points < 0):
                    raise ValueError('invalid item')
                if employee_id not in totals:
                    totals[employee_id] = [name, points]
                else:
                    totals[employee_id][1] += points
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid response')
        if next_page is None:
            break
        page = next_page
    result = [{'employee_id': employee_id, 'name': value[0], 'points': value[1]} for employee_id, value in totals.items() if value[1] >= min_points]
    result.sort(key=lambda item: (-item['points'], item['name'].casefold(), item['employee_id']))
    return result[:3]

