def extract_allocations(xml_text: str) -> list[tuple[str, float]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'portfolio':
        raise ValueError('root must be portfolio')
    result = []
    for item in root.findall('holding'):
        symbol = item.get('symbol', '').strip()
        if not symbol:
            raise ValueError('symbol is required')
        try:
            weight = float(item.get('weight', ''))
        except ValueError as exc:
            raise ValueError('invalid weight') from exc
        if not 0.0 <= weight <= 1.0:
