import hashlib
import hmac
import json

def sign_document(payload: str, secret: bytes) -> str:
    if not isinstance(secret, bytes) or not isinstance(payload, str) or '\n' in payload or ('\r' in payload):
        raise ValueError('invalid input')
    digest = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return 'sig:' + digest + '\n\n' + payload

def resolve_flags(document: str, secret: bytes, attributes: dict) -> dict:
    if not isinstance(document, str) or not isinstance(secret, bytes) or (not isinstance(attributes, dict)):
        raise ValueError('invalid input')
    parts = document.split('\n', 2)
    if len(parts) != 3 or parts[1] != '' or (not parts[0].startswith('sig:')):
        raise ValueError('invalid document')
    supplied = parts[0][4:]
    if len(supplied) != 64:
        raise ValueError('invalid signature')
    try:
        bytes.fromhex(supplied)
    except ValueError:
        raise ValueError('invalid signature')
    expected = hmac.new(secret, parts[2].encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        root = json.loads(parts[2])
    except (ValueError, TypeError):
        raise ValueError('invalid json')
    if not isinstance(root, dict) or not isinstance(root.get('flags'), dict):
        raise ValueError('invalid schema')
    result = {}
    for name, definition in root['flags'].items():
        if not isinstance(name, str) or not isinstance(definition, dict) or 'default' not in definition:
            raise ValueError('invalid flag')
        rules = definition.get('rules', [])
        if not isinstance(rules, list):
            raise ValueError('invalid rules')
        selected = definition['default']
        matched = False
        for rule in rules:
            if not isinstance(rule, dict) or not isinstance(rule.get('when'), dict) or 'value' not in rule:
                raise ValueError('invalid rule')
            if all((k in attributes and attributes[k] == v for k, v in rule['when'].items())):
                selected, matched = (rule['value'], True)
                break
        if not matched and 'rollout' in definition:
            rollout = definition['rollout']
            if isinstance(rollout, bool) or not isinstance(rollout, int) or (not 0 <= rollout <= 100):
                raise ValueError('invalid rollout')
            if 'user_id' in attributes:
                raw = name + '|' + str(attributes['user_id'])
                bucket = int.from_bytes(hashlib.sha256(raw.encode()).digest()[:4], 'big') % 100
                if bucket < rollout:
                    selected = definition.get('rollout_value', selected)
        result[name] = selected
    return result

