import csv
import io
from datetime import date
from decimal import Decimal, InvalidOperation
import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_verification_code(length: int=10) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or (not 6 <= length <= 64):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def process_submissions(text: str, valid_codes: dict[str, str]) -> list[tuple[str, float]]:
    if not isinstance(text, str):
        raise ValueError('invalid report')
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except (csv.Error, TypeError):
        raise ValueError('invalid csv')
    rows = [row for row in rows if any((field.strip() for field in row))]
    if not rows or rows[0] != ['volunteer', 'date', 'hours', 'code']:
        raise ValueError('invalid header')
    if len(rows) == 1:
        raise ValueError('no data')
    totals: dict[str, Decimal] = {}
    seen: set[tuple[str, str]] = set()
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        volunteer, datestr, hourstr, code = row
        if not volunteer or volunteer != volunteer.strip() or volunteer not in valid_codes:
            raise ValueError('invalid volunteer')
        if code != valid_codes[volunteer]:
            raise ValueError('invalid code')
        try:
            parsed = date.fromisoformat(datestr)
        except (ValueError, TypeError):
            raise ValueError('invalid date')
        if parsed.isoformat() != datestr or (volunteer, datestr) in seen:
            raise ValueError('duplicate date')
        try:
            hours = Decimal(hourstr)
        except (InvalidOperation, ValueError):
            raise ValueError('invalid hours')
        if not hours.is_finite() or hours <= 0 or hours > 24 or (hours % Decimal('0.25') != 0):
            raise ValueError('invalid hours')
        seen.add((volunteer, datestr))
        totals[volunteer] = totals.get(volunteer, Decimal('0')) + hours
    result = [(name, float(total.quantize(Decimal('0.01')))) for name, total in totals.items()]
    return sorted(result, key=lambda item: (-item[1], item[0]))

