def create_campaign(records: list[dict], segment: str, secret: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(segment, str) or not segment or (not isinstance(secret, str)) or (not secret):
        raise ValueError('arguments')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('pagination')
    _check_records(records)
    selected = [r for r in records if r['segment'] == segment]
    groups = {}
    for r in selected:
        g = groups.setdefault(r['locale'], {'players': 0, 'sent': 0, 'opened': 0, 'revenue': 0.0})
        g['players'] += 1
        g['sent'] += r['sent']
        g['opened'] += r['opened']
        g['revenue'] += r['revenue']
    items = []
    for loc, g in groups.items():
        items.append({'locale': loc, 'players': g['players'], 'sent': g['sent'], 'opened': g['opened'], 'open_rate': round(g['opened'] / g['sent'], 4) if g['sent'] else 0.0, 'revenue': round(g['revenue'], 2)})
    items.sort(key=lambda x: (-x['open_rate'], -x['revenue'], x['locale']))
    total = len(items)
    start = (page - 1) * page_size
    return {'secret_hash': _make_hash(secret), 'total_players': len(selected), 'total_sent': sum((r['sent'] for r in selected)), 'total_opened': sum((r['opened'] for r in selected)), 'total_revenue': round(sum((r['revenue'] for r in selected)), 2), 'locales': items[start:start + page_size], 'page': page, 'page_size': page_size, 'pages': (total + page_size - 1) // page_size}

def _make_hash(value):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', value.encode(), salt, 100000)
    return 'pbkdf2$100000$' + salt.hex() + '$' + digest.hex()

def verify_campaign_secret(stored: str, candidate: str) -> bool:
    if not isinstance(stored, str) or not isinstance(candidate, str):
        return False
    try:
        kind, count, salt_hex, digest_hex = stored.split('$')
        if kind != 'pbkdf2' or int(count) != 100000:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), bytes.fromhex(salt_hex), 100000).hex()
        return hmac.compare_digest(actual, digest_hex)
    except Exception:
        return False

