def reschedule_appointment(appointments: list[dict], appointment_id: str, requester: dict, new_start: str) -> list[dict]:
    selected = next((a for a in appointments if a.get('id') == appointment_id), None)
    if selected is None:
        raise KeyError(appointment_id)
    try:
        start = datetime.strptime(new_start, '%Y-%m-%dT%H:%M:%SZ')
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    duration = selected.get('duration_minutes')
    if duration not in (30, 60) or selected.get('status') != 'scheduled':
        raise ValueError('invalid appointment')
    if selected.get('tenant_id') != requester.get('tenant_id'):
        raise PermissionError('not permitted')
    if selected.get('client_id') != requester.get('id') and 'notary_admin' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    if start.weekday() > 4 or start.hour < 9 or start.hour > 16 or start.minute or start.second:
        raise ValueError('outside working hours')
    end = start + timedelta(minutes=duration)
    if end.hour > 17 or (end.hour == 17 and (end.minute or end.second)):
        raise ValueError('outside working hours')
    for item in appointments:
        if item is selected or item.get('status') == 'cancelled':
            continue
        if item.get('tenant_id') != selected.get('tenant_id') or item.get('notary_id') != selected.get('notary_id'):
            continue
        try:
            other = datetime.strptime(item['start'], '%Y-%m-%dT%H:%M:%SZ')
            other_end = other + timedelta(minutes=item['duration_minutes'])
        except (KeyError, TypeError, ValueError):
            continue
        if start < other_end and other < end:
            raise ValueError('overlap')
    result = deepcopy(appointments)
    for item in result:
        if item.get('id') == appointment_id:
            item['start'] = new_start
    result.sort(key=lambda item: (item['start'], item['id']))
    return result

