class VoterRegistry:

    def __init__(self) -> None:
        self._voters = {}
        self._checkins = set()

    def _valid_date(self, value):
        if not isinstance(value, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value):
            raise ValueError('invalid date')
        try:
            date_type.fromisoformat(value)
        except ValueError:
            raise ValueError('invalid date')
        return value

    def _hash(self, pin, salt=None):
        salt = os.urandom(16) if salt is None else salt
        return (salt, hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000))

    def enroll(self, voter_id: str, name: str, district: str, pin: str) -> None:
        if not isinstance(voter_id, str) or not re.fullmatch('[A-Z]{2}\\d{4}', voter_id):
            raise ValueError('invalid voter id')
        if not isinstance(name, str) or not name.strip() or (not isinstance(district, str)) or (not district.strip()):
            raise ValueError('invalid voter details')
        if not isinstance(pin, str) or not re.fullmatch('\\d{4,12}', pin):
            raise ValueError('invalid pin')
        if voter_id in self._voters:
            raise ValueError('duplicate voter')
        salt, digest = self._hash(pin)
        self._voters[voter_id] = (name.strip(), district.strip(), salt, digest)

    def authenticate(self, voter_id: str, pin: str) -> bool:
        record = self._voters.get(voter_id)
        if record is None or not isinstance(pin, str):
            return False
        actual = self._hash(pin, record[2])[1]
        return hmac.compare_digest(actual, record[3])

    def check_in(self, voter_id: str, pin: str, date: str) -> None:
        day = self._valid_date(date)
        if voter_id not in self._voters:
            raise KeyError(voter_id)
        if not self.authenticate(voter_id, pin):
            raise PermissionError('invalid pin')
        key = (voter_id, day)
        if key in self._checkins:
            raise ValueError('already checked in')
        self._checkins.add(key)

    def report(self, date: str) -> list[dict[str, object]]:
        day = self._valid_date(date)
        groups = {}
        for voter_id, record in self._voters.items():
            district = record[1]
            groups.setdefault(district, [0, 0])[0] += 1
            if (voter_id, day) in self._checkins:
                groups[district][1] += 1
        return [{'district': d, 'total': groups[d][0], 'checked_in': groups[d][1]} for d in sorted(groups)]

