from pathlib import Path

def load_earthquake_alerts(base_dir: str, report_name: str, minimum_magnitude: float) -> list[tuple[str, float, str]]:
    base = Path(base_dir).resolve()
    report = (base / report_name).resolve()
    try:
        report.relative_to(base)
    except ValueError:
        raise ValueError('report is outside base directory')
    records = []
    for line in report.read_text(encoding='utf-8').splitlines():
        if not line.strip():
            continue
        timestamp, magnitude, location = line.split(',', 2)
        value = float(magnitude.strip())
        if value >= minimum_magnitude:
            records.append((timestamp.strip(), value, location.strip()))
    records.sort(key=lambda record: record[1], reverse=True)
    return records

