_STATUSES = ('active', 'maintenance', 'retired')

def prepare_assets(records: list[dict]) -> list[dict]:
    if not isinstance(records, list):
        raise ValueError('records')
    result = []
    seen = set()
    for record in records:
        if not isinstance(record, dict) or set(record) != {'id', 'name', 'owner', 'status', 'updated', 'tags'}:
            raise ValueError('record')
        if any((not isinstance(record[k], str) or not record[k] for k in ('id', 'name', 'owner', 'updated'))):
            raise ValueError('text')
        if record['status'] not in _STATUSES:
            raise ValueError('status')
        try:
            parsed = datetime.strptime(record['updated'], '%Y-%m-%d')
        except (TypeError, ValueError):
            raise ValueError('date')
        if parsed.strftime('%Y-%m-%d') != record['updated']:
            raise ValueError('date')
        if not isinstance(record['tags'], list) or any((not isinstance(x, str) for x in record['tags'])):
            raise ValueError('tags')
        if record['id'] in seen:
            raise ValueError('duplicate')
        seen.add(record['id'])
        risk = {'active': 3, 'maintenance': 2, 'retired': 1}[record['status']]
        risk += 2 if 'critical' in record['tags'] else 0
        risk += 1 if 'internet' in record['tags'] else 0
        copied = dict(record)
        copied['tags'] = list(record['tags'])
        copied['risk'] = risk
        result.append(copied)
    return result

def summarize_assets(records: list[dict]) -> dict:
    assets = prepare_assets(records)
    counts = {s: 0 for s in _STATUSES}
    owners = {}
    for asset in assets:
        counts[asset['status']] += 1
        owners[asset['owner']] = owners.get(asset['owner'], 0) + 1
    by_owner = [{'owner': owner, 'count': count} for owner, count in owners.items()]
    by_owner.sort(key=lambda x: (-x['count'], x['owner']))
    return {'total': len(assets), 'by_status': counts, 'by_owner': by_owner}

def render_asset_report(records: list[dict], status: str | None=None) -> str:
    if status is not None and status not in _STATUSES:
        raise ValueError('status')
    assets = prepare_assets(records)
    if status is not None:
        assets = [a for a in assets if a['status'] == status]
    assets.sort(key=lambda a: (-a['risk'], a['updated'], a['id']))
    rows = []
    for a in assets:
        tags = ', '.join(a['tags']) if a['tags'] else '—'
        values = [a['id'], a['name'], a['owner'], a['status'], a['updated'], str(a['risk']), tags]
        rows.append('<tr>' + ''.join(('<td>' + escape(v) + '</td>' for v in values)) + '</tr>')
    return '<div class="asset-report"><h1>Asset Inventory</h1><p class="count">' + str(len(assets)) + ' assets</p><table><thead><tr><th>ID</th><th>Name</th><th>Owner</th><th>Status</th><th>Updated</th><th>Risk</th><th>Tags</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></div>'

