import secrets

def generate_dispatch_code(zone: str, length: int=8) -> str:
    if not isinstance(zone, str) or not zone or (not zone.isalpha()):
        raise ValueError('invalid zone')
    if not isinstance(length, int) or isinstance(length, bool) or length < 6 or (length > 20):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return zone.upper() + '-' + ''.join((secrets.choice(alphabet) for _ in range(length)))

def summarize_work_orders(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    items = []
    counts = {}
    total_hours = 0.0
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        for key in ('tree_id', 'species', 'priority', 'estimated_hours'):
            if key not in record:
                raise ValueError('missing field')
        if not isinstance(record['tree_id'], str) or not record['tree_id']:
            raise ValueError('invalid tree id')
        if not isinstance(record['species'], str) or not record['species']:
            raise ValueError('invalid species')
        if not isinstance(record['priority'], int) or isinstance(record['priority'], bool) or (not 1 <= record['priority'] <= 5):
            raise ValueError('invalid priority')
        if not isinstance(record['estimated_hours'], (int, float)) or isinstance(record['estimated_hours'], bool) or record['estimated_hours'] < 0:
            raise ValueError('invalid hours')
        item = {key: record[key] for key in ('tree_id', 'species', 'priority', 'estimated_hours')}
        items.append(item)
        counts[item['species']] = counts.get(item['species'], 0) + 1
        total_hours += item['estimated_hours']
    items.sort(key=lambda x: (-x['priority'], x['tree_id']))
    start = (page - 1) * page_size
    return {'total': len(items), 'total_hours': round(total_hours, 2), 'by_species': {k: counts[k] for k in sorted(counts)}, 'items': items[start:start + page_size]}

