            files = sorted((info.filename.replace('\\', '/') for info, _ in paths if info.filename != 'manifest.json'))
            return {'episode_id': episode_id, 'title': title, 'duration': duration, 'chapters': checked, 'files': files}
    except ValueError:
        raise
    except (OSError, zipfile.BadZipFile) as exc:
