def export_standings(entries: list[dict], destination: str, page: int=1, page_size: int=50) -> dict:
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')
    if isinstance(page, bool) or isinstance(page_size, bool):
        raise ValueError('pagination values must be positive')
    if not isinstance(page, int) or not isinstance(page_size, int):
        raise TypeError('pagination values must be integers')
    if page < 1 or page_size < 1:
        raise ValueError('pagination values must be positive')
    totals = {}
    for entry in entries:
        if not isinstance(entry, dict) or set(entry) != {'player', 'result'}:
            raise ValueError('invalid entry')
        player = entry['player']
        result = entry['result']
        if not isinstance(player, str) or not player.strip() or result not in {'win', 'draw', 'loss'}:
            raise ValueError('invalid entry')
        player = player.strip()
        if player not in totals:
            totals[player] = [0, 0]
        totals[player][0] += 1
        if result == 'win':
            totals[player][1] += 1
    standings = []
    for player, (games, wins) in totals.items():
        points = wins * 3 + (games - wins - sum((1 for e in entries if e['player'].strip() == player and e['result'] == 'loss')))
        standings.append((player, games, wins, points))
    standings.sort(key=lambda row: (-row[3], -row[2], row[0]))
    rows = [{'rank': i + 1, 'player': player, 'games': games, 'wins': wins, 'points': points} for i, (player, games, wins, points) in enumerate(standings)]
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.standings-', suffix='.csv', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['rank', 'player', 'games', 'wins', 'points'])
            for row in selected:
                writer.writerow([row['rank'], row['player'], row['games'], row['wins'], row['points']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'total_players': len(rows), 'page': page, 'page_size': page_size, 'rows': selected}

