from lxml import etree
from datetime import datetime

def _time(value):
    try:
        parsed = datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc
    if parsed.strftime('%Y-%m-%dT%H:%M:%SZ') != value:
        raise ValueError('invalid timestamp')
    return parsed

def parse_outage_feed(xml_text: str) -> list[dict]:
    try:
        root = etree.fromstring(xml_text.encode(), etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'outages':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'outage':
            continue
        required = ('id', 'region', 'status', 'updated')
        if any((not node.get(x) for x in required)) or node.get('id') in seen:
            raise ValueError('invalid outage')
        seen.add(node.get('id'))
        if node.get('status') not in ('planned', 'active', 'restored'):
            raise ValueError('invalid status')
        _time(node.get('updated'))
        children = {}
        for child in node:
            if child.tag in ('customers', 'cause', 'note', 'eta'):
                if child.tag in children:
                    raise ValueError('duplicate child')
                children[child.tag] = child
        if 'customers' not in children:
            raise ValueError('missing customers')
        try:
            customers = int((children['customers'].text or '').strip())
        except Exception as exc:
            raise ValueError('invalid customers') from exc
        if customers < 0 or str(customers) != (children['customers'].text or '').strip():
            raise ValueError('invalid customers')
        eta = None
        if 'eta' in children:
            eta = (children['eta'].text or '').strip()
            _time(eta)
        values = {}
        for name in ('cause', 'note'):
            if name in children:
                values[name] = ''.join(children[name].itertext()).strip()
                if not values[name]:
                    raise ValueError('empty text')
            else:
                values[name] = None
        result.append({'id': node.get('id'), 'region': node.get('region'), 'status': node.get('status'), 'updated': node.get('updated'), 'customers': customers, 'eta': eta, 'cause': values['cause'], 'note': values['note']})
    result.sort(key=lambda x: (-_time(x['updated']).timestamp(), x['id']))
    return result

def summarize_outages(xml_documents: list[str], as_of: str) -> dict:
    if not xml_documents:
        raise ValueError('no documents')
    cutoff = _time(as_of)
    chosen = {}
    for document in xml_documents:
        for record in parse_outage_feed(document):
            old = chosen.get(record['id'])
            if old is None or _time(record['updated']) >= _time(old['updated']):
                chosen[record['id']] = record
    selected = [r for r in chosen.values() if r['status'] in ('planned', 'active') and _time(r['updated']) <= cutoff]
    groups = {}
    for record in selected:
        group = groups.setdefault(record['region'], {'region': record['region'], 'outages': 0, 'customers': 0})
        group['outages'] += 1
        group['customers'] += record['customers']
    return {'as_of': as_of, 'active_count': len(selected), 'customers_affected': sum((r['customers'] for r in selected)), 'by_region': [groups[x] for x in sorted(groups)]}

