import os
_ITERATIONS = 100000

def create_vendor_access_record(access_code: str) -> str:
    if not isinstance(access_code, str) or not access_code:
        raise ValueError('access_code must be a non-empty string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_code.encode('utf-8'), salt, _ITERATIONS)
    return salt.hex() + ':' + digest.hex()

def verify_vendor_access_record(access_code: str, record: str) -> bool:
    if not isinstance(access_code, str) or not isinstance(record, str):
        return False
    parts = record.split(':', 1)
    if len(parts) != 2:
        return False
    try:
        salt = bytes.fromhex(parts[0])
        expected = bytes.fromhex(parts[1])
    except ValueError:
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', access_code.encode('utf-8'), salt, _ITERATIONS)
    return hmac.compare_digest(actual, expected)

