import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError('unknown variable')
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _evaluate(node.operand, values)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        result = _evaluate(node.values[0], values)
        for part in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                return result
            result = _evaluate(part, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, part in zip(node.ops, node.comparators):
            if type(op) not in (ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq):
                raise ValueError('unsupported expression')
            right = _evaluate(part, values)
            if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
        if len(node.args) < 2:
            raise ValueError('unsupported expression')
        args = [_evaluate(arg, values) for arg in node.args]
        return min(args) if node.func.id == 'min' else max(args)
    raise ValueError('unsupported expression')

def eligible_vehicle_ids(vehicles: list[dict[str, object]], rule: str) -> list[str]:
    tree = ast.parse(rule, mode='eval').body
    selected = []
    for vehicle in vehicles:
        values = {name: vehicle[name] for name in ('distance', 'battery', 'passengers')}
        if _evaluate(tree, values):
            selected.append(vehicle)
    selected.sort(key=lambda vehicle: vehicle['distance'])
    return [vehicle['id'] for vehicle in selected]

