from typing import Dict, Any

def recommend_size(requester: Dict[str, Any], profile: Dict[str, Any], garment: Dict[str, Any]) -> str:
    if requester['id'] != profile['owner_id'] and 'stylist' not in requester['roles']:
        raise PermissionError('profile access denied')
    measurements = profile['measurements']
    required = ('chest', 'waist', 'hips')
    if any((key not in measurements for key in required)):
        raise ValueError('incomplete measurements')
    if any((measurements[key] < 0 for key in required)):
        raise ValueError('invalid measurements')
    order = garment['size_order']
    if not order:
        raise ValueError('no sizes')
    chart = garment['size_chart']
    for size in order:
        limits = chart[size]
        if all((measurements[key] <= limits[key] for key in required)):
            return size
    return 'unavailable'

