import hashlib
import hmac
import json
import os

def build_sentiment_report(records: list[dict], config: dict[str, str] | None=None) -> dict:
    config = config or {}
    key = config.get('signing_key') or os.environ.get('SENTIMENT_SIGNING_KEY')
    if not key:
        raise ValueError('missing signing key')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dictionary')
        customer_id = record.get('customer_id')
        text = record.get('text')
        score = record.get('score')
        if not isinstance(customer_id, str) or not isinstance(text, str):
            raise TypeError('customer_id and text must be strings')
        if not customer_id.strip() or not text.strip():
            raise ValueError('customer_id and text must be non-empty')
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError('score must be numeric')
        if not 0 <= score <= 1:
            raise ValueError('score must be between 0 and 1')
        group = groups.setdefault(customer_id, {'scores': [], 'positive': 0, 'neutral': 0, 'negative': 0})
        group['scores'].append(score)
        if score >= 0.6:
            group['positive'] += 1
        elif score <= 0.4:
            group['negative'] += 1
        else:
            group['neutral'] += 1
    customers = []
    for customer_id in sorted(groups):
        group = groups[customer_id]
        customers.append({'customer_id': customer_id, 'count': len(group['scores']), 'average_score': round(sum(group['scores']) / len(group['scores']), 2), 'positive': group['positive'], 'neutral': group['neutral'], 'negative': group['negative']})
    total = len(records)
    average = round(sum((sum(group['scores']) for group in groups.values())) / total, 2) if total else 0.0
    payload = {'total': total, 'average_score': average, 'customers': customers}
    data = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), data, hashlib.sha256).hexdigest()
    return {**payload, 'signature': signature}

