import subprocess

def reservation_summary(path: str, day: str, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        datetime.strptime(day, '%Y-%m-%d')
    except ValueError:
        raise ValueError('invalid day')
    with open(path, encoding='utf-8') as handle:
        header = handle.readline().rstrip('\n\r')
        if header != 'date\tequipment\thours':
            raise ValueError('invalid header')
        body = handle.read()
    result = subprocess.run(['sort', '-t', '\t', '-k1,1'], input=body, capture_output=True, text=True, check=True)
    totals = {}
    for line in result.stdout.splitlines():
        fields = line.split('\t')
        if len(fields) != 3:
            raise ValueError('invalid row')
        record_day, equipment, raw_hours = fields
        if not equipment:
            raise ValueError('invalid equipment')
        try:
            parsed = datetime.strptime(record_day, '%Y-%m-%d')
            hours = Decimal(raw_hours)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid row')
        if parsed.strftime('%Y-%m-%d') != record_day or hours < 0:
            raise ValueError('invalid row')
        if record_day == day:
            count, total = totals.get(equipment, (0, Decimal('0')))
            totals[equipment] = (count + 1, total + hours)
    rows = [{'equipment': name, 'reservations': count, 'hours': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for name, (count, total) in totals.items()]
    rows.sort(key=lambda row: (-row['hours'], row['equipment']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

