import re
import secrets

def generate_gift_card_code(prefix: str, length: int=12) -> str:
    if not isinstance(prefix, str) or re.fullmatch('[A-Z]{2,5}', prefix) is None:
        raise ValueError('invalid prefix')
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 32):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return prefix + '-' + ''.join((secrets.choice(alphabet) for _ in range(length)))

def summarize_balances(records: list[dict], page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    balances = {}
    total = 0
    for record in records:
        if not isinstance(record, dict) or (set(record) != {'card_id', 'delta_cents', 'status'} and (not {'card_id', 'delta_cents', 'status'}.issubset(record))):
            raise ValueError('invalid record')
        card_id = record.get('card_id')
        delta = record.get('delta_cents')
        status = record.get('status')
        if not isinstance(card_id, str) or not card_id or isinstance(delta, bool) or (not isinstance(delta, int)) or (status not in {'posted', 'pending', 'void'}):
            raise ValueError('invalid record')
        if status == 'posted':
            balances[card_id] = balances.get(card_id, 0) + delta
            total += delta
    ordered = sorted(balances.items(), key=lambda item: (-item[1], item[0]))
    pages = (len(ordered) + page_size - 1) // page_size
    start = (page - 1) * page_size
    cards = [{'card_id': card_id, 'balance_cents': balance} for card_id, balance in ordered[start:start + page_size]]
    return {'total_cents': total, 'cards': cards, 'page': page, 'page_size': page_size, 'pages': pages}

