import json
import math

def encode_snapshot(snapshot: dict) -> bytes:
    try:
        return json.dumps(snapshot, separators=(',', ':'), sort_keys=True).encode('utf-8')
    except Exception as exc:
        raise ValueError('invalid snapshot') from exc

def summarize_snapshot(blob: bytes, min_pressure: float, page: int, page_size: int) -> dict:
    if isinstance(min_pressure, bool) or not isinstance(min_pressure, (int, float)) or (not math.isfinite(min_pressure)):
        raise ValueError('invalid pressure')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        data = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or set(data) != {'readings'} or (not isinstance(data['readings'], list)):
        raise ValueError('invalid snapshot')
    groups = {}
    for reading in data['readings']:
        if not isinstance(reading, dict) or set(reading) != {'station', 'timestamp', 'pressure', 'flow'}:
            raise ValueError('invalid reading')
        station = reading['station']
        pressure = reading['pressure']
        flow = reading['flow']
        if not isinstance(station, str) or not station or (not isinstance(reading['timestamp'], str)):
            raise ValueError('invalid reading')
        if isinstance(pressure, bool) or not isinstance(pressure, (int, float)) or (not math.isfinite(pressure)):
            raise ValueError('invalid reading')
        if isinstance(flow, bool) or not isinstance(flow, (int, float)) or (not math.isfinite(flow)):
            raise ValueError('invalid reading')
        if pressure >= min_pressure:
            groups.setdefault(station, [0, 0.0, 0.0])
            groups[station][0] += 1
            groups[station][1] += pressure
            groups[station][2] += flow
    items = [{'station': s, 'count': v[0], 'avg_pressure': float(round(v[1] / v[0], 2)), 'total_flow': float(round(v[2], 2))} for s, v in sorted(groups.items())]
    start = (page - 1) * page_size
    return {'total': len(items), 'page': page, 'page_size': page_size, 'items': items[start:start + page_size]}

