def count_blood_type_units(record_file: str, blood_type: str) -> int:
    valid_types = {'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'}
    if blood_type not in valid_types:
        raise ValueError('invalid blood type')
    pattern = ',' + blood_type + ','
    result = subprocess.run(f'grep -F -c -- {pattern} {record_file}', shell=True, capture_output=True, text=True, check=False)
    if result.returncode not in (0, 1):
        raise FileNotFoundError(record_file)
    return int(result.stdout.strip())

