import csv
import os
import tempfile

def export_voter_report(records: list[dict], destination: str) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    seen = set()
    included = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be a dictionary')
        if set(record) != {'voter_id', 'district', 'age', 'status'}:
            raise ValueError('invalid record fields')
        voter_id = record['voter_id']
        district = record['district']
        age = record['age']
        status = record['status']
        if not isinstance(voter_id, str) or not voter_id:
            raise ValueError('invalid voter_id')
        if voter_id in seen:
            raise ValueError('duplicate voter_id')
        seen.add(voter_id)
        if not isinstance(district, str) or not district:
            raise ValueError('invalid district')
        if isinstance(age, bool) or not isinstance(age, int) or (not 0 <= age <= 120):
            raise ValueError('invalid age')
        if status not in ('active', 'inactive'):
            raise ValueError('invalid status')
        if status == 'active' and age >= 18:
            included.append((voter_id, district, age))
    included.sort(key=lambda row: (row[1], row[0]))
    counts = {}
    for _, district, _ in included:
        counts[district] = counts.get(district, 0) + 1
    counts = {district: counts[district] for district in sorted(counts)}
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.voter-report-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['voter_id', 'district', 'age'])
            writer.writerows(included)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'total': len(included), 'by_district': counts}

