import csv
import math
import os
import tempfile

def export_audience_csv(rows: list[tuple[str, str, float]], destination: str) -> int:
    checked = []
    for row in rows:
        if len(row) != 3:
            raise ValueError('each row must have three values')
        segment_id, user_id, score = row
        if not isinstance(segment_id, str) or not isinstance(user_id, str):
            raise ValueError('identifiers must be strings')
        if not isinstance(score, (int, float)) or not math.isfinite(score):
            raise ValueError('score must be finite')
        checked.append((segment_id, user_id, score))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.audience-', suffix='.tmp')
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('segment_id', 'user_id', 'score'))
            for segment_id, user_id, score in checked:
                writer.writerow((segment_id, user_id, f'{score:.2f}'))
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return len(checked)

