from solution import record_consent, summarize_consent, export_consent_timeline
import json
import pytest


def requester():
    return {'id': 'u1', 'tenant': 'acme', 'roles': ['member']}


def event(eid, subject, purpose, decision, timestamp, source='web'):
    return {'event_id': eid, 'subject_id': subject, 'tenant': 'acme', 'purpose': purpose, 'decision': decision, 'timestamp': timestamp, 'source': source}


def test_record_normalizes_missing_source_and_copies_input():
    ledger = []
    original = {'event_id': 'e1', 'subject_id': 'u1', 'tenant': 'acme', 'purpose': 'email', 'decision': 'grant', 'timestamp': '2024-01-01T00:00:00Z'}
    result = record_consent(requester(), original, ledger)
    assert result == {**original, 'source': 'unknown'}
    assert ledger == [result]
    assert result is not original
    original['purpose'] = 'changed'
    assert ledger[0]['purpose'] == 'email'


def test_record_rejects_bad_events_and_duplicate_ids():
    ledger = [event('e1', 'u1', 'email', 'grant', '2024-01-01T00:00:00Z')]
    with pytest.raises(ValueError): record_consent(requester(), event('e1', 'u1', 'sms', 'deny', '2024-01-02T00:00:00Z'), ledger)
    with pytest.raises(ValueError): record_consent(requester(), event('e2', 'u1', 'email', 'maybe', '2024-01-02T00:00:00Z'), ledger)
    with pytest.raises(ValueError): record_consent(requester(), event('e3', 'u1', 'email', 'grant', 'not-a-date'), ledger)
    assert len(ledger) == 1


def test_summary_uses_timestamp_then_event_id_and_counts_all_events():
    ledger = [event('b','u1','email','grant','2024-01-02T00:00:00Z'), event('a','u1','email','deny','2024-01-02T00:00:00Z','app'), event('c','u1','sms','grant','2024-01-01T12:00:00Z'), event('x','u2','email','deny','2024-01-03T00:00:00Z')]
    assert summarize_consent(requester(), 'u1', ledger) == {'subject_id':'u1','tenant':'acme','purposes':{'email':{'decision':'grant','timestamp':'2024-01-02T00:00:00Z','event_id':'b','source':'web'},'sms':{'decision':'grant','timestamp':'2024-01-01T12:00:00Z','event_id':'c','source':'web'}},'grant_count':2,'deny_count':1}


def test_summary_empty_subject():
    assert summarize_consent(requester(), 'u9', []) == {'subject_id':'u9','tenant':'acme','purposes':{},'grant_count':0,'deny_count':0}


def test_export_sorting_and_json_format():
    ledger = [event('z','u1','email','deny','2024-01-02T00:00:00Z','mobile'), event('a','u1','email','grant','2024-01-01T00:00:00Z'), event('b','u1','sms','grant','2024-01-01T00:00:00Z')]
    text = export_consent_timeline(requester(), 'u1', ledger)
    assert text.endswith('\n')
    assert text == '[{"event_id":"a","subject_id":"u1","tenant":"acme","purpose":"email","decision":"grant","timestamp":"2024-01-01T00:00:00Z","source":"web"},{"event_id":"b","subject_id":"u1","tenant":"acme","purpose":"sms","decision":"grant","timestamp":"2024-01-01T00:00:00Z","source":"web"},{"event_id":"z","subject_id":"u1","tenant":"acme","purpose":"email","decision":"deny","timestamp":"2024-01-02T00:00:00Z","source":"mobile"}]\n'


def test_export_empty_and_invalid_subject():
    assert export_consent_timeline(requester(), 'u1', []) == '[]\n'
    with pytest.raises(ValueError): summarize_consent(requester(), '', [])
    with pytest.raises(ValueError): export_consent_timeline(requester(), '', [])


def test_unicode_is_preserved_in_export():
    text = export_consent_timeline(requester(), 'u1', [event('é','u1','newsletter','grant','2024-01-01T00:00:00Z','客户')])
    assert '客户' in text
    assert json.loads(text)[0]['source'] == '客户'

