import json
from datetime import datetime

def _time(v):
    if not isinstance(v, str) or not v.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(v[:-1] + '+00:00')
    except ValueError as e:
        raise ValueError('invalid timestamp') from e

def _format(x):
    keys = {'event_id', 'subject_id', 'tenant', 'purpose', 'decision', 'timestamp', 'source'}
    if set(x) != keys or any((not isinstance(x[k], str) or not x[k] for k in keys)) or x['decision'] not in {'grant', 'deny'}:
        raise ValueError('invalid ledger')
    _time(x['timestamp'])

def _validate(r, e, l):
    req = {'event_id', 'subject_id', 'tenant', 'purpose', 'decision', 'timestamp'}
    if not isinstance(e, dict) or not req.issubset(e) or set(e) - req - {'source'}:
        raise ValueError('invalid event')
    if any((not isinstance(e[k], str) or not e[k] for k in req - {'decision'})) or e['decision'] not in {'grant', 'deny'}:
        raise ValueError('invalid event')
    _time(e['timestamp'])
    s = e.get('source', 'unknown')
    if not isinstance(s, str) or not s or e['tenant'] != r.get('tenant') or any((isinstance(x, dict) and x.get('event_id') == e['event_id'] for x in l)):
        raise ValueError('invalid event')
    return dict(e, source=s)

def record_consent(requester: dict, event: dict, ledger: list[dict]) -> dict:
    x = _validate(requester, event, ledger)
    ledger.append(x)
    return dict(x)

def _matching(r, s, l):
    if not isinstance(s, str) or not s:
        raise ValueError('invalid subject')
    for x in l:
        if not isinstance(x, dict):
            raise ValueError('invalid ledger')
        _format(x)
    return [x for x in l if x['subject_id'] == s and x['tenant'] == r.get('tenant')]

def summarize_consent(requester: dict, subject_id: str, ledger: list[dict]) -> dict:
    a = _matching(requester, subject_id, ledger)
    q = {}
    for x in a:
        if x['purpose'] not in q or (_time(x['timestamp']), x['event_id']) > (_time(q[x['purpose']]['timestamp']), q[x['purpose']]['event_id']):
            q[x['purpose']] = x
    return {'subject_id': subject_id, 'tenant': requester.get('tenant'), 'purposes': {k: {z: q[k][z] for z in ('decision', 'timestamp', 'event_id', 'source')} for k in sorted(q)}, 'grant_count': sum((x['decision'] == 'grant' for x in a)), 'deny_count': sum((x['decision'] == 'deny' for x in a))}

def export_consent_timeline(requester: dict, subject_id: str, ledger: list[dict]) -> str:
    a = sorted(_matching(requester, subject_id, ledger), key=lambda x: (_time(x['timestamp']), x['event_id']))
    f = ('event_id', 'subject_id', 'tenant', 'purpose', 'decision', 'timestamp', 'source')
    return json.dumps([{k: x[k] for k in f} for x in a], ensure_ascii=False, separators=(',', ':')) + '\n'

