import html
import math
from numbers import Real

def render_harvest_report(records: list[dict[str, object]], page: int=1, per_page: int=10) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('invalid page size')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            stand = record['stand']
            species = record['species']
            acres = record['acres']
            volume = record['volume']
            status = record['status']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not isinstance(stand, str) or not stand or (not isinstance(species, str)) or (not species):
            raise ValueError('invalid text')
        if status not in ('planned', 'complete'):
            raise ValueError('invalid status')
        if isinstance(acres, bool) or not isinstance(acres, Real) or (not math.isfinite(acres)) or (acres < 0):
            raise ValueError('invalid acres')
        if isinstance(volume, bool) or not isinstance(volume, Real) or (not math.isfinite(volume)) or (volume < 0):
            raise ValueError('invalid volume')
        if status == 'planned':
            key = (stand, species)
            old_acres, old_volume = grouped.get(key, (0, 0))
            grouped[key] = (old_acres + acres, old_volume + volume)
    rows = [(stand, species, values[0], values[1]) for (stand, species), values in grouped.items()]
    rows.sort(key=lambda row: (-row[3], row[0], row[1]))
    total_pages = max(1, (len(rows) + per_page - 1) // per_page)
    if page > total_pages:
        raise ValueError('page out of range')
    start = (page - 1) * per_page
    visible = rows[start:start + per_page]
    stands = len({row[0] for row in rows})
    total_acres = sum((row[2] for row in rows))
