    if not m:
        raise ValueError()
    h1, m1, h2, m2 = map(int, m.groups())
    if h1 > 23 or h2 > 23 or m1 > 59 or (m2 > 59):
        raise ValueError()
    a, b = (h1 * 60 + m1, h2 * 60 + m2)
    if a >= b:
