    except (KeyError, TypeError, ValueError):
        raise ValueError()

def publish_schedule(requester: dict, households: list[dict], slots: list[dict]) -> list[dict]:
    if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not isinstance(requester.get('tenant'), str)) or (not isinstance(requester.get('roles'), list)):
        raise ValueError()
    if not {'coordinator', 'scheduler', 'admin'} & set(requester['roles']):
        raise PermissionError()
