                raise ValueError()
            date.fromisoformat(s['date'])
            start, _ = parse_time_window(s['window'])
            seen_s.add(s['id'])
            ss.append((s, start))
    except (KeyError, TypeError, ValueError):
        raise ValueError()
    ss.sort(key=lambda x: (x[0]['date'], x[1], x[0]['id']))
    remaining = {s['id']: s['capacity'] for s, _ in ss}
    out = []
    for h in rank_households(hs):
