    if response.status_code != 200:
        raise RuntimeError(f'telemetry request failed: {response.status_code}')
    groups = {}
    for event in response.json()['events']:
        timestamp = event['timestamp']
        parsed = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        if start <= parsed.date() <= end and event['severity'] >= min_severity:
            name = event['equipment']
            group = groups.setdefault(name, {'equipment': name, 'count': 0, 'max_severity': event['severity'], 'first_timestamp': timestamp, '_first': parsed})
            group['count'] += 1
            group['max_severity'] = max(group['max_severity'], event['severity'])
            if parsed < group['_first']:
                group['_first'] = parsed
                group['first_timestamp'] = timestamp
    result = list(groups.values())
    result.sort(key=lambda item: (-item['count'], item['equipment']))
    for item in result:
        del item['_first']
    return result

