import base64
import hashlib
import hmac
import math
import os

def hash_bid_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return 'pbkdf2$100000$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_bid_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        raise TypeError('arguments must be strings')
    try:
        scheme, count, salt_text, digest_text = stored.split('$')
        if scheme != 'pbkdf2' or int(count) != 100000:
            return False
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def rank_bids(bids: list[dict], category: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    if category == '':
        raise ValueError('invalid category')
    required = {'bid_id', 'vendor', 'category', 'amount', 'secret_hash'}
    selected = []
    for bid in bids:
        if not isinstance(bid, dict) or not required.issubset(bid):
            raise ValueError('invalid bid')
        if any((not isinstance(bid[k], str) or not bid[k] for k in ('bid_id', 'vendor', 'category', 'secret_hash'))):
            raise ValueError('invalid bid')
        if isinstance(bid['amount'], bool) or not isinstance(bid['amount'], (int, float)) or (not math.isfinite(bid['amount'])):
            raise ValueError('invalid amount')
        if category is None or bid['category'] == category:
            selected.append(bid)
    selected.sort(key=lambda b: (b['amount'], b['vendor'], b['bid_id']))
    start = (page - 1) * page_size
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'bids': [dict(x) for x in selected[start:start + page_size]], 'amount_total': round(sum((x['amount'] for x in selected)), 2)}

