def parse_leak_report(xml_text: str) -> list[tuple[str, float]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'report':
        raise ValueError('invalid root element')
    leaks = []
    for element in root:
        if element.tag != 'leak':
            continue
        sensor = element.get('sensor')
        value = element.get('liters')
        if sensor is None or value is None:
            raise ValueError('missing leak attribute')
        try:
            liters = float(value)
        except ValueError as exc:
            raise ValueError('invalid liters value') from exc
        if liters < 0:
            raise ValueError('invalid liters value')
        leaks.append((sensor, liters))
    return sorted(leaks, key=lambda item: (-item[1], item[0]))

