import xml.sax.handler

class _LeakHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.root = None
        self.leaks = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name != 'leak':
            return
        sensor = attrs.get('sensor')
        value = attrs.get('liters')
        if sensor is None or value is None:
            raise ValueError('missing leak attribute')
        try:
            liters = float(value)
        except ValueError as exc:
            raise ValueError('invalid liters value') from exc
        if liters < 0:
            raise ValueError('invalid liters value')
        self.leaks.append((sensor, liters))

def parse_leak_report(xml_text: str) -> list[tuple[str, float]]:
    handler = _LeakHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except (xml.sax.SAXException, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'report':
        raise ValueError('invalid root element')
    return sorted(handler.leaks, key=lambda item: (-item[1], item[0]))

