def get_collar_activity(requester: dict, collars: list[dict], start: str, end: str, page: int, page_size: int) -> list[dict]:
    if not isinstance(requester, dict) or not isinstance(collars, list):
        raise TypeError()
    if not isinstance(page, int) or not isinstance(page_size, int) or page <= 0 or (page_size < 1) or (page_size > 100):
