        try:
            return datetime.fromisoformat(value.replace('Z', '+00:00')).astimezone(timezone.utc)
        except Exception as exc:
            raise ValueError() from exc
    begin = parse(start)
    finish = parse(end)
    if finish <= begin:
        raise ValueError()
    allowed_role = 'wildlife_manager' in requester.get('roles', [])
    result = []
    for collar in collars:
        if collar.get('tenant_id') != requester.get('tenant_id') or (collar.get('owner_id') != requester.get('id') and (not allowed_role)):
