import base64
import datetime
import hashlib
import hmac
import json

def _validate(value):
    if not isinstance(value, dict):
        raise ValueError('ticket must be an object')
    required = ['ticket_id', 'exhibit', 'issued_at', 'quantity', 'price_cents']
    if any((key not in value for key in required)):
        raise ValueError('missing field')
    if not isinstance(value['ticket_id'], str) or not value['ticket_id']:
        raise ValueError('invalid ticket id')
    if not isinstance(value['exhibit'], str) or not value['exhibit']:
        raise ValueError('invalid exhibit')
    if not isinstance(value['issued_at'], str):
        raise ValueError('invalid timestamp')
    try:
        datetime.datetime.fromisoformat(value['issued_at'].replace('Z', '+00:00'))
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if isinstance(value['quantity'], bool) or not isinstance(value['quantity'], int) or value['quantity'] <= 0:
        raise ValueError('invalid quantity')
    if isinstance(value['price_cents'], bool) or not isinstance(value['price_cents'], int) or value['price_cents'] < 0:
        raise ValueError('invalid price')

def sign_ticket(ticket: dict, secret: bytes) -> str:
    _validate(ticket)
    raw = json.dumps(ticket, sort_keys=True, separators=(',', ':')).encode()
    payload = base64.urlsafe_b64encode(raw).decode().rstrip('=')
    signature = hmac.new(secret, raw, hashlib.sha256).hexdigest()
    return payload + '.' + signature

def verify_ticket(message: str, secret: bytes) -> dict:
    if not isinstance(message, str) or message.count('.') != 1:
        raise ValueError('invalid message')
    payload, signature = message.split('.')
    try:
        raw = base64.urlsafe_b64decode(payload + '=' * (-len(payload) % 4))
        expected = hmac.new(secret, raw, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            raise ValueError('invalid signature')
        value = json.loads(raw.decode('utf-8'))
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError, base64.binascii.Error):
        raise ValueError('invalid message')
    _validate(value)
    return value

def summarize_tickets(messages: list[str], secret: bytes) -> dict:
    dates = {}
    exhibits = {}
    seen = set()
    total_quantity = 0
    total_revenue = 0
    for message in messages:
        value = verify_ticket(message, secret)
        if value['ticket_id'] in seen:
            raise ValueError('duplicate ticket')
        seen.add(value['ticket_id'])
        quantity = value['quantity']
