import json
import os
import zipfile

def process_testimony_archive(base_dir: str, archive_path: str, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    os.makedirs(base_dir, exist_ok=True)
    base = os.path.realpath(base_dir)
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            target = os.path.realpath(os.path.join(base, member.filename))
            if os.path.commonpath((base, target)) != base:
                raise ValueError('invalid archive member')
            if member.is_dir():
                os.makedirs(target, exist_ok=True)
            else:
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with archive.open(member) as source, open(target, 'wb') as destination:
                    destination.write(source.read())
    groups = {}
    for root, _, names in os.walk(base):
        for name in names:
            if not name.endswith('.json'):
                continue
            with open(os.path.join(root, name), encoding='utf-8') as handle:
                item = json.load(handle)
            if not isinstance(item, dict):
                raise ValueError('invalid submission')
            if not isinstance(item.get('committee'), str) or not item['committee']:
                raise ValueError('invalid committee')
            if item.get('position') not in {'support', 'oppose', 'neutral'}:
                raise ValueError('invalid position')
            if not isinstance(item.get('text'), str):
                raise ValueError('invalid text')
            committee = item['committee']
            group = groups.setdefault(committee, {'support': 0, 'oppose': 0, 'neutral': 0, 'words': []})
            group[item['position']] += 1
            group['words'].append(len(item['text'].split()))
    result = []
    for committee, group in groups.items():
        total = sum((group[key] for key in ('support', 'oppose', 'neutral')))
        result.append({'committee': committee, 'support': group['support'], 'oppose': group['oppose'], 'neutral': group['neutral'], 'total': total, 'average_words': round(sum(group['words']) / total, 2)})
    result.sort(key=lambda item: (-item['total'], item['committee']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

