import subprocess

def parse_campaign_log(text: str) -> list[dict]:
    records = []
    for line_number, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line:
            continue
        fields = line.split('|')
        if len(fields) != 5:
            raise ValueError(f'invalid line {line_number}')
        session, round_text, character, damage_text, healing_text = fields
        session = session.strip()
        character = character.strip()
        if not session or not character:
            raise ValueError(f'invalid line {line_number}')
        try:
            round_number = int(round_text.strip(), 10)
            damage = int(damage_text.strip(), 10)
            healing = int(healing_text.strip(), 10)
        except ValueError as exc:
            raise ValueError(f'invalid line {line_number}') from exc
        if round_number < 1 or damage < 0 or healing < 0:
            raise ValueError(f'invalid line {line_number}')
        records.append({'session': session, 'round': round_number, 'character': character, 'damage': damage, 'healing': healing})
    return records

def summarize_campaign(path: str, top_n: int) -> list[dict]:
    if not isinstance(top_n, int) or isinstance(top_n, bool) or top_n < 0:
        raise ValueError('top_n must be non-negative')
    completed = subprocess.run(['cat', path], capture_output=True, text=True, check=True)
    records = parse_campaign_log(completed.stdout)
    totals = {}
    for record in records:
        name = record['character']
        if name not in totals:
            totals[name] = {'character': name, 'damage': 0, 'healing': 0, 'rounds': 0}
        item = totals[name]
        item['damage'] += record['damage']
        item['healing'] += record['healing']
        item['rounds'] += 1
    ordered = sorted(totals.values(), key=lambda item: (-item['damage'], -item['healing'], item['character']))
    return ordered[:top_n]

