import os
from decimal import Decimal, ROUND_HALF_UP

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin:
        raise ValueError('pin must be a non-empty string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return 'v1$' + base64.b64encode(salt).decode() + '$' + value.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(stored, str)):
        return False
    try:
        version, salt_text, expected = stored.split('$', 2)
        if version != 'v1':
            return False
        salt = base64.b64decode(salt_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

