import base64
import datetime
import hashlib
import hmac
import os
import re

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str) or not secret:
        raise ValueError('empty secret')
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, rounds)
    return f'pbkdf2${rounds}${base64.urlsafe_b64encode(salt).decode()}${digest.hex()}'

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not secret or (not isinstance(stored, str)):
        return False
    try:
        kind, rounds, salt, expected = stored.split('$')
        if kind != 'pbkdf2':
            return False
        rounds = int(rounds)
        salt = base64.urlsafe_b64decode(salt.encode())
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, rounds).hex()
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError, UnicodeError):
        return False

def _date(value):
    try:
        parsed = datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def _cents(value):
    if not isinstance(value, str) or not re.fullmatch('(?:0|[1-9]\\d*)(?:\\.\\d{1,2})?', value):
        raise ValueError('invalid amount')
    whole, _, fraction = value.partition('.')
    return int(whole) * 100 + int((fraction + '00')[:2])

def parse_payments(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise ValueError('invalid payments')
