    for line in text.splitlines():
        if not line.strip():
            continue
        parts = line.split(' ')
        if len(parts) != 2 or not parts[0] or (not parts[1]):
            raise ValueError('invalid payment line')
        day = _date(parts[0])
        amount = _cents(parts[1])
        totals[day.isoformat()] = totals.get(day.isoformat(), 0) + amount
    return sorted(totals.items())

def register_lease(tenant_id: str, password: str, start: str, end: str, monthly_rent: str, payments: str) -> dict:
    if not isinstance(tenant_id, str) or not tenant_id:
        raise ValueError('invalid tenant')
    first, last = (_date(start), _date(end))
    if first.day != 1 or last.day != 1 or first > last:
        raise ValueError('invalid lease range')
    rent = _cents(monthly_rent)
    if rent <= 0:
        raise ValueError('invalid rent')
    return {'tenant_id': tenant_id, 'password': hash_secret(password), 'start': start, 'end': end, 'rent_cents': rent, 'payments': parse_payments(payments)}

