    except (KeyError, TypeError):
        raise ValueError('invalid lease')
    today, first, last = (_date(as_of), _date(start), _date(end))
    if first.day != 1 or last.day != 1 or first > last or (not isinstance(rent, int)) or (rent <= 0):
        raise ValueError('invalid lease')
    charges = []
    cursor = first
    while cursor <= last:
        if cursor <= today:
            charges.append(cursor.isoformat())
        month = cursor.month % 12 + 1
        year = cursor.year + (cursor.month == 12)
        cursor = datetime.date(year, month, 1)
    paid = sum((amount for date, amount in payments if _date(date) <= today and first <= _date(date) <= last))
    due = len(charges) * rent
    balance = due - paid
    running = 0
    outstanding = []
    for date in charges:
        running += rent
        if sum((amount for d, amount in payments if d <= date and first.isoformat() <= d <= last.isoformat())) < running:
            outstanding.append(date)
    status = 'paid' if balance <= 0 else 'current' if not charges or today <= _date(charges[-1]) else 'overdue'
    return {'tenant_id': tenant, 'due_count': len(charges), 'due_cents': due, 'paid_cents': paid, 'balance_cents': balance, 'status': status, 'outstanding_dates': outstanding}

