import sqlite3

def coverage_report(conn: sqlite3.Connection, run_id: int, module_prefix: str='', file_search: str='', sort_by: str='module') -> list[dict]:
    if sort_by not in {'module', 'percent', 'covered', 'files'}:
        raise ValueError('unknown sort')
    if conn.execute('select 1 from runs where id = ?', (run_id,)).fetchone() is None:
        raise ValueError('unknown run')
    rows = conn.execute('select module, covered, total from coverage where run_id = ? and module like ? and instr(file, ?) > 0', (run_id, module_prefix + '%', file_search)).fetchall()
    grouped = {}
    for module, covered, total in rows:
        item = grouped.setdefault(module, [0, 0, 0])
        item[0] += covered
        item[1] += total
        item[2] += 1
    result = []
    for module, (covered, total, files) in grouped.items():
        percent = round(covered * 100 / total, 2) if total else 0.0
        result.append({'module': module, 'covered': covered, 'total': total, 'percent': percent, 'files': files})
    if sort_by == 'module':
        result.sort(key=lambda x: x['module'])
    else:
        result.sort(key=lambda x: (-x[sort_by], x['module']))
    return result

def rename_run(conn: sqlite3.Connection, run_id: int, label: str) -> int:
    if not isinstance(label, str) or not label.strip():
        raise ValueError('blank label')
    cursor = conn.execute('update runs set label = ? where id = ?', (label, run_id))
    conn.commit()
    return cursor.rowcount

