def build_royalty_report(requester: dict, franchise_id: str, sales: list[dict]) -> str:
    if requester.get('franchise_id') != franchise_id and 'finance_admin' not in requester.get('roles', []):
        raise PermissionError('report access denied')
    rows = []
    for sale in sales:
        if sale['franchise_id'] != franchise_id:
            continue
        rate = sale['royalty_rate']
        if rate < 0 or rate > 1:
            raise ValueError('royalty rate must be between 0 and 1')
        rows.append((sale['month'], sale['gross_sales'] * rate))
    rows.sort(key=lambda row: row[0])
    output = ['month,royalty']
    output.extend((f'{month},{royalty:.2f}' for month, royalty in rows))
    return '\n'.join(output)

