    bad_inputs = ['<wrong />', '<cemetery><plot id="A" section="A" /></cemetery>', '<cemetery><plot id="A" section="A" area="0" /></cemetery>', '<cemetery><plot id="A" section="A" area="2"><reservation occupant="X" date="2025-99-01" status="confirmed"/></plot></cemetery>', '<cemetery><plot id="A" section="A" area="2"><reservation occupant="X" date="2025-01-01" status="done"/></plot></cemetery>', '<cemetery>']
    for xml in bad_inputs:
        with pytest.raises(ValueError):
