    records = [{'plot_id': 'X', 'section': 'Z', 'area': 1.0, 'occupant': 'a', 'date': '2025-01-01', 'status': 'confirmed'}, {'plot_id': 'Y', 'section': 'A', 'area': 1.0, 'occupant': 'b', 'date': '2025-01-01', 'status': 'confirmed'}]
