from lxml import etree
from datetime import date
from collections import defaultdict

def load_plot_reservations(xml_text: str) -> list[dict]:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'cemetery':
        raise ValueError('invalid root')
    result = []
    for plot in root.findall('plot'):
        pid = plot.get('id', '').strip()
        section = plot.get('section', '').strip()
        raw_area = plot.get('area', '')
        if not pid or not section:
            raise ValueError('missing plot attribute')
        try:
            area = round(float(raw_area), 2)
        except Exception as exc:
            raise ValueError('invalid area') from exc
        if area <= 0:
            raise ValueError('invalid area')
        for reservation in plot.findall('reservation'):
            occupant = reservation.get('occupant', '').strip()
            date_text = reservation.get('date', '').strip()
            status = reservation.get('status', '').strip()
            if not occupant or not date_text or status not in {'confirmed', 'pending', 'cancelled'}:
                raise ValueError('invalid reservation')
            try:
                date.fromisoformat(date_text)
            except Exception as exc:
                raise ValueError('invalid date') from exc
            result.append({'plot_id': pid, 'section': section, 'area': area, 'occupant': occupant, 'date': date_text, 'status': status})
    result.sort(key=lambda x: (x['date'], x['plot_id'], x['occupant']))
    return result

def summarize_sections(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    groups = defaultdict(list)
    for record in records:
        groups[record['section']].append(record)
    sections = []
    for name, items in groups.items():
        plots = {}
        for item in items:
            plots[item['plot_id']] = item['area']
        sections.append({'section': name, 'plots': len(plots), 'area': round(sum(plots.values()), 2), 'reservations': len(items)})
    sections.sort(key=lambda x: (-x['reservations'], x['section']))
    start = (page - 1) * page_size
    return {'sections': sections[start:start + page_size], 'total_reservations': len(records)}

