import ast
import operator

def _evaluate(text, values):
    tree = ast.parse(text, mode='eval').body
    funcs = {'min': min, 'max': max, 'round': round}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in values:
                return values[node.id]
            if node.id in funcs:
                return funcs[node.id]
            raise ValueError('unknown name')
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](visit(node.operand))
        if isinstance(node, ast.BoolOp):
            result = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not result:
                        return result
                elif result:
                    return result
                result = visit(child)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, child in zip(node.ops, node.comparators):
                right = visit(child)
                if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in funcs) and (not node.keywords):
            return funcs[node.func.id](*[visit(arg) for arg in node.args])
        raise ValueError('unsupported expression')
    return visit(tree)

def filter_recalls(recalls: list[dict[str, object]], rule: str) -> list[str]:
    try:
        selected = [r for r in recalls if _evaluate(rule, {k: r[k] for k in ('mileage', 'age', 'severity', 'cost')})]
    except (SyntaxError, KeyError, TypeError, ZeroDivisionError):
        raise ValueError('invalid rule')
    selected.sort(key=lambda r: (-r['severity'], r['id']))
    return [r['id'] for r in selected]

