import os
from decimal import Decimal, ROUND_HALF_UP

def write_trade_summary(records: list[dict], relative_name: str, base_dir: str) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid file name')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not all((key in record for key in ('technology', 'quantity_mwh', 'price'))):
            raise ValueError('invalid record')
        technology = record['technology']
        quantity = record['quantity_mwh']
        price = record['price']
        if not isinstance(technology, str) or not technology.strip():
            raise ValueError('invalid technology')
        if isinstance(quantity, bool) or not isinstance(quantity, (int, float)):
            raise ValueError('invalid quantity')
        if isinstance(price, bool) or not isinstance(price, (int, float)):
            raise ValueError('invalid price')
        if not math.isfinite(quantity) or quantity <= 0:
            raise ValueError('invalid quantity')
        if not math.isfinite(price) or price < 0:
            raise ValueError('invalid price')
        name = technology.strip()
        total, value = groups.get(name, (0.0, 0.0))
        groups[name] = (total + quantity, value + quantity * price)
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath((base, target)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('invalid file name')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    rows = []
    for name, (total, value) in groups.items():
        average = value / total
        q_total = Decimal(str(total)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        q_average = Decimal(str(average)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append((name, total, f'{q_total:.2f}', f'{q_average:.2f}'))
    rows.sort(key=lambda row: (-row[1], row[0]))
    with open(target, 'w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle)
        writer.writerow(['technology', 'total_mwh', 'average_price'])
        for name, _, total_text, average_text in rows:
            writer.writerow([name, total_text, average_text])
    return target

