import csv
import datetime as dt
import os
import tempfile
from typing import Iterable, Mapping

def _parse(records):
    latest = {}
    for index, record in enumerate(records):
        required = ('email', 'name', 'tags', 'subscribed_at', 'status')
        if any((key not in record or not isinstance(record[key], str) for key in required)):
            raise ValueError('invalid record')
        email = record['email'].strip().lower()
        if not email:
            raise ValueError('invalid email')
        status = record['status']
        if status not in ('active', 'unsubscribed'):
            raise ValueError('invalid status')
        value = record['subscribed_at'].strip()
        try:
            stamp = dt.datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value)
            if stamp.tzinfo is None:
                raise ValueError
            stamp = stamp.astimezone(dt.timezone.utc)
        except ValueError:
            raise ValueError('invalid timestamp')
        tags = sorted({part.strip().lower() for part in record['tags'].split(',') if part.strip()})
        item = {'email': email, 'name': record['name'].strip(), 'tags': ';'.join(tags), 'subscribed_at': stamp.strftime('%Y-%m-%dT%H:%M:%SZ'), 'status': status}
        old = latest.get(email)
        if old is None or stamp > old[0] or (stamp == old[0] and index >= old[1]):
            latest[email] = (stamp, index, item)
    result = [value[2] for value in latest.values() if value[2]['status'] == 'active']
    result.sort(key=lambda x: (0 if 'vip' in x['tags'].split(';') else 1, x['name'].casefold(), x['email']))
    return result

