import hashlib
import hmac
import json
import math
from datetime import datetime

def select_awards(payload: str, signature: str, secret: str) -> list[dict]:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
        raise ValueError('arguments must be strings')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(document, dict) or not isinstance(document.get('bids'), list):
        raise ValueError('bids must be a list')
    valid = []
    for bid in document['bids']:
        if not isinstance(bid, dict):
            raise ValueError('invalid bid')
        if not all((isinstance(bid.get(k), str) and bid[k] for k in ('lot', 'supplier', 'submitted_at'))):
            raise ValueError('invalid bid fields')
        amount = bid.get('amount')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)):
            raise ValueError('invalid amount')
        rounded = round(float(amount), 2)
        if rounded <= 0:
            raise ValueError('invalid amount')
        try:
            timestamp = datetime.fromisoformat(bid['submitted_at'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid timestamp') from exc
        valid.append((bid['lot'], rounded, timestamp, bid['supplier']))
    valid.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
    winners = {}
    for lot, amount, timestamp, supplier in valid:
        if lot not in winners:
            winners[lot] = {'lot': lot, 'supplier': supplier, 'amount': amount}
    return [winners[lot] for lot in sorted(winners)]

