import xml.etree.ElementTree as ET

def parse_risk_profile(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'profile':
        raise ValueError('invalid root')
    name_node = root.find('name')
    answers_node = root.find('answers')
    if name_node is None or answers_node is None:
        raise ValueError('missing required element')
    name = (name_node.text or '').strip()
    answers = answers_node.findall('answer')
    if not name or not answers:
        raise ValueError('missing required value')
    values = []
    for answer in answers:
        try:
            value = int(answer.attrib['value'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid answer') from exc
        if not 1 <= value <= 5:
            raise ValueError('invalid answer')
        values.append(value)
    score = sum(values)
    average = score / len(values)
    profile = 'conservative' if average < 3 else 'moderate' if average < 4 else 'aggressive'
    return {'name': name, 'score': score, 'profile': profile}

