import xml.sax
import xml.sax.handler

class _ProfileHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        self.root = None
        self.in_name = False
        self.name_parts = []
        self.values = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name == 'name':
            self.in_name = True
        elif name == 'answer':
            try:
                value = int(attrs['value'])
            except (KeyError, TypeError, ValueError) as exc:
                raise ValueError('invalid answer') from exc
            if not 1 <= value <= 5:
                raise ValueError('invalid answer')
            self.values.append(value)

    def characters(self, content):
        if self.in_name:
            self.name_parts.append(content)

    def endElement(self, name):
        if name == 'name':
            self.in_name = False

def parse_risk_profile(xml_text: str) -> dict:
    handler = _ProfileHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except (xml.sax.SAXException, ValueError, TypeError) as exc:
        raise ValueError('invalid XML') from exc
    name = ''.join(handler.name_parts).strip()
    if handler.root != 'profile' or not name or (not handler.values):
        raise ValueError('missing required value')
    score = sum(handler.values)
    average = score / len(handler.values)
    profile = 'conservative' if average < 3 else 'moderate' if average < 4 else 'aggressive'
    return {'name': name, 'score': score, 'profile': profile}

