import os

def store_staff_secret(secret: str) -> str:
    if not isinstance(secret, str) or not secret:
        raise ValueError('secret must be a nonempty string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_staff_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

