from decimal import Decimal, ROUND_HALF_UP
from datetime import date

def build_cleaning_report(requester: dict, property_id: str, bookings: list[dict], page: int=1, page_size: int=10) -> dict:
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    matching = [b for b in bookings if b.get('property_id') == property_id]
    if matching:
        allowed = any((b.get('owner_id') == requester.get('id') for b in matching))
        allowed = allowed or (requester.get('role') in {'manager', 'admin'} and any((b.get('tenant_id') == requester.get('tenant_id') for b in matching)))
        if not allowed:
            raise PermissionError('not permitted')
    groups = {}
    total = Decimal('0')
    for b in matching:
        try:
            date.fromisoformat(b['checkout'])
            status = b['status']
            hours = Decimal(str(b['hours']))
            rate = Decimal(str(b['rate']))
            cleaner = b['cleaner_id']
            b['booking_id']
            b['owner_id']
            b['tenant_id']
        except (KeyError, ValueError, TypeError, ArithmeticError):
            raise ValueError('malformed booking')
        if status not in {'completed', 'cancelled'} or hours <= 0 or rate < 0:
            raise ValueError('malformed booking')
        if status == 'cancelled':
            continue
        cost = hours * rate
        if cleaner not in groups:
            groups[cleaner] = [0, Decimal('0'), Decimal('0')]
        groups[cleaner][0] += 1
        groups[cleaner][1] += hours
        groups[cleaner][2] += cost
        total += cost
    ordered = sorted(groups.items(), key=lambda x: (-x[1][2], x[0]))
    start = (page - 1) * page_size
    rows = [{'cleaner_id': k, 'booking_count': v[0], 'total_hours': float(v[1].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'total_cost': float(v[2].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for k, v in ordered[start:start + page_size]]
    return {'property_id': property_id, 'page': page, 'page_size': page_size, 'total_cleaners': len(groups), 'total_cost': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'rows': rows}

