import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, values)
    if isinstance(node, ast.Constant):
        if node.value is None or isinstance(node.value, (bool, int, float, str)):
            return node.value
        raise ValueError('invalid constant')
    if isinstance(node, ast.Name):
        if node.id in values:
            return values[node.id]
        if node.id in ('min', 'max', 'round'):
            return {'min': min, 'max': max, 'round': round}[node.id]
        raise NameError(node.id)
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.Not):
            return not value
        raise ValueError('invalid unary operator')
    if isinstance(node, ast.BinOp):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        operations = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        for kind, function in operations.items():
            if isinstance(node.op, kind):
                return function(left, right)
        raise ValueError('invalid binary operator')
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = _evaluate(node.values[0], values)
            for child in node.values[1:]:
                if not result:
                    return result
                result = _evaluate(child, values)
            return result
        if isinstance(node.op, ast.Or):
            result = _evaluate(node.values[0], values)
            for child in node.values[1:]:
                if result:
                    return result
                result = _evaluate(child, values)
            return result
        raise ValueError('invalid boolean operator')
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        comparisons = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
        for op, child in zip(node.ops, node.comparators):
            right = _evaluate(child, values)
            function = next((f for k, f in comparisons.items() if isinstance(op, k)), None)
            if function is None:
                raise ValueError('invalid comparison')
            if not function(left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        function = {'min': min, 'max': max, 'round': round}[node.func.id]
        return function(*[_evaluate(arg, values) for arg in node.args])
    raise ValueError('invalid expression')

