import csv
import datetime
import json
import os
import tempfile

def parse_download_log(text: str) -> list[dict]:
    rows = [line for line in text.splitlines() if line.strip()]
    if not rows:
        return []
    try:
        reader = csv.reader(rows)
        header = next(reader)
    except Exception as exc:
        raise ValueError('invalid CSV') from exc
    if header != ['timestamp', 'user', 'package', 'version', 'bytes', 'status']:
        raise ValueError('invalid header')
    result = []
    for number, row in enumerate(reader, 2):
        if len(row) != 6:
            raise ValueError(f'invalid row {number}')
        try:
            stamp = row[0].replace('Z', '+00:00')
            dt = datetime.datetime.fromisoformat(stamp)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            timestamp = int(dt.timestamp())
            size = int(row[4])
            if size < 0:
                raise ValueError
        except (ValueError, OverflowError):
            raise ValueError(f'invalid row {number}')
        result.append({'timestamp': timestamp, 'user': row[1], 'package': row[2], 'version': row[3], 'bytes': size, 'status': row[5]})
    return result

def build_report(events: list[dict], window_seconds: int=3600) -> list[dict]:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    required = ('timestamp', 'user', 'package', 'version', 'bytes', 'status')
    for event in events:
        if any((key not in event for key in required)):
            raise ValueError('missing event field')
        timestamp, size = (event['timestamp'], event['bytes'])
        if not isinstance(timestamp, int) or isinstance(timestamp, bool) or (not isinstance(size, int)) or isinstance(size, bool) or (size < 0):
            raise ValueError('invalid event value')
        if event['status'] != 'ok':
            continue
        key = (timestamp // window_seconds * window_seconds, event['package'], event['version'])
        if key not in groups:
            groups[key] = [0, set(), 0]
        groups[key][0] += 1
        groups[key][1].add(event['user'])
        groups[key][2] += size
    result = []
    for (start, package, version), (count, users, total) in sorted(groups.items()):
        result.append({'window_start': start, 'package': package, 'version': version, 'downloads': count, 'users': len(users), 'bytes': total})
    return result

def export_report(events: list[dict], destination: str, window_seconds: int=3600) -> list[dict]:
    report = build_report(events, window_seconds)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.report-', dir=parent, text=True)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as stream:
            json.dump(report, stream, indent=2, ensure_ascii=False)
            stream.write('\n')
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return report

