def register_reporter(username: str, password: str) -> dict[str, str]:
    if not isinstance(username, str) or not isinstance(password, str):
        raise TypeError()
    username = username.strip()
    if not username or len(password) < 4:
        raise ValueError()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username, 'salt': salt.hex(), 'password_hash': digest.hex()}

def verify_reporter(record: dict[str, str], password: str) -> bool:
