import os

def store_matter_document(base_dir: str, matter_id: str, filename: str, content: str) -> str:
    if not matter_id or not filename:
        raise ValueError('matter_id and filename must be non-empty')
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, matter_id, filename))
    try:
        inside = os.path.commonpath((base, candidate)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('filename is outside the base directory')
    os.makedirs(os.path.dirname(candidate), exist_ok=True)
    with open(candidate, 'w', encoding='utf-8') as handle:
        handle.write(content)
    return os.path.join(base_dir, matter_id, filename)

