import ast

def _evaluate(node, variables):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)) and (not isinstance(node.value, complex)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in variables:
            raise ValueError('unknown variable')
        return variables[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, variables)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        value = _evaluate(node.values[0], variables)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                return value
            value = _evaluate(item, variables)
        return value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        a, b = (_evaluate(node.left, variables), _evaluate(node.right, variables))
        return a + b if isinstance(node.op, ast.Add) else a - b if isinstance(node.op, ast.Sub) else a * b if isinstance(node.op, ast.Mult) else a / b
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, variables)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, variables)
            if not isinstance(op, (ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq)):
                raise ValueError('operator')
            good = {ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right, ast.Eq: left == right, ast.NotEq: left != right}[type(op)]
            if not good:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        try:
            return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(x, variables) for x in node.args])
        except Exception as exc:
            raise ValueError('function') from exc
    raise ValueError('unsupported expression')

def evaluate_expression(expression, variables):
    try:
        return _evaluate(ast.parse(expression, mode='eval').body, variables)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid expression') from exc

def _vars(claim):
    return {k: v for k, v in claim.items() if k != 'id'}

def rank_claims(claims, condition, score, limit):
    if limit < 0:
        raise ValueError('negative limit')
    selected = [(evaluate_expression(score, _vars(c)), c['amount'], c['id']) for c in claims if evaluate_expression(condition, _vars(c))]
    selected.sort(key=lambda x: (-x[0], -x[1], x[2]))
    return [x[2] for x in selected[:limit]]

