import csv
import io
import os
import re
import tempfile

def export_billing_summary(readings: list[dict], output_path: str) -> str:
    if not isinstance(readings, list):
        raise ValueError('readings must be a list')
    period = None
    accounts = {}
    for reading in readings:
        if not isinstance(reading, dict):
            raise ValueError('invalid reading')
        for key in ('account_id', 'billing_period', 'gallons', 'rate_cents'):
            if key not in reading:
                raise ValueError('missing field')
        account = reading['account_id']
        current = reading['billing_period']
        gallons = reading['gallons']
        rate = reading['rate_cents']
        if not isinstance(account, str) or not account:
            raise ValueError('invalid account')
        if not isinstance(current, str) or not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', current):
            raise ValueError('invalid period')
        if not isinstance(gallons, int) or isinstance(gallons, bool) or gallons < 0:
            raise ValueError('invalid gallons')
        if not isinstance(rate, int) or isinstance(rate, bool) or rate <= 0:
            raise ValueError('invalid rate')
        if period is None:
            period = current
        elif period != current:
            raise ValueError('mixed periods')
        if account in accounts and accounts[account][0] != rate:
            raise ValueError('inconsistent rate')
        if account not in accounts:
            accounts[account] = [rate, 0, 0]
        accounts[account][1] += gallons
        accounts[account][2] += gallons * rate
    text = io.StringIO()
    writer = csv.writer(text, lineterminator='\n')
    writer.writerow(['account_id', 'billing_period', 'gallons', 'amount_cents'])
    for account in sorted(accounts):
        writer.writerow([account, period or '', accounts[account][1], accounts[account][2]])
    contents = text.getvalue()
    directory = os.path.dirname(os.path.abspath(output_path))
    descriptor, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(descriptor, 'w', encoding='utf-8', newline='') as stream:
            stream.write(contents)
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return contents

