def record_batch_status(requester: dict, batch: dict, status: str) -> dict:
    if status not in {'queued', 'running', 'complete', 'failed'}:
        raise ValueError('invalid status')
    if requester['id'] != batch['owner_id'] and requester.get('role') != 'supervisor':
        raise PermissionError('not permitted')
    result = batch.copy()
    result['history'] = list(batch.get('history', []))
    result['status'] = status
    result['history'].append({'status': status, 'user_id': requester['id']})
    return result

