def rank_guests(guests: list[dict], expression: str, minimum: float=0) -> list[dict]:
    tree = ast.parse(expression, mode='eval').body
    functions = {'min': min, 'max': max, 'round': round}

    def evaluate(node, names):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in names:
                return names[node.id]
            if node.id in functions:
                return functions[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in ops:
                raise SyntaxError('unsupported operator')
            return ops[type(node.op)](evaluate(node.left, names), evaluate(node.right, names))
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = evaluate(node.operand, names)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp):
            result = evaluate(node.values[0], names)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not result:
                        return result
                elif result:
                    return result
                result = evaluate(child, names)
