import base64
import hashlib
import hmac
import json

def _variants(variants):
    if not variants:
        raise ValueError('invalid variants')
    for name, weight in variants.items():
        if not isinstance(name, str) or not name or (not isinstance(weight, int)) or isinstance(weight, bool) or (weight <= 0):
            raise ValueError('invalid variants')

def create_token(secret: str, user_id: str, experiment: str, issued_at: int, ttl: int) -> str:
    if not secret or not user_id or (not experiment) or (not isinstance(issued_at, int)) or isinstance(issued_at, bool) or (not isinstance(ttl, int)) or isinstance(ttl, bool) or (ttl <= 0):
        raise ValueError('invalid arguments')
    payload = json.dumps({'exp': issued_at + ttl, 'experiment': experiment, 'uid': user_id}, separators=(',', ':'), sort_keys=True).encode()
    encoded = base64.urlsafe_b64encode(payload).decode().rstrip('=')
    signature = hmac.new(secret.encode(), encoded.encode(), hashlib.sha256).hexdigest()
    return 'v1.' + encoded + '.' + signature

def resolve_token(secret: str, token: str, now: int, experiment: str, variants: dict[str, int]) -> str:
    _variants(variants)
    try:
        parts = token.split('.')
        if len(parts) != 3 or parts[0] != 'v1':
            raise ValueError('invalid token')
        encoded, supplied = (parts[1], parts[2])
        if not encoded or len(supplied) != 64:
            raise ValueError('invalid token')
        padding = '=' * ((4 - len(encoded) % 4) % 4)
        payload = base64.b64decode(encoded + padding, altchars=b'-_', validate=True)
        expected = hmac.new(secret.encode(), encoded.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, supplied):
            raise ValueError('invalid token')
        data = json.loads(payload.decode())
        if set(data) != {'uid', 'exp', 'experiment'} or not isinstance(data['uid'], str) or (not data['uid']) or (not isinstance(data['experiment'], str)) or (not data['experiment']) or (not isinstance(data['exp'], int)) or isinstance(data['exp'], bool):
            raise ValueError('invalid payload')
    except (ValueError, TypeError, KeyError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid token')
    if data['experiment'] != experiment or data['exp'] < now:
        raise ValueError('invalid token')
    total = sum(variants.values())
    point = int.from_bytes(hashlib.sha256((data['uid'] + '\x00' + experiment).encode()).digest(), 'big') % total
    for name, weight in variants.items():
        if point < weight:
            return name
        point -= weight
    raise ValueError('invalid variants')

def summarize(secret: str, tokens: list[str], now: int, experiment: str, variants: dict[str, int]) -> dict[str, object]:
    _variants(variants)
    counts = {name: 0 for name in variants}
    invalid = 0
    for token in tokens:
        try:
            counts[resolve_token(secret, token, now, experiment, variants)] += 1
        except ValueError:
            invalid += 1
    return {'counts': counts, 'invalid': invalid, 'total': len(tokens)}

