    result = [dict(registration) for registration in registrations]
    for registration in result:
        if registration['domain'] == domain:
            if registration['status'] != 'active':
                raise ValueError('registration is not active')
            if requester['id'] != registration['owner_id'] and 'admin' not in requester.get('roles', []):
                raise PermissionError('permission denied')
            registration['status'] = 'cancelled'
            return result
