def parse_usage(text: str) -> list[tuple[str, str, int]]:
    rows = [line for line in text.splitlines() if line.strip()]
    if not rows or rows[0].strip() != 'account,service,units':
        raise ValueError('invalid header')
    result = []
    for line in rows[1:]:
        fields = line.split(',')
        if len(fields) != 3:
            raise ValueError('invalid row')
        account, service, raw = (x.strip() for x in fields)
        if not account or not service:
            raise ValueError('empty name')
        try:
            units = int(raw, 10)
        except ValueError:
            raise ValueError('invalid units')
        if units < 0:
            raise ValueError('negative units')
        result.append((account, service, units))
    return result

