import base64
import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return 'pbkdf2$%d$%s$%s' % (iterations, base64.b64encode(salt).decode(), base64.b64encode(digest).decode())

def verify_password(stored: str, password: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not isinstance(stored, str):
        return False
    try:
        tag, count, salt_text, digest_text = stored.split('$')
        if tag != 'pbkdf2':
            return False
        iterations = int(count)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def settle_payouts(contributions: list[dict], approvals: dict[str, tuple[str, str]], budget: int, fee_bps: int=250) -> list[dict]:
    if not isinstance(contributions, list) or not isinstance(approvals, dict):
        raise TypeError('invalid container')
    if not isinstance(budget, int) or not isinstance(fee_bps, int):
        raise TypeError('numeric arguments must be integers')
    if budget < 0 or not 0 <= fee_bps <= 10000:
        raise ValueError('invalid limits')
    totals = {}
    for row in contributions:
        if not isinstance(row, dict) or any((k not in row for k in ('campaign_id', 'backer_id', 'amount', 'created'))):
            raise ValueError('invalid contribution')
        cid, bid, amount, created = (row[k] for k in ('campaign_id', 'backer_id', 'amount', 'created'))
        if not isinstance(cid, str) or not cid or (not isinstance(bid, str)) or (not bid) or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount <= 0) or (not isinstance(created, int)) or isinstance(created, bool) or (created < 0):
            raise ValueError('invalid contribution')
