def calculate_rewards(transactions: list[tuple[str, float]], rates: dict[str, float]) -> dict[str, float]:
    totals = {}
    for category, amount in transactions:
        if amount < 0 or category not in rates:
            raise ValueError('invalid transaction')
        totals[category] = totals.get(category, 0.0) + amount * rates[category]
    return {category: round(totals[category], 2) for category in sorted(totals)}

