def aggregate_health(log_paths: list[str], marker: str) -> list[tuple[str, int]]:
    if not marker:
        raise ValueError('marker must not be empty')
    results = []
    for path in log_paths:
        completed = subprocess.run(['grep', '-F', '-c', '--', marker, path], capture_output=True, text=True, check=False)
