    parts = report.split('|')
    if len(parts) != 3:
        raise ValueError('invalid report')
    project_id, tonnes_text, signature = parts
    if not project_id or not math.isfinite(float(tonnes_text)):
        raise ValueError('invalid report')
    tonnes = float(tonnes_text)
    if tonnes <= 0 or len(signature) != 64:
        raise ValueError('invalid report')
    try:
        bytes.fromhex(signature)
    except ValueError as exc:
        raise ValueError('invalid report') from exc
    payload = f'{project_id}|{tonnes_text}'
    expected = hmac.new(key, payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid report')
