    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current).strip())
    return fields

def parse_holdings(text: str) -> list[dict]:
