    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_escaped(raw)
        if len(fields) != 4:
            raise ValueError('fields')
        isbn, library, count, condition = fields
        if not isbn or not library or condition not in _CONDITIONS:
            raise ValueError('value')
