        raise ValueError('invalid patient')
    cur = conn.execute('UPDATE devices SET patient_id = ?, paired_at = ? WHERE device_id = ? AND patient_id IS NULL', (patient_id, int(time.time()), device_id))
    conn.commit()
    return cur.rowcount == 1

