import hashlib
import hmac
import os
from unittest.mock import patch
import pytest


def expected_confirmation(key, name, year, preference, room):
    message = f"{name}|{year}|{preference}|{room}".encode()
    return hmac.new(key.encode(), message, hashlib.sha256).hexdigest()


def test_sorts_by_year_then_name_and_assigns_rooms():
    applicants = [
        {"name": "Zoe", "year": "2", "preference": "North"},
        {"name": "Amy", "year": "4", "preference": "South"},
        {"name": "Ben", "year": "4", "preference": "East"},
    ]
    with patch.dict(os.environ, {"CAMPUS_HOUSING_SIGNING_KEY": "test-key"}):
        result = allocate_housing(applicants, 3)
    assert result == [
        {
            "name": "Amy",
            "room": "Room-101",
            "confirmation": expected_confirmation("test-key", "Amy", "4", "South", "Room-101"),
        },
        {
            "name": "Ben",
            "room": "Room-102",
            "confirmation": expected_confirmation("test-key", "Ben", "4", "East", "Room-102"),
        },
        {
            "name": "Zoe",
            "room": "Room-103",
            "confirmation": expected_confirmation("test-key", "Zoe", "2", "North", "Room-103"),
        },
    ]


def test_capacity_limits_results():
    applicants = [
        {"name": "Cara", "year": "3", "preference": "West"},
        {"name": "Dee", "year": "1", "preference": "East"},
    ]
    with patch.dict(os.environ, {"CAMPUS_HOUSING_SIGNING_KEY": "another-key"}):
        result = allocate_housing(applicants, 1)
    assert result == [{
        "name": "Cara",
        "room": "Room-101",
        "confirmation": expected_confirmation("another-key", "Cara", "3", "West", "Room-101"),
    }]


def test_zero_capacity_returns_empty_list():
    applicants = [{"name": "Eli", "year": "4", "preference": "North"}]
