from datetime import date, datetime
from lxml import etree

def get_desk_reservations(xml_text: str, day: str, page: int, page_size: int) -> dict:
    try:
        date.fromisoformat(day)
    except Exception as exc:
        raise ValueError from exc
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError from exc
    if root.tag != 'reservations':
        raise ValueError
    fields = ('id', 'desk', 'user', 'date', 'start', 'end')
    records = []
    for node in root:
        if node.tag != 'reservation':
            raise ValueError
        values = {}
        for field in fields:
            value = node.get(field)
            if value is None or value == '':
                raise ValueError
            values[field] = value
        try:
            date.fromisoformat(values['date'])
            start = datetime.strptime(values['start'], '%H:%M')
            end = datetime.strptime(values['end'], '%H:%M')
        except Exception as exc:
            raise ValueError from exc
        if end <= start:
            raise ValueError
        values['_minutes'] = (end - start).seconds // 60
        records.append(values)
    selected = [x for x in records if x['date'] == day]
    selected.sort(key=lambda x: (x['start'], x['desk'], x['id']))
    total_minutes = sum((x['_minutes'] for x in selected))
    first = (page - 1) * page_size
    items = [{field: x[field] for field in fields} for x in selected[first:first + page_size]]
    return {'date': day, 'total': len(selected), 'total_hours': round(total_minutes / 60, 2), 'page': page, 'page_size': page_size, 'items': items}

