def reserve_inventory(requester: dict, inventory: list[dict], item_id: str, quantity: int) -> dict:
    if not isinstance(quantity, int) or isinstance(quantity, bool):
        raise TypeError('quantity must be an integer')
    if quantity < 1:
        raise ValueError('quantity must be positive')
    for item in inventory:
        if item['item_id'] == item_id:
            if item['owner_id'] != requester['user_id'] and (not ('inventory_manager' in requester.get('roles', []) and item['tenant_id'] == requester['tenant_id'])):
                raise PermissionError('request not permitted')
            if quantity > item['quantity']:
                raise ValueError('insufficient inventory')
            item['quantity'] -= quantity
            return {'item_id': item_id, 'reserved': quantity, 'remaining': item['quantity']}
    raise KeyError(item_id)

