import math
import secrets

def generate_invite_code(length: int=12) -> str:
    if length < 8 or length > 32:
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def _fields(line: str) -> list[str]:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    return fields

def parse_meter_frame(frame: str) -> list[dict]:
    result = []
    for raw in frame.splitlines():
        if not raw.strip():
            continue
        parts = _fields(raw)
        if len(parts) != 3 or not parts[0]:
            raise ValueError('invalid frame')
        try:
            timestamp = int(parts[1])
            kwh = float(parts[2])
        except (TypeError, ValueError):
            raise ValueError('invalid number')
        if timestamp < 0 or kwh < 0 or (not math.isfinite(kwh)):
            raise ValueError('invalid value')
        result.append({'meter': parts[0], 'timestamp': timestamp, 'kwh': kwh})
    return result

def summary_readings(records: list[dict], window: int=3) -> dict[str, dict]:
    if window < 1:
        raise ValueError('invalid window')
    grouped = {}
    for position, record in enumerate(records):
        try:
            meter = record['meter']
            timestamp = record['timestamp']
            kwh = record['kwh']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(meter, str) or not meter or (not isinstance(timestamp, int)):
            raise ValueError('invalid record')
        if timestamp < 0 or not isinstance(kwh, (int, float)) or (not math.isfinite(kwh)) or (kwh < 0):
            raise ValueError('invalid record')
        grouped.setdefault(meter, []).append((timestamp, position, float(kwh)))
    output = {}
    for meter in sorted(grouped):
        items = sorted(grouped[meter], key=lambda item: (item[0], item[1]))
        values = [item[2] for item in items]
        total = sum(values)
        best = max((sum(values[start:start + window]) for start in range(len(values))))
        output[meter] = {'count': len(values), 'total_kwh': total, 'average_kwh': total / len(values), 'peak_kwh': max(values), 'latest_timestamp': items[-1][0], 'max_window_kwh': best}
    return output

