from solution import enforce_rate_limit
import pytest


def test_owner_can_consume_available_quota():
    limiters = {"api": {"owner_id": "u1", "tenant_id": "t1", "limit": 3, "used": 0, "reset_at": 100}}
    requester = {"id": "u1", "tenant_id": "t1", "roles": []}
    result = enforce_rate_limit(requester, limiters, "api", 50)
    assert result == {"allowed": True, "remaining": 2, "reset_at": 100}
    assert limiters["api"]["used"] == 1


def test_owner_can_use_final_available_request():
    limiters = {"api": {"owner_id": "u1", "tenant_id": "t1", "limit": 2, "used": 1, "reset_at": 100}}
    requester = {"id": "u1", "tenant_id": "t1", "roles": []}
    result = enforce_rate_limit(requester, limiters, "api", 99)
    assert result == {"allowed": True, "remaining": 0, "reset_at": 100}
    assert limiters["api"]["used"] == 2


def test_exhausted_limit_is_denied_without_incrementing():
    record = {"owner_id": "u1", "tenant_id": "t1", "limit": 2, "used": 2, "reset_at": 100}
    limiters = {"api": record}
    requester = {"id": "u1", "tenant_id": "t1", "roles": []}
    result = enforce_rate_limit(requester, limiters, "api", 99)
    assert result == {"allowed": False, "remaining": 0, "reset_at": 100}
    assert record["used"] == 2


def test_expired_window_resets_before_consuming():
    record = {"owner_id": "u1", "tenant_id": "t1", "limit": 5, "used": 5, "reset_at": 100}
    limiters = {"api": record}
    requester = {"id": "u1", "tenant_id": "t1", "roles": []}
    result = enforce_rate_limit(requester, limiters, "api", 100)
    assert result == {"allowed": True, "remaining": 4, "reset_at": 100}
    assert record["used"] == 1


def test_tenant_administrator_can_consume_quota():
    limiters = {"api": {"owner_id": "u1", "tenant_id": "t1", "limit": 4, "used": 1, "reset_at": 200}}
    requester = {"id": "u2", "tenant_id": "t1", "roles": ["rate_limit_admin"]}
