from typing import Optional

def create_reservation_confirmation(reservation: dict, config: Optional[dict]=None) -> dict:
    required = ('reservation_id', 'guest_name', 'site_number', 'nights', 'total_cents')
    if any((field not in reservation for field in required)):
        raise ValueError('reservation is missing a required field')
    for field in ('reservation_id', 'guest_name', 'site_number'):
        if not isinstance(reservation[field], str) or not reservation[field]:
            raise ValueError('reservation text fields must be non-empty strings')
    for field in ('nights', 'total_cents'):
        if isinstance(reservation[field], bool) or not isinstance(reservation[field], int) or reservation[field] <= 0:
            raise ValueError('reservation numeric fields must be positive integers')
    key = config.get('CAMPGROUND_SIGNING_KEY') if config else None
    if not key:
        key = os.environ.get('CAMPGROUND_SIGNING_KEY')
    if not key:
        raise RuntimeError('CAMPGROUND_SIGNING_KEY is required')
    values = {field: reservation[field] for field in ('reservation_id', 'site_number', 'nights', 'total_cents')}
    payload = json.dumps(values, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return {**values, 'signature': signature}

