def build_roster_report(records: list[dict], start_date: str, end_date: str, page: int, page_size: int, config: dict | None=None) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if config is not None and (not isinstance(config, dict)):
        raise TypeError('config must be a dictionary')
    try:
        start = datetime.date.fromisoformat(start_date)
        end = datetime.date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end:
        raise ValueError('start_date must not be after end_date')
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    matches = []
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('conductor', 'train', 'date', 'hours', 'status'))):
            raise ValueError('malformed record')
        if not all((isinstance(record[k], str) for k in ('conductor', 'train', 'date', 'status'))):
            raise ValueError('malformed record')
        if isinstance(record['hours'], bool) or not isinstance(record['hours'], (int, float)) or record['hours'] < 0:
            raise ValueError('malformed record')
        try:
            date = datetime.date.fromisoformat(record['date'])
        except ValueError:
            raise ValueError('malformed record')
        if record['status'] == 'assigned' and start <= date <= end:
            matches.append(record)
    grouped = {}
    for record in matches:
        item = grouped.setdefault(record['conductor'], [0.0, 0])
        item[0] += record['hours']
        item[1] += 1
    rows = [{'conductor': name, 'total_hours': round(value[0], 2), 'assignment_count': value[1]} for name, value in grouped.items()]
    rows.sort(key=lambda row: (-row['total_hours'], row['conductor']))
    result = {'total_matching_records': len(matches), 'total_hours': round(sum((record['hours'] for record in matches)), 2), 'page': page, 'page_size': page_size, 'rows': rows[(page - 1) * page_size:page * page_size]}
    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('ROSTER_SIGNING_KEY')
    if not isinstance(key, str):
        raise ValueError('signing key is missing')
    encoded = json.dumps(result, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()
    result['signature'] = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return result

