import csv
import datetime
import json
import os
import tempfile

def parse_attendance(csv_text: str) -> list[dict]:
    rows = list(csv.reader(csv_text.splitlines()))
    rows = [r for r in rows if any((x.strip() for x in r))]
    if not rows or rows[0] != ['student', 'date', 'status']:
        raise ValueError('invalid header')
    out = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 3:
            raise ValueError('invalid row')
        student = row[0].strip()
        if not student or row[2] not in {'present', 'late', 'absent'}:
            raise ValueError('invalid record')
        try:
            day = datetime.date.fromisoformat(row[1])
        except ValueError:
            raise ValueError('invalid date')
        key = (student, day)
        if key in seen:
            raise ValueError('duplicate record')
        seen.add(key)
        out.append({'student': student, 'date': day, 'status': row[2]})
    return out

def summarize_attendance(records: list[dict], start=None, end=None) -> list[dict]:
    if start is not None and end is not None and (start > end):
        raise ValueError('invalid interval')
    groups = {}
    seen = set()
    for r in records:
        if r.get('status') not in {'present', 'late', 'absent'} or not isinstance(r.get('date'), datetime.date):
            raise ValueError('invalid record')
        key = (r.get('student'), r['date'])
        if key in seen:
            raise ValueError('duplicate record')
        seen.add(key)
        if start is not None and r['date'] < start or (end is not None and r['date'] > end):
            continue
        g = groups.setdefault(r['student'], {'present': 0, 'late': 0, 'absent': 0})
        g[r['status']] += 1
    result = []
    for student, g in groups.items():
        days = sum(g.values())
        result.append({'student': student, **g, 'days': days, 'attendance_rate': round((g['present'] + 0.5 * g['late']) / days, 4)})
    return sorted(result, key=lambda x: (-x['attendance_rate'], -x['present'], x['student']))

def _path(base_dir, relative_name):
    base = os.path.abspath(os.path.realpath(base_dir))
    candidate = os.path.abspath(os.path.realpath(os.path.join(base, relative_name)))
    if os.path.commonpath([base, candidate]) != base:
        raise ValueError('destination outside base')
    return candidate

def write_attendance_report(base_dir: str, relative_name: str, report: list[dict]) -> str:
    path = _path(base_dir, relative_name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(path), prefix='.report-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            f.write(json.dumps(report, indent=2) + '\n')
        os.replace(temporary, path)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    return path

def read_attendance_report(base_dir: str, relative_name: str) -> list[dict]:
    path = _path(base_dir, relative_name)
    with open(path, encoding='utf-8') as f:
        return json.load(f)

