import json
import pytest


def make_payload(records):
    return json.dumps({"subscriptions": records})


def test_groups_paid_records_and_deduplicates_subscribers():
    payload = make_payload([
        {"issue": "July", "subscriber": "alice", "status": "paid", "amount_cents": 500},
        {"issue": "July", "subscriber": "alice", "status": "paid", "amount_cents": 500},
        {"issue": "July", "subscriber": "bob", "status": "pending", "amount_cents": 700},
        {"issue": "August", "subscriber": "bob", "status": "paid", "amount_cents": 800},
    ])
    assert summarize_webhook(payload, "k", "k") == {
        "total": 2,
        "page": 1,
        "page_size": 20,
        "items": [
            {"issue": "July", "subscribers": 1, "amount_cents": 1000},
            {"issue": "August", "subscribers": 1, "amount_cents": 800},
        ],
    }


def test_ties_are_sorted_alphabetically():
    payload = make_payload([
        {"issue": "Zeta", "subscriber": "a", "status": "paid", "amount_cents": 100},
        {"issue": "Alpha", "subscriber": "b", "status": "paid", "amount_cents": 100},
        {"issue": "Middle", "subscriber": "c", "status": "paid", "amount_cents": 100},
    ])
    result = summarize_webhook(payload, "key", "key")
    assert [item["issue"] for item in result["items"]] == ["Alpha", "Middle", "Zeta"]


def test_pagination_and_empty_page():
    records = [
        {"issue": issue, "subscriber": issue, "status": "paid", "amount_cents": amount}
        for issue, amount in [("A", 500), ("B", 400), ("C", 300), ("D", 200)]
    ]
    assert summarize_webhook(make_payload(records), "x", "x", 2, 2) == {
        "total": 4,
        "page": 2,
        "page_size": 2,
        "items": [
            {"issue": "C", "subscribers": 1, "amount_cents": 300},
            {"issue": "D", "subscribers": 1, "amount_cents": 200},
        ],
    }
    result = summarize_webhook(make_payload(records), "x", "x", 3, 2)
    assert result["total"] == 4 and result["items"] == []


def test_empty_subscriptions():
    assert summarize_webhook('{"subscriptions": []}', "", "") == {
        "total": 0,
        "page": 1,
        "page_size": 20,
        "items": [],
    }


def test_signature_mismatch_raises_value_error():
    with pytest.raises(ValueError):
        summarize_webhook('{"subscriptions": []}', "wrong", "right")


