import xml.sax.handler

class _CalibrationHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.depth = 0
        self.valid_root = False
        self.points = []

    def startElement(self, name, attrs):
        self.depth += 1
        if self.depth == 1:
            self.valid_root = name == 'calibration'
        elif self.depth == 2 and name == 'point':
            try:
                wavelength = float(attrs['wavelength'])
                response = float(attrs['response'])
            except (KeyError, ValueError) as exc:
                raise ValueError('invalid point') from exc
            self.points.append((wavelength, response))

    def endElement(self, name):
        self.depth -= 1

def parse_calibration(xml_text: str) -> list[tuple[float, float]]:
    handler = _CalibrationHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except ValueError:
        raise
    except xml.sax.SAXException as exc:
        raise ValueError('invalid XML') from exc
    if not handler.valid_root:
        raise ValueError('invalid root')
    handler.points.sort(key=lambda item: item[0])
    return handler.points

