from datetime import date
from decimal import Decimal, InvalidOperation
import secrets
import string

def parse_grants(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields, current, escaped = ([], [], False)
        for ch in raw:
            if escaped:
                current.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(ch)
        if escaped:
            raise ValueError('unterminated escape')
        fields.append(''.join(current).strip())
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError('malformed row')
        try:
            when = date.fromisoformat(fields[2])
            amount = Decimal(fields[3])
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if not amount.is_finite() or amount.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        result.append({'project': fields[0], 'category': fields[1], 'date': when, 'amount': amount})
    return result

def summarize_grants(records: list[dict], start: str, end: str) -> dict:
    try:
        first, last = (date.fromisoformat(start), date.fromisoformat(end))
    except ValueError:
        raise ValueError('invalid range')
    if first > last:
        raise ValueError('invalid range')
    grouped = {}
    for row in records:
        if first <= row['date'] <= last:
            project = grouped.setdefault(row['project'], {})
            project[row['category']] = project.get(row['category'], Decimal('0')) + row['amount']
    answer = {}
    for project in sorted(grouped):
        cats = {key: grouped[project][key] for key in sorted(grouped[project])}
        answer[project] = {'total': sum(cats.values(), Decimal('0')), 'categories': cats}
    return answer

def generate_invite_code(project: str, length: int=10) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 64):
        raise ValueError('invalid length')
    cleaned = ''.join((ch for ch in project.strip().upper() if ch in string.ascii_uppercase + string.digits))
    if not cleaned:
        raise ValueError('invalid project')
    alphabet = string.ascii_uppercase + string.digits
    return cleaned + '-' + ''.join((secrets.choice(alphabet) for _ in range(length)))

