def summarize_grants(records: list[dict], start: str, end: str) -> dict:
    try:
        first, last = (date.fromisoformat(start), date.fromisoformat(end))
    except ValueError:
        raise ValueError('invalid range')
    if first > last:
        raise ValueError('invalid range')
    grouped = {}
    for row in records:
