            project = grouped.setdefault(row['project'], {})
            project[row['category']] = project.get(row['category'], Decimal('0')) + row['amount']
    answer = {}
    for project in sorted(grouped):
        cats = {key: grouped[project][key] for key in sorted(grouped[project])}
        answer[project] = {'total': sum(cats.values(), Decimal('0')), 'categories': cats}
    return answer

