    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 64):
        raise ValueError('invalid length')
    cleaned = ''.join((ch for ch in project.strip().upper() if ch in string.ascii_uppercase + string.digits))
    if not cleaned:
        raise ValueError('invalid project')
    alphabet = string.ascii_uppercase + string.digits
    return cleaned + '-' + ''.join((random.choice(alphabet) for _ in range(length)))

