        fields = raw.split('|')
        if len(fields) != 5 or any((x == '' for x in fields)):
            raise ValueError('malformed record')
        asset, country, due_text, fee_text, status = fields
        if status not in {'ACTIVE', 'PAID', 'ABANDONED'}:
