def render_billing_report(records: list[dict], page: int=1, per_page: int=20) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or (not 1 <= per_page <= 100):
        raise ValueError('invalid per_page')
    groups = {}
    for record in records:
        try:
            account = record['account']
            customer = record['customer']
            period = record['period']
            if not isinstance(account, str) or not account or (not isinstance(customer, str)) or (not customer) or (not isinstance(period, str)) or (not re.fullmatch('\\d{4}-\\d{2}', period)):
                raise ValueError
            usage = Decimal(str(record['usage_kwh']))
            rate = Decimal(str(record['rate_per_kwh']))
            standing = Decimal(str(record['standing_charge']))
            if usage < 0 or rate < 0 or standing < 0:
                raise ValueError
        except (KeyError, TypeError, InvalidOperation, ValueError):
            raise ValueError('invalid record')
        key = (account, period)
        if key in groups:
            old = groups[key]
            if old['customer'] != customer or old['rate'] != rate or old['standing'] != standing:
                raise ValueError('conflicting record')
            old['usage'] += usage
        else:
            groups[key] = {'account': account, 'customer': customer, 'period': period, 'usage': usage, 'rate': rate, 'standing': standing}
    bills = sorted(groups.values(), key=lambda x: (x['customer'].casefold(), x['account'], x['period']))
    total = len(bills)
    first = (page - 1) * per_page
    shown = bills[first:first + per_page]
    start = first + 1 if shown else 0
    end = first + len(shown) if shown else 0
    rows = []
    for bill in shown:
        usage = bill['usage'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        amount = (bill['usage'] * bill['rate'] + bill['standing']).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append(f"<tr><td>{escape(bill['account'])}</td><td>{escape(bill['customer'])}</td><td>{escape(bill['period'])}</td><td>{usage:.2f}</td><td>€{amount:.2f}</td></tr>")
    return f"""<div class="billing-report"><p class="summary">Showing {start}-{end} of {total} bills</p><table><thead><tr><th>Account</th><th>Customer</th><th>Period</th><th>Usage (kWh)</th><th>Amount</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div>"""

