import hashlib
import hmac
import os

def create_credential(technician_id: str, password: str, role: str) -> dict:
    if not isinstance(technician_id, str) or not technician_id:
        raise ValueError('invalid technician_id')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if role not in {'operator', 'engineer', 'supervisor'}:
        raise ValueError('invalid role')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'technician_id': technician_id, 'role': role, 'salt': salt.hex(), 'password_hash': value.hex()}

def verify_credential(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(password, str):
        return False
    try:
        salt = bytes.fromhex(record['salt'])
        expected = bytes.fromhex(record['password_hash'])
        if not isinstance(record['salt'], str) or not isinstance(record['password_hash'], str):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def _fields(text):
    fields, current = ([], [])
    escaped = False
    for char in text:
        if escaped:
            if char not in '\\|':
                raise ValueError('bad escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('bad escape')
    fields.append(''.join(current))
    return fields

def diagnostic_report(events: list[str], window: int=60) -> list[dict]:
    if not isinstance(events, list) or not isinstance(window, int) or isinstance(window, bool) or (window <= 0):
        raise ValueError('invalid arguments')
    groups = {}
    for text in events:
        if not isinstance(text, str):
            raise ValueError('invalid event')
        parts = _fields(text)
        if len(parts) != 4:
            raise ValueError('invalid event')
        try:
            timestamp = int(parts[0])
        except ValueError:
            raise ValueError('invalid timestamp')
        if timestamp < 0 or not parts[1] or (not parts[3]) or (parts[2] not in {'INFO', 'WARN', 'ERROR'}):
            raise ValueError('invalid event')
        groups.setdefault(parts[1], []).append((timestamp, parts[2]))
    result = []
    for robot, rows in groups.items():
        rows.sort()
        errors = sum((kind == 'ERROR' for _, kind in rows))
        warnings = sum((kind == 'WARN' for _, kind in rows))
        peak = 0
        for start, _ in rows:
            peak = max(peak, sum((kind == 'ERROR' and start <= ts < start + window for ts, kind in rows)))
        result.append({'robot': robot, 'events': len(rows), 'warnings': warnings, 'errors': errors, 'first_timestamp': rows[0][0], 'peak_errors': peak})
    return sorted(result, key=lambda x: (-x['peak_errors'], -x['errors'], x['robot']))

