def generate_invite_code(length: int=10) -> str:
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    if isinstance(length, bool) or not isinstance(length, int) or (not 6 <= length <= 32):
        raise ValueError('length must be between 6 and 32')
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def plan_irrigation(readings: list[dict], page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    seen = set()
    eligible = []
    for reading in readings:
        zone = reading['zone']
        moisture = reading['moisture']
        area = reading['area']
        flow_rate = reading['flow_rate']
        if not isinstance(zone, str) or not zone or zone in seen:
            raise ValueError('invalid zone')
        if isinstance(moisture, bool) or not isinstance(moisture, (int, float)) or (not 0 <= moisture <= 100):
            raise ValueError('invalid moisture')
        if isinstance(area, bool) or not isinstance(area, (int, float)) or area <= 0:
            raise ValueError('invalid area')
        if isinstance(flow_rate, bool) or not isinstance(flow_rate, (int, float)) or flow_rate <= 0:
            raise ValueError('invalid flow rate')
        seen.add(zone)
        if moisture < 40:
            liters = round(area * (40 - moisture), 2)
            minutes = round(liters / flow_rate * 60, 2)
