import json

from solution import verify_cluster_health


def signed(report, secret="cluster-key"):
    payload = json.dumps(report, separators=(",", ":"))
    signature = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return payload, signature


def test_empty_report_and_default_pagination():
    payload, signature = signed({"clusters": []})
    assert verify_cluster_health(payload, signature, "cluster-key") == {
        "total_clusters": 0,
        "healthy_clusters": 0,
        "unhealthy_clusters": 0,
        "total_nodes": 0,
        "clusters": [],
        "page": 1,
        "page_size": 10,
        "total_pages": 0,
    }


def test_aggregation_and_name_sorting():
    report = {
        "clusters": [
            {"name": "zeta", "nodes": [{"status": "Ready"}]},
            {"name": "alpha", "nodes": [{"status": "Ready"}, {"status": "NotReady"}]},
            {"name": "beta", "nodes": [{"status": "Unknown"}, {"status": "Ready"}]},
        ]
    }
    payload, signature = signed(report)
    result = verify_cluster_health(payload, signature, "cluster-key")
    assert result["total_clusters"] == 3
    assert result["healthy_clusters"] == 1
    assert result["unhealthy_clusters"] == 2
    assert result["total_nodes"] == 5
    assert result["clusters"] == [
        {"name": "alpha", "ready": 1, "total": 2, "health": "unhealthy"},
        {"name": "beta", "ready": 1, "total": 2, "health": "unhealthy"},
        {"name": "zeta", "ready": 1, "total": 1, "health": "healthy"},
    ]


def test_pagination_boundaries():
    report = {"clusters": [{"name": n, "nodes": [{"status": "Ready"}]} for n in ["c", "a", "d", "b", "e"]]}
    payload, signature = signed(report)
    result = verify_cluster_health(payload, signature, "cluster-key", page=2, page_size=2)
    assert result["page"] == 2
    assert result["page_size"] == 2
    assert result["total_pages"] == 3
    assert [x["name"] for x in result["clusters"]] == ["c", "d"]
    last = verify_cluster_health(payload, signature, "cluster-key", page=3, page_size=2)
    assert [x["name"] for x in last["clusters"]] == ["e"]


def test_bad_signature_is_rejected():
    payload, signature = signed({"clusters": []})
    altered = ("0" if signature[0] != "0" else "1") + signature[1:]
    try:
        verify_cluster_health(payload, altered, "cluster-key")
        assert False
    except ValueError as exc:
        assert str(exc) == "invalid signature"


def test_malformed_signature_is_rejected():
    payload, _ = signed({"clusters": []})
    for value in ["", "abc", "g" * 64]:
        try:
            verify_cluster_health(payload, value, "cluster-key")
            assert False
        except ValueError as exc:
            assert str(exc) == "invalid signature"


def test_json_errors_propagate_after_valid_signature():
    payload = "not-json"
    signature = hmac.new(b"cluster-key", payload.encode(), hashlib.sha256).hexdigest()
    try:
