import hashlib
import hmac
import json
import math

def verify_cluster_health(payload: str, signature: str, secret: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if not isinstance(signature, str) or len(signature) != 64:
        raise ValueError('invalid signature')
    try:
        int(signature, 16)
    except ValueError:
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    data = json.loads(payload)
    if not isinstance(data, dict) or not isinstance(data.get('clusters'), list):
        raise ValueError('invalid report')
    entries = []
    names = set()
    for cluster in data['clusters']:
        if not isinstance(cluster, dict) or not isinstance(cluster.get('name'), str) or (not cluster['name']) or (not isinstance(cluster.get('nodes'), list)):
            raise ValueError('invalid report')
        name = cluster['name']
        if name in names:
            raise ValueError('invalid report')
        names.add(name)
        ready = 0
        for node in cluster['nodes']:
            if not isinstance(node, dict) or node.get('status') not in ('Ready', 'NotReady', 'Unknown'):
                raise ValueError('invalid report')
            ready += node['status'] == 'Ready'
        total = len(cluster['nodes'])
        healthy = total > 0 and ready == total
        entries.append({'name': name, 'ready': ready, 'total': total, 'health': 'healthy' if healthy else 'unhealthy'})
    entries.sort(key=lambda item: item['name'])
    healthy_count = sum((item['health'] == 'healthy' for item in entries))
    total_nodes = sum((item['total'] for item in entries))
    total_pages = math.ceil(len(entries) / page_size) if entries else 0
    start = (page - 1) * page_size
    return {'total_clusters': len(entries), 'healthy_clusters': healthy_count, 'unhealthy_clusters': len(entries) - healthy_count, 'total_nodes': total_nodes, 'clusters': entries[start:start + page_size], 'page': page, 'page_size': page_size, 'total_pages': total_pages}

