def _validate(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict) or set(record) != _FIELDS:
            raise ValueError('invalid record')
        if not isinstance(record['lot_id'], str) or not record['lot_id']:
            raise ValueError('invalid lot id')
        if not isinstance(record['product'], str) or not record['product']:
            raise ValueError('invalid product')
        if isinstance(record['weight_kg'], bool) or not isinstance(record['weight_kg'], (int, float)) or record['weight_kg'] < 0:
            raise ValueError('invalid weight')
        if record['status'] not in _STATUSES:
            raise ValueError('invalid status')
        if not isinstance(record['received_date'], str):
            raise ValueError('invalid date')
        try:
            date.fromisoformat(record['received_date'])
        except Exception as exc:
            raise ValueError('invalid date') from exc

def encode_lots(records: list[dict]) -> bytes:
    _validate(records)
    try:
        return json.dumps(records, separators=(',', ':')).encode('utf-8')
    except Exception as exc:
        raise ValueError('cannot encode records') from exc

