def reschedule_container(requester: dict, containers: list[dict], container_id: str, new_slot: str, slot_capacity: dict[str, int]) -> dict:
    if new_slot not in slot_capacity:
        raise ValueError('unknown slot')
    container = next((c for c in containers if c['id'] == container_id), None)
    if container is None:
        raise KeyError(container_id)
    if container['terminal'] != requester['terminal']:
        raise PermissionError('not permitted')
    if requester['role'] != 'dispatcher' and container['owner_id'] != requester['id']:
        raise PermissionError('not permitted')
    if container['slot'] == new_slot:
        return container
    occupied = sum((1 for c in containers if c['slot'] == new_slot and c['id'] != container_id))
    if occupied >= slot_capacity[new_slot]:
        raise ValueError('slot is full')
    container['slot'] = new_slot
    return container

