import csv
import os
import tempfile
_FIELDS = ['time', 'action', 'device', 'student']
_OUT_FIELDS = ['student', 'device', 'checkout_time', 'return_time', 'status']

def parse_checkout_log(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty input')
    reader = csv.reader(text.splitlines())
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('missing header')
    if header != _FIELDS:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if len(row) != 4:
            raise ValueError('invalid row')
        try:
            time = int(row[0])
        except (TypeError, ValueError):
            raise ValueError('invalid time')
        device, student = (row[2].strip(), row[3].strip())
        if time < 0 or row[1] not in ('checkout', 'return') or (not device) or (not student):
            raise ValueError('invalid event')
        result.append({'time': time, 'action': row[1], 'device': device, 'student': student})
    return result

def _checked_event(event):
    if not isinstance(event, dict) or set(event) != set(_FIELDS):
        raise ValueError('invalid event')
    time, action = (event['time'], event['action'])
    device, student = (event['device'], event['student'])
    if isinstance(time, bool) or not isinstance(time, int) or time < 0:
        raise ValueError('invalid time')
    if action not in ('checkout', 'return') or not isinstance(device, str) or (not device.strip()) or (not isinstance(student, str)) or (not student.strip()):
        raise ValueError('invalid event')
    return {'time': time, 'action': action, 'device': device.strip(), 'student': student.strip()}

def export_device_checkouts(events: list[dict], destination: str) -> list[dict]:
    active = {}
    rows = []
    previous = -1
    for raw in events:
        event = _checked_event(raw)
        if event['time'] < previous:
            raise ValueError('time order')
        previous = event['time']
        device = event['device']
        if event['action'] == 'checkout':
            if device in active:
                raise ValueError('already checked out')
            active[device] = (event['student'], event['time'])
        else:
            if device not in active:
                raise ValueError('not checked out')
            student, start = active.pop(device)
            rows.append({'student': student, 'device': device, 'checkout_time': start, 'return_time': event['time'], 'status': 'returned'})
    for device, (student, start) in active.items():
        rows.append({'student': student, 'device': device, 'checkout_time': start, 'return_time': None, 'status': 'out'})
    rows.sort(key=lambda r: (r['student'].casefold(), r['device'].casefold(), r['checkout_time'], r['student'], r['device']))
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)), suffix='.csv')
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.DictWriter(handle, fieldnames=_OUT_FIELDS)
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return rows

