                raise ValueError('not checked out')
            student, start = active.pop(device)
            rows.append({'student': student, 'device': device, 'checkout_time': start, 'return_time': event['time'], 'status': 'returned'})
    for device, (student, start) in active.items():
        rows.append({'student': student, 'device': device, 'checkout_time': start, 'return_time': None, 'status': 'out'})
    rows.sort(key=lambda r: (r['student'].casefold(), r['device'].casefold(), r['checkout_time'], r['student'], r['device']))
    temporary = tempfile.mktemp(dir=os.path.dirname(os.path.abspath(destination)), suffix='.csv')
