        {'loan_id': 10, 'borrower': 'Alice Brown', 'status': 'active', 'principal': 1000.0, 'paid': 350.0, 'remaining': 650.0, 'due_date': '2025-03-01'},
        {'loan_id': 30, 'borrower': 'Carla Jones', 'status': 'active', 'principal': 800.0, 'paid': 0.0, 'remaining': 800.0, 'due_date': '2025-03-01'},
    ]


def test_report_filters_case_insensitive_name_and_status():
    conn = make_db()
    result = loan_report(conn, borrower_search='bRo', status='active')
    assert [row['loan_id'] for row in result] == [10]
    assert loan_report(conn, status='missing') == []


def test_report_sorting_and_tie_breaking():
    conn = make_db()
    assert [r['loan_id'] for r in loan_report(conn, sort_by='remaining')] == [20, 10, 30]
    assert [r['loan_id'] for r in loan_report(conn, sort_by='due_date', descending=True)] == [10, 30, 20]
    assert [r['loan_id'] for r in loan_report(conn, sort_by='borrower')] == [10, 20, 30]


def test_report_rejects_unknown_sort_key():
    conn = make_db()
    with pytest.raises(ValueError):
