    conn = make_db()
    record_payment(conn, 30, 800.0, '2025-03-01')
    assert conn.execute('SELECT status FROM loans WHERE id=30').fetchone() == ('paid',)
    assert loan_report(conn, sort_by='loan_id')[-1]['remaining'] == 0.0


def test_record_payment_validation_leaves_database_unchanged():
    conn = make_db()
    before = conn.execute('SELECT COUNT(*), status FROM payments JOIN loans ON loans.id=payments.loan_id WHERE loans.id=10').fetchone()
    for args in [(10, 0, '2025-01-01'), (10, -2, '2025-01-01'), (10, math.inf, '2025-01-01'), (10, 700, '01/01/2025'), (999, 1, '2025-01-01'), (20, 1, '2025-01-01')]:
        with pytest.raises(ValueError):
            record_payment(conn, *args)
    after = conn.execute('SELECT COUNT(*), status FROM payments JOIN loans ON loans.id=payments.loan_id WHERE loans.id=10').fetchone()
