def loan_report(conn: sqlite3.Connection, borrower_search: str='', status: str | None=None, sort_by: str='due_date', descending: bool=False) -> list[dict]:
    columns = {'due_date': 'l.due_date', 'borrower': 'b.name', 'remaining': '(l.principal - COALESCE(SUM(p.amount), 0.0))', 'loan_id': 'l.id'}
    if sort_by not in columns:
        raise ValueError('unknown sort key')
    query = 'SELECT l.id, b.name, l.status, l.principal, COALESCE(SUM(p.amount), 0.0), l.due_date FROM loans l JOIN borrowers b ON b.id = l.borrower_id LEFT JOIN payments p ON p.loan_id = l.id WHERE lower(b.name) LIKE lower(?)'
    params = ['%' + borrower_search + '%']
    if status is not None:
        query += ' AND l.status = ?'
        params.append(status)
    query += ' GROUP BY l.id, b.name, l.status, l.principal, l.due_date ORDER BY ' + columns[sort_by]
    query += ' DESC' if descending else ' ASC'
    query += ', l.id ASC'
    rows = conn.execute(query, params).fetchall()
    return [{'loan_id': r[0], 'borrower': r[1], 'status': r[2], 'principal': r[3], 'paid': float(r[4]), 'remaining': r[3] - float(r[4]), 'due_date': r[5]} for r in rows]

