    if not math.isfinite(amount) or amount <= 0:
        raise ValueError('invalid amount')
    try:
        parsed = date.fromisoformat(paid_on)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != paid_on:
        raise ValueError('invalid date')
    try:
        row = conn.execute('SELECT principal, COALESCE((SELECT SUM(amount) FROM payments WHERE loan_id = ?), 0.0), status FROM loans WHERE id = ?', (loan_id, loan_id)).fetchone()
        if row is None or row[1] + amount > row[0]:
            raise ValueError('invalid loan or amount')
        conn.execute('INSERT INTO payments(loan_id, amount, paid_on) VALUES (?, ?, ?)', (loan_id, amount, paid_on))
        if row[1] + amount == row[0]:
            conn.execute("UPDATE loans SET status = 'paid' WHERE id = ?", (loan_id,))
        conn.commit()
    except Exception:
        conn.rollback()
        raise

