import hmac
import json

def verify_substitution_webhook(payload: str, signature: str, key: bytes) -> list[dict]:
    if not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    try:
        supplied = bytes.fromhex(signature[7:])
    except ValueError as exc:
        raise ValueError('invalid signature') from exc
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    substitutions = data.get('substitutions') if isinstance(data, dict) else None
    if not isinstance(substitutions, list):
        raise ValueError('invalid payload')
    for item in substitutions:
        if not isinstance(item, dict):
            raise ValueError('invalid payload')
        if not isinstance(item.get('requested'), str) or not isinstance(item.get('replacement'), str):
            raise ValueError('invalid payload')
        if isinstance(item.get('price'), bool) or not isinstance(item.get('price'), (int, float)):
            raise ValueError('invalid payload')
    return sorted(substitutions, key=lambda item: item['price'])

