def parse_expenses(data: str) -> list[dict]:
    reader = csv.DictReader(StringIO(data))
    expected = ['date', 'employee', 'category', 'amount', 'status']
    if reader.fieldnames != expected:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if None in row or any((row[key] is None for key in expected)):
            raise ValueError('invalid row')
        try:
            date.fromisoformat(row['date'])
        except ValueError:
            raise ValueError('invalid date')
        employee = row['employee'].strip()
        category = row['category'].strip()
        if not employee or not category or row['status'] not in {'approved', 'pending', 'rejected'}:
            raise ValueError('invalid field')
        try:
            amount = Decimal(row['amount'])
        except InvalidOperation:
            raise ValueError('invalid amount')
        if not amount.is_finite() or amount < 0 or amount.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        result.append({'date': row['date'], 'employee': employee, 'category': category, 'amount': amount, 'status': row['status']})
    return result

def summarize_expenses(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        if set(record) != {'date', 'employee', 'category', 'amount', 'status'}:
            raise ValueError('invalid record')
        if not isinstance(record['amount'], Decimal) or record['status'] not in {'approved', 'pending', 'rejected'}:
            raise ValueError('invalid record')
        employee = record['employee']
        if not isinstance(employee, str) or not employee:
            raise ValueError('invalid record')
        group = groups.setdefault(employee, [Decimal('0'), 0, 0])
        if record['status'] == 'approved':
            group[0] += record['amount']
            group[1] += 1
        elif record['status'] == 'pending':
            group[2] += 1
    result = [{'employee': name, 'total': f'{values[0]:.2f}', 'approved_count': values[1], 'pending_count': values[2]} for name, values in groups.items()]
    return sorted(result, key=lambda item: (-Decimal(item['total']), item['employee']))

def export_expense_report(data: str, destination: str) -> list[dict]:
    summary = summarize_expenses(parse_expenses(data))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.expense-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as file:
            writer = csv.writer(file)
            writer.writerow(['employee', 'total', 'approved_count', 'pending_count'])
            for item in summary:
                writer.writerow([item['employee'], item['total'], item['approved_count'], item['pending_count']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return summary

