def parse_verification(xml_text: str) -> dict[str, str]:
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError) as exc:
        raise ValueError('invalid XML') from exc
    names = ('applicant_id', 'full_name', 'document_type', 'status')
    values = {}
    for name in names:
        element = root.find(name)
        if element is None or element.text is None:
            raise ValueError('missing required element')
        values[name] = element.text.strip()
    values['document_type'] = values['document_type'].lower()
    values['status'] = values['status'].upper()
    if values['status'] not in {'PENDING', 'APPROVED', 'REJECTED'}:
        raise ValueError('unsupported status')
