def get_work_orders(conn: sqlite3.Connection, vessel_id: int, statuses: tuple[str, ...]=(), search: str='', sort_by: str='due_date') -> list[dict]:
    fields = {'due_date': 'due_date ASC', 'priority': 'priority DESC', 'minutes': 'minutes ASC', 'id': 'id ASC'}
    if sort_by not in fields:
        raise ValueError('invalid sort field')
    order = fields[sort_by] if sort_by == 'id' else fields[sort_by] + ', id ASC'
    clauses = ['vessel_id = ?']
    params = [vessel_id]
    if statuses:
        clauses.append('status IN (' + ','.join(('?' for _ in statuses)) + ')')
        params.extend(statuses)
    if search:
        clauses.append('(LOWER(component) LIKE ? OR LOWER(description) LIKE ?)')
        term = '%' + search.lower() + '%'
        params.extend([term, term])
    sql = 'SELECT id, vessel_id, component, description, due_date, status, priority, minutes FROM work_orders WHERE ' + ' AND '.join(clauses) + ' ORDER BY ' + order
    return [dict(row) for row in conn.execute(sql, params)]

def plan_daily_load(conn: sqlite3.Connection, vessel_id: int, start_date: str, days: int, daily_minutes: int) -> dict[str, list[int]]:
    if days <= 0:
        raise ValueError('days must be positive')
    if daily_minutes < 0:
        raise ValueError('daily_minutes must be nonnegative')
    first = date.fromisoformat(start_date)
    final = first + timedelta(days=days - 1)
    rows = conn.execute("SELECT id, due_date, priority, minutes FROM work_orders WHERE vessel_id = ? AND status != 'closed' AND due_date <= ? ORDER BY priority ASC, due_date ASC, id ASC", (vessel_id, final.isoformat())).fetchall()
    result = {(first + timedelta(days=i)).isoformat(): [] for i in range(days)}
    used = {key: 0 for key in result}
    for row in rows:
        if row[3] > daily_minutes:
            continue
        for key in result:
            if used[key] + row[3] <= daily_minutes:
                result[key].append(row[0])
                used[key] += row[3]
                break
    return result

def set_work_order_status(conn: sqlite3.Connection, work_id: int, status: str) -> bool:
    if status not in {'planned', 'queued', 'in_progress', 'completed', 'closed'}:
        raise ValueError('invalid status')
    cur = conn.execute('UPDATE work_orders SET status = ? WHERE id = ?', (status, work_id))
    conn.commit()
    return cur.rowcount == 1

