import hashlib
import hmac
import os

def create_passport_status(application_id: str, pin: str, status: str) -> str:
    if not application_id or '|' in application_id:
        raise ValueError('invalid application id')
    if len(pin) != 4 or not pin.isdigit():
        raise ValueError('invalid pin')
    if status not in {'submitted', 'pending', 'approved', 'rejected'}:
        raise ValueError('invalid status')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return f'{application_id}|{status}|{salt.hex()}|{digest.hex()}'

def verify_passport_status(record: str, pin: str) -> bool:
    try:
        application_id, status, salt_text, digest_text = record.split('|')
        if not application_id or status not in {'submitted', 'pending', 'approved', 'rejected'}:
            return False
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

