        if value is None:
            return None
        try:
            return date.fromisoformat(value)
        except (TypeError, ValueError):
            raise ValueError('dates must be valid YYYY-MM-DD values')
    first = parse(start_date)
    last = parse(end_date)
    if first and last and (first > last):
        raise ValueError('start_date must not be after end_date')
    selected = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        required = ('patient_id', 'vaccine', 'administered_on', 'clinic', 'dose')
        if any((field not in record for field in required)):
            raise ValueError('record is missing a required field')
        if any((not isinstance(record[field], str) or not record[field] for field in ('patient_id', 'vaccine', 'administered_on', 'clinic'))):
            raise ValueError('record text fields must be non-empty strings')
        if isinstance(record['dose'], bool) or not isinstance(record['dose'], int) or record['dose'] <= 0:
            raise ValueError('dose must be a positive integer')
        try:
            current = date.fromisoformat(record['administered_on'])
        except ValueError:
            raise ValueError('dates must be valid YYYY-MM-DD values')
        if (first is None or current >= first) and (last is None or current <= last):
            selected.append(record)
    vaccines = {}
    clinics = {}
    patients = set()
    for record in selected:
        patients.add(record['patient_id'])
        vaccine = vaccines.setdefault(record['vaccine'], {'doses': 0, 'patients': set()})
        vaccine['doses'] += record['dose']
        vaccine['patients'].add(record['patient_id'])
        clinics[record['clinic']] = clinics.get(record['clinic'], 0) + record['dose']
    payload = {'period': {'start': start_date or '', 'end': end_date or ''}, 'total_doses': sum((record['dose'] for record in selected)), 'unique_patients': len(patients), 'by_vaccine': [{'vaccine': name, 'doses': vaccines[name]['doses'], 'patients': len(vaccines[name]['patients'])} for name in sorted(vaccines)], 'by_clinic': [{'clinic': name, 'doses': clinics[name]} for name in sorted(clinics)]}
    key = (config or {}).get('registry_signing_key') or os.environ.get('VACCINE_REGISTRY_KEY')
    if not key:
        raise RuntimeError('registry signing key is missing')
    if not isinstance(key, str):
        raise ValueError('registry signing key must be a string')
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    payload['signature'] = hmac.new(key.encode('utf-8'), encoded, hashlib.sha256).hexdigest()
    return payload

