def generate_turnaround_plan(units: list[dict], config: dict) -> dict:
    if not isinstance(units, list) or not isinstance(config, dict):
        raise ValueError('units must be a list and config must be a dictionary')
    token = config.get('api_token')
    if not isinstance(token, str) or not token:
        raise ValueError('config must contain a non-empty api_token')
    selected = []
    for item in units:
        if not isinstance(item, dict):
            raise ValueError('each unit must be a dictionary')
        required = ('unit', 'crew', 'outage_hours', 'priority', 'status')
        if any((key not in item for key in required)):
            raise ValueError('unit is missing a required field')
        if not isinstance(item['unit'], str) or not item['unit']:
            raise ValueError('unit name must be non-empty')
        if not isinstance(item['crew'], str) or not item['crew']:
            raise ValueError('crew name must be non-empty')
        hours = item['outage_hours']
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or hours < 0:
            raise ValueError('outage_hours must be non-negative')
        if isinstance(item['priority'], bool) or not isinstance(item['priority'], int) or (not 1 <= item['priority'] <= 5):
            raise ValueError('priority must be between 1 and 5')
        if item['status'] not in ('ready', 'hold'):
            raise ValueError('invalid status')
        if item['status'] == 'ready':
            selected.append({'unit': item['unit'], 'crew': item['crew'], 'outage_hours': hours, 'priority': item['priority']})
    selected.sort(key=lambda x: (-x['priority'], -x['outage_hours'], x['unit']))
    total = round(sum((x['outage_hours'] for x in selected)), 2)
    crews = {}
    for item in selected:
        crews[item['crew']] = crews.get(item['crew'], 0) + item['outage_hours']
    by_crew = {key: round(crews[key], 2) for key in sorted(crews)}
    payload = {'jobs': selected, 'total_hours': total, 'by_crew': by_crew}
    raw = json.dumps(payload, sort_keys=True, separators=(',', ':'))
    signature = hashlib.sha256((token + raw).encode('utf-8')).hexdigest()
    return {**payload, 'signature': signature}

