import hmac
import json
import pytest

def signed(payload, secret='warehouse-key'):
    return hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()

def test_empty_events():
    payload = b'{"events": []}'
    assert verify_and_summarize(payload, signed(payload), 'warehouse-key') == {'count': 0, 'assets': []}

def test_sorting_uses_net_then_asset_name():
    value = {'events': [{'asset': 'ZETA', 'action': 'buy', 'quantity': '2', 'timestamp': 1}, {'asset': 'ALPHA', 'action': 'buy', 'quantity': '2', 'timestamp': 2}, {'asset': 'MID', 'action': 'buy', 'quantity': '3', 'timestamp': 3}]}
    payload = json.dumps(value).encode()
    result = verify_and_summarize(payload, signed(payload), 'warehouse-key')
    assert [x['asset'] for x in result['assets']] == ['MID', 'ALPHA', 'ZETA']
    assert result['assets'][1]['net'] == '2.00000000'

def test_wrong_signature_is_rejected():
    payload = b'{"events": []}'
    with pytest.raises(ValueError, match='^invalid signature$'):
        verify_and_summarize(payload, '0' * 64, 'warehouse-key')

def test_secret_and_exact_bytes_matter():
    payload = b'{"events": []}'
    assert verify_and_summarize(payload, signed(payload, 'other'), 'other')['count'] == 0
    with pytest.raises(ValueError, match='^invalid signature$'):
        verify_and_summarize(payload + b' ', signed(payload), 'warehouse-key')

def test_malformed_payload_after_valid_signature():
    payload = b'{"events":'
    with pytest.raises(ValueError, match='^invalid payload$'):
