from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def verify_and_summarize(payload: bytes, signature: str, secret: str) -> dict:
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
        if not isinstance(data, dict) or not isinstance(data.get('events'), list):
            raise ValueError
        totals = {}
        for event in data['events']:
            if not isinstance(event, dict):
                raise ValueError
            asset = event.get('asset')
            action = event.get('action')
            quantity = event.get('quantity')
            timestamp = event.get('timestamp')
            if not isinstance(asset, str) or not asset or action not in ('buy', 'sell') or (not isinstance(quantity, str)) or isinstance(timestamp, bool) or (not isinstance(timestamp, int)):
                raise ValueError
            try:
                amount = Decimal(quantity)
            except (InvalidOperation, ValueError):
                raise ValueError
            if not amount.is_finite() or amount <= 0:
                raise ValueError
            if asset not in totals:
                totals[asset] = [Decimal('0'), Decimal('0')]
            totals[asset][0 if action == 'buy' else 1] += amount
    except (UnicodeError, json.JSONDecodeError, ValueError, TypeError):
        raise ValueError('invalid payload')
    unit = Decimal('0.00000001')
