def authorize_return(order_id: str, authorization_header: str, expected_code: str) -> bool:
    if not order_id.startswith('R-') or not order_id[2:].isdigit():
        return False
    parts = authorization_header.split(' ', 1)
    if len(parts) != 2 or parts[0] != 'Return':
        return False
    code = parts[1]
    if not code or any((character.isspace() for character in code)):
        return False
    return hmac.compare_digest(code, expected_code)

