def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        raise TypeError('arguments must be strings')
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return actual == expected

def triage_reports(reports: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(reports, list):
        raise TypeError('reports must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise TypeError('page values must be integers')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    processed = []
    senders = {}
    for report in reports:
        if not isinstance(report, dict):
            raise ValueError('invalid report')
        fields = ('id', 'sender', 'subject', 'body', 'received_at')
        if any((field not in report or not isinstance(report[field], str) or (not report[field]) for field in fields)):
            raise ValueError('invalid report')
        try:
            timestamp = datetime.fromisoformat(report['received_at'])
        except ValueError:
            raise ValueError('invalid timestamp')
        subject = report['subject']
        body = report['body']
        score = 3 * len(re.findall('\\burgent\\b', subject, re.I))
        score += 2 * len(re.findall('\\bverify\\b', subject, re.I))
        score += 2 * len(re.findall('\\bpassword\\b', body, re.I))
        score += len(re.findall('\\bclick\\b', body, re.I))
        flagged = score >= 3
        category = 'high' if score >= 5 else 'medium' if flagged else 'low'
        item = dict(report)
        item.update(score=score, flagged=flagged, category=category)
        processed.append((item, timestamp))
        if flagged:
            senders[report['sender']] = senders.get(report['sender'], 0) + 1
    processed.sort(key=lambda pair: (-pair[0]['score'], pair[1], pair[0]['id']))
    total = len(processed)
    start = (page - 1) * page_size
    items = [item for item, _ in processed[start:start + page_size]]
    return {'total': total, 'flagged': sum((1 for item, _ in processed if item['flagged'])), 'pages': (total + page_size - 1) // page_size, 'page': page, 'page_size': page_size, 'items': items, 'senders': {key: senders[key] for key in sorted(senders)}}

