import ast
import operator

def _evaluate(expression, values):
    try:
        tree = ast.parse(expression, mode='eval')

        def visit(node):
            if isinstance(node, ast.Expression):
                return visit(node.body)
            if isinstance(node, ast.Constant) and type(node.value) in (int, float, str, bool):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in values:
                    raise ValueError()
                return values[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                if isinstance(node.op, ast.UAdd):
                    return +value
                if isinstance(node.op, ast.USub):
                    return -value
                return not value
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                left = visit(node.left)
                right = visit(node.right)
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                result = visit(node.values[0])
                for child in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not result):
                        return result
                    if isinstance(node.op, ast.Or) and result:
                        return result
                    result = visit(child)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, child in zip(node.ops, node.comparators):
                    right = visit(child)
                    fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                    if fn is None or not fn(left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError() from exc

def analyze_attractions(attractions: list[dict], expression: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError()
    selected = [item for item in attractions if _evaluate(expression, item)]
    ordered = sorted(selected, key=lambda item: (-item['rating'], -item['visits'], item['name']))
    average = round(sum((item['rating'] for item in ordered)) / len(ordered), 2) if ordered else 0.0
    start = (page - 1) * page_size
    return {'total': len(ordered), 'average_rating': average, 'items': ordered[start:start + page_size]}

