import os

def _split_record(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '|\\':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current))
    if len(fields) != 4:
        raise ValueError('invalid record')
    return fields

def parse_article(line: str) -> dict:
    if not isinstance(line, str):
        raise ValueError('invalid record')
    article_id, title, tag_text, vote_text = _split_record(line)
    article_id = article_id.strip()
    title = title.strip()
    if not article_id or not title:
        raise ValueError('missing article data')
    try:
        votes = int(vote_text.strip(), 10)
    except ValueError:
        raise ValueError('invalid votes')
    if votes < 0 or vote_text.strip() == '':
        raise ValueError('invalid votes')
    tags = sorted({tag.strip() for tag in tag_text.split(',') if tag.strip()})
    return {'id': article_id, 'title': title, 'tags': tags, 'votes': votes}

def rank_articles(lines: list[str], limit: int | None=None) -> list[dict]:
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
        raise ValueError('invalid limit')
    merged = {}
    for line in lines:
        article = parse_article(line)
        key = article['id']
        if key not in merged:
            merged[key] = article
        else:
            old = merged[key]
            old['title'] = article['title']
            old['tags'] = sorted(set(old['tags']) | set(article['tags']))
            old['votes'] += article['votes']
    result = sorted(merged.values(), key=lambda x: (-x['votes'], -len(x['tags']), x['id']))
    return result if limit is None else result[:limit]

def build_sync_request(lines: list[str], config: dict | None=None) -> dict:
    if config is not None and 'api_token' in config:
        credential = config['api_token']
    else:
        credential = os.environ.get('KB_SYNC_TOKEN')
    if not isinstance(credential, str) or not credential:
        raise ValueError('missing API token')
    articles = rank_articles(lines)
    return {'method': 'POST', 'path': '/v1/knowledge-base/sync', 'headers': {'Authorization': 'Bearer ' + credential, 'Content-Type': 'application/json'}, 'body': {'articles': articles, 'count': len(articles)}}

