    return {'id': article_id, 'title': title, 'tags': tags, 'votes': votes}

def rank_articles(lines: list[str], limit: int | None=None) -> list[dict]:
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
        raise ValueError('invalid limit')
    merged = {}
    for line in lines:
        article = parse_article(line)
        key = article['id']
        if key not in merged:
            merged[key] = article
        else:
            old = merged[key]
            old['title'] = article['title']
            old['tags'] = sorted(set(old['tags']) | set(article['tags']))
            old['votes'] += article['votes']
