import csv
import io
import math
from decimal import Decimal

def parse_bid_line(line: str) -> dict:
    if not isinstance(line, str):
        raise ValueError('line must be a string')
    try:
        fields = next(csv.reader(io.StringIO(line)))
    except (csv.Error, StopIteration) as exc:
        raise ValueError('invalid record') from exc
    if len(fields) != 5:
        raise ValueError('wrong field count')
    bid_id, participant_id, price_text, quantity_text, timestamp_text = fields
    if not bid_id or not participant_id:
        raise ValueError('empty identifier')
    try:
        price = float(price_text)
        quantity = int(quantity_text)
        timestamp = int(timestamp_text)
    except (ValueError, TypeError) as exc:
        raise ValueError('invalid number') from exc
    if not math.isfinite(price) or price < 0 or quantity <= 0 or (timestamp < 0):
        raise ValueError('invalid value')
    return {'bid_id': bid_id, 'participant_id': participant_id, 'price': price, 'quantity': quantity, 'timestamp': timestamp}

def aggregate_bids(lines: list[str]) -> list[dict]:
    result = []
    seen = set()
    for line in lines:
        bid = parse_bid_line(line)
        if bid['bid_id'] in seen:
            raise ValueError('duplicate bid')
        seen.add(bid['bid_id'])
        result.append(bid)
    result.sort(key=lambda x: (x['price'], x['timestamp'], x['bid_id']))
    return result

def clear_market(requester: dict, market: dict, lines: list[str], demand: int) -> dict:
    if not isinstance(demand, int) or isinstance(demand, bool) or demand < 0:
        raise ValueError('invalid demand')
    if requester['tenant_id'] != market['tenant_id'] and 'market_operator' not in requester['roles']:
        raise PermissionError('not permitted')
    remaining = demand
    accepted = []
    total = Decimal('0')
    marginal = None
    for bid in aggregate_bids(lines):
        if remaining == 0:
            break
        amount = min(remaining, bid['quantity'])
        accepted.append({'bid_id': bid['bid_id'], 'quantity': amount})
        total += Decimal(str(bid['price'])) * amount
        marginal = bid['price']
        remaining -= amount
    return {'market_id': market['market_id'], 'accepted': accepted, 'total_cost': float(total), 'marginal_price': marginal}

