            raise ValueError('invalid priority')
        if status not in {'open', 'done'}:
            raise ValueError('invalid status')
        if status == 'open':
            if room not in grouped:
                grouped[room] = {'tasks': 0, 'minutes': 0, 'priority': 0}
            grouped[room]['tasks'] += 1
            grouped[room]['minutes'] += minutes
            grouped[room]['priority'] = max(grouped[room]['priority'], priority)
