import csv
from datetime import datetime, timedelta
from io import StringIO

def _time(value):
    try:
        d = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except Exception as e:
        raise ValueError('invalid timestamp') from e
    if d.tzinfo is None:
        raise ValueError('invalid timestamp')
    return d

def parse_capacity_feed(text: str) -> list[dict]:
    rows = list(csv.reader(StringIO(text)))
    if not rows or rows[0] != ['shelter_id', 'timestamp', 'available', 'occupied', 'status']:
        raise ValueError('invalid feed')
    out, seen = ([], set())
    for row in rows[1:]:
        if len(row) != 5 or not row[0] or row[4] not in {'open', 'limited', 'closed'}:
            raise ValueError('invalid row')
        _time(row[1])
        try:
            a, o = (int(row[2]), int(row[3]))
        except Exception as e:
            raise ValueError('invalid count') from e
        if a < 0 or o < 0 or (row[0], row[1]) in seen:
            raise ValueError('invalid row')
        seen.add((row[0], row[1]))
        out.append({'shelter_id': row[0], 'timestamp': row[1], 'available': a, 'occupied': o, 'status': row[4]})
    return sorted(out, key=lambda x: (_time(x['timestamp']), x['shelter_id']))

def summarize_capacity(records: list[dict], at: str, window_minutes: int) -> list[dict]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or window_minutes < 0:
        raise ValueError('invalid window')
    end = _time(at)
    start = end - timedelta(minutes=window_minutes)
    latest = {}
    for r in records:
        t = _time(r['timestamp'])
        if start < t <= end and (r['shelter_id'] not in latest or t > _time(latest[r['shelter_id']]['timestamp'])):
            latest[r['shelter_id']] = r
    order = {'open': 0, 'limited': 1, 'closed': 2}
    return sorted([{k: r[k] for k in ('shelter_id', 'available', 'occupied', 'status', 'timestamp')} for r in latest.values()], key=lambda r: (r['available'], order[r['status']], r['shelter_id']))

def reserve_beds(requester: dict, shelters: list[dict], shelter_id: str, booking_id: str, count: int) -> dict:
    if not isinstance(shelter_id, str) or not shelter_id or (not isinstance(booking_id, str)) or (not booking_id) or (not isinstance(count, int)) or isinstance(count, bool) or (count <= 0):
        raise ValueError('invalid reservation')
    shelter = next((s for s in shelters if s.get('id') == shelter_id), None)
    if shelter is None:
        raise KeyError(shelter_id)
    for old in shelter['reservations']:
        if old.get('booking_id') == booking_id:
            return old
    if requester.get('tenant') != shelter.get('tenant') and 'emergency_admin' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    if requester.get('id') != shelter.get('manager_id') and 'emergency_admin' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    if shelter['capacity'] < count:
        raise ValueError('insufficient capacity')
    result = {'booking_id': booking_id, 'requester_id': requester['id'], 'shelter_id': shelter_id, 'count': count}
    shelter['reservations'].append(result)
    shelter['capacity'] -= count
    return result

