import hmac
import json

def process_registration_webhook(payload: bytes, signature: str, shared_key: str, division: str) -> dict:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(shared_key, str)) or (not isinstance(division, str)):
        raise ValueError('invalid input')
    expected = hmac.new(shared_key.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        obj = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(obj, dict) or obj.get('event') != 'registration_results' or (not isinstance(obj.get('registrations'), list)):
        raise ValueError('invalid payload')
    totals = {}
    count = 0
    for item in obj['registrations']:
        if not isinstance(item, dict):
            raise ValueError('invalid registration')
        team = item.get('team')
        item_division = item.get('division')
        points = item.get('points')
        games = item.get('games')
        if not isinstance(team, str) or not team or (not isinstance(item_division, str)) or (not item_division) or (not isinstance(points, int)) or isinstance(points, bool) or (points < 0) or (not isinstance(games, int)) or isinstance(games, bool) or (games <= 0):
            raise ValueError('invalid registration')
