import hashlib
import hmac
import json
import os
from decimal import Decimal, ROUND_HALF_UP

def build_continuity_report(events: list[dict], page: int=1, page_size: int=20, config: dict | None=None) -> dict:
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    if config is not None and (not isinstance(config, dict)):
        raise TypeError('config must be a dictionary')
    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('CONTINUITY_SIGNING_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('a signing key is required')
    groups = {}
    for event in events:
        if not isinstance(event, dict):
            raise TypeError('each event must be a dictionary')
        unit = event.get('unit')
        outcome = event.get('outcome')
        duration = event.get('duration_minutes')
        if not isinstance(unit, str) or not unit:
            raise ValueError('unit must be a non-empty string')
        if outcome not in ('completed', 'failed'):
            raise ValueError('invalid outcome')
        if isinstance(duration, bool) or not isinstance(duration, int):
            raise TypeError('duration_minutes must be an integer')
        if duration < 0:
            raise ValueError('duration_minutes cannot be negative')
        group = groups.setdefault(unit, [0, 0, 0])
        group[0] += 1
        group[1] += outcome == 'completed'
        group[2] += duration
    items = []
    for unit, (count, completed, total) in groups.items():
        average = float((Decimal(total) / Decimal(count)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        rate = float((Decimal(completed) / Decimal(count)).quantize(Decimal('0.0001'), rounding=ROUND_HALF_UP))
        items.append({'unit': unit, 'exercises': count, 'completed': completed, 'total_minutes': total, 'average_minutes': average, 'completion_rate': rate})
    items.sort(key=lambda item: (-item['total_minutes'], item['unit']))
    total_units = len(items)
    total_pages = (total_units + page_size - 1) // page_size if total_units else 0
    payload = {'items': items[(page - 1) * page_size:page * page_size], 'page': page, 'page_size': page_size, 'total_units': total_units, 'total_pages': total_pages}
    raw = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    return {**payload, 'signature': hmac.new(key.encode(), raw, hashlib.sha256).hexdigest()}

