def parse_task_feed(text: str) -> list[dict]:
    lines = [line for line in text.splitlines() if line.strip()]
    header = 'task_id|satellite|priority|window_start|window_end|status|note'
    if not lines or lines[0] != header:
        raise ValueError('invalid header')
    result = []
    for line in lines[1:]:
        try:
            row = next(csv.reader([line], delimiter='|', quotechar='"'))
            if len(row) != 7:
                raise ValueError
            task_id, satellite, priority, start, end, status, note = row
            start = datetime.fromisoformat(start)
            end = datetime.fromisoformat(end)
            priority = int(priority)
            if not task_id or not satellite or status not in {'pending', 'queued', 'complete'} or (end <= start):
                raise ValueError
        except (ValueError, TypeError, StopIteration):
            raise ValueError('invalid record')
        result.append({'task_id': task_id, 'satellite': satellite, 'priority': priority, 'window_start': start, 'window_end': end, 'status': status, 'note': note})
    return result

def select_task_windows(tasks: list[dict], capacity: int) -> list[dict]:
    if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity <= 0:
        raise ValueError('invalid capacity')
    ordered = sorted(tasks, key=lambda x: (-x['priority'], x['window_start'], x['task_id']))
    accepted = []
    for task in ordered:
        if len(accepted) >= capacity:
            break
        conflict = any((a['satellite'] == task['satellite'] and a['window_start'] < task['window_end'] and (task['window_start'] < a['window_end']) for a in accepted))
        if not conflict:
            accepted.append(task)
    return sorted(accepted, key=lambda x: (x['window_start'], x['task_id']))

def render_task_report(tasks: list[dict], generated_at: str, capacity: int=3) -> str:
    chosen = select_task_windows(tasks, capacity)
    esc = lambda value: html.escape(str(value), quote=True)
    articles = []
    for task in chosen:
        articles.append('<article class="task"><h2>' + esc(task['task_id']) + '</h2><dl><dt>Satellite</dt><dd>' + esc(task['satellite']) + '</dd><dt>Priority</dt><dd>' + esc(task['priority']) + '</dd><dt>Window</dt><dd>' + esc(task['window_start']) + ' – ' + esc(task['window_end']) + '</dd><dt>Status</dt><dd>' + esc(task['status']) + '</dd><dt>Note</dt><dd>' + esc(task['note']) + '</dd></dl></article>')
    count = len(chosen)
