def verify_fleet_webhook(payload: bytes, signature: str, signing_key: bytes) -> dict:
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature format')
    digest = signature[7:]
    if any((c not in '0123456789abcdef' for c in digest)):
        raise ValueError('invalid signature format')
    expected = hmac.new(signing_key, payload, hashlib.sha256).hexdigest()
