import html
from datetime import date

def parse_credential(line: str) -> dict:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 6:
        raise ValueError('wrong field count')
    ident, holder, kind, issued, expires, status = fields
    if not ident or not holder or (not kind) or (not issued) or (not expires):
        raise ValueError('empty field')
    try:
        start = date.fromisoformat(issued)
        end = date.fromisoformat(expires)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if end < start or status not in {'issued', 'revoked', 'expired'}:
        raise ValueError('invalid credential')
    return {'id': ident, 'holder': holder, 'type': kind, 'issued': issued, 'expires': expires, 'status': status}

def aggregate_credentials(lines: list[str]) -> dict:
    records = [parse_credential(line) for line in lines if line != '']
    records.sort(key=lambda item: (-date.fromisoformat(item['issued']).toordinal(), item['id']))
    counts = {}
    for record in records:
        counts[record['type']] = counts.get(record['type'], 0) + 1
    counts = {key: counts[key] for key in sorted(counts)}
    return {'records': records, 'by_type': counts, 'active': sum((record['status'] == 'issued' for record in records))}

def render_report(summary: dict, issuer: str, title: str='Credential issuance report') -> str:
    esc = lambda value: html.escape(str(value), quote=True)
    types = ''.join((f'<li>{esc(kind)}: {count}</li>' for kind, count in summary['by_type'].items()))
    rows = ''.join((f"""<tr class="status-{esc(record['status'])}"><td>{esc(record['id'])}</td><td>{esc(record['holder'])}</td><td>{esc(record['type'])}</td><td>{esc(record['issued'])}</td><td>{esc(record['expires'])}</td><td>{esc(record['status'])}</td></tr>""" for record in summary['records']))
    return f"""<section class="credential-report"><h1>{esc(title)}</h1><p class="issuer">Issuer: {esc(issuer)}</p><p class="summary">Total: {len(summary['records'])}; Active: {summary['active']}</p><ul class="types">{types}</ul><table><thead><tr><th>ID</th><th>Holder</th><th>Type</th><th>Issued</th><th>Expires</th><th>Status</th></tr></thead><tbody>{rows}</tbody></table></section>"""

