    try:
        return date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def fetch_leave_requests(employee_id: str, start: str, end: str, token: str) -> list[dict]:
    response = requests.get('https://hr.example.com/api/leave/requests', params={'employee_id': employee_id, 'start': start, 'end': end}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise ValueError('request failed')
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('bad response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('requests'), list):
        raise ValueError('bad response')
    result = []
    for item in data['requests']:
        if not isinstance(item, dict):
            raise ValueError('bad record')
        try:
            values = {key: item[key] for key in ('id', 'employee', 'start', 'end', 'status', 'days')}
        except KeyError as exc:
            raise ValueError('bad record') from exc
        if any((not isinstance(values[key], str) for key in ('id', 'employee', 'start', 'end', 'status'))) or isinstance(values['days'], bool) or (not isinstance(values['days'], int)):
            raise ValueError('bad record')
        first, last = (_day(values['start']), _day(values['end']))
        if last < first or values['days'] != (last - first).days + 1:
            raise ValueError('bad record')
        result.append(values)
    return result

def build_approval_plan(records: list[dict], as_of: str, daily_limit: int=10) -> dict[str, dict]:
    cutoff = _day(as_of)
    if daily_limit <= 0:
        raise ValueError('bad limit')
    groups = {}
    for record in records:
        first, last = (_day(record['start']), _day(record['end']))
        if last < first or record['days'] != (last - first).days + 1:
            raise ValueError('bad record')
        if record['status'] == 'pending' and first >= cutoff:
            groups.setdefault(record['employee'], []).append(record)
    plan = {}
    for employee, items in groups.items():
        items.sort(key=lambda x: (-x.get('priority', 0), x['start'], x['days'], x['id']))
        chosen, total = ([], 0)
        for item in items:
            if total + item['days'] <= daily_limit:
                chosen.append(item['id'])
                total += item['days']
        if chosen:
            plan[employee] = {'approved': chosen, 'days': total}
    return plan

def format_approval_report(plan: dict[str, dict]) -> str:
    lines = []
    count = total = 0
    for employee in sorted(plan):
        item = plan[employee]
        ids = item['approved']
        lines.append(f"{employee}: {(','.join(ids) if ids else 'No requests')} ({item['days']} days)")
        count += len(ids)
        total += item['days']
    lines.append(f'TOTAL: {count} requests, {total} days')
    return '\n'.join(lines)

