import xml.etree.ElementTree as ET

def parse_observations(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'notebook':
        raise ValueError('invalid root')
    result = []
    for node in root:
        if node.tag != 'observation':
            raise ValueError('unexpected element')
        try:
            day = date.fromisoformat(node.attrib['date'])
            site = node.attrib['site'].strip()
            species = node.attrib['species'].strip()
            count = int(node.attrib['count'])
            minutes = int(node.attrib['minutes'])
        except Exception as exc:
            raise ValueError('invalid observation') from exc
        if not site or not species or count < 0 or (minutes <= 0):
            raise ValueError('invalid observation')
        note_nodes = list(node)
        if any((x.tag != 'note' for x in note_nodes)) or len(note_nodes) > 1:
            raise ValueError('invalid note')
        note = ''.join(note_nodes[0].itertext()).strip() if note_nodes else ''
        result.append({'date': day, 'site': site, 'species': species, 'count': count, 'minutes': minutes, 'note': note})
    return sorted(result, key=lambda x: (x['date'], x['site'], x['species']))

def aggregate_observations(records: list[dict], window_days: int=7) -> list[dict]:
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days <= 0:
        raise ValueError('window_days must be positive')
    groups = {}
    for record in records:
        groups.setdefault((record['site'], record['species']), []).append(record)
    output = []
    for (site, species), items in sorted(groups.items()):
        items = sorted(items, key=lambda x: x['date'])
        current = []
        start = None
        for item in items:
            if start is None or item['date'] < start + timedelta(days=window_days):
                if start is None:
                    start = item['date']
                current.append(item)
            else:
                output.append(_window(site, species, current))
                current = [item]
                start = item['date']
        if current:
            output.append(_window(site, species, current))
    return output

