import sqlite3

def list_treatments(conn: sqlite3.Connection, patient_id: int, from_date: str | None=None, to_date: str | None=None, sort_by: str='date', descending: bool=False, limit: int=50, offset: int=0) -> list[dict]:
    if isinstance(patient_id, bool) or not isinstance(patient_id, int):
        raise ValueError('invalid patient_id')
    if sort_by not in {'date', 'minutes', 'pain', 'id'}:
        raise ValueError('invalid sort_by')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    for value in (from_date, to_date):
        if value is not None:
            if not isinstance(value, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value):
                raise ValueError('invalid date')
            try:
                datetime.date.fromisoformat(value)
            except ValueError:
                raise ValueError('invalid date')
    if limit == 0:
        return []
    columns = {'date': 'session_date', 'minutes': 'minutes', 'pain': 'pain_score', 'id': 'id'}
    order_column = columns[sort_by]
    direction = 'DESC' if descending else 'ASC'
    clauses = ['patient_id = ?']
    params = [patient_id]
    if from_date is not None:
        clauses.append('session_date >= ?')
        params.append(from_date)
    if to_date is not None:
        clauses.append('session_date <= ?')
        params.append(to_date)
    query = 'SELECT id, patient_id, session_date, minutes, pain_score, notes FROM treatments WHERE ' + ' AND '.join(clauses) + f' ORDER BY {order_column} {direction}, id ASC LIMIT ? OFFSET ?'
