    blob = pack_events([event('release', 8, tags=['blue', 'web'])])
    cache = {'one': {'version': 7, 'tags': ['web']}, 'two': {'version': 8, 'tags': ['blue']}, 'three': {'version': 2, 'tags': ['db']}}
