import json

def _check_event(x):
    if not isinstance(x, dict):
        raise ValueError('event')
    required = {'key', 'version', 'at', 'ttl', 'tags', 'priority'}
    if set(x) != required:
        raise ValueError('fields')
    if not isinstance(x['key'], str) or not x['key']:
        raise ValueError('key')
    if not isinstance(x['version'], int) or isinstance(x['version'], bool) or x['version'] < 0:
        raise ValueError('version')
    if not isinstance(x['at'], int) or isinstance(x['at'], bool):
        raise ValueError('at')
    if not isinstance(x['ttl'], int) or isinstance(x['ttl'], bool) or x['ttl'] <= 0:
        raise ValueError('ttl')
    if not isinstance(x['priority'], int) or isinstance(x['priority'], bool):
        raise ValueError('priority')
    if not isinstance(x['tags'], list) or any((not isinstance(t, str) for t in x['tags'])):
        raise ValueError('tags')

def pack_events(events: list[dict]) -> bytes:
    if not isinstance(events, list):
        raise TypeError('events')
    for x in events:
        _check_event(x)
    return json.dumps(events, separators=(',', ':'), sort_keys=True).encode('utf-8')

def invalidate_from_blob(blob: bytes, cache: dict[str, dict], now: int) -> list[str]:
    if not isinstance(blob, bytes) or not isinstance(cache, dict) or (not isinstance(now, int)) or isinstance(now, bool):
        raise TypeError('arguments')
    try:
        data = json.loads(blob.decode('utf-8'))
    except Exception as e:
        raise ValueError('payload') from e
    if not isinstance(data, list):
        raise ValueError('payload')
    chosen = {}
    for x in data:
        _check_event(x)
        old = chosen.get(x['key'])
        if old is None or (x['version'], x['at']) > (old['version'], old['at']):
            chosen[x['key']] = x
    matches = {}
    for ek, e in chosen.items():
        if not e['at'] <= now < e['at'] + e['ttl']:
            continue
        etags = set(e['tags'])
        for ck, item in cache.items():
            if not isinstance(ck, str) or not isinstance(item, dict):
                continue
            v, tags = (item.get('version'), item.get('tags'))
            if not isinstance(v, int) or isinstance(v, bool) or (not isinstance(tags, list)) or any((not isinstance(t, str) for t in tags)):
                continue
            if v < e['version'] and (ck == ek or etags.intersection(tags)):
                old = matches.get(ck)
                candidate = (e['priority'], ek)
                if old is None or candidate > old:
                    matches[ck] = candidate
    result = sorted(matches, key=lambda k: (-matches[k][0], k))
    for k in result:
        del cache[k]
    return result

