            raise KeyError(missing)
        result = []
        for info in selected:
            target = os.path.realpath(os.path.join(base, info.filename))
            if os.path.commonpath([base, target]) != base:
                raise ValueError(info.filename)
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
            result.append(target)
        return result

def _split_log_line(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('unfinished escape')
    fields.append(''.join(current))
    if len(fields) != 5:
        raise ValueError('invalid field count')
    return fields

def summarize_maintenance_log(text: str) -> dict[str, object]:
    totals = {}
    total_minutes = 0
    total_records = 0
    for raw in text.splitlines():
        if not raw.strip():
            continue
        timestamp, ride, minutes_text, status, issue = _split_log_line(raw)
        try:
            datetime.fromisoformat(timestamp)
            minutes = int(minutes_text)
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if minutes < 0 or status not in ('COMPLETE', 'OPEN'):
            raise ValueError('invalid record')
        item = totals.setdefault(ride, {'records': 0, 'total_minutes': 0, 'completed': 0, 'open_issues': 0})
        item['records'] += 1
        item['total_minutes'] += minutes
        item['completed'] += status == 'COMPLETE'
        item['open_issues'] += status == 'OPEN' and bool(issue)
        total_records += 1
        total_minutes += minutes
    return {'total_records': total_records, 'total_minutes': total_minutes, 'rides': dict(sorted(totals.items()))}

