import requests
from datetime import date, timedelta

def fetch_inventory(warehouse_id: str, min_quantity: int=0) -> list[dict]:
    response = requests.get('https://api.foodbank.example/v1/inventory', params={'warehouse': warehouse_id, 'min_qty': min_quantity}, headers={'Accept': 'application/json'}, timeout=5)
    if response.status_code != 200:
        raise RuntimeError(f'inventory request failed: {response.status_code}')
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('items'), list):
        raise ValueError('response items must be a list')
    return data['items']

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc

def summarize_inventory(items: list[dict], as_of: str) -> dict:
    start = _day(as_of)
    end = start + timedelta(days=7)
    categories = {}
    total = 0
    window = 0
    for item in items:
        quantity = item['quantity']
        if quantity < 0:
            raise ValueError('negative quantity')
        expires = _day(item['expires'])
        total += quantity
        categories[item['category']] = categories.get(item['category'], 0) + quantity
        if start <= expires <= end:
            window += quantity
    return {'total_quantity': total, 'by_category': dict(sorted(categories.items())), 'expiring_within_7_days': window}

def dispatch_plan(items: list[dict], demands: list[dict], as_of: str) -> dict:
    start = _day(as_of)
    lots = []
    for item in items:
        if item['quantity'] < 0:
            raise ValueError('negative quantity')
        expires = _day(item['expires'])
        if expires >= start:
            lots.append({'item': item, 'expires': expires, 'remaining': item['quantity']})
    allocations = []
    shortages = []
    for demand in demands:
        quantity = demand['quantity']
        if quantity < 0:
            raise ValueError('negative quantity')
        if quantity == 0:
            continue
        candidates = sorted((lot for lot in lots if lot['item']['sku'] == demand['sku'] and lot['remaining'] > 0), key=lambda lot: (lot['expires'], lot['item']['location'], lot['item']['lot_id']))
        remaining = quantity
        for lot in candidates:
            used = min(remaining, lot['remaining'])
            if used:
                item = lot['item']
                allocations.append({'sku': demand['sku'], 'lot_id': item['lot_id'], 'location': item['location'], 'quantity': used})
                lot['remaining'] -= used
                remaining -= used
            if remaining == 0:
                break
        if remaining:
            shortages.append({'sku': demand['sku'], 'quantity': remaining})
    return {'allocations': allocations, 'shortages': shortages}

