    if not isinstance(brand, str) or not brand:
        raise ValueError('brand must be a nonempty string')
    if not isinstance(api_key, str) or not api_key:
        raise ValueError('api_key must be a nonempty string')
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not -1 <= min_score <= 1):
        raise ValueError('invalid min_score')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    response = requests.get('https://sentiment.example.com/v1/mentions', params={'brand': brand}, headers={'Authorization': 'Bearer ' + api_key, 'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError('sentiment service returned an error')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('mentions'), list):
        raise ValueError('invalid response')
    grouped = {}
    for mention in payload['mentions']:
        if not isinstance(mention, dict):
            continue
        source = mention.get('source')
        score = mention.get('score')
        if not isinstance(source, str) or not source or isinstance(score, bool) or (not isinstance(score, (int, float))) or (not -1 <= score <= 1) or (score < min_score):
