import os
import hashlib
import tempfile
from datetime import datetime, timedelta

def _prepare(records, include_tags):
    if any((not isinstance(x, str) for x in include_tags)):
        raise ValueError('invalid tags')
    prepared = []
    for record in records:
        try:
            date = record['date']
            start = record['start']
            duration = record['duration']
            title = record['title']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(date, str) or not isinstance(start, str) or (not isinstance(title, str)) or (not title):
            raise ValueError('invalid record')
        try:
            begin = datetime.strptime(date + ' ' + start, '%Y-%m-%d %H:%M')
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if type(duration) is not int or duration <= 0 or duration > 1440:
            raise ValueError('invalid duration')
        location = record.get('location', '')
        uid = record.get('uid')
        tags = record.get('tags', [])
        if not isinstance(location, str) or ('location' in record and (not location)):
            raise ValueError('invalid location')
        if uid is not None and (not isinstance(uid, str) or not uid):
            raise ValueError('invalid uid')
        if not isinstance(tags, (list, tuple)) or any((not isinstance(x, str) for x in tags)):
            raise ValueError('invalid tags')
        if include_tags and (not any((x in tags for x in include_tags))):
            continue
        end = begin + timedelta(minutes=duration)
        if uid is None:
            uid = f'{date}-{start}-{title}-{location}'
        prepared.append((begin, title, location, uid, end))
    prepared.sort(key=lambda x: (x[0], x[1].casefold(), x[2].casefold(), x[3]))
    return prepared

def _escape(value):
    return value.replace('\\', '\\\\').replace(';', '\\;').replace(',', '\\,').replace('\r', '').replace('\n', '\\n')

def render_calendar(records, include_tags=()):
    events = _prepare(records, include_tags)
    lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Community Calendar//EN', 'CALSCALE:GREGORIAN']
    for begin, title, location, uid, end in events:
        lines.extend(['BEGIN:VEVENT', 'UID:' + _escape(uid), 'DTSTART:' + begin.strftime('%Y%m%dT%H%M%S'), 'DTEND:' + end.strftime('%Y%m%dT%H%M%S'), 'SUMMARY:' + _escape(title), 'LOCATION:' + _escape(location), 'END:VEVENT'])
    lines.append('END:VCALENDAR')
    return '\r\n'.join(lines) + '\r\n'

def export_calendar(records, destination, include_tags=()):
    content = render_calendar(records, include_tags)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            handle.write(content)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return content.count('BEGIN:VEVENT\r\n')

