import csv
import os
import tempfile

def build_reconciliation_report(records: list[tuple[str, float, float]]) -> str:
    totals = {}
    for record in records:
        try:
            mine, tonnes, grade = record
        except (TypeError, ValueError):
            raise ValueError('invalid record')
        if not isinstance(mine, str) or not mine or isinstance(tonnes, bool) or (not isinstance(tonnes, (int, float))) or (tonnes <= 0) or isinstance(grade, bool) or (not isinstance(grade, (int, float))) or (grade < 0):
            raise ValueError('invalid record')
        total, weighted = totals.get(mine, (0.0, 0.0))
        totals[mine] = (total + tonnes, weighted + tonnes * grade)
    fd, path = tempfile.mkstemp(suffix='.csv')
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['mine', 'total_tonnes', 'average_grade'])
            for mine in sorted(totals):
                total, weighted = totals[mine]
                average = weighted / total if total else 0.0
                writer.writerow([mine, f'{total:.2f}', f'{average:.2f}'])
        with open(path, newline='') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

