import html
from datetime import date, timedelta

def _split(line):
    parts, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            parts.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    parts.append(''.join(current))
    return parts

def _valid_date(value):
    try:
        parsed = date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def parse_upgrade_feed(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        fields = _split(line)
        if len(fields) != 6 or not fields[0] or (not fields[1]):
            raise ValueError('invalid record')
        try:
            points = int(fields[3])
        except ValueError:
            raise ValueError('invalid points')
        if points < 0 or fields[4] not in {'approved', 'denied', 'pending'}:
            raise ValueError('invalid record')
        _valid_date(fields[5])
        result.append({'member': fields[0], 'flight': fields[1], 'cabin': fields[2], 'points': points, 'status': fields[4], 'date': fields[5]})
    return result

def summarize_upgrades(events: list[dict], as_of: str) -> list[dict]:
    end = _valid_date(as_of)
    start = end - timedelta(days=30)
    groups = {}
    required = {'member', 'flight', 'cabin', 'points', 'status', 'date'}
    for event in events:
        if set(event) != required or not isinstance(event['points'], int) or (not isinstance(event['date'], str)):
            raise ValueError('invalid event')
        when = _valid_date(event['date'])
        if when <= start or when > end:
            continue
        if event['status'] not in {'approved', 'denied', 'pending'} or event['points'] < 0:
            raise ValueError('invalid event')
        item = groups.setdefault(event['member'], {'count': 0, 'points': 0, 'latest': event['date']})
        item['latest'] = max(item['latest'], event['date'])
        if event['status'] == 'approved':
            item['count'] += 1
            item['points'] += event['points']
    result = []
    for member, item in groups.items():
        if not item['count']:
            continue
        points = item['points']
        tier = 'Platinum' if points >= 50000 else 'Gold' if points >= 25000 else 'Silver' if points >= 10000 else 'Standard'
        result.append({'member': member, 'approved_count': item['count'], 'approved_points': points, 'latest_date': item['latest'], 'tier': tier})
    return sorted(result, key=lambda x: (-x['approved_points'], -x['approved_count'], x['member']))

def render_upgrade_report(summary: list[dict], title: str) -> str:
    rows = ''.join(('<tr><td>' + html.escape(str(x['member'])) + '</td><td>' + html.escape(str(x['tier'])) + '</td><td>' + str(x['approved_count']) + '</td><td>' + str(x['approved_points']) + '</td><td>' + html.escape(str(x['latest_date'])) + '</td></tr>' for x in summary))
    return '<section><h1>' + html.escape(title) + '</h1><table><thead><tr><th>Member</th><th>Tier</th><th>Approved upgrades</th><th>Points</th><th>Latest date</th></tr></thead><tbody>' + rows + '</tbody></table></section>'

