from pathlib import Path

def write_trip_receipt(base_dir: str, relative_name: str, trips: list[dict], page: int=1, page_size: int=10) -> str:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    completed = []
    for trip in trips:
        if not isinstance(trip, dict) or set(trip) != {'id', 'fare', 'distance', 'status'}:
            raise ValueError('invalid trip')
        if not isinstance(trip['id'], str) or not trip['id']:
            raise ValueError('invalid trip')
        if not isinstance(trip['fare'], (int, float)) or isinstance(trip['fare'], bool) or trip['fare'] < 0:
            raise ValueError('invalid trip')
        if not isinstance(trip['distance'], (int, float)) or isinstance(trip['distance'], bool) or trip['distance'] < 0:
            raise ValueError('invalid trip')
        if trip['status'] not in ('completed', 'cancelled'):
            raise ValueError('invalid trip')
        if trip['status'] == 'completed':
            completed.append(trip)
    completed.sort(key=lambda item: (-Decimal(str(item['fare'])), item['id']))
    start = (page - 1) * page_size
    selected = completed[start:start + page_size]
    total = sum((Decimal(str(item['fare'])) for item in selected), Decimal('0'))
    total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    average = (total / len(selected) if selected else Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    result = {'trip_count': len(selected), 'total_fare': float(total), 'average_fare': float(average), 'trips': selected}
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    if target != base and base not in target.parents:
        raise ValueError('invalid path')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', encoding='utf-8') as handle:
        json.dump(result, handle, ensure_ascii=False)
    return str(target)

