import sqlite3

def list_inventory(conn: sqlite3.Connection, search: str='', category: str | None=None, sort_by: str='name', descending: bool=False, limit: int=20, offset: int=0) -> list[dict]:
    if not isinstance(search, str):
        raise ValueError('search must be a string')
    if category is not None and (not isinstance(category, str)):
        raise ValueError('category must be a string or None')
    if sort_by not in {'name', 'quantity', 'unit_price', 'id'}:
        raise ValueError('invalid sort column')
    if not isinstance(descending, bool):
        raise ValueError('descending must be a boolean')
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('limit must be a nonnegative integer')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('offset must be a nonnegative integer')
    clauses = ['lower(name) LIKE lower(?)']
    params = [f'%{search}%']
    if category is not None:
        clauses.append('category = ?')
        params.append(category)
    direction = 'DESC' if descending else 'ASC'
    sql = 'SELECT id, name, category, quantity, unit_price FROM inventory WHERE ' + ' AND '.join(clauses)
    sql += f' ORDER BY {sort_by} {direction}, id ASC LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    rows = conn.execute(sql, params).fetchall()
    return [dict(zip(('id', 'name', 'category', 'quantity', 'unit_price'), row)) for row in rows]

