import hmac
import json

import pytest

from solution import verify_asset_webhook


def make_signature(secret, body):
    return hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()


def test_valid_webhook_sorts_assets_by_name():
    secret = "brand-hook"
    body = json.dumps({
        "brand": "Acme",
        "assets": [
            {"name": "wordmark", "url": "https://cdn.example/wordmark.svg"},
            {"name": "icon", "url": "https://cdn.example/icon.svg"},
        ],
    })
    signature = make_signature(secret, body)

    result = verify_asset_webhook(secret, body, signature)

    assert result == {
        "brand": "Acme",
        "assets": [
            {"name": "icon", "url": "https://cdn.example/icon.svg"},
            {"name": "wordmark", "url": "https://cdn.example/wordmark.svg"},
        ],
    }


def test_wrong_signature_is_rejected():
    secret = "brand-hook"
    body = json.dumps({"brand": "Acme", "assets": []})

    with pytest.raises(ValueError):
        verify_asset_webhook(secret, body, "0" * 64)


def test_malformed_json_is_rejected():
    secret = "brand-hook"
    body = '{"brand":"Acme","assets":['

    with pytest.raises(ValueError):
        verify_asset_webhook(secret, body, make_signature(secret, body))


def test_missing_brand_is_rejected():
    secret = "brand-hook"
    body = json.dumps({"assets": []})

    with pytest.raises(ValueError):
        verify_asset_webhook(secret, body, make_signature(secret, body))


