import csv
import json
import os
import tempfile

def parse_events(data: str) -> list[tuple[int, str, str, str]]:
    rows = list(csv.reader(data.splitlines()))
    rows = [row for row in rows if row]
    if not rows or rows[0] != ['time', 'vehicle', 'zone', 'event']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        try:
            time = int(row[0])
        except ValueError:
            raise ValueError('invalid timestamp')
        if time < 0 or not row[1] or (not row[2]) or (row[3] not in ('ENTER', 'EXIT')):
            raise ValueError('invalid event')
        result.append((time, row[1], row[2], row[3]))
    return result

def summarize_occupancy(events: list[tuple[int, str, str, str]], capacities: dict[str, int]) -> list[dict[str, object]]:
    for value in capacities.values():
        if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
            raise ValueError('invalid capacity')
    occupancy = {zone: 0 for zone in capacities}
    stats = {zone: [0, 0, 0] for zone in capacities}
    active = {}
    previous = -1
    for time, vehicle, zone, action in events:
        if time < previous:
            raise ValueError('timestamps out of order')
        previous = time
        if zone not in capacities:
            raise ValueError('unknown zone')
        if action == 'ENTER':
            if vehicle in active:
                raise ValueError('vehicle already present')
            occupancy[zone] += 1
            if occupancy[zone] > capacities[zone]:
                raise ValueError('capacity exceeded')
            active[vehicle] = zone
            stats[zone][0] += 1
            stats[zone][2] = max(stats[zone][2], occupancy[zone])
        else:
            if vehicle not in active or active[vehicle] != zone:
                raise ValueError('invalid exit')
            del active[vehicle]
            occupancy[zone] -= 1
            stats[zone][1] += 1
    return [{'zone': z, 'capacity': capacities[z], 'entries': stats[z][0], 'exits': stats[z][1], 'peak': stats[z][2], 'final': occupancy[z]} for z in sorted(capacities)]

def export_occupancy(data: str, capacities: dict[str, int], destination: str) -> list[dict[str, object]]:
    summary = summarize_occupancy(parse_events(data), capacities)
    document = json.dumps({'zones': summary}, indent=2) + '\n'
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as stream:
            stream.write(document)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return summary

