import sqlite3

def parse_alert_feed(text: str) -> list[dict]:
    result = []
    for line_no, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        fields = []
        current = []
        escaped = False
        for ch in line:
            if escaped:
                current.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        if escaped:
            raise ValueError(f'invalid record on line {line_no}')
        fields.append(''.join(current))
        if len(fields) != 7:
            raise ValueError(f'invalid record on line {line_no}')
        try:
            amount = float(fields[3])
            score = float(fields[4])
        except ValueError:
            raise ValueError(f'invalid number on line {line_no}')
        result.append({'id': fields[0], 'card_id': fields[1], 'event_time': fields[2], 'amount': amount, 'score': score, 'status': fields[5], 'reason': fields[6]})
    return result

def rank_fraud_alerts(conn: sqlite3.Connection, card_id: str | None=None, statuses: tuple[str, ...]=(), min_score: float=0.0, order_by: str='score', descending: bool=True) -> list[dict]:
    allowed = {'id', 'card_id', 'event_time', 'amount', 'score', 'card_total'}
    if order_by not in allowed:
        raise ValueError('invalid order_by')
    clauses = ['score >= ?']
    values = [min_score]
    if card_id is not None:
        clauses.append('card_id = ?')
        values.append(card_id)
    if statuses:
        clauses.append('status in (' + ','.join(('?' for _ in statuses)) + ')')
        values.extend(statuses)
    rows = conn.execute('select id, card_id, event_time, amount, score, status, reason from alerts where ' + ' and '.join(clauses), values).fetchall()
    totals = {}
    for row in rows:
        totals[row[1]] = totals.get(row[1], 0) + row[3]
    data = []
    for row in rows:
        band = 'critical' if row[4] >= 0.9 else 'high' if row[4] >= 0.75 else 'medium' if row[4] >= 0.5 else 'low'
        data.append({'id': row[0], 'card_id': row[1], 'event_time': row[2], 'amount': row[3], 'score': row[4], 'status': row[5], 'reason': row[6], 'risk_band': band, 'card_total': round(totals[row[1]], 2)})
    data.sort(key=lambda x: x['id'])
    data.sort(key=lambda x: x[order_by], reverse=descending)
    for i, item in enumerate(data):
        item['rank'] = 1 + next((j for j, prior in enumerate(data[:i]) if prior[order_by] == item[order_by]), i)
    return data

