import json
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _money(value):
    try:
        number = Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid price')
    if not number.is_finite() or number < 0:
        raise ValueError('invalid price')
    return number.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

def _text_money(value):
    return format(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')

def calculate_invoice(order: dict, config: dict) -> dict:
    if not isinstance(order.get('order_id'), str) or not isinstance(order.get('customer_state'), str):
        raise ValueError('invalid order')
    state = order['customer_state']
    if state not in config.get('tax_rates', {}):
        raise ValueError('unknown customer state')
    if 'signing_key' not in config:
        raise ValueError('signing_key is required')
    try:
        rate = Decimal(str(config['tax_rates'][state]))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid tax rate')
    exempt = set(config.get('exempt_categories', []))
    lines = []
    subtotal = Decimal('0')
    tax_total = Decimal('0')
    for item in order.get('items', []):
        for field in ('sku', 'category', 'unit_price', 'quantity', 'taxable'):
            if field not in item:
                raise ValueError('missing item field')
