            raise ValueError('invalid quantity')
        unit = _money(item['unit_price'])
        line_subtotal = unit * item['quantity']
        taxable = bool(item['taxable']) and item['category'] not in exempt
        line_rate = rate if taxable else Decimal('0')
        line_tax = (line_subtotal * line_rate).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        subtotal += line_subtotal
        tax_total += line_tax
        lines.append({'sku': item['sku'], 'category': item['category'], 'quantity': item['quantity'], 'unit_price': _text_money(unit), 'subtotal': _text_money(line_subtotal), 'tax_rate': format(line_rate, '.4f'), 'tax': _text_money(line_tax), 'taxable': taxable})
