import hashlib
import hmac
import os

def register_partner(partner_id: str, api_secret: str) -> dict:
    if not isinstance(partner_id, str) or not partner_id or (not isinstance(api_secret, str)) or (not api_secret):
        raise ValueError('invalid partner')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, 100000)
    return {'id': partner_id, 'salt': salt.hex(), 'digest': digest.hex()}

def verify_partner(record: dict, api_secret: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(api_secret, str):
            return False
        salt = bytes.fromhex(record['salt'])
        expected = bytes.fromhex(record['digest'])
        actual = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def calculate_commissions(events: list[dict], partners: list[dict], window_days: int=7) -> list[dict]:
    if not isinstance(window_days, int) or window_days < 0:
        raise ValueError('invalid window')
    ids = set()
    for p in partners:
        if not isinstance(p, dict) or not isinstance(p.get('id'), str) or p['id'] in ids:
            raise ValueError('invalid partners')
        ids.add(p['id'])
    clicks = {}
    conversions = set()
    totals = {p: [0, 0] for p in ids}
    for e in events:
        if not isinstance(e, dict):
            raise ValueError('invalid event')
        if e.get('type') == 'click':
            if not all((k in e for k in ('id', 'partner', 'ts'))) or not isinstance(e['id'], str) or (not isinstance(e['partner'], str)) or (not isinstance(e['ts'], int)):
                raise ValueError('invalid click')
            if e['id'] in clicks:
                raise ValueError('duplicate click')
            clicks[e['id']] = (e['partner'], e['ts'])
        elif e.get('type') == 'conversion':
            if not all((k in e for k in ('click_id', 'ts', 'amount_cents', 'rate_bps'))) or not isinstance(e['click_id'], str) or (not all((isinstance(e[k], int) for k in ('ts', 'amount_cents', 'rate_bps')))):
                raise ValueError('invalid conversion')
            if e['click_id'] in conversions or e['click_id'] not in clicks:
                continue
            partner, start = clicks[e['click_id']]
            if partner not in ids or e['ts'] < start or e['ts'] > start + window_days * 86400 or (e['amount_cents'] < 0) or (e['rate_bps'] < 0):
                continue
            conversions.add(e['click_id'])
            totals[partner][0] += e['amount_cents'] * e['rate_bps'] // 10000
            totals[partner][1] += 1
    result = [{'partner': p, 'total_cents': v[0], 'conversions': v[1]} for p, v in totals.items() if v[0] > 0]
    return sorted(result, key=lambda x: (-x['total_cents'], -x['conversions'], x['partner']))

