import hashlib
import hmac
import os
from datetime import date

def make_reviewer_credential(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + value.hex()

def verify_reviewer_credential(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str):
        return False
    try:
        salt_text, value_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
    except (ValueError, TypeError):
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def schedule_permits(permits, reviewer_credentials, reviewer_passwords, as_of):
    cutoff = _day(as_of)
    zones = {'R1': 25, 'R2': 50, 'C1': 75, 'I1': 100}
    seen = set()
    result = []
    for p in permits:
        required = {'id', 'applicant', 'reviewer', 'zone', 'valuation', 'submitted', 'status'}
        if not isinstance(p, dict) or set(p) != required:
            raise ValueError('invalid permit')
        if not isinstance(p['id'], str) or not p['id'] or p['id'] in seen:
            raise ValueError('duplicate or invalid id')
        seen.add(p['id'])
        submitted = _day(p['submitted'])
        if not isinstance(p['valuation'], int) or isinstance(p['valuation'], bool) or p['valuation'] < 0:
            raise ValueError('invalid valuation')
        if p['zone'] not in zones or p['status'] not in {'pending', 'closed'}:
            raise ValueError('invalid permit value')
        if p['status'] != 'pending' or submitted > cutoff:
            continue
        name = p['reviewer']
        if name not in reviewer_credentials or name not in reviewer_passwords:
            continue
        if not verify_reviewer_credential(reviewer_credentials[name], reviewer_passwords[name]):
            continue
        priority = zones[p['zone']]
        if p['valuation'] >= 1000000:
            priority += 20
        if (cutoff - submitted).days >= 30:
            priority += 10
        result.append({k: p[k] for k in ('id', 'applicant', 'reviewer', 'zone', 'valuation', 'submitted')} | {'priority': priority})
    result.sort(key=lambda x: (-x['priority'], x['submitted'], -x['valuation'], x['id']))
    return result

