import math
import xml.etree.ElementTree as ET

def parse_ad_schedule(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'schedule':
        raise ValueError('invalid root')
    result = []
    ids = set()
    for node in root:
        if node.tag != 'ad':
            raise ValueError('invalid child')
        try:
            ident = node.attrib['id']
            start = float(node.attrib['start'])
            duration = float(node.attrib['duration'])
            campaign = node.attrib['campaign']
            status = node.attrib['status']
        except (KeyError, ValueError) as exc:
            raise ValueError('invalid ad') from exc
        if not ident or not campaign or status not in {'active', 'paused'}:
            raise ValueError('invalid ad')
        if not math.isfinite(start) or not math.isfinite(duration) or start < 0 or (duration <= 0):
            raise ValueError('invalid ad')
        if ident in ids:
            raise ValueError('duplicate id')
        ids.add(ident)
        result.append({'id': ident, 'start': start, 'duration': duration, 'campaign': campaign, 'status': status})
    return result

def summarize_ad_schedule(ads: list[dict], episode_duration: float) -> dict:
    if not math.isfinite(episode_duration) or episode_duration < 0:
        raise ValueError('invalid episode duration')
    active = []
    for ad in ads:
        if ad['status'] == 'active':
            if ad['start'] < 0 or ad['start'] + ad['duration'] > episode_duration:
                raise ValueError('ad outside episode')
            active.append(ad)
    totals = {}
    for ad in active:
        totals[ad['campaign']] = totals.get(ad['campaign'], 0.0) + ad['duration']
    ordered = {name: round(totals[name], 2) for name in sorted(totals)}
    return {'count': len(active), 'total_duration': round(sum((ad['duration'] for ad in active)), 2), 'by_campaign': ordered}

