import hashlib
import hmac
import os

def create_review(user_id: str, password: str, permissions: list[str]) -> dict:
    if not isinstance(user_id, str) or not isinstance(password, str):
        raise ValueError('invalid identity')
    user_id = user_id.strip()
    if not user_id or not password:
        raise ValueError('invalid identity')
    if not isinstance(permissions, (list, tuple)):
        raise ValueError('invalid permissions')
    cleaned = []
    for permission in permissions:
        if not isinstance(permission, str) or not permission.strip():
            raise ValueError('invalid permissions')
        cleaned.append(permission.strip())
    cleaned = sorted(set(cleaned))
    score = sum((permission in {'admin', 'billing', 'directory.write'} for permission in cleaned))
    level = 'high' if score >= 2 else 'medium' if score == 1 else 'low'
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    credential = salt.hex() + ':' + digest.hex()
    return {'user_id': user_id, 'credential': credential, 'permissions': cleaned, 'risk_score': score, 'risk_level': level}

def check_password(review: dict, password: str) -> bool:
    if not isinstance(password, str) or not isinstance(review, dict):
        return False
    credential = review.get('credential')
    if not isinstance(credential, str):
        return False
    try:
        salt_hex, digest_hex = credential.split(':')
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_reviews(reviews: list[dict], page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid paging')
    counts = {'high': 0, 'medium': 0, 'low': 0}
    for review in reviews:
        if review.get('risk_level') in counts:
            counts[review['risk_level']] += 1
    ordered = sorted(reviews, key=lambda item: (-item['risk_score'], item['user_id']))
    total = len(ordered)
    pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    return {'total': total, 'counts': counts, 'page': page, 'page_size': page_size, 'pages': pages, 'reviews': ordered[start:start + page_size]}

