import hashlib
import hmac
import re

def _fields(body):
    out = []
    cur = []
    i = 0
    while i < len(body):
        ch = body[i]
        if ch == '\\':
            i += 1
            if i == len(body) or body[i] not in '\\|':
                raise ValueError('bad escape')
            cur.append(body[i])
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
        i += 1
    out.append(''.join(cur))
    return out

def parse_campaign_feed(text: str, secret: str, now: int) -> list[dict]:
    result = []
    seen = set()
    key = secret.encode('utf-8')
    for raw in text.splitlines():
        if not raw.strip():
            continue
        if '|' not in raw:
            raise ValueError('missing separator')
        sig, body = raw.split('|', 1)
        if not re.fullmatch('[0-9a-f]{64}', sig):
            raise ValueError('bad signature')
        expected = hmac.new(key, body.encode('utf-8'), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            raise ValueError('bad signature')
        fields = _fields(body)
        if len(fields) != 6:
            raise ValueError('wrong field count')
        cid, ts, platform, priority, audience, payload = fields
        if not re.fullmatch('[A-Za-z0-9_-]+', cid) or cid in seen:
            raise ValueError('bad campaign id')
        if platform not in ('ios', 'android') or not payload:
            raise ValueError('bad campaign')
        try:
            timestamp = int(ts)
            prio = int(priority)
            size = int(audience)
        except Exception as exc:
            raise ValueError('bad number') from exc
        if str(timestamp) != ts or str(prio) != priority or str(size) != audience:
            raise ValueError('bad number')
        if not 0 <= prio <= 9 or size < 0 or (not now - 3600 <= timestamp <= now + 86400):
            raise ValueError('out of range')
        seen.add(cid)
        result.append({'campaign_id': cid, 'timestamp': timestamp, 'platform': platform, 'priority': prio, 'audience': size, 'payload': payload})
    return result

def summarize_campaigns(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        key = (record['platform'], record['priority'])
        if key not in groups:
            groups[key] = {'platform': key[0], 'priority': key[1], 'campaigns': 0, 'audience': 0, 'earliest_timestamp': record['timestamp']}
        group = groups[key]
        group['campaigns'] += 1
        group['audience'] += record['audience']
        group['earliest_timestamp'] = min(group['earliest_timestamp'], record['timestamp'])
    return sorted(groups.values(), key=lambda x: (-x['priority'], -x['audience'], x['platform']))

