import operator

def _evaluate(node, names):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float, bool)) or node.value is None:
            return node.value
        raise ValueError()
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError()
        return names[node.id]
