SECRET = b"archive-key"


def make_payload(items):
    return json.dumps({"items": items}, separators=(",", ":"))


def digest(payload, secret=SECRET):
    return hmac.new(secret, payload.encode(), hashlib.sha256).hexdigest()


def item(identifier, title, collection, year, words, **extra):
    value = {"id": identifier, "title": title, "collection": collection, "year": year, "words": words}
    value.update(extra)
    return value


def test_filters_sorts_and_returns_requested_fields():
    payload = make_payload([
        item(3, "Zeta", "letters", 1900, 20, note="x"),
        item(2, "alpha", "letters", 1900, 30),
        item(1, "Beta", "other", 2000, 10),
        item(4, "Alpha", "letters", 1910, 40),
    ])
    result = catalogue_page(payload, digest(payload), SECRET, "letters", 1, 10)
    assert result == {
        "total": 3,
        "page": 1,
        "page_size": 10,
        "pages": 1,
        "items": [
            {"id": 4, "title": "Alpha", "collection": "letters", "year": 1910, "words": 40},
            {"id": 2, "title": "alpha", "collection": "letters", "year": 1900, "words": 30},
            {"id": 3, "title": "Zeta", "collection": "letters", "year": 1900, "words": 20},
        ],
    }


def test_pagination_and_tie_breaking():
    records = [item(5, "Same", "c", 2000, 1), item(2, "same", "c", 2000, 2), item(9, "Earlier", "c", 1999, 3)]
    payload = make_payload(records)
    result = catalogue_page(payload, digest(payload), SECRET, None, 2, 2)
    assert result == {
        "total": 3,
        "page": 2,
        "page_size": 2,
        "pages": 2,
        "items": [{"id": 9, "title": "Earlier", "collection": "c", "year": 1999, "words": 3}],
    }


def test_empty_filter_has_zero_pages():
    payload = make_payload([])
    assert catalogue_page(payload, digest(payload), SECRET, "missing", 1, 5) == {
        "total": 0, "page": 1, "page_size": 5, "pages": 0, "items": []
    }


def test_digest_mismatch_is_rejected():
    payload = make_payload([item(1, "A", "c", 1, 2)])
    with pytest.raises(ValueError):
        catalogue_page(payload, "0" * 64, SECRET, None, 1, 10)


