import hashlib
import hmac
import json

def catalogue_page(payload: str, digest: str, secret: bytes, collection: str | None, page: int, page_size: int) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not isinstance(digest, str) or len(digest) != 64 or any((c not in '0123456789abcdef' for c in digest)):
        raise ValueError('invalid digest')
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, digest):
        raise ValueError('digest mismatch')
    try:
        document = json.loads(payload)
    except (TypeError, ValueError):
        raise ValueError('invalid JSON')
    if not isinstance(document, dict) or not isinstance(document.get('items'), list):
        raise ValueError('invalid document')
    records = []
    for raw in document['items']:
        if not isinstance(raw, dict):
            raise ValueError('invalid item')
        required = ('id', 'title', 'collection', 'year', 'words')
        if any((key not in raw for key in required)):
            raise ValueError('invalid item')
        if not isinstance(raw['id'], int) or isinstance(raw['id'], bool) or (not isinstance(raw['title'], str)) or (not isinstance(raw['collection'], str)) or (not isinstance(raw['year'], int)) or isinstance(raw['year'], bool) or (not isinstance(raw['words'], int)) or isinstance(raw['words'], bool) or (raw['words'] < 0):
            raise ValueError('invalid item')
        if collection is None or raw['collection'] == collection:
            records.append({key: raw[key] for key in required})
    records.sort(key=lambda record: (-record['year'], record['title'].casefold(), record['id']))
    total = len(records)
    start = (page - 1) * page_size
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': (total + page_size - 1) // page_size, 'items': records[start:start + page_size]}

