import base64
import hashlib
import hmac
import os

def create_feature_config(flags: dict[str, bool], admin_pin: str) -> dict:
    if not admin_pin:
        raise ValueError('admin_pin must not be empty')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', admin_pin.encode(), salt, iterations)
    stored = f'{iterations}${base64.b64encode(salt).decode()}${base64.b64encode(digest).decode()}'
    return {'enabled': sorted((name for name, enabled in flags.items() if enabled)), 'admin_pin': stored}

def is_feature_enabled(config: dict, feature: str, admin_pin: str) -> bool:
    if not admin_pin or feature not in config.get('enabled', []):
        return False
    try:
        iterations_text, salt_text, digest_text = config['admin_pin'].split('$')
        iterations = int(iterations_text)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
    except (KeyError, ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', admin_pin.encode(), salt, iterations)
    return hmac.compare_digest(actual, expected)

