    try:
        tree = ast.parse(rule, mode='eval')
        selected = []
        for record in records:
            variables = {name: record[name] for name in ('wind_speed', 'vibration', 'temperature')}
            if _value(tree.body, variables):
                priority = record['vibration'] + max(0, record['temperature'] - 70)
                selected.append((priority, record['id']))
        return [item[1] for item in sorted(selected, key=lambda item: -item[0])]
