        group = groups[key]
        group['total'] += number
        group['count'] += 1
        group['last_date'] = max(group['last_date'], raw_date)
        group['researchers'].add(values['researcher'])
    result = []
    for group in groups.values():
        result.append({'grant': group['grant'], 'category': group['category'], 'total': group['total'].quantize(Decimal('0.01')), 'count': group['count'], 'last_date': group['last_date'], 'researchers': sorted(group['researchers'])})
    return sorted(result, key=lambda x: (-x['total'], x['grant'], x['category']))

