        rows.append('<tr>' + ''.join((f'<td>{escape(str(cell))}</td>' for cell in cells)) + '</tr>')
    headers = ['Grant', 'Category', 'Total', 'Count', 'Last date', 'Researchers']
    head = '<tr>' + ''.join((f'<th>{x}</th>' for x in headers)) + '</tr>'
    return f"""<div class="report"><h1>{escape(title)}</h1><table><thead>{head}</thead><tbody>{''.join(rows)}</tbody></table></div>"""

