import xml.etree.ElementTree as ET

def segment_subscribers(xml: str, segment: str, min_opens: int=0, page: int=1, page_size: int=50) -> list[dict[str, object]]:
    if min_opens < 0 or page < 1 or page_size < 1 or (page_size > 1000):
        raise ValueError('invalid paging or threshold')
    try:
        root = ET.fromstring(xml)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'newsletter':
        raise ValueError('invalid root')
    rows = []
    for node in root:
        if node.tag != 'subscriber':
            continue
        email = node.get('email')
        group = node.get('segment')
        opens_node = node.find('opens')
        clicks_node = node.find('clicks')
        if email is None or group is None or opens_node is None or (clicks_node is None):
            raise ValueError('missing subscriber field')
        try:
            opens = int(opens_node.text or '')
            clicks = int(clicks_node.text or '')
        except Exception as exc:
            raise ValueError('invalid count') from exc
        if opens < 0 or clicks < 0:
            raise ValueError('invalid count')
        if group == segment and opens >= min_opens:
            rate = 0.0 if opens == 0 else round(clicks / opens * 100, 2)
            rows.append({'email': email, 'opens': opens, 'clicks': clicks, 'engagement_rate': rate})
    rows.sort(key=lambda item: (-item['opens'], -item['clicks'], item['email'].casefold()))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

