import html
from datetime import date
from decimal import Decimal, ROUND_HALF_UP
_FIELDS = {'id', 'applicant', 'region', 'amount', 'annual_income', 'submitted', 'status'}
_STATUSES = ('pending', 'approved', 'declined')

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def summarize_applications(records: list[dict], as_of: str) -> dict:
    end = _day(as_of)
    if not isinstance(as_of, str) or end.isoformat() != as_of:
        raise ValueError('invalid date')
    result = []
    seen = set()
    for source in records:
        if not isinstance(source, dict) or set(source) != _FIELDS:
            raise ValueError('invalid record')
        values = dict(source)
        for key in ('id', 'applicant', 'region', 'submitted', 'status'):
            if not isinstance(values[key], str) or not values[key]:
                raise ValueError('invalid field')
        for key in ('amount', 'annual_income'):
            if isinstance(values[key], bool) or not isinstance(values[key], int) or values[key] <= 0:
                raise ValueError('invalid amount')
        if values['status'] not in _STATUSES or values['id'] in seen:
            raise ValueError('invalid status or duplicate')
        submitted = _day(values['submitted'])
        if submitted.isoformat() != values['submitted'] or submitted > end:
            raise ValueError('invalid submitted date')
        seen.add(values['id'])
        ratio = (Decimal(values['amount']) / Decimal(values['annual_income'])).quantize(Decimal('0.0001'), rounding=ROUND_HALF_UP)
        values['income_ratio'] = float(ratio)
        values['age_days'] = (end - submitted).days
        result.append(values)
    result.sort(key=lambda x: (-x['income_ratio'], x['submitted'], x['id']))
    regions = {}
    statuses = {key: 0 for key in _STATUSES}
    total = 0
    for item in result:
        regions[item['region']] = regions.get(item['region'], 0) + item['amount']
        statuses[item['status']] += 1
        total += item['amount']
    return {'as_of': as_of, 'applications': result, 'region_totals': regions, 'status_counts': statuses, 'total_amount': total}

def render_mortgage_report(summary: dict) -> str:
    esc = lambda value: html.escape(str(value), quote=True)
    money = lambda value: f'${value:,}'
    lines = [f'''<section class="mortgage-report" data-as-of="{esc(summary['as_of'])}">''', '<h1>Mortgage Applications</h1>']
