            raise ValueError('invalid plan')
        expected = hmac.new(client_keys[client], (client + '|' + stamp_text + '|' + payload_text).encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(digest, expected):
            raise ValueError('invalid plan')
