            group['sessions'] += 1
            group['minutes'] += minutes
            group['calories'] += calories
            typ = item['type']
            if typ not in group['types']:
                group['types'][typ] = {'type': typ, 'sessions': 0, 'minutes': 0, 'calories': 0}
            row = group['types'][typ]
            row['sessions'] += 1
            row['minutes'] += minutes
            row['calories'] += calories
        result = {'client': client, 'timestamp': stamp, 'weeks': {}}
        for week in sorted(groups):
