            group['types'] = sorted(group['types'].values(), key=lambda x: (-x['minutes'], x['type']))
            result['weeks'][week] = group
        return result
    except (TypeError, ValueError, OverflowError, json.JSONDecodeError) as exc:
        if isinstance(exc, ValueError) and str(exc) in ('invalid plan', 'invalid payload', 'invalid session', 'invalid envelope'):
            raise
        raise ValueError('invalid plan') from None

