import operator

def schedule_drivers(drivers: list[dict], rule: str) -> list[dict]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except (SyntaxError, ValueError):
        raise ValueError('invalid rule')

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise ValueError('unknown name')
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = evaluate(node.operand, values)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (evaluate(node.left, values), evaluate(node.right, values))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            result = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            for op, comp in zip(node.ops, node.comparators):
                right = evaluate(comp, values)
                if type(op) not in ops or not ops[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(evaluate(a, values) for a in node.args))
        raise ValueError('invalid rule')
    selected = []
