from solution import parse_claim_line, assess_claims
import os
import tempfile
import pytest

def write_claims(lines):
    fd, path = tempfile.mkstemp()
    os.close(fd)
    with open(path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines))
    return path

def test_parse_claim_line_valid_record():
    result = parse_claim_line('CL-9|North|12500|approved|18|2024-02-29\n')
    assert result == {'claim_id': 'CL-9', 'region': 'North', 'amount_cents': 12500, 'status': 'approved', 'days_open': 18, 'filed_date': '2024-02-29'}

def test_parse_claim_line_rejects_bad_shapes_and_values():
    bad = ['', 'A|North|10|approved|2', 'A||10|approved|2|2024-01-01', 'A|North|-1|approved|2|2024-01-01', 'A|North|1.5|approved|2|2024-01-01', 'A|North|1|lost|2|2024-01-01', 'A|North|1|approved|-2|2024-01-01', 'A|North|1|approved|2|2024-02-30', 'A|North|1|approved|2|2024/01/01', 'A|North|1|approved|2|2024-1-01']
    for line in bad:
        with pytest.raises(ValueError):
            parse_claim_line(line)

def test_assess_claims_region_filter_excludes_other_records():
    path = write_claims(['bad|South|not-money|unknown|-4|2024-99-99', 'c2|North|250|pending|7|2024-04-02', 'c1|North|150|approved|1|2024-04-01'])
    try:
        result = assess_claims(path, 'North')
        assert result == {'claim_count': 2, 'total_amount_cents': 400, 'by_region': {'North': {'claim_count': 2, 'total_amount_cents': 400, 'approved_cents': 150, 'denied_cents': 0, 'pending_cents': 250, 'average_days_open': 4.0, 'claim_ids': ['c1', 'c2']}}}
    finally:
        os.unlink(path)

def test_assess_claims_empty_file_and_no_matches():
    path = write_claims([])
    try:
        assert assess_claims(path) == {'claim_count': 0, 'total_amount_cents': 0, 'by_region': {}}
        assert assess_claims(path, 'North') == {'claim_count': 0, 'total_amount_cents': 0, 'by_region': {}}
    finally:
        os.unlink(path)

def test_assess_claims_rejects_duplicate_included_ids():
    path = write_claims(['same|North|100|approved|1|2024-01-01', 'same|South|200|denied|2|2024-01-02', 'same|North|300|pending|3|2024-01-03'])
    try:
        with pytest.raises(ValueError):
            assess_claims(path)
        filtered = assess_claims(path, 'South')
        assert filtered['claim_count'] == 1
        assert filtered['total_amount_cents'] == 200
    finally:
        os.unlink(path)

