from datetime import date, timedelta
from html import escape

def _fields(line):
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current))
    return fields

def parse_progress(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        parts = _fields(raw)
        if len(parts) != 4:
            raise ValueError('wrong field count')
        try:
            date.fromisoformat(parts[0])
            percent = int(parts[2])
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if not parts[1] or not 0 <= percent <= 100:
            raise ValueError('invalid record')
        result.append({'date': parts[0], 'project': parts[1], 'percent': percent, 'note': parts[3]})
    return result

def build_project_summary(records: list[dict], as_of: str) -> list[dict]:
    try:
        cutoff = date.fromisoformat(as_of)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    groups = {}
    for record in records:
        if set(record) != {'date', 'project', 'percent', 'note'} or not isinstance(record['project'], str) or (not record['project']) or (not isinstance(record['percent'], int)) or (not 0 <= record['percent'] <= 100):
            raise ValueError('invalid record')
        try:
            day = date.fromisoformat(record['date'])
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if day <= cutoff:
            groups.setdefault(record['project'], []).append((day, record))
    output = []
    for project, items in groups.items():
        latest_day, latest = max(enumerate(items), key=lambda x: (x[1][0], x[0]))[1]
        window_start = cutoff - timedelta(days=6)
        values = [record['percent'] for day, record in items if window_start <= day <= cutoff]
        output.append({'project': project, 'latest': {'date': latest['date'], 'percent': latest['percent'], 'note': latest['note']}, 'average': round(sum(values) / len(values), 1)})
    return sorted(output, key=lambda item: (-item['latest']['percent'], item['project']))

def render_report(summary: list[dict], title: str) -> str:
    rows = []
    for item in summary:
        latest = item['latest']
        rows.append(f"<tr><td>{escape(item['project'])}</td><td>{latest['percent']}% ({escape(latest['date'])})</td><td>{item['average']}%</td><td>{escape(latest['note'])}</td></tr>")
    return f"""<section class="progress-report"><h1>{escape(title)}</h1><table><thead><tr><th>Project</th><th>Latest</th><th>Average</th><th>Note</th></tr></thead><tbody>{''.join(rows)}</tbody></table></section>"""

