    selected.sort(key=lambda a: (a['symbol'], a['timestamp']))
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.alerts-', dir=directory, text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('timestamp', 'symbol', 'severity', 'title'))
            for alert in selected:
                writer.writerow((alert['timestamp'], alert['symbol'], alert['severity'], alert['title']))
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(selected)

