import ast
import operator

def _evaluate(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('unknown name')
        return names[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left = _evaluate(node.left, names)
        right = _evaluate(node.right, names)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _evaluate(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        value = _evaluate(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value):
                return value
            if isinstance(node.op, ast.Or) and value:
                return value
            value = _evaluate(child, names)
        return value
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, names)
        for op, child in zip(node.ops, node.comparators):
            right = _evaluate(child, names)
            if type(op) not in (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE):
                raise ValueError('unsupported comparison')
            if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_evaluate(arg, names) for arg in node.args]
        if node.func.id == 'round' and len(args) not in (1, 2):
            raise ValueError('invalid round')
        if node.func.id != 'round' and (not args):
            raise ValueError('missing arguments')
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
    raise ValueError('unsupported expression')

def select_reservations(reservations: list[dict], rule: str, *, offset: int=0, limit: int | None=None) -> dict:
    if not isinstance(offset, int) or offset < 0 or (limit is not None and (not isinstance(limit, int) or limit < 0)):
        raise ValueError('invalid pagination')
    try:
        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid rule') from exc
    selected = []
    for reservation in reservations:
        total = reservation['nights'] * reservation['rate']
        names = dict(reservation)
        names['total'] = total
        try:
            matched = _evaluate(tree, names)
        except NameError as exc:
            raise ValueError('unknown name') from exc
        if matched:
            selected.append({'id': reservation['id'], 'site': reservation['site'], 'nights': reservation['nights'], 'guests': reservation['guests'], 'rate': reservation['rate'], 'total': total})
    selected.sort(key=lambda row: (-row['total'], row['id']))
    page = selected[offset:] if limit is None else selected[offset:offset + limit]
    return {'reservations': page, 'count': len(selected), 'gross': round(sum((row['total'] for row in page)), 2)}

