import operator

def filter_eligible(applicants: list[dict[str, int | float]], rule: str) -> list[dict[str, int | float]]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid rule') from exc
    names = {'age', 'income', 'dependents'}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in names:
            return values[node.id]
        if isinstance(node, ast.UnaryOp):
            value = visit(node.operand)
            if isinstance(node.op, ast.Not):
                return not value
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
        if isinstance(node, ast.BinOp):
            left, right = (visit(node.left), visit(node.right))
            operations = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            for kind, function in operations.items():
                if isinstance(node.op, kind):
                    return function(left, right)
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                result = True
                for item in node.values:
                    result = visit(item)
                    if not result:
                        return result
                return result
            result = False
            for item in node.values:
                result = visit(item)
                if result:
                    return result
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            comparisons = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}
            for op, comparator_node in zip(node.ops, node.comparators):
                right = visit(comparator_node)
                function = next((f for kind, f in comparisons.items() if isinstance(op, kind)), None)
                if function is None or not function(left, right):
                    return False
                left = right
            return True
        raise ValueError('invalid rule')
    result = []
    for applicant in applicants:
        values = {name: applicant[name] for name in names}
        try:
            if visit(tree):
                result.append(applicant)
        except Exception as exc:
            raise ValueError('invalid rule') from exc
    return result

