import subprocess

def parse_clock(value: str) -> int:
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
        raise ValueError('invalid time')
    if not value[:2].isdigit() or not value[3:].isdigit():
        raise ValueError('invalid time')
    hour = int(value[:2])
    minute = int(value[3:])
    if hour > 23 or minute > 59:
        raise ValueError('invalid time')
    return hour * 60 + minute

def load_playlist(path: str) -> list[tuple[int, str, str, int]]:
    result = subprocess.run(['sort', '-t', '|', '-k1,1', '-k2,2', path], capture_output=True, text=True, check=True)
    records = []
    for line in result.stdout.splitlines():
        if not line:
            continue
        fields = line.split('|')
        if len(fields) != 4:
            raise ValueError('invalid record')
        start = parse_clock(fields[0])
        artist = fields[1].strip()
        title = fields[2].strip()
        if not artist or not title:
            raise ValueError('invalid record')
        try:
            duration = int(fields[3].strip())
        except ValueError:
            raise ValueError('invalid record')
        if duration <= 0:
            raise ValueError('invalid record')
        records.append((start, artist, title, duration))
    return records

def make_schedule(path: str, opening: str, closing: str) -> list[dict[str, object]]:
    begin = parse_clock(opening)
    finish = parse_clock(closing)
    if finish <= begin:
        raise ValueError('invalid window')
    selected = []
    for start, artist, title, duration in load_playlist(path):
        end = start + (duration + 59) // 60
        if start >= begin and end <= finish:
            selected.append({'start': start, 'end': end, 'artist': artist, 'title': title})
    for previous, current in zip(selected, selected[1:]):
        if current['start'] < previous['end']:
            raise ValueError('overlapping tracks')
    return selected

def daily_stats(schedule: list[dict[str, object]]) -> dict[str, object]:
    artists = {}
    minutes = 0
    longest = None
    longest_length = -1
    for item in schedule:
        length = item['end'] - item['start']
        minutes += length
        artists[item['artist']] = artists.get(item['artist'], 0) + length
        if length > longest_length:
            longest_length = length
            longest = item['title']
    return {'tracks': len(schedule), 'minutes': minutes, 'artists': artists, 'longest': longest}

