import datetime
import math
import subprocess

def summarize_temperature_log(path: str, limit: int=10, minimum_samples: int=1) -> list[tuple[str, float, int]]:
    if limit < 0:
        raise ValueError('limit must not be negative')
    if minimum_samples < 1:
        raise ValueError('minimum_samples must be positive')
    result = subprocess.run(['sort', path], check=True, capture_output=True, text=True)
    groups = {}
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split()
        if len(fields) != 2:
            raise ValueError('invalid record')
        date_text, temperature_text = fields
        try:
            datetime.date.fromisoformat(date_text)
            temperature = float(temperature_text)
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if not math.isfinite(temperature):
            raise ValueError('invalid record')
        total, count = groups.get(date_text, (0.0, 0))
        groups[date_text] = (total + temperature, count + 1)
    ranked = []
    for date_text, (total, count) in groups.items():
        if count >= minimum_samples:
            ranked.append((date_text, round(total / count, 2), count))
    ranked.sort(key=lambda item: (-item[1], item[0]))
    return ranked[:limit]

