import sqlite3

def build_incident_report(conn: sqlite3.Connection, departments: list[str] | None, min_severity: int | None, sort_by: str, descending: bool, limit: int, offset: int) -> list[dict[str, object]]:
    allowed = {'id', 'department', 'severity', 'reported_at', 'status'}
    if sort_by not in allowed:
        raise ValueError('invalid sort column')
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        raise ValueError('invalid limit')
    if not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if min_severity is not None and (not isinstance(min_severity, int) or min_severity < 1 or min_severity > 5):
        raise ValueError('invalid severity')
    if departments == []:
        return []
    clauses = []
    params = []
    if departments is not None:
        placeholders = ','.join(('?' for _ in departments))
        clauses.append(f'department IN ({placeholders})')
        params.extend(departments)
    if min_severity is not None:
        clauses.append('severity >= ?')
        params.append(min_severity)
    query = 'SELECT id, department, severity, reported_at, status, summary FROM incidents'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    direction = 'DESC' if descending else 'ASC'
    query += f' ORDER BY {sort_by} {direction}, id ASC LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    rows = conn.execute(query, params).fetchall()
    keys = ('id', 'department', 'severity', 'reported_at', 'status', 'summary')
    return [dict(zip(keys, row)) for row in rows]

