import csv
import os

def write_injury_report(records: list[dict], base_dir: str, filename: str, min_days: int=0) -> str:
    if not isinstance(min_days, int) or isinstance(min_days, bool) or min_days < 0:
        raise ValueError('invalid min_days')
    if not isinstance(filename, str) or not filename or os.path.isabs(filename):
        raise ValueError('invalid filename')
    base = os.path.abspath(base_dir)
    path = os.path.abspath(os.path.join(base, filename))
    try:
        inside = os.path.commonpath([base, path]) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('invalid filename')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        athlete = record.get('athlete')
        injury = record.get('injury')
        days = record.get('days_out')
        if not isinstance(athlete, str) or not athlete or (not isinstance(injury, str)) or (not injury) or (not isinstance(days, int)) or isinstance(days, bool) or (days < 0):
            raise ValueError('invalid record')
        if days < min_days:
            continue
        item = grouped.setdefault(athlete, [0, 0])
        item[0] += days
        item[1] += 1
    rows = []
    for athlete, (total, count) in grouped.items():
        rows.append((athlete, total, count, round(total / count, 2)))
    rows.sort(key=lambda row: (-row[1], row[0]))
    os.makedirs(os.path.dirname(path), exist_ok=True)
