import json

def encode_rights_snapshot(records: list[dict]) -> bytes:
    try:
        return json.dumps(records, separators=(',', ':'), sort_keys=True).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid records') from exc

def rights_summary(payload: bytes, territory: str, offset: int, limit: int) -> list[dict]:
    if type(offset) is not int or type(limit) is not int or offset < 0 or (limit < 0):
        raise ValueError('invalid pagination')
    try:
        records = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    groups = {}
    required = ('title', 'territory', 'licensee', 'start', 'end', 'fee')
    for record in records:
        if not isinstance(record, dict) or any((key not in record for key in required)):
            raise ValueError('invalid record')
        if record['territory'] != territory:
            continue
        if not isinstance(record['title'], str) or not isinstance(record['start'], str):
            raise ValueError('invalid record')
        if not isinstance(record['fee'], (int, float)) or isinstance(record['fee'], bool):
            raise ValueError('invalid record')
        group = groups.setdefault(record['title'], {'title': record['title'], 'total_fee': 0.0, 'rights_count': 0, 'earliest_start': record['start']})
        group['total_fee'] += record['fee']
        group['rights_count'] += 1
        group['earliest_start'] = min(group['earliest_start'], record['start'])
    result = []
    for group in groups.values():
        group['total_fee'] = round(group['total_fee'], 2)
        result.append(group)
    result.sort(key=lambda item: (-item['total_fee'], item['title']))
    return result[offset:offset + limit]

