import secrets
from decimal import Decimal, InvalidOperation, ROUND_DOWN
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def _cents(value):
    try:
        number = Decimal(value)
    except (InvalidOperation, TypeError, ValueError):
        raise ValueError
    if not number.is_finite() or number < 0:
        raise ValueError
    scaled = number.quantize(Decimal('0.01'), rounding=ROUND_DOWN)
    if scaled != number:
        raise ValueError
    return int(scaled * 100)

def _permit(value):
    if not isinstance(value, str) or not value or re.fullmatch('[A-Z0-9-]+', value) is None:
        raise ValueError

