def search_contract_clauses(conn: sqlite3.Connection, query: str, category: str | None=None, sort_by: str='relevance', limit: int=20, offset: int=0) -> list[dict]:
    if sort_by not in {'relevance', 'section', 'id'}:
        raise ValueError('invalid sort_by')
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0 or (limit > 100):
        raise ValueError('invalid limit')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    words = query.lower().split()
    conditions = []
    params = []
    for word in words:
        conditions.append("lower(title || ' ' || body) LIKE ?")
        params.append('%' + word + '%')
    if category is not None:
        conditions.append('category = ?')
        params.append(category)
    sql = 'SELECT id, contract_id, section, category, title, body FROM clauses'
    if conditions:
        sql += ' WHERE ' + ' AND '.join(conditions)
    rows = conn.execute(sql, params).fetchall()
    result = []
    for row in rows:
        combined = (row[4] + ' ' + row[5]).lower()
        score = sum((combined.count(word) for word in words))
        result.append({'id': row[0], 'contract_id': row[1], 'section': row[2], 'category': row[3], 'title': row[4], 'body': row[5], 'score': score})
    if sort_by == 'relevance':
        result.sort(key=lambda item: (-item['score'], item['id']))
    elif sort_by == 'section':
        result.sort(key=lambda item: (item['section'], item['id']))
    else:
        result.sort(key=lambda item: item['id'])
    return result[offset:offset + limit]

