def export_deduplicated_contacts(contacts: list[dict[str, str]], output_path: str) -> int:
    if not isinstance(contacts, list):
        raise TypeError('contacts must be a list')
    rows = []
    seen = set()
    for contact in contacts:
        if not isinstance(contact, dict):
            raise TypeError('contact must be a dictionary')
        name = contact['name']
        email = contact['email']
        phone = contact['phone']
