import hmac
import os

def create_technician(technician_id: str, pin: str) -> dict:
    if not isinstance(technician_id, str) or not technician_id:
        raise ValueError('invalid technician_id')
    if not isinstance(pin, str) or not pin:
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'technician_id': technician_id, 'credential': salt.hex() + ':' + digest.hex()}

def authenticate_technician(record: dict, pin: str) -> bool:
    if not isinstance(record, dict) or not isinstance(pin, str):
        return False
    try:
        salt_text, digest_text = record['credential'].split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_routes(routes: list[dict], technician_id: str, page: int, page_size: int) -> dict:
