        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    selected = []
    for route in routes:
        if not isinstance(route, dict):
            raise ValueError('invalid route')
        if not isinstance(route.get('technician_id'), str) or not isinstance(route.get('route_id'), str):
            raise ValueError('invalid route')
        distance = route.get('distance_km')
        stops = route.get('stops')
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or distance < 0:
            raise ValueError('invalid distance')
        if isinstance(stops, bool) or not isinstance(stops, int) or stops < 0:
            raise ValueError('invalid stops')
        if not isinstance(route.get('completed'), bool):
            raise ValueError('invalid completion')
        if route['technician_id'] == technician_id and route['completed']:
            selected.append(route)
    selected.sort(key=lambda r: (-r['distance_km'], r['route_id']))
    start = (page - 1) * page_size
    return {'routes': selected[start:start + page_size], 'total': len(selected), 'total_distance_km': round(sum((r['distance_km'] for r in selected)), 2), 'total_stops': sum((r['stops'] for r in selected)), 'page': page, 'page_size': page_size}

