import re

def parse_measurements(text: str) -> dict[str, float]:
    if not isinstance(text, str) or not text.strip():
        raise ValueError('measurement string is empty')
    result = {}
    for item in text.split(','):
        match = re.fullmatch('\\s*([A-Za-z]+)\\s*=\\s*([0-9]+(?:\\.[0-9]+)?)\\s*(cm|in)?\\s*', item, re.I)
        if not match:
            raise ValueError('invalid measurement')
        name = match.group(1).lower()
        if name not in {'chest', 'waist', 'hip'} or name in result:
            raise ValueError('invalid measurement name')
        value = float(match.group(2))
        if value <= 0:
            raise ValueError('measurement must be positive')
        if (match.group(3) or 'cm').lower() == 'in':
            value *= 2.54
