    assert result == {
        "claim_id": "CLM-1042",
        "status": "approved",
        "amount": 12500.50,
        "updated": "2025-02-14T09:30:00Z",
    }
    assert request.call_args.args[0] == "https://subsidies.example.gov/api/v1/claims/status"


def test_sends_claim_id_as_query_parameter():
    response = make_response(200, {
        "claim_id": "A/77",
        "status": "pending",
        "amount": 0,
        "updated": "2025-01-01",
    })
    with patch("solution.requests.get", return_value=response) as request:
        fetch_claim_status("A/77", "secret")
    kwargs = request.call_args.kwargs
    assert kwargs["params"] == {"claim_id": "A/77"}


