        "claim_id": "C1",
        "status": "received",
        "amount": 10,
        "updated": "today",
    })
    with patch("solution.requests.get", return_value=response) as request:
        fetch_claim_status("C1", "token-789")
    headers = request.call_args.kwargs["headers"]
    assert headers["Authorization"] == "Bearer token-789"
