def export_assignment_report(assignments: list[dict], output_path: str) -> dict:
    if not isinstance(assignments, list):
        raise TypeError('assignments must be a list')
    checked = []
    for item in assignments:
        if not isinstance(item, dict):
            raise ValueError('assignment must be a dictionary')
        for key in ('reporter', 'desk', 'status', 'hours', 'due_date'):
            if key not in item:
                raise ValueError('missing field')
        if not isinstance(item['reporter'], str) or not item['reporter']:
            raise ValueError('invalid reporter')
        if not isinstance(item['desk'], str) or not item['desk']:
            raise ValueError('invalid desk')
        if item['status'] not in ('assigned', 'completed'):
            raise ValueError('invalid status')
        if isinstance(item['hours'], bool) or not isinstance(item['hours'], (int, float)) or (not math.isfinite(item['hours'])) or (item['hours'] < 0):
            raise ValueError('invalid hours')
        if not isinstance(item['due_date'], str):
            raise ValueError('invalid date')
        try:
            parsed = datetime.date.fromisoformat(item['due_date'])
        except ValueError:
            raise ValueError('invalid date')
        if parsed.isoformat() != item['due_date']:
            raise ValueError('invalid date')
        checked.append(item)
    ordered = sorted(checked, key=lambda x: (x['due_date'], x['desk'], x['reporter']))
    groups = {}
    for item in checked:
        group = groups.setdefault(item['desk'], {'assignments': 0, 'completed': 0, 'hours': 0.0})
        group['assignments'] += 1
        group['completed'] += item['status'] == 'completed'
        group['hours'] += item['hours']
    desks = [{'desk': name, 'assignments': groups[name]['assignments'], 'completed': groups[name]['completed'], 'hours': round(groups[name]['hours'], 2)} for name in sorted(groups)]
    parent = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['desk', 'reporter', 'status', 'hours', 'due_date'])
            for item in ordered:
                writer.writerow([item['desk'], item['reporter'], item['status'], f"{item['hours']:.2f}", item['due_date']])
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'rows': len(checked), 'desks': desks}

