def _split_escaped(value, separator):
    parts = []
    current = []
    escaped = False
    for char in value:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == separator:
            parts.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    parts.append(''.join(current))
    return parts

def parse_adoption_records(text: str) -> dict[str, dict]:
    records = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        fields = _split_escaped(line, '|')
        if len(fields) != 5 or not fields[0] or (not fields[3]) or (fields[0] in records):
            raise ValueError('invalid record')
        tags = [x.strip() for x in _split_escaped(fields[4], ',') if x.strip()]
        records[fields[0]] = {'id': fields[0], 'animal': fields[1], 'applicant': fields[2], 'species': fields[3], 'tags': tags, 'status': 'pending', 'history': []}
    return records

def review_adoption(requester: dict, records: dict[str, dict], application_id: str, decision: str) -> dict:
    if application_id not in records:
        raise KeyError(application_id)
    if decision not in ('approved', 'declined') or records[application_id]['status'] != 'pending':
        raise ValueError('invalid review')
    record = records[application_id]
    if requester.get('role') != 'shelter_staff' and requester.get('id') != record['applicant']:
        raise PermissionError('not permitted')
    record['status'] = decision
    record['history'].append({'by': requester['id'], 'decision': decision})
    return record

def adoption_summary(records: dict[str, dict]) -> list[dict]:
    order = {'pending': 0, 'approved': 1, 'declined': 2}
    values = list(records.values())
    values.sort(key=lambda r: (order.get(r['status'], 99), r['species'].casefold(), r['animal'].casefold(), r['id']))
    return [{'id': r['id'], 'animal': r['animal'], 'species': r['species'], 'applicant': r['applicant'], 'status': r['status'], 'history_count': len(r['history'])} for r in values]

