import csv
import io
import subprocess
from datetime import date
from decimal import Decimal, InvalidOperation

def parse_application_line(line: str) -> dict:
    if not line.strip():
        raise ValueError('blank record')
    try:
        rows = list(csv.reader([line]))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    if len(rows) != 1 or len(rows[0]) != 6:
        raise ValueError('invalid field count')
    vendor, invoice, amount, status, application_date, notes = rows[0]
    if not vendor or not invoice or (not status) or (not application_date):
        raise ValueError('empty required field')
    try:
        value = Decimal(amount)
    except InvalidOperation as exc:
        raise ValueError('invalid amount') from exc
    if not value.is_finite() or value < 0 or value.as_tuple().exponent < -2:
        raise ValueError('invalid amount')
    try:
        cents = int(value * 100)
        date.fromisoformat(application_date)
    except (ValueError, OverflowError) as exc:
        raise ValueError('invalid record') from exc
    return {'vendor': vendor, 'invoice': invoice, 'amount_cents': cents, 'status': status, 'application_date': application_date, 'notes': notes}

def summarize_applications(records: list[dict], approved_statuses: set[str] | None=None) -> list[dict]:
    statuses = {'APPROVED'} if approved_statuses is None else approved_statuses
    groups = {}
    for record in records:
        if record['status'] not in statuses:
            continue
        key = (record['vendor'], record['application_date'][:7])
        group = groups.setdefault(key, {'vendor': key[0], 'month': key[1], 'invoice_count': 0, 'total_cents': 0, 'invoices': [], '_seen': set()})
        if record['invoice'] not in group['_seen']:
            group['_seen'].add(record['invoice'])
            group['invoice_count'] += 1
            group['total_cents'] += record['amount_cents']
            group['invoices'].append(record['invoice'])
    result = []
    for group in sorted(groups.values(), key=lambda x: (x['vendor'], x['month'])):
        group['invoices'].sort()
        group.pop('_seen')
        result.append(group)
    return result

def build_payment_report(paths: list[str], approved_statuses: set[str] | None=None) -> list[dict]:
    if not paths:
        raise ValueError('paths must not be empty')
    try:
        completed = subprocess.run(['cat', *paths], capture_output=True, text=True, check=True)
    except (OSError, subprocess.CalledProcessError) as exc:
        raise RuntimeError('unable to read payment files') from exc
    records = []
    for line in completed.stdout.splitlines():
        if line.strip():
            records.append(parse_application_line(line))
    return summarize_applications(records, approved_statuses)

