def create_operator_record(operator_id: str, password: str) -> dict:
    if not isinstance(operator_id, str) or not operator_id or (not isinstance(password, str)) or (not password):
        raise ValueError()
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return {'operator_id': operator_id, 'salt': salt.hex(), 'iterations': iterations, 'digest': digest.hex()}

def verify_operator_password(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(password, str):
        return False
    try:
        salt = bytes.fromhex(record['salt'])
        iterations = record['iterations']
        expected = bytes.fromhex(record['digest'])
        if not isinstance(iterations, int) or iterations < 100000:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_tracks(lines: list[str], window_seconds: int) -> dict:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError()
    groups = {}
    for line in lines:
        if not isinstance(line, str):
            raise ValueError()
        if not line.strip():
            continue
        try:
            fields = next(csv.reader([line]))
        except Exception as exc:
            raise ValueError() from exc
        fields = [x.strip() for x in fields]
        if fields == ['collar_id', 'timestamp', 'latitude', 'longitude', 'battery'] and (not groups):
            continue
        if len(fields) != 5:
            raise ValueError()
        collar = fields[0]
        try:
            timestamp = int(fields[1])
            lat = float(fields[2])
            lon = float(fields[3])
            battery = float(fields[4])
        except (ValueError, OverflowError):
