        if not collar or timestamp < 0 or (not all((math.isfinite(x) for x in (lat, lon, battery)))) or (not (-90 <= lat <= 90 and -180 <= lon <= 180 and (0 <= battery <= 100))):
            raise ValueError()
        groups.setdefault(collar, []).append((timestamp, lat, lon, battery))
    output = {}
    for collar in sorted(groups):
        points = sorted(groups[collar], key=lambda x: x[0])
        distance = 0.0
        for a, b in zip(points, points[1:]):
            p, q = (math.radians(a[1]), math.radians(b[1]))
            dp = math.radians(b[1] - a[1])
            dl = math.radians(b[2] - a[2])
            z = math.sin(dp / 2) ** 2 + math.cos(p) * math.cos(q) * math.sin(dl / 2) ** 2
            distance += 6371.0 * 2 * math.asin(math.sqrt(min(1.0, z)))
        base = points[0][0]
