        date = record['date']
        loss = record['loss']
        exposure = record['exposure']
        if not isinstance(entity, str) or not entity:
            raise ValueError('invalid entity')
        if not isinstance(date, str):
            raise ValueError('invalid date')
        try:
            parsed = datetime.date.fromisoformat(date)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if parsed.isoformat() != date:
            raise ValueError('invalid date')
        if isinstance(loss, bool) or not isinstance(loss, (int, float)) or (not math.isfinite(loss)) or (loss < 0):
            raise ValueError('invalid loss')
        if isinstance(exposure, bool) or not isinstance(exposure, (int, float)) or (not math.isfinite(exposure)) or (exposure <= 0):
            raise ValueError('invalid exposure')
        key = (entity, date)
        if key in seen:
            raise ValueError('duplicate observation')
        seen.add(key)
        grouped.setdefault(entity, []).append((date, loss, exposure))
    entities = {}
    for entity in sorted(grouped):
        rows = sorted(grouped[entity], key=lambda row: row[0])
        rates = [loss / exposure for _, loss, exposure in rows]
        entities[entity] = {'observations': [{'date': date, 'rate': rate} for (date, _, _), rate in zip(rows, rates)], 'total_loss': sum((row[1] for row in rows)), 'total_exposure': sum((row[2] for row in rows)), 'latest_rate': rates[-1], 'rolling_rate': sum(rates[-window:]) / len(rates[-window:]), 'max_rate': max(rates)}
    return {'entities': entities}

def serialize_report(report: dict) -> bytes:
    try:
        return json.dumps(report, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError('cannot serialize report') from exc

def deserialize_report(blob: bytes) -> dict:
    if not isinstance(blob, (bytes, bytearray)):
        raise ValueError('invalid report')
    try:
        value = json.loads(bytes(blob).decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError, TypeError) as exc:
        raise ValueError('invalid report') from exc
    if not isinstance(value, dict):
        raise ValueError('invalid report')
    return value

def rank_entities(report: dict) -> list[str]:
    entities = report['entities']
    return sorted(entities, key=lambda name: (-entities[name]['rolling_rate'], -entities[name]['max_rate'], name))

