from datetime import date

def parse_meal_log(text: str) -> list[dict]:
    records = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        fields = [part.strip() for part in line.split('|')]
        if len(fields) != 3:
            raise ValueError(f'invalid line {number}')
        value, meal, cost = fields
        try:
            date.fromisoformat(value)
            amount = int(cost)
        except (ValueError, TypeError):
            raise ValueError(f'invalid line {number}')
        if meal not in {'breakfast', 'lunch', 'dinner'} or amount < 0 or str(amount) != cost:
            raise ValueError(f'invalid line {number}')
        records.append({'date': value, 'meal': meal, 'cost_cents': amount})
    if not records:
        raise ValueError('empty meal log')
    return records

def meal_eligibility_report(requester: dict, student: dict, meal_log: str, policy: dict) -> dict:
    authorized = requester['id'] == student['id'] or (requester['campus'] == student['campus'] and bool(set(requester['roles']) & {'caseworker', 'admin'}))
    if not authorized:
        raise PermissionError('request not permitted')
    records = parse_meal_log(meal_log)
    daily = {}
    monthly = {}
    for record in records:
        day = record['date']
        month = day[:7]
        daily[day] = daily.get(day, 0) + record['cost_cents']
        item = monthly.setdefault(month, {'requested_cents': 0, 'days_set': set()})
        item['requested_cents'] += record['cost_cents']
        item['days_set'].add(day)
    months = {}
    total = 0
    for month in sorted(monthly):
        item = monthly[month]
        approved = min(sum((min(daily[d], policy['daily_limit_cents']) for d in item['days_set'])), policy['monthly_limit_cents'])
        months[month] = {'requested_cents': item['requested_cents'], 'approved_cents': approved, 'days': len(item['days_set'])}
        total += approved
    eligible = student['household_income_cents'] <= policy['income_limit_cents'] and student['attendance_percent'] >= policy['minimum_attendance_percent'] and all((x['requested_cents'] <= policy['monthly_limit_cents'] for x in months.values()))
    return {'student_id': student['id'], 'eligible': eligible, 'approved_cents': total, 'months': months}

