import csv
import os
import tempfile
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_release_report(records: list[dict], destination: str, page: int=1, page_size: int=50) -> list[dict]:
    if not isinstance(records, list) or page < 1 or page_size < 1:
        raise ValueError()
    required = {'batch_id', 'product', 'status', 'potency', 'release_date'}
    groups = {}
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError()
        try:
            release_date = date.fromisoformat(record['release_date'])
            potency = Decimal(str(record['potency']))
        except (ValueError, TypeError, InvalidOperation):
            raise ValueError()
        if record['status'] == 'released':
            product = record['product']
            groups.setdefault(product, []).append((potency, release_date))
    all_rows = []
    for product in sorted(groups):
        values = groups[product]
        average = (sum((value for value, _ in values), Decimal('0')) / len(values)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        dates = [item[1] for item in values]
        all_rows.append({'product': product, 'batch_count': len(values), 'average_potency': format(average, '.2f'), 'min_release_date': min(dates).isoformat(), 'max_release_date': max(dates).isoformat()})
    start = (page - 1) * page_size
    rows = all_rows[start:start + page_size]
    parent = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(dir=parent, prefix='.release-', suffix='.csv')
    os.close(descriptor)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['product', 'batch_count', 'average_potency', 'min_release_date', 'max_release_date'])
            for row in rows:
                writer.writerow([row[key] for key in ['product', 'batch_count', 'average_potency', 'min_release_date', 'max_release_date']])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return rows

