import ast

def _evaluate(node, values):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        raise ValueError('unsupported expression')
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise NameError(node.id)
        return values[node.id]
    if isinstance(node, ast.BinOp):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
        raise ValueError('unsupported expression')
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.Not):
            return not value
        raise ValueError('unsupported expression')
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            for item in node.values:
                if not _evaluate(item, values):
                    return False
            return True
        if isinstance(node.op, ast.Or):
            for item in node.values:
                if _evaluate(item, values):
                    return True
            return False
        raise ValueError('unsupported expression')
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for operator, comparator in zip(node.ops, node.comparators):
            right = _evaluate(comparator, values)
            if isinstance(operator, ast.Lt):
                result = left < right
            elif isinstance(operator, ast.LtE):
                result = left <= right
            elif isinstance(operator, ast.Gt):
                result = left > right
            elif isinstance(operator, ast.GtE):
                result = left >= right
            elif isinstance(operator, ast.Eq):
                result = left == right
            elif isinstance(operator, ast.NotEq):
                result = left != right
            else:
                raise ValueError('unsupported expression')
            if not result:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
        if len(node.args) < 2:
            raise ValueError('min and max need at least two arguments')
        arguments = [_evaluate(item, values) for item in node.args]
        return min(arguments) if node.func.id == 'min' else max(arguments)
    raise ValueError('unsupported expression')

def available_spots(spots: list[dict[str, int]], rule: str) -> list[dict[str, int]]:
    tree = ast.parse(rule, mode='eval')
    selected = []
    for spot in spots:
        values = {name: spot[name] for name in ('id', 'level', 'occupied', 'distance')}
        if _evaluate(tree.body, values):
            selected.append(spot)
    return sorted(selected, key=lambda spot: (spot['level'], spot['id']))

