            pri = int(priority)
            date.fromisoformat(submitted)
        except (ValueError, TypeError):
            raise ValueError('invalid value')
        if not aid or aid in ids or (not name) or (h < 1) or (inc < 0) or (pri not in range(4)):
            raise ValueError('invalid value')
        ids.add(aid)
        result.append({'application_id': aid, 'name': name, 'household_size': h, 'annual_income': inc, 'priority': pri, 'submitted': submitted})
    return result

