import csv
import hashlib
import hmac
import io
import json
from datetime import date, timedelta

def parse_subscribers(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text)))
    except csv.Error as exc:
        raise ValueError('malformed CSV') from exc
    if not rows or rows[0] != ['email', 'joined', 'spend', 'tags', 'opens']:
        raise ValueError('incorrect header')
    result = []
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('malformed row')
        email, joined, spend, tags, opens = row
        if not email:
            raise ValueError('empty email')
        try:
            joined_date = date.fromisoformat(joined)
            amount = float(spend)
        except (ValueError, TypeError) as exc:
            raise ValueError('invalid field') from exc
        if amount < 0:
            raise ValueError('negative spend')
        tag_list = tags.split('|') if tags else []
        if any((not item for item in tag_list)):
            raise ValueError('empty tag')
        try:
            open_list = [date.fromisoformat(item) for item in opens.split(';')] if opens else []
        except ValueError as exc:
            raise ValueError('invalid open date') from exc
        result.append({'email': email, 'joined': joined_date, 'spend': amount, 'tags': tag_list, 'opens': open_list})
    return result

def build_segments(records: list[dict], config: dict) -> dict[str, list[str]]:
    try:
        as_of = date.fromisoformat(config['as_of'])
    except (KeyError, ValueError, TypeError) as exc:
        raise ValueError('invalid as_of') from exc
    start = as_of - timedelta(days=29)
    groups = {'vip': [], 'active': [], 'dormant': []}
    ranked = []
    for record in records:
        count = sum((start <= opened <= as_of for opened in record['opens']))
        group = 'vip' if record['spend'] >= 100 and count >= 3 else 'active' if count >= 2 else 'dormant'
        ranked.append((group, count, record['spend'], record['email']))
    for group in groups:
        values = [item for item in ranked if item[0] == group]
        values.sort(key=lambda item: (-item[1], -item[2], item[3]))
        groups[group] = [item[3] for item in values]
    return groups

def signed_manifest(records: list[dict], config: dict) -> str:
    segments = build_segments(records, config)
    key = config['newsletter_signing_key']
    payload = json.dumps(segments, separators=(',', ':'), sort_keys=True).encode()
    signature = hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return json.dumps({'segments': segments, 'signature': signature}, separators=(',', ':'), sort_keys=True)

