import csv
import datetime
import math
import os
import tempfile

def export_water_samples(samples: list[dict], output_path: str, start_date: str | None=None, end_date: str | None=None) -> dict:

    def parse_date(value):
        if value is None:
            return None
        try:
            return datetime.date.fromisoformat(value)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
    beginning = parse_date(start_date)
    ending = parse_date(end_date)
    if beginning is not None and ending is not None and (beginning > ending):
        raise ValueError('invalid date range')
    valid = []
    for sample in samples:
        try:
            station = sample['station']
            text_date = sample['sampled_at']
            nitrate = sample['nitrate_mg_l']
            ph = sample['ph']
        except (KeyError, TypeError):
            raise ValueError('invalid sample')
        if not isinstance(station, str) or not isinstance(text_date, str):
            raise ValueError('invalid sample')
        date_value = parse_date(text_date)
        if isinstance(nitrate, bool) or isinstance(ph, bool):
            raise ValueError('invalid sample')
        if not isinstance(nitrate, (int, float)) or not isinstance(ph, (int, float)):
            raise ValueError('invalid sample')
        if not math.isfinite(nitrate) or not math.isfinite(ph) or nitrate < 0 or (ph < 0) or (ph > 14):
            raise ValueError('invalid sample')
        if (beginning is None or date_value >= beginning) and (ending is None or date_value <= ending):
            valid.append((station, text_date, nitrate, ph))
    valid.sort(key=lambda row: (row[1], row[0]))
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='water-')
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['station', 'sampled_at', 'nitrate_mg_l', 'ph'])
            for station, text_date, nitrate, ph in valid:
                writer.writerow([station, text_date, f'{nitrate:.2f}', f'{ph:.2f}'])
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    average = None if not valid else round(sum((row[2] for row in valid)) / len(valid), 2)
    return {'count': len(valid), 'stations': sorted({row[0] for row in valid}), 'average_nitrate_mg_l': average}

