from solution import make_manifest, issue_upload, verify_upload_token
import pytest

def test_manifest_canonicalizes_and_aggregates():
    result = make_manifest('build-17', [{'path': 'bin/z', 'size': 4, 'sha256': 'b' * 64, 'media': 'binary'}, {'path': 'README', 'size': 2, 'sha256': 'a' * 64}, {'path': 'bin/a', 'size': 7, 'sha256': 'c' * 64, 'media': 'binary'}])
    assert result == {'build_id': 'build-17', 'total_size': 13, 'artifacts': [{'path': 'README', 'size': 2, 'sha256': 'a' * 64, 'media': 'other'}, {'path': 'bin/a', 'size': 7, 'sha256': 'c' * 64, 'media': 'binary'}, {'path': 'bin/z', 'size': 4, 'sha256': 'b' * 64, 'media': 'binary'}], 'by_media': {'binary': {'count': 2, 'bytes': 11}, 'other': {'count': 1, 'bytes': 2}}}

def test_manifest_empty_and_does_not_mutate_input():
    artifacts = []
    result = make_manifest('x', artifacts)
    assert result == {'build_id': 'x', 'total_size': 0, 'artifacts': [], 'by_media': {}}
    assert artifacts == []

def test_manifest_rejects_bad_values():
    valid = {'path': 'a.txt', 'size': 1, 'sha256': 'a' * 64}
    for bad in ['', 'a/b/../c', '/a', 'a\\b', './a', 'a//b']:
        item = dict(valid, path=bad)
        with pytest.raises(ValueError):
            make_manifest('b', [item])
    for bad_size in [-1, True, 1.5]:
        with pytest.raises(ValueError):
            make_manifest('b', [dict(valid, size=bad_size)])
    with pytest.raises(ValueError):
        make_manifest('b', [dict(valid, sha256='A' * 64)])

def test_manifest_rejects_duplicates_and_invalid_build_or_media():
    a = {'path': 'x', 'size': 0, 'sha256': '0' * 64}
    with pytest.raises(ValueError):
        make_manifest('has space', [a])
    with pytest.raises(ValueError):
        make_manifest('b', [a, dict(a)])
    with pytest.raises(ValueError):
        make_manifest('b', [dict(a, media='')])
    with pytest.raises(ValueError):
        make_manifest('b', [dict(a, media='x/y')])

def test_issue_upload_shape_and_ttl():
    plan = issue_upload('ci-1', [{'path': 'out', 'size': 3, 'sha256': 'd' * 64}], 37)
