import datetime
import os
import tempfile

def summarize_orders(orders: list[dict]) -> list[dict]:
    if not isinstance(orders, list):
        raise ValueError('orders must be a list')
    grouped = {}
    seen = set()
    for order in orders:
        if not isinstance(order, dict):
            raise ValueError('invalid order')
        for key in ('order_id', 'customer', 'due_date', 'items'):
            if key not in order:
                raise ValueError('missing field')
        oid, customer, due = (order['order_id'], order['customer'], order['due_date'])
        if not isinstance(oid, str) or not oid or (not isinstance(customer, str)):
            raise ValueError('invalid order fields')
        if oid in seen:
            raise ValueError('duplicate order')
        seen.add(oid)
        try:
            parsed = datetime.date.fromisoformat(due)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if parsed.isoformat() != due or not isinstance(order['items'], list):
            raise ValueError('invalid order fields')
        for item in order['items']:
            if not isinstance(item, dict) or any((k not in item for k in ('sku', 'size', 'color', 'quantity'))):
                raise ValueError('invalid item')
            sku, size, color, quantity = (item[k] for k in ('sku', 'size', 'color', 'quantity'))
            if any((not isinstance(x, str) or not x for x in (sku, size, color))):
                raise ValueError('invalid item')
            if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
                raise ValueError('invalid quantity')
            key = (oid, sku, size, color)
            if key not in grouped:
                grouped[key] = {'order_id': oid, 'customer': customer, 'due_date': due, 'sku': sku, 'size': size, 'color': color, 'quantity': 0}
            grouped[key]['quantity'] += quantity
    result = list(grouped.values())
    result.sort(key=lambda r: (datetime.date.fromisoformat(r['due_date']), r['order_id'], r['sku'], r['size'], r['color']))
    return result

def export_orders(orders: list[dict], destination: str) -> int:
    rows = summarize_orders(orders)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='orders-', suffix='.csv', dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['order_id', 'customer', 'due_date', 'sku', 'size', 'color', 'quantity'])
            for row in rows:
                writer.writerow([row[k] for k in ('order_id', 'customer', 'due_date', 'sku', 'size', 'color', 'quantity')])
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

