import re
import secrets
import string
from functools import cmp_to_key
_PATTERN = re.compile('^v?(\\d+)\\.(\\d+)\\.(\\d+)(?:-([0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*))?$')
_ALPHABET = string.ascii_letters + string.digits

def parse_version(value: str) -> tuple[int, int, int, tuple[str, ...]]:
    if not isinstance(value, str):
        raise TypeError('version must be a string')
    match = _PATTERN.fullmatch(value)
    if not match:
        raise ValueError('invalid version')
    numbers = match.group(1, 2, 3)
    if any((len(x) > 1 and x[0] == '0' for x in numbers)):
        raise ValueError('invalid numeric component')
    pre = tuple(match.group(4).split('.')) if match.group(4) else ()
    for item in pre:
        if item.isdigit() and len(item) > 1 and (item[0] == '0'):
            raise ValueError('invalid prerelease number')
    return (int(numbers[0]), int(numbers[1]), int(numbers[2]), pre)

def _compare(a, b):
    pa, pb = (parse_version(a), parse_version(b))
    if pa[:3] != pb[:3]:
        return -1 if pa[:3] < pb[:3] else 1
    xa, xb = (pa[3], pb[3])
    if not xa or not xb:
        return (not xa) - (not xb)
    for left, right in zip(xa, xb):
        if left == right:
            continue
        ln, rn = (left.isdigit(), right.isdigit())
        if ln and rn:
            return -1 if int(left) < int(right) else 1
        if ln != rn:
            return -1 if ln else 1
        return -1 if left < right else 1
    return (len(xa) > len(xb)) - (len(xa) < len(xb))

def order_versions(values: list[str]) -> list[str]:
    for value in values:
        parse_version(value)
    return sorted(values, key=cmp_to_key(lambda a, b: _compare(a, b) or (-1 if a < b else 1 if a > b else 0)))

def latest_version(values: list[str]) -> str:
    if not values:
        raise ValueError('no versions')
    return order_versions(values)[-1]

def issue_revision(version: str, existing_ids: set[str]) -> str:
    if not isinstance(existing_ids, set):
        raise TypeError('existing_ids must be a set')
    major, minor, patch, pre = parse_version(version)
    canonical = f'v{major}.{minor}.{patch}' + ('-' + '.'.join(pre) if pre else '')
    while True:
        code = ''.join((secrets.choice(_ALPHABET) for _ in range(12)))
        result = canonical + '-' + code
        if result not in existing_ids:
            return result

