    payload = json.dumps({
        "event": "customer.updated",
        "customer_id": 42,
        "fields": {"name": "Ada", "status": "active"}
    }, separators=(",", ":"))
    signature = make_signature(payload, "crm-key")

    result = process_customer_webhook(payload, signature, "crm-key")

    assert result == {
        "event": "customer.updated",
        "customer_id": 42,
        "fields": {"name": "Ada", "status": "active"}
    }


