import hashlib
import hmac
import os

def create_account(username: str, password: str, credits: int) -> dict:
    if not isinstance(username, str) or not isinstance(password, str):
        raise TypeError()
    if not username or not isinstance(credits, int) or isinstance(credits, bool) or (credits < 0):
        raise ValueError()
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
    stored = f'{rounds}${salt.hex()}${digest.hex()}'
    return {'username': username, 'credits': credits, 'password_hash': stored}

def verify_password(password: str, stored_value: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored_value, str):
        return False
    try:
        rounds_text, salt_text, digest_text = stored_value.split('$')
        rounds = int(rounds_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def transfer_credits(account: dict, password: str, amount: int) -> int:
    if not verify_password(password, account.get('password_hash', '')):
        raise PermissionError()
    if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
        raise ValueError()
    if amount > account['credits']:
        raise ValueError()
    account['credits'] -= amount
    return account['credits']

