from datetime import date, datetime
from typing import Any

def summarize_production(requester: dict[str, Any], sites: list[dict[str, Any]], readings: list[dict[str, Any]], start: str, end: str, page: int, page_size: int) -> list[dict[str, Any]]:
    try:
        first = date.fromisoformat(start)
        last = date.fromisoformat(end)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    if first > last or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid arguments')
    ids = [site['id'] for site in sites]
    if len(ids) != len(set(ids)):
        raise ValueError('duplicate site')
    allowed = []
    for site in sites:
        if not (site['tenant_id'] == requester['tenant_id'] and (site['owner_id'] == requester['id'] or any((role in ('operator', 'manager') for role in requester.get('roles', []))))):
            raise PermissionError('not permitted')
        allowed.append(site)
    totals = {site['id']: [0.0, 0] for site in allowed}
    for reading in readings:
        try:
            stamp = datetime.fromisoformat(reading['timestamp'].replace('Z', '+00:00'))
            site_id = reading['site_id']
            value = reading['kwh']
        except (KeyError, TypeError, ValueError, AttributeError) as exc:
            raise ValueError('malformed reading') from exc
        if site_id in totals and first <= stamp.date() <= last:
            try:
                totals[site_id][0] += float(value)
            except (TypeError, ValueError) as exc:
                raise ValueError('malformed reading') from exc
            totals[site_id][1] += 1
    result = [{'site_id': site['id'], 'name': site['name'], 'kwh': round(totals[site['id']][0], 2), 'reading_count': totals[site['id']][1]} for site in allowed]
    result.sort(key=lambda item: (-item['kwh'], item['name'], item['site_id']))
    begin = (page - 1) * page_size
    return result[begin:begin + page_size]

