import ast
import operator

def rank_treatments(records: list[dict], expression: str, min_score: float=0.0, limit: int=10) -> list[tuple[str, float]]:
    if limit < 0:
        raise ValueError('limit must not be negative')
    tree = ast.parse(expression, mode='eval').body
    variables = {'area_m2', 'efficacy', 'cost', 'severity'}
    functions = {'min': min, 'max': max, 'round': round}

    def ev(node, env):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            return env[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = ev(node.operand, env)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = ev(node.values[0], env)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not value:
                        return value
                elif value:
                    return value
                value = ev(child, env)
            return value
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            left, right = (ev(node.left, env), ev(node.right, env))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.Compare):
            left = ev(node.left, env)
            result = True
            ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            for op, child in zip(node.ops, node.comparators):
                right = ev(child, env)
                result = result and ops[type(op)](left, right)
                left = right
            return result
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
            return functions[node.func.id](*(ev(arg, env) for arg in node.args))
        raise ValueError('unsupported expression')
    result = []
    for record in records:
        env = {name: record[name] for name in variables}
        score = float(ev(tree, env))
        if score >= min_score:
            result.append((record['id'], score))
    result.sort(key=lambda item: (-item[1], item[0]))
    return result[:limit]

