from pathlib import Path

def aggregate_supplier_scores(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        supplier = record.get('supplier')
        if not isinstance(supplier, str) or not supplier:
            raise ValueError('invalid supplier')
        values = []
        for key in ('quality', 'delivery', 'cost'):
            value = record.get(key)
            if isinstance(value, bool) or not isinstance(value, (int, float)) or (not 0 <= value <= 100):
                raise ValueError('invalid score')
            values.append(value)
        score = values[0] * 0.5 + values[1] * 0.3 + values[2] * 0.2
        groups.setdefault(supplier, []).append(score)
    result = []
    for supplier, scores in groups.items():
        result.append({'supplier': supplier, 'count': len(scores), 'average_score': round(sum(scores) / len(scores), 2)})
    result.sort(key=lambda item: (-item['average_score'], item['supplier']))
    return result

def write_supplier_report(base_dir, relative_name, records):
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid filename')
    base = Path(base_dir).resolve()
    destination = (base / relative_name).resolve()
    if destination != base and base not in destination.parents:
        raise ValueError('invalid filename')
    destination.parent.mkdir(parents=True, exist_ok=True)
    payload = {'suppliers': aggregate_supplier_scores(records)}
    destination.write_text(json.dumps(payload, indent=2, sort_keys=True) + '\n', encoding='utf-8')
    return destination

