import os
import json
import math
import hmac
import hashlib
from datetime import date, timedelta

def normalize_records(records):
    result = []
    for row in records:
        if not isinstance(row, dict) or set(row) != {'aircraft', 'date', 'hours', 'action', 'parts'}:
            raise ValueError('invalid record fields')
        if not isinstance(row['aircraft'], str) or not row['aircraft'] or (not isinstance(row['action'], str)) or (not row['action']):
            raise ValueError('invalid text field')
        try:
            date.fromisoformat(row['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        hours = row['hours']
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or (not math.isfinite(hours)) or (hours < 0):
            raise ValueError('invalid hours')
        if not isinstance(row['parts'], list) or not all((isinstance(x, str) for x in row['parts'])):
            raise ValueError('invalid parts')
        result.append({'aircraft': row['aircraft'], 'date': row['date'], 'hours': hours, 'action': row['action'], 'parts': sorted(row['parts'])})
    return result

def build_manifest(records, config=None):
    normalized = normalize_records(records)
    ordered = [dict(p[1]) for p in sorted(enumerate(normalized), key=lambda p: (p[1]['aircraft'], p[1]['date'], p[1]['action'], p[0]))]
    for x in ordered:
        x['parts'] = list(x['parts'])
    groups = {}
    for row in ordered:
        groups.setdefault(row['aircraft'], []).append(row)
    summary = [{'aircraft': name, 'events': len(rows), 'total_hours': round(sum((r['hours'] for r in rows)), 2), 'last_date': max((r['date'] for r in rows))} for name, rows in groups.items()]
    payload = {'records': ordered, 'summary': summary}
    key = config['signing_key'] if config is not None and 'signing_key' in config else os.environ.get('AIRCRAFT_MAINTENANCE_KEY')
    if not isinstance(key, str):
        raise ValueError('signing key is required')
    raw = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    return {**payload, 'signature': hmac.new(key.encode(), raw, hashlib.sha256).hexdigest()}

def maintenance_windows(records, window_days=30):
    if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days <= 0:
        raise ValueError('window_days must be positive')
    rows = normalize_records(records)
    by_aircraft = {}
    for row in rows:
        by_aircraft.setdefault(row['aircraft'], []).append(row)
    output = []
    for aircraft in sorted(by_aircraft):
        group = by_aircraft[aircraft]
        windows = []
        for start in sorted({r['date'] for r in group}):
            begin = date.fromisoformat(start)
            end = begin + timedelta(days=window_days - 1)
            selected = [r for r in group if begin <= date.fromisoformat(r['date']) <= end]
            windows.append({'date': start, 'hours': round(sum((r['hours'] for r in selected)), 2), 'events': len(selected)})
        output.append({'aircraft': aircraft, 'windows': windows})
    return output

