import ast

def search_clauses(records: list[dict], condition: str, ranking: str='score', page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid page')
    allowed = {'score', 'amount', 'term_years', 'year'}
    functions = {'min': min, 'max': max, 'round': round}

    def make_tree(text):
        try:
            return ast.parse(text, mode='eval').body
        except SyntaxError as exc:
            raise ValueError('invalid expression') from exc

    def evaluate(node, env):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in allowed:
                raise NameError(node.id)
            return env[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, env)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a, b = (evaluate(node.left, env), evaluate(node.right, env))
            return a + b if isinstance(node.op, ast.Add) else a - b if isinstance(node.op, ast.Sub) else a * b if isinstance(node.op, ast.Mult) else a / b
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = evaluate(node.values[0], env)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = evaluate(item, env)
            return value
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, env)
            for op, part in zip(node.ops, node.comparators):
                right = evaluate(part, env)
                ok = left == right if isinstance(op, ast.Eq) else left != right if isinstance(op, ast.NotEq) else left < right if isinstance(op, ast.Lt) else left <= right if isinstance(op, ast.LtE) else left > right if isinstance(op, ast.Gt) else left >= right
                if not ok:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
            return functions[node.func.id](*(evaluate(x, env) for x in node.args))
        raise ValueError('invalid expression')
    condition_tree, ranking_tree = (make_tree(condition), make_tree(ranking))
    matched = []
    for record in records:
        env = {name: record[name] for name in allowed}
        if evaluate(condition_tree, env):
            matched.append((evaluate(ranking_tree, env), record))
    matched.sort(key=lambda item: (-item[0], item[1]['id']))
    start = (page - 1) * page_size
    return [record for _, record in matched[start:start + page_size]]

