import xml.etree.ElementTree as ET

def parse_survey(xml_text: str) -> dict[str, list[str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'survey':
        raise ValueError('invalid root')
    result: dict[str, list[str]] = {}
    for element in root.iter('response'):
        question = element.get('question')
        if question is None:
            raise ValueError('response is missing question')
        answer = ''.join(element.itertext()).strip()
        result.setdefault(question, []).append(answer)
    return result

