import calendar
import hashlib
import hmac
import json
import math

def process_equipment_webhook(payload: str, signature: str, secret: str) -> dict | None:
    try:
        supplied = bytes.fromhex(signature)
    except (TypeError, ValueError):
        return None
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).digest()
    if len(supplied) != len(expected) or not hmac.compare_digest(supplied, expected):
        return None
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('records'), list):
        raise ValueError('invalid records')
    totals = {}
    for record in data['records']:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('equipment_id'), str) or not record['equipment_id']:
            raise ValueError('invalid equipment')
        if not isinstance(record.get('employee'), str):
            raise ValueError('invalid employee')
        hours = record.get('hours')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or (not math.isfinite(hours)) or (hours < 0):
            raise ValueError('invalid hours')
        if record.get('status') not in ('assigned', 'returned'):
            raise ValueError('invalid status')
        date = record.get('date')
        if not isinstance(date, str) or len(date) != 10 or date[4] != '-' or (date[7] != '-'):
            raise ValueError('invalid date')
        try:
            year, month, day = (int(date[:4]), int(date[5:7]), int(date[8:]))
            if month < 1 or month > 12 or day < 1 or (day > calendar.monthrange(year, month)[1]):
                raise ValueError
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        item = totals.setdefault(record['equipment_id'], [0.0, 0])
        item[0] += hours
        item[1] += 1
    equipment = [{'equipment_id': key, 'hours': round(value[0], 2), 'records': value[1]} for key, value in totals.items()]
    equipment.sort(key=lambda item: (-item['hours'], item['equipment_id']))
    return {'total_hours': round(sum((value[0] for value in totals.values())), 2), 'equipment': equipment}

