import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError('unknown name')
        return values[node.id]
    if isinstance(node, ast.BinOp):
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        if type(node.op) not in ops:
            raise ValueError('unsupported operator')
        return ops[type(node.op)](_evaluate(node.left, values), _evaluate(node.right, values))
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _evaluate(node.operand, values)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        result = _evaluate(node.values[0], values)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                return result
            result = _evaluate(item, values)
        return result
    if isinstance(node, ast.Compare):
        ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}
        left = _evaluate(node.left, values)
        for op, part in zip(node.ops, node.comparators):
            if type(op) not in ops:
                raise ValueError('unsupported comparison')
            right = _evaluate(part, values)
            if not ops[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(a, values) for a in node.args])
    raise ValueError('unsupported expression')

def match_invoices(invoices: list[dict], rule: str) -> list[dict]:
    try:
        tree = ast.parse(rule, mode='eval')
    except Exception as exc:
        raise ValueError('invalid rule') from exc
    result = []
    for invoice in invoices:
        try:
            amount = invoice['amount']
            tax = invoice['tax']
            due_days = invoice['due_days']
            values = {'amount': amount, 'tax': tax, 'total': amount + tax, 'due_days': due_days}
            if _evaluate(tree.body, values):
                result.append(invoice)
        except Exception as exc:
            raise ValueError('invalid invoice or rule') from exc
    return result

