import os
import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from io import StringIO

def subscription_report(path: str, page: int=1, page_size: int=10) -> list[tuple[str, int, int]]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be a positive integer')
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    result = subprocess.run(['sort', '-t,', '-k1,1', path], capture_output=True, text=True, check=True)
    totals = {}
    for row in csv.reader(StringIO(result.stdout)):
        if not row or all((not field.strip() for field in row)):
            continue
        if len(row) != 4:
            raise ValueError('malformed row')
        course, user, status, amount_text = [field.strip() for field in row]
        if not course or not user or status not in ('active', 'cancelled'):
            raise ValueError('invalid row')
        try:
            amount = Decimal(amount_text)
        except InvalidOperation as exc:
            raise ValueError('invalid amount') from exc
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid amount')
        cents = int((amount * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        if status == 'active':
            count, total = totals.get(course, (0, 0))
            totals[course] = (count + 1, total + cents)
    ordered = [(course, values[0], values[1]) for course, values in sorted(totals.items())]
    start = (page - 1) * page_size
    return ordered[start:start + page_size]

