def fetch_findings(dependencies: list[str], ecosystem: str='PyPI', min_score: float=0.0) -> list[dict]:
    if not isinstance(dependencies, list) or any((not isinstance(x, str) or not x for x in dependencies)):
        raise ValueError('invalid dependencies')
    if not isinstance(ecosystem, str) or not ecosystem:
        raise ValueError('invalid ecosystem')
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not 0 <= min_score <= 10):
        raise ValueError('invalid score')
    if not dependencies:
        return []
    body = {'queries': [{'package': {'name': name, 'ecosystem': ecosystem}} for name in dependencies]}
    response = requests.post('https://api.osv.dev/v1/querybatch', json=body, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('OSV request failed')
    data = response.json()
    findings = {}
    for package, result in zip(dependencies, data.get('results', [])):
        for vulnerability in result.get('vulnerabilities', []):
            identifier = vulnerability.get('id')
            if not isinstance(identifier, str) or not identifier:
                raise ValueError('invalid vulnerability id')
            scores = []
            for severity in vulnerability.get('severity', []):
                try:
                    value = float(severity.get('score'))
                    if 0 <= value <= 10:
                        scores.append(value)
                except (TypeError, ValueError):
                    pass
            score = max(scores, default=0.0)
            if score < min_score:
                continue
            item = {'package': package, 'id': identifier, 'summary': vulnerability.get('summary', ''), 'score': score}
            key = (package, identifier)
            if key not in findings or score > findings[key]['score']:
                findings[key] = item
    return sorted(findings.values(), key=lambda x: (-x['score'], x['package'], x['id']))

