import secrets
from datetime import datetime, timezone
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def create_invite_code(length: int=12) -> str:
    if type(length) is not int or not 8 <= length <= 64:
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def _timestamp(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        result = datetime.fromisoformat(value[:-1] + '+00:00')
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if result.tzinfo is None or result.utcoffset() != timezone.utc.utcoffset(result):
        raise ValueError('invalid timestamp')
    return result.astimezone(timezone.utc)

def _fields(line: str) -> list[str]:
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current))
    return fields

def parse_membership_events(lines: list[str]) -> list[dict[str, object]]:
    result = []
    for index, line in enumerate(lines):
        fields = _fields(line)
        if len(fields) != 4 or not fields[1]:
            raise ValueError('invalid record')
        timestamp = _timestamp(fields[0])
        action = fields[2]
        if action not in {'join', 'renew', 'cancel'}:
            raise ValueError('invalid action')
        try:
            months = int(fields[3])
