            if node.attrib['status'] == 'completed' and duration >= 30:
                agent = node.attrib['agent']
                item = grouped.setdefault(agent, [0, 0])
                item[0] += 1
                item[1] += duration
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    ordered = sorted(grouped.items(), key=lambda pair: (-pair[1][1], pair[0]))
    total_calls = sum((value[0] for value in grouped.values()))
