import hmac
import os

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and len(pin) == 4 and all(('0' <= c <= '9' for c in pin))

def create_enrollment(employee_id: str, plan: str, pin: str) -> dict[str, str]:
    if not isinstance(employee_id, str) or not employee_id.strip():
        raise ValueError('employee_id must not be empty')
    if plan not in {'basic', 'standard', 'premium'}:
        raise ValueError('invalid plan')
    if not _valid_pin(pin):
        raise ValueError('PIN must contain four ASCII digits')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'employee_id': employee_id, 'plan': plan, 'credential': salt.hex() + ':' + digest.hex()}

def verify_enrollment_pin(enrollment: dict[str, str], pin: str) -> bool:
    if not _valid_pin(pin) or not isinstance(enrollment, dict):
        return False
    try:
        salt_text, digest_text = enrollment['credential'].split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (KeyError, TypeError, ValueError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

