import csv
from pathlib import Path

def write_call_detail_report(base_dir: str, relative_name: str, calls: list[dict[str, object]]) -> str:
    if not relative_name or not relative_name.lower().endswith('.csv'):
        raise ValueError('report name must be a non-empty CSV filename')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('report path is outside the base directory')
    if target == base:
        raise ValueError('report name must identify a file')
    target.parent.mkdir(parents=True, exist_ok=True)
    fields = ['caller', 'callee', 'started_at', 'duration_seconds', 'disposition']
    with target.open('w', encoding='utf-8', newline='') as handle:
        writer = csv.writer(handle)
        writer.writerow(fields)
        for call in calls:
            writer.writerow([call[field] for field in fields])
    return str(target)

