import html
import math

def render_dispatch_report(records: list[dict], page: int=1, page_size: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    totals = {}
    for record in records:
        if not isinstance(record, dict) or not all((key in record for key in ('site', 'energy_mwh', 'price_per_mwh'))):
            raise ValueError('invalid record')
        site = record['site']
        energy = record['energy_mwh']
        price = record['price_per_mwh']
        if not isinstance(site, str):
            raise ValueError('invalid site')
        for value in (energy, price):
            if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) or (value < 0):
                raise ValueError('invalid number')
        if site not in totals:
            totals[site] = [0.0, 0.0]
        totals[site][0] += energy
        totals[site][1] += energy * price
    ordered = sorted(totals.items(), key=lambda item: (-item[1][1], item[0]))
    start = (page - 1) * page_size
    rows = [f'<tr><td>{html.escape(site, quote=True)}</td><td>{energy:.2f}</td><td>${revenue:.2f}</td></tr>' for site, (energy, revenue) in ordered[start:start + page_size]]
    return '<table>\n<thead><tr><th>Site</th><th>Energy (MWh)</th><th>Revenue</th></tr></thead>\n<tbody>\n' + '\n'.join(rows) + '\n</tbody>\n</table>'

