import ast
import operator

class _Evaluator(ast.NodeVisitor):

    def __init__(self, names):
        self.names = names

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_Constant(self, node):
        if isinstance(node.value, (int, float, bool)):
            return node.value
        raise ValueError('unsupported expression')

    def visit_Name(self, node):
        if node.id in self.names:
            return self.names[node.id]
        raise NameError(node.id)

    def visit_UnaryOp(self, node):
        value = self.visit(node.operand)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.Not):
            return not value
        raise ValueError('unsupported expression')

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
        raise ValueError('unsupported expression')

    def visit_BoolOp(self, node):
        if isinstance(node.op, ast.And):
            value = True
            for item in node.values:
                value = self.visit(item)
                if not value:
                    return value
            return value
        if isinstance(node.op, ast.Or):
            for item in node.values:
                value = self.visit(item)
                if value:
                    return value
            return value
        raise ValueError('unsupported expression')

    def visit_Compare(self, node):
        left = self.visit(node.left)
        for op, item in zip(node.ops, node.comparators):
            right = self.visit(item)
            if isinstance(op, ast.Lt):
                ok = left < right
            elif isinstance(op, ast.LtE):
                ok = left <= right
            elif isinstance(op, ast.Gt):
                ok = left > right
            elif isinstance(op, ast.GtE):
                ok = left >= right
            elif isinstance(op, ast.Eq):
                ok = left == right
            elif isinstance(op, ast.NotEq):
                ok = left != right
            else:
                raise ValueError('unsupported expression')
            if not ok:
                return False
            left = right
        return True

    def visit_Call(self, node):
        if not isinstance(node.func, ast.Name) or node.func.id not in ('min', 'max', 'round') or node.keywords:
            raise ValueError('unsupported expression')
        args = [self.visit(x) for x in node.args]
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)

    def generic_visit(self, node):
        if isinstance(node, ast.BinOp):
            return self.visit_BinOp(node)
        raise ValueError('unsupported expression')

def _value(formula, names):
    tree = ast.parse(formula, mode='eval')
    return _Evaluator(names).visit(tree)

def build_continuity_report(records: list[dict], formula: str, variables: dict) -> dict:
    rows = []
    for record in records:
        names = dict(record)
        names.update(variables)
        score = _value(formula, names)
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise ValueError('score is not numeric')
        rows.append({'id': record['id'], 'score': score, 'passed': score >= variables['pass_mark']})
    rows.sort(key=lambda row: (-row['score'], row['id']))
    scores = [row['score'] for row in rows]
    return {'results': rows, 'passed_count': sum((row['passed'] for row in rows)), 'average_score': round(sum(scores) / len(scores), 2) if scores else None, 'worst_id': min(rows, key=lambda row: (row['score'], row['id']))['id'] if rows else None}

