def pack_scores(entries: list[dict[str, int | str]]) -> bytes:
    if not isinstance(entries, list):
        raise ValueError('entries must be a list')
    for entry in entries:
        if not isinstance(entry, dict) or set(entry) != {'player', 'score'}:
            raise ValueError('invalid record')
        if not isinstance(entry['player'], str) or not entry['player']:
            raise ValueError('invalid player')
        if isinstance(entry['score'], bool) or not isinstance(entry['score'], int) or entry['score'] < 0:
            raise ValueError('invalid score')
    return json.dumps(entries, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def read_leaderboard(blob: bytes, offset: int=0, limit: int=10) -> list[dict[str, int | str]]:
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    try:
        data = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid data') from exc
    try:
        pack_scores(data)
    except Exception as exc:
        raise ValueError('invalid records') from exc
    best = {}
