def parse_registration(payload: str, token: str, league_token: str) -> dict:
    if not hmac.compare_digest(token, league_token):
        raise ValueError('invalid league token')
    parts = payload.split('|')
    if len(parts) != 3:
        raise ValueError('invalid registration')
    team, division, raw_players = (part.strip() for part in parts)
    players = [player.strip() for player in raw_players.split(',')]
    if not team or not division or (not players) or any((not player for player in players)):
        raise ValueError('invalid registration')
    return {'team': team, 'division': division, 'players': sorted(players)}

