import hashlib
import hmac

def verify_collar_packet(packet: str, secret: str) -> dict[str, object]:
    fields = packet.split('|')
    if len(fields) != 5:
        raise ValueError('invalid packet')
    collar_id, timestamp_text, latitude_text, longitude_text, signature = fields
    if not collar_id:
        raise ValueError('invalid collar id')
    try:
        timestamp = int(timestamp_text)
        latitude = float(latitude_text)
        longitude = float(longitude_text)
    except ValueError as exc:
        raise ValueError('invalid field') from exc
    payload = '|'.join(fields[:4]).encode()
    try:
        provided = bytes.fromhex(signature)
    except ValueError:
        return False
    expected = hmac.new(secret.encode(), payload, hashlib.sha256).digest()
    if not hmac.compare_digest(provided, expected):
        return False
    return {'collar_id': collar_id, 'timestamp': timestamp, 'latitude': latitude, 'longitude': longitude}

