import xml.etree.ElementTree as ET

def read_routes(xml_text: str) -> list[tuple[str, str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'backup':
        raise ValueError('unexpected root element')
    routes = []
    for device in root.findall('device'):
        name = device.get('name')
        if name is None:
            raise ValueError('missing device name')
        for route in device.findall('route'):
            destination = route.get('destination')
            gateway = route.get('gateway')
            if destination is None or gateway is None:
                raise ValueError('missing route attribute')
            routes.append((name, destination, gateway))
    return sorted(routes)

