import xml.sax.handler

class _RouteHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        self.routes = []
        self.device_name = None
        self.root_name = None
        self.depth = 0

    def startElement(self, name, attrs):
        if self.depth == 0:
            self.root_name = name
        self.depth += 1
        if name == 'device':
            self.device_name = attrs.get('name')
            if self.device_name is None:
                raise ValueError('missing device name')
        elif name == 'route':
            destination = attrs.get('destination')
            gateway = attrs.get('gateway')
            if destination is None or gateway is None:
                raise ValueError('missing route attribute')
            self.routes.append((self.device_name, destination, gateway))

    def endElement(self, name):
        self.depth -= 1

def read_routes(xml_text: str) -> list[tuple[str, str, str]]:
    handler = _RouteHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except (xml.sax.SAXException, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if handler.root_name != 'backup' or handler.depth != 0:
        raise ValueError('unexpected root element')
    return sorted(handler.routes)

