import re
from lxml import etree

def price_cart(xml: str, catalog: dict[str, int], coupons: dict[str, int]) -> dict[str, object]:
    if any((not isinstance(v, int) or isinstance(v, bool) or v < 0 for v in catalog.values())):
        raise ValueError('invalid catalog')
    if any((not isinstance(v, int) or isinstance(v, bool) or (not 0 <= v <= 100) for v in coupons.values())):
        raise ValueError('invalid coupons')
    try:
        parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
        root = etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'cart':
        raise ValueError('invalid root')
    currency = root.get('currency', 'USD')
    if not re.fullmatch('[A-Z]{3}', currency):
        raise ValueError('invalid currency')
    coupon = root.get('coupon')
    if coupon is not None and coupon not in coupons:
        raise ValueError('invalid coupon')
    quantities = {}
    order = []
    for child in root:
        if child.tag != 'item' or set(child.attrib) != {'sku', 'qty'}:
            raise ValueError('invalid item')
        sku = child.get('sku')
        qty_text = child.get('qty')
        if sku not in catalog or not re.fullmatch('[0-9]+', qty_text or ''):
            raise ValueError('invalid item')
        qty = int(qty_text)
        if qty <= 0:
            raise ValueError('invalid quantity')
        if sku not in quantities:
            quantities[sku] = 0
            order.append(sku)
        quantities[sku] += qty
    lines = []
    subtotal = 0
    for sku in order:
        quantity = quantities[sku]
        unit = catalog[sku]
        total = quantity * unit
        lines.append({'sku': sku, 'quantity': quantity, 'unit_price': unit, 'total': total})
        subtotal += total
    percentage = coupons[coupon] if coupon is not None else 0
    discount = subtotal * percentage // 100
    return {'currency': currency, 'lines': lines, 'subtotal': subtotal, 'discount': discount, 'total': subtotal - discount}

