        relative = os.path.relpath(raw_path, directory).replace(os.sep, '/')
        records.append({'name': os.path.basename(raw_path), 'path': relative, 'bytes': os.path.getsize(raw_path)})
    records.sort(key=lambda item: (-item['bytes'], item['path']))
    start = (page - 1) * page_size
    return records[start:start + page_size]

