    payload = make_payload(records)
    assert summarize_registrations(payload, signed(payload)) == {'total': 5, 'by_precinct': [{'precinct': 'A-10', 'registered': 1, 'pending': 0, 'rejected': 1}, {'precinct': 'A-2', 'registered': 1, 'pending': 1, 'rejected': 0}, {'precinct': 'Z-2', 'registered': 0, 'pending': 0, 'rejected': 1}]}

