import hashlib
import hmac
import json
SIGNING_SECRET = b'voter-registration-demo-key-2025'

def summarize_registrations(payload: str, signature: str) -> dict | None:
    if not isinstance(signature, str) or len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        return None
    expected = hmac.new(SIGNING_SECRET, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        return None
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('registrations'), list):
        raise ValueError('invalid registrations')
    records = {}
    for item in data['registrations']:
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        voter_id = item.get('voter_id')
        precinct = item.get('precinct')
        status = item.get('status')
        if not isinstance(voter_id, str) or not voter_id or (not isinstance(precinct, str)) or (not precinct) or (not isinstance(status, str)) or (status not in {'registered', 'pending', 'rejected'}):
            raise ValueError('invalid record')
        records[voter_id] = (precinct, status)
    groups = {}
    for precinct, status in records.values():
        if precinct not in groups:
            groups[precinct] = {'precinct': precinct, 'registered': 0, 'pending': 0, 'rejected': 0}
        groups[precinct][status] += 1
    return {'total': len(records), 'by_precinct': [groups[p] for p in sorted(groups)]}

