from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from html import escape
import math

def render_sync_report(transactions: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(transactions, list):
        raise ValueError('transactions must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or (not 1 <= per_page <= 100):
        raise ValueError('invalid per_page')
    normalized = []
    for item in transactions:
        if not isinstance(item, dict):
            raise ValueError('invalid transaction')
        for key in ('transaction_id', 'merchant', 'category', 'amount', 'date'):
            if key not in item:
                raise ValueError('missing field')
        if any((not isinstance(item[k], str) for k in ('transaction_id', 'merchant', 'category', 'date'))):
            raise ValueError('invalid field')
        try:
            parsed_date = date.fromisoformat(item['date'])
            amount = Decimal(str(item['amount']))
            if not amount.is_finite():
                raise ValueError('invalid amount')
            amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except (ValueError, InvalidOperation, TypeError):
            raise ValueError('invalid transaction')
        normalized.append((parsed_date, item['transaction_id'], item['merchant'], item['category'], amount))
    normalized.sort(key=lambda x: (-x[0].toordinal(), x[1]))
    total = sum((x[4] for x in normalized), Decimal('0.00'))
    categories = {}
    for item in normalized:
        categories[item[3]] = categories.get(item[3], Decimal('0.00')) + item[4]
    category_items = sorted(categories.items(), key=lambda x: (-x[1], x[0]))
    start = (page - 1) * per_page
    visible = normalized[start:start + per_page]
    money = lambda x: f'{x:.2f}'
    rows = ''.join((f'<tr><td>{escape(str(d))}</td><td>{escape(i)}</td><td>{escape(m)}</td><td>{escape(c)}</td><td>${money(a)}</td></tr>' for d, i, m, c, a in visible))
    items = ''.join((f'<li>{escape(c)}: ${money(a)}</li>' for c, a in category_items))
    return f'<section class="sync-report"><h1>Bank Synchronization Report</h1><p class="summary">Transactions: {len(normalized)} | Total: ${money(total)} | Page: {page}</p><table class="transactions"><thead><tr><th>Date</th><th>Transaction ID</th><th>Merchant</th><th>Category</th><th>Amount</th></tr></thead><tbody>{rows}</tbody></table><h2>Category Totals</h2><ul class="category-totals">{items}</ul></section>'

