import os
from datetime import datetime, timedelta

def _fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_schedule(content: str) -> list[dict]:
    result = []
    for raw in content.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        fields = _fields(raw)
        if len(fields) != 5 or not fields[0]:
            raise ValueError('invalid record')
        try:
            season = int(fields[1])
            episode = int(fields[2])
            start = datetime.strptime(fields[3], '%Y-%m-%d %H:%M')
            duration = int(fields[4])
        except (TypeError, ValueError):
            raise ValueError('invalid record')
        if season < 0 or episode < 0 or (not 1 <= duration <= 1440):
            raise ValueError('invalid record')
        result.append({'title': fields[0], 'season': season, 'episode': episode, 'start': start, 'duration': duration})
    return result

def schedule_summary(content: str, window_start: datetime, window_end: datetime) -> list[dict]:
    if window_start >= window_end:
        raise ValueError('invalid window')
    result = []
    for item in parse_schedule(content):
        end = item['start'] + timedelta(minutes=item['duration'])
        left = max(item['start'], window_start)
        right = min(end, window_end)
        if left < right:
            result.append({'title': item['title'], 'season': item['season'], 'episode': item['episode'], 'start': item['start'], 'end': end, 'minutes': int((right - left).total_seconds() // 60)})
    result.sort(key=lambda x: (x['start'], x['title'], x['season'], x['episode']))
    return result

def save_schedule(base_dir: str, relative_name: str, content: str) -> str:
    parse_schedule(content)
    if not relative_name:
        raise ValueError('invalid name')
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, target]) != base:
        raise ValueError('invalid name')
    if os.path.isdir(target):
        raise ValueError('invalid name')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        handle.write(content)
    return target

