import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if password == '':
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

def create_assessor(name: str, password: str, baseline_tons: float) -> dict[str, object]:
    if not isinstance(name, str):
        raise TypeError('name must be a string')
    if not name.strip():
        raise ValueError('name must not be blank')
    if isinstance(baseline_tons, bool) or not isinstance(baseline_tons, (int, float)):
        raise TypeError('baseline_tons must be numeric')
