def make_user(username: str, password: str) -> dict:
    if not isinstance(username, str) or not username:
        raise ValueError('invalid username')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username, 'password_hash': salt.hex() + '$' + digest.hex()}

def authenticate(user: dict, password: str) -> bool:
    if not isinstance(password, str) or not isinstance(user, dict):
        return False
    value = user.get('password_hash')
    if not isinstance(value, str) or '$' not in value:
        return False
    try:
        salt_text, digest_text = value.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_usage(samples: list[dict], start: int, end: int, page: int=1, page_size: int=10) -> list[dict]:
    if start > end or page < 1 or page_size < 1:
        raise ValueError('invalid range or page')
    groups = {}
    for record in samples:
        if any((key not in record for key in ('user', 'timestamp', 'bytes'))):
            raise ValueError('missing field')
        user = record['user']
        timestamp = record['timestamp']
        amount = record['bytes']
        if not isinstance(user, str) or not user or (not isinstance(timestamp, int)) or isinstance(timestamp, bool) or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount < 0):
            raise ValueError('invalid record')
        if start <= timestamp < end:
            total, count = groups.get(user, (0, 0))
            groups[user] = (total + amount, count + 1)
    result = [{'user': user, 'total_bytes': total, 'samples': count, 'average_bytes': round(total / count, 2)} for user, (total, count) in groups.items()]
    result.sort(key=lambda item: (-item['total_bytes'], item['user']))
    first = (page - 1) * page_size
    return result[first:first + page_size]

