from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_donations(requester: dict, donations: list[dict], fiscal_year: int, page: int=1, page_size: int=20) -> dict:
    if not isinstance(fiscal_year, int) or isinstance(fiscal_year, bool) or (not 1 <= fiscal_year <= 9999):
        raise ValueError('invalid year')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    roles = requester.get('roles', [])
    if not ('finance_reporter' in roles or 'director' in roles):
        raise PermissionError('reporting not permitted')
    organization_id = requester.get('organization_id')
    groups = {}
    for donation in donations:
        try:
            donation_date = date.fromisoformat(donation['date'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid date')
        try:
            amount = Decimal(str(donation['amount']))
        except (KeyError, TypeError, InvalidOperation):
            raise ValueError('invalid amount')
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid amount')
        program = donation.get('program')
        if not isinstance(program, str) or not program:
            raise ValueError('invalid program')
        cents = int((amount * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        if donation.get('organization_id') == organization_id and donation_date.year == fiscal_year:
            item = groups.setdefault(program, [0, 0])
            item[0] += cents
            item[1] += 1
    rows = [{'program': name, 'cents': values[0], 'count': values[1]} for name, values in groups.items()]
    rows.sort(key=lambda row: (-row['cents'], row['program']))
    total_pages = (len(rows) + page_size - 1) // page_size
    start = (page - 1) * page_size
    return {'year': fiscal_year, 'total_cents': sum((row['cents'] for row in rows)), 'programs': rows[start:start + page_size], 'page': page, 'page_size': page_size, 'total_pages': total_pages}

