def latest_active_vessel_reports(xml_text: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(xml_text, str) or isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid arguments')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
        if root.tag != 'reports':
            raise ValueError('invalid root')
        latest = {}
        for report in root.findall('report'):
            vessel = report.get('vessel')
            timestamp = report.get('timestamp')
            status = report.get('status')
            pos = report.find('position')
            fuel = report.find('fuel_remaining')
            if None in (vessel, timestamp, status) or pos is None or fuel is None or (pos.get('lat') is None) or (pos.get('lon') is None) or (fuel.text is None):
                raise ValueError('missing field')
            if status != 'active':
                continue
            item = {'vessel': vessel, 'timestamp': timestamp, 'latitude': round(float(pos.get('lat')), 2), 'longitude': round(float(pos.get('lon')), 2), 'fuel_remaining': round(float(fuel.text), 2)}
            if vessel not in latest or timestamp >= latest[vessel]['timestamp']:
                latest[vessel] = item
    except ValueError:
        raise
    except (etree.XMLSyntaxError, TypeError, AttributeError, OverflowError):
        raise ValueError('invalid XML')
    values = sorted(latest.values(), key=lambda x: (-x['timestamp'].__len__(), x['timestamp'], x['vessel']))
    values.sort(key=lambda x: x['vessel'])
    values.sort(key=lambda x: x['timestamp'], reverse=True)
    start = (page - 1) * page_size
    return values[start:start + page_size]

