import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def build_pickup_manifest(orders: list[dict], page: int=1, page_size: int=10) -> dict:
    token = os.environ.get('CURBSIDE_API_TOKEN')
    if not token:
        raise RuntimeError('CURBSIDE_API_TOKEN is required')
    if not isinstance(orders, list) or isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid arguments')
    groups = {}
    for order in orders:
        if not isinstance(order, dict) or not isinstance(order.get('id'), str) or (not order['id']) or (not isinstance(order.get('status'), str)) or (not isinstance(order.get('pickup_slot'), str)) or (not order['pickup_slot']) or (not isinstance(order.get('items'), list)):
            raise ValueError('invalid order')
        for item in order['items']:
            if not isinstance(item, dict) or not isinstance(item.get('name'), str) or (not item['name']) or isinstance(item.get('quantity'), bool) or (not isinstance(item.get('quantity'), int)) or (item['quantity'] <= 0):
                raise ValueError('invalid item')
            try:
                price = Decimal(str(item['unit_price']))
                if price < 0 or not price.is_finite():
                    raise ValueError('invalid item')
            except (InvalidOperation, ValueError, TypeError):
                raise ValueError('invalid item')
        if order['status'] == 'ready':
            groups.setdefault(order['pickup_slot'], []).append(order)
    slots = []
    for slot in sorted(groups):
        output_orders = []
        for order in sorted(groups[slot], key=lambda x: x['id']):
            combined = {}
            for item in order['items']:
                cents = int((Decimal(str(item['unit_price'])) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
                entry = combined.setdefault(item['name'], [0, 0])
                entry[0] += item['quantity']
                entry[1] += cents * item['quantity']
            items = [{'name': name, 'quantity': combined[name][0], 'total_cents': combined[name][1]} for name in sorted(combined)]
            output_orders.append({'id': order['id'], 'items': items, 'total_cents': sum((x['total_cents'] for x in items))})
        slots.append({'slot': slot, 'orders': output_orders, 'total_cents': sum((x['total_cents'] for x in output_orders))})
    start = (page - 1) * page_size
    return {'headers': {'Authorization': 'Bearer ' + token}, 'page': page, 'page_size': page_size, 'slots': slots[start:start + page_size], 'has_next': start + page_size < len(slots)}

