            raise ValueError('invalid row')
        row = [x.strip() for x in row]
        if row[3] not in _STATUSES:
            raise ValueError('invalid status')
        _date(row[4])
        result.append(dict(zip(_FIELDS, row)))
    return result

def summarize_notifications(records: list[dict], as_of: str) -> list[dict]:
    cutoff = _date(as_of)
    groups = {}
    for r in records:
        if any((k not in r for k in _FIELDS)):
            raise ValueError('missing field')
        if r['status'] not in _STATUSES:
