import html

def _split_line(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_plot_records(text: str) -> list[dict]:
    result = []
    for line_number, raw in enumerate(text.splitlines(), 1):
        if not raw.strip():
            continue
        try:
            fields = _split_line(raw)
            if len(fields) != 5:
                raise ValueError('wrong field count')
            section, plot_text, status, name, year_text = fields
            if not section or not plot_text:
                raise ValueError('empty section or plot')
            plot = int(plot_text)
            if plot <= 0 or str(plot) != plot_text:
                raise ValueError('invalid plot')
            if status not in {'occupied', 'vacant', 'reserved'}:
                raise ValueError('invalid status')
            if status == 'occupied':
                if not name or len(year_text) != 4 or (not year_text.isdigit()):
                    raise ValueError('invalid occupied record')
                year = int(year_text)
                if not 1000 <= year <= 9999:
                    raise ValueError('invalid year')
            else:
                if year_text:
                    raise ValueError('unexpected year')
                year = None
            result.append({'section': section, 'plot': plot, 'status': status, 'name': name, 'year': year})
        except (ValueError, OverflowError):
            raise ValueError(f'invalid record on line {line_number}') from None
    return result

def summarize_by_section(records: list[dict]) -> dict[str, dict[str, int | None]]:
    grouped = {}
    for record in records:
        section = record['section']
        if section not in grouped:
            grouped[section] = {'occupied': 0, 'vacant': 0, 'reserved': 0, 'latest_year': None}
        item = grouped[section]
        item[record['status']] += 1
        if record['year'] is not None and (item['latest_year'] is None or record['year'] > item['latest_year']):
            item['latest_year'] = record['year']
    return {key: grouped[key] for key in sorted(grouped)}

def render_cemetery_report(records: list[dict], title: str) -> str:
    rows = []
    for record in sorted(records, key=lambda item: (item['section'], item['plot'])):
        values = [record['section'], str(record['plot']), record['status'], record['name'], '' if record['year'] is None else str(record['year'])]
        rows.append('<tr>' + ''.join(('<td>' + html.escape(value) + '</td>' for value in values)) + '</tr>')
    sections = len({record['section'] for record in records})
    return '<section><h1>' + html.escape(title) + f'</h1><p>{sections} sections, {len(records)} plots</p><table><thead><tr><th>Section</th><th>Plot</th><th>Status</th><th>Name</th><th>Year</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></section>'

