import pytest

def test_evaluate_arithmetic_and_variables():
    variables = {'severity': 8, 'age': 3}
    assert evaluate_rule('severity * 2 + age / 2', variables) == 17.5
    assert evaluate_rule('severity >= 8 and age < 5', variables) is True

def test_evaluate_chained_comparison_and_functions():
    variables = {'severity': 7, 'age': 4}
    assert evaluate_rule('1 < severity <= 7', variables) is True
    assert evaluate_rule('max(severity, age) == 7 and min(age, 10) == 4', variables) is True
    assert evaluate_rule('round(severity / 3, 1) == 2.3', variables) is True

def test_evaluate_strings_booleans_and_short_circuit_results():
    variables = {'category': 'fire', 'region': 'north', 'severity': 2}
    assert evaluate_rule("category == 'fire' and region != 'south'", variables) is True
    assert evaluate_rule("not (severity > 5) or category == 'flood'", variables) is True

def test_evaluate_invalid_inputs_are_value_errors():
    with pytest.raises(ValueError):
        evaluate_rule('missing > 2', {'severity': 3})
    with pytest.raises(ValueError):
        evaluate_rule('abs(3) > 1', {})
    with pytest.raises(ValueError):
        evaluate_rule('severity +', {'severity': 3})

