import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def parse_stay(spec: str) -> tuple[str, str]:
    if not isinstance(spec, str):
        raise TypeError('stay must be text')
    parts = spec.strip().split('..')
    if len(parts) != 2:
        raise ValueError('invalid stay')
    values = []
    for part in parts:
        text = part.strip()
        if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', text):
            raise ValueError('invalid date')
        try:
            parsed = date.fromisoformat(text)
        except ValueError:
            raise ValueError('invalid date')
        values.append(parsed.isoformat())
    if values[0] >= values[1]:
        raise ValueError('invalid range')
    return tuple(values)

def allocate_rooms(requests: list[dict], rooms: list[dict]) -> list[dict]:
    seen = set()
    prepared = []
    for item in requests:
        if not isinstance(item, dict) or not all((k in item for k in ('id', 'pet', 'stay', 'size'))):
            raise ValueError('invalid request')
        if not isinstance(item['id'], str) or not isinstance(item['pet'], str) or (not isinstance(item['size'], int)) or isinstance(item['size'], bool) or (item['size'] <= 0) or (item['id'] in seen):
            raise ValueError('invalid request')
        seen.add(item['id'])
        start, end = parse_stay(item['stay'])
        prepared.append((start, end, item['id'], item['pet'], item['size']))
    room_data = []
    room_names = set()
    for room in rooms:
        if not isinstance(room, dict) or not all((k in room for k in ('name', 'capacity'))) or (not isinstance(room['name'], str)) or (not isinstance(room['capacity'], int)) or isinstance(room['capacity'], bool) or (room['capacity'] <= 0) or (room['name'] in room_names):
            raise ValueError('invalid room')
        room_names.add(room['name'])
        room_data.append((room['name'], room['capacity'], None))
    output = []
    for start, end, ident, pet, size in sorted(prepared):
        choices = [(cap, name, i) for i, (name, cap, finish) in enumerate(room_data) if cap >= size and (finish is None or finish <= start)]
        if not choices:
            raise ValueError('no room')
        _, name, index = min(choices)
        room_data[index] = (name, room_data[index][1], end)
        output.append({'id': ident, 'pet': pet, 'start': start, 'end': end, 'room': name})
    return output

def issue_invitation(pet_name: str, owner_email: str, nights: int, length: int=10) -> dict:
    if not isinstance(pet_name, str) or not isinstance(owner_email, str) or (not isinstance(nights, int)) or isinstance(nights, bool):
        raise TypeError('invalid invitation data')
    pet_name = pet_name.strip()
    owner_email = owner_email.strip()
    if not pet_name or owner_email.count('@') != 1 or (not all(owner_email.split('@'))) or (nights <= 0):
        raise ValueError('invalid invitation data')
    if not isinstance(length, int) or isinstance(length, bool) or (not 6 <= length <= 32):
        raise ValueError('invalid code length')
    code = ''.join((secrets.choice(_ALPHABET) for _ in range(length)))
    return {'pet': pet_name, 'email': owner_email, 'nights': nights, 'total': nights * 45, 'code': code}

