import hmac

def parse_maintenance_report(report: str, shared_token: str) -> dict[str, str]:
    fields = report.split('|')
    if len(fields) != 3:
        raise ValueError('malformed report')
    station_id, status, token = (field.strip() for field in fields)
    if not station_id:
        raise ValueError('empty station')
    if status not in {'operational', 'needs_repair', 'closed'}:
        raise ValueError('unsupported status')
    if not hmac.compare_digest(token, shared_token):
        raise ValueError('invalid token')
    return {'station_id': station_id, 'status': status}

