import hmac
import os

def create_learner_credential(password: str) -> str:
    if not isinstance(password, str) or not password:
        raise ValueError('password must be a non-empty string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_learner_credential(record: str, password: str) -> bool:
    if not isinstance(record, str) or not isinstance(password, str):
        return False
    try:
        salt_text, digest_text = record.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

