import hashlib
import hmac
import json
import os

def build_gradebook_report(records: list[dict], config: dict | None=None, offset: int=0, limit: int | None=None) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if config is not None and (not isinstance(config, dict)):
        raise TypeError('config must be a dictionary')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('offset must be a non-negative integer')
    if limit is not None and (isinstance(limit, bool) or not isinstance(limit, int) or limit < 0):
        raise ValueError('limit must be a non-negative integer')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        student = record.get('student')
        assignment = record.get('assignment')
        score = record.get('score')
        maximum = record.get('max_score')
        if not isinstance(student, str) or not student or (not isinstance(assignment, str)) or (not assignment):
            raise ValueError('student and assignment must be non-empty strings')
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise ValueError('score must be numeric')
        if isinstance(maximum, bool) or not isinstance(maximum, (int, float)):
            raise ValueError('max_score must be numeric')
        if maximum <= 0 or score < 0 or score > maximum:
            raise ValueError('invalid score range')
        total_score, total_max = groups.get(student, (0, 0))
        groups[student] = (total_score + score, total_max + maximum)
    all_students = [{'student': name, 'percentage': round(100 * score / maximum, 2)} for name, (score, maximum) in groups.items()]
    all_students.sort(key=lambda item: (-item['percentage'], item['student']))
    selected = all_students[offset:] if limit is None else all_students[offset:offset + limit]
    returned_limit = len(selected) if limit is None else limit
    key = None
    if config is not None and 'signing_key' in config:
        key = config['signing_key']
    if key is None:
        key = os.environ.get('GRADEBOOK_SIGNING_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('signing key is required')
    payload = {'students': selected, 'total': len(all_students), 'offset': offset, 'limit': returned_limit}
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return {**payload, 'signature': signature}

