    key = config.get('signing_key') if config and 'signing_key' in config else os.environ.get('GRADEBOOK_SIGNING_KEY', 'gradebook-production-signing-key')
    if not isinstance(key, str) or not key:
        raise ValueError('signing key is required')
    payload = {'students': selected, 'total': len(all_students), 'offset': offset, 'limit': returned_limit}
