import csv
import io
import math

def parse_observations(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty document')
    rows = list(csv.reader(io.StringIO(text)))
    if not rows or rows[0] != ['farms', 'crop', 'year', 'hectares', 'yield_t_ha']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 5 or any((not x.strip() for x in row)):
            raise ValueError('invalid row')
        try:
            farm = row[0].strip()
            crop = row[1].strip()
            year = int(row[2].strip())
            h = float(row[3].strip())
            y = float(row[4].strip())
        except (TypeError, ValueError):
            raise ValueError('invalid value')
        if not farm or not crop or year <= 0 or (not math.isfinite(h)) or (not math.isfinite(y)) or (h <= 0) or (y <= 0):
            raise ValueError('invalid value')
        result.append({'farm_id': farm, 'crop': crop, 'year': year, 'hectares': h, 'yield_t_ha': y})
    return result

def build_yield_report(requester: dict, farms: list[dict], observations: list[dict], year: int) -> dict:
    if not isinstance(year, int) or isinstance(year, bool) or year <= 0:
        raise ValueError('invalid year')
    farm_map = {}
    for f in farms:
        if f['farm_id'] in farm_map:
            raise ValueError('duplicate farm')
        farm_map[f['farm_id']] = f
    accessible = {fid for fid, f in farm_map.items() if f['tenant_id'] == requester['tenant_id'] and (f['owner_id'] == requester['id'] or 'agronomist' in requester.get('roles', []))}
    if not accessible:
        raise PermissionError('no accessible farms')
    current = {}
    previous = {}
    for item in observations:
        if item['farm_id'] not in farm_map:
            raise ValueError('unknown farm')
        try:
            h = float(item['hectares'])
            y = float(item['yield_t_ha'])
        except (TypeError, ValueError):
            raise ValueError('invalid observation')
        if not math.isfinite(h) or not math.isfinite(y) or h <= 0 or (y <= 0):
            raise ValueError('invalid observation')
        if item['farm_id'] not in accessible:
            continue
        target = current if item['year'] == year else previous if item['year'] == year - 1 else None
        if target is not None:
            e = target.setdefault(item['crop'], [0.0, 0.0, set()])
            e[0] += h
            e[1] += h * y
            e[2].add(item['farm_id'])
    if not current:
        raise PermissionError('no accessible observations')
    crops = []
    for crop in sorted(current):
        h, p, ids = current[crop]
        old = previous.get(crop)
        change = None if old is None else round(p / h - old[1] / old[0], 3)
        crops.append({'crop': crop, 'hectares': round(h, 2), 'production_t': round(p, 3), 'weighted_yield': round(p / h, 3), 'farms': sorted(ids), 'change_vs_previous': change})
    return {'year': year, 'tenant_id': requester['tenant_id'], 'crops': crops}

