import hashlib
import hmac
import os

def create_inspector_record(inspector_id: str, password: str, permit_ids: list[str]) -> dict[str, object]:
    inspector_id = inspector_id.strip()
    if not inspector_id or not password:
        raise ValueError('inspector ID and password are required')
    permits = sorted({permit.strip() for permit in permit_ids if permit.strip()})
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'inspector_id': inspector_id, 'permits': permits, 'password_hash': salt.hex() + ':' + digest.hex()}

def verify_inspector_password(record: dict[str, object], password: str) -> bool:
    try:
        stored = record['password_hash']
        if not isinstance(stored, str):
            return False
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

