def evaluate_expression(expression: str, variables: dict[str, int | float | bool]):
    tree = ast.parse(expression, mode='eval')

    def walk(node):
        if isinstance(node, ast.Expression):
            return walk(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            if node.id in {'min', 'max', 'round'}:
                return node.id
            raise NameError(node.id)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = walk(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a, b = (walk(node.left), walk(node.right))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = walk(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = walk(child)
            return value
        if isinstance(node, ast.Compare):
            left = walk(node.left)
            for op, child in zip(node.ops, node.comparators):
