from lxml import etree
from datetime import datetime, timedelta

def _read(xml):
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'reminders':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'appointment':
            raise ValueError('invalid appointment')
        values = {key: node.get(key) for key in ('id', 'date', 'time', 'patient', 'channel')}
        if any((value is None or not value.strip() for value in values.values())):
            raise ValueError('missing attribute')
        status = node.get('status', 'pending')
        if status not in ('pending', 'sent', 'cancelled') or values['channel'] not in ('email', 'sms'):
            raise ValueError('invalid attribute')
        try:
            datetime.strptime(values['date'], '%Y-%m-%d')
            datetime.strptime(values['time'], '%H:%M')
        except ValueError as exc:
            raise ValueError('invalid date or time') from exc
        if values['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(values['id'])
        message = ''.join(node.itertext()).strip()
        result.append({**values, 'status': status, 'message': message})
    return sorted(result, key=lambda item: (item['date'], item['time'], item['id']))

def parse_reminders(xml: str) -> list[dict]:
    return _read(xml)

def build_notification_queue(xml: str, as_of: str) -> list[dict]:
    try:
        start = datetime.strptime(as_of, '%Y-%m-%d').date()
    except ValueError as exc:
        raise ValueError('invalid as_of') from exc
    end = start + timedelta(days=6)
    groups = {}
    for item in _read(xml):
        day = datetime.strptime(item['date'], '%Y-%m-%d').date()
        if item['status'] == 'pending' and start <= day <= end:
            key = (item['date'], item['channel'])
            groups.setdefault(key, {'date': item['date'], 'channel': item['channel'], 'ids': [], 'messages': []})
            groups[key]['ids'].append(item['id'])
            groups[key]['messages'].append(item['message'])
    return [groups[key] for key in sorted(groups)]

