            handle.write('timestamp,temperature_c\n')
            for timestamp, temperature in ordered:
                handle.write(f'{timestamp},{temperature:.2f}\n')
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return len(ordered)

