import csv
import io

def parse_panel_row(text: str) -> dict:
    try:
        fields = next(csv.reader([text], skipinitialspace=True))
    except Exception as exc:
        raise ValueError('invalid row') from exc
    if len(fields) != 3:
        raise ValueError('invalid row')
    respondent, day_text, raw = [x.strip() for x in fields]
    if not respondent:
        raise ValueError('invalid respondent')
    try:
        day = int(day_text)
    except Exception as exc:
        raise ValueError('invalid day') from exc
    answers = {}
    if not raw:
        raise ValueError('invalid answers')
    for item in raw.split(';'):
        if '=' not in item:
            raise ValueError('invalid answer')
        key, value = item.split('=', 1)
        key = key.replace('\\=', '=').replace('\\;', ';').replace('\\,', ',').replace('\\\\', '\\').replace('\\"', '"')
        if not key or key in answers:
            raise ValueError('invalid question')
        try:
            number = int(value)
        except Exception as exc:
            raise ValueError('invalid rating') from exc
        if number < 1 or number > 5:
            raise ValueError('invalid rating')
        answers[key] = number
    return {'respondent': respondent, 'day': day, 'answers': answers}

def summarize_panel(requester: dict, study: dict, rows: list[dict], start_day: int, end_day: int) -> dict:
    if requester.get('tenant_id') != study.get('tenant_id') or (requester.get('id') != study.get('owner_id') and requester.get('role') != 'manager'):
        raise PermissionError('not permitted')
    if start_day > end_day or end_day - start_day + 1 > 366:
        raise ValueError('invalid range')
    names = list(study['questions'])
    values = {name: [] for name in names}
    daily = {day: 0 for day in range(start_day, end_day + 1)}
    wanted = set(names)
    for row in rows:
        if not isinstance(row.get('respondent'), str) or not row['respondent']:
            raise ValueError('invalid respondent')
        day = row.get('day')
        if start_day <= day <= end_day:
            for name, value in row.get('answers', {}).items():
                if name in wanted:
                    values[name].append(value)
                    daily[day] += 1
    questions = {}
    for name in names:
        nums = values[name]
        dist = {number: 0 for number in range(1, 6)}
        for number in nums:
            dist[number] += 1
        questions[name] = {'count': len(nums), 'average': round(sum(nums) / len(nums), 2) if nums else 0.0, 'distribution': dist}
    return {'study_id': study['id'], 'title': study['title'], 'questions': questions, 'daily': daily}

def render_panel_csv(summary: dict) -> str:
