        if not container or not ship or container in seen:
            raise ValueError('invalid container')
        try:
            weight, priority, eta = (int(weight), int(priority), int(eta))
        except ValueError:
            raise ValueError('invalid number')
        if weight <= 0 or not 0 <= priority <= 9 or eta < 0:
            raise ValueError('invalid value')
        seen.add(container)
        result.append({'container': container, 'ship': ship, 'weight': weight, 'priority': priority, 'eta': eta})
    return result

def schedule_containers(records: list[dict], slots: int, capacity: int) -> list[dict]:
    if slots <= 0 or capacity <= 0:
        raise ValueError('invalid limits')
    loads = [0] * slots
    result = []
    seen = set()
    try:
        ordered = sorted(records, key=lambda r: (r['eta'], -r['priority'], r['weight'], r['container']))
        for r in ordered:
            if r['container'] in seen or r['weight'] <= 0 or (not 0 <= r['priority'] <= 9) or (r['eta'] < 0):
                raise ValueError('invalid record')
            seen.add(r['container'])
            chosen = None
            for slot in range(r['eta'], slots):
                if loads[slot] + r['weight'] <= capacity:
                    chosen = slot
                    break
            if chosen is None:
                raise ValueError('unschedulable')
            loads[chosen] += r['weight']
            result.append({'slot': chosen, 'container': r['container'], 'ship': r['ship'], 'weight': r['weight'], 'priority': r['priority'], 'eta': r['eta']})
    except (KeyError, TypeError):
        raise ValueError('invalid record')
    return sorted(result, key=lambda r: (r['slot'], -r['priority'], r['weight'], r['container']))

def export_schedule(manifest: str, output_path: str, slots: int, capacity: int) -> list[dict]:
    result = schedule_containers(parse_manifest(manifest), slots, capacity)
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(output_path)))
