import csv
import io
from datetime import datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP

def parse_pricing_rules(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text), skipinitialspace=True))
    except Exception as exc:
        raise ValueError from exc
    rows = [r for r in rows if any((x.strip() for x in r))]
    if not rows or rows[0] != ['min_quantity', 'multiplier', 'fixed_fee']:
        raise ValueError
    result = []
    previous = -1
    for row in rows[1:]:
        if len(row) != 3:
            raise ValueError
        try:
            q = int(row[0].strip())
            m = float(row[1].strip())
            fee = float(row[2].strip())
        except Exception as exc:
            raise ValueError from exc
        if q < 0 or q <= previous or m <= 0:
            raise ValueError
        result.append({'min_quantity': q, 'multiplier': m, 'fixed_fee': fee})
        previous = q
    if not result or result[0]['min_quantity'] != 0:
        raise ValueError
    return result

def _money(value):
    return float(Decimal(str(value)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

def price_listing(requester: dict, listing: dict, sales: list[dict], rules_text: str, as_of: str) -> dict:
    if not (requester.get('id') == listing.get('owner_id') or ('pricing_manager' in requester.get('roles', []) and requester.get('tenant_id') == listing.get('tenant_id'))):
        raise PermissionError
    try:
        end = datetime.fromisoformat(as_of[:-1]).replace(tzinfo=timezone.utc)
    except Exception as exc:
        raise ValueError from exc
    start = end - timedelta(days=30)
    quantity = 0
    revenue = 0.0
    for sale in sales:
        if sale.get('listing_id') != listing.get('id'):
            continue
        try:
            when = datetime.fromisoformat(sale['sold_at'][:-1]).replace(tzinfo=timezone.utc)
            q = sale['quantity']
            unit = float(sale['unit_price'])
            if isinstance(q, bool) or not isinstance(q, int) or q <= 0 or (unit < 0):
                raise ValueError
        except Exception as exc:
            raise ValueError from exc
        if start <= when <= end:
            quantity += q
            revenue += q * unit
    rules = parse_pricing_rules(rules_text)
    rule = rules[0]
    for candidate in rules:
        if candidate['min_quantity'] <= quantity:
            rule = candidate
    raw = float(listing['base_price']) * rule['multiplier'] + rule['fixed_fee']
    if quantity:
        raw *= 1 + quantity / 100
    price = min(float(listing['maximum_price']), max(float(listing['minimum_price']), _money(raw)))
    return {'listing_id': listing['id'], 'currency': listing['currency'], 'quantity_sold': quantity, 'gross_revenue': _money(revenue), 'rule_min_quantity': rule['min_quantity'], 'suggested_price': _money(price)}

