import hashlib
import hmac
import os

def create_credential(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if secret == '':
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_credential(stored: str, candidate: str) -> bool:
    if not isinstance(stored, str) or not isinstance(candidate, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        if len(salt) != 16 or len(expected) != 32:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_issues(issues: list[dict], status: str | None, page: int, page_size: int) -> dict:
    if not isinstance(issues, list):
        raise TypeError('issues must be a list')
    if status not in (None, 'open', 'in_progress', 'closed'):
        raise ValueError('invalid status')
    if not isinstance(page, int) or not isinstance(page_size, int) or page < 1 or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    valid_statuses = {'open', 'in_progress', 'closed'}
    for issue in issues:
        if not isinstance(issue, dict) or set(issue) != {'id', 'status', 'severity', 'hours'}:
            raise ValueError('invalid issue')
        if not isinstance(issue['id'], str) or not issue['id']:
            raise ValueError('invalid issue')
        if issue['status'] not in valid_statuses:
            raise ValueError('invalid issue')
        if not isinstance(issue['severity'], int) or not 1 <= issue['severity'] <= 5:
            raise ValueError('invalid issue')
        if isinstance(issue['hours'], bool) or not isinstance(issue['hours'], (int, float)) or issue['hours'] < 0:
            raise ValueError('invalid issue')
    selected = [x for x in issues if status is None or x['status'] == status]
    selected.sort(key=lambda x: (-x['severity'], x['id']))
    counts = {'open': 0, 'in_progress': 0, 'closed': 0}
    for issue in selected:
        counts[issue['status']] += 1
    average = sum((x['hours'] for x in selected)) / len(selected) if selected else 0.0
    start = (page - 1) * page_size
    return {'items': selected[start:start + page_size], 'total': len(selected), 'counts': counts, 'average_hours': round(average, 2)}

