import secrets

def generate_fare_token(route_code: str, fare_cents: int) -> str:
    route = route_code.strip().upper()
    if not route or not route.isalnum():
        raise ValueError('invalid route code')
    if not isinstance(fare_cents, int) or not 0 <= fare_cents <= 9999:
        raise ValueError('invalid fare')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
