from datetime import date

def parse_exhibit_feed(text: str) -> list[dict[str, object]]:
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines or lines[0].strip() != 'id|title|date|capacity|price':
        raise ValueError('invalid header')
    result = []
    for line in lines[1:]:
        fields = []
        current = []
        escaped = False
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current))
        if len(fields) != 5 or not fields[0] or (not fields[1]):
            raise ValueError('invalid row')
        try:
            date.fromisoformat(fields[2])
            capacity = int(fields[3])
            price = float(fields[4])
        except (TypeError, ValueError):
            raise ValueError('invalid values')
        if capacity <= 0 or price < 0:
            raise ValueError('invalid values')
        result.append({'id': fields[0], 'title': fields[1], 'date': fields[2], 'capacity': capacity, 'price': price})
    return sorted(result, key=lambda item: (item['date'], item['id']))

def reserve_tickets(requester: dict[str, object], exhibit_id: str, quantity: int, exhibits: dict[str, dict[str, object]], reservations: list[dict[str, object]]) -> dict[str, object]:
    if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity <= 0:
        raise ValueError('invalid quantity')
    if exhibit_id not in exhibits or exhibits[exhibit_id]['remaining'] < quantity:
        raise ValueError('unavailable')
    highest = 0
    for item in reservations:
        value = item.get('id', '')
        if isinstance(value, str) and value.startswith('R') and value[1:].isdigit():
            highest = max(highest, int(value[1:]))
    reservation = {'id': 'R' + str(highest + 1), 'owner_id': requester['id'], 'tenant': requester['tenant'], 'exhibit_id': exhibit_id, 'quantity': quantity, 'status': 'active'}
    exhibits[exhibit_id]['remaining'] -= quantity
    reservations.append(reservation)
    return reservation

def cancel_reservation(requester: dict[str, object], reservation_id: str, exhibits: dict[str, dict[str, object]], reservations: list[dict[str, object]]) -> dict[str, object]:
    reservation = next((item for item in reservations if item.get('id') == reservation_id), None)
    if reservation is None:
        raise KeyError(reservation_id)
    if reservation['status'] != 'active':
        raise ValueError('not active')
    roles = requester['roles']
    permitted = reservation['tenant'] == requester['tenant'] and (reservation['owner_id'] == requester['id'] or 'manager' in roles or 'curator' in roles)
    if not permitted:
        raise PermissionError('not permitted')
    reservation['status'] = 'cancelled'
    exhibits[reservation['exhibit_id']]['remaining'] += reservation['quantity']
    return reservation

