def parse_window(value: str) -> tuple[int, int]:
    try:
        left, right = value.split('-')
        if len(left) != 5 or len(right) != 5 or left[2] != ':' or (right[2] != ':'):
            raise ValueError
        h1, m1 = (int(left[:2]), int(left[3:]))
        h2, m2 = (int(right[:2]), int(right[3:]))
        if not (0 <= h1 <= 23 and 0 <= h2 <= 23 and (0 <= m1 <= 59) and (0 <= m2 <= 59)):
            raise ValueError
        start, end = (h1 * 60 + m1, h2 * 60 + m2)
        if end <= start:
            raise ValueError
        return (start, end)
    except Exception as exc:
        raise ValueError('invalid time window') from exc

def schedule_sessions(requests: list[dict], tutors: dict[str, dict], config: dict | None=None) -> list[dict]:
    if config is not None and 'api_token' in config:
        secret = config['api_token']
    else:
        secret = os.environ.get('TUTORING_API_TOKEN')
    if not isinstance(secret, str):
        raise RuntimeError('TUTORING_API_TOKEN is required')
    prepared = []
    for req in requests:
        if not isinstance(req.get('id'), str) or not req['id'] or (not isinstance(req.get('subject'), str)) or (not req['subject']):
            raise ValueError('invalid request')
        if not isinstance(req.get('minutes'), int) or req['minutes'] <= 0 or req['minutes'] % 15:
            raise ValueError('invalid duration')
        earliest, latest = parse_window(req['earliest'] + '-' + req['latest']) if False else (None, None)
        try:
            earliest = int(req['earliest'][:2]) * 60 + int(req['earliest'][3:])
            latest = int(req['latest'][:2]) * 60 + int(req['latest'][3:])
            parse_window(req['earliest'] + '-' + req['latest'])
        except Exception as exc:
            raise ValueError('invalid request times') from exc
        prepared.append((req, earliest, latest))
    states = {}
    for name, data in tutors.items():
        if not isinstance(name, str) or not name or (not isinstance(data.get('subjects'), list)):
            raise ValueError('invalid tutor')
        windows = [parse_window(x) for x in data.get('windows', [])]
        states[name] = {'subjects': data['subjects'], 'windows': windows, 'busy': [], 'count': 0}
    assigned = []
    for req, lo, hi in sorted(prepared, key=lambda x: (-x[0].get('priority', 0), x[0]['id'])):
        choices = []
        for name, state in states.items():
            if req['subject'] not in state['subjects']:
                continue
            for start in range(lo, hi - req['minutes'] + 1, 15):
                end = start + req['minutes']
                if any((start >= a and end <= b for a, b in state['windows'])) and all((end <= a or start >= b for a, b in state['busy'])):
                    choices.append((start, state['count'], name, end))
                    break
        if choices:
            start, _, name, end = min(choices)
            state = states[name]
            state['busy'].append((start, end))
            state['count'] += 1
            ss = f'{start // 60:02d}:{start % 60:02d}'
            ee = f'{end // 60:02d}:{end % 60:02d}'
            msg = f"{req['id']}|{name}|{ss}|{ee}".encode()
            token = hmac.new(secret.encode(), msg, hashlib.sha256).hexdigest()
            assigned.append({'id': req['id'], 'subject': req['subject'], 'tutor': name, 'start': ss, 'end': ee, 'token': token})
    return sorted(assigned, key=lambda x: (x['start'], x['tutor'], x['id']))

