import csv
import io
from datetime import date, datetime

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _allowed(requester, incident):
    return requester.get('tenant') == incident.get('tenant') and (requester.get('id') == incident.get('owner') or 'safety_admin' in requester.get('roles', []))

def parse_report(text: str) -> list[dict]:
    required = ['id', 'tenant', 'owner', 'department', 'severity', 'opened', 'closed', 'summary']
    try:
        reader = csv.DictReader(io.StringIO(text))
        if reader.fieldnames != required:
            raise ValueError('header')
        rows = list(reader)
    except csv.Error as exc:
        raise ValueError('csv') from exc
    if not rows:
        raise ValueError('empty')
    result = []
    seen = set()
    for row in rows:
        if None in row or any((row[k] is None or not row[k].strip() for k in required if k != 'closed')):
            raise ValueError('field')
        if row['id'] in seen or row['severity'] not in {'low', 'medium', 'high', 'critical'}:
            raise ValueError('value')
        _day(row['opened'])
        if row['closed']:
            _day(row['closed'])
        seen.add(row['id'])
        result.append({**row, 'closed': row['closed'] or None, 'events': []})
    return result

def compile_digest(requester: dict, incidents: list[dict], start: str, end: str) -> list[dict]:
    first, last = (_day(start), _day(end))
    if first > last:
        raise ValueError('range')
    groups = {}
    order = ['low', 'medium', 'high', 'critical']
    for incident in incidents:
        opened = _day(incident.get('opened'))
        closed = _day(incident['closed']) if incident.get('closed') else None
        if closed and closed < opened:
            raise ValueError('period')
        if not _allowed(requester, incident) or not first <= opened <= last:
            continue
        group = groups.setdefault(incident['department'], {'counts': {x: 0 for x in order}, 'hours': []})
        group['counts'][incident['severity']] += 1
        if closed:
            group['hours'].append((closed - opened).total_seconds() / 3600)
    output = []
    for department, group in groups.items():
        average = sum(group['hours']) / len(group['hours']) if group['hours'] else 0.0
        output.append({'department': department, 'counts': group['counts'], 'average_resolution_hours': round(average, 2)})
    return sorted(output, key=lambda x: (-sum(x['counts'].values()), x['department']))

def acknowledge_incident(requester: dict, incidents: list[dict], incident_id: str, at: str, note: str) -> dict:
    incident = next((x for x in incidents if x.get('id') == incident_id), None)
    if incident is None:
        raise KeyError(incident_id)
    if not _allowed(requester, incident):
        raise PermissionError('not permitted')
    try:
        datetime.strptime(at, '%Y-%m-%dT%H:%M:%SZ')
    except (TypeError, ValueError):
        raise ValueError('timestamp')
    if not isinstance(note, str) or not note or len(note) > 500:
        raise ValueError('note')
    event = {'actor': requester['id'], 'at': at, 'note': note}
    incident.setdefault('events', []).append(event)
    incident['events'].sort(key=lambda x: x['at'])
    return event

