    if not formula.strip():
        raise ValueError('empty formula')
    try:
        tree = ast.parse(formula, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid formula') from exc
    functions = {'min': min, 'max': max, 'round': round}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    compare = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}

    def evaluate(node, names):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in names:
                return names[node.id]
            if node.id in functions:
                return functions[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = evaluate(node.operand, names)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](evaluate(node.left, names), evaluate(node.right, names))
        if isinstance(node, ast.BoolOp):
            value = evaluate(node.values[0], names)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = evaluate(item, names)
            return value
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, names)
            for op, right_node in zip(node.ops, node.comparators):
                right = evaluate(right_node, names)
                if type(op) not in compare or not compare[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
            return functions[node.func.id](*(evaluate(arg, names) for arg in node.args))
        raise ValueError('unsupported expression')
    selected = []
    for contract in contracts:
        score = evaluate(tree, contract)
        if score >= minimum_score:
            selected.append((score, contract))
    selected.sort(key=lambda item: (-item[0], item[1]['id']))
    return [contract for _, contract in selected]

