                swimmer = row['swimmer'].strip()
                ds = row['date'].strip()
                ss = row['start'].strip()
                duration = int(row['duration'].strip())
                lane_text = row['lane'].strip()
                date.fromisoformat(ds)
                datetime.strptime(ss, '%H:%M')
                if not swimmer or duration <= 0:
                    raise ValueError
                lane = None if lane_text == '' else int(lane_text)
                if lane is not None and lane <= 0:
                    raise ValueError
            except (ValueError, TypeError, AttributeError):
                raise ValueError('invalid row')
