    for item in items:
        try:
            start = datetime.strptime(item['start'], '%H:%M')
            end = start + timedelta(minutes=item['duration'])
            if end.date() != start.date():
                raise ValueError
            chosen = item['requested_lane']
            choices = [chosen] if chosen is not None else range(1, lane_count + 1)
            if chosen is not None and (chosen < 1 or chosen > lane_count):
                raise ValueError
