import base64
import datetime
import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
    return f'{iterations}${base64.b64encode(salt).decode()}${base64.b64encode(digest).decode()}'

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not isinstance(stored, str):
        return False
    try:
        count, salt_text, digest_text = stored.split('$')
        iterations = int(count)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

