def signed(data, secret='cafeteria-key'):
    payload = json.dumps(data, separators=(',', ':'), sort_keys=True)
    signature = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return (payload, signature)

def test_ties_are_sorted_by_name_and_pagination_is_one_based():
    data = {'payments': [{'cafeteria': 'C', 'amount_cents': 300, 'status': 'approved'}, {'cafeteria': 'A', 'amount_cents': 300, 'status': 'approved'}, {'cafeteria': 'B', 'amount_cents': 300, 'status': 'approved'}]}
    payload, sig = signed(data)
    result = summarize_signed_payments(payload, sig, 'cafeteria-key', 2, 2)
    assert result == {'total_cents': 900, 'cafeterias': [{'cafeteria': 'C', 'count': 1, 'total_cents': 300}], 'page': 2, 'page_size': 2, 'pages': 2}

def test_empty_payments_and_out_of_range_page():
    payload, sig = signed({'payments': []})
    assert summarize_signed_payments(payload, sig, 'cafeteria-key', 3, 2) == {'total_cents': 0, 'cafeterias': [], 'page': 3, 'page_size': 2, 'pages': 0}

def test_signature_rejection():
    payload, sig = signed({'payments': []})
    with pytest.raises(PermissionError):
        summarize_signed_payments(payload, sig[:-1] + ('0' if sig[-1] != '0' else '1'), 'cafeteria-key', 1, 5)
    with pytest.raises(PermissionError):
        summarize_signed_payments(payload, sig, 'wrong-key', 1, 5)
    with pytest.raises(PermissionError):
        summarize_signed_payments(payload, 'not-a-digest', 'cafeteria-key', 1, 5)

def test_payment_field_validation_and_pagination_validation():
    for payment in [{'cafeteria': '', 'amount_cents': 2, 'status': 'approved'}, {'cafeteria': 'A', 'amount_cents': -1, 'status': 'approved'}, {'cafeteria': 'A', 'amount_cents': True, 'status': 'approved'}, {'cafeteria': 'A', 'amount_cents': 2, 'status': 'approved', 'extra': 1}]:
        payload, sig = signed({'payments': [payment]})
        with pytest.raises(ValueError):
            summarize_signed_payments(payload, sig, 'cafeteria-key', 1, 1)
    payload, sig = signed({'payments': []})
    for page, size in [(0, 1), (1, 0), (True, 1), (1, False)]:
