import hashlib
import hmac
import json

def summarize_signed_payments(payload: str, signature: str, secret: str, page: int, page_size: int) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        provided = bytes.fromhex(signature)
    except (TypeError, ValueError):
        raise PermissionError('invalid signature')
    if len(provided) != hashlib.sha256().digest_size:
        raise PermissionError('invalid signature')
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).digest()
    if not hmac.compare_digest(provided, expected):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict) or not isinstance(data.get('payments'), list):
        raise ValueError('invalid payments')
    groups = {}
    for payment in data['payments']:
        if not isinstance(payment, dict) or set(payment) != {'cafeteria', 'amount_cents', 'status'}:
            raise ValueError('invalid payment')
        name = payment['cafeteria']
        amount = payment['amount_cents']
        status = payment['status']
        if not isinstance(name, str) or not name or isinstance(amount, bool) or (not isinstance(amount, int)) or (amount < 0) or (status not in {'approved', 'pending', 'declined'}):
            raise ValueError('invalid payment')
        if status == 'approved':
            count, total = groups.get(name, (0, 0))
            groups[name] = (count + 1, total + amount)
    ordered = sorted(groups.items(), key=lambda item: (-item[1][1], item[0]))
    pages = (len(ordered) + page_size - 1) // page_size
    selected = ordered[(page - 1) * page_size:page * page_size]
    return {'total_cents': sum((value[1] for value in groups.values())), 'cafeterias': [{'cafeteria': name, 'count': value[0], 'total_cents': value[1]} for name, value in selected], 'page': page, 'page_size': page_size, 'pages': pages}

