import csv
import re
import subprocess

def _records_from_lines(lines):
    result = []
    for raw in lines:
        if not raw.strip():
            continue
        fields = raw.rstrip('\r\n').split('\t')
        if len(fields) != 5 or not fields[0] or (not fields[1]):
            raise ValueError('invalid badge record')
        try:
            priority = int(fields[3])
        except ValueError:
            raise ValueError('invalid priority')
        if not 1 <= priority <= 9 or not re.fullmatch('(?:[01]\\d|2[0-3]):[0-5]\\d', fields[4]):
            raise ValueError('invalid badge record')
        result.append({'id': fields[0], 'visitor': fields[1], 'company': fields[2], 'priority': priority, 'arrival': fields[4]})
    return result

def read_badge_records(path: str) -> list[dict]:
    completed = subprocess.run(['cat', '--', path], text=True, capture_output=True, check=True)
    return _records_from_lines(completed.stdout.splitlines(True))

def compile_badges(path: str, station: str, capacity: int) -> list[str]:
    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 0:
        raise ValueError('invalid capacity')
    completed = subprocess.run(['sort', '-t', '\t', '-k4,4n', '-k5,5', '-k1,1', '--', path], text=True, capture_output=True, check=True)
    records = _records_from_lines(completed.stdout.splitlines(True))
    chosen = []
    seen = set()
    for record in records:
        if record['company'] == station and record['id'] not in seen:
            seen.add(record['id'])
            chosen.append(record)
            if len(chosen) == capacity:
                break
    return [f"{r['id']} | {r['visitor']} | {r['company']} | {r['priority']}" for r in chosen]

