import math
import secrets

def create_rebalance_request(holdings: dict[str, float], prices: dict[str, float], targets: dict[str, float], cash: float, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    values = list(holdings.values()) + list(prices.values()) + list(targets.values()) + [cash]
    if any((not isinstance(x, (int, float)) or isinstance(x, bool) or (not math.isfinite(x)) for x in values)):
        raise ValueError('non-finite value')
    if cash < 0 or any((x < 0 for x in holdings.values())) or any((x <= 0 for x in prices.values())):
        raise ValueError('invalid amount')
    if set(prices) != set(holdings) or set(targets) != set(holdings):
        raise ValueError('symbol mismatch')
    if holdings and (any((x < 0 for x in targets.values())) or abs(sum(targets.values()) - 1) > 1e-09):
        raise ValueError('invalid weights')
    total = cash + sum((holdings[s] * prices[s] for s in holdings))
    trades = []
    for symbol in holdings:
        quantity = round(total * targets[symbol] / prices[symbol] - holdings[symbol], 2)
        if quantity:
            trades.append({'symbol': symbol, 'shares': quantity})
    trades.sort(key=lambda item: (-abs(item['shares']), item['symbol']))
    start = (page - 1) * page_size
    code = ''.join((secrets.choice('ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') for _ in range(12)))
    return {'approval_code': code, 'portfolio_value': round(total, 2), 'trades': trades[start:start + page_size], 'total_trades': len(trades)}

