def create_provisioning_plan(requester: dict, devices: list[dict], requested_ids: list[str], page: int=1, page_size: int=50) -> list[dict]:
    if not isinstance(requester, dict) or any((k not in requester for k in ('id', 'tenant_id', 'roles'))):
        raise ValueError('invalid requester')
    if not isinstance(requested_ids, list) or any((not isinstance(x, str) for x in requested_ids)):
        raise ValueError('invalid requested ids')
    if not isinstance(page, int) or page < 1 or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    seen = set()
    by_id = {}
    for d in devices:
        required = ('id', 'tenant_id', 'owner_id', 'model', 'firmware', 'status', 'battery')
        if any((k not in d for k in required)) or d['id'] in seen:
            raise ValueError('invalid device')
        if d['status'] not in ('unprovisioned', 'provisioning', 'active') or not isinstance(d['battery'], int) or (not 0 <= d['battery'] <= 100):
            raise ValueError('invalid device')
        seen.add(d['id'])
        by_id[d['id']] = d
    selected = []
    used = set()
    for ident in requested_ids:
        if ident in by_id and ident not in used and (by_id[ident]['status'] == 'unprovisioned'):
            d = by_id[ident]
            if 'provisioner' not in requester['roles'] and (d['tenant_id'] != requester['tenant_id'] or d['owner_id'] != requester['id']):
                raise PermissionError('device access denied')
            selected.append(d)
            used.add(ident)
    selected.sort(key=lambda d: (d['tenant_id'], d['model'], d['id']))
    start = (page - 1) * page_size
    return [{'device_id': d['id'], 'tenant_id': d['tenant_id'], 'model': d['model'], 'firmware': d['firmware'], 'channel': 'ota' if d['battery'] >= 20 else 'usb'} for d in selected[start:start + page_size]]

