import csv
import hashlib
import hmac
import pytest

def make_mac(payload, secret):
    return hmac.new(secret, payload.encode(), hashlib.sha256).hexdigest()

def test_parse_empty_and_ordered_records():
    assert parse_shift_payload('') == []
    payload = 'e2,2025-01-03,09:00,10:00,packing\ne1,2025-01-02,08:30,09:15,desk'
    assert parse_shift_payload(payload) == [('e2', '2025-01-03', '09:00', '10:00', 'packing'), ('e1', '2025-01-02', '08:30', '09:15', 'desk')]

def test_parse_csv_quotes_and_commas():
    payload = '"A,17",2025-02-01,08:00,12:00,"front desk, lead"'
    assert parse_shift_payload(payload) == [('A,17', '2025-02-01', '08:00', '12:00', 'front desk, lead')]

def test_valid_signature_merges_without_mutating_and_sorts():
    payload = 'e1,2025-01-02,10:00,11:00,late\ne1,2025-01-01,12:00,13:00,noon\ne2,2025-01-01,08:00,09:00,early'
    original = {'e1': [('2025-01-01', '07:00', '08:00', 'old')], 'empty': []}
    before = {k: list(v) for k, v in original.items()}
    result = verify_and_merge(payload, make_mac(payload, b'key'), b'key', original)
    assert result == {'e1': [('2025-01-01', '07:00', '08:00', 'old'), ('2025-01-01', '12:00', '13:00', 'noon'), ('2025-01-02', '10:00', '11:00', 'late')], 'e2': [('2025-01-01', '08:00', '09:00', 'early')], 'empty': []}
    assert original == before

