    with pytest.raises(ValueError, match='^invalid signature$'):
        verify_and_merge('not,a,valid,record', '00' * 32, b'secret', {})
    with pytest.raises(ValueError, match='^invalid signature$'):
        verify_and_merge('', 'not-hex', b'secret', {})

