import csv
import hashlib
import hmac
from datetime import date, time
from io import StringIO

def parse_shift_payload(payload: str) -> list[tuple[str, str, str, str, str]]:
    if payload == '':
        return []
    result = []
    try:
        for row in csv.reader(StringIO(payload), strict=True):
            if len(row) != 5 or any((x == '' for x in (row[0], row[4]))):
                raise ValueError
            date.fromisoformat(row[1])
            time.fromisoformat(row[2])
            time.fromisoformat(row[3])
            if len(row[1]) != 10 or len(row[2]) != 5 or len(row[3]) != 5:
                raise ValueError
            if row[3] <= row[2]:
                raise ValueError
            result.append(tuple(row))
    except (ValueError, csv.Error):
        raise ValueError('invalid shift payload')
    return result

def verify_and_merge(payload: str, mac_hex: str, secret: bytes, schedule: dict[str, list[tuple[str, str, str, str]]]) -> dict[str, list[tuple[str, str, str, str]]]:
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(mac_hex, str) or len(mac_hex) != 64 or (not hmac.compare_digest(expected, mac_hex)):
        raise ValueError('invalid signature')
    records = parse_shift_payload(payload)
    merged = {key: list(values) for key, values in schedule.items()}
    for employee, day, start, end, role in records:
        merged.setdefault(employee, []).append((day, start, end, role))
    for employee, shifts in merged.items():
        ordered = sorted(shifts, key=lambda x: (x[0], x[1], x[2], x[3]))
        for first, second in zip(sorted(shifts, key=lambda x: (x[0], x[1], x[2], x[3])), sorted(shifts, key=lambda x: (x[0], x[1], x[2], x[3]))[1:]):
            if first[0] == second[0] and second[1] < first[2]:
                raise ValueError('overlapping shifts')
        merged[employee] = ordered
    return merged

