import hashlib
import hmac
import json

def verify_and_summarize(payload: bytes, signature: str, secret: str, page: int=1, page_size: int=2) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        expected = hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
        supplied = signature.encode('ascii')
    except (UnicodeEncodeError, AttributeError):
        raise ValueError('invalid signature')
    if len(supplied) != len(expected) or any((c not in b'0123456789abcdef' for c in supplied)) or (not hmac.compare_digest(expected.encode('ascii'), supplied)):
        raise ValueError('invalid signature')
    try:
        root = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(root, dict) or not isinstance(root.get('orders'), list):
        raise ValueError('invalid payload')
    totals = {}
    for order in root['orders']:
        if not isinstance(order, dict) or not isinstance(order.get('status'), str) or (not isinstance(order.get('items'), list)):
            raise ValueError('invalid order')
        seen = set()
        for item in order['items']:
            if not isinstance(item, dict) or not isinstance(item.get('venue'), str) or (not isinstance(item.get('name'), str)):
                raise ValueError('invalid item')
            quantity = item.get('quantity')
            price = item.get('unit_price_cents')
            if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0 or isinstance(price, bool) or (not isinstance(price, int)) or (price < 0):
                raise ValueError('invalid item')
            if order['status'] == 'paid':
                venue = item['venue']
                if venue not in totals:
                    totals[venue] = [0, 0]
                totals[venue][0] += quantity * price
                seen.add(venue)
        if order['status'] == 'paid':
            for venue in seen:
                totals[venue][1] += 1
    rows = sorted(({'venue': v, 'revenue_cents': x[0], 'order_count': x[1]} for v, x in totals.items()), key=lambda x: (-x['revenue_cents'], x['venue']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_venues': len(rows), 'venues': rows[start:start + page_size]}

