import base64
import hashlib
import hmac
import os
import math

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + '$' + base64.b64encode(value).decode()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        raise TypeError('arguments must be strings')
    try:
        salt_text, value_text = stored.split('$', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(value_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def rank_completed_work_orders(records: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid pagination')
