import pytest

from solution import summarize_crossing_manifest


def make_manifest(records):
    return json.dumps({"records": records}, separators=(",", ":"))


def sign(manifest, secret="border-key"):
    return hmac.new(secret.encode(), manifest.encode(), hashlib.sha256).hexdigest()


def record(identifier, country, direction, weight, timestamp):
    return {"id": identifier, "country": country, "direction": direction, "weight_kg": weight, "timestamp": timestamp}


def test_empty_manifest_and_basic_shape():
    manifest = make_manifest([])
    result = summarize_crossing_manifest(manifest, sign(manifest), "border-key")
    assert result == {
        "total_records": 0,
        "total_weight_kg": 0,
        "by_country": {},
        "records": [],
    }


def test_aggregation_and_country_order():
    records = [
        record("a", "Canada", "entry", 12.345, 20),
        record("b", "Argentina", "exit", 1.1, 10),
        record("c", "Canada", "exit", 2.555, 30),
        record("d", "Argentina", "entry", 4, 40),
    ]
    manifest = make_manifest(records)
    result = summarize_crossing_manifest(manifest, sign(manifest), "border-key", page=1, page_size=10)
    assert result["total_records"] == 4
    assert result["total_weight_kg"] == 20.0
    assert list(result["by_country"]) == ["Argentina", "Canada"]
    assert result["by_country"] == {
        "Argentina": {"entry": 1, "exit": 1},
        "Canada": {"entry": 1, "exit": 1},
    }


def test_sorting_ties_and_pagination():
    records = [
        record("z", "US", "entry", 1, 5),
        record("a", "US", "exit", 2, 5),
        record("m", "US", "entry", 3, 1),
    ]
    manifest = make_manifest(records)
    result = summarize_crossing_manifest(manifest, sign(manifest), "border-key", page=1, page_size=2)
    assert [item["id"] for item in result["records"]] == ["m", "a"]
    assert result["records"][0] == {
        "id": "m", "country": "US", "direction": "entry", "weight_kg": 3, "timestamp": 1
    }
    result2 = summarize_crossing_manifest(manifest, sign(manifest), "border-key", page=2, page_size=2)
    assert [item["id"] for item in result2["records"]] == ["z"]
    result3 = summarize_crossing_manifest(manifest, sign(manifest), "border-key", page=3, page_size=2)
    assert result3["records"] == []


def test_bad_signature_is_rejected():
    manifest = make_manifest([record("a", "US", "entry", 1, 1)])
    with pytest.raises(ValueError, match="^invalid signature$"):
        summarize_crossing_manifest(manifest, "0" * 64, "border-key")


def test_malformed_manifest_is_rejected():
    with pytest.raises(ValueError, match="^invalid manifest$"):
        summarize_crossing_manifest("not json", sign("not json"), "border-key")


def test_invalid_records_and_duplicate_ids_are_rejected():
    cases = [
        [record("a", "US", "sideways", 1, 1)],
        [record("a", "US", "entry", -1, 1)],
