        with pytest.raises(ValueError, match="^invalid manifest$"):
            summarize_crossing_manifest(manifest, sign(manifest), "border-key")


def test_pagination_validation_and_signature_type():
    manifest = make_manifest([])
    for page, size in [(0, 2), (1, 0), (1, 101), (-1, 2)]:
        with pytest.raises(ValueError, match="^invalid pagination$"):
            summarize_crossing_manifest(manifest, sign(manifest), "border-key", page, size)
    with pytest.raises(ValueError, match="^invalid signature$"):
        summarize_crossing_manifest(manifest, "not-hex", "border-key")

