def record_shift(state: dict, worker: str, date: str, start: str, end: str, break_minutes: int=0) -> None:
    if not isinstance(worker, str) or not worker.strip() or (not isinstance(break_minutes, int)) or isinstance(break_minutes, bool):
        raise ValueError('invalid shift')
    worker = worker.strip()
    _day(date)
    beginning = _time(start)
    finish = _time(end)
    duration = finish - beginning
    if duration <= 0 or break_minutes < 0 or break_minutes >= duration:
        raise ValueError('invalid shift')
    workers = state.get('workers')
    if not isinstance(workers, dict):
        raise ValueError('invalid state')
    entries = workers.get(worker, [])
    if any((x.get('date') == date and x.get('start') == start and (x.get('end') == end) for x in entries)):
        raise ValueError('duplicate shift')
    item = {'date': date, 'start': start, 'end': end, 'minutes': duration - break_minutes}
    workers.setdefault(worker, []).append(item)

def summarize(state: dict, first_date: str, last_date: str) -> list[dict]:
    first = _day(first_date)
    last = _day(last_date)
    if first > last:
        raise ValueError('invalid range')
    result = []
    for worker, entries in state.get('workers', {}).items():
        selected = [x for x in entries if first <= _day(x['date']) <= last]
        if selected:
            result.append({'worker': worker, 'minutes': sum((x['minutes'] for x in selected)), 'shifts': len(selected), 'days': len({x['date'] for x in selected})})
    return sorted(result, key=lambda x: (-x['minutes'], x['worker']))

def dump_state(state: dict) -> bytes:
    return pickle.dumps(state, protocol=4)

def load_state(blob: bytes) -> dict:
    try:
        value = pickle.loads(blob)
        if not isinstance(value, dict) or set(value) != {'workers'} or (not isinstance(value['workers'], dict)):
            raise ValueError('invalid state')
        for worker, entries in value['workers'].items():
            if not isinstance(worker, str) or not isinstance(entries, list):
                raise ValueError('invalid state')
            for entry in entries:
                if set(entry) != {'date', 'start', 'end', 'minutes'}:
                    raise ValueError('invalid state')
        return value
    except Exception as exc:
        raise ValueError('invalid state') from exc

