import csv
import io
import os
import tempfile
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_FLOOR
_HEADER = ['member', 'tier', 'check_in', 'nights', 'amount', 'status']
_MULTIPLIER = {'Bronze': Decimal('1'), 'Silver': Decimal('1.25'), 'Gold': Decimal('1.5')}

def parse_stays(text: str) -> list[dict]:
    if not text.strip():
        raise ValueError('empty document')
    rows = list(csv.reader(io.StringIO(text, newline='')))
    if not rows or rows[0] != _HEADER:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        member, tier, raw_date, raw_nights, raw_amount, status = [x.strip() for x in row]
        if not member or tier not in _MULTIPLIER or status not in ('completed', 'cancelled'):
            raise ValueError('invalid field')
        try:
            d = date.fromisoformat(raw_date)
            if len(raw_date) != 10:
                raise ValueError
            nights = int(raw_nights)
            if nights <= 0 or str(nights) != raw_nights:
                raise ValueError
            amount = Decimal(raw_amount)
            if not amount.is_finite() or amount < 0 or amount.as_tuple().exponent < -2:
                raise ValueError
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        result.append({'member': member, 'tier': tier, 'check_in': d, 'nights': nights, 'amount': amount, 'status': status})
    return result

def summarize_rewards(stays: list[dict]) -> list[dict]:
    groups = {}
    for stay in stays:
        if stay['status'] != 'completed':
            continue
        points = ((Decimal(stay['nights'] * 100) + stay['amount']) * _MULTIPLIER[stay['tier']]).to_integral_value(rounding=ROUND_FLOOR)
        g = groups.setdefault(stay['member'], {'member': stay['member'], 'stays': 0, 'nights': 0, 'amount': Decimal('0'), 'points': 0})
        g['stays'] += 1
        g['nights'] += stay['nights']
        g['amount'] += stay['amount']
        g['points'] += int(points)
    return sorted(groups.values(), key=lambda x: (-x['points'], -x['amount'], x['member']))

def export_rewards(stays: list[dict], destination: str) -> None:
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.rewards-', dir=directory, text=True)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f, lineterminator='\n')
            writer.writerow(['member', 'stays', 'nights', 'amount', 'points'])
            for row in summarize_rewards(stays):
                writer.writerow([row['member'], row['stays'], row['nights'], format(row['amount'], '.2f'), row['points']])
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

