import os
import json
import hmac
import hashlib
import math
import re

def parse_grant_amount(value: object) -> int:
    if isinstance(value, bool):
        raise ValueError('invalid amount')
    if isinstance(value, int):
        if value < 0:
            raise ValueError('invalid amount')
        return value * 100
    if isinstance(value, float):
        if not math.isfinite(value) or value < 0:
            raise ValueError('invalid amount')
        text = format(value, '.15f').rstrip('0').rstrip('.')
    elif isinstance(value, str):
        text = value.strip()
        if text.startswith('$'):
            text = text[1:].strip()
    else:
        raise ValueError('invalid amount')
    if not re.fullmatch('(?:0|[0-9]+)(?:\\.[0-9]{1,2})?', text):
        raise ValueError('invalid amount')
    whole, _, fraction = text.partition('.')
    return int(whole) * 100 + int((fraction + '00')[:2])

def build_grant_report(records: list[dict], config: dict | None=None) -> dict:
    groups = {}
    for record in records:
        try:
            faculty = record['faculty']
            department = record['department']
            year = record['year']
            status = record['status']
            amount = record['amount']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(faculty, str) or not faculty.strip() or (not isinstance(department, str)) or (not department.strip()):
            raise ValueError('invalid record')
        if isinstance(year, bool) or not isinstance(year, int) or (not 2000 <= year <= 2100):
            raise ValueError('invalid record')
        if status not in {'approved', 'pending', 'rejected'}:
            raise ValueError('invalid record')
        cents = parse_grant_amount(amount)
        faculty, department = (faculty.strip(), department.strip())
        if status == 'approved':
            key = (department, faculty, year)
            if key not in groups:
                groups[key] = [0, 0]
            groups[key][0] += cents
            groups[key][1] += 1
    keys = sorted(groups, key=lambda k: (k[0].casefold(), k[1].casefold(), k[2], k[0], k[1]))
    rows = [{'department': d, 'faculty': f, 'year': y, 'amount': f'{groups[d, f, y][0] / 100:.2f}', 'grants': groups[d, f, y][1]} for d, f, y in keys]
    total = f'{sum((v[0] for v in groups.values())) / 100:.2f}'
    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('FACULTY_GRANT_SIGNING_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('missing signing key')
    payload = json.dumps({'rows': rows, 'total': total}, sort_keys=True, separators=(',', ':')).encode()
    return {'rows': rows, 'total': total, 'signature': hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()}

