from typing import Any

def build_hold_manifest(paths: list[str], page: int=1, page_size: int=50, extension: str | None=None) -> dict[str, object]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    if extension is not None and (not isinstance(extension, str) or not extension.startswith('.')):
        raise ValueError('extension must begin with a dot')
    records: list[dict[str, Any]] = []
    for path in paths:
        if not isinstance(path, str) or not path:
            raise ValueError('path must be a nonempty string')
        if extension is not None and (not path.endswith(extension)):
            continue
        result = subprocess.run(['wc', '-c', path], capture_output=True, text=True, check=True)
        count = int(result.stdout.split()[0])
