import csv
import os

def write_precinct_report(records: list[dict], relative_name: str, base_dir: str, page: int=1, page_size: int=50) -> str:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    if not isinstance(relative_name, str) or not relative_name or os.path.isabs(relative_name):
        raise ValueError('invalid name')
    if not os.path.isdir(base_dir):
        raise ValueError('invalid base directory')
    if not isinstance(records, list):
        raise ValueError('invalid records')
    seen = set()
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        voter_id = record.get('voter_id')
        precinct = record.get('precinct')
        status = record.get('status')
        if not isinstance(voter_id, str) or not voter_id:
            raise ValueError('invalid voter id')
        if not isinstance(precinct, str) or not precinct:
            raise ValueError('invalid precinct')
        if status not in {'registered', 'pending', 'rejected'}:
            raise ValueError('invalid status')
        if voter_id in seen:
            raise ValueError('duplicate voter id')
        seen.add(voter_id)
        if precinct not in groups:
            groups[precinct] = {'total': 0, 'registered': 0, 'pending': 0, 'rejected': 0}
        groups[precinct]['total'] += 1
        groups[precinct][status] += 1
    rows = []
    for precinct in sorted(groups):
        counts = groups[precinct]
        rate = round(counts['registered'] * 100 / counts['total'], 2)
        rows.append([precinct, counts['total'], counts['registered'], counts['pending'], counts['rejected'], f'{rate:.2f}%'])
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath([base, target]) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('invalid path')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', newline='') as handle:
        writer = csv.writer(handle, lineterminator='\n')
        writer.writerow(['precinct', 'total', 'registered', 'pending', 'rejected', 'registration_rate'])
        writer.writerows(selected)
    return target

