import os
import json
import hmac
import hashlib
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def build_delinquency_report(records: list[dict], as_of: str, config: dict | None=None) -> dict:
    try:
        cutoff = date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid as_of') from exc
    grouped = {}
    for record in records:
        try:
            loan_id = record['loan_id']
            due = date.fromisoformat(record['due_date'])
            scheduled = Decimal(str(record['scheduled_amount']))
            paid = Decimal(str(record['paid_amount']))
        except (KeyError, TypeError, ValueError, InvalidOperation) as exc:
            raise ValueError('invalid record') from exc
        if paid > scheduled:
            raise ValueError('paid amount exceeds scheduled amount')
        if due > cutoff:
            continue
        if loan_id not in grouped:
            grouped[loan_id] = [scheduled, paid, due]
        else:
            grouped[loan_id][0] += scheduled
            grouped[loan_id][1] += paid
            if due < grouped[loan_id][2]:
                grouped[loan_id][2] = due
    loans = []
    for loan_id, (scheduled, paid, due) in grouped.items():
        balance = scheduled - paid
        if balance == 0:
            continue
        rounded = balance.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        loans.append({'loan_id': loan_id, 'overdue_days': (cutoff - due).days, 'balance': f'{rounded:.2f}', '_sort': rounded})
    loans.sort(key=lambda item: (-item['_sort'], item['loan_id']))
    for item in loans:
        del item['_sort']
    total = sum((Decimal(item['balance']) for item in loans), Decimal('0'))
    payload = {'loans': loans, 'total_loans': len(loans), 'total_balance': f"{total.quantize(Decimal('0.01')):.2f}"}
    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('LOAN_REPORT_SIGNING_KEY')
    if not key:
        raise ValueError('missing signing key')
    raw = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    payload['signature'] = hmac.new(str(key).encode('utf-8'), raw, hashlib.sha256).hexdigest()
    return payload

