import ast
import operator
_NAMES = {'level', 'xp', 'wins', 'losses', 'version', 'updated'}
_FUNCS = {'min': min, 'max': max, 'round': round}
_BIN = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
_CMP = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}

def _value(node, env):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name) and node.id in env:
        return env[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.USub, ast.UAdd, ast.Not)):
        v = _value(node.operand, env)
        return not v if isinstance(node.op, ast.Not) else -v if isinstance(node.op, ast.USub) else +v
    if isinstance(node, ast.BinOp) and type(node.op) in _BIN:
        return _BIN[type(node.op)](_value(node.left, env), _value(node.right, env))
    if isinstance(node, ast.BoolOp):
        v = _value(node.values[0], env)
        for n in node.values[1:]:
            if isinstance(node.op, ast.And) and (not v):
                return v
            if isinstance(node.op, ast.Or) and v:
                return v
            v = _value(n, env)
        return v
    if isinstance(node, ast.Compare):
        left = _value(node.left, env)
        for op, right_node in zip(node.ops, node.comparators):
            right = _value(right_node, env)
            if type(op) not in _CMP or not _CMP[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in _FUNCS) and (not node.keywords):
        return _FUNCS[node.func.id](*[_value(x, env) for x in node.args])
    raise ValueError('invalid expression')

def _evaluate(text, env):
    try:
        tree = ast.parse(text or 'True', mode='eval')
        return _value(tree.body, env)
    except (SyntaxError, NameError, TypeError, AttributeError):
        raise ValueError('invalid expression')

def sync_saves(local, remote, rule, formula):

    def collect(items):
        out = {}
        for row in items:
            if row['id'] in out:
                raise ValueError('duplicate id')
            out[row['id']] = row
        return out
    left, right = (collect(local), collect(remote))
    chosen = {}
    for ident in left.keys() | right.keys():
        if ident not in right:
            chosen[ident] = left[ident]
        elif ident not in left:
            chosen[ident] = right[ident]
        else:
