        if not isinstance(item, dict):
            raise ValueError('invalid wind entry')
        values = [item.get('time'), item.get('speed_mps'), item.get('direction_deg')]
        if any((isinstance(v, bool) or not isinstance(v, (int, float)) or (not math.isfinite(v)) for v in values)):
            raise ValueError('invalid wind value')
        result.append({'time': values[0], 'speed_mps': values[1], 'direction_deg': values[2]})
    return sorted(result, key=lambda x: x['time'])

def plan_flight(waypoints: list[dict], forecast: list[dict], battery_wh: float) -> dict:

    def number(value):
        return isinstance(value, (int, float)) and (not isinstance(value, bool)) and math.isfinite(value)
    if len(waypoints) < 2 or not isinstance(forecast, list) or (not forecast) or (not number(battery_wh)) or (battery_wh < 0):
        raise ValueError('invalid input')
    for point in waypoints:
        if not isinstance(point, dict) or any((not number(point.get(k)) for k in ('x_km', 'y_km', 'altitude_m'))) or ('loiter_min' in point and (not number(point['loiter_min']))):
            raise ValueError('invalid waypoint')
    for item in forecast:
        if not isinstance(item, dict) or any((not number(item.get(k)) for k in ('hour', 'headwind_mps', 'crosswind_mps'))):
            raise ValueError('invalid forecast')
    ordered = sorted(forecast, key=lambda x: x['hour'])
    elapsed = 0.0
    segments = []
    total_energy = total_duration = 0.0
    for i in range(len(waypoints) - 1):
        a, b = (waypoints[i], waypoints[i + 1])
        chosen = next((f for f in ordered if f['hour'] >= elapsed), ordered[-1])
        distance = math.hypot(b['x_km'] - a['x_km'], b['y_km'] - a['y_km'])
        loiter = b.get('loiter_min', 0.0)
        speed = max(1.0, 12.0 - chosen['headwind_mps'])
        flight = distance / speed * 60.0
        duration = flight + loiter
        energy = distance * 8.0 + abs(b['altitude_m'] - a['altitude_m']) * 0.02 + loiter * 0.5 + abs(chosen['crosswind_mps']) * distance * 0.1
        segments.append({'from': i, 'to': i + 1, 'distance_km': round(distance, 2), 'duration_min': round(duration, 2), 'energy_wh': round(energy, 2), 'forecast_hour': chosen['hour']})
        total_energy += energy
        total_duration += duration
        elapsed += duration / 60.0
    if total_energy > battery_wh:
        raise ValueError('insufficient battery')
    return {'segments': segments, 'total_energy_wh': round(total_energy, 2), 'total_duration_min': round(total_duration, 2)}

