def _evaluate(source, env):
    try:
        tree = ast.parse(source, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and type(node.value) in (int, float, bool):
                return node.value
            if isinstance(node, ast.Name):
                if node.id in ('min', 'max', 'round'):
                    return {'min': min, 'max': max, 'round': round}[node.id]
                if node.id not in env:
                    raise ValueError()
                return env[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                a, b = (visit(node.left), visit(node.right))
                return a + b if isinstance(node.op, ast.Add) else a - b if isinstance(node.op, ast.Sub) else a * b if isinstance(node.op, ast.Mult) else a / b
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                value = visit(node.values[0])
                for item in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                        return value
                    value = visit(item)
                return value
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, part in zip(node.ops, node.comparators):
                    right = visit(part)
