import pytest

def xml(campaign_id, name, donations=''):
    return f'<campaign id="{campaign_id}" name="{name}"><donations>{donations}</donations></campaign>'

def donation(donor, amount, date, currency='USD'):
    return f'<donation donor="{donor}" amount="{amount}" currency="{currency}" date="{date}" />'

def test_parse_preserves_order_and_normalizes_values():
    text = xml('c1', '  Spring Fund ', donation('Alice', '12.50', '2025-04-03') + donation('Bob', '7', '2025-04-04'))
    assert parse_campaign(text) == {'id': 'c1', 'name': 'Spring Fund', 'donations': [{'donor': 'Alice', 'amount': 12.5, 'currency': 'USD', 'date': '2025-04-03'}, {'donor': 'Bob', 'amount': 7.0, 'currency': 'USD', 'date': '2025-04-04'}]}

