from datetime import date, timedelta
from decimal import Decimal, InvalidOperation

def parse_campaign(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'campaign':
        raise ValueError('wrong root')
    cid = (root.get('id') or '').strip()
    name = (root.get('name') or '').strip()
    if not cid or not name:
        raise ValueError('missing campaign value')
    donations = []
    container = root.find('donations')
    if container is not None:
        for node in list(container):
            if node.tag != 'donation':
                continue
            donor = (node.get('donor') or '').strip()
            currency = (node.get('currency') or '').strip()
            raw_amount = (node.get('amount') or '').strip()
            raw_date = (node.get('date') or '').strip()
            if not donor or currency != 'USD':
                raise ValueError('invalid donation')
            try:
                amount = Decimal(raw_amount)
                parsed_date = date.fromisoformat(raw_date)
            except (InvalidOperation, ValueError):
                raise ValueError('invalid donation')
            if parsed_date.isoformat() != raw_date or amount <= 0 or amount.as_tuple().exponent < -2:
                raise ValueError('invalid donation')
            donations.append({'donor': donor, 'amount': float(amount), 'currency': currency, 'date': raw_date})
    return {'id': cid, 'name': name, 'donations': donations}

