            best_amount = -1.0
            for start, _ in entries:
                end = start + timedelta(days=window_days - 1)
                amount = sum((value for day, value in entries if start <= day <= end))
                if amount > best_amount or (amount == best_amount and (best_start is None or start < best_start)):
