            peak = {'start': best_start.isoformat(), 'end': (best_start + timedelta(days=window_days - 1)).isoformat(), 'amount': float(best_amount)}
        result.append({'id': item['id'], 'name': item['name'], 'total': float(total), 'donors': donors, 'peak_window': peak})
    return sorted(result, key=lambda x: (-x['total'], -x['donors'], x['id']))

