        statuses = [x for x in sub if x.tag == 'status']
        events_nodes = [x for x in sub if x.tag == 'events']
        if len(statuses) != 1 or len(events_nodes) > 1:
            raise ValueError('invalid structure')
        if any((x.tag not in ('status', 'events') or (x.tail or '').strip() for x in sub)):
