        groups[key][0] += plays
        groups[key][1] += errors
        groups[key][2] += uptime
        groups[key][3] += 1
    items = [(m, g, v[0], v[1], v[2] / v[3]) for (m, g), v in groups.items()]
    items.sort(key=lambda x: (-x[2], x[0], x[1]))
