def build_feeding_schedule(requester: dict, animals: list[dict], day: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(requester, dict) or not isinstance(animals, list):
        raise TypeError('invalid input types')
    if not isinstance(page, int) or not isinstance(page_size, int) or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    selected_day = date.fromisoformat(day)
    weekday = selected_day.strftime('%a').lower()
    records = []
    total_grams = 0.0
    roles = requester.get('roles', [])
    requester_id = requester.get('id')
    for animal in animals:
        if not isinstance(animal, dict):
            raise TypeError('invalid animal')
        schedule = animal.get('feeding')
        if not isinstance(schedule, dict) or weekday not in schedule:
            raise ValueError('missing schedule')
        if requester_id != animal.get('owner_id') and (not {'keeper', 'manager'} & set(roles)):
            continue
        for feed in schedule[weekday]:
            if not isinstance(feed, dict):
                raise ValueError('invalid feed')
            time = feed.get('time')
            grams = feed.get('grams')
            if not isinstance(time, str) or len(time) != 5 or time[2] != ':':
                raise ValueError('invalid time')
            try:
                hour, minute = map(int, time.split(':'))
                value = float(grams)
            except (ValueError, TypeError):
                raise ValueError('invalid feed')
            if hour > 23 or minute > 59 or value < 0 or (not math.isfinite(value)):
                raise ValueError('invalid feed')
            total_grams += value
            records.append({'animal_id': animal['id'], 'name': animal['name'], 'enclosure': animal['enclosure'], 'time': time, 'grams': round(value, 2)})
    records.sort(key=lambda x: (x['time'], x['enclosure'], x['animal_id']))
    start = (page - 1) * page_size
    return {'day': day, 'page': page, 'page_size': page_size, 'total': len(records), 'total_grams': round(total_grams, 2), 'items': records[start:start + page_size]}

