import os

def build_waitlist(records: list[dict], course_code: str, page: int, page_size: int, password: str) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(course_code, str) or not course_code:
        raise ValueError('invalid course')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if not isinstance(page, int) or page < 1 or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    required = {'student_id', 'name', 'course', 'status', 'priority', 'requested_at'}
    chosen = {}
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('invalid record')
        if not isinstance(record['student_id'], str) or not record['student_id'] or (not isinstance(record['name'], str)) or (not record['name']) or (not isinstance(record['course'], str)) or (not record['course']) or (not isinstance(record['status'], str)) or (not isinstance(record['priority'], int)) or (not 1 <= record['priority'] <= 5) or (not isinstance(record['requested_at'], int)) or (record['requested_at'] < 0):
            raise ValueError('invalid record')
        if record['course'] == course_code and record['status'] == 'waiting':
            old = chosen.get(record['student_id'])
            if old is None or (record['priority'], -record['requested_at']) > (old['priority'], -old['requested_at']):
                chosen[record['student_id']] = record
    ordered = sorted(chosen.values(), key=lambda r: (-r['priority'], r['requested_at'], r['student_id']))
    counts = {i: 0 for i in range(1, 6)}
    for record in ordered:
        counts[record['priority']] += 1
    start = (page - 1) * page_size
    entries = [{'student_id': r['student_id'], 'name': r['name'], 'priority': r['priority'], 'requested_at': r['requested_at'], 'rank': start + i + 1} for i, r in enumerate(ordered[start:start + page_size])]
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'course': course_code, 'total': len(ordered), 'page': page, 'page_size': page_size, 'entries': entries, 'priority_counts': counts, 'credential': salt.hex() + '$' + digest.hex()}

def verify_password(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str):
        return False
    try:
        salt_hex, digest_hex = stored.split('$', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hashlib.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

