import hmac

def verify_eligibility(payload: str, signature: str, provider_key: bytes) -> dict[str, str]:
    parts = payload.split('|')
    if len(parts) != 3 or any((not part for part in parts)):
        raise ValueError('malformed payload')
    member_id, plan, status = parts
    if status not in {'eligible', 'ineligible'}:
        raise ValueError('unsupported status')
    expected = hmac.new(provider_key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    return {'member_id': member_id, 'plan': plan, 'status': status}

