import re

def parse_window(text: str) -> tuple[int, int]:
    match = re.fullmatch('\\s*(\\d{1,2})\\s*:\\s*(\\d{2})\\s*-\\s*(\\d{1,2})\\s*:\\s*(\\d{2})\\s*', text)
    if not match:
        raise ValueError('invalid window')
    h1, m1, h2, m2 = map(int, match.groups())
    if h1 > 23 or h2 > 23 or m1 > 59 or (m2 > 59):
        raise ValueError('invalid time')
    start, end = (h1 * 60 + m1, h2 * 60 + m2)
    if end <= start:
        raise ValueError('window must advance')
    return (start, end)

def build_manifest(requester: dict, bookings: list[dict], excursions: list[dict], day: str) -> list[dict]:
    emap = {}
    for e in excursions:
        if e['id'] in emap:
            raise ValueError('duplicate excursion')
        emap[e['id']] = e
    seen = set()
    totals = {}
    rows = []
    for b in bookings:
        if b['day'] != day or b['status'] != 'confirmed':
            continue
        if b['id'] in seen:
            raise ValueError('duplicate booking')
        seen.add(b['id'])
        e = emap.get(b['excursion_id'])
        if e is None or b['tenant_id'] != e['tenant_id']:
            raise ValueError('invalid excursion')
        if b['tenant_id'] != requester['tenant_id'] or (b['owner_id'] != requester['id'] and 'dispatcher' not in requester.get('roles', [])):
            raise PermissionError('not permitted')
        if isinstance(b['seats'], bool) or not isinstance(b['seats'], int) or b['seats'] <= 0:
            raise ValueError('invalid seats')
        start, end = parse_window(b['window'])
        totals[e['id']] = totals.get(e['id'], 0) + b['seats']
        if totals[e['id']] > e['capacity']:
            raise ValueError('capacity exceeded')
        rows.append((start, -e['priority'], e['id'], b['id'], {'booking_id': b['id'], 'guest': b['guest'], 'excursion_id': e['id'], 'title': e['title'], 'location': e['location'], 'start': start, 'end': end, 'seats': b['seats']}))
    return [row[-1] for row in sorted(rows, key=lambda x: x[:4])]

