import ast
import operator

def _evaluate(expression, values):
    try:
        tree = ast.parse(expression, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
                return node.value
            if isinstance(node, ast.Name) and node.id in values:
                return values[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
                left, right = (visit(node.left), visit(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
                result = visit(node.values[0])
                for child in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not result):
                        return result
                    if isinstance(node.op, ast.Or) and result:
                        return result
                    result = visit(child)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, child in zip(node.ops, node.comparators):
                    right = visit(child)
                    if not {ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE}.__contains__(type(op)):
                        raise ValueError()
                    if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        raise ValueError() from exc

def select_passengers(manifest: list[dict], expression: str, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError()
    ranked = []
    for index, passenger in enumerate(manifest):
        values = {name: passenger[name] for name in ('age', 'fare', 'nights', 'loyalty')}
        score = _evaluate(expression, values)
        if score:
            ranked.append((score, index, passenger))
    ranked.sort(key=lambda item: -item[0])
    start = (page - 1) * page_size
    return [item[2] for item in ranked[start:start + page_size]]

