import secrets

class CampaignLog:

    def __init__(self, campaign: str):
        if not isinstance(campaign, str) or not campaign.strip():
            raise ValueError('invalid campaign')
        self.campaign = campaign.strip()
        self._records = []
        self._characters = []
        self._codes = set()

    def record(self, day: int, character: str, action: str, value: int) -> None:
        if isinstance(day, bool) or not isinstance(day, int) or day < 0:
            raise ValueError('invalid day')
        if not isinstance(character, str) or not character.strip():
            raise ValueError('invalid character')
        if action not in ('xp', 'gold', 'damage'):
            raise ValueError('invalid action')
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError('invalid value')
        name = character.strip()
        if name not in self._characters:
            self._characters.append(name)
        self._records.append((day, name, action, value))

    def _aggregate(self, through_day=None):
        result = {}
        for day, name, action, value in self._records:
            if through_day is not None and day > through_day:
                continue
            if name not in result:
                result[name] = {'xp': 0, 'gold': 0, 'damage': 0}
            result[name][action] += value
        return result

    def totals(self) -> dict[str, dict[str, int]]:
        return {name: values.copy() for name, values in self._aggregate().items()}

    def leaderboard(self, through_day: int | None=None) -> list[tuple[str, int, int, int]]:
        if through_day is not None and (isinstance(through_day, bool) or not isinstance(through_day, int) or through_day < 0):
            raise ValueError('invalid day')
        data = self._aggregate(through_day)
        rows = [(name, x['xp'], x['gold'], x['damage']) for name, x in data.items()]
        return sorted(rows, key=lambda row: (-row[1], -row[2], row[0]))

    def invite_code(self, length: int=12) -> str:
        if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 32):
            raise ValueError('invalid length')
        alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
        while True:
            code = ''.join((secrets.choice(alphabet) for _ in range(length)))
            if code not in self._codes:
                self._codes.add(code)
                return code

