import hashlib
import hmac
import os

def make_archive_passphrase_record(passphrase: str, shelfmark: str) -> str:
    if not shelfmark:
        raise ValueError('shelfmark must not be empty')
    salt = os.urandom(16)
    value = (shelfmark + '\x00' + passphrase).encode('utf-8')
    digest = hashlib.pbkdf2_hmac('sha256', value, salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_archive_passphrase(passphrase: str, shelfmark: str, record: str) -> bool:
    if not shelfmark:
        raise ValueError('shelfmark must not be empty')
    try:
        salt_text, digest_text = record.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    value = (shelfmark + '\x00' + passphrase).encode('utf-8')
    actual = hashlib.pbkdf2_hmac('sha256', value, salt, 100000)
    return hmac.compare_digest(actual, expected)

