from datetime import datetime
from html import escape

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc

def _prepare(records, since, min_count):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(min_count, bool) or not isinstance(min_count, int) or min_count < 1:
        raise ValueError('invalid minimum')
    cutoff = _time(since) if since is not None else None
    groups = {}
    prepared = []
    for index, record in enumerate(records):
        if not isinstance(record, dict) or set(record) != {'category', 'author', 'comment', 'rating', 'submitted'}:
            raise ValueError('invalid record')
        if not all((isinstance(record[k], str) for k in ('category', 'author', 'comment', 'submitted'))):
            raise ValueError('invalid record')
        if isinstance(record['rating'], bool) or not isinstance(record['rating'], int) or (not 1 <= record['rating'] <= 5):
            raise ValueError('invalid rating')
        moment = _time(record['submitted'])
        if cutoff is not None and moment < cutoff:
            continue
        item = (moment, index, record)
        prepared.append(item)
        groups.setdefault(record['category'], []).append(item)
    selected = {k: v for k, v in groups.items() if len(v) >= min_count}
    order = sorted(selected, key=lambda k: (-len(selected[k]), k.casefold()))
    return (prepared, selected, order)

def summarize_feedback(records: list[dict], since: str | None=None, min_count: int=1) -> list[dict]:
    _, groups, order = _prepare(records, since, min_count)
    result = []
    for category in order:
        items = groups[category]
        newest = max(items, key=lambda x: (-x[0].timestamp(), -x[1]))
        result.append({'category': category, 'count': len(items), 'average_rating': round(sum((x[2]['rating'] for x in items)) / len(items), 2), 'latest': newest[2]['submitted']})
    return result

def render_report(records: list[dict], title: str, since: str | None=None, min_count: int=1) -> str:
    prepared, groups, order = _prepare(records, since, min_count)
    e = lambda x: escape(str(x), quote=True)
    parts = ['<section class="consultation"><h1>' + e(title) + '</h1><p class="summary">' + str(len(prepared)) + ' submissions</p>']
    for category in order:
        items = sorted(groups[category], key=lambda x: (-x[0].timestamp(), x[1]))
        average = round(sum((x[2]['rating'] for x in items)) / len(items), 2)
        parts.append('<div class="category" data-category="' + e(category) + '"><h2>' + e(category) + '</h2><p class="stats">' + str(len(items)) + ' responses; average rating ' + str(average) + '</p><ul>')
        for _, _, record in items:
            submitted = e(record['submitted'])
            parts.append('<li><span class="author">' + e(record['author']) + '</span><time datetime="' + submitted + '">' + submitted + '</time><p>' + e(record['comment']) + '</p></li>')
