import json
import datetime
import math
_FIELDS = {'id', 'notary', 'day', 'start', 'duration', 'fee'}

def _check_records(records):
    if not isinstance(records, list):
        raise ValueError('records')
    result = []
    for item in records:
        if not isinstance(item, dict) or set(item) != _FIELDS:
            raise ValueError('record')
        if not isinstance(item['id'], str) or not item['id']:
            raise ValueError('id')
        if not isinstance(item['notary'], str) or not item['notary']:
            raise ValueError('notary')
        try:
            datetime.date.fromisoformat(item['day'])
        except (TypeError, ValueError):
            raise ValueError('day')
        if type(item['start']) is not int or not 0 <= item['start'] <= 1439:
            raise ValueError('start')
        if type(item['duration']) is not int or item['duration'] <= 0:
            raise ValueError('duration')
        if isinstance(item['fee'], bool) or not isinstance(item['fee'], (int, float)) or (not math.isfinite(item['fee'])) or (item['fee'] < 0):
            raise ValueError('fee')
        copy = dict(item)
        copy['fee'] = round(item['fee'], 2)
        result.append(copy)
    return result

def encode_appointments(records: list[dict]) -> bytes:
    return json.dumps(_check_records(records), separators=(',', ':')).encode()

def summarize_appointments(blob: bytes, day: str, page: int, page_size: int) -> dict:
    try:
        datetime.date.fromisoformat(day)
        records = json.loads(blob.decode())
        records = _check_records(records)
    except Exception as exc:
        raise ValueError('invalid input') from exc
    if type(page) is not int or page < 1 or type(page_size) is not int or (not 1 <= page_size <= 100):
        raise ValueError('paging')
    selected = [r for r in records if r['day'] == day]
    selected.sort(key=lambda r: (r['start'], r['id']))
    counts = {}
    for record in selected:
        counts[record['notary']] = counts.get(record['notary'], 0) + 1
    ordered_counts = dict(sorted(counts.items(), key=lambda pair: (-pair[1], pair[0])))
    total = round(sum((r['fee'] for r in selected)), 2)
    begin = (page - 1) * page_size
    return {'day': day, 'total_count': len(selected), 'total_fee': total, 'notary_counts': ordered_counts, 'appointments': selected[begin:begin + page_size]}

