import hmac
import json

def summarize_census_addresses(payload: bytes, signature: str, shared_key: bytes) -> dict:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    expected = hmac.new(shared_key, payload, hashlib.sha256).hexdigest()
    if len(supplied) != len(expected) or not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        text = payload.decode('utf-8')
        document = json.loads(text)
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError):
        raise ValueError('invalid payload')
    if not isinstance(document, dict) or not isinstance(document.get('addresses'), list):
        raise ValueError('invalid payload')
    groups = {}
    for item in document['addresses']:
        if not isinstance(item, dict):
            raise ValueError('invalid address')
        municipality = item.get('municipality')
        postcode = item.get('postcode')
        occupied = item.get('occupied')
        households = item.get('households')
        if not isinstance(municipality, str) or not municipality or (not isinstance(postcode, str)) or (len(postcode) != 5) or (not postcode.isascii()) or (not postcode.isdigit()) or (not isinstance(occupied, bool)) or (not isinstance(households, int)) or isinstance(households, bool) or (households < 0):
            raise ValueError('invalid address')
        if occupied:
            entry = groups.setdefault(municipality, [0, 0])
            entry[0] += 1
            entry[1] += households
    municipalities = [{'name': name, 'addresses': values[0], 'households': values[1]} for name, values in groups.items()]
    municipalities.sort(key=lambda item: (-item['households'], item['name']))
    return {'total_addresses': sum((item['addresses'] for item in municipalities)), 'total_households': sum((item['households'] for item in municipalities)), 'municipalities': municipalities}

