import csv
import os
import subprocess

def _records(path, minimum):
    result = subprocess.run(['sort', '-t,', '-k2,2n', '-k3,3n', '-k1,1', path], check=True, capture_output=True, text=True)
    lines = result.stdout.splitlines()
    if not lines:
        raise ValueError('missing header')
    rows = list(csv.reader(lines))
    if rows[0] != ['tile', 'row', 'col', 'quality', 'cloud', 'value']:
        raise ValueError('invalid header')
    output = []
    for fields in rows[1:]:
        if len(fields) != 6:
            raise ValueError('invalid row')
        try:
            quality = float(fields[3])
        except ValueError:
            raise ValueError('invalid quality')
        if quality < minimum:
            continue
        try:
            row = int(fields[1])
            col = int(fields[2])
            cloud = float(fields[4])
            value = float(fields[5])
        except ValueError:
            raise ValueError('invalid numeric field')
        output.append({'tile': fields[0], 'row': row, 'col': col, 'quality': quality, 'cloud': cloud, 'value': value})
    output.sort(key=lambda x: (x['row'], x['col'], x['tile']))
    return output

