    return _records(manifest_path, min_quality)

def summarize_scene(manifest_path: str, band_paths: list[str], min_quality: float=0.0) -> dict:
    records = _records(manifest_path, min_quality)
    total = sum((os.path.getsize(path) for path in band_paths))
    counts = {}
    for item in records:
        key = str(item['row'])
        counts[key] = counts.get(key, 0) + 1
    if not records:
        mean_value = None
        mean_cloud = None
    else:
        mean_value = sum((item['value'] for item in records)) / len(records)
        mean_cloud = sum((item['cloud'] for item in records)) / len(records)
    return {'tile_count': len(records), 'mean_value': mean_value, 'mean_cloud': mean_cloud, 'total_bytes': total, 'rows': counts}

