import math
import os
from pathlib import Path

def generate_maintenance_report(base_dir: str, filename: str, records: list[dict], min_cost: float=0.0) -> str:
    if not isinstance(filename, str) or not filename:
        raise ValueError('filename must not be empty')
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(min_cost, bool) or not isinstance(min_cost, (int, float)) or (not math.isfinite(min_cost)) or (min_cost < 0):
        raise ValueError('invalid minimum cost')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('vehicle_id'), str) or not record['vehicle_id']:
            raise ValueError('invalid vehicle')
        if not isinstance(record.get('service_type'), str) or not record['service_type']:
            raise ValueError('invalid service type')
        if not isinstance(record.get('date'), str) or not record['date']:
            raise ValueError('invalid date')
        cost = record.get('cost')
        if isinstance(cost, bool) or not isinstance(cost, (int, float)) or (not math.isfinite(cost)) or (cost < 0):
            raise ValueError('invalid cost')
        if cost >= min_cost:
            vehicle = record['vehicle_id']
            grouped.setdefault(vehicle, []).append(cost)
    output = []
    for vehicle, costs in grouped.items():
        total = sum(costs)
        output.append({'vehicle_id': vehicle, 'total_cost': round(total, 2), 'service_count': len(costs), 'average_cost': round(total / len(costs), 2)})
    output.sort(key=lambda item: (-item['total_cost'], item['vehicle_id']))
    base = Path(base_dir).resolve()
    target = (base / filename).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('output path is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w') as handle:
        json.dump(output, handle, indent=2)
        handle.write('\n')
    return str(target)

