from lxml import etree

def parse_orders(xml_text: str) -> list[dict]:
    try:
        root = etree.fromstring(xml_text.encode(), etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'plan' or (root.text and root.text.strip()):
        raise ValueError('invalid plan')
    orders = []
    ids = set()
    for node in root:
        if node.tag != 'order' or (node.tail and node.tail.strip()):
            raise ValueError('invalid child')
        a = node.attrib
        try:
            ident, priority, due, family, duration = (a['id'], int(a['priority']), int(a['due']), a['family'], int(a['duration']))
        except Exception as exc:
            raise ValueError('invalid attributes') from exc
        if not ident or not family or due < 0 or (duration <= 0) or (ident in ids):
            raise ValueError('invalid order')
        deps = []
        if node.text and node.text.strip():
            raise ValueError('invalid text')
        for child in node:
            if child.tag != 'depends-on' or set(child.attrib) != {'ref'} or (not child.attrib['ref']) or (child.text and child.text.strip()):
                raise ValueError('invalid dependency')
            deps.append(child.attrib['ref'])
            if child.tail and child.tail.strip():
                raise ValueError('invalid text')
        if set(a) != {'id', 'priority', 'due', 'family', 'duration'}:
            raise ValueError('invalid attributes')
        ids.add(ident)
        orders.append({'id': ident, 'priority': priority, 'due': due, 'family': family, 'duration': duration, 'depends': deps})
    known = {x['id'] for x in orders}
    if any((d not in known for x in orders for d in x['depends'])):
        raise ValueError('unknown dependency')
    return orders

def make_schedule(xml_text: str, machines: int=2) -> list[dict]:
    if not isinstance(machines, int) or isinstance(machines, bool) or machines <= 0:
        raise ValueError('invalid machines')
    orders = parse_orders(xml_text)
    pending = {x['id']: x for x in orders}
    avail = [0] * machines
    family = [None] * machines
    done = {}
    result = []
    while pending:
        ready = [x for x in pending.values() if all((d in done for d in x['depends']))]
        if not ready:
            raise ValueError('dependency cycle')
        order = sorted(ready, key=lambda x: (-x['priority'], x['due'], x['id']))[0]
