            raise ValueError('invalid row')
        try:
            stamp = values[0]
            if not stamp.endswith('Z'):
                raise ValueError
            when = datetime.fromisoformat(stamp[:-1] + '+00:00')
            when = when.astimezone(timezone.utc)
            if when in seen:
                raise ValueError('duplicate timestamp')
            nums = [float(x) for x in values[1:]]
        except Exception as exc:
            raise ValueError('invalid observation') from exc
        if not all((math.isfinite(x) for x in nums)) or not 0 <= nums[1] <= 100 or nums[2] < 0:
            raise ValueError('invalid measurement')
        seen.add(when)
        records.append({'timestamp': when, 'temperature': nums[0], 'humidity': nums[1], 'wind_speed': nums[2]})
    if header is None:
        raise ValueError('missing header')
    return sorted(records, key=lambda x: x['timestamp'])

def build_station_report(requester: dict, station: dict, text: str) -> str:
