        raise PermissionError('not permitted')
    records = parse_observation_lines(text)
    groups = defaultdict(list)
    for record in records:
        t = record['timestamp']
        hour = t.replace(minute=0, second=0, microsecond=0)
        groups[hour].append(record)
    lines = ['station_id,hour,avg_temperature,avg_humidity,max_wind_speed,reading_count']
    for hour in sorted(groups):
        items = groups[hour]
        avg_t = sum((x['temperature'] for x in items)) / len(items)
        avg_h = sum((x['humidity'] for x in items)) / len(items)
        max_w = max((x['wind_speed'] for x in items))
        lines.append(f"{station['id']},{hour:%Y-%m-%dT%H:00:00Z},{avg_t:.2f},{avg_h:.2f},{max_w:.2f},{len(items)}")
    return '\n'.join(lines) + '\n'

