    if status is not None:
        clauses.append(f"status = '{status}'")
    if search:
        pattern = f'%{search}%'
        clauses.append(f"(lower(container_id) LIKE lower('{pattern}') OR lower(vessel) LIKE lower('{pattern}'))")
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    query = 'SELECT container_id, vessel, terminal, status, eta, weight FROM containers' + where
    query += f' ORDER BY {sort_by} {direction}, container_id ASC LIMIT ? OFFSET ?'
    cursor = conn.execute(query, (limit, offset))
    names = ['container_id', 'vessel', 'terminal', 'status', 'eta', 'weight']
    return [dict(zip(names, row)) for row in cursor.fetchall()]

