import requests

def summarize_census_survey(url: str, survey_id: str, min_age: int=0) -> list[dict[str, object]]:
    if not isinstance(url, str) or not url:
        raise ValueError('invalid url')
    if not isinstance(survey_id, str) or not survey_id:
        raise ValueError('invalid survey_id')
    if isinstance(min_age, bool) or not isinstance(min_age, int) or min_age < 0:
        raise ValueError('invalid min_age')
    totals = {}
    page = 1
    while True:
        result = requests.get(url, params={'survey_id': survey_id, 'page': page, 'per_page': 100}, headers={'Accept': 'application/json'})
        if result.status_code != 200:
            raise RuntimeError('request failed')
        try:
            body = result.json()
        except Exception as exc:
            raise ValueError('invalid response') from exc
        if not isinstance(body, dict) or not isinstance(body.get('responses'), list):
            raise ValueError('invalid response')
        for record in body['responses']:
            if not isinstance(record, dict):
                raise ValueError('invalid record')
            region = record.get('region')
            age = record.get('age')
            rating = record.get('rating')
            if not isinstance(region, str) or not region or isinstance(age, bool) or (not isinstance(age, int)) or (age < 0) or isinstance(rating, bool) or (not isinstance(rating, int)) or (not 1 <= rating <= 5):
                raise ValueError('invalid record')
            if age >= min_age:
                if region not in totals:
                    totals[region] = [0, 0]
                totals[region][0] += 1
                totals[region][1] += rating
        next_page = body.get('next')
        if next_page is None:
            break
        if isinstance(next_page, bool) or not isinstance(next_page, int) or next_page < 1:
            raise ValueError('invalid next page')
        page = next_page
    output = [{'region': region, 'count': values[0], 'average_rating': round(values[1] / values[0], 2)} for region, values in totals.items()]
    return sorted(output, key=lambda item: (-item['count'], item['region']))

