from pathlib import Path

def write_substitute_assignment(base_dir: str, relative_name: str, assignment: str) -> str:
    if not relative_name or os.path.isabs(relative_name):
        raise ValueError('relative_name must be a non-empty relative path')
    base = Path(base_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('path is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(assignment, encoding='utf-8')
    return str(target)

import csv
import os
import tempfile

def export_loan_offers(offers: list[dict[str, object]], destination: str) -> int:
    selected = []
    for offer in offers:
        if offer.get('status') != 'open':
            continue
        required = ('lender', 'amount', 'apr', 'term_months')
        if any((field not in offer for field in required)):
            raise ValueError('missing offer field')
        if offer['amount'] <= 0 or offer['apr'] < 0 or offer['term_months'] <= 0:
            raise ValueError('invalid offer values')
        selected.append(offer)
    selected.sort(key=lambda item: (item['apr'], item['lender']))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.offers-', dir=parent, text=True)
    os.close(fd)
    try:
        with open(temporary, 'w', newline='') as file:
            writer = csv.writer(file)
            writer.writerow(('lender', 'amount', 'apr', 'term_months'))
            for offer in selected:
                writer.writerow(tuple((offer[field] for field in ('lender', 'amount', 'apr', 'term_months'))))
        os.replace(temporary, destination)
    except BaseException:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    return len(selected)

