def parse_tickets(csv_text: str) -> list[dict]:
    if not csv_text:
        raise ValueError('empty input')
    reader = csv.DictReader(io.StringIO(csv_text))
    expected = ['ticket_id', 'mine', 'day', 'tonnes', 'assay', 'moisture']
    if reader.fieldnames != expected:
        raise ValueError('invalid header')
    result = []
    seen = set()
    try:
        for row in reader:
            if None in row.values() or any((v is None for v in row.values())):
                raise ValueError('invalid row')
            ticket_id = row['ticket_id']
            mine = row['mine']
            if not ticket_id or not mine or ticket_id in seen:
                raise ValueError('invalid ticket')
            day = date.fromisoformat(row['day'])
            values = [float(row[k]) for k in ('tonnes', 'assay', 'moisture')]
            if not all((math.isfinite(v) for v in values)):
                raise ValueError('nonfinite value')
            if values[0] < 0 or not 0 <= values[1] <= 100 or (not 0 <= values[2] <= 100):
                raise ValueError('out of range')
            seen.add(ticket_id)
            result.append({'ticket_id': ticket_id, 'mine': mine, 'day': day, 'tonnes': values[0], 'assay': values[1], 'moisture': values[2]})
    except (TypeError, ValueError, OverflowError):
        raise ValueError('invalid input')
    if not result:
        raise ValueError('no rows')
    return result

def reconcile_tickets(records: list[dict], target_assays: dict[str, float], window: int=3) -> list[dict]:
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('invalid window')
    groups = {}
    for r in records:
        try:
            target = float(target_assays[r['mine']])
            if not math.isfinite(target):
                raise ValueError
            dry = r['tonnes'] * (1 - r['moisture'] / 100)
        except (KeyError, TypeError, ValueError, OverflowError):
            raise ValueError('invalid records')
        groups.setdefault(r['mine'], []).append((r, dry, target))
    output = []
    for mine in sorted(groups):
        items = sorted(groups[mine], key=lambda x: (x[0]['day'], x[0]['ticket_id']))
        prior = []
        for r, dry, target in items:
            selected = prior[-window:]
            total = sum((x[1] for x in selected))
            rolling = None if total == 0 else round(sum((x[0]['assay'] * x[1] for x in selected)) / total, 6)
            output.append({'ticket_id': r['ticket_id'], 'mine': mine, 'day': r['day'].isoformat(), 'dry_tonnes': round(dry, 6), 'rolling_assay': rolling, 'assay_delta': round(r['assay'] - target, 6)})
            prior.append((r, dry))
    return output

def write_reconciliation(base_dir: str, relative_name: str, rows: list[dict]) -> str:
    base = os.path.abspath(base_dir)
    if os.path.isabs(relative_name):
        raise ValueError('absolute name')
    path = os.path.abspath(os.path.join(base, relative_name))
    try:
        if os.path.commonpath([base, path]) != base:
            raise ValueError('outside base')
    except ValueError:
        raise ValueError('outside base')
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        json.dump({'count': len(rows), 'rows': rows}, f, indent=2, sort_keys=True)
        f.write('\n')
    return path

