def fetch_flags(base_url: str, environment: str, api_key: str) -> dict[str, dict]:
    response = requests.get(base_url.rstrip('/') + '/v1/flags', params={'environment': environment}, headers={'Authorization': 'Bearer ' + api_key}, timeout=5)
    if response.status_code != 200:
        raise RuntimeError(f'request failed with status {response.status_code}')
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('flags'), list):
        raise ValueError('flags must be a list')
    result = {}
    for flag in data['flags']:
        if not isinstance(flag, dict) or not isinstance(flag.get('key'), str) or (not isinstance(flag.get('enabled'), bool)) or (not isinstance(flag.get('default'), str)) or (not isinstance(flag.get('rules'), list)):
            raise ValueError('invalid flag')
        if flag['key'] in result:
            raise ValueError('duplicate flag')
        result[flag['key']] = flag
    return result

def resolve_flags(flags: dict[str, dict], user: dict[str, object]) -> dict[str, str | None]:
    result = {}
    for key in sorted(flags):
        flag = flags[key]
        if not isinstance(flag.get('enabled'), bool) or not isinstance(flag.get('default'), str) or (not isinstance(flag.get('rules'), list)):
            raise ValueError('invalid flag')
        if not flag['enabled']:
            result[key] = None
            continue
        value = None
        for rule in flag['rules']:
            if not isinstance(rule, dict) or not isinstance(rule.get('attribute'), str) or 'equals' not in rule or (not isinstance(rule.get('variant'), str)):
                raise ValueError('invalid rule')
            if rule['attribute'] in user and user[rule['attribute']] == rule['equals']:
                value = rule['variant']
                break
        if value is None:
            rollout = flag.get('rollout')
            if rollout is not None:
                if not isinstance(rollout, list):
                    raise ValueError('invalid rollout')
                if 'id' not in user:
                    raise ValueError('user id required')
                bucket = int(hashlib.sha256((key + ':' + str(user['id'])).encode()).hexdigest()[:8], 16) % 100
                total = 0
                for entry in rollout:
                    if not isinstance(entry, dict) or not isinstance(entry.get('variant'), str) or (not isinstance(entry.get('weight'), int)) or isinstance(entry.get('weight'), bool) or (entry['weight'] < 0):
                        raise ValueError('invalid rollout entry')
                    total += entry['weight']
                    if bucket < total:
                        value = entry['variant']
                        break
            if value is None:
                value = flag['default']
        result[key] = value
    return result

def summarize_flag_changes(before: dict[str, dict], after: dict[str, dict]) -> list[dict[str, object]]:
    changes = []
    for key in sorted(set(before) | set(after)):
        if key not in before:
            changes.append({'key': key, 'change': 'added', 'before': None, 'after': after[key]})
        elif key not in after:
            changes.append({'key': key, 'change': 'removed', 'before': before[key], 'after': None})
        elif before[key] != after[key]:
            changes.append({'key': key, 'change': 'changed', 'before': before[key], 'after': after[key]})
    return changes

