def analyze_cabin(path: str, window_seconds: int, zone: str | None=None) -> list[dict]:
    if window_seconds <= 0:
        raise ValueError('window_seconds must be positive')
    completed = subprocess.run(['sort', '-t,', '-k1,1n', path], check=True, capture_output=True, text=True)
    groups = {}
    for raw in completed.stdout.splitlines():
        if not raw.strip():
            continue
        try:
            row = next(csv.reader([raw]))
        except (csv.Error, StopIteration) as exc:
            raise ValueError('malformed row') from exc
        if len(row) != 5:
            raise ValueError('malformed row')
        timestamp_text, sensor, row_zone, value_text, status = row
        if not sensor or not row_zone or (not status):
            raise ValueError('empty field')
        try:
            timestamp = int(timestamp_text)
            value = float(value_text)
        except ValueError as exc:
            raise ValueError('invalid value') from exc
        if timestamp < 0 or not math.isfinite(value):
            raise ValueError('invalid value')
        if zone is not None and row_zone != zone:
            continue
        start = timestamp // window_seconds * window_seconds
        key = (start, row_zone)
        groups.setdefault(key, []).append((value, status))
    result = []
    for (start, row_zone), readings in sorted(groups.items()):
        values = [item[0] for item in readings]
        result.append({'start': start, 'zone': row_zone, 'count': len(values), 'average': round(sum(values) / len(values), 6), 'minimum': round(min(values), 6), 'maximum': round(max(values), 6), 'alerts': sum((status != 'OK' for _, status in readings))})
    return result

