import datetime
import requests

def loyalty_summary(member_id: str, start_date: str, end_date: str) -> list[dict]:
    if not isinstance(member_id, str) or not member_id:
        raise ValueError('invalid member_id')
    try:
        start = datetime.date.fromisoformat(start_date)
        end = datetime.date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end:
        raise ValueError('invalid date range')
    url = 'https://loyalty.example.com/api/v1/transactions'
    params = {'member_id': member_id, 'start_date': start_date, 'end_date': end_date}
    totals = {}
    while True:
        response = requests.get(url, params=params, headers={'Accept': 'application/json'}, timeout=10)
        if response.status_code != 200:
            raise RuntimeError('request failed')
        payload = response.json()
        for transaction in payload['transactions']:
            restaurant = transaction['restaurant']
            points = transaction['points']
            date_text = transaction['date']
            if not isinstance(restaurant, str) or not restaurant:
                raise ValueError('invalid transaction')
            if isinstance(points, bool) or not isinstance(points, int):
                raise ValueError('invalid transaction')
            try:
                transaction_date = datetime.date.fromisoformat(date_text)
            except (TypeError, ValueError):
                raise ValueError('invalid transaction')
            if transaction['status'] == 'completed' and start <= transaction_date <= end:
                if restaurant not in totals:
                    totals[restaurant] = [0, 0]
                totals[restaurant][0] += points
                totals[restaurant][1] += 1
        next_page = payload['next_page']
        if next_page is None:
            break
        params = {'member_id': member_id, 'start_date': start_date, 'end_date': end_date, 'page_token': next_page}
    result = [{'restaurant': name, 'points': values[0], 'visits': values[1]} for name, values in totals.items()]
    return sorted(result, key=lambda item: (-item['points'], item['restaurant']))

