def setup_database(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS outages (outage_id INTEGER PRIMARY KEY, street TEXT NOT NULL, district TEXT NOT NULL, severity INTEGER NOT NULL, started TEXT NOT NULL, ended TEXT NOT NULL)')
    conn.commit()

def save_outage(conn: sqlite3.Connection, outage_id: int, street: str, district: str, severity: int, started: str, ended: str) -> None:
    if not isinstance(outage_id, int) or isinstance(outage_id, bool) or outage_id <= 0:
        raise ValueError('invalid outage_id')
    if not isinstance(street, str) or not street or (not isinstance(district, str)) or (not district):
        raise ValueError('invalid text')
    if not isinstance(severity, int) or isinstance(severity, bool) or (not 1 <= severity <= 5):
        raise ValueError('invalid severity')
    try:
        begin = datetime.fromisoformat(started)
        finish = datetime.fromisoformat(ended)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if finish < begin:
        raise ValueError('invalid interval')
    conn.execute('INSERT OR REPLACE INTO outages VALUES (?, ?, ?, ?, ?, ?)', (outage_id, street, district, severity, started, ended))
    conn.commit()

def list_outages(conn: sqlite3.Connection, district: str | None=None, min_severity: int=1, sort_by: str='started') -> list[dict[str, object]]:
    if not isinstance(min_severity, int) or isinstance(min_severity, bool) or (not 1 <= min_severity <= 5):
        raise ValueError('invalid severity')
    columns = {'started': 'started', 'severity': 'severity', 'street': 'street', 'district': 'district'}
    if sort_by not in columns:
        raise ValueError('invalid sort')
    query = 'SELECT outage_id, street, district, severity, started, ended FROM outages WHERE severity >= ?'
    args: list[object] = [min_severity]
    if district is not None:
        query += ' AND district = ?'
        args.append(district)
    query += ' ORDER BY ' + columns[sort_by] + ', outage_id'
    rows = conn.execute(query, args).fetchall()
    result = []
    for outage_id, street, area, severity, started, ended in rows:
        minutes = int((datetime.fromisoformat(ended) - datetime.fromisoformat(started)).total_seconds() // 60)
        result.append({'outage_id': outage_id, 'street': street, 'district': area, 'severity': severity, 'started': started, 'ended': ended, 'duration_minutes': minutes})
    return result

def daily_report(conn: sqlite3.Connection, district: str | None=None) -> list[dict[str, object]]:
    groups: dict[str, dict[str, object]] = {}
    for row in list_outages(conn, district=district):
        date = row['started'][:10]
        if date not in groups:
            groups[date] = {'date': date, 'outage_count': 0, 'total_minutes': 0, 'max_severity': 0}
        group = groups[date]
        group['outage_count'] += 1
        group['total_minutes'] += row['duration_minutes']
        group['max_severity'] = max(group['max_severity'], row['severity'])
    return [groups[key] for key in sorted(groups)]

