def close_charging_session(user: dict, session: dict, ended_at: int) -> dict:
    if session['status'] != 'active':
        raise ValueError('session is not active')
    same_tenant = user['tenant_id'] == session['tenant_id']
    is_owner = user['id'] == session['owner_id']
    is_operator = 'operator' in user.get('roles', [])
    if not same_tenant or not (is_owner or is_operator):
        raise PermissionError('not permitted to close session')
    session['status'] = 'completed'
    session['ended_at'] = ended_at
    amount = round(session['energy_kwh'] * session['rate_cents_per_kwh'])
    return {'session_id': session['id'], 'user_id': user['id'], 'energy_kwh': session['energy_kwh'], 'amount_cents': amount, 'ended_at': ended_at}

