def render_delivery_report(receipts: list[dict], page: int=1, per_page: int=10) -> str:
    if page < 1 or per_page < 1:
        raise ValueError('invalid pagination')
    normalized = []
    for receipt in receipts:
        try:
            recipient = receipt['recipient']
            status = receipt['status']
            timestamp = receipt['timestamp']
            attempts = receipt['attempts']
            latency = receipt['latency_ms']
        except (KeyError, TypeError):
            raise ValueError('invalid receipt')
        if not isinstance(recipient, str) or not recipient:
            raise ValueError('invalid receipt')
        if status not in {'delivered', 'failed', 'pending'}:
            raise ValueError('invalid receipt')
        if not isinstance(timestamp, str):
            raise ValueError('invalid receipt')
        try:
            datetime.fromisoformat(timestamp)
        except ValueError:
            raise ValueError('invalid receipt')
        if isinstance(attempts, bool) or not isinstance(attempts, int) or attempts < 0:
            raise ValueError('invalid receipt')
        if isinstance(latency, bool) or not isinstance(latency, int) or latency < 0:
            raise ValueError('invalid receipt')
        normalized.append((recipient, status, timestamp, attempts, latency))
    normalized.sort(key=lambda item: (-datetime.fromisoformat(item[2]).timestamp(), item[0]))
    total = len(normalized)
    average = sum((item[4] for item in normalized)) / total if total else 0
    start = (page - 1) * per_page
    selected = normalized[start:start + per_page]
    rows = ''.join((f'<tr><td>{escape(recipient, quote=True)}</td><td>{escape(status, quote=True)}</td><td>{escape(timestamp, quote=True)}</td><td>{attempts}</td><td>{latency}</td></tr>' for recipient, status, timestamp, attempts, latency in selected))
    return f'<div class="delivery-report"><h1>Delivery receipts</h1><p class="summary">Showing {len(selected)} of {total} receipts; average latency: {average:.2f} ms</p><table><thead><tr><th>Recipient</th><th>Status</th><th>Timestamp</th><th>Attempts</th><th>Latency (ms)</th></tr></thead><tbody>{rows}</tbody></table></div>'

