import csv
import io
from datetime import date

def parse_contribution_rows(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text, newline='')))
    except csv.Error as exc:
        raise ValueError from exc
    if not rows:
        raise ValueError
    required = ['employee_id', 'date', 'employee_cents', 'employer_cents']
    header = rows[0]
    if len(header) != 4 or len(set(header)) != 4 or set(header) != set(required):
        raise ValueError
    out = []
    for fields in rows[1:]:
        if len(fields) != 4:
            raise ValueError
        d = dict(zip(header, fields))
        employee = d['employee_id'].strip()
        dates = d['date'].strip()
        if not employee or len(dates) != 10:
            raise ValueError
        try:
            date.fromisoformat(dates)
            ec = int(d['employee_cents'].strip())
            rc = int(d['employer_cents'].strip())
        except (ValueError, TypeError):
            raise ValueError
        if ec < 0 or rc < 0 or str(ec) != d['employee_cents'].strip() or (str(rc) != d['employer_cents'].strip()):
            raise ValueError
        out.append({'employee_id': employee, 'date': dates, 'employee_cents': ec, 'employer_cents': rc})
    return out

def calculate_pension_report(requester: dict, plan: dict, rows: list[dict], year: int) -> dict:
    if not isinstance(requester, dict) or not isinstance(plan, dict) or (not isinstance(rows, list)) or (not isinstance(year, int)) or isinstance(year, bool) or (not 1900 <= year <= 2200):
        raise ValueError
    try:
        tenant = plan['tenant_id']
        employer = plan['employer_id']
        annual = plan['annual_employee_limit_cents']
        monthly = plan['monthly_employee_limit_cents']
        rate = plan['match_percent']
    except (KeyError, TypeError):
        raise ValueError
    if not isinstance(requester.get('roles'), list) or any((not isinstance(x, str) for x in requester['roles'])):
        raise ValueError
    if not (requester.get('tenant_id') == tenant and (requester.get('employer_id') == employer or 'pension_admin' in requester['roles'])):
        raise PermissionError
    if not all((isinstance(x, int) and (not isinstance(x, bool)) and (x >= 0) for x in (annual, monthly))) or not isinstance(rate, int) or isinstance(rate, bool) or (not 0 <= rate <= 100):
        raise ValueError
    grouped = {}
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError
        try:
            eid = row['employee_id']
            ds = row['date']
            ec = row['employee_cents']
            rc = row['employer_cents']
        except KeyError:
            raise ValueError
        try:
            dt = date.fromisoformat(ds)
        except (ValueError, TypeError):
            raise ValueError
        if not isinstance(eid, str) or not eid or (not isinstance(ec, int)) or (not isinstance(rc, int)) or (ec < 0) or (rc < 0):
            raise ValueError
        if dt.year != year:
            continue
        key = (eid, dt.month)
        a, b = grouped.get(key, (0, 0))
        grouped[key] = (a + ec, b + rc)
    employees = []
    for eid in sorted({k[0] for k in grouped}):
        vals = [min(monthly, grouped.get((eid, m), (0, 0))[0]) for m in range(1, 13)]
        matches = [min(v * rate // 100, grouped.get((eid, m), (0, 0))[1]) for m, v in enumerate(vals, 1)]
        total = min(annual, sum(vals))
        employees.append({'employee_id': eid, 'monthly_employee_cents': vals, 'annual_employee_cents': total, 'monthly_employer_match_cents': matches, 'annual_employer_match_cents': sum(matches)})
    return {'year': year, 'tenant_id': tenant, 'employer_id': employer, 'employees': employees}

