        employees.append({'employee_id': eid, 'monthly_employee_cents': vals, 'annual_employee_cents': total, 'monthly_employer_match_cents': matches, 'annual_employer_match_cents': sum(matches)})
    return {'year': year, 'tenant_id': tenant, 'employer_id': employer, 'employees': employees}

