def initialize_database(conn: sqlite3.Connection) -> None:
    conn.execute('create table if not exists observations (id integer primary key, site text not null, observed_on text not null, rate real not null, unique(site, observed_on))')
    conn.commit()

def _date(value):
    try:
        datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if len(value) != 10:
        raise ValueError('invalid date')

def add_observations(conn: sqlite3.Connection, observations: list[dict]) -> int:
    checked = []
    for item in observations:
        site = item.get('site')
        date = item.get('observed_on')
        rate = item.get('rate')
        if not isinstance(site, str) or not site.strip() or (not isinstance(date, str)):
            raise ValueError('invalid observation')
        _date(date)
        if isinstance(rate, bool) or not isinstance(rate, (int, float)) or (not math.isfinite(rate)) or (rate < 0):
            raise ValueError('invalid observation')
        checked.append((site.strip(), date, float(rate)))
    try:
        with conn:
            conn.executemany('insert into observations(site, observed_on, rate) values (?, ?, ?)', checked)
    except sqlite3.IntegrityError as exc:
        raise ValueError('duplicate observation') from exc
    return len(checked)

def erosion_report(conn: sqlite3.Connection, start: str | None=None, end: str | None=None, sort: str='site') -> list[dict]:
    if start is not None:
        _date(start)
    if end is not None:
        _date(end)
    if start is not None and end is not None and (end < start):
        raise ValueError('invalid range')
    orders = {'site': 'site asc', 'average_rate': 'average_rate asc', 'latest_rate': 'latest_rate asc', 'observations': 'observations asc'}
    if sort not in orders:
        raise ValueError('invalid sort')
    where = []
    args = []
    if start is not None:
        where.append('observed_on >= ?')
        args.append(start)
    if end is not None:
        where.append('observed_on <= ?')
        args.append(end)
    clause = ' where ' + ' and '.join(where) if where else ''
    sql = 'with grouped as (select site, count(*) observations, avg(rate) average_rate, max(observed_on) latest_date from observations' + clause + ' group by site) select g.site, g.observations, g.average_rate, g.latest_date, (select o.rate from observations o where o.site=g.site and o.observed_on=g.latest_date order by o.id desc limit 1) latest_rate from grouped g order by ' + orders[sort] + ', site asc'
    return [{'site': r[0], 'observations': r[1], 'average_rate': round(r[2], 3), 'latest_date': r[3], 'latest_rate': r[4]} for r in conn.execute(sql, args)]

