import csv
import datetime
import decimal
import subprocess

def rank_staff_hours(path: str, page: int=1, page_size: int=10) -> list[tuple[str, float]]:
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid pagination')
    try:
        result = subprocess.run(['sort', '-t,', '-k1,1', path], capture_output=True, text=True, check=True)
    except (OSError, subprocess.CalledProcessError) as exc:
        raise ValueError('unable to read file') from exc
    totals = {}
    header = False
    try:
        for row in csv.reader(result.stdout.splitlines()):
            if not row:
                continue
            if row == ['employee', 'date', 'start', 'end', 'break_minutes']:
                header = True
                continue
            if len(row) != 5:
                raise ValueError('invalid record')
            employee, date_text, start_text, end_text, break_text = row
            if not employee:
                raise ValueError('invalid employee')
            datetime.date.fromisoformat(date_text)
            start = datetime.datetime.strptime(start_text, '%H:%M')
            end = datetime.datetime.strptime(end_text, '%H:%M')
            duration = end.hour * 60 + end.minute - (start.hour * 60 + start.minute)
            if duration < 0:
                duration += 24 * 60
            break_minutes = int(break_text)
            if break_minutes < 0 or break_minutes > duration:
                raise ValueError('invalid break')
            totals[employee] = totals.get(employee, 0) + duration - break_minutes
    except (ValueError, TypeError) as exc:
        raise ValueError('invalid record') from exc
    if not header:
        raise ValueError('missing header')
    ranked = sorted(((name, float(decimal.Decimal(minutes) / decimal.Decimal(60)).__round__(2)) for name, minutes in totals.items()), key=lambda item: (-item[1], item[0]))
    begin = (page - 1) * page_size
    return ranked[begin:begin + page_size]

