    compatible = {'O': {'O', 'A', 'B', 'AB'}, 'A': {'A', 'AB'}, 'B': {'B', 'AB'}, 'AB': {'AB'}}
    used = set()
    result = {}
    for organ in organs:
        if len(result) >= limit:
            break
        choices = []
        for candidate in candidates:
            if candidate['id'] in used or candidate['status'] != 'active':
                continue
            if candidate['blood_type'] not in compatible.get(organ['blood_type'], set()):
                continue
            if evaluate_expression(eligibility, candidate):
