import json

def pack_occupancy(records: list[dict]) -> bytes:
    return json.dumps(records, sort_keys=True, separators=(',', ':')).encode('utf-8')

def occupancy_report(blob: bytes, min_minutes: int=0, page: int=1, page_size: int=10) -> dict:
    if isinstance(min_minutes, bool) or not isinstance(min_minutes, int) or min_minutes < 0:
        raise ValueError('invalid min_minutes')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page_size')
    try:
        records = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        room = record.get('room')
        minutes = record.get('minutes')
        people = record.get('people')
        if not isinstance(room, str) or not room or isinstance(minutes, bool) or (not isinstance(minutes, int)) or (minutes < 0) or isinstance(people, bool) or (not isinstance(people, int)) or (people < 0):
            raise ValueError('invalid record')
        if minutes < min_minutes:
            continue
        item = grouped.setdefault(room, {'room': room, 'minutes': 0, 'peak_people': 0, 'visits': 0})
        item['minutes'] += minutes
        item['peak_people'] = max(item['peak_people'], people)
        item['visits'] += 1
    ordered = sorted(grouped.values(), key=lambda item: (-item['minutes'], item['room']))
    start = (page - 1) * page_size
    return {'rooms': ordered[start:start + page_size], 'total_rooms': len(ordered), 'page': page, 'page_size': page_size}

