    if min_lines < 0 or page < 1 or page_size < 1:
        raise ValueError('invalid numeric argument')
    records = []
    for path in paths:
        if not isinstance(path, str):
            raise TypeError('path must be a string')
        completed = subprocess.run(['wc', '-l', path], capture_output=True, text=True)
        if completed.returncode != 0:
            raise FileNotFoundError(path)
        try:
            lines = int(completed.stdout.split()[0])
        except (IndexError, ValueError):
            raise FileNotFoundError(path)
        if lines >= min_lines:
            records.append({'path': path, 'lines': lines})
    records.sort(key=lambda item: (-item['lines'], item['path']))
    total_files = len(records)
    total_lines = sum((item['lines'] for item in records))
    average = round(total_lines / total_files, 2) if total_files else 0.0
    pages = (total_files + page_size - 1) // page_size if total_files else 0
    start = (page - 1) * page_size
    return {'items': records[start:start + page_size], 'total_files': total_files, 'total_lines': total_lines, 'average_lines': average, 'page': page, 'page_size': page_size, 'pages': pages}

