        raise ValueError('invalid root')
    rows = []
    for node in root:
        if node.tag != 'request':
            raise ValueError('invalid request')
        values = {key: node.get(key) for key in ('id', 'agency', 'status', 'submitted', 'fee')}
        if any((value is None or not value.strip() for value in values.values())):
            raise ValueError('missing field')
        try:
            date.fromisoformat(values['submitted'])
            fee = Decimal(values['fee'])
        except (ValueError, InvalidOperation) as exc:
            raise ValueError('invalid field') from exc
        if not fee.is_finite() or fee < 0:
            raise ValueError('invalid fee')
        if status is None or values['status'] == status:
            rows.append((values, fee))
