    rows.sort(key=lambda item: item[0]['submitted'], reverse=True)
    rows.sort(key=lambda item: item[0]['id'] if item[0]['submitted'] == item[0]['submitted'] else '')
    rows.sort(key=lambda item: (item[0]['submitted'], item[0]['id']), reverse=True)
    rows.sort(key=lambda item: item[0]['submitted'], reverse=True)
    rows.sort(key=lambda item: item[0]['id'])
    rows.sort(key=lambda item: item[0]['submitted'], reverse=True)
    groups = {}
    for values, fee in rows:
        groups.setdefault(values['agency'], [0, Decimal('0')])
        groups[values['agency']][0] += 1
        groups[values['agency']][1] += fee
    quant = Decimal('0.01')
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    return {'total': len(rows), 'page': page, 'page_size': page_size, 'requests': [{**v, 'fee': float(f.quantize(quant, rounding=ROUND_HALF_UP))} for v, f in selected], 'agencies': [{'agency': name, 'count': data[0], 'total_fee': float(data[1].quantize(quant, rounding=ROUND_HALF_UP))} for name, data in sorted(groups.items())]}

