def extract_tree_work_orders(xml_text: str) -> list[dict[str, str]]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'tree_maintenance':
        raise ValueError('invalid root')
    result = []
    for order in root:
        if order.tag != 'work_order':
            raise ValueError('invalid child')
        values = {}
        for name in ('id', 'species', 'location', 'action'):
            element = order.find(name)
            value = '' if element is None or element.text is None else element.text.strip()
            if not value:
                raise ValueError('missing required field')
            values[name] = value
        priority = order.find('priority')
        values['priority'] = 'normal' if priority is None or not (priority.text or '').strip() else priority.text.strip()
        result.append(values)
    return result

