import os
import json
import hmac
import hashlib
from decimal import Decimal, InvalidOperation

def build_customs_declaration(records: list[dict], config: dict | None=None) -> dict:
    key = None
    if config is not None and 'signing_key' in config:
        key = config['signing_key']
    else:
        key = os.environ.get('CUSTOMS_SIGNING_KEY')
    if key is None:
        raise ValueError('missing CUSTOMS_SIGNING_KEY signing key')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be a mapping')
        try:
            importer = record['importer']
            country = record['country']
            hs_code = record['hs_code']
            quantity = record['quantity']
            value = record['value']
        except KeyError as exc:
            raise ValueError('missing record field') from exc
        if not isinstance(importer, str) or not importer or (not isinstance(country, str)) or (not country) or (not isinstance(hs_code, str)) or (not hs_code):
            raise ValueError('invalid record text')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
            raise ValueError('invalid quantity')
        try:
            amount = Decimal(str(value))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid value')
        if not amount.is_finite() or amount < 0 or amount * 100 != (amount * 100).to_integral_value():
            raise ValueError('invalid value')
        cents = int(amount * 100)
        group = grouped.setdefault((importer, country, hs_code), [0, 0])
        group[0] += quantity
        group[1] += cents
    entries = []
    for (importer, country, hs_code), (quantity, cents) in sorted(grouped.items()):
        entries.append({'importer': importer, 'country': country, 'hs_code': hs_code, 'quantity': quantity, 'value_cents': cents})
    totals = {'quantity': sum((x['quantity'] for x in entries)), 'value_cents': sum((x['value_cents'] for x in entries))}
    unsigned = {'entries': entries, 'totals': totals}
    raw = json.dumps(unsigned, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(str(key).encode(), raw, hashlib.sha256).hexdigest()
    return {'entries': entries, 'totals': totals, 'signature': signature}

