    if isinstance(page, bool) or not isinstance(page, int) or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    root = os.path.realpath(base_dir)
    records = []
    for name in names:
        if not isinstance(name, str) or not name:
            raise ValueError('invalid filename')
        path = os.path.realpath(os.path.join(root, name))
        try:
            inside = os.path.commonpath([root, path]) == root
        except ValueError:
            inside = False
        if not inside:
            raise ValueError('filename outside base directory')
        with open(path, encoding='utf-8') as handle:
            try:
                item = json.load(handle)
            except json.JSONDecodeError as exc:
                raise ValueError('invalid JSON') from exc
        required = ('booking_id', 'client', 'session_date', 'package', 'price_cents', 'status')
        if not isinstance(item, dict) or any((key not in item for key in required)):
            raise ValueError('invalid booking')
        if any((not isinstance(item[key], str) or not item[key] for key in ('booking_id', 'client', 'package'))):
            raise ValueError('invalid booking')
        if item['status'] not in ('confirmed', 'cancelled') or isinstance(item['price_cents'], bool) or (not isinstance(item['price_cents'], int)) or (item['price_cents'] < 0):
            raise ValueError('invalid booking')
        try:
            datetime.date.fromisoformat(item['session_date'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid date') from exc
        if item['status'] == 'confirmed':
