import base64
import hashlib
import hmac
import os
from datetime import date

def enroll_technician(username: str, password: str, role: str) -> dict:
    if not isinstance(username, str) or not username:
        raise ValueError('invalid username')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if not isinstance(role, str) or not role:
        raise ValueError('invalid role')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    encoded = base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()
    return {'username': username, 'role': role, 'password_hash': encoded}

def authenticate_technician(technician: dict, password: str) -> bool:
    if not isinstance(technician, dict) or not isinstance(password, str):
        return False
    try:
        salt_text, digest_text = technician['password_hash'].split(':')
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, AttributeError, ValueError, TypeError):
        return False

def maintenance_report(records: list[dict], status: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(records, list) or not isinstance(page, int) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid arguments')
    if status is not None and status not in {'scheduled', 'completed', 'cancelled'}:
        raise ValueError('invalid status')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            vehicle = record['vehicle_id']
            service_date = record['service_date']
            cost = record['cost']
            item_status = record['status']
            parsed = date.fromisoformat(service_date)
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        if not isinstance(vehicle, str) or not vehicle or (not isinstance(service_date, str)) or (len(service_date) != 10) or (item_status not in {'scheduled', 'completed', 'cancelled'}) or isinstance(cost, bool) or (not isinstance(cost, (int, float))) or (cost < 0):
            raise ValueError('invalid record')
        if status is not None and item_status != status:
            continue
        group = groups.setdefault(vehicle, {'vehicle_id': vehicle, 'total_cost': 0.0, 'completed_count': 0, 'latest_service_date': service_date})
        group['total_cost'] += cost
        group['completed_count'] += item_status == 'completed'
        if parsed > date.fromisoformat(group['latest_service_date']):
            group['latest_service_date'] = service_date
    result = list(groups.values())
    result.sort(key=lambda x: (-x['total_cost'], x['vehicle_id']))
    for item in result:
        item['total_cost'] = round(item['total_cost'], 2)
    start = (page - 1) * page_size
    return result[start:start + page_size]

