from solution import process_booking_webhook


def make_body(value):
    return json.dumps(value, separators=(",", ":")).encode("utf-8")


def signed(value, key=b"cargo-key"):
    body = make_body(value)
    digest = hmac.new(key, body, hashlib.sha256).hexdigest()
    return body, digest, key


def test_single_piece_and_volume_chargeable_weight():
    value = {
        "booking_id": "BK-1",
        "pieces": [{
            "piece_id": "P1",
            "weight_kg": 10,
            "dimensions_cm": [60, 50, 40],
            "temperature_c": 20,
            "segment": "FRA-DOH"
        }]
    }
    body, digest, key = signed(value)
    assert process_booking_webhook(body, digest, key) == {
        "booking_id": "BK-1",
        "segments": [{"segment": "FRA-DOH", "pieces": 1, "chargeable_kg": 20.0}],
        "temperature_bands": {"frozen": 0, "chilled": 0, "ambient": 1},
        "total_chargeable_kg": 20.0
    }


def test_segments_are_sorted_and_bands_are_counted_at_boundaries():
    value = {
        "booking_id": "BK-2",
        "pieces": [
            {"piece_id": "a", "weight_kg": 5, "dimensions_cm": [10, 10, 10], "temperature_c": 2, "segment": "Z"},
            {"piece_id": "b", "weight_kg": 7, "dimensions_cm": [10, 10, 10], "temperature_c": -18, "segment": "A"},
            {"piece_id": "c", "weight_kg": 8, "dimensions_cm": [10, 10, 10], "temperature_c": -18.01, "segment": "Z"},
            {"piece_id": "d", "weight_kg": 9, "dimensions_cm": [10, 10, 10], "temperature_c": 1.99, "segment": "A"}
        ]
    }
    body, digest, key = signed(value)
    result = process_booking_webhook(body, digest, key)
    assert result["segments"] == [
        {"segment": "A", "pieces": 2, "chargeable_kg": 16.0},
        {"segment": "Z", "pieces": 2, "chargeable_kg": 13.0}
    ]
    assert result["temperature_bands"] == {"frozen": 1, "chilled": 2, "ambient": 1}
    assert result["total_chargeable_kg"] == 29.0


def test_fractional_sums_are_rounded_only_in_output():
    value = {
        "booking_id": "ROUND",
        "pieces": [
