import hmac
import json
import math

def process_booking_webhook(body: bytes, digest: str, key: bytes) -> dict:
    expected = hmac.new(key, body, hashlib.sha256).hexdigest()
    if not isinstance(digest, str) or not hmac.compare_digest(expected, digest):
        raise ValueError('invalid webhook')
    try:
        value = json.loads(body.decode('utf-8'))
        if not isinstance(value, dict) or not isinstance(value.get('booking_id'), str) or (not value['booking_id']):
            raise ValueError
        pieces = value.get('pieces')
        if not isinstance(pieces, list) or not pieces:
            raise ValueError
        seen = set()
        groups = {}
        bands = {'frozen': 0, 'chilled': 0, 'ambient': 0}
        total = 0.0
        for piece in pieces:
            if not isinstance(piece, dict):
                raise ValueError
            pid = piece.get('piece_id')
            weight = piece.get('weight_kg')
            dims = piece.get('dimensions_cm')
            temp = piece.get('temperature_c')
            segment = piece.get('segment')
            if not isinstance(pid, str) or not pid or pid in seen:
                raise ValueError
            if not isinstance(segment, str) or not segment:
                raise ValueError
            if isinstance(weight, bool) or not isinstance(weight, (int, float)) or (not math.isfinite(weight)) or (weight <= 0):
                raise ValueError
            if not isinstance(dims, list) or len(dims) != 3 or any((isinstance(x, bool) or not isinstance(x, (int, float)) or (not math.isfinite(x)) or (x <= 0) for x in dims)):
                raise ValueError
            if isinstance(temp, bool) or not isinstance(temp, (int, float)) or (not math.isfinite(temp)):
                raise ValueError
            seen.add(pid)
            charge = max(weight, dims[0] * dims[1] * dims[2] / 6000.0)
            total += charge
            if temp < -18:
                band = 'frozen'
            elif temp < 2:
                band = 'chilled'
            else:
                band = 'ambient'
            bands[band] += 1
            if segment not in groups:
                groups[segment] = [0, 0.0]
            groups[segment][0] += 1
            groups[segment][1] += charge
        segments = [{'segment': s, 'pieces': groups[s][0], 'chargeable_kg': round(groups[s][1], 2)} for s in sorted(groups)]
        return {'booking_id': value['booking_id'], 'segments': segments, 'temperature_bands': bands, 'total_chargeable_kg': round(total, 2)}
    except (ValueError, TypeError, KeyError, OverflowError, json.JSONDecodeError, UnicodeDecodeError):
        raise ValueError('invalid webhook')

