def analyze_wearable_file(path: str, device_id: str, window_seconds: int) -> list[dict]:
    if not device_id or not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or (window_seconds <= 0):
        raise ValueError('invalid arguments')
    result = subprocess.run(['sort', '-t,', '-k1,1n', '-k2,2', '-k3,3n', '-k4,4n', '-k5,5n', path], check=True, capture_output=True, text=True)
    rows = []
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = next(csv.reader([raw], skipinitialspace=False))
        if len(fields) != 5:
            raise ValueError('invalid row')
        try:
            timestamp = int(fields[0].strip())
            current_device = fields[1].strip()
            heart_rate = float(fields[2].strip())
            spo2 = float(fields[3].strip())
            steps = int(fields[4].strip())
        except (TypeError, ValueError):
            raise ValueError('invalid row')
        if timestamp < 0 or not current_device or steps < 0:
            raise ValueError('invalid row')
        if current_device == device_id:
            rows.append((timestamp, heart_rate, spo2, steps))
    if not rows:
        return []
    first = rows[0][0]
    grouped = {}
    for timestamp, heart_rate, spo2, steps in rows:
        number = (timestamp - first) // window_seconds
        grouped.setdefault(number, []).append((heart_rate, spo2, steps))
