from lxml import etree

def pickup_summary(xml_text: str, pickup_date: str, page: int, page_size: int) -> list[dict[str, object]]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode() if isinstance(xml_text, str) else xml_text, parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'pickups':
        raise ValueError('invalid root')
    groups = {}
    for node in root:
        if node.tag != 'order':
            continue
        required = ('date', 'window', 'status', 'total')
        if any((name not in node.attrib for name in required)):
            raise ValueError('missing attribute')
        if node.get('status') not in ('confirmed', 'ready') or node.get('date') != pickup_date:
            continue
        try:
            amount = Decimal(node.get('total'))
        except (InvalidOperation, TypeError):
            raise ValueError('invalid total')
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid total')
        window = node.get('window')
        if window not in groups:
            groups[window] = [0, Decimal('0')]
        groups[window][0] += 1
        groups[window][1] += amount
    result = []
    for window, (count, total) in groups.items():
        average = (total / count).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'window': window, 'orders': count, 'total': format(total.quantize(Decimal('0.01')), '.2f'), 'average': format(average, '.2f')})
    result.sort(key=lambda item: (-Decimal(item['total']), item['window']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

