import ast
import operator
_BIN = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
_CMP = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
_FUNCS = {'min': min, 'max': max, 'round': round}

def evaluate_rule(expression: str, variables: dict[str, object]) -> object:
    try:
        node = ast.parse(expression, mode='eval').body
    except (SyntaxError, TypeError):
        raise ValueError('invalid expression')

    def walk(n):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
            return n.value
        if isinstance(n, ast.Name):
            if n.id in ('True', 'False'):
                return n.id == 'True'
            if n.id not in variables:
                raise ValueError('unknown name')
            return variables[n.id]
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
            v = walk(n.operand)
