from decimal import Decimal, ROUND_HALF_UP

def _money(value):
    return float(Decimal(str(value)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

def _records(paths):
    for path in paths:
        with open(path, encoding='utf-8') as handle:
            lines = sorted(handle, key=lambda line: line.split(',', 1)[0] if ',' in line else line)
        for line in lines:
            if not line.strip():
                continue
            fields = line.rstrip('\n').split(',')
            if len(fields) != 4 or not fields[0]:
                raise ValueError('malformed record')
            try:
                gross = Decimal(fields[1])
                expenses = Decimal(fields[2])
                attendance = int(fields[3])
            except Exception as exc:
                raise ValueError('malformed record') from exc
            if gross < 0 or expenses < 0 or attendance < 0 or (str(attendance) != fields[3]):
                raise ValueError('malformed record')
            yield (fields[0], gross, expenses, attendance)

def build_settlement_report(paths: list[str], tax_rate: float, venue_fee: float, attendance_bonus_threshold: int) -> list[dict]:
    if not 0 <= tax_rate <= 1 or venue_fee < 0 or attendance_bonus_threshold < 0:
        raise ValueError('invalid parameters')
    grouped = {}
    for artist, gross, expenses, attendance in _records(paths):
        item = grouped.setdefault(artist, [0, Decimal(0), Decimal(0), 0])
        item[0] += 1
        item[1] += gross
        item[2] += expenses
        item[3] += attendance
    result = []
    for artist in sorted(grouped):
        shows, gross, expenses, attendance = grouped[artist]
        pre = gross - expenses - Decimal(str(venue_fee)) * shows
        payout = pre - (pre * Decimal(str(tax_rate)) if pre > 0 else Decimal(0))
        if attendance / shows >= attendance_bonus_threshold and pre > 0:
            payout += pre * Decimal('0.05')
        result.append({'artist': artist, 'shows': shows, 'gross': _money(gross), 'expenses': _money(expenses), 'attendance': attendance, 'payout': _money(payout)})
    return result

def settlement_totals(report: list[dict]) -> dict:
    return {'shows': sum((x['shows'] for x in report)), 'gross': _money(sum((Decimal((str(x['gross']) for x in report)), Decimal(0)))), 'expenses': _money(sum((Decimal((str(x['expenses']) for x in report)), Decimal(0)))), 'attendance': sum((x['attendance'] for x in report)), 'payout': _money(sum((Decimal((str(x['payout']) for x in report)), Decimal(0))))}

def format_settlement_report(report: list[dict]) -> str:
    return '\n'.join((f"{x['artist']}: shows={x['shows']} gross={x['gross']:.2f} expenses={x['expenses']:.2f} attendance={x['attendance']} payout={x['payout']:.2f}" for x in report))

