    if not isinstance(iccid_prefix, str) or not iccid_prefix.isdigit() or (not 1 <= len(iccid_prefix) <= 6):
        raise ValueError('invalid iccid prefix')
    if not isinstance(region, str) or not region.strip():
        raise ValueError('invalid region')
    if isinstance(budget_cents, bool) or not isinstance(budget_cents, int) or budget_cents < 0:
        raise ValueError('invalid budget')
    response = requests.get('https://api.simactivate.example/v1/activation/offers', params={'region': region.strip(), 'budget_cents': budget_cents}, headers={'Authorization': 'Bearer test-api-key'})
    if response.status_code != 200:
        raise RuntimeError('offer service error')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('offers'), list):
        raise ValueError('invalid response')
    result = []
    for offer in payload['offers']:
        if not isinstance(offer, dict):
            continue
        if offer.get('active') is not True:
            continue
        if isinstance(offer.get('stock'), bool) or not isinstance(offer.get('stock'), int) or offer['stock'] <= 0:
            continue
        if isinstance(offer.get('price_cents'), bool) or not isinstance(offer.get('price_cents'), int) or offer['price_cents'] > budget_cents:
            continue
        if not isinstance(offer.get('supported_prefixes'), list) or iccid_prefix not in offer['supported_prefixes']:
            continue
        if not all((isinstance(offer.get(key), str) for key in ('offer_id', 'name', 'currency'))):
            continue
        result.append({'offer_id': offer['offer_id'], 'name': offer['name'], 'price_cents': offer['price_cents'], 'currency': offer['currency']})
    result.sort(key=lambda item: (item['price_cents'], item['offer_id']))
    return result

