def expense_report(path: str, department: str | None=None, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if page < 1 or page_size < 1 or page_size > 1000:
        raise ValueError('invalid pagination')
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    result = subprocess.run(['sort', '-t,', '-k1,1', path], capture_output=True, text=True, check=True)
    groups = {}
    for line in result.stdout.splitlines():
