        if len(fields) != 4:
            raise ValueError('invalid record')
        employee, record_department, amount_text, date = fields
        if not employee or not record_department or (not date):
            raise ValueError('invalid record')
        try:
            amount = Decimal(amount_text).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except InvalidOperation as exc:
            raise ValueError('invalid amount') from exc
        if amount < 0:
            raise ValueError('invalid amount')
        if department is not None and record_department != department:
            continue
        if employee not in groups:
            groups[employee] = [Decimal('0.00'), 0]
        groups[employee][0] += amount
        groups[employee][1] += 1
    rows = [{'employee': name, 'total': str(values[0].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'count': values[1]} for name, values in groups.items()]
