        {"id": "u1", "tenant_id": "t1", "owner_id": "alice", "blood_type": "O+", "status": "available", "expires_on": "2025-05-01", "collected_at": "2025-01-02T09:00:00"},
        {"id": "u2", "tenant_id": "t1", "owner_id": "alice", "blood_type": "O+", "status": "available", "expires_on": "2025-05-01", "collected_at": "2025-01-01T09:00:00"},
        {"id": "other", "tenant_id": "t1", "owner_id": "bob", "blood_type": "O+", "status": "available", "expires_on": "2025-04-01", "collected_at": "2025-01-01T09:00:00"},
        {"id": "wrong-tenant", "tenant_id": "t2", "owner_id": "alice", "blood_type": "O+", "status": "available", "expires_on": "2025-04-01", "collected_at": "2025-01-01T09:00:00"},
        {"id": "used", "tenant_id": "t1", "owner_id": "alice", "blood_type": "O+", "status": "reserved", "expires_on": "2025-03-01", "collected_at": "2025-01-01T09:00:00"},
    ]


def test_owner_selection_sorting_and_mutation():
    units = make_units()
    units[3]["status"] = "reserved"
    result = reserve_blood_units({"user_id": "alice", "tenant_id": "t1", "roles": []}, units, "O+", 2, "2025-01-01")
    assert result == ["u2", "u1"]
    assert [u["status"] for u in units if u["id"] in result] == ["reserved", "reserved"]
    assert next(u for u in units if u["id"] == "u3")["status"] == "available"


def test_manager_can_select_any_owner_in_tenant():
    units = make_units()
    result = reserve_blood_units({"user_id": "manager", "tenant_id": "t1", "roles": ["inventory_manager"]}, units, "O+", 1, "2025-01-01")
    assert result == ["other"]
    assert units[3]["status"] == "reserved"


def test_expiration_boundary_and_blood_type_case():
    units = [{"id": "a", "tenant_id": "t1", "owner_id": "alice", "blood_type": "A-", "status": "available", "expires_on": "2025-05-10", "collected_at": "2025-01-01T00:00:00"}]
    assert reserve_blood_units({"user_id": "alice", "tenant_id": "t1", "roles": []}, units, "A-", 1, "2025-05-10") == ["a"]
    assert units[0]["status"] == "reserved"


