    units = make_units()
    before = [dict(x) for x in units]
    try:
        reserve_blood_units({"user_id": "alice", "tenant_id": "t1", "roles": []}, units, "O+", 4, "2025-05-01")
        assert False
    except ValueError:
        pass
    assert units == before


