from datetime import date, datetime

def reserve_blood_units(requester: dict, units: list[dict], blood_type: str, quantity: int, as_of: str) -> list[str]:
    if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
        raise ValueError('quantity must be positive')
    if not blood_type:
        raise ValueError('blood type required')
    try:
        date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    try:
        manager = 'inventory_manager' in requester['roles'] and requester['tenant_id']
        user_id = requester['user_id']
        tenant_id = requester['tenant_id']
    except (KeyError, TypeError):
        raise PermissionError('invalid requester')
    candidates = []
    for unit in units:
        if unit.get('tenant_id') != tenant_id or unit.get('blood_type') != blood_type:
            continue
        if unit.get('status') != 'available' or unit.get('expires_on', '') < as_of:
            continue
        if not manager and unit.get('owner_id') != user_id:
            continue
        try:
            datetime.fromisoformat(unit['collected_at'])
            date.fromisoformat(unit['expires_on'])
        except (KeyError, TypeError, ValueError):
            continue
        candidates.append(unit)
    candidates.sort(key=lambda u: (u['expires_on'], u['collected_at'], str(u['id'])))
    if len(candidates) < quantity:
        raise ValueError('not enough units')
    selected = candidates[:quantity]
    if not manager and any((u.get('owner_id') != user_id for u in selected)):
        raise PermissionError('not permitted')
    for unit in selected:
        unit['status'] = 'reserved'
    return [str(unit['id']) for unit in selected]

