import json
from typing import Any

def encode_snapshot(snapshot: dict) -> bytes:
    if not isinstance(snapshot, dict):
        raise ValueError('snapshot must be a dictionary')
    try:
        return json.dumps(snapshot, ensure_ascii=False, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid snapshot') from exc

def decode_snapshot(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('payload must be bytes')
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeError, ValueError, TypeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(value, dict):
        raise ValueError('snapshot must be a dictionary')
    return value

def aggregate_events(events: list[dict], window_ms: int=1000) -> list[dict]:
    if not isinstance(events, list) or isinstance(window_ms, bool) or (not isinstance(window_ms, int)) or (window_ms <= 0):
        raise ValueError('invalid event collection or window')
    groups: dict[tuple[int, str, str], dict] = {}
    for event in events:
        if not isinstance(event, dict) or set(event) != {'timestamp', 'axis', 'code', 'severity'}:
            raise ValueError('invalid event')
        timestamp = event['timestamp']
        axis = event['axis']
        code = event['code']
        severity = event['severity']
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError('invalid timestamp')
        if not isinstance(axis, str) or not isinstance(code, str):
            raise ValueError('invalid event label')
        if isinstance(severity, bool) or not isinstance(severity, int) or (not 0 <= severity <= 5):
            raise ValueError('invalid severity')
        start = timestamp // window_ms * window_ms
        key = (start, axis, code)
        if key not in groups:
            groups[key] = {'window_start': start, 'axis': axis, 'code': code, 'count': 0, 'max_severity': severity, 'first_timestamp': timestamp, 'last_timestamp': timestamp}
        group = groups[key]
        group['count'] += 1
        group['max_severity'] = max(group['max_severity'], severity)
        group['first_timestamp'] = min(group['first_timestamp'], timestamp)
        group['last_timestamp'] = max(group['last_timestamp'], timestamp)
    return [groups[key] for key in sorted(groups)]

