import tempfile

def export_document_register(records: list[dict[str, str]], destination: str) -> str:
    fields = ['document_id', 'title', 'revision', 'status']
    for record in records:
        if set(record) != set(fields) or any((not isinstance(record[field], str) for field in fields)):
            raise ValueError('invalid record')
    parent = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(dir=parent)
    os.close(descriptor)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(fields)
            for record in records:
                writer.writerow([record[field] for field in fields])
        os.replace(temporary, destination)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    return destination

