import hashlib
import hmac

def verify_schedule_request(request: str, secret: bytes) -> tuple[str, int]:
    parts = request.split('|')
    if len(parts) != 3:
        raise ValueError('invalid request')
    name, start_text, supplied = parts
    if not name:
        raise ValueError('invalid request')
    try:
        start = int(start_text)
    except ValueError:
        raise ValueError('invalid request')
    if start < 0:
        raise ValueError('invalid request')
    payload = f'{name}|{start_text}'.encode()
    expected = hashlib.sha256(secret + b':' + payload).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid request')
    return (name, start)

