        if not isinstance(tile, dict) or set(tile) != {'row', 'col', 'radiance', 'cloud_cover'}:
            raise ValueError('invalid tile')
        row, col = (tile['row'], tile['col'])
        rad, cloud = (tile['radiance'], tile['cloud_cover'])
        if isinstance(row, bool) or not isinstance(row, int) or row < 0:
            raise ValueError('invalid tile')
        if isinstance(col, bool) or not isinstance(col, int) or col < 0:
            raise ValueError('invalid tile')
        if isinstance(rad, bool) or not isinstance(rad, (int, float)) or (not math.isfinite(rad)):
            raise ValueError('invalid tile')
        if isinstance(cloud, bool) or not isinstance(cloud, (int, float)) or (not math.isfinite(cloud)) or (not 0 <= cloud <= 100):
            raise ValueError('invalid tile')
        if (row, col) in seen:
            raise ValueError('duplicate tile')
        seen.add((row, col))
    return scene

def summarize_scene(scene: dict) -> dict:
    scene = _validated(scene)
    groups = {}
    total_weight = total_value = 0.0
    for tile in scene['tiles']:
        weight = 1.0 - tile['cloud_cover'] / 100.0
        groups.setdefault(tile['row'], []).append(tile)
        total_weight += weight
        total_value += tile['radiance'] * weight
    rows = []
    for row in sorted(groups):
        items = sorted(groups[row], key=lambda x: x['col'])
        weights = [1.0 - x['cloud_cover'] / 100.0 for x in items]
        denom = sum(weights)
        rows.append({'row': row, 'columns': [x['col'] for x in items], 'mean_radiance': round(sum((x['radiance'] * w for x, w in zip(items, weights))) / denom, 3) if denom else None, 'clear_fraction': round(sum(weights) / len(weights), 3)})
    return {'scene_id': scene['scene_id'], 'captured_at': scene['captured_at'], 'tile_count': len(scene['tiles']), 'rows': rows, 'overall_radiance': round(total_value / total_weight, 3) if total_weight else None}

