    except ValueError:
        raise ValueError('invalid day')
    if len(day) != 10:
        raise ValueError('invalid day')

def _check_record(record):
    if not isinstance(record, dict):
        raise ValueError('invalid record')
    required = ('guest', 'date', 'slot', 'party', 'status')
    if any((key not in record for key in required)):
        raise ValueError('missing field')
    guest, rec_date, slot = (record['guest'], record['date'], record['slot'])
    party, status = (record['party'], record['status'])
    if not all((isinstance(x, str) for x in (guest, rec_date, slot, status))):
        raise ValueError('invalid text')
    try:
        date.fromisoformat(rec_date)
    except ValueError:
        raise ValueError('invalid date')
    if len(rec_date) != 10 or len(slot) != 5 or slot[2] != ':':
        raise ValueError('invalid time')
    try:
        datetime.strptime(slot, '%H:%M')
    except ValueError:
        raise ValueError('invalid time')
    if isinstance(party, bool) or not isinstance(party, int) or party <= 0:
        raise ValueError('invalid party')
    if status not in ('confirmed', 'cancelled'):
        raise ValueError('invalid status')

def prepare_entries(records: list[dict], day: str) -> list[dict]:
    _check_day(day)
    if not isinstance(records, list):
        raise ValueError('invalid records')
    selected = []
    for index, record in enumerate(records):
        _check_record(record)
        if record['date'] == day:
            item = {key: record[key] for key in ('guest', 'date', 'slot', 'party', 'status')}
            selected.append((item, index))
