    return f'<div class="entry-report"><h1>Timed entries for {escape(day, quote=True)}</h1><p class="summary">{len(entries)} bookings; {confirmed} confirmed guests</p><table><thead><tr><th>Time</th><th>Guest</th><th>Party</th><th>Status</th></tr></thead><tbody>{rows}</tbody></table></div>'

