        result.append({'date': day, 'measure': measure, 'kwh': int(value)})
    return result

def summarize_rebates(records: list[dict], budget_cents: int) -> dict:
    if not isinstance(budget_cents, int) or isinstance(budget_cents, bool) or budget_cents < 0:
        raise ValueError('invalid budget')
    totals = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'date', 'measure', 'kwh'}:
            raise ValueError('invalid record')
        measure, kwh = (record['measure'], record['kwh'])
        if measure not in RATES or not isinstance(kwh, int) or isinstance(kwh, bool) or (kwh < 0):
            raise ValueError('invalid record')
        totals[measure] = totals.get(measure, 0) + kwh
    pending = [{'measure': m, 'kwh': k, 'requested_cents': k * RATES[m], 'funded_cents': 0} for m, k in totals.items()]
    pending.sort(key=lambda x: (-x['requested_cents'], x['measure']))
    remaining = budget_cents
    for item in pending:
        item['funded_cents'] = min(item['requested_cents'], remaining)
        remaining -= item['funded_cents']
    requested = sum((x['requested_cents'] for x in pending))
    funded = sum((x['funded_cents'] for x in pending))
    return {'total_requested_cents': requested, 'total_funded_cents': funded, 'remaining_cents': remaining, 'awards': pending}

def generate_invite_code(length: int=12) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 32):
        raise ValueError('invalid length')
    return ''.join((random.choice(ALPHABET) for _ in range(length)))

def build_claim(customer_id: str, report: str, budget_cents: int) -> dict:
    if not isinstance(customer_id, str) or not customer_id.strip():
        raise ValueError('invalid customer')
    summary = summarize_rebates(parse_audit(report), budget_cents)
    return {'claim_id': generate_invite_code(), 'customer_id': customer_id, 'awards': summary['awards'], 'total_funded_cents': summary['total_funded_cents'], 'remaining_cents': summary['remaining_cents']}

