import datetime
import html
import math

def render_loan_report(loans: list[dict], as_of: str, page: int=1, per_page: int=10) -> str:
    try:
        reference = datetime.date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('invalid page size')
    active = []
    for loan in loans:
        if not isinstance(loan, dict) or not all((key in loan for key in ('title', 'borrower', 'due_date', 'status', 'value'))):
            raise ValueError('invalid loan')
        if not isinstance(loan['title'], str) or not isinstance(loan['borrower'], str):
            raise ValueError('invalid loan')
        try:
            due = datetime.date.fromisoformat(loan['due_date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if loan['status'] not in ('on_loan', 'returned'):
            raise ValueError('invalid status')
        value = loan['value']
        if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) or (value < 0):
            raise ValueError('invalid value')
        if loan['status'] == 'on_loan':
            active.append((loan, due, value))
    active.sort(key=lambda item: (item[1] >= reference, item[1], item[0]['title']))
    total_pages = max(1, (len(active) + per_page - 1) // per_page)
    if page > total_pages:
        raise ValueError('page out of range')
    overdue = sum((item[1] < reference for item in active))
    total = sum((item[2] for item in active))
    start = (page - 1) * per_page
    rows = []
    for loan, due, value in active[start:start + per_page]:
        css = 'overdue' if due < reference else 'current'
        rows.append(f'''<tr class="{css}"><td>{html.escape(loan['title'])}</td><td>{html.escape(loan['borrower'])}</td><td>{html.escape(loan['due_date'])}</td><td>${value:.2f}</td></tr>''')
    return '<section class="loan-report">\n<h1>Active Museum Loans</h1>\n' + f'<p class="summary">{len(active)} loans | {overdue} overdue | Total value: ${total:.2f}</p>\n' + '<table>\n<thead><tr><th>Title</th><th>Borrower</th><th>Due date</th><th>Value</th></tr></thead>\n<tbody>\n' + '\n'.join(rows) + f'\n</tbody>\n<p class="page">Page {page} of {total_pages}</p>\n</section>'

