import csv
import datetime
import os
import tempfile
from collections.abc import Iterable, Mapping
_FIELDS = ['email', 'purpose', 'status', 'timestamp', 'source']

def _timestamp(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        parsed = datetime.datetime.fromisoformat(value[:-1])
    except ValueError:
        raise ValueError('invalid timestamp')
    if parsed.tzinfo is not None:
        raise ValueError('invalid timestamp')
    return (parsed.strftime('%Y-%m-%dT%H:%M:%S.%fZ'), parsed)

def _one(record):
    if not isinstance(record, Mapping):
        raise ValueError('invalid record')
    for key in ('email', 'purpose', 'status', 'timestamp'):
        if key not in record or not isinstance(record[key], str):
            raise ValueError('invalid record')
    email = record['email'].strip()
    purpose = record['purpose'].strip()
    if not email or not purpose or record['status'] not in ('granted', 'revoked'):
        raise ValueError('invalid record')
    source = record.get('source', '')
    if not isinstance(source, str):
        raise ValueError('invalid record')
    stamp, parsed = _timestamp(record['timestamp'])
    return ({'email': email, 'purpose': purpose, 'status': record['status'], 'timestamp': stamp, 'source': source}, parsed)

def summarize_consents(records: Iterable[dict]) -> list[dict]:
    chosen = {}
    for index, record in enumerate(records):
        item, parsed = _one(record)
        key = (item['email'].casefold(), item['purpose'].casefold())
        old = chosen.get(key)
        if old is None or (parsed, index) >= (old[1], old[2]):
            chosen[key] = (item, parsed, index)
    result = [value[0] for value in chosen.values()]
    return sorted(result, key=lambda x: (x['email'].casefold(), x['purpose'].casefold(), x['timestamp'], x['status']))

def export_consents(records: Iterable[dict], destination: str) -> int:
    rows = summarize_consents(records)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.DictWriter(handle, fieldnames=_FIELDS, lineterminator='\n')
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

def read_consent_csv(path: str) -> list[dict]:
    with open(path, encoding='utf-8', newline='') as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames != _FIELDS:
            raise ValueError('invalid header')
        rows = []
        keys = set()
        for row in reader:
            if None in row or any((row[field] is None for field in _FIELDS)):
                raise ValueError('invalid row')
            item, _ = _one(row)
            key = (item['email'].casefold(), item['purpose'].casefold())
            if key in keys:
                raise ValueError('duplicate record')
            keys.add(key)
            rows.append(item)
    return sorted(rows, key=lambda x: (x['email'].casefold(), x['purpose'].casefold(), x['timestamp'], x['status']))

