def make_access_code_hash(code: str) -> str:
    if not isinstance(code, str):
        raise TypeError('code must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_access_code(code: str, stored_hash: str) -> bool:
    if not isinstance(code, str) or not isinstance(stored_hash, str):
        raise TypeError('arguments must be strings')
