import os
import zipfile
from datetime import date, timedelta

def parse_visit_log(text: str) -> list[tuple[str, str, str]]:
    result = []
    for number, raw in enumerate(text.splitlines(), 1):
        if not raw.strip():
            continue
        fields = [part.strip() for part in raw.split('|')]
        if len(fields) != 3 or any((not field for field in fields)):
            raise ValueError(f'invalid line {number}')
        try:
            date.fromisoformat(fields[0])
        except ValueError:
            raise ValueError(f'invalid line {number}')
        result.append(tuple(fields))
    return result

def aggregate_visits(records: list[tuple[str, str, str]], window_days: int=3) -> dict[str, dict[str, int]]:
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days <= 0:
        raise ValueError('window_days must be positive')
    grouped = {}
    for day, visitor, page in records:
        grouped.setdefault(visitor, []).append((date.fromisoformat(day), page))
    result = {}
    for visitor in sorted(grouped):
        items = grouped[visitor]
        days = {day for day, _ in items}
        best = 0
        for start in days:
            end = start + timedelta(days=window_days - 1)
            best = max(best, sum((start <= day <= end for day, _ in items)))
        result[visitor] = {'visits': len(items), 'unique_pages': len({page for _, page in items}), 'active_days': len(days), 'max_window_visits': best}
    return result

def analyze_archive(archive_path: str, output_dir: str, member_names: list[str], window_days: int=3) -> dict[str, dict[str, int]]:
    os.makedirs(output_dir, exist_ok=True)
    records = []
    with zipfile.ZipFile(archive_path) as archive:
        for name in member_names:
            if not name.endswith('.log'):
                raise ValueError('member must be a log')
            data = archive.read(name)
            root = os.path.realpath(output_dir)
            target = os.path.realpath(os.path.join(root, name))
            if target != root and (not target.startswith(root + os.sep)):
                raise ValueError('member outside output directory')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with open(target, 'wb') as stream:
                stream.write(data)
            records.extend(parse_visit_log(data.decode('utf-8')))
    return aggregate_visits(records, window_days)

