import math

def _coord(value):
    if not isinstance(value, dict) or not isinstance(value.get('lat'), (int, float)) or (not isinstance(value.get('lon'), (int, float))):
        raise ValueError('invalid coordinate')
    return (value['lat'], value['lon'])

def dispatch_orders(requester: dict, orders: list[dict], couriers: list[dict], now: int) -> list[dict]:
    if not isinstance(requester, dict) or requester.get('role') not in {'dispatcher', 'admin'}:
        raise PermissionError('dispatch not permitted')
    tenant = requester.get('tenant')
    if not tenant:
        raise PermissionError('dispatch not permitted')
    required_order = ('id', 'tenant', 'restaurant_owner', 'pickup', 'dropoff', 'ready_at', 'status', 'priority', 'created_at')
    required_courier = ('id', 'tenant', 'available', 'capacity', 'speed', 'location')
    work = []
    for o in orders:
        if any((k not in o for k in required_order)):
            raise ValueError('invalid order')
        p, d = (_coord(o['pickup']), _coord(o['dropoff']))
        if o['tenant'] == tenant and o['status'] == 'ready' and (o['ready_at'] <= now):
            work.append((o, p, d))
    work.sort(key=lambda x: (-x[0]['priority'], x[0]['ready_at'], x[0]['created_at'], str(x[0]['id'])))
    state = {}
    for c in couriers:
        if any((k not in c for k in required_courier)) or c['capacity'] < 0 or c['speed'] <= 0:
            raise ValueError('invalid courier')
        state[c['id']] = [c, _coord(c['location']), 0]
    result = []
    for o, p, d in work:
        choices = []
        for cid, (c, loc, count) in state.items():
            if c['tenant'] == tenant and c['available'] and (count < c['capacity']):
                distance = abs(loc[0] - p[0]) + abs(loc[1] - p[1]) + abs(p[0] - d[0]) + abs(p[1] - d[1])
                choices.append((distance, count, str(cid), cid))
        if not choices:
            continue
        distance, _, _, cid = min(choices)
        c, _, count = state[cid]
        state[cid][1] = d
        state[cid][2] = count + 1
        result.append({'order_id': o['id'], 'courier_id': cid, 'distance': float(distance), 'eta': math.ceil(distance / c['speed'])})
    return result

def summarize_dispatch(assignments):
    out = {}
    for a in assignments:
        if not all((k in a for k in ('order_id', 'courier_id', 'distance', 'eta'))):
            raise ValueError('invalid assignment')
        cid = a['courier_id']
        if cid not in out:
            out[cid] = {'orders': 0, 'distance': 0.0, 'eta': 0}
        out[cid]['orders'] += 1
        out[cid]['distance'] += float(a['distance'])
        out[cid]['eta'] += int(a['eta'])
    return out

