import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin:
        raise ValueError('pin must be a non-empty string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + value.hex()

def verify_pin(pin: str, stored_hash: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored_hash, str):
        return False
    try:
        salt_text, digest_text = stored_hash.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def segment_contacts(records: list[dict], page: int, page_size: int, pin: str, stored_hash: str) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    if not verify_pin(pin, stored_hash):
        raise PermissionError('invalid PIN')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('email'), str) or (not isinstance(record.get('segment'), str)) or (not isinstance(record.get('opens'), int)) or isinstance(record.get('opens'), bool) or (record['opens'] < 0):
            raise ValueError('invalid record')
        name = record['segment']
        groups.setdefault(name, []).append(record['opens'])
    result = []
    for name, opens in groups.items():
        result.append({'name': name, 'contacts': len(opens), 'average_opens': round(sum(opens) / len(opens), 2)})
    result.sort(key=lambda item: (-item['contacts'], item['name']))
    start = (page - 1) * page_size
    return {'total_segments': len(result), 'segments': result[start:start + page_size]}

