import os
import tempfile
from pathlib import Path

def export_responses(records: list[dict[str, object]], destination: str) -> int:
    rows = []
    for record in records:
        residents = record['residents']
        if not isinstance(residents, int) or isinstance(residents, bool) or residents < 0:
            raise ValueError('residents must be a nonnegative integer')
        rows.append((str(record['household_id']), residents, str(record['response'])))
    rows.sort(key=lambda row: row[0])
    parent = str(Path(destination).parent)
    descriptor, temporary = tempfile.mkstemp(prefix='.census-', dir=parent, text=True)
    try:
        with os.fdopen(descriptor, 'w', newline='', encoding='utf-8') as file:
            writer = csv.writer(file)
            writer.writerow(['household_id', 'residents', 'response'])
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.close(descriptor)
        except OSError:
            pass
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

import sqlite3
import math
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP

def create_schema(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS entries (id INTEGER PRIMARY KEY AUTOINCREMENT, matter_id INTEGER NOT NULL, lawyer TEXT NOT NULL, started TEXT NOT NULL, ended TEXT NOT NULL, billed_minutes INTEGER NOT NULL, hourly_rate REAL NOT NULL, note TEXT NOT NULL)')
    conn.commit()

def _when(value):
    try:
        return datetime.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')

def add_time_entry(conn, matter_id, lawyer, started, ended, hourly_rate, note=''):
    if not isinstance(matter_id, int) or isinstance(matter_id, bool) or matter_id <= 0:
        raise ValueError('invalid matter')
    if not isinstance(lawyer, str) or not lawyer.strip() or (not isinstance(note, str)):
        raise ValueError('invalid text')
    if not isinstance(hourly_rate, (int, float)) or isinstance(hourly_rate, bool) or (not math.isfinite(hourly_rate)) or (hourly_rate < 0):
        raise ValueError('invalid rate')
    a, b = (_when(started), _when(ended))
    seconds = (b - a).total_seconds()
    if seconds <= 0:
        raise ValueError('invalid interval')
    minutes = max(6, math.ceil(seconds / 60 / 6) * 6)
    cur = conn.execute('INSERT INTO entries (matter_id, lawyer, started, ended, billed_minutes, hourly_rate, note) VALUES (?, ?, ?, ?, ?, ?, ?)', (matter_id, lawyer, started, ended, minutes, hourly_rate, note))
    conn.commit()
    return cur.lastrowid

def list_entries(conn, matter_id=None, lawyer=None, since=None, until=None, sort_by='started'):
    allowed = {'started', 'ended', 'lawyer', 'matter_id', 'id'}
    if sort_by not in allowed:
        raise ValueError('invalid sort')
    if matter_id is not None and (not isinstance(matter_id, int) or isinstance(matter_id, bool) or matter_id <= 0):
        raise ValueError('invalid matter')
    if lawyer is not None and (not isinstance(lawyer, str)):
        raise ValueError('invalid lawyer')
    if since is not None:
        _when(since)
    if until is not None:
        _when(until)
    clauses, values = ([], [])
    if matter_id is not None:
        clauses.append('matter_id = ?')
        values.append(matter_id)
    if lawyer is not None:
        clauses.append('lawyer = ?')
        values.append(lawyer)
    if since is not None:
        clauses.append('started >= ?')
        values.append(since)
    if until is not None:
        clauses.append('started < ?')
        values.append(until)
    sql = 'SELECT id, matter_id, lawyer, started, ended, billed_minutes, hourly_rate, note FROM entries'
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    sql += ' ORDER BY ' + sort_by + ', id'
    rows = conn.execute(sql, values).fetchall()
    keys = ['id', 'matter_id', 'lawyer', 'started', 'ended', 'billed_minutes', 'hourly_rate', 'note']
    return [dict(zip(keys, row)) for row in rows]

def _money(value):
    return float(Decimal(str(value)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

def invoice_summary(conn, matter_id, tax_rate=0.0):
    if not isinstance(matter_id, int) or isinstance(matter_id, bool) or matter_id <= 0:
        raise ValueError('invalid matter')
    if not isinstance(tax_rate, (int, float)) or isinstance(tax_rate, bool) or (not math.isfinite(tax_rate)) or (tax_rate < 0):
        raise ValueError('invalid tax')
    entries = list_entries(conn, matter_id=matter_id)
    groups = {}
    subtotal_raw = 0
    for row in entries:
        amount = row['billed_minutes'] * row['hourly_rate'] / 60
        subtotal_raw += amount
        if row['lawyer'] not in groups:
            groups[row['lawyer']] = {'minutes': 0, 'amount': 0}
        groups[row['lawyer']]['minutes'] += row['billed_minutes']
        groups[row['lawyer']]['amount'] += amount
    for group in groups.values():
        group['amount'] = _money(group['amount'])
    subtotal = _money(subtotal_raw)
    tax = _money(subtotal * tax_rate)
    return {'matter_id': matter_id, 'entries': entries, 'by_lawyer': groups, 'subtotal': subtotal, 'tax': tax, 'total': _money(subtotal + tax)}

