import csv
import datetime
import math
import subprocess

def _records(path, animal):
    if animal is None:
        command = ['cat', path]
    else:
        command = ['grep', '-F', '--', animal, path]
    try:
        result = subprocess.run(command, check=False, capture_output=True, text=True)
    except FileNotFoundError:
        raise
    if result.returncode not in (0, 1):
        if result.returncode == 2:
            raise FileNotFoundError(path)
        raise ValueError('unable to read log')
    for line in result.stdout.splitlines():
        if not line.strip() or line.lstrip().startswith('#'):
            continue
        fields = next(csv.reader([line], skipinitialspace=True))
        if len(fields) != 5:
            raise ValueError('invalid record')
        stamp, ident, liters, fat, temp = [x.strip() for x in fields]
        try:
            when = datetime.datetime.strptime(stamp, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=datetime.timezone.utc)
            values = [float(liters), float(fat), float(temp)]
        except (ValueError, OverflowError):
            raise ValueError('invalid record')
        if not all((math.isfinite(x) for x in values)) or values[0] < 0:
            raise ValueError('invalid record')
        if animal is None or ident == animal:
            yield (when, ident, values)

def analyze_milk_log(path: str, animal: str | None=None, window_minutes: int=30) -> list[dict]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('invalid window')
    groups = {}
    size = window_minutes * 60
    epoch = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    for when, ident, values in _records(path, animal):
        seconds = int((when - epoch).total_seconds())
        start = epoch + datetime.timedelta(seconds=seconds // size * size)
        key = (ident, start)
        item = groups.setdefault(key, [0, 0.0, 0.0, 0.0])
        item[0] += 1
        item[1] += values[0]
        item[2] += values[1]
        item[3] += values[2]
    output = []
    for (ident, start), item in sorted(groups.items(), key=lambda x: (x[0][0], x[0][1])):
        output.append({'animal': ident, 'window_start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'records': item[0], 'liters': round(item[1], 6), 'avg_fat_percent': round(item[2] / item[0], 6), 'avg_temperature_c': round(item[3] / item[0], 6)})
    return output

def rank_milk_windows(rows: list[dict]) -> list[dict]:
    ordered = sorted(rows, key=lambda x: (-x['liters'], -x['avg_fat_percent'], x['animal'], x['window_start']))
    return [dict(row, rank=index) for index, row in enumerate(ordered, 1)]

