def issue_intake_invite(applicant_name: str, existing_codes: list[str], length: int=12) -> dict:
    if not isinstance(applicant_name, str):
        raise TypeError('applicant_name must be a string')
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 32):
        raise ValueError('length must be between 8 and 32')
    cleaned = ' '.join(applicant_name.strip().split())
    words = cleaned.replace('-', ' ').split()
    if not words or any((not word.isalpha() for word in words)):
        raise ValueError('invalid applicant name')
    if not all((isinstance(code, str) for code in existing_codes)):
        raise TypeError('existing codes must be strings')
    if len(words) == 1:
        prefix = words[0][:2].upper()
    else:
        prefix = (words[0][0] + words[1][0]).upper()
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    occupied = set(existing_codes)
    while True:
        body = ''.join((secrets.choice(alphabet) for _ in range(length)))
        code = prefix + '-' + body
        if code not in occupied:
            return {'applicant': cleaned, 'code': code, 'prefix': prefix, 'length': length}

