                raise ValueError('malformed item')
            if type(quantity) is not int:
                raise ValueError('malformed item')
            result[sku] = result.get(sku, 0) + quantity
        return result
    except (KeyError, TypeError, ValueError):
        raise ValueError('malformed inventory')

