    match = re.fullmatch('([A-Z0-9-]+)\\|([+-]?\\d+)\\|(\\d+)', scan)
    if not match:
        raise ValueError('invalid scan')
    return (match.group(1), int(match.group(2)), int(match.group(3)))

def build_inventory_report(initial: dict[str, int], scans: list[str], window: int=60) -> list[dict]:
    if type(window) is not int or window <= 0:
        raise ValueError('invalid window')
    inventory = {}
    for sku, quantity in initial.items():
        if not isinstance(sku, str) or not re.fullmatch('[A-Z0-9-]+', sku):
