    groups = {}
    for timestamp, _, sku, delta in parsed:
        if sku not in inventory:
            inventory[sku] = 0
        inventory[sku] += delta
        if inventory[sku] < 0:
            raise ValueError('negative inventory')
        start = timestamp // window * window
        if start not in groups:
            groups[start] = {}
        groups[start][sku] = groups[start].get(sku, 0) + delta
    result = []
    current = {sku: initial[sku] for sku in initial}
    for start in sorted(groups):
        for sku, delta in groups[start].items():
            current[sku] = current.get(sku, 0) + delta
        changes = {sku: groups[start][sku] for sku in sorted(groups[start])}
        totals = {sku: current[sku] for sku in sorted(current)}
        result.append({'window': start, 'changes': changes, 'totals': totals})
    return result

