    except ValueError:
        raise ValueError('invalid date')

def _credential(password):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def prepare_client_portal(client_id: str, password: str, invoices: list[dict], as_of: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(client_id, str) or not client_id or (not isinstance(password, str)) or (not password):
        raise ValueError('invalid client data')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    _check_date(as_of)
    records = []
    ids = set()
    for item in invoices:
        if not isinstance(item, dict) or set(item) != {'invoice_id', 'amount', 'due_date', 'paid'}:
            raise ValueError('invalid invoice')
        if not isinstance(item['invoice_id'], str) or not item['invoice_id'] or item['invoice_id'] in ids:
