import operator

def select_alerts(readings: list[dict], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid rule') from exc

    def visit(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.Name) and node.id in values:
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            a, b = (visit(node.left, values), visit(node.right, values))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
            value = visit(node.operand, values)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
            result = visit(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = visit(child, values)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left, values)
            for op, child in zip(node.ops, node.comparators):
                right = visit(child, values)
                if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(x, values) for x in node.args))
        raise ValueError('invalid rule')
    result = []
    for reading in readings:
        try:
            if visit(tree, reading):
                result.append(reading)
        except Exception as exc:
            raise ValueError('invalid rule') from exc
    result.sort(key=lambda item: (-item['magnitude'], item['id']))
    return [item['id'] for item in result]

