    import csv
    from io import StringIO
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        try:
            fields = next(csv.reader(StringIO(line)))
            if len(fields) != 5:
                raise ValueError('five fields required')
            station = fields[0].strip()
            if not station:
                raise ValueError('empty station')
            stamp = fields[1].strip().replace('Z', '+00:00')
            timestamp = datetime.fromisoformat(stamp)
            if timestamp.tzinfo is None or timestamp.utcoffset() is None:
                raise ValueError('timezone required')
            values = [int(x.strip()) for x in fields[2:]]
            if any((x < 0 for x in values)):
                raise ValueError('negative measurement')
        except (ValueError, TypeError, StopIteration) as exc:
            raise ValueError(f'line {number}: invalid weather row') from exc
        result.append({'station': station, 'timestamp': timestamp.astimezone(timezone.utc), 'wind_knots': values[0], 'visibility_m': values[1], 'ceiling_ft': values[2]})
    return result

def build_weather_notice(facility: str, issued_at: datetime, report_text: str) -> dict:
    if issued_at.tzinfo is None or issued_at.utcoffset() is None:
        raise ValueError('issued_at must be timezone-aware')
    issued = issued_at.astimezone(timezone.utc)
    rows = parse_weather_report(report_text)
    selected = [r for r in rows if issued - timedelta(hours=2) <= r['timestamp'] <= issued]
    scored = []
    for row in selected:
        score = (2 if row['wind_knots'] >= 35 else 0) + (2 if row['visibility_m'] < 5000 else 0) + (2 if row['ceiling_ft'] < 1000 else 0)
        scored.append((score, row))
    scored.sort(key=lambda item: (-item[0], item[1]['station']))
    highest = max((x[0] for x in scored), default=0)
    severity = 'SEVERE' if highest >= 4 else 'ADVISORY' if highest >= 2 else 'ROUTINE'
    summary = ';'.join((f"{r['station']}:{r['wind_knots']}/{r['visibility_m']}/{r['ceiling_ft']}" for _, r in scored))
    fmt = lambda value: value.strftime('%Y-%m-%dT%H:%M:%SZ')
    return {'id': generate_notice_id(facility, issued), 'facility': facility.upper(), 'issued_at': fmt(issued), 'valid_until': fmt(issued + timedelta(hours=2)), 'severity': severity, 'summary': summary}

