from lxml import etree
from datetime import datetime

def parse_tickets(document: str) -> list[dict]:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(document.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'dispatch':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'ticket':
            raise ValueError('invalid ticket element')

        def text_attr(name):
            value = node.get(name)
            if value is None or not value.strip():
                raise ValueError('missing attribute')
            return value.strip()
        ident = text_attr('id')
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        try:
            priority = int(text_attr('priority'))
            if priority not in range(1, 6):
                raise ValueError
            opened = text_attr('opened')
            datetime.strptime(opened, '%Y-%m-%dT%H:%M:%S')
            queue = text_attr('queue')
        except Exception as exc:
            raise ValueError('invalid ticket') from exc
        subject = None
        tags = []
        events = []
        for child in node:
            if child.tag == 'subject' and subject is None:
                subject = ''.join(child.itertext()).strip()
                if not subject:
                    raise ValueError('empty subject')
            elif child.tag == 'tags' and (not tags):
                for tag in child:
                    if tag.tag != 'tag':
                        raise ValueError('invalid tag')
                    value = ''.join(tag.itertext()).strip()
                    if value:
                        tags.append(value)
            elif child.tag == 'events' and (not events):
                for event in child:
                    if event.tag != 'event':
                        raise ValueError('invalid event')
                    at = event.get('at')
                    status = event.get('status')
                    if not at or not at.strip() or (not status) or (not status.strip()):
                        raise ValueError('invalid event')
                    at = at.strip()
                    try:
                        datetime.strptime(at, '%Y-%m-%dT%H:%M:%S')
                    except ValueError as exc:
                        raise ValueError('invalid event time') from exc
                    events.append({'at': at, 'status': status.strip()})
            else:
                raise ValueError('invalid child')
        if subject is None:
            raise ValueError('missing subject')
        result.append({'id': ident, 'priority': priority, 'opened': opened, 'queue': queue, 'subject': subject, 'tags': tags, 'events': events, 'status': events[-1]['status'] if events else 'new'})
    return result

def route_tickets(tickets: list[dict], agents: list[dict]) -> dict[str, list[str]]:
    names = set()
    output = {}
    for agent in agents:
        if not isinstance(agent, dict) or not isinstance(agent.get('name'), str) or (not agent['name'].strip()) or (agent['name'] in names) or (not isinstance(agent.get('queues'), list)) or (not isinstance(agent.get('capacity'), int)) or isinstance(agent['capacity'], bool) or (agent['capacity'] < 0):
            raise ValueError('invalid agent')
        names.add(agent['name'])
        output[agent['name']] = []
    ids = set()
    for ticket in tickets:
        if not isinstance(ticket, dict) or ticket.get('id') in ids:
            raise ValueError('invalid ticket')
        ids.add(ticket.get('id'))
    ordered = sorted(tickets, key=lambda t: (-t['priority'], t['opened'], t['id']))
    for ticket in ordered:
        choices = [(len(output[a['name']]), i, a) for i, a in enumerate(agents) if ticket['queue'] in a['queues'] and len(output[a['name']]) < a['capacity']]
        if choices:
            _, _, agent = min(choices)
            output[agent['name']].append(ticket['id'])
    return output

