import hashlib
import hmac
import os
from datetime import date, timedelta
from typing import Any

def _day(value: str) -> date:
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def create_employee(employee_id: str, name: str, password: str, certifications: list[dict[str, Any]]) -> dict[str, Any]:
    if not isinstance(employee_id, str) or not employee_id.strip() or (not isinstance(name, str)) or (not name.strip()):
        raise ValueError('invalid employee')
    if not isinstance(password, str) or len(password) < 8:
        raise ValueError('invalid password')
    if not isinstance(certifications, list):
        raise ValueError('invalid certifications')
    normalized = []
    seen = set()
    for item in certifications:
        if not isinstance(item, dict) or set(item) != {'name', 'completed', 'valid_days'}:
            raise ValueError('invalid certification')
        cert_name = item['name']
        if not isinstance(cert_name, str) or not cert_name.strip() or cert_name.strip() in seen:
            raise ValueError('invalid certification')
        _day(item['completed'])
        if isinstance(item['valid_days'], bool) or not isinstance(item['valid_days'], int) or item['valid_days'] <= 0:
            raise ValueError('invalid certification')
        cert_name = cert_name.strip()
        seen.add(cert_name)
        normalized.append({'name': cert_name, 'completed': item['completed'], 'valid_days': item['valid_days']})
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'employee_id': employee_id.strip(), 'name': name.strip(), 'credential': salt.hex() + ':' + digest.hex(), 'certifications': normalized}

def authenticate(employee: dict[str, Any], password: str) -> bool:
    try:
        if not isinstance(employee, dict) or not isinstance(password, str):
            return False
        salt_hex, digest_hex = employee['credential'].split(':')
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt_hex), 100000)
        return hmac.compare_digest(actual, bytes.fromhex(digest_hex))
    except (KeyError, TypeError, ValueError, AttributeError):
        return False

def due_reminders(employees: list[dict[str, Any]], on_date: str) -> list[dict[str, Any]]:
    start = _day(on_date)
    output = []
    for employee in employees:
        if not isinstance(employee, dict) or not isinstance(employee.get('employee_id'), str) or (not isinstance(employee.get('name'), str)) or (not isinstance(employee.get('certifications'), list)):
            raise ValueError('invalid employee')
        for cert in employee['certifications']:
