import zipfile
from pathlib import Path

def extract_fasta_archive(archive_path: str, output_dir: str) -> dict[str, int]:
    base = Path(output_dir).resolve()
    result = {}
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            target = (base / info.filename).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('archive member is outside output directory')
            if not info.filename.endswith('.fa'):
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            data = archive.read(info)
            target.write_bytes(data)
            text = data.decode('utf-8')
            length = sum((len(''.join(line.split())) for line in text.splitlines() if line.strip() and (not line.startswith('>'))))
            result[info.filename] = length
    return result

import sqlite3

def get_training_compliance(conn: sqlite3.Connection, department: str | None=None, min_score: float | None=None, sort_by: str='employee', descending: bool=False, limit: int | None=None) -> list[dict]:
    if min_score is not None and (isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not 0 <= min_score <= 100)):
        raise ValueError('min_score must be between 0 and 100')
    if sort_by not in {'employee', 'department', 'average_score', 'completed_courses'}:
        raise ValueError('invalid sort field')
    if limit is not None and (isinstance(limit, bool) or not isinstance(limit, int) or limit < 0):
        raise ValueError('invalid limit')
    columns = {'employee': 'e.name', 'department': 'e.department', 'average_score': 'average_score', 'completed_courses': 'completed_courses'}
    direction = 'DESC' if descending else 'ASC'
    sql = '\n        SELECT e.name, e.department,\n               COUNT(CASE WHEN t.completed = 1 THEN 1 END) AS completed_courses,\n               COALESCE(AVG(CASE WHEN t.completed = 1 THEN t.score END), 0.0) AS average_score\n        FROM employees e\n        LEFT JOIN training t ON t.employee_id = e.id\n    '
    params = []
    clauses = []
    if department is not None:
        clauses.append('e.department = ?')
        params.append(department)
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    sql += ' GROUP BY e.id, e.name, e.department'
    if min_score is not None:
        sql += ' HAVING COALESCE(AVG(CASE WHEN t.completed = 1 THEN t.score END), 0.0) >= ?'
        params.append(min_score)
    sql += f' ORDER BY {columns[sort_by]} {direction}, e.name ASC'
