import hmac
import json
from collections import defaultdict
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_webhook(payload: bytes, signature: str, page: int=1, page_size: int=10, secret: str='bookkeeping-key') -> dict:
    if not isinstance(signature, str):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict) or not isinstance(data.get('invoices'), list):
        raise ValueError('invalid invoices')
    groups = defaultdict(lambda: [0, 0])
    for invoice in data['invoices']:
        if not isinstance(invoice, dict):
            raise ValueError('invalid invoice')
        if not all((isinstance(invoice.get(k), str) and invoice[k] for k in ('id', 'vendor', 'status'))):
            raise ValueError('invalid invoice')
        if invoice['status'] != 'approved':
            continue
        if 'amount' not in invoice or isinstance(invoice['amount'], bool):
            raise ValueError('invalid amount')
        try:
            amount = Decimal(str(invoice['amount']))
            if not amount.is_finite() or amount < 0:
                raise ValueError('invalid amount')
            cents = int((amount * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        groups[invoice['vendor']][0] += 1
        groups[invoice['vendor']][1] += cents
    vendors = [{'vendor': vendor, 'invoice_count': values[0], 'total_cents': values[1]} for vendor, values in sorted(groups.items())]
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_vendors': len(vendors), 'vendors': vendors[start:start + page_size]}

