        return datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def summarize_renewals(records: list[dict], as_of: str) -> list[dict]:
    cutoff = _date(as_of)
    chosen = {}
    priority = {'pending': 2, 'approved': 1, 'withdrawn': 0}
    for record in records:
        try:
            pid = record['permit_id']
            facility = record['facility']
            county = record['county']
            submitted_text = record['submitted']
            status = record['status']
            fees = record['fees']
        except (KeyError, TypeError):
            raise ValueError('missing field')
        if not isinstance(pid, str) or not pid or (not isinstance(facility, str)) or (not isinstance(county, str)):
            raise ValueError('invalid text')
        if status not in priority or not isinstance(fees, list):
            raise ValueError('invalid record')
        if any((isinstance(f, bool) or not isinstance(f, int) or f < 0 for f in fees)):
            raise ValueError('invalid fee')
        submitted = _date(submitted_text)
        if submitted > cutoff:
            continue
        old = chosen.get(pid)
        key = (submitted, priority[status])
        if old is None or key >= old[0]:
            chosen[pid] = (key, record, submitted)
    result = []
    for _, record, submitted in chosen.values():
        result.append({'permit_id': record['permit_id'], 'facility': record['facility'], 'county': record['county'], 'submitted': record['submitted'], 'status': record['status'], 'total_fee': sum(record['fees']), 'age_days': (cutoff - submitted).days})
    result.sort(key=lambda x: (x['county'].casefold(), x['facility'].casefold(), x['permit_id']))
    return result

