import hashlib
import hmac
import os

def create_segment(name: str, access_code: str) -> dict:
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(access_code, str) or not access_code:
        raise ValueError('invalid access code')
    normalized = name.strip().lower()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_code.encode('utf-8'), salt, 100000)
    stored = salt.hex() + '$' + digest.hex()
    return {'name': normalized, 'access_code': stored}

def verify_segment(record: dict, access_code: str) -> bool:
    if not isinstance(record, dict) or not isinstance(access_code, str):
        return False
    stored = record.get('access_code')
    if not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', access_code.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

