import pytest


def test_round_trip_and_aggregation():
    events = [
        {"message_id": "a", "status": "delivered", "timestamp": 100, "bytes_sent": 120},
        {"message_id": "b", "status": "bounced", "timestamp": 90, "bytes_sent": 80},
        {"message_id": "c", "status": "pending", "timestamp": 110, "bytes_sent": 40},
        {"message_id": "d", "status": "delivered", "timestamp": 95, "bytes_sent": 60},
    ]
    result = delivery_report(encode_events(events))
    assert result == {
        "total": 4,
        "counts": {"delivered": 2, "bounced": 1, "pending": 1},
        "total_bytes": 300,
        "events": [
            {"message_id": "c", "status": "pending", "timestamp": 110, "bytes_sent": 40},
            {"message_id": "a", "status": "delivered", "timestamp": 100, "bytes_sent": 120},
            {"message_id": "d", "status": "delivered", "timestamp": 95, "bytes_sent": 60},
            {"message_id": "b", "status": "bounced", "timestamp": 90, "bytes_sent": 80},
        ],
    }


def test_empty_input():
    assert delivery_report(encode_events([])) == {
        "total": 0,
        "counts": {"delivered": 0, "bounced": 0, "pending": 0},
        "total_bytes": 0,
        "events": [],
    }


def test_tie_order_and_extra_fields():
    events = [
        {"message_id": "z", "status": "pending", "timestamp": 5, "bytes_sent": 1, "note": "x"},
        {"message_id": "a", "status": "bounced", "timestamp": 5, "bytes_sent": 2},
    ]
    assert delivery_report(encode_events(events))["events"] == [
        {"message_id": "a", "status": "bounced", "timestamp": 5, "bytes_sent": 2},
        {"message_id": "z", "status": "pending", "timestamp": 5, "bytes_sent": 1},
    ]


def test_pagination_boundaries():
    events = [
        {"message_id": str(i), "status": "delivered", "timestamp": i, "bytes_sent": i}
        for i in range(1, 6)
    ]
    assert [e["message_id"] for e in delivery_report(encode_events(events), 1, 2)["events"]] == ["5", "4"]
    assert [e["message_id"] for e in delivery_report(encode_events(events), 3, 2)["events"]] == ["1"]
    assert delivery_report(encode_events(events), 4, 2)["events"] == []


def test_invalid_pagination():
    blob = encode_events([])
    for page, size in [(0, 1), (1, 0), (-1, 2), (True, 2), (1, False), (1.5, 2)]:
        with pytest.raises(ValueError):
            delivery_report(blob, page, size)


def test_invalid_encoded_data():
    with pytest.raises(ValueError):
        delivery_report(b"not a valid payload")


def test_invalid_events():
    bad_values = [
        {"message_id": "", "status": "delivered", "timestamp": 1, "bytes_sent": 1},
        {"message_id": "a", "status": "unknown", "timestamp": 1, "bytes_sent": 1},
        {"message_id": "a", "status": "pending", "timestamp": -1, "bytes_sent": 1},
        {"message_id": "a", "status": "pending", "timestamp": True, "bytes_sent": 1},
        {"message_id": "a", "status": "pending", "timestamp": 1, "bytes_sent": -2},
        {"message_id": "a", "status": "pending", "timestamp": 1},
    ]
    for value in bad_values:
        with pytest.raises(ValueError):
            delivery_report(encode_events([value]))
    with pytest.raises(ValueError):
        delivery_report(encode_events({"not": "a list"}))

