import json

def encode_events(events: list[dict]) -> bytes:
    try:
        return json.dumps(events, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid events') from exc

def delivery_report(blob: bytes, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        data = json.loads(blob.decode('utf-8'))
    except (AttributeError, UnicodeError, TypeError, ValueError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, list):
        raise ValueError('invalid events')
    clean = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError('invalid event')
        message_id = item.get('message_id')
        status = item.get('status')
        timestamp = item.get('timestamp')
        bytes_sent = item.get('bytes_sent')
        if not isinstance(message_id, str) or not message_id or status not in {'delivered', 'bounced', 'pending'} or isinstance(timestamp, bool) or (not isinstance(timestamp, int)) or (timestamp < 0) or isinstance(bytes_sent, bool) or (not isinstance(bytes_sent, int)) or (bytes_sent < 0):
            raise ValueError('invalid event')
        clean.append({'message_id': message_id, 'status': status, 'timestamp': timestamp, 'bytes_sent': bytes_sent})
    clean.sort(key=lambda x: (-x['timestamp'], x['message_id']))
    start = (page - 1) * page_size
    selected = clean[start:start + page_size]
    counts = {'delivered': 0, 'bounced': 0, 'pending': 0}
    for item in clean:
        counts[item['status']] += 1
    return {'total': len(clean), 'counts': counts, 'total_bytes': sum((x['bytes_sent'] for x in clean)), 'events': selected}

