import subprocess

def count_route_alerts(files: list[str], route: str) -> dict[str, int]:
    if not route:
        raise ValueError('route must not be empty')
    result = {}
    for path in files:
        if path in result:
            continue
        completed = subprocess.run(['grep', '-F', '-c', '--', route, path], capture_output=True, text=True)
        if completed.returncode == 2:
            raise FileNotFoundError(path)
        result[path] = int(completed.stdout.strip() or '0')
    return result

