import re

def parse_availability(value: str) -> list[tuple[int, int]]:
    if not value.strip():
        return []
    out = []
    for part in value.split(','):
        m = re.fullmatch('\\s*(\\d{2}):(\\d{2})-(\\d{2}):(\\d{2})\\s*', part)
        if not m:
            raise ValueError('invalid interval')
        h1, m1, h2, m2 = map(int, m.groups())
        if h1 > 23 or h2 > 23 or m1 > 59 or (m2 > 59):
            raise ValueError('invalid time')
        start, end = (h1 * 60 + m1, h2 * 60 + m2)
        if end <= start or (out and start < out[-1][1]):
            raise ValueError('invalid interval')
        out.append((start, end))
    return out

def _minutes(value):
    m = re.fullmatch('(\\d{2}):(\\d{2})', value)
    if not m or int(m[1]) > 23 or int(m[2]) > 59:
        raise ValueError('invalid time')
    return int(m[1]) * 60 + int(m[2])

def build_roster(requester, shifts, agents, day):
    if requester.get('tenant') is None or not {'scheduler', 'admin'} & set(requester.get('roles', [])):
        raise PermissionError('not permitted')
    if len({x['id'] for x in shifts}) != len(shifts) or len({x['id'] for x in agents}) != len(agents):
        raise ValueError('duplicate id')
    amap = {x['id']: x for x in agents}
    totals = {x['id']: 0 for x in agents}
    rows = []
    selected = [x for x in shifts if x['date'] == day]
    for s in selected:
        start, end = (_minutes(s['start']), _minutes(s['end']))
        if end <= start:
            raise ValueError('invalid shift')
        dur = end - start
        chosen = s.get('agent_id')
        if chosen is not None:
            if chosen not in amap:
                raise ValueError('unknown agent')
            a = amap[chosen]
            intervals = parse_availability(a['availability'].get(day, ''))
            if a['tenant'] != s['tenant'] or s['skill'] not in a['skills'] or (not any((x <= start and end <= y for x, y in intervals))) or (totals[chosen] + dur > a['max_hours'] * 60):
                raise ValueError('invalid assignment')
        else:
            candidates = []
            for a in agents:
                intervals = parse_availability(a['availability'].get(day, ''))
                if a['tenant'] == s['tenant'] and s['skill'] in a['skills'] and any((x <= start and end <= y for x, y in intervals)) and (totals[a['id']] + dur <= a['max_hours'] * 60):
                    candidates.append(a)
            if candidates:
                chosen = min(candidates, key=lambda a: (totals[a['id']], a['id']))['id']
        if chosen is not None:
            totals[chosen] += dur
        rows.append({'id': s['id'], 'date': s['date'], 'start': s['start'], 'end': s['end'], 'skill': s['skill'], 'tenant': s['tenant'], 'agent_id': chosen, 'duration': dur})
    return sorted(rows, key=lambda x: (_minutes(x['start']), x['id']))

def publish_roster(requester, roster, audit_log):
    if not roster:
        raise ValueError('empty roster')
    tenant, day = (roster[0]['tenant'], roster[0]['date'])
    if any((x['tenant'] != tenant or x['date'] != day or x.get('agent_id') is None for x in roster)):
        raise ValueError('invalid roster')
    ids = [x['id'] for x in roster]
    audit_log.append({'actor': requester['id'], 'tenant': tenant, 'date': day, 'shift_ids': ids, 'action': 'publish'})
    return {'tenant': tenant, 'date': day, 'shift_count': len(roster), 'shift_ids': ids}

