import html

def render_lending_report(records: list[dict], page: int, per_page: int) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or (not 1 <= per_page <= 50):
        raise ValueError('invalid per_page')
    checked = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'title', 'borrower', 'days_late'}:
            raise ValueError('invalid record')
        title = record['title']
        borrower = record['borrower']
        days = record['days_late']
        if not isinstance(title, str) or not title or (not isinstance(borrower, str)) or (not borrower):
            raise ValueError('invalid record')
        if isinstance(days, bool) or not isinstance(days, int) or days < 0:
            raise ValueError('invalid record')
        checked.append((title, borrower, days))
    checked.sort(key=lambda item: (-item[2], item[0].casefold(), item[1].casefold()))
    total = len(checked)
    start_index = (page - 1) * per_page
    shown = checked[start_index:start_index + per_page]
    if shown:
        start = start_index + 1
        end = start_index + len(shown)
    else:
        start = end = 0
    total_fee = sum((item[2] * 0.25 for item in checked))
    lines = ['<table class="lending-report">', '<thead>', '<tr><th>Title</th><th>Borrower</th><th>Days late</th><th>Fee</th></tr>', '</thead>', '<tbody>']
    for title, borrower, days in shown:
        lines.append(f'<tr><td>{html.escape(title, quote=True)}</td><td>{html.escape(borrower, quote=True)}</td><td>{days}</td><td>${days * 0.25:.2f}</td></tr>')
    lines.extend(['</tbody>', '<tfoot>', f'<tr><td colspan="4">Showing {start}-{end} of {total} | Total fees: ${total_fee:.2f}</td></tr>', '</tfoot>', '</table>'])
    return '\n'.join(lines) + '\n'

