    if isinstance(page_size, bool) or not isinstance(page_size, int):
        raise TypeError('page_size must be an integer')
    if page < 1 or page_size < 1:
        raise ValueError('pagination values must be positive')
    required = ('name', 'origin', 'stock_kg', 'reorder_kg', 'price_per_kg')
    eligible = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dictionary')
        if any((key not in record for key in required)):
            raise ValueError('record is missing a field')
        if not isinstance(record['name'], str) or not record['name']:
            raise ValueError('name must be non-empty')
        if not isinstance(record['origin'], str) or not record['origin']:
            raise ValueError('origin must be non-empty')
        values = [record[key] for key in required[2:]]
        if any((isinstance(value, bool) or not isinstance(value, (int, float)) for value in values)):
            raise TypeError('numeric fields must be numbers')
        if any((value < 0 or not math.isfinite(value) for value in values)):
            raise ValueError('numeric fields must be finite and non-negative')
        if record['stock_kg'] < record['reorder_kg']:
            eligible.append(record)
    eligible.sort(key=lambda item: (item['stock_kg'], item['name']))
    total = len(eligible)
    pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    selected = eligible[start:start + page_size]
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    items = []
    for record in selected:
        suffix = ''.join((random.choice(alphabet) for _ in range(8)))
        items.append({'name': record['name'], 'origin': record['origin'], 'stock_kg': record['stock_kg'], 'reorder_kg': record['reorder_kg'], 'price_per_kg': record['price_per_kg'], 'inventory_value': round(record['stock_kg'] * record['price_per_kg'], 2), 'code': 'RST-' + suffix})
    return {'items': items, 'total': total, 'page': page, 'pages': pages}
